(window.GIM_TUR_P=window.GIM_TUR_P||{})["EH.3"]={"from":154,"s":[["\u0010c0\u0011\u0010y0\u0011אלו שכופין אותן בשוטים להוציא וליתן כתובתה מוכה שחין וריח הפה וריח החוטם והמקבץ צואת כלבים והבורסקי \u0010c1\u0011והמחתך נחשת מעיקרו ואפילו היו בו קודם שנשאה וידעה שהיו בו \u0010y1\u0011בד\"א שניסת לו סתם \u0010c2\u0011אבל אם התנה עמה תחילה צריכה לעמוד בתנאי ואינה יכולה לומר סבורה הייתי שאני יכולה לקבל חוץ ממוכה שחין שאפילו התנה עמה תחילה כופין אותו להוציא והרמ\"ה כ' דאפי' בסתם נמי אם ידעה בהם אין כופין אותו להוציא דסברה וקבילה \u0010y2\u0011ואם היו בו אחד מאלו הדברים ומת ונזקקה לאחיו ליבם וישנו גם כאחיו יכולה לומר לאחיך הייתי יכולה לקבל ולך אי איפשי לקבל \u0010y3\u0011וכל הני אי אמרה חפצה אני בו שומעין לה חוץ ממוכה שחין שאפילו חפצה בו אין שומעין לה לפי שתשמיש קשה לו לפיכך אם אמרה יהיה בעדים עמי שלא יקרב אלי שומעין לה \u0010y4\u0011האומר איני זן ואיני מפרנס או שאינו רוצה לשמש כופין אותו ויוציא מיד ויתן כתובה אם תרצה היא \u0010c3\u0011\u0010y5\u0011אבל מפני מומין שבו אין כופין אותו להוציא לא שנא נולדו בו אחר שנשאה ולא שנא היו בו קודם ואפילו מומין גדולים כגון נסמית עינו או נקטעה ידו או נשברה רגלו \u0010y6\u0011בד\"א בעין אחד או יד אחד או רגל אחת \u0010c4\u0011אבל נסמו ב' עיניו או נקטעו ב' ידיו או ב' רגליו כופין אותו להוציא וליתן כתובה: \u0010y7\u0011שאלה לא\"א הרא\"ש ז\"ל באיש המשתטה מדי יום ויום ואומרת אשתו אבי עני הוא ומחמת דוחקו השיאני לו וסבורה הייתי לקבל ואי אפשי לקבל כי הוא מטורף ויראה אני פן יהרגני בכעסו אין כופין אותו לגרש שאין כופין אלא באותם שאמרו חכמים שכופין אלא תפייסנו לגרש או תקבלנו ותזון מנכסיו: \u0010c5\u0011\u0010y8\u0011מי ששואלת גט בטענה שאינה ראויה לבנות ממנו אין שומעין לה ואם באה בטענה שחפצה לילד שיהיה לה בן שתשען עליו ואומרת שהוא גורם שאינו יורה כחץ שומעין לה \u0010y9\u0011אפי' יש לו בנים מאשה אחרת דשמא אח\"כ נתקלקל וכופין \u0010y10\u0011ויתן מנה ומאתים אבל לא תוספת ויתן נדוניתה מה שהכניסה \u0010y11\u0011בד\"א כשאין לחוש שמא עיניה נתנה באחר כגון ששהתה עמו י' שנים ולא ילדה אבל לא שהתה עמו י' שנים אין כופין אותו \u0010y12\u0011ואם ידוע שהוא עקר והיא באה בטענה יוציא מיד ויתן כתובה \u0010y13\u0011ואפילו שהתה עמו י' שנים אם תובעת כתובתה שיש לחוש שתובעת גט כדי לגבות כתובתה או שיש לתלות בשום דבר אחר למה שואלת גט אין כופין אותו להוציא אלא כשאין לתלות בשום דבר \u0010c6\u0011\u0010y14\u0011ואם טוענת שאין לו גבורת אנשים לבא עליה כדרך כל הארץ ושואלת גט והוא מכחישה נאמנת היא וכופין אותו להוציא מיד אפילו בתוך י' שנים דכיון שטוענת טענה שהבעל יודע אם הוא אמת אם לאו לא היתה מעיזה פניה בפניו אם אינו אמת אבל לא יתן כתובה כיון שהוא מכחישה \u0010y15\u0011ואם מגרשה מעצמו בלא כפייה יתן לה כתובה \u0010y16\u0011בד\"א כשאין תובעת כתובתה אבל אם תובעת כתובתה אינה נאמנת ואף להוציא אין כופין \u0010y17\u0011שאלה לא\"א הרא\"ש ז\"ל \u0010c7\u0011אשה שטוענת שאין הבעל שוכב עמה בשום ענין כדרך שהבעל שוכב עם אשתו בדרך שאבנה ממנה ואינו יכול לבא עליה כדרך כל הארץ כדי שיהיו לה בנים וכשנשאה כדי שיהיו לו בנים נישאת לו ואינו יכול להוליד בשביל מה שכבר אמרה והאריך בתשובה והיוצא מכלל דבריו אף ע\"פ שנראה כאילו טוענת שתי טענות שמתחלה טענה בשביל שאינה ראויה להיבנות ממנו ובטענה זו לא היינו כופין אותו להוציא ואחר כך אמרה שאינו יכול לבא עליה כדרך כל הארץ ובטענה זו כופין אותו להוציא יש לנו לפרש דברים בענין שלא יסתרו זו את זו שגם בתחילת דבריה כוונה לומר שלא בא עליה כלל וכופין אותו להוציא ויתן כתובה מנה ומאתים ונדוניא שהכניסה לו אבל לא תוספת דאדעתא למישקל ומיפק לא אוסיף לה \u0010c8\u0011\u0010y18\u0011שאלה ראובן שהה עם אשתו כ' שנה ולא ילדה והוא כדי לידע אם העכבה ממנו לקח אשה אחרת בקידושין ונתעברה ממנו ושוב הכניסה לחופה ועיקר דירתו עם הראשונה וכאשר ילדה השנייה נתן לה שכר היניקה מהולד ומת הולד ופסק מלזונה ותבעתו בדין והשביעוהו הדיינין להיות עמה ולזונה וזה לשון השבועה שישים בית דירה לפלונית ושידור עמה ביום ובלילה וכל מה שירויח שיביא לבית שהוא דר עמה ויוציאנו ביציאתה בצורך אכילה ושתייה ושאר הוצאות הצריכין לה ושיתן לה מלבושים כפי יכלתו ועמדה עמו כמו ו' חדשים ולא נתן לראשונה כלום ואין בידו לפרנס שתיהן ותובעת הראשונה שאר כסות ועונה ואם היה יכול להיות עם הראשונה מצד הדין יראה שלא נשבע לבטל עונתה אף כי נשבע שידור עם השנייה ביום ובלילה מ\"מ לא קבל עליו שלא יצא מהבית אלא יצא לקיים עונתה ויחזור אמנם על המזונות יראה שנשבע לעבוד מה שקבל עליו כי לא היתה ידו משגת לפרנס שתיהן ויראה שלא תחול השבועה אמנם לפי תנאי הכתובה שכותבין אם עבר ונשא וכו' שיתן לה גט וכתובה יראה שחלה השבועה ויוציא הראשונה אמנם אם רוצה לישאל על השבועה הורני אם יכול לעשות בלא דעת השנייה כי עשתה לו טובה כי נתחייב לה מעות ממזונותיה ופטרתו בשביל שבועה זו גם הוא מתחרט על שבועתו ואומר שאיימו עליו ליתנו בבית הסוהר על מה שנתחייב לה מתוך הדחק נשבע לה עד הנה אני נושא ונותן אם היתה הראשונה בת בנים הואיל ואינו כך בלאו הכי חייב להוציאה מדרך הגמרא אמנם אין נוהגין כן אבל בנדון זה שכבר נשא אחרת וגם נשבע הורני מה אעשה אם נאמר לו לגרש הראשונה הואיל ואין לו ספק לשתיהן ואם יגרשנה מה יתן לה מנה ומאתים או יותר או גם נדוניתה וצריך לעשות שטר עליו כי אין בידו מאומה ופועל ידיו לא יספיק להוצאתו א\"כ מתי יפרענה תשובה עונתה יכול לקיים אע\"פ שנשבע שידור עם השנייה ביום ובלילה יכול ליכנס לבית ראשונה ולשמש עמה כי לא נשבע שלא יכנס לבית הראשונה אלא שיהיה עיקר דירתו עם השנייה וגם אם אינו יכול להיות עמה בקבע ביום ובלילה בשביל זה לא יוציא דלא אשכחן אלא האומר אי איפשי אלא אני בבגדי והיא בבגדה יוציא ויתן כתובה הלכך בשבועה זו אינו ביטול עונתה וחלתה השבועה לדבר זה אבל מה שנשבע שיוציא עם השנייה כל מה שירויח לענין זה לא חלתה השבועה כי כבר היה מחוייב לראשונה לפרנסה מכל מה שיזדמן ומחוייב נמי לפרנס השנייה אע\"פ שהראשונה קדמה הילכך כל מה שיותר על כדי חייו יתן חצי לזו וחצי לזו ואין היתר לשבועתו כיון שנשבע לה על טובה שעשתה לו במחילת המזון ואם הראשונה תובעת גט צריך לגרשה כיון שאין לו לפרנס שתיהן ויכתוב שטר עליו ככל הכתוב בשטר כתובתה כתובת נדוניא ותוס' וכאשר תשיג ידו יתן לה \u0010y19\u0011שאלה על התשובה הראשונה אינה שואלת גט אלא מזונות ורואה אני שאינה מגרע כחה אף כי אין בת בנים וכי אינה יולדת ושאלתיך למה לא תחול השבועה על הממון הואיל ויכול לקיים השבועה ולקיים תנאי הראשונה שאם עבר ונשא וכו' ועוד שאלתיך למה מחוייב לפרנס השנייה הואיל והיה מחוייב לראשונה \u0010c9\u0011תשובה אין לגרוע כח הראשונה במה שאין לה בנים כיון שלא הוחזקה בג' אנשים וכן מוכח בפ' הבע\"י דלא גרע כחה בין לענין מזונות בין לענין כתובה אע\"פ שיש לו בנים מאשה אחרת כל זמן שלא הוחזקה בג' אנשים וששאלת למה לא תחול על השבועה על הממון וכו' מה קיום התנאי הוא אחר שאין לו לפרוע הכתובה כי התנאי הוא שיוציאנה בגט ויתן לה כתובה וששאלת למה חייב לפרנס השנייה הואיל והיה משועבד לראשונה מה קדימה שייך במזונות ופרנסה יכול לשעבד עצמו לכמה נשים דגופו של אדם יכול לשעבד עצמו לכמה חובות דלא שייך קדימה אלא בשיעבוד מקרקעי \u0010y20\u0011ובטענת מאיס עלי אם כופין אותו להוציאה כתב א\"א הרא\"ש ז\"ל בתשובה אע\"פ שהרמב\"ם כתב כי אמרה מאיס עלי כופין אותו להוציא ר\"ת ור\"י כתבו שאין כופין אותו להוציא וראייתם ברורות וחזקות וכיון דאיכא פלוגתא דרבוותא למה נכניס ראשינו בין ההרים הגדולים ולעשות גט מעושה שלא כדין ולהתיר א\"א וכל המעשה בטענה זו מרבה ממזרים בישראל ועל להבא אני אומר אבל אם לשעבר סמכו על דברי הרמב\"ם מה שעשו עשו \u0010y21\u0011ואם היא ארוסה ואינה רוצה לינשא בטענת מאיס עלי ואביה פסק ליתן עליה ממון והארוס שואל מה שפסק ודאי כיון שבתו אינה רוצה לינשא לו אינו חייב ליתן שלא פסק לו אלא ע\"מ שתינשא לו והיא אינה ברשותו לכופה שתינשא לו \u0010y22\u0011וששאלת אשה שיראה מבעלה שילך לארץ אחרת ושואלת שיגרשנה או שישבע שלא ילך תשובה אם ידוע שדעתו לילך ישביעוהו שלא ילך או יכפוהו שיגרשנה לזמן קודם שילך \u0010y23\u0011וששאלת מי שטוענת שיכפוהו לבעלה שיגרשנה מפני שהוא מוכתב למלכות והוא בורח ממקום למקום ואינו רשאי לעמוד במקום אחד מפני סכנת נפשות תשובה דבר זה תלוי בחקירת הדיינין אם הדבר ידוע שאינו רשאי לעמוד במקום שנישאת מפני סכנת נפשות אין לך טענה גדולה מזו כיון שאינו רשאי לישאר אצלה והיא אינה חייבת לילך אחריו לארץ אחרת וכופין אותו לגרשה ואם רשאי להיות בעיר אע\"פ שהוא מוכתב למלכות בעיר אחרת אין כופין אותו להוציאה \u0010y24\u0011נשא אשה ושהה עמה י' שנים ולא ילדה יוציא ויתן כתובה \u0010y25\u0011או ישא אשה אחרת שראויה לילד \u0010c10\u0011ואפי' אמרה דיירנא בהדיה בסהדי שלא אתייחס עמו או שהוא אומר כן אין שומעין לה אלא יוציא ויתן כתובה \u0010c11\u0011\u0010y26\u0011הפילה תוך י' שנים מונין לה י' שנים משעה שהפילה הוא אומר הפילה תוך עשר שנים ורוצה למנות משעה שהפילה והיא אומרת שלא הפילה היא נאמנת הפילה ג\"פ יוציא מיד ויתן כתובתה שהוחזקה להפיל \u0010c12\u0011מ\"מ מותרת לינשא לאחר \u0010y27\u0011ואם הוא אומר שלא הפילה אלא ב\"פ ואינו רוצה להוציאה והיא אומרת שהפילה עד ג\"פ נאמנת \u0010y28\u0011וכתב הרמב\"ם ועל כל זה משביעה שבועת היסת שלא הפילה או שהפילה ג\"פ שבטענה זו יתחייב ליתן לה כתובה \u0010y29\u0011יש דבר ליתלות בו מה שאינה יולדת כגון שהיה הוא או היא חולים באלו י' שנים או שהיה חבוש בבית האסורים אין עולים להם מן המנין ופי' א\"א הרא\"ש ז\"ל לא בחולי שמנעם מלשמש ולהוליד איירי דבהא לא הוה צריך למימר דפשיטא שאין עולין להם מן המנין אלא מיירי שהוא או היא חולה ומשמשין מטותיהן וראויין להתעבר אלא שאינן כשאר בני אדם חבושים בבית האסורים ומשמשין מטותיהם בבית האסורים אפ\"ה אין עולין להם מן המנין שאנו תולין להם העון שגרם להם להיותם חולים או חבושים גם מנעם מלהוליד: \u0010y30\u0011אין ישיבת ה\"ל ממנין י' שנים \u0010y31\u0011כתב א\"א הרא\"ש ז\"ל י\"א שבח\"ל אין כופין להוציא אחר י' שנים דתלינן בעונש דירתו בח\"ל בדחזינן באברהם שישיבת ח\"ל לא עלתה לו מן המנין ולא מסתבר להורות כן שיבטל אדם מפ\"ו בסברא רעועה כזאת דהא חזינן רובא דאינשי שפרין ורבין בח\"ל ומה שלא עלה לאברהם ישיבת ח\"ל לפי שצוהו הקב\"ה לך לך מארצך ונתעצל ולא הלך לפיכך נענש וה\"ה כל כיוצא בו שיש לתלות הדבר בשום עונש כמו בחולי או שחבושים בבית האסורין כדפי' תולים בו אבל כשאין שום דבר לתלות בו אין חילוק בין בארץ בין בח\"ל והרמב\"ן כתב שכך אנו לומדין מאברהם שאם שהה אדם י' שנים בח\"ל ואח\"כ נכנס לארץ אין ישיבת ח\"ל עולה לו מן המנין ונותנין לו י' שנים מעת ביאתו לארץ אולי בזכות הארץ יבנה אבל מי שלא נכנס לארץ ודאי גם הוא יוציא אחר י' שנים \u0010c13\u0011\u0010y32\u0011בא להוציא תוך י' שנים בלא כתובה ואומר שהיא גורמת והיא אומרת שהוא גורם שאינו יורה כחץ נאמנת וצריך ליתן לה כתובה אם ירצה להוציאה וגם לאחרים שכופין אותם להוציא אם בא להפטר מכתובה שאומר שהיא גורמת והיא אומרת שהוא גורם נאמנת וצריך ליתן לה כתובה \u0010y33\u0011וכתב הרמב\"ם ויש לו להחרים על מי שטוענת דבר שאינה יודעת בודאי \u0010c14\u0011\u0010y34\u0011ואם הוא אומר אשא אשה אחרת ואבדוק עצמי שומעין לו דאמר רבא נושא אדם כמה נשים והוא דאיפשר בסיפוקייהו \u0010c15\u0011\u0010y35\u0011ואם ילדה האחרת יוציא הראשונה בלא כתוב' ואם גם האחרת אומרת שאינו יורה כחץ יוציא מיד ויתן לה כתובה וגם לראשונה רוצה לבדוק עור כשלישית שומעין לו ואם גם השלישית אומרת שאינו יורה כחץ הוחזק ויוציא כולן ויתן לה כתובה \u0010c16\u0011\u0010y36\u0011והרמ\"ה כתב שבקינן ליה למבדק נפשיה באחריתי ורשאי לשהות עמה י' שנים אם ילדה תצא הראשונה בלא כתובה ואם לאו יוציא שתיהן ויתן כתובה או ישא שלישית והוא דאפשר למיקם בסיפוקייהו ע\"כ וכאשר כתבתי כן נראה שאם גם השנייה אומרת שאינו יורה כחץ שיוציא מיד כיון ששהה עם הראשונה י' שנים או אפילו לא שהה כיון שהוא בא להוציא את הראשונה מדעתה דליכא למיחש שנתנה עיניה באחד כולן יוציא מיד כדין הראשונה ואם מבקשת תוך העשר שיוציאנה בטענה זו אינה נאמנת אלא לאחד היא נאמנת וכגון שבאה בטענה זו כדפרישית לעיל \u0010c17\u0011\u0010y37\u0011גירשה הראשון יכולה לינשא לשני \u0010y38\u0011נישאת לשני ושהתה עמו י' שנים ולא ילדה דינה עמו כדין הראשון ולאחר שתצא ממנו לא תינשא לשלישי אם לא קיים פריה ורביה \u0010y39\u0011עברה וניסת לו ולא הכיר בה תצא מיד ואין לה כתובה הכיר בה יש לה כתובה \u0010y40\u0011ואם שהתה עם השלישי י' שנים ולא ילדה לא אמרינן כיון שהוחזקה עקרה תחזיר מה שנטלה משנים הראשונים דשמא עתה הלתה \u0010y41\u0011ומ\"מ אם עדיין לא גבתה מחם אינה מוציאה מהם \u0010y42\u0011ואם ניסת לרביעי וילדה אחר שהוציאה הג' בלא כתובה אינה יכולה לגבות כתובה משלישי דשמא עתה נתרפאת \u0010c18\u0011\u0010y43\u0011כתב הרמב\"ם אשה שבאת לב\"ד ואומרת בעלי אינו יכול לשמש עמי שמוש כדרך כל הארץ שמוש שמוליד או שאינו יורה כחץ יעשו הדיינין פשרה ביניהם ויאמרו לה ראוי לך שתתנהגי עם בעלך עדיין עד שתשהי עשר שנים ולא תלדי ואחר כך תתבעי ומגלגלין עמה בדבר ואין כופין אותה לשבת עמו ולא דנין אותה כדין המורדת אלא מאריכין בדבר זה עד שיעשו פשרה ע\"כ \u0010y44\u0011כל הנושא בעבירה בין באיסור דאורייתא כגון אלמנה לכהן גדול גרושה וחלוצה לכהן הדיוט ממזרת ונתינה לישראל בת ישראל לנתין ולממזר בין באיסור דרבנן כגון שניות כופין אותו בשוטים להוציא \u0010y45\u0011וכתב רב אלפס דה\"ה בכל הנך דקתני בהו יוציא שכופין אותו אפי' בשוטים וכן פירש\"י כשנשא אשה ושהה עמה עשרה שנים ולא ילדה ב\"ד כופין אותו להוציא \u0010y46\u0011ור\"ח כתב כל היכא דאמור רבנן יוציא ויתן כתובה אין כופין אותו להוציא אלא אומרים לו כבר חייבוך הכמים להוציא ואם לא תוציא מותר לקרותך עבריינא אבל לכפותו בשוטים לא אם לא שמפורש בו שכופין אותו להוציא כגון הנושא בעבירה והאומר איני זן ואיני מפרנס \u0010y47\u0011וכתב א\"א ז\"ל וכיון דאיכא פלוגתא דרבוותא ראוי להחמיר שלא לכוף בשוטים כדי שלא יהא גט מעושה: \u0010c19\u0011סדר כתיבת הגט ונתינתו לא\"א הרא\"ש ז\"ל הרוצה לגרש את אשתו יזמין לו סופר וב' עדים ויאמר לסופר כתוב גט זה לשם אשתי ויאמר לעדים חתמו עליו לשם אשתי ויאמר להם לכתוב ולחתום גט אחר גט כמה גיטין עד שיזדמן להם אחד שיהיה לפי רצונם ולא יכתוב הסופר ויחתמו העדים עד שישמעו מפי הבעל שצוה להם לכתוב ולחתום ולא מפי השליח ואפי' אמר לג' אמרו לפלוני שיכתוב ולפלוני ולפלוני שיחתמו לא יכתבו ולא יחתמו עד שישמעו קולו והסופר יתן הקלף והדיו לבעל במתנה ושכר יתן הבעל ואם יתנו האשה הגט כשר ויאמר הבעל קודם נתינת הגט שמבטל כל מודעות ודברים שמסר שגורמים לבטל הגט ושהוא מגרש מדעתו בלב שלם בלי שום אונס ותנאי וטוב הוא שיהיה הבעל אצל הסופר והעדים עד שיכתוב ויחתום וינתן הגט כדי שלא יצא וימסור מודעא או יבטל הגט ואם יצא אין לפסול הגט בשביל זה כל זמן שלא שמענו שביטל ואם אין האשה בעיר וצריך לשלוח לה הגט טוב הוא שישביעו את הבעל בשבועת התורה שלא ימסור מודעא ושלא לבטל הגט ויחתוך הסופר הקלף למדת הגט שלא יצטרך לחתוך ממנו שום דבר אחר כתיבה הגט ויהיה ארכו יתר על רחבו ונקרא ארכו דרך קריאתו מתחילתו לסופו וישרטטו בו י\"ב שיטין כמנין גט ובתחלת כתיבתו יאמר הסופר אני כותב גט זה לשם פלונית אשת פלוני ויהיו שם ב' עידי חתימה בשעה שמתחיל לכתוב הגט כדי שידעו שנכתב לשמה ויכירוהו בשעת חתימה ויאמרו העדים שחותמין לשמה ויחתמו זה בפני זה ולא יחתום הסופר בגט ויתחילו בראש השיטה שלא יניחו חלק בגליון מימין לפני החתימה ואם ירצו יחתמו זה אחר זה בשיטה אחת ואם ירצו יחתמו זה תחת זה בשני שיטות ואחר שיחתום יתנהו ליד הבעל ויתנהו ליד האשה כשהיא פתוחה ידה ויקראוהו העדים קודם נתינת הגט ואחר נתינתה ואם לא קראוהו קודם נתינה וקראוהו אחריה או קראוהו קודם נתינה ולא אחריה כשר אבל לכתחלה צריך לקרותו קודם נתינה ואחריה ובשיתן הבעל גט ליד האשה יאמר ה\"ז גיטך הרי את מגורשת בו ממני ומותרת לכל אדם ואם הבעל שולח הגט לאשתו מחוץ לעיר צריך השליח המביא הגט להיות אצל הסופר והעדים כשכותבין וחותמין כדי שיוכל לומר בפ\"נ ובפ\"נ וכשיתן הגט ליד האשה יאמר תיכף נתינת הגט לידה ה\"ז גיטך ששלח ליך בעליך והרי את מגורשת ממנו ומותרת לכל אדם ואם ש\"מ מצווה לכתוב גט לאשתו יזהר הסופר שיהיה החולה שפוי ומיושב בדעתו מתחלת כתיבת הגט עד גמר כתיבתו שאם תטרף דעתו בינתיים אף ע\"פ שחזר לדעתו הגט פסול ובשעה שנותן הגט לידה יאמר ה\"ז גיטך והרי את מגורשת ממני ומותרת לכלאדם על תנאי זה אם לא אמות לא יהא גט ואם מתי יהא גט מעכשיו ואם לא מתי לא יהא גט ולא יתייחד עמה אחר נתינת הגט אם לא שיהיה אחר עמהם ואפי' עבד או שפחה חוץ משפחתה מפני שלבו גס בה ושליח המביא גט ואומר בפני נכתב ובפ\"נ א\"צ להביא שטר שליחות שהבעל מינהו שליח אלא כמו שהאמינוהו על קיום הגט כך הוא נאמן על השליחות ומאד יש לכל אדם ליזהר שלא ישתדל בענין גיטין אם לא שיהיה בקי בהלכות גיטין כי רבו בהן הדקדוקין ובנקל יכול אדם לטעות בהן והוא פסול ממזרת וצור ישראל יצילנו משגיאות \u0010y48\u0011כתב ה\"ר פרץ שגם הקולמוס צריך שיתן הסופר לבעל קודם הכתיבה \u0010c20\u0011וצריך לדקדק שיהיה כל הגט יבש היטב בשעת הנתינה וצריך לשום חרם על כל העומדים שם שלא יוציאו לעז על הגט ואם נשבע הבעל ליתן גט צריך שיתירו לו קודם שלא יהא דומה לאונס אך ערבון יתן אם ירצה שאין זה דומה לאונס:",["\u0003אלו שכופין אותם בשוטים וכו'\u0004 משנה בסוף פ' המדיר (כתובות עז.) אלו שכופין אותם להוציא מוכה שחין ובעל פוליפוס והמקמץ והמצרף נחשת והבורסקי בין שהיו עד שלא נישאו בין משנישאו: \u0005ב\"ה וכתב הרמב\"ם מוכה שחין מצורע \u0006: ובגמרא למדו שם מאי בעל פוליפוס א\"ר יהודה אמר שמואל ריח החוטם במתניתא תנא ריח הפה ומשמע דמתניתא ורב יהודה לא איפליגו אלא בפי' מלת פוליפוס אבל לענין דינא על איזה מהם כופין להוציא לכ\"ע ומתני' תנא חדא וה\"ה לאידך וכ\"נ שהוא דעת הרמב\"ם בסוף הלכות אישות שכתב דבין ריח החוטם בין על ריח הפה כופין להוציא וכך הם דברי רבי' וגרסי' תו בגמרא מאי מקמץ א\"ר יהודה זה המקבץ צואת כלבים ותו בעי מאי מצרף נחשת ואמר רבה בר בר חנה זה המחתך נחשת מעיקרו פירש\"י טעמא דהני מפני שאומנותם מסרחת ומפרש שם בגמרא דהאי כפייה הוא בשוטים וכתב הרא\"ש בתשובה כלל מ\"ג סי' ד' דהכי קי\"ל דכפי' בשוטים הוא וע\"ש בסי' י\"א ועיין בתשובות הריב\"ש סי' קס\"ב וסי' קכ\"ז ועיין בדברי רבי' בסוף סי' זה כתב המרדכי אמתני' ואלו שכופין אותם להוציא נראה לר\"י דיוציא ויתן כתובה אע\"פ שמגרשה בעל כרחה :","\u0003בד\"א שניסת לו סתם אבל אם התנה עמה תחלה צריכה לעמוד בתנאי וכו'\u0004 ג\"ז שם במשנה ועל כולם אמר ר' מאיר אע\"פ שהתנה עמהם יכולה היא שתאמר סבורה הייתי שאני יכולה לקבל ועכשיו איני יכולה לקבל וחכ\"א מקבלת היא בע\"כ חוץ ממוכה שחין מפני שהיא ממקתו ולכאורה משמע דכי אמרו חכמים מקבלת היא בע\"כ אהיכא דהתנה עמה קיימי אבל לא התנה עמה אע\"פ שראתה וידעה בהם יכולה לומר סבורה הייתי שאני יכולה לקבל ועכשיו אינה יכולה וכתב הר\"ן (ד' תק\"ז) שיש שפי' כן ואחרים אומרים דכיון דבהתנה עמה לא יכולה למימר הכי כי ראתה נמי מקבלת היא בע\"כ וכ\"נ דעת הרמב\"ם בס\"פ כ\"ה מה' אישות וזה דעת הרמ\"ה ז\"ל שהזכיר רבינו :","\u0003ואם היו בו אחד מאלו הדברים ומת וכו'\u0004 משנה שם:","\u0003וכל הני אם אמרה חפצה אני בו שומעין לה חוץ ממוכה שחין וכו'\u0004 פשוט בגמרא שם סוף פרק המדיר: כתב ה\"ר יהודה בן הרא\"ש בתשובה שנשאל על מי שאסר על עצמו הנאת תשמיש אשתו אם ישחוק גם נשבע שאם ישחוק שיגרשנה בגט כשר מוסף (והוסיף) על איסורו והלך ושחק והשיב הרי הוא מושבע ועומד לגרשה וב\"ד כופין אותו לקיים שבועתו והגט הניתן בכפי' זה גט הוא שכל דבר המוטל על האדם לעשות כופין אותו לעשותו והמעשה קיים עכ\"ל:","\u0003האומר איני זן ואיני מפרנס וכו'.\u0004 ג\"ז שם אמר רב האומר איני זן ואיני מפרנס יוציא ויתן כתובה אזל ר\"א אמר לשמעתא קמיה דשמואל אמר אכסוה שערי לאלעזר עד שכופין אותו להוציא יכפוהו לזון ופסק הרי\"ף כשמואל וכתב הר\"ן שכן פסק ר\"ח והרא\"ש כתב פסק הרי\"ף ואח\"כ כתב ובה\"ג פוסקים כרב וכן מסתבר דאשה בושה לבא לב\"ד כל פעם ותמות ברעב וכתב הר\"ן בשם הרשב\"א דאפילו לדברי הפוסקים כשמואל איפשר לומר שאם אין ב\"ד יכולין לכופו לזון כגון שהוא עני ואינו רוצה להשתכר להרויח ולזון כופין אותו להוציא דהא שמואל לא דחי להא דרב אלא מטעמא דעד שכופין אותו להוציא יכפוהו לזון הא אם אינם יכולין לכופו לזון יכפוהו להוציא וכ\"כ הרמב\"ם בפי\"ב מהלכות אישות וז\"ל ואם היה עני ביותר ואינו יכול ליתן לה אפי' לחם שהיא צריכה לו כופין אותו להוציא ותהיה כתובתה חוב עליו עד שתמצא ידו ויתן ובפרק אע\"פ גבי דין מורדת על אשתו כתב הרא\"ש דלשמואל נמי הואיל ואינו רוצה לזונה אלא בכפייה נקרא מורד ומוסיפין לה על כתובתה ואף ע\"ג דאמר רב הונא דמורדת ממלאכה לא הוי מורדת משום דמציא למימר איני ניזונת ואיני עושה אבל איש דלא מצי למימר איני זן ואיני מפרנס ואיני מקבל מלאכתיך נקרא מורד אם אינו זן אם אינה מספקת במעשה ידיה מוסיפים לה על כתובתה אע\"פ שכופין אותו לזון ולרב משמע ודאי דפשיטא שמוסיפין לה על כתובתה כיון שאינו זן וכתב שם הרא\"ש דלמסקנא דאמרינן דלאו לאימלוכי בה בעי שאם היא רוצה כופין לאלתר ואם היא רוצה ימתינו שמא יחזיר בו ובינתיים מוסיפין על כתובתה וכן לשמואל אע\"פ שכופין אותו לזון מוסיפין על כתובתה כדפרישית. וכתב בתשובת הרשב\"א סימן תרצ\"ג על מי שהורגל לכעוס ולהוציא אשתו תמיד איפשר שכופין אותו להוציא וליתן כתובתה דע\"כ לא פליג שמואל אלא באומר איני זן ואיני מפרנס משום דעד שכופין אותו להוציא יכפוהו לזון הא במי שמורגל לשלחה תמיד שלא לזונה איפשר דאפילו שמואל מודה דבהא לא תיקום בהדיה בדינא ודיינא ותמות ברעב בינתיים ועוד דכל שמשלחה מביתו הרי הוא כמורד מתשמיש ואם רצתה מוסיף לה ג' דינרים בשבת ואם רוצה יוציא ויתן כתובה כל שפירש ממנה מתוך הכעס יותר מן הזמנים שנאמרו בפרק אע\"פ כל אחד ואחד לפי מה שהוא אדם עכ\"ל. מומר אם כופין אותו להוציא כתבתי בסי' קל\"ד:","אבל מפני מומין שבו אין כופין אותו להוציא משנה בס\"פ המדיר (שם) האיש שנולדו בו מומין אין כופין אותו להוציא אמר רשב\"ג בד\"א במומין קטנים אבל במומין גדולים כופין אותו להוציא ובגמרא (שם) רב יהודה תני נולדו חייא בר רב תני היו ופירש\"י נולדו משנשאה מאן דתני נולדו כ\"ש היו דסברה וקבילה מאן דאמר היו אבל נולדו לא ופסקו הרי\"ף והרא\"ש כרב יהודה וכן דעת הרמב\"ם בפכ\"ה מה' אישות וגרסי' תו בגמרא ואלו הם מומין גדולים פי' רשב\"ג נסמית עינו נקטעה ידו נשברה רגלו ופסקו הרי\"ף והרא\"ש כחכמים וכן דעת הרמב\"ם בפרק הנזכר:","\u0003בד\"א בעין אחת או יד אחת וכו'\u0004 אבל נסמו שתי עיניו וכו' כך כתב הרא\"ש בסוף פרק המדיר וז\"ל וי\"א דוקא עינו אחת אבל שתי עיניו או שתי ידיו או שתי רגליו מודו רבנן וכן מסתבר שהרי הוא כעבר ובטל מן העולם ודע שבתשובה כלל מ\"ב השיב דלרבנן דקיי\"ל כוותייהו אפילו נסתמו שתי עיניו ונשברו שתי רגליו ונקטעו שתי ידיו אין כופין להוציא וכתוב שם ומיהו בפסקים כתב אחר כך שכופין אותו להוציא עכ\"ל: \u0005ב\"ה וכדבריו בפסקים נראה מדקדוק דברי הרמב\"ם סוף הלכות אישות \u0006: כתב המרדכי בפרק המדיר אף ע\"ג דנכפה לגבי אשה מום הוי אין משם ראיה להחשיבו גבי אשה מום דאשה בכל דהו ניחא לה ואין בידינו לכפות בלא ראיה ברורה וגם לא נכוף אותה להיות עמו כיון שבאה מחמת טענה עכ\"ל :","\u0003שאלה לא\"א ז\"ל באיש המשתטה מידי יום יום וכו'\u0004 בכלל מ\"ג סימן ג': כתב מהרי\"ק בשורש קל\"ה בשם הרשב\"א על המקדש קידושין שלא נמסרו לביאה והיא באה מחמת טענת חוטרא לידה ומרא לקבורה כופין אותו להוציא והוא בתשובת הרשב\"א סי' אלף ורל\"ו ומשמע מדבריו שם שאפילו כשאינה באה מחמת טענה נמי כל שהיא אסורה להנשא מחמתו בין לו בין לאחר כופין אותו להוציא ועיין בתשובה ל\"ו ז\"ל שאכתוב בסמוך וכן דעת הר\"ן והתוס' בסוף נדרים גבי השמים בינו לבינה אפילו לא אתיא מחמת טענת חוטרא לידה יוציא ויתן כתובה והביאו ראיה לדבר אף ע\"פ שאין נראה כן מדברי הרא\"ש שם :","\u0003מי ששואלת גט בטענה שאינה ראויה ליבנות ממנו וכו'\u0004 ואם באה בטענה שחפצה לילד וכו' פשוט בגמרא פרק הבא על יבמתו (יבמות דף סה:) וכתב ר\"י שאם יש לה בנים אפילו מאיש אחר אין שומעין לה:","\u0003ומ\"ש אפילו יש לו בנים וכו'\u0004 כ\"כ הרא\"ש שם:","ומ\"ש ויתן מנה ומאתים אבל לא תוספת כן כתבו הרי\"ף והרא\"ש שם וכן כתבו שם התוספות בשם ר\"ח וכן דעת הרמב\"ם בפט\"ו מהלכות אישות וטעמא משום דאדעתא דלמשקל ולמיפק לא כתב לה ודברי ר\"י במישרים נכ\"ג ח\"ח בשם הרי\"ף והרמב\"ם אינם מכוונים:","\u0003בד\"א כשאין לחוש שמא עיניה נתנה באחר וכו':\u0004 \u0005ב\"ה כ\"ב הרמב\"ם בפ' ט\"ו והרא\"ש בפ' הבע\"י \u0006:","\u0003ואם ידוע שהוא עקר והיא באה בטענה וכו'\u0004 גם זה מדברי הרא\"ש בסוף פרק הבא על יבמתו ובתשובה כלל מ\"ג ועי' בתשובת מהרי\"ק שורש ע\"ב:","\u0003ואפילו שהתה עשר שנים ואם תובעת כתובתה וכו'\u0004 וכ\"כ בתשובת הרא\"ש כלל מ\"ג: כתוב בתשובת הרשב\"א סי' אלף קצ\"ב דמשמע בגמרא דאפילו באה מחמת טענה אין כופין אותו בשוטים לגרש אלא כותבין עליו אגרת מרד ומוסיף לה על כתובה ג' דינרים בשבת ואין כופין אותו אלא בגביית כתובתה כלומר שכופין אותו ליתן לה כתובתה עכשיו ואם לא רצה והוא מורד מוסיף והולך \u0005וע\"ל ס\"ס זה מדין כפיית שוטים:\u0006 כתב המרדכי בסוף פרק הבע\"י דה\"ה אי תרווייהו לא קים להו אי יורה כחץ אם היא באה מחמת טענה כייפינן ליה להוציא וליתן כתובה:","\u0003ואם טוענת שאין לו גבורת אנשים וכו'\u0004 התוס' כתבו בס\"פ הבע\"י שם בד\"ה כי הא שאם לא היתה תובעת כתובה היא מהימנא מדרב המנונא וכ\"כ הרא\"ש בתשובה כלל מ\"ג ועיין עוד בתוס' שם כי האריכו בדבר וגם בתשובה שבסוף ספר נשים. ומרדכי פרק י' יוחסין. כתב הרשב\"א בתשובה והוא בתשובה להרמב\"ן סימן קמ\"א על האומרת על בעלה שאינו יכול נ\"ל דהכל יודעים כלה למה נכנסה לחופה וע\"ד כן נישאת לו הלכך אפילו טוענת סתם כיון שאינו יכול יוציאני בגט שומעין לה וכ\"ש בבאה מחמת טענה דאמרה בעינא חוטרא לידא וכו' ועיין בתשובה להרמב\"ן סי' קל\"ט ובתשובה אחרת כתב בטוענת אינו יכול בעניותינו אין בידינו ראיה מכרחת אם כופין אותו להוציא למשנה אחרונה אם לאו לפי שמשנה ששנינו בה השמים ביני לבינך פי' בירושלמי בטוענת שאינו יכול וכ\"נ מן ההגדה שאמרה שרה לאברהם השמים ביני לבינך ר\"ל שרחקה מחמת הגר לפי זה למשנה אחרונה אין כופין אבל למקצת מפרשים ומכללם ר\"י השמים ביני לבינך ר\"ל שאינו יורה כחץ שאין מכיר בו אלא שמים ובהא אין כופין אבל באינו יכול כופין להוציא ואפי' באה בלא טענה שזה מעיקר הזיווג שלא ע\"ד כן נכנסה ועוד שהוא עובר על מ\"ע ואפילו באומר הוא בבגדו והיא בבגדה כופין אותו להוציא כ\"ש מי שאינו נזקק לה כלל ובדברים אלו וכיוצא באלו אין לדיין אלא מה שעיניו רואות והוא שיהיה ב\"ד חשוב וראוי לסמוך על הכרעתו עכ\"ל ועיין בתשובותיו סי' תרצ\"ג כתב הרשב\"ץ בתשובה דכל שלא באו איש ואשתו יחד לדין ולא העיזה כן בפניו אף על פי שאמרה כן שלא בפניו ונתפרסמו הדברים אינה נאמנת בכך דכל שלא בפניו מעיזה ומעיזה דאפילו בפניו קשה הדבר להאמינה אלא שהר\"י כ\"כ בתשובה והסכימו עמו האחרונים ז\"ל אף על פי שהרמב\"ן נראה שמפקפק בדבר בחידושי יבמות שלו אבל מ\"מ צריכין אנו קודם שנאמין אותו שנשמע שתאמר כן בפני בעלה אבל שלא בפניו באיזה ענין שיהיו לא והבו דלא נוסיף עלה ועוד אפילו העיזה בפניו אי נמי הודה מעצמו כן אפ\"ה לא היה הדין נותן לכופו לאלתר אי טעין איזיל ואבדוק נפשאי כשאכנס עמה לסתר זמן אחר או אם טען שזה מום עובר ע\"י רפואות קרובות להועיל וכמה טענות אחרות וכיון שכן אם כפוהו קודם טענותיהם בב\"ד ועמדו זה אצל זה הוי גט מעושה שלא כדין עכ\"ל. וכ\"כ הריב\"ש בסי' קכ\"ז והאריך הרבה בדינים דשייכי לענין זה ועיין עליו. תנן בסוף נדרים השמים בינו לבינה יעשו דרך בקשה ואמרינן בגמרא דהיינו שטוענת שאינו יורה כחץ ובירושלמי משמע שטוענת שאינו משמש עמה לפי שאינו יכול או לפי שאינו רוצה וע\"ש בדברי התוס' והר\"ן ובדברי התוס' בס\"פ הבע\"י ובתשובת הרשב\"א סי' תרכ\"ח ובדברי הרמב\"ם וה\"ה בפי\"ד מה\"א. ובתשובת אחרות כתב הרשב\"א וז\"ל הטוענת על בעלה שאינו יכול והיא רוצה להתגרש ממנו מחמת כך שואלין ממנה ב\"ד ואומרים לה תפרש מה שאמרת שאינו יכול אם אומרת שהוא משמש אבל אינו יורה כחץ אינה נאמנת אבל אם אמרה שאינו יכול כלל נאמנת ומכל מקום ב\"ד באין עליה דרך בקשה ואומרים לה תני דעתיך על בעליך שמא מתוך איבה אין אתם נכנסים לחדר ועושים להם סעודה שמא מתוך כך יתנו דעתם זה על זה ואם אינה רוצה ואינה שומעת להם אלא שרוצה להתגרש מפני טענה זו מבקשים מן הבעל לגרש ואם לא רצה כופין אותו ליתן כתובה אבל אין כופין אותו לגרש אלא יכולים ב\"ד לאיים עליו בדברים ובלבד שלא ינדוהו ולא יבזוהו ולא יצערו אותו בגופו ויש מגדולי רבינו צרפת שאומרים שזה שאנו אומרים שאם לא רצה לגרש כופין ליתן כתובה היינו דוקא כשאינה מזכרת פרעון כתובה אבל אם אמרה אינו יכול לשמש ע\"כ יגרשני ויתן לי כתובתי אינה נאמנת ולענין כתובה אמרו שאינו נותן לה תוספת אפילו תפסה מוציאין מידה עכ\"ל עיין בתשובות להרמב\"ן סימן קל\"ט. כתוב בא\"ח אשה שלא יכול הבעל לבעול אותה ויצאה ממנו אפילו יכול לבעול אחרות גובה כתובתה שאומרת מסרתי לך עצמי ומה אעשה לך יותר:","\u0003ומ\"ש ואם מגרשה מעצמו בלא כפייה וכו'\u0004 הוא בתשובת הרא\"ש כלל מ\"ג סי' י\"א:","\u0003ומ\"ש בד\"א שאינה תובעת כתובתה בתוס' ס\"פ הבע\"י ובתשובת הרא\"ש כלל מ\"ג סי' ב' וסי' י\"א:\u0004 ","\u0003שאלה להרא\"ש אשה שתובעת שאין הבעל שוכב עמה וכו'\u0004 ואיני יודע למה הוצרך לפרש דבריה ישאלוה והיא בעצמה תפרשם כלל מ\"ג סי' ד' ועיין בכלל ל\"ג סי' ב' וג':","\u0003שאלה ראובן שהה עם אשתו כ' שנים ולא ילדה וכו'\u0004 כלל ח' ס\"ז:","\u0003שאלה על התשובה הראשונה וכו'\u0004 שם:","ובטענת מאיס עלי אם כופין אותו להוציא כתב א\"א ז\"ל בתשובה כלל מ\"ג סימן ו' וכבר כתבתי בסימן ע\"ז דעת הפוסקים בדין זה ועיין בתשובת הרא\"ש כלל מ\"ג סימן י\"ב וכתוב בתשובת הרא\"ש כלל נ\"ה סימן א' על אלמנת ת\"ח ובת גדולים שהיה מלמד תינוקת דר בביתה וקדשה ואין זה כבוד בעלה הראשון והיא אומרת שמואסת בו אם יראה לרבותי הקרובים בדבר שהמקדש אינו אדם ראוי והגון לידבק בבת טובים ובנכל ובתרמית פתוה קרוב הדבר לדמותו לעובדא דגרסינן בפרק ב\"ש (יבמות קי.) משום שעשה שלא כהוגן הפקיעו הקידושין ג\"ז שעשה שלא כהוגן נהי דקידושין לא נפקיע מ\"מ יש לסמוך בנדון זה על דברי קצת רבותינו שפסקו בדינא דמורד דכופין אותו לגרשה אמנם יש לנסות אם יוכלו לפייסו במנה כסף ואם לא יאות אני נגרר אחריכם לכופו לגרשה עכ\"ל:","\u0003ואם היא ארוסה ואינה רוצה לינשא בטענת מאיס עלי וכו':\u0004 ","\u0003וששאלת אשה שיראה מבעלה שילך לארץ אחרת וכו'\u0004 כלל מ\"ג סימן י\"ג ובסימן ח' כ' וז\"ל ואם דעתו לעגנה ראוי הוא שתסמוך על מנהגיכ' בעת הזאת לכופו ליתן גט לזמן:","\u0003וששאלת מי שטוענת שיכפוהו לבעל שיגרשנה וכו':\u0004 ","\u0003נשא אשה ושהה עמה וכו'\u0004 משנה וברייתא בס\"פ הבע\"י (יבמות ד' סד):","\u0003מ\"ש או ישא אחרת וכו'\u0004 אפילו אמרה דיירנא בהדיה בסהדי וכו' פשוט בגמרא ס\"פ המדיר (כתובות דף עז:) כתב הריב\"ש בתשובה סי' ט\"ו דעת קצת מפרשים דדוקא קתני מתני' שהתה י' שנים ולא ילדה הא אם ילדה ולד של קיימא אף ע\"פ שעדיין לא קיים מצות פריה ורביה אין כופין להוציא מיהו היינו בזו שלא הוחזקה עקרה עדיין ואיפשר שתלד לו עוד שהרי כבר זכה ליבנות ממנה אבל בזקנה שאין לה תקנה אף ע\"פ שילדה לו כיון שאין לו בנים כשיעור הצריך לקיום המצוה כופין אותו להוציא ואצ\"ל לדעת מי שאומר דשהתה עשר שנים ולא ילדה ארישא קאי כלומר שלא ילדה ולד קיימא השיעור הצריך עד כאן לשונו ועיין בתשובות הרשב\"א שאכתוב בסי' זה: \u0005ב\"ה כתב ה\"ה בפט\"ז שכתב הרשב\"א בשם הירושלמי היו לו בנים ומתו מונה משעה שמתו. \u0006כתוב במישרים נכ\"ג ח\"ח וז\"ל כתב הרא\"ש יש מחלוקת במי ששהא עם אשתו י' שנים ולא ילדה אם כופין אותו בשוטים וכיון שנחלקו בו הגדולים ראוי להחמיר שלא לכוף בשוטים דלא ליהוי גט מעושה עכ\"ל:","\u0003הפילה תוך י' שנים וכו'\u0004 משנה בס\"פ הבא על יבמתו (יבמות דף סה:) הוא אומר הפילה תוך י' שנים וכו' ג\"ז שם מימרא דרבי אמי (דף סה:) הפילה ג\"פ יוציא מיד וכו' ג\"ז שם: הפילה וחזרה והפילה הוחזקה לנפלים וכתב הרא\"ש ואם הפילה ג' פעמים תצא שלא בכתובה ואם הפילה ב' פעמים אליבא דרב תצא בכתובה ולא תינשא אלא למי שיש לו בנים ואם נישאת למי שאין לו בנים תצא שלא בכתובה אם לא הכיר בה כך הוה מסתבר לי לפרושי דחזקה זו שהוחזקה להיות מפלת אתרעי גופה שלעולם לא יגמור הריונה וה\"ל כמו אשה שהוחזקה אצל ב' אנשים שאנו מחזיקים אותה עקרה ורש\"י ז\"ל לא פירש כן וכן הרי\"ף אלא יוציא ויתן כתובה ואין לו להמתין עד י' שנים דכיון שהוחזקה אצלו בנפלים שמא לא זכה ליבנות הימנה ומותרת לינשא לאחר דאין תולין בה אלא בעונש הבעל ודברי אף ע\"פ שדברי טעם הם בטלים הם כנגד דברי רבותינו עכ\"ל:","\u0003ואם הוא אומר שלא הפילה אלא ב\"פ וכו'\u0004 פשוט בס\"פ הבע\"י שם:","\u0003וכתב הרמב\"ם ועל כל זה משביעה שבועת היסת וכו'\u0004 בפט\"ו:","\u0003יש דבר לתלות בו מה שאינה יולדת כגון שהיה הוא או היא חולים וכו'\u0004 פשוט בס\"פ הבע\"י (יבמות דף סד.):","\u0003אין ישיבת ח\"ל עולה ממנין י' שנים בס\"פ הבע\"י שם:\u0004 ","\u0003כתב א\"א ז\"ל י\"א שבח\"ל אין כופין להוציא וכו'\u0004 ג\"ז בס\"פ הבע\"י ועיין בפירוש התורה להרמב\"ן פרשת לך לך ובמהרי\"ק שורש ע\"ב ובמרדכי ס\"פ הבע\"י ובהג' מיימון פט\"ו מה' אישות (וכ\"כ נ\"י דף ת\"ה):","\u0003בא להוציא תוך י' שנים וכו'\u0004 מימרא בס\"פ הבע\"י (יבמות ד' סה.):","\u0003וכתב הרמב\"ם ויש לו להחרים וכו'\u0004 בפט\"ו:","\u0003ואם הוא אומר אשא אשה אחרת כו'\u0004 בס\"פ הבע\"י (שם) פלוגתא דרב אמי ורבא ופסקו הרי\"ף והרא\"ש כרבה:","\u0003ומ\"ש ואם ילדה האחרת יוציא הראשונה בלא כתובה ואם גם האחרת אומרת שאינו יורה כחץ וכו'\u0004 עיין בנ\"י:","\u0003ומ\"ש רבי' בשם הרמ\"ה כ\"כ במישרים בשמו:\u0004 ","גירשה הראשון יכולה לינשא לשני משנה שם (דף סד:):","\u0003נישאת לשני ושהתה עמו י' שנים וכו'\u0004 ולאחר שתצא ממנו לא תינשא לג' וכו' ג\"ז בס\"פ הבא על יבמתו שם סתם מתני' כר' דאמר בתרי זימני הויא חזקה:","\u0003עברה ונישאת לו וכו'\u0004 ג\"ז שם ת\"ר נישאת לאח' ולא היו לה בנים לב' ולא היו לה בנים לג' לא תינשא אלא למי שיש לו בנים נישאת למי שאין לו בנים תצא בלא כתובה וכתבו התוספות והרא\"ש שכתוב בה\"ג דבלא הכיר בה איירי אבל הכיר בה יש לה כתובה:","\u0003ואם שהתה עם הג' י' שנים ולא ילדה וכו'\u0004 גם זה שם בעיא דאיפשיטא:","\u0003ומ\"ש ומ\"מ אם עדיין לא גבתה וכו'\u0004 כ\"כ הרא\"ש שם:","\u0003ואם נישאת לד' וילדה וכו'\u0004 גם זה שם בעיא דאיפשיטא:","\u0003כתב הרמב\"ם אשה שבאה לב\"ד וכו'\u0004 בפט\"ו דין מתנה עם אשתו שלא ישא אחרת עליה אם הוא כמתנה ע\"מ שכתוב בתורה כתוב בתשובת הרא\"ש ורבי' בסי' קי\"ח כתב הריב\"ש בסט\"ו על אדם שאין לו בנים ורצה לישא זקנה בת צ' שנה לשם ממון שורת הדין שב\"ד מונעים אותו מלישאנה אבל מה נעשה שלא ראינו מימינו ולא שמענו מכמה דורות בית דין שנזקק לזה לכוף ולהוציא באשה ששהתה עם בעלה י' שנים ולא ילדה או שהיא זקנה ואף אם אין לו בנים וכן לא ראינו ב\"ד שנזקקו למחות במי שנושא קטנה ואע\"פ שדינם שוה לזקנה כמ\"ש הרמב\"ם ואפילו מי שיש לו בנים אין לו לישא קטנה כמו שאמרו בפרק כל היד (נדה יג:) הני דנסבי קטנות מעכבים את המשיח וכן אחז\"ל (קידושין מא.) אסור לאדם שיקדש את בתו קטנה ומימינו לא ראינו במי שמיחה בזה וכן בבת כהן ובת ת\"ח לע\"ה ולזה אם היו ב\"ד נזקקין לדקדק בשורת הדין הגמור בעניני הזיוגים ובאו לכפותם היו צריכים לכפות את כולם ורוב הנשים הבאות בימים היו יוצאות ונוטלות כתובה וליכא כתובה דלא רמו בה תיגרא ותרבה הקטטה והמריבה ולזה העלימו חכמי דורות עיניהם בעניני הזיווגים שלא למנעם ואצ\"ל שלא להפרידם כל ששניהם רוצים ואין בנישואי ההם משום ערוה ולא משום איסור מצוה ולא משום קדושה עכ\"ל והאריך עוד בדבר:","\u0003כל הנושא בעבירה וכו'\u0004 בס\"פ המדיר (כתובות דף עז) אמר שמואל אין מעשין אלא לפסולות כגון אלמנה לכ\"ג וכו' אבל נשא אשה ושהה עמה י' שנים ולא ילדה אין כופין אותו ורב תחליפא אמר אפילו נשא ושהה עמה י' שנים ולא ילדה כופין אותו להוציא:","\u0003וכתב הרי\"ף דה\"ה בכל הנך וכו'\u0004 בס\"פ הבע\"י כתב דהיכא דנשא אשה ושהה עמה י' שנים שכופין אותו להוציא בשוטים וכן פירש רש\"י שם ומ\"מ מ\"ש רבינו בשם רב אלפס דה\"ה לכל הנך דקתני בהו יוציא לא מצאתי לרב אלפס שכתב כך ונ\"ל שיש להגיה ולכתוב ר\"י במקום רב אלפס שסברא זו בשם ר\"י כתבו התוספות והמרדכי בר\"פ המדיר ושם כתבו ג\"כ סברת ר\"ח ומ\"מ אפשר לקיים גירסת הספרים דגרסי כתב הרי\"ף דה\"ה בכל הנך כו' ממ\"ש הרא\"ש בפרק הבע\"י ומיהו בתוס' תני מקמץ ומצרף נחושת ובורסי יוציא ויתן כתובה והיינו על כרחו כופין כדתנן בפרק המדיר ושרש\"י כתב בשמעתין שכופין אותו ב\"ד וכ\"כ רב אלפס עכ\"ל:","ור\"ח כתב כל היכא דאמור רבנן יוציא ויתן כתובה וכולי דברי ר\"ח טעמו \u0005ב\"ה צריך להגיה ולכתוב כלשון הזה כתבו התוס' בפרק המדיר והרא\"ש בסוף פרק הבא על יבמתו \u0006כתב הרא\"ש והתוס' בס\"פ הבא על יבמתו:","כתב א\"א ז\"ל גם זה שם וכן כתבו התוס' בר\"פ המדיר וכתבו המרדכי בר\"פ המדיר בשם הר\"מ כל היכא דתני יוציא ויתן כתובה נהי דאין כופין אלא בראיה ברורה מ\"מ נפיק ממונא מידיה ויהיבנא לה מנה מאתים ונדוניא דהנעלת ליה אבל תוס' איכא פלוגתא דרבוותא ודין מוכה שחין לענין ממון עיין בתוספות פרק הבא על יבמתו כתב המרדכי בפרק המדיר בכל הני דקתני כופין שיוציא ויתן כתובה לא כפינן אלא בדברים בעלמא ולא בשמתא דחמירא מנגידא ואמרינן בפ' שבועת הדיינין (שבועות מא.) גבי שמתא האי לינקוט בכובסיה הוא אבל הר\"ם הכהן בשם ר\"ת כתב דנוכל לעשות שנקבל גזירה שלא לישא וליתן עמו עד שיקבל ליתן גט אבל לנדות לא וכן עשה ר\"ת מעשה באחד שלא היה מאותם שכופין להוציא ונידוהו עד שנתן ופסל אותו גט וצוה לעשות לו גט אחר עכ\"ל: \u0005ב\"ה סדר הגט ונתינתו לא\"א הרא\"ש ז\"ל וכו' בפסקיו בסוף גיטין:\u0006 כתב הרשב\"א (ח\"ג סי' ש\"מ) בתשוב' דהא דאמרינן הפילה וחזרה והפילה הוחזקה לנפלים לא אמרו אלא במי שלא ילדה בן קיימא הא ילדה ראויה היתה זו אלא שלאחר מכן נתקלקלה ושדהו הוא דנסתחפה והגע עצמך אם ילדה ועמדה מלדת הנאמר שיגרש הא ודאי לא יגרש דשדהו הוא דנסתחפה ולא אמרו במשנתינו אלא שלא יבטל אדם מפריה ורביה אלא א\"כ יש לו בנים אלא יתעסק עד שיהיו לו ובאשה זו אם ירצה יקח אשה אחרת על אשתו אם עמדה מלדת אבל לגרש לא אמרו אלא כששהה עמה עשר שנים ולא ילדה ומשמע שלא ילדה כלל הא ילדה לא וטעמא כדפרישית דאיהו הוא דנסתחפה שדהו: וכתב עוד כל שילדה ודאי נראה דקלקול חולי הוא שנתקלקלה בית ולד שלה וכל מחמת חולי אין זמן עשרה שנים עולה לו כדאיתא בפרק הבא על יבמתו וכל שהוא מחמת חולי סופו להבריא ועוד תדע דלא אמרו בששהה י' שנים אלא שבזמן שניכר שהיא עקרה שהרי שנינו אם הפילה מונה משעה שהפילה והטעם בזה דמ\"מ כיון שנתעברה ניכר שאינה עקרה אלא שוהה עמה עוד י' שנים דשמא כיון שאינה עקרה עוד תלד ולד של קיימא אבל אם לאחר שהפילה לא ילדה חוששין שבית ולדה שלה מקולקל שלא לגמור ולד של קיימא או שלא לקבל הזרע ומ\"מ לא אמרתי אלא שלא לכוף בשוטי' להוציא כמו שכופין למי ששהה עמה עשרה שנים ולא ילדה אבל הוא מצוה שלא יתבטל מפ\"ו ואם לא מזו ישא אחרת ותדע דבאותה שלא ילדה קאמרינן דהא כששהא עמה עשרה שנים אפי' אמרה דיירנא בהדיה בסהדי לא שבקינן לה כדאמרינן בהמדיר מפני שהיא מוחזקת בעקרה שלא תלד אבל זו שילדה יצתה מכלל עקרה ולמה לא תשב עמו הרבה נשים עמדו מלדת אחר שילדו מחמת מקרה שקיבל בית הולד שלהן ואחר ילדו ע\"י רופא ושמא זו אם תשב אצלו עוד תלד לו והילכך יקח אשה על זו ותשב זו עוד תחתיו ולא בעדים אלא אדרבא תזקק לו ועוד אילו היה לו בנים ומתו דקי\"ל כר' יוחנן (יבמות סג.) דלא קיים פ\"ו הנאמר שאלו אשר מתו אחר אשר זקנה אמם שנכוף אותו בשוטים לגרש אם הבנים ויקח אשה אחרת ומי שילדה לו בנים ונמצא אחד מהם סריס שלא קיים פ\"ו נאמר שיגרש את אשתו הזקנה ואם לא רצה הנאמר שישא אשה אחרת ויוציא זו אשר ילדה לו זה אין השכל מקבלו אלא שחייב לישא אשה על אשתו ותלד לו עכ\"ל ועיין בתשובות הריב\"ש שכתבתי בסימן זה: מ\"כ בשם ספר אגודה בפרק הבע\"י פעם אחת בא מעשה לידי לאה טוענת על ראובן שהיה רועה זונות והוא כופר ופסקתי שאם תביא עדים שהוא כן יוציא ויתן כתובה אי בעית אימא קרא ואבע\"א סברא ואבע\"א גמרא קרא דכתיב (בראשית ל״א:נ׳) אם תקח נשים על בנותי גמרא דאמרינן הכא הא דאיפשר בסיפוקייהו ובנדון זה יאבד הון דגרע מכל הנהו דפרק המדיר ודוקא שיש עדים שראו אותו עם המנאפים אבל אם הביאו לו הזרים בנים עבור זה לא כפינן ליה שראינו כמה נתפסים בעלילות ודוקא שיכולה האשה לבקש עדים שיעידו מעצמם אבל לא פסקתי להחרים על ככה דכל ישראל בחזקת כשרות עד שיודע פיסולו גם אמרתי שיעידו עדים זה שלא בפני זה ויחקרו אותם בדרישה וחקירה כמו על דיני נפשות ואחרי שפסקתי הפסק שלחו קרובי האשה תשובת הרמב\"ם ז\"ל והאריך בו מאד וכתב כל הני טעמי שכתבתי וסוף דבריו היכא דאיכא עדות או כשהודה מעצמו כייפינן ליה להוציא עכ\"ל כתב המרדכי בפרק אע\"פ אף אם זה האיש שוחק ומאבד ממונו בשחוק לא מצינו שתוכל אשתו למרוד בו לא מתשמיש ולא ממלאכה כיון שלא החציף להעבירה על דת לשמש באיסור עכ\"ל מצאתי בתשובת רבינו שמחה המכה את אשתו מקובלני שיש יותר להחמיר מבמכה את חבירו דבחבירו אינו חייב בכבודו ואשתו חייב לכבדה יותר מגופו והעושה כן יש להחרימו ולנדותו ולהלקותו ולענשו בכל מיני רדוי ואף לקוץ ידו אם רגיל בכך ואם הוא רוצה לגרש יוציא ויתן כתובה ואחר כך כתב תטילו שלום ביניהם ואם לא יעמוד הבעל בקיום השלום שאם יוסיף להכותה ולבזותה אנו מסכימים להיות מנודה ויעשוהו ע\"י עכו\"ם לתת גט או עשה מה שישראל אומרין לך ואפי' לשמואל שאמר בפרק המדיר עד שיכופוהו להוציא יכפוהו לזון ה\"מ מזונות שיש תקנה בידינו לירד לנכסיו ולזון אותה אבל להכותה ולבזותה שעניה זו מסורה בידו ואין בידינו לעשות תקנה לדבר אפי' שמואל מודה ואפי' בההוא גופא דזן ומפרנס כרב קי\"ל ואפי' קבלה עליה יכולה לומר איני יכולה לקבל שהן הכאות שאין להם קצבה וכן כתב בהגהות אשיר\"י פרק המניח את הכד בשם א\"ז וז\"ל אסור לאדם להכות את אשתו וגם חייב בנזקיה אם הזיקה הוא ואם רגיל תמיד להכותה ולבזותה ברבים כופין אותו להוציא וליתן כתובתה וכן השיב רבינו שמחה שיעשוהו ע\"י עכו\"ם עשה מה שישראל אומרין לך עכ\"ל ועיין בתשובה להרמב\"ן סימן ק\"ב וכתבתי בסוף סימן ע\"ד ומ\"מ נ\"ל דאין לסמוך על דברי ספר אגודה ורבינו שמחה וא\"ז לכפות להוציא על דברים כיון שלא נזכרו בדברי שום אחד מהפוסקים המפורסמים ועי' בתא\"ו נכ\"ג ח\"ה: מ\"כ בשם רבינו ברוך נ\"ל דכל היכא דקתני יוציא ויתן כתובה נהי דאין כופין אותו אלא בראיה ברורה מ\"מ נפיק ממונא מיניה דכיון דחייבוהו חכמים בממון זה לתת הילכך מפקינן מיניה כתובה ויהבינן לה מנה ומאתים ונדוניא דהנעלת ליה אבל תוספת איכא פלוגתא דרבוותא ר\"ת כתב בר\"פ אע\"פ (כתובות נד:) דתוספת נמי אית לה דלכל מילי תנאי כתובה ככתובה דמי ור\"ח כתב דוקא להני מילי דמייתינן בפרק אע\"פ אמרינן תנאי כתובה ככתובה דמי למידי אחרינא לא ומספיקא לא מפקינן מיניה התוס' כיון דאיפליגו ביה רבוותא ז\"ל עכ\"ל: מ\"כ ראובן תלה ונתן גט לאשתו מהיום אם מתי מעכשיו ונפטר ולא הניחו לאששתו ליגע אליו ואפי' לבכותו ולא לצאת אחר מטתו כי אמרו שאם תעשה אחד מהן תבטל הגט ונראה שאין ממש בדבריהם דלא מיבעיא הספד ובכיה דלא מבטלי גיטא אלא אפי' היתה היא מבטלת הגט לא ביטל דאין בטל אלא באיש שהאשה מתגרשת שלא לדעתה משא\"כ באיש וכ\"ש דלאחר מיתה ליכא למימנע על זה ועל זה ועל כיוצא בזה אמרו חכמים כל שאינו יודע בטיב גיטין וקידושין לא יהא לו עסק בהם: כתב הריטב\"א בתשובה על איש שנשבע לגרש את אשתו וגירשה קודם שיתירו לו ואח\"כ היה מערער לפסול הגט מפני כך והשיב זו אינה טענה לפסול הגט בדיעבד שלא מצינו שיהא חשוב אונס בגט אלא באונס שבא לו שלא מעצמו אבל שבועה זו הוא הביאה על עצמו שהרי מרצון עצמו חייב עצמו בשבועה לגרש לפי שגמר דעתו לגרש עכ\"פ לזרוזי נפשיה ואם נתחרט אחר שבועה ואינו מגרש אלא מחמתה ה\"ל לבקש צד להיות נקי משבועתו או לגלות דעתו למסור מודעא בכך:","\u0003ומ\"ש ה\"ר פרץ שצריך שיתירו לו וכו'\u0004 לפי דעתי לא כתב אלא שצריך כן לכתחלה לעשות גירושין ברורים לא שיהא פוסל הגט בזה בדיעבד וכמו שכתב שם בהלכות ההם דברים הרבה דרך חומרא ולמעשה מובחר וכ\"נ מלשונו שכתב כאן כדי שלא יהא דומה לאונס הרי שלא כתב רבי' שיהא זה אונס וזה נראה ברור וכמדומה לי שכך דן הרב ז\"ל וכן הסכים עכ\"ל ב\"ה וכ\"כ בתשובת הריב\"ש והרא\"ש שכתבתי בתחלת סימן זה. וה\"ר לוי ן' חביב ז\"ל עשה מעשה במי שנדר נזירות שמשון לגרש את אשתו וגירשה בבית דינו וכתב על זה פסק ארוך והביא כמה ראיות לדבריו וכתב בסוף דבריו על ה\"ר משה קשטרו ז\"ל ואנהרינהו לעיינין מפרק השולח (גיטין מה:) המוציא את אשתו משום נדר לא יחזיר וכו' א\"ר יוסי מעשה בצידן באחד שאמר לאשתו קונם אם איני מגרשיך וגירשה וכו':"],["\u0003אלו שכופין אותו וכו'\u0004 משנה ס\"פ המדיר (כתובות דף ע\"ז) אלו שכופין אותו להוציא מוכה שחין וכו' ופירש\"י וכולן מפני שאומנתן מסרחת היא ומפרש בגמרא דהאי כפייה הוא בשוטים.","ומ\"ש והמחתך נחשת מעיקרו פירש\"י ממקום מוצאו מן הארץ והיינו כרבב\"ח ותניא כוותיה דלא כרב אשי דאמר חשלי דודאי פ' מחשלין ומרדדין נחשת ועושין ממנו יורות ומסריח הוא וכתבו התוס' נראה לר\"י דיוציא ויתן כתובה קאמר אעפ\"י שמגרשה בעל כרחו וכו':","\u0003אבל אם התנה עמה וכו'\u0004 שם במשנה פליגי בה רבי מאיר וחכמים ופסק כחכמים ומפרש רבינו דחכמים לא קיימי אלא היכא דהתנה עמה אבל הרמ\"ה מפרש דחכמים קיימי נמי אהיכא דידעה וראתה ולא התנה נמי מקבלת היא בע\"כ וכ\"כ הר\"ן ע\"ש הרמב\"ם וצ\"ל לפ\"ז דהא דתנן אם התנה ר\"מ הוא דקאמר הכי להשמיענו רבותא דאפי' התנה עמה יכולה שתאמר סבורה הייתי שאני יכולה לקבל אבל לחכמים אפילו לא התנה אלא דידעה וראתה מקבלת היא בע\"כ ומתני' דתני כופין להוציא בין שהיו עד שלא נשאו ובין משנשאו למדו היינו דוקא בדלא ידעה בהם כלל ולא אתא לאשמועינן אלא דאעפ\"י שלא היו בו אלא דלאחר שנשאו למדו לא אמרינן לאשה דנסתחפה שדך דלגבי אשה ליכא למימר הכי דאין האיש שדה של אשה כמ\"ש התוספות לשם:","\u0003אבל מפני מומין שבו אין כופין וכו'\u0004 אדלעיל קאי דכופין להוציא אם הוא מוכה שחין וכו' אבל מפני מומין אין כופין וכו' והוא משנה שם ופסק כרב יודא דאפילו נולדו אין כופין כ\"ש היו דסברה וקבלה ולרבינו ניחא דלגבי מוכה שחין וכו' אם היו בו אע\"ג דסברה וקיבלה יכולה לומר סבורה הייתי שיכולה לקבל ועכשיו אין יכולה לקבל וכופין אותו להוציא אא\"כ התנה עמה תחלה אבל מפני מומין אין כופין אבל להרמ\"ה דבמוכה שחין וכו' נמי אפילו בסתם נמי אם ידעה בהם אין כופין אותו להוציא אא\"כ דלא ידעה בהם כלל אם כן גבי מומין דאין כופין בע\"כ דאפי' לא ידעה בהם כלל קאמר דאין כופין וא\"כ קשה מאי האי דקאמר כ\"ש היו דסברה וקיבלה הלא ליכא למימר דסברה וקיבלה כיון דלא ידעה בהא כלל וי\"ל דמ\"מ שפיר קאמר כ\"ש היו כיון דאפשר דידעה וסברה וקבלה משא\"כ בנולדו דלא שייך כלל לומר סברה וקבלה וז\"ל התוספות סבורה הייתי שאני יכולה לקבל קצת תימה דא\"כ כל אשה תערים ותשאנו כדי שיתן לה כתובה שתאמר איני יכולה לקבל ויגרשנה ושמא במקום שיש חשש ערמה אין לה כתובה עכ\"ל ונראה דלא הוצרכו לכך אלא לר\"מ דאפילו התנה עמה יכולה היא שתאמר סבורה הייתי וכו' אבל לחכמים דקי\"ל כוותייהו דבהתנה עמה ודאי דמקבלה ע\"כ ליכא קושיא כלל דכל אשה תערים וכו' דאיהו אפסיד אנפשיה דה\"ל להתנות עמה בפי' וכ\"ש להרמ\"ה דאפילו בסתם נמי אמרינן דאי ידעה בהם סברה וקבלה:","אבל נסמו ב' עיניו וכן פי' אעפ\"י שהיו בו קודם שנשאו אם לא התנה עמה דאם התנה עמה מתחלה אין כופין אותו לדעת רבינו אפילו נסמו ב' עיניו חוץ ממוכה שחין בלחוד כדלעיל ולהרמ\"ה בב' עיניו אפילו בניסת סתם אם ידעה וסברה וקבלה אין כופין אותו:","\u0003מי ששואלת גט בטענה וכו'\u0004 בס\"פ הבע\"י הוא אמר מינה והיא אמרה מיניה א\"ר אמי דברים שבינו לבינה נאמנת וטעמא מאי היא קיימא לה ביורה כחץ הוא לא קיים ליה ביורה כחץ ופירש\"י מינה יודע אני שמחמתה הוא שאין לה בנים ולא אתן כתובה כל ש\"ז שאינו יורה כחץ אינו מזריע ובסוף אותו הדף מחלק תלמודא דלא כפינן ליה להוציא וליתן כתובה אלא בבאה מחמת טענה בעינא חוטרא לידה ומרא לקבורה אבל ברוצה להבנות בלחוד כיון דאשה לא מיפקדא אפריה ורביה אין שומעין לה לכופו ולגרש ואם רוצה לגרשה אין לה כתובה וכל שאר חילוקי דינים שכתב רבינו מבוארים לשם בתוספות ובאשר\"י:","\u0003ואם טוענת שאין לו גבורת אנשים וכו'\u0004 דכיון שטוענת טענה שהבעל יודע וכו' כתב כן כדי ליישב דלא דמי לטוענת שאין יורה כחץ דאינה נאמנת תוך י' שנים משום דכיון שבעלה לא ידע בה דמשקרה חיישינן שמא משקרה ומעיזה אבל הכא ידע דמשקרה אינה מעיזה ונאמנת:","\u0003אשה שטוענת שאין הבעל שוכב עמה וכו'\u0004 יש לנו לפרש דבריה בענין שלא יסתרו וכו' כלומר דאם היו סותרים לא היינו כופין אותו מספק דשמא טענה הראשונה אמת אבל כיון שאפשר לפרש שאינן סותרין אלא בראשונה נמי כיונה לומר שלא בא עליה כלל כופין אותו וכתב ב\"י ואיני יודע למה הוצרך לפרש דבריה ישאלוה והיא בעצמה תפרשה עכ\"ל ואין זה קושיא דאם לא היה נראה בעיניו לפרש דברים בענין זה לא היינו מקבלין פירוש זה שהוא שקר. ועוד דכיון שיצאת חוץ לב\"ד לא היינו מקבלין פירושה ולפיכך הוצרך לומר דבעיני ב\"ד נראה שיש לפרש דבריה שאינן סותרים:","\u0003שאלה ראובן שהה עם אשתו כ' שנה וכו'\u0004 כי עשתה לו טובה וכו' וזהו גם כן שאמר בסמוך על טובה שעשתה לו במחילת המזון כלומר שמחלה לו מה שכבר נתחייב לה בעד המזון. ובס\"א כתוב במחילת הממון:","\u0003ומ\"ש תשובה אין לגרוע כח הראשונה וכו'\u0004 פי' אין לגרוע כחה לא לענין פרעון כתובה ולא לענין מזונות ולכן מה שיותיר על כדי חייו יתן חצי לזו וחצי לזו:","\u0003ומ\"ש ואפילו אומרת דיירנא בהדיה בסהדי וכו'\u0004 ה\"א ס\"פ המדיר ומפרש הרמב\"ם בפט\"ו דאישות וכ\"כ רבינו דכל זמן שלא נשא אחרת צריך לגרשה לזו ולא יועיל כשתאמר האשה לא אתייחד עמו כלל או האיש אומר לא אתייחד עמה כלל וא\"כ למה אגרש אותה כיון שעדים מעידים שלא אתייחד עמה ולא אבא אליה וא\"כ בודאי היום או מחר אשא אשה אחרת לביתי אפ\"ה כל זמן שלא נשא אחרת צריך לגרשה לזו כי לא נאמין לו שישא אשה אחרת:","\u0003הפילה וכו'\u0004 משנה ס\"פ הבע\"י והיא אומרת שלא הפילה היא נאמנת שם בגמרא דאי איתא דאפילה נפשה בעקרתא לא מחזקא:","ומ\"ש מ\"מ מוחרת לינשא לאחר טעמו משום דלא איתרעי גופה שלעולם לא יגמור הריונה אלא תולין בעונש הבעל שלא זכה הוא לבר קיימא ממנה: ומ\"ש והיא אומרת שהפילה עד ג' פעמים נאמנת שם דאי איתא דלא אפילא נפשה בנפלים לא מחזקא ואע\"ג דמותרת לינשא לאחר מ\"מ אין לה קופצים אחרי שהוחזקה לנפלים הרא\"ש:","\u0003בא להוציא תוך עשר שנים כו'\u0004 ס\"פ הבע\"י הוא אמר מינה וכו' וע\"ל סעיף ה':","\u0003ואם הוא אומר אשא אשה אחרת ואבדוק עצמי וכו'\u0004 שם אמר איהו איזיל אינסיב איתתא איבדוק נפשאי א\"ר אמי אף בזו יוציא ויתן כתובה וכו' רבא אמר נושא אדם כמה נשים וכו':","\u0003ואם ילדה האחרת יוציא הראשונה בלא כתובה וכו'\u0004 תימא דלעיל הביא תשובת הרא\"ש שפסק אין לגרוע כח הראשונה במה שאין לה בנים כיון שלא הוחזקה בג' אנשים וכן מוכח בפרק הבע\"י דלא גרע כחה בין לענין מזונות בין לענין כתובה אף עפ\"י שיש לו בנים מאשה אחרת כ\"ז שלא הוחזקה בג' אנשים ואע\"ג שילדה האחרת שנשא וכאן פסק בהיפך דאם ילדה האחרת יוציא הראשונה בלא כתובה ופשיטא דה\"ה אם לא יוציא דאינו חייב במזונות ובתשובת הרא\"ש פסק דאם אינו מוציא בגט יש לה מזונות ואפשר לומר דתשובת הרא\"ש הוא ע\"פ ההוכחה דדייק מדקבעי תלמודא נישאת לג' ולא ה\"ל בנים מהו דליתבעוה הנך קמאי מי מצי א\"ל איגלאי מילתא דאת הוא דגרמת ומדלא מיבעיא ליה אם נשאו הראשון והשני וילדו מהו דליתבעוה כתובה דאיגלאי מילתא דאת גרמת אלמא דלא אמרינן איגלאי מילתא אא\"כ הוחזקה בג' אנשים דתלינן שמא לא זכו ליבנות ממנה ואעפ\"י שר\"י תירץ וכו' וכתב וקצת י\"ל דמיירי בשיש לו בנים מאשה אחרת הלכך אין לתלות בעונש שלו אלא אית לן למימר דאיהי לא זכתה ליבנות ממנו וכו' לא סמכינן אהאי שינוייא דאית תמן שינוייא אחרינא וכו' ובפסקיו נמי כתב שינויא דר\"י וז\"ל ומיהו שמא י\"ל דכיון דקיים פריה ורביה אין לנו לתלות בעונש שלו אלא אית לן למימר אדרבה איהי הא לא זכתה וכו' ואחר כך כתב והר\"ש בר חיים תירץ דמיירי כששהתה עם השלישי י' שנים וכו' יש מתרצין דבנדרים איירי כשהיא באה להפקיע עצמה מתחת בעלה בע\"כ הלכך חיישינן שמא נתנה עיניה באחר אבל הכא דמיירי שהבעל רוצה לגרשה ובכתובה הוא דפליגי ולא שייך הכא שמא עיניה נתנה באחר ורב אלפס מפרש דהאי הוא אמר מינה קאי אשהה עמה עשר שנים והוא טוען ברי מינה הוא דלאו בת אולודי היא כגון שהיא מפלטת שכבת זרע (הגה\"ה מדברי ה\"ה הוא טוען ברי שהיא מתקשה בשעת תשמיש) אלא שאינו יכול לברר בעדים ורוצה לישבע ואין מוציאין ממנו כתובה כיון שטוען טענת ברי אלא שהיא אומרת ומה בכך שהיא אינה ראויה לילד גם הוא אינו ראוי לילד והיא טוענת ברי שאינו יורה כחץ והוא אינו יכול להכחישה דלא קים ליה ביורה כחץ וקמ\"ל רבי אמי דהיא נאמנת למאי דפי' אפילו בתוך עשר נמי והוא בא לגרשה בלא כתובה שטוען ברי שאינה ראויה להוליד והיא אומרת מיניה איהי מהימנא דלעיניה נתנה באחר ליכא למיחש כיון דהיא אינה תובעת להתגרש עכ\"ל הרא\"ש ולפ\"ז ניחא הא דכתב רבינו ואם ילדה האחרת יוציא הראשונה בלא כתובה היינו דוקא כשהיא באה להפקיע עצמה מתחת בעלה בע\"כ והוא אומר אבדוק עצמי וכו' הלכך אם ילדה האחרת יוציא הראשונה בלא כתובה ואע\"ג שלא הוחזקה בג' אנשים כיון דטוען ברי שהיא מתקשה בשעת תשמיש או שמפלטת שכבת זרע אבל לעיל בתשובת הרא\"ש הבעל לא בא בטענת ברי שאינה יולדת אלא שבא לידע אם העכבה אינה ממנו לא נגרעה כח האשה לא לענין כתובה ולא לענין מזונות וכיון שאין הבעל בא להוציאה וגם היא אינה תובעת גט ואע\"ג דלדינא דגמרא כופין אותה להוציא מ\"מ אין המנהג כך כמ\"ש לשם בשאלה וגם התנה עם הראשונה שכאשר יגרשה יתן לה כתובה ותוספת ונדוניא וא\"כ אם לא יגרשנה חייב במזונותיה כ\"ז שלא הוחזקה בג' אנשים כיון שאינו טוען ברי:","\u0003ומ\"ש והרמ\"ה כתב וכו'\u0004 פירוש חולק הוא אמ\"ש שאם גם האחרת אומרת שאינו יורה כחץ יוציא מיד ולא ישהה עמה י' שנים ע\"ז חולק הרמ\"ה שצריך שישהה עמה י' שנים:","\u0003גרשה הראשון כו'\u0004 שם בברייתא עברה וניסת לו ולא הכיר בה תצא מיד ואין לה כתובה כתב הרא\"ש אבל מן הב' יש לה כתובה אע\"ג דס\"ל להאי תנא דבתרי זימני הוי חזקה מדאסר לה לשלישי היינו דוקא לענין איסורא אבל לענין ממון בעיא חזקה תלתא זימני וכו' עכ\"ל:","\u0003כתב הרמב\"ם אשה שבאה לב\"ד וכו'\u0004 איכא לתמוה דלעיל ס\"ו כתב רבינו בדין זה דכופין אותו להוציא מיד אפי' תוך י' וכאן הביא דברי הרמב\"ם דאין כופין וי\"ל דלעיל כיון דמכחישה כופין מדרב המנונא דאין אשה מעיזה פניה בפני בעלה ובודאי קושטא קאמרה וכמ\"ש התוס' ס\"פ הבע\"י סוף דיבור המתחיל שבינו לבינה ודברי הרמב\"ם בשאינו מכחישה ובהא אמרינן בנדרים יעשו דרך בקשה:","\u0003סדר הגט ואם הבעל שולח וכו'\u0004 צריך השליח המביא הגט להיות אצל הסופר וכו' ולעיל בסימן קמ\"ב כתב שא\"צ להיות השליח אצל כל הכתיבה ואדרבא אם באו להחמיר אין שומעין לו ע\"ש סעיף י':","\u0003וצריך לדקדק שיהא כל הגט יבש וכו'\u0004 פירוש שאם לא יהיה יבש ה\"ל כתב שיכול להזדייף:"]],["\u0003הלכות מיאון \u0004\n\u0010c0\u0011\u0010y0\u0011קטנה שאין לה אב או שיש לה אב והשיאה אביה ונתארמלה או נתגרשה שאין לו עוד רשות בה והשיאוה אחיה או אמה לדעתה כיון שקדושיה דרבנן אם אינה חפצה בבעלה אינה צריכה גט אלא יוצאת ממנו במיאון אבל השיאוה שלא לדעתה או אפי' לדעתה ואינה יודעת לשמור קדושיה אפי' מיאון אינה צריכה \u0010y1\u0011ולעיל בהלכות קידושין פירשנו דין קטנה שנשאת שלא לדעת אביה אם צריכה מיאון \u0010c1\u0011\u0010y2\u0011והמיאון הוא שתאמר אי אפשי בפלוני בעלי ואי אפשי בקידושין שקידשוני אמי ואחי \u0010y3\u0011ואפי' לא מיאנה אלא שנתקדשה לאחר אינה צריכה מיאון אחר ומבטלת מעשה הראשון אפי' אם היתה נישאת כבר \u0010c2\u0011\u0010y4\u0011וממאנת בין מן האירוסין בין מן הנשואין אפילו שלא בפני הבעל ושלא בפני ב\"ד \u0010c3\u0011\u0010y5\u0011רק שיהא בפני שנים שיעידו על הדבר ור\"ח כתב דלכתחילה בעינן ג' ובדיעבד כשר בפני שנים וכן כתב בעל העיטור \u0010y6\u0011וממאנת כ\"ז שהיא קטנה אפי' ד' וה' פעמים \u0010c4\u0011וכשם שממאנת בבעל כך ממאנת ביבם אם מת הבעל ולא מיאנה בו \u0010y7\u0011והשנים שמיאנה בפניהם כותבין לה גט מיאון וחותמין לה ואינו כגט גירושין להיות נתינתו מגרשת \u0010c5\u0011לפיכך אין צריך לא כתיבה ולא מסירה ולא דבר ממשפטי הגט ואין כותבין בו טופס הגט שלא יראה כגט גמור ואתי לאיחלופי בגט \u0010y8\u0011וזהו נוסחו: \u0003בכך וכך בשבת בכך וכך לירח פלוני שנת כך וכך למנין פלוני מיאנה פלונית בת פלוני בפנינו ואמרה אמי או אחי הטעוני וקדשוני או השיאוני ואני קטנה לפלוני בן פלוני והשתא גליתי דעתי קדמיכון דלא צבינא ביה ולא [קאמינא] קאימנא עמיה והשתא בדקנו פלונית ואתברר לנא דעדיין קטנה היא וכתבנא וחתמנא ויהיבנא לה להיות לזכות ולראיה בידה:\u0004 \u0010y9\u0011ואלו שממאנת בפניהם צריכין שיכירו אותה ואת בעלה לפיכך [כל מי] שיראה שמיאנה בפני שנים יכול לכתוב לה גט מיאון להתירה אע\"פ שאינו מכירה שודאי הכירוה אותם שמיאנה בפניהם \u0010c6\u0011\u0010y10\u0011קטנה שממאנת אין לה כתובה מנה או מאתים אבל יש לה תוספת ואין לה מזונות ופירות \u0010y11\u0011כגון שהלך בעלה למדינת הים ולותה ואכלה או פדתה עצמה ואחר כך מיאנה אינו חייב לשלם אבל בעודה תחתיו חייב לזונה ולפדותה \u0010y12\u0011וכן אם יוצאה במיאון והוא לוקט פירות אפי' הם מונחים בעין הוא נוטלן \u0010y13\u0011ונכסים שהכניסה לו אם הם בעין בין של מלוג בין של צאן ברזל נוטלתן \u0010c7\u0011ואם אינם בעין צריך לשלם \u0010y14\u0011ומותרת בקרוביו וכשרה לכהונה \u0010c8\u0011\u0010y15\u0011ואינה צריכה להמתין שלשה חדשים מלהנשא \u0010y16\u0011ואם נישאת לאחר וגירשה או מת מותרת לחזור לראשון: \u0010y17\u0011וקטנה שנתגרשה יש לה כתובה ואסורה בקרוביו ואסורה לכהונה אבל גירשה והחזירה בעודה קטנה וממאנת בו וניסת לאחר אחר שמיאנה בזה וגירשה השני מותרת לחזור לראשון שכיון שיצאה ממנו במיאון אחרי גירושין נתבטלו גירושין הראשונים אבל אם מיאנה בראשון ואח\"כ החזירה וגירשה ונישאת לאחר וגירשה השני אסורה לחזור לראשון ולקרוביו \u0010y18\u0011אע\"פ שיוצאה מן השני במיאון שכל שיוצאה ממנו במיאון לבסוף מותרת לחזור לו וכל שיוצאה ממנו בגט לבסוף אסורה לחזור לו \u0010c9\u0011\u0010y19\u0011הממאנת ביבם אסורה לאביו מפני שנראית לו ככלתו בשעה שמת בנו אבל מותרת בשאר קרוביו לפיכך מיאנה מאחד מהיבמים מותרת לשאר האחין: \u0010c10\u0011\u0010y20\u0011עד מתי הקטנה ממאנת עד שתביא ב' שערות \u0010y21\u0011או עד שתלד שאם ילדה חשובה כגדולה \u0010y22\u0011אבל כל זמן שלא ילדה ולא הביאה ב' שערות יכולה למאן עד שתהא בת כ' שנה שכ\"ז שאינה בת כ' ולא הביאה ב' שערות חשובה כקטנה אפילו נולדו לה סימני איילונית אבל אם היא בת כ' ונולדו בה סימני איילונית חשובה כגדולה ואינה יכולה למאן \u0010y23\u0011והרמב\"ם כתב היתה בת כ' פחות ל' יום ונולדו בה סימני איילונית הרי היא איילונית ע\"כ ונ\"ל דטעות סופר הוא אלא כך יש לו להיות אם היא בת י\"ט שנה ול' יום דקי\"ל דלא בעינן עשרים שנה שלימים כיון דלא תני בת כ' שנה ויום אחד כי היכי דתני ג' שנים ויום אחד ול' יום כשנה חשיב שנה אבל אין שום טעם לומר כ' שנה פחות ל' יום ואם היא בת כ' שנה ולא נולדו בה \u0010y24\u0011סימני איילונית ולא הביאה שתי שערות חשובה כקטנה עד שתביא שתי שערות או עד שתגיע לרוב שנותיה \u0010c11\u0011שהן ל\"ו שנה אז חשובה כגדולה ואינה יכולה למאן אף על פי שלא הביאה שתי שערות וסימני איילונית יתבאר לקמן בעזרת השם בהל' ייבום \u0010c12\u0011\u0010y25\u0011אין שתי שערות סימן גדלות אא\"כ באו מי\"ב שנה ואילך אבל אם באו קודם לכן אפילו תוך שנת שנים עשר חשיבי כשומא ואינה נחשבת גדולה על ידם אא\"כ הביאה אחרות אחר י\"ב שנה ומיהו כשמוצאין לה ב' שערות אחר הזמן מחזיקין לה בגדולה ואפילו לחליצה ולא חיישינן שמא באו קודם הזמן ואפילו נשים נאמנות לומר שהביאה שתי שערות אחר י\"ב \u0010c13\u0011ור\"ת כתב שאם הביאה שתי שערות ביום האחרון של שנת י\"ב חשיבא שפיר גדולה: \u0010y26\u0011שתי שערות אין צריך שיהיה לכל אחד גומא אלא אפילו שנים יונקות מגומא אחת וכן ג\"כ אם יש לה ב' גומות אפילו בלא שערות חשובה גדולה וקאמרי חכמים שצריך שיהיו שתי שערות במקום אחד ור' ישמעאל אומר אפי' אחד בגבה ואחד בכריסה או אחד בקשרי אצבעותיה של יד ואחת בקשרי אצבעותיה של רגל ופסק רב אלפס כרבנן וכ\"כ הרמב\"ם. ב' שערות צריכין שיהיו במקום בית הערוה, ובית הערוה כולו ממקום סימנים בין מלמעלה בין מלמטה בין על איברי הזרע עצמן וצריכין להיות במקום אחד ושיהיו בעיקרן גומות ואפי' שתיהן בגומא אחת הרי אלו סימנין ע\"כ \u0010y27\u0011ור\"י פסק כדברי שניהם להחמיר אחת בגבה ואחת בקשרי אצבעותיה לא תמאן ולא תחלוץ עד שיהיו שניהם במקום אחד וכן הוא מסקנת א\"א הרא\"ש ז\"ל. \u0010c14\u0011\u0010y28\u0011ולענין שיעור אורך השערות פליגי בהן תנאי ר' ישמעאל אומר כדי לכוף ראשן לעיקרן ורבי אליעזר אומר כדי לקרוץ בציפורן ורבי עקיבא אומר כדי שיהיו ניטלות בזוג וקי\"ל כדברי כולן להחמיר משיהיו כדי לקרוץ כציפורן לא תמאן ולא תחלוץ עד שיהיו כדי לכוף ראשן לעיקרן והרמב\"ם כתב משיהיו נטלות בפי הזוג חשיבא גדולה \u0010y29\u0011ויראה מדבריו שהוא קודם קריצתן כציפורן בד\"א שיכולה למאן אחר י\"ב שנה שבדקו אותה ולא הביא' שערו' אבל סתמא משיש לה י\"ב שנה אינה יכולה למאן חזקה שהביאה שערות מ\"מ לא תחלוץ עד שיבדקו אותה שהביאה שתי שערות \u0010c15\u0011\u0010y30\u0011ובד\"א שיכולה למאן כשבודקין אותה ולא הביאה כשלא בעל אחר היות לה שנים עשר שנה ויום אחד אבל אם בא עליה אחרי כן אינה יכולה למאן שאע\"פ שאין מוצאין לה סימנים חוששין שמא נשרו קודם שהוא ספק דאורייתא שאם היה ידוע שהיה לה שערות קודם שבא עליה הוי קידושין גמורים שודאי בעל לשם קידושין ואם קדשה אחר אינה צריכה ממנו גט וכיון שהוא ספק דאורייתא חיישי' שמא הביאה סימנין קודם שבעל וצריכה גט מספק \u0010y31\u0011ואם מיאנה בו אחר שנבעלה ונבדקה ולא נמצא לה ונתקדשה לאחר צריכה ממנו גט מספק ואסורה לחזור לו ואם ניסת תצא מזה ומזה והולך ספק ממזר \u0010c16\u0011\u0010y32\u0011ובסה\"ת החמיר וכתב דבזמן הזה אינה ממאנת אחר י\"ב שנה אע\"פ שלא בעל משום דקי\"ל גומות אע\"פ שאין שערות ואין אנו בקיאין להבחין בדבר הזה שלא יהו בו גומות ועוד שמא הביאה ב' שערות אפילו אחד בגבה ואחד בכריסה או על קשרי אצבעותיה ומי יוכל לבדוק כל הגוף ולעמוד על אמיתת דבר זה \u0010c17\u0011הביאה סימנים אחר י\"ב ולא בעל אח\"כ הוו ספק קידושין ואם בא להוציאה צריכה גט מדרבנן \u0010c18\u0011ומיהו אם לא גירשה ועמדה ונתקדשה לאחר צריכה גט משניהם ואם ירצו מגרש ראשון ונושא שני אבל לא יגרש שני ונושא ראשון שמא יאמרו מחזיר ראשון גרושתו משנתארסה \u0010y33\u0011וכתב הרמב\"ם דוקא היכא שלא בעל אחר שגדלה ונתקדשה לאחר צריכה גט מהשני ואסורה לחזור לראשון אבל בעל אחר שגדלה ונתקדשה לאחר אפילו גט אינה צריכה מהשני ומותרת לחזור לראשון \u0010y34\u0011ואפי' לא בעל אחר שגדלה ונתקדשה שצריכה גט מהשני ואסורה לחזור לראשון אם חטפה אחר דרך אונס וקדשה בביאה אינה צריכה גט משני ומותרת לחזור לראשון \u0010c19\u0011וכתב רב אלפס דוקא שלא בא עליה שני קודם גירושי ראשון אבל אם בא עליה שני קודם גירושי ראשון אסורה לשניהם וצריכה גט משניהם כאשה שהלך בעלה למ\"ה ונשאת לאחר שאסורה לשניהם וצריכה גט משניהם אבל ממזר לית בה דנשואי דרבנן נינהו ולא נשואי תורה וכ\"כ הרמב\"ם וסיים עוד אבל אם בא עליה ראשון קודם גירושי שני הולד ממזר והראב\"ד ז\"ל התיר אפילו בא עליה שני קודם גירושי ראשון וכתב על דברי רב אלפס כדי הוא הרב לסמוך עליו אף אם יאמר על המותר אסור כי בכאן אין איסור חמור ולא לגזור בה משום אשה שהלך בעלה למדינת הים שאם גזרו במקום שיש ערוה או איסור לאו דבר תורה נגזור במקום שאין איסור ערוה ולא איסור לאו דבר תורה הלכך אם יש כאן מי שמורה להיתר נשמע לו \u0010y35\u0011וכן הוא מסקנת א\"א הרא\"ש ז\"ל:",["קטנה שאין לה אב או שיש לה אב והשיאה אביה ונתאלמנה או נתגרשה שאין לו עוד רשות בה והשיאוה אחיה או אמה לדעתה כיון שקידושיה דרבנן אם אינה חפצה בבעלה אינה צריכה גט אלא יוצאת ממנו במיאון דין יתומה קטנה שיוצאה במיאון מבואר בכמה מקומות מהן פ' ב\"ש (יבמות דף קז קח) ומה שכתב או שיש לה אב והשיאוה אביה ונתאלמנה או נתגרשה וכו' כ\"כ הרמב\"ם וכתב ה\"ה שהוא מבואר בפ' האיש מקדש (קידושין מד.) ורבינו ירוחם כתב שכן פשוט בירושלמי וכ\"כ הרמ\"ה ומ\"ש אבל השיאוה שלא לדעתה או אפי' לדעתה ואינה יודעת לשמור קידושיה אפי' מיאון אינה צריכה כך הוא הגירסא הנכונה בספרי רבינו ודברים אלו מבוארים במשנה פרק ב\"ש (שם) דתנן התם אי זו היא קטנה שצריכה למאן כל שהשיאוה אמה ואחיה לדעתה השיאוה שלא לדעתה אינה צריכה למאן רבי חנינא בן אנטיגנוס אומר כל תינוקת שאינה יכולה לשמור קידושיה אינה צריכה למאן ובגמרא א\"ר יהודה אמר שמואל הלכה כר' חנינא בן אנטיגנוס וכתב ה\"ה דקאמר בירושלמי אי זו היא לדעתה עבדין לה גננא ומלבישין לה קוזמרין ומדכרין לה גבר איזו היא שלא לדעתה עבדין לה גננא ומלבישין לה קוזמרין ולא מדכרין לה גבר ע\"כ וכתבו הרשב\"א ז\"ל. ונ\"י כתב הירושלמי הזה וכתב אח\"כ שיש מי שפירש לדעתה כבת עשר כבת י\"א ושלא לדעתה כבת ה' כבת ו' וכ' עוד אינה צריכה למאן ופירש הרמב\"ם בפירוש המשנה אינה צריכה מיאון בפני ב' אבל תלך ותינשא ותעשה מה שתרצה וכתבו עליו שאין פירושו מחוור דנישואין הן מיאוניה כדאמרינן בגמרא. ור\"ח פירש מדקאמר רבי חנינא בן אנטיגנוס כל שאינה יכולה לשמור קידושיה אינה צריכה למאן ש\"מ דבפנויה היא ואם לא נבעלה כלל שריא לעלמא ואפי' גדלה דאי לא תימא הכי מאי איכא בין רבי חנינא בן אנטיגנוס לרבי יהודה בן בתירא וכתב עליו הרשב\"א איני רואה הכרח בדבר זה לפי שי\"ל דאינה צריכה למאן דקאמר לומר שאם מתה אינו יורשה ואינו מטמא לה ואינו זכאי במציאתה ובהפרת נדריה ואפשר דלר' חנינא בן אנטיגנוס אף הקטנה שאינה יכולה לשמור קידושיה אינה יוצאת בכדי אלא במיאון דאינה צריכה למאן דקאמר אינו אלא לדברים אלו עכ\"ל וכתב שם עוד כתב תשובת ה\"ר יהודה בר ברזילי לרי\"ף דקידושי קטנה אינן כלום ואין קידושין מועילים אלא לאחר הנישואין ואז צריכה למאן אבל בקידושין לחודייהו אינה צריכה למאן והקשו עליו דהא תנן וב\"ה אומרים ארוסות ונשואות ואמרינן בפרק התקבל (גיטין סה.) וכנגדן בקטנה מתקדשת למיאון ואמרינן לקמן (קח.) איזהו מיאון כל שאמרה אי איפשי בקידושין שקדשני אמי ואחי וכן אמר לקמן גבי קטנה שעמדה ונתקדשה לאחר דנישואין הם מיאוניה דאיקדישא מעיקרא או דאינסיבא מעיקרא אלמא כיון דאיקדישא מעיקרא בלחוד צריכה מיאון והרמב\"ן ז\"ל הראה פנים להעמיד דברי הרב ז\"ל דכל הני דמוכחן דארוסה צריכה למאן דוקא כשקבלה היא קידושיה אבל כשקדשוה אמה ואחיה אפי' לדעתה אינה מקודשת כלל ואינה צריכה מיאון לפי שלא מצינו שתקנו חכמים שליחות לקטן אבל כשהכניסוה לחופה לדעתה אף ע\"פ שקבלו הם הקידושין צריכה למאן והיינו דקתני מתני' שהשיאתה אמה או אחיה ולא קתני שקדשתה והיינו נמי דאמר רבי חנינא בן אנטיגנוס כל שאינה יכולה לשמור קידושיה אינה צריכה למאן דמשמע שהיא מקבלת אותם וכשהיא מקבלת אותם ויודעת לשמור צריכה מיאון בפירוש בקידושין שקדשוני אמי ואחי כלומר הם פתוני לקבל הקידושין וכן כתבו בשמו הרשב\"א והריטב\"א ז\"ל:","\u0003ומ\"ש ולעיל בהלכות קידושין פירשנו דין קטנה שנישאת שלא לדעת אביה אם צריכה מיאון בסימן ל\"ז:\u0004 כתב הרמב\"ם בפי\"א מהלכות גירושין אי זו היא קטנה שנישאת שצריכה למאן מבת ו' עד בת י' בודקין אותה לפי יופי דעתה אם יודעת לשמור קידושיה ושהן קידושין לא שתשמור אותן כדרך שמשמרת האגוז ותמרה וכיוצא בהם הרי זו צריכה מיאון ואם אינה יודעת לשמור קידושיה אינה צריכה למאן אלא הולכת לבית אמה כאילו לא נתקדשה לעולם ופחותה מבת ו' אפי' יודעת לשמור אינה צריכה מיאון ויתירה על בת עשרה אפילו סכלה ביותר צריכה מיאון וכל מי שהשיאוה אחיה או אמה או קרוביה שלא לדעתה אינה צריכה למאן עכ\"ל ובסימן מ\"ג נתבאר טעמו ושם נתבאר שיש חולקין עליו בקצת דברים אלו וכתב נ\"י בפרק ב\"ש אהא דתנן רבי חנינא בן אנטיגנוס אומר כל תינוקת שאינה יכולה לשמור קידושיה אינה צריכה למאן פירש\"י שאינה מבחנת בין קידושין לדבר אחר והקשו עליו מדאמר רבא בפרק התקבל (גיטין סה.) הפעוטות מקחן מקח וממכרן ממכר במטלטלטלין וכנגדן בקטנה מתקדשת למיאון אלמא דקודם לכן אינה מתקדשת למיאון לכך פירש הכא שיכולה לשמור קידושיה היינו שיכולה לשמרם במקחה וממכרה שלא תתאנה והיינו שהגיעה לעונת הפעוטות והריטב\"א תירץ לפי פירוש הראשון דהכא קאי ארישא שנתקדשה ע\"י אחיה ולהכי סגי לה בשהגיעה שיודעת להבחין בין קידושין לדבר אחר וההוא דהתם בשנתקדשה ע\"י עצמה ובעיא שתהי' כפעוטות עכ\"ל. כתב הרשב\"א בתשובה חייא סי' אלף ר\"ג דקטנה והיא חרשת נמי ממאנת דלא פלוג רבנן בין פקחת לחרשת לענין מיאון:","והמיאון הוא שתאמר אי אפשי בפלוני בעלי ואי אפשי בקידושין שקדשוני אמי ואחי ברייתא שם (דף קח.) ונראה דאו או קתני דבין שאמרה אי אפשי בפלוני בעלי בין שאמרה אי אפשי בקידושין שקדשוני אמי ואחי באיזה מהם שתאמר הוי מיאון וכן משמע לישנא דברייתא וכך מבואר בדברי הרמב\"ם ז\"ל:","ומ\"ש ואפילו לא מיאנה אלא שנתקדשה לאחר אינה צריכה מיאון אחר ומבטלת מעשה הראשון אפילו אם היתה נישאת כבר ברייתא שם קטנה שלא מיאנה ועמדה ונתקדשה משום ר\"י בן בתירא אמרו הן הן מיאוניה ואסיקנא דהלכה כר\"י בן בתירה ואפי' בנישואין דקמא:","וממאנת בין מן האירוסין בין מן הנישואין אפי' שלא בפני הבעל ושלא בפני ב\"ד שם פלוגתא דב\"ש וב\"ה במתני' (קז.) והלכה כב\"ה דאמרי דבכל גווני הוי מיאון:","ומ\"ש רק שיהיה בפני שנים שיעידו על הדבר שם בברייתא ב\"ש אומרים בפני ב\"ד ובה\"א בפני ב\"ד ושלא בפני ב\"ד ואלו ואלו מודים שצריך ג' ר\"י ב\"ר יהודה ור\"א בר\"ש מכשירים בשנים אמר רב יוסף בר מניומי אמר רב נחמן הלכה כאותו הזוג וכתבו התוס' מכשירין בב' ה\"ה בחד אלא שצריך לעדות שמיאנה: ומ\"ש בשם ר\"ח כן כתבו התוס' בשמו משום דמכשירין דיעבד משמע וז\"ל ה\"ה יש מי שכתב דלכתחילה בעינן ג' ואין כן דעת רש\"י ודעת רבינו ועיקר וכתב נ\"י שכתב הרשב\"א על דברי ר\"ח נראה מדבריו דאפילו דיעבד דוקא בשנים אבל בפני אחד אפילו דיעבד לא ואין נראה כן מדברי רש\"י שפי' לקמן אפילו שגרה בעלה אצל החנוני אין לך מיאון גדול מזה כלומר דאלמא אפילו בפני אחד מיאונה מיאון עכ\"ל:","\u0003וממאנת כל זמן שהיא קטנה אפילו ד' וה' פעמים וכו'\u0004 וכשם שממאנת נבעל כך ממאנת ביבם אם מת הבעל ולא מיאנה בו שם במשנה פלוגתא דב\"ש וב\"ה והלכה כב\"ה דאמרי הכי:","והשנים שמיאנה בפניהם נותנין לה גט מיאון וחותמין לה ואינו כגט גירושין להיות נתינתו מגרשת לפיכך א\"צ לא כתיבה לשמה ולא מסירה ולא דבר ממשפטי הגט ואין כותבין בו טופס הגט שלא יראה כגט גמור ואתי לאיחלופי בגט כל זה מדברי הרמב\"ם בפי\"א מה' גירושין וטעמו מדאמר בפרק ב\"ש (שם:) בראשונה היו כותבין גט מיאון לא רעינא ביה ולא צבינא ביה ולית אנא בעיא להתנסבא ליה כיון דחזי דנפיש דיבורא אמרי אתו לאיחלופי בגיטא תקינו הכי ביום פלוני מיאנה פב\"פ באנפנא ופירש\"י אתי לאיחלופי בגיטא. שיכתבנו סופר בו בגט גירושין לגרש בו אשה וה\"ה כתב דילמא אתי לאחלופי בגיטא ויבואו לאסור קרובות:","\u0003וזהו נוסחו בכך וכך בשבת וכו'\u0004 נוסח זה כתב הרמב\"ם בפרק הנזכר שהוא מנהג ישראל וכתב ה\"ה ראיתי בעיטור מוסיף ויהיבנא לה למהך להתנסבא לכל גבר דתצבי ואיניש לא ימחה בידה מן יומא דנן ולעלם ע\"כ ונוסח רבינו עיקר לפי שנוסח זה הוא בגט ואתי לאיחלופי דהשתא כנפיש דיבורא אמרו בגמרא דאתי לאיחלופי כ\"ש לכתוב בו לשונות הגט עכ\"ל:","ואלו שממאנת בפניהם צריכין שיכירו אותה ואת בעלה לפיכך כל מי שיראה שמיאנה בפני שנים יכול לכתוב לה גט מיאון להתירה אע\"פ שאינו מכירה וכו' פלוגתא דאמוראי בס\"פ מצות חליצה (קז.) ופסקו הפוסקים הלכה כרבא דאמר אין ממאנין אא\"כ מכירין לפיכך כותבין אע\"פ שאין מכירין ומפרש רבינו שצריך שיכירו אותה ואת בעלה וכך הם דברי הרמב\"ם וה\"ה כתב אבל הרשב\"א כתב אא\"כ מכירין את האשה אע\"פ שאין מכירין הבעל ודאי ממאנין דמאי איכפת לן בבעל אפילו אין זה בעלה הרי יכולה למאן שלא בפניו ומה לה לשקר שלא בפניו תמאן עכשיו בכל מקום שהוא אלא ההקפדה בהכרת האשה דלמא מסקה שמה כשם אותה קטנה עכ\"ל ומסתברא לי דשמא יש לחוש דילמא איכא קטנה דשמה כשמה ואיהי מסקה שם בעלה כשם בעלה של אותה קטנה ואע\"ג דלרב יוסף לא חיישינן אא\"כ הוחזקו ה\"מ בגברי גדולים דשמם נפיק להו ואם איתא דהוי קלא אית להו אבל בנשי קטנות איכא למיחש אבל לשם בעלה בשם בעלה ושמה כשמה לכולי האי לא חיישינן ומכירין שהזכירו במיאון משמע דומיא דמכירין דחליצה מה בחליצה צריך שיכירו שניהם אף במיאון כן כנ\"ל לדעתו ז\"ל עכ\"ל וכך הם דברי הר\"ן בתשובה סימן ו' וסיים בה וכ\"ת בהיא גופא מאי איכפת לן נ\"ל בהאי חששי טובא איכא דשמא יש קטנה בעיר שהשיאוה אמה ואחיה ותגדל וגדלי קדושיה בהדה ורמאי אחד פתה קטנה שאין אנו מכירין יחליף שמה בקטנה הראשונה ואם יהיה ביד הקטנה השנייה גט מיאזן ילך הרמאי ויפתה הקטנה הראשונה אחר שגדלה אצל הראשון שתנשא לו שיתן לה אותו גט מיאון ותאמר כבר מיאנתי בבעלי קודם שגדלתי אצלו אי נמי דילמא מתה לה ההיא קטנה ומדינא בעל ירית לה ומפקי האי גיטה דכבר מיאנה וקרובים ירתי לה כל אלו החששות הן כשאין מכירין הקטנה אבל כשמכירין אותה אע\"פ שאין מכירין הבעל מאי איכפת לן הא קי\"ל בפרק ב\"ש דממאנת בפניו ושלא בפניו הילכך כיון שאמרה הריני ממאנת בפלוני בעלי אין כאן בית מיחוש ואע\"פ שהרמב\"ם הצריך שיהו מכירין אותה ואת בעלה שמיאנה בו יש להעמידה כגון שבאה ואמרה הריני ממאנת באיש זה שאין לכתוב שמיאנה בבעלה סתם אא\"כ מכירין אבל אמרה הריני ממאנת בראובן למאי ניחוש לה ואפשר ג\"כ שהרב ז\"ל החמיר בבעלה לכתחילה אבל דיעבד כיון שהכירו האשה כשר עכ\"ל: \u0005ב\"ה ובעיקר הדין אני תמיה למה אנו מחזיקים שאותה שמיאנה בפניהם מכירים אותה שהרי אפשר שתמאן בפני אורחים כדאיתא בגמרא וכדברי הרמב\"ם ואינם מכירה ותו אטו דכ\"ע דיני גמירי שאין ממאנין אא\"כ המכירים אותה ואפשר דאורחא דמילתא מסתמא שאינה ממאנת אלא בפני המכירים אותה:\u0006 קטנה שבאה למאן ועדים המעידים שהיא קטנה אינם מצויים כאן ואמה או קרוביה אומרים לב\"ד תמאן עכשיו בפניכם ותכתבו לה באיזה יום מיאנה ותתנו לה ואם תביא אח\"כ עדים שביום שמיאנה היתה קטנה תתירוה להינשא למי שתרצה ואם לא תביא עדים הנזכר תשאר בחזקת נשואה נראה שאין ב\"ד רשאין לעשות כן ואפילו להעיד שתמאן בפניהם אינם רשאים ואפילו לא יכתבו לה וראיה מדאמרינן אין ממאנין אא\"כ מכירין וכו' לפיכך כל מי שיראה שמיאנה בפני שנים יכול לכתוב לה גט מיאון להתירה אע\"פ שאינו מכירה וכו' משמע דאין אחר מיאון שבפני שנים כלום וכן יש ללמוד ממה שכתב רבינו בטוח\"מ בסימן ר\"ה בשם רבינו יונה בענין מסירת מודעה:","קטנה שממאנת אין לה כתובה מנה או מאתים אבל יש לה תוספת ואין לה מזונות ופירות וכו' משנה וגמרא ס\"פ אלמנה ניזונת (כתובות דף ק: קא.):","\u0003ומ\"ש כגון שהלך בעלה למדינת הים ולוותה ואכלה וכו'\u0004 אבל בעודה תחתיו חייב לזונה ולפדותה ברייתא בפרק שני דייני גזירות (כתובות דף קז:) לענין מזונות וכתב הרא\"ש בס\"ת אלמנה ניזונת דה\"ה לפירות:","ומ\"ש וכן אם יוצאה במיאון והוא ליקט פירות אפי' הם מונחים בעין הוא נוטלן כ\"כ התוס' והרא\"ש ז\"ל בס\"פ אלמנה ניזונת וכבר נתבאר כל זה בסימן מ\"ג ובסימן קט\"ו:","\u0003ומ\"ש ונכסים שהכניסה לו וכו'\u0004 זה פשוט ומיהו מ\"ש שאם אינם בעין צריך לשלם בנכסי מלוג היינו דוקא כשאבד הוא הא לאו הכי לא דהא תנן יבמות (סו.) בעבדי מלוג אם מתו מתו לה :","ומ\"ש ומותרת בקרוביו וכשרה לכהונה משנה בפרק ב\"ש (יבמות דף קח.):","ומ\"ש ואינה צריכה להמתין שלשה חדשים מלהנשא מימרא דשמואל סוף פרק ד' אחין (יבמות דף לה.) וסוף פרק אלמנה ניזונת (דף ק\"ז:):","\u0003ומ\"ש ואם נישאת לאחר וגירשה או מת מותרת לחזור לראשון וכו'\u0004 משנה בפרק ב\"ש (יבמות דף קח.):","ומ\"ש וקטנה שנתגרשה יש לה כתובה בס\"פ אלמנה ניזונת (דף קח:) פלוגתא דרב ושמואל ופסקו הפוסקים הלכה כשמואל דאמר ממאנת אין לה כתובה אבל יוצאה בגט יש לה כתובה. ומ\"ש ואסורה לקרוביו ואסורה לכהונה וכן מ\"ש אבל גירשה והחזירה בעודה קטנה ומיאנה בו ונישאת לאחר אחר שמיאנה בזה וגירשה השני מותרת לחזור לראשון וכו' אבל אם מיאנה בראשון ואחר כך החזירה וכו' הכל במשנה פ' ב\"ש (יבמות ד' קח):","\u0003ומ\"ש אע\"פ שיוצאה מן השני במיאון וכו'\u0004 שם פלוגתא דאמוראי ופסקו הפוסקים כרב דאסר:","הממאנת ביבם אסורה לאביו מפני שנראית לו ככלתו בשעה שמת בנו אבל מותרת בשאר קרוביו (שם ד' קו: ) תני רמי בר יחזקאל מיאנה בבעל מותרת לאביו ביבם אסורה לאביו ומפרש טעמא משום דבשעת נפילה נראית ככלתו. ומ\"ש לפיכך אם מיאנה באחד מהיבמים מותרת לשאר האחים שם אמר רב מיאנה בזה אסורה לזה מידי דהוה אבעלת הגט בעלת הגט כיון דאיתסר לה לחד לא איתסר לה לכולהו ה\"נ ל\"ש שמואל אמר מיאנה בזה מותרת לזה ולא דמיא לבעלת הגט בעלת הגט הוא דקא עביד בה הכא היא עבדה ביה דאמרה ליה לא רעינא בך ולא צבינא בך בך הוא דלא רעינא הא בחברך רעינא ופירש\"י בעלת הגט אם נתן לה האחד גט פסלה על כולם וכתבו הרי\"ף והרא\"ש הילכתא כשמואל דקאי ר' יוחנן כוותיה וכן פסק הרמב\"ם בפי\"א מהל' גירושין ול' רבינו שכתב לפיכך אינו מכוון יפה דהא הני תרי דיני לא תלוי הא בהא: \u0005(ב\"ה) והרי הרמב\"ן והרשב\"א שאוסרים בשאר קרובים כמו באב ומתירים בשאר האחים.\u0006 וכתב נ\"י בשם הריטב\"א דכיון דמהאי טעמא הוא שנראית בשעת נפילה כאשתו של ראשון דוקא לקרובי המת היא נאסרה אבל לא לקרובי היבם דהא פקעה מיניה בלא כלום אבל הרב רבינו משה מיימון ז\"ל כתב שמותרת לשאר קרובים כמו שהיא מותרת לשאר האחים כשמיאנה באחד מהיבמים וכתבו עליו דאינו מחוור דטעמא דשריא לשאר האחין היינו משום דלא דחייה נפשה מכולה בית אלא מזיקתו של זה ועדיין נראית כאשת המת הילכך שריא לאחים משום ייבום אבל לשאר הקרובים ודאי אסורה כשם שהיא אסורה לאב וגדולה מזו כתב הרי\"ף לקמן שהממאנת באחי אמו אסורה לו משום שנראית בשעת מיתה כאשת אחי אמו ואע\"פ שאינה לזה אלא שנייה של דבריהם וכ\"ש לשאר הקרובים שהיא ערוה להם דבר תורה וכ\"כ בעל הלכות כדברי הרי\"ף אע\"פ שיש מי שנ\"ל שאין ראיה מאשת אחי אמו עכ\"ל וגם ה\"ה כתב שהרמב\"ן והרשב\"א חלקו על הרמב\"ם וכתבו דכי היכי דאסורה לאביו ה\"נ אסורה לקרובים אחרים וכתב עוד ודע שאפילו לדעת רבינו אם לא נשאר שם יבם אחר מיתה אינה יכולה למאן והרי היא אסורה בקרוביו וכתב עוד שם אמרו שאם היתה אשת אחי אמו שהיא שנייה לו ונשאה אחיו מאביו אינה ממאנת עכשיו לעקור נישואין הראשונים כדי שתתייבם וכן פסקו בהלכות ופירשו דאע\"ג דקי\"ל דיש מיאון אחר מיתה כמו שנתבאר שהיא ממאנת ביבם הכא בשנייה לא לפי שבשעת מיתת אחי אמו נראית כאשת אחי אמו. ולמדנו שיש שניות ג\"כ בנישואי קטנה תמהני למה לא כתב דין זה באשת אחי אמו בהלכו' ייבום עכ\"ל:","עד מתי הבת ממאנת עד שתביא ב' שערות משנה בפרק בא סימן (נדה דף נב:) ואע\"ג דפליג התם ר' יהודה ואמר עד שירבה השחור ואיכא אמוראי בגמרא דסברי דהלכתא כוותיה כתבו הרי\"ף והרא\"ש דלא קיי\"ל כוותיה דגרסי' בפ' מי שמת (בבא בתרא דף קנו.) למיאונין לאפוקי מדר' יהודה דאמר עד שירבה השחור:","ומ\"ש או עד שתלד שאם ילדה חשובה כגדולה בפ\"ק דיבמות (דף יב) תני רבה בר שמואל דאי אתה יכול לומר בחמותו שהיא ממאנת וקאמר רב ספרא בגמרא דבנים הרי הם כסימנים ופירש\"י הילכך אין לך יולדת ממאנת אפילו היא קטנה וכתב רבינו ירוחם שכן פסק הרמ\"ה וכתב שי\"מ שלפעמים תלד בלא סימנים והוי לפי זה אם ילדה ולא נמצאו לה סימנים הוי ספק גדולה וכן פירשו בתוספות ואינה יכולה למאן מכל מקום לענין קידושין ועונשין הוי ספק גדולה עכ\"ל ועיין בדברי הרמב\"ם וה\"ה בפ\"ב מה\"א :","ומ\"ש אבל כל זמן שלא ילדה ולא הביאה ב' שערות יכולה למאן עד שתהא בת כ' שנה שכל זמן שאינה בת כ' ולא הביאה ב' שערות חשובה כקטנה אפילו נולדו בה סימני איילונית וכו' בס\"פ יוצא דופן (נדה דף מז:) תנן בת כ' שנה שלא הביאה ב' שערות תביא ראיה שהיא בת כ' והיא איילונית לא חולצת ולא מתייבמת וכן בן כ' שנה שלא הביא ב' שערות יביא ראיה שהוא בן כ' והוא הסריס לא חולץ ולא מייבם ובגמרא שם ורמינהו אחד לי בן ט' שנים ויום אחד ואחד לי בן כ' שנה שלא הביא ב' שערות אמר רב שמואל בר רב יצחק אמר רב והוא שנולדו בו סימני סריס עד כמה תני ר' חייא עד רוב שנותיו ואיתא נמי להא בס\"פ האשה רבה (יבמות דף צז.) ופי' רש\"י והוא שנולדו בו וכו' הא דקתני דחשבינן ליה כגדול כגון שנולדו לו סימני סריס דמוכחא מילתא דהאי דלא מייתי משום דסריס הוא אבל כל כמה דלא חזינן ביה סימני סריס תלינן בקטנות עד כמה נדון כקטן ואע\"ג דגבי סריס הוא דאיתמר הכי משמע דה\"ה לאיילונית וכך הם דברי הרמב\"ם בפ\"ב מה\"א וז\"ל הגיעה לי\"ב ויום א' ולא הביאה ב' שערות אע\"פ שנראו בה סימני איילונית עדיין קטנה היא עד כ' שנה וכשהביאה ב' שטרות אפי' בשנת כ' תהיה נערה ו' חדשים ואח\"כ תקרא בוגרת היתה בת כ' שנה פחות ל' יום ולא הביאה ב' שערות ונראו בה סימני איילונית הרי היא איילונית ואם לא נראו בה סימני איילונית עדיין קטנה היא עד שתביא ב' שערות או עד שתהיה בת ל\"ה שנה ויום אחד הגיעה לזמן הזה ולא הביאה ב' שערות הרי זו נקראת איילונית אע\"פ שלא נראה בה סימן מסימני איילונית עכ\"ל. ומ\"ש עד ל\"ה שנה מבואר שהוא מדתני ר' חייא עד רוב שנותיו ומשום דימי שנותינו שבעים שנה כל שהוא יותר על ל\"ה אפילו יום אחד מיקרי רוב שנותיו: כתב ריב\"ש בסימן ק\"ט הנה נתבאר שאף בן כ' שלא הביא ב' שערות שעדיין קטן הוא עד שיביאם או שיולדו לו סימני סריס אמנם יש הפרש בין הבאת ב' שערות לסימני סריס דבהבאת ב' שערות אינו נעשה גדול למפרע אלא משעה שיביאם ואילך ובסימני סריס אם בן כ' נעשה גדול למפרע מבן י\"ג שנה ויום אחד לפי שעתה נתברר שהיא סריס ממעי אמו ומה שלא הביא ב' שערות היה בסבת זה והא דבעיא שתי שערות זהו במי שעתיד להביאם אבל זה שהוא סריס ממעי אמו ואינו עתיד להביאם הרי הוא גדול מי\"ג שנה ויום אחד כי כ\"כ רמ\"ה ז\"ל עכ\"ל ורבינו כתב דברים אלו בטוח\"מ סימן רל\"ו:","\u0003ומ\"ש בשם הרמב\"ם היתה בת כ' פחות ל' יום וכו'\u0004 הוא בפ\"ב מהל' אישות וטעמא מדתניא בס\"פ יוצא דופן (נדה דף מז:) שנת עשרים שיצאו ממנה ל' יום הרי הוא כשנת כ' לכל דבריו ומפרש ז\"ל דהיינו לומר שעתידים לצאת ממנה ל' יום דכיון דאינה חסרה אלא ל' יום הרי הוא כאילו נשלמה ומ\"ש עליו רבינו דט\"ס הוא טעמו משום דלישנא דיצאו ממנה שלשים יום משמע ודאי דלא עברו ממנה אלא ל' יום שנמצאת שהיא בת י\"ט שנה ול' יום חשובה כבת כ' דל' יום בשנה חשובים שנה ולא לומר שלא נשאר משנת עשרים אלא ל' יום כדמפרש הרמב\"ם דההוא לאו שיצאו מיקרי דהא הנהו ל' יום עדיין לא יצאו וה\"ה ג\"כ כתב שכל המפרשים פירשו דהיינו לומר שאע\"פ שלא נכנסה בשנת כ' אלא ל' יום חשובה כבת כ' וכמו שפי' רבינו ושכן נראה עיקר וכן הוא דעת הראב\"ד בהשגות:","\u0003ומ\"ש וסימני איילונית יתבאר לקמן בהלכות ייבום הוא בסימן קע\"ב:\u0004 ","אין שתי שערות סימן גדלות אא\"כ באו מי\"ב שנה ואילך אבל אם באו קודם לכן אפי' תוך שנת י\"ב חשיבי כשומא ואינה נחשבת גדולה על ידם וכו' בפרק יוצא דופן (נדה מז:) איפליגו אמוראי תוך זמן אי הוי כלפני זמן או כלאחר זמן ואסיק רבא הילכתא תוך זמן כלפני זמן וכתב הרא\"ש ע\"ז ואינה גדולה עד שתביא ב' סימנים מי\"ב שנה ואילך ואם נראו בה שערות קודם י\"ב שנה אינה גדולה עד שתביא ב' שערות אחרות משתהא בת י\"ב ונראה שטעמו מדאמרינן בפרק בא סימן (עח:) בשלמא לפני הפרק בעיא בדיקה דאי משתכחי לאחר הפרק שומא נינהו ומשמע מדברי רבינו דלגמרי קאמר דשומא נינהו ואפי' לענין מיאון שאם אחר י\"ב לא הביאה שערות אחרות אלא אותם שהביאה בתוך י\"ב אע\"פ שעודם עליה ממאנת דשומא נינהו אבל רש\"י פירש דאי משתכחי לאחר הפרק שומא נינהו ולא חלצה וכתבו התוספות שהדין עמו דליכא לפרושי שומא נינהו ותמאן דהא קתני בסיפא דאינה נאמנת לומר קטנה היא ותמאן ומדברי הרמב\"ם נראה כדברי רבינו שסתם וכתב בפ\"ב מה' אישות הבת שהביאה ב' שערות בתוך י\"ב שנה וכן הבן שהביא בתוך י\"ג שנה שניהם שומא אע\"פ שאותם שערות במקומן הן עומדות לאחר י\"ג לזכר ואחר י\"ב לנקבה אינו סימן וכתב ה\"ה שם בשם הרמב\"ן דקטנה שלא נודעה אם הגיעה לכלל שנותיה והביאה סימנים לא מצינו בגמרא דינה מפורש וי\"א שמטילין אותה לחומרא כדין כל שאר הספיקות עכ\"ל ומה שכתב ומיהא כשמוצאין לה שערות אחר הזמן מחזיקין לה לגדולה ואפי' לחליצה ולא חיישינן שמא באו קודם הזמן כ\"כ הרמב\"ם בפרק הנזכר וכן משמע מהא דפרק בא סימן שכתבתי בסמוך דקאמר לפני הפרק בעיא בדיקה דאי משתכחי לאחר הפרק שומא נינהו משמע בהדיא דהיכא דלא בדקוה לפני הפרק כי משתכחי אחר הפרק לא חיישינן שמא לפני הפרק באו דאל\"כ אמאי בעיא בדיקה לפני הפרק משום דאי משתכחי לפני הפרק אמרינן שומא נינהו הא בלא נבדקה נמי אמרינן שומא נינהו אלא ודאי כדאמרן וכ\"כ התוס' שם. ומ\"ש ואפי' נשים נאמנות לומר שהביאה ב' שערות אחר י\"ב פלוגתא דתנאי ר\"פ בא סימן (נדה דף מח:) ופסק הרא\"ש הלכה כמ\"ד דנבדקת ע\"פ נשים בין להקל בין להחמיר וכן פסק הרמב\"ם בפ\"ב מה' אישות וז\"ל כשבודקין הבת בין בתוך זמן שהוא כל שנת י\"ב בין קודם זמן זה בין לאחר זמן בודקין ע\"פ נשים כשרות ונאמנות ואפי' אשה אחת בודקת ושומעין לה אם הביאה ואם לא הביאה וכתב ה\"ה שכן הסכימו הרמב\"ן והרשב\"א ז\"ל כתב המרדכי בפרק מצות חליצה מ\"כ שהשיבו לרבינו משולם כיון דנשים אינן ראויות להעיד והכא מהימני מה לי קרובות מה לי רחוקות ורפיא בידי שוב מצאתי בספר אבי\"ה ור\"ת פסק אפי' הנשים שאין נאמנות לומר מת בעלה נאמנות בבדיקה דאין לך כתב מוכיח גדול מזה דעביד לאיגלויי וכ\"פ ראבי\"ה דאנשים קרובים בודקין את החולץ ונשים קרובות בודקים אותה ע\"כ אם נשים נאמנות לומר שהממאנת היא בת י\"א וכן אם אמה נאמנת במספר שנותיה בתשובת המיי' דשייכי לספר נשים ובמרדכי פרק אלמנה לכה\"ג ומתחיל מצות חליצה ואכתוב בזה בסימן קס\"ט. ומ\"ש בשם ר\"ת שאם הביאה ב' שערות ביום האחרון של שנת י\"ב חשיב שפיר גדולה בפרק בא סימן אהא דתניא ר' יהודה אומר לפני הפרק ולאחר הפרק נשים בודקות אותן תוך הפרק אין נשים בודקות אותן שאין משיאין ספיקות ע\"פ נשים רש\"א אף תוך הפרק נשים בודקות אותן ונאמנות נשים להחמיר אבל לא להקל כתבו התוס' והרא\"ש קשה לר\"ת על כל הני דמפרשי דתוך הפרק ותוך זמן חדא מילתא נינהו חדא אמאי קרי ליה לעיל תוך זמן והכא קרי ליה תוך הפרק ועוד דפרק משמע סמוך לגדלות ממש ופי' ר\"ת דפליגי ביום אחרון של שנת י\"ב לנקיבה וי\"ג לזכר ואותו יום קרוי תוך הפרק לר' יהודה הוי זמן הבאת ב' שערות מתחלת היום ולר\"ש בסוף היום והלכה כר' יהודה ע\"כ ואין כן דעת הרמב\"ם ז\"ל שבהדיא כתב בפ\"ב מהל' אישות אם הביאה ב' שערות והיא מבת י\"ב שנה ויום אחד ולמעלה נקראת נערה ובתשובות הרשב\"א סי' אלף ורי\"ו כתוב על אשה שנסתפקו במספר שנותיה ונתקדשה ונבדקה ולא מצאו לה סימנים איפשר שגם בזו אנו חוששים שמא נשרו אלא שיש להתישב בזה לפי שיש לומר בזה ב' ספיקות ספק הגיעה לכלל שנותיה ספק לא הגיעה ואפי' ת\"ל הגיעה ספק הביאה סימנים ונשרו ספק לא הביאה וכל ספק ספיקא אפי' בשל תורה לקולא ואפ\"ה איני רואה בזה להקל כי יש עוד להתיישב בדבר עכ\"ל :","\u0003ושתי שערות אין צריך שיהיה לכל אחד גומא וכו'\u0004 וכן ג\"כ אם יש לה שתי גומות אפי' בלא שערות חשובה גדולה בפרק בא סימן (נדה דף נב:) אמר רב הונא שתי שערות שאמרו צריך שיהיה בעיקרן גומות רב מלכיו אמר רב אדא בר אהבה גומות אע\"פ שאין שערות אמר רב אשי אמר לי מר זוטרא קשה בה רב חנינא מסורא לא לישתמיט תנא לאשמועינן גומות אי אשמועינן גומות ה\"א עד שיהיו ב' שערות בב' גומות קמ\"ל דאפילו ב' שערות בגומא אחתוז\"ל הרמב\"ם בפ\"ב מה' אישות ב' שערות צריך שיהא בעיקרן גומות ואפילו שתיהן בגומא אחת הרי אלו סימן נמצאו ב' גומות זו בצד זו ואין בהם שיער הרי אלו סימן חזקה אין גומא בלא שיער שערות היו בהם ונשרו וכתב ה\"ה דעת רבינו דרב הונא ורב מלכיו לא פליגי אהדדי וכן נראה שם ע\"כ: \u0005ב\"ה כתב רבינו בסימן קס\"ט אם יש להם ריבוי שערות או שהן ארוכות חזקה שבאו לכלל שנים וע\"ז סומכים שא\"צ לבדוק אם יש בהם גומות דאע\"ג דקי\"ל שצריך שיהיו בעיקר גומות אם יש ריבוי שערות או שהן ארוכות א\"צ לבדוק על הגומות: \u0006וקאמרי חכמים שצריך שיהיו ב' שערות במקום אחד ור' ישמעאל אומר אפי' אחד בגבה ואחד בכריסה וכו' שם א\"ר יהודה אמר שמואל ב' שערות שאמרו אפי' אחד על הכף ואחד על הביצים תנ\"ה שתי שערות שאמרו אפי' אחד בגבה וא' בכריסה אחד ע\"ג קשרי אצבעותיה של יד וא' ע\"ג קשרי אצבעותיה של רגל דברי רבי שמעון בן יהודה איש כפר עכו שאמר משום ר\"ש ורבנן אמר רב חסדא עד שיהא ב' שערות במקום א' ופירש\"י על הכף. גובה שעל האבר למטה מן הכרס: אפי' אחד על הכף וכו'. ואע\"ג דאינן במקום אחד: אחת בגבה. תחת אותו מקום: בין קשר אצבע אינה מביאה שיער עד שתגדיל והרי\"ף הביא סוגיא זו בס\"פ ב\"ש ופסק שם הלכה כרבנן וכן פסק הרמב\"ם ז\"ל בפ\"ב מה\"א וכתב ה\"ה מפרש רבינו שמקום אחד הוא בית הערוה בדוקא אבל קצת המפרשים פירשו דרבנן לא נחלקו אלא שיהיו במקום אחד אבל כיון שהם במקום אחד אפי' בקשר אצבעות יד או רגל הן סימן אבל ודאי גבה וכריסה הכל הוא בערוה וגבה מקום תפוח שעל הערוה וכריסה שפתי הערוה אבל גבה וכריסה ממש ודאי אין מועילין אלו דבריהם ז\"ל ולזה השכימו הרמב\"ן והרשב\"א ז\"ל עכ\"ל: \u0005ב\"ה וזה לשון הרמב\"ם בפ\"ג מהל' אישות ב' שערות צריכות שיהיו במקום הערוה וכולי וצריכות להיות במקום אחד דקאסר שאם וכו' וכתוב שם בכסף משנה :\u0006","\u0003ומ\"ש רבינו ור\"י פסק כדברי שניהם להחמיר וכו'\u0004 כ\"כ שם הרא\"ש בשם ר\"י והתוס' כתבו כן בשם ר\"ת ונראה מדבריהם דטעמא משום דגבי שיעור ב' שערות אסיקנא הלכה כדברי כולם להחמיר וכדבסמוך משמע להו ז\"ל דבהאי פלוגתא נמי הוי דינא הכי וכתבו עוד שם התוס' בשם ר\"ת דמשהגיעה לכלל שנותיה לא תמאן בזמה\"ז דאע\"ג דהיכא דלא בעל פסקינן בפרק יוצא דופן דלא חיישינן שמא נשרו אין אנו בקיאין לבדוק בכל גופה שלא יהא לה שערות דאפי' א' בגבה ואחת בכריסה ובקשרי אצבעותיה מצטרפין או גומות גרידא עכ\"ל וכבר הזכיר רבינו סברא זו לקמן בסמוך בשם ספר התרומות ומ\"ש רבינו שמסקנת הרא\"ש ז\"ל כדברי ר\"י איני רואה הכרע בדברי הרא\"ש לכך:","\u0003ולענין שיעור אורך השערות פליגי בהו תנאי וכו'\u0004 במשנה בפרק הנזכר (שם) ואיפסיקא בגמרא הלכה כדברי כולם להחמיר ומ\"ש רבינו משיהיו נקרצות בציפורן לא תמאן וכו' כן פי' רש\"י והרא\"ש ז\"ל ומ\"ש בשם הרמב\"ם הוא בפ\"ב מה\"א:","ומ\"ש ויראה מדבריו שהוא קודם קריצתן בציפורן כלומר שנראה מדברי הרמב\"ם ז\"ל שסובר שניטלות בזוג הוא השיעור המועט שבכולן וכן כתב ה\"ה ופשוט הוא:","במה דברים אמורים שיכולה למאן אחר י\"ב שנה שבדקו אותה ולא הביאה שערות אבל סתמא משיש לה י\"ב שנה אינה יכולה למאן וכו' ובד\"א שיכולה למאן כשבודקין אותה ולא הביאה כשלא בעל אחר היות לה י\"א שנה ויום אחד וכו' בפ' יוצא דופן (נדה דף מ\"ו.) אמר רבא קטנה כל י\"ב שנה ממאנת והולכת מכאן ואילך אינה ממאנת ואינה חולצת הא גופא קשיא אמרת ממאנת אלמא גדולה היא אי גדולה היא תחלוץ וכ\"ת מספקא ליה והאמר רבא קטנה שהגיע לכלל שנותיה אינה צריכה בדיקה חזקה הביאה סימנים הני מילי בסתמא אבל היכא דבדקו ולא אשכחו לא א\"ה תמאן חוששין שמא נשרו הניחא למ\"ד חוששין אלא למ\"ד אין חוששין מאי איכא למימר ה\"מ לענין חליצה אבל לענין מיאון חוששין מכלל דמ\"ד חוששין חולצת והא חוששין בעלמא קאמר אלא לעולם דלא בדקה ולענין חליצה חיישינן וכי קאמר רבא חזקה למיאון אבל לחליצה בעיא בדיקה אמר רב דימי מנהרדעא הלכתא חוששין שמא נשרו וה\"מ דקדשה בתוך זמן ובעל לאחר זמן דליכא ספיקא דאורייתא אבל מעיקרא לא ופירש\"י אלא לעולם אינה ממאנת. דרבא בדלא בדקנוה הילכך מסתמא אמרינן כיון שהגיעה לכלל שנותיה ודאי אית לה ואינה צריכה בדיקה ובעיא גט ולענין חליצה חיישינן כלומר ולענין חליצה מ\"ה אינה חולצת דחיישינן שמא לא הביאה סימנין ודקא קשיא לך הא אמר רבא חזקה הביאה סימנים ל\"ק כי אמר רבא חזקה למיאון דלא ממאנת מסתמא אבל לחליצה בעיא בדיקה חוששין שמא נשרו ואם הגיעה לכלל שנותיה ובדקו ולא אשכחו לא ממאנת: דקדיש תוך זמן. יתומה מדעת אמה ואחיה לדעת': ובעל לאחר זמן. דאיכא ספיקא דאשת איש דאורייתא דבשעת בעילה דלאחר זמן שמא הביאה והו\"ל ביאה זו קידושין גמורים דהא גדלה ושוב אינה יוצאה במיאון: אבל מעיקרא. דמכי עברה שתא די\"ב ולא בעל לא חיישינן שמא נשרו דהא דלא הוו בה קידושין גמורים דאין מעשה קטנה כלום אא\"כ קיבל אביה קידושין הלכך מספיקא לא מחמרי עלה היכא דלא אשכחן אבל הביאה ודאי סימנים אף על גב דקידושין קמאי לא הוי קדושין אלא מדרבנן לא תיקנו רבנן מיאון בגדולה דילמא אתי למאן הנבעלת לאחר שגדלה דההוא הויא א\"א דביאה שבא עליה משגדלה מקדשה לה עכ\"ל: ומ\"ש שאם היה ידוע שהיה לה שערות קודם שבא עליה הוו קידושין גמורין שודאי בעל לשם קידושין ואם קדשה אחר אינה צריכה ממנו גט וכו' בפ' ב\"ש (יבמות דף קט.) איתמר קטנה שלא מיאנה והגדילה ועמדה ונשאת רב אמר אינה צריכה גט משני ושמואל אמר צריכה גט משני ואוקימנא להא דאמר רב אינה צריכה גט משני בשבעלה הראשון אחר שגדלה אצלו אבל אם לא בעלה אחר שגדלה אצלו קידושי קטנה לאו כלום הוא וצריכה גט משני ושמואל סבר אע\"ג דבעלה אחר שגדלה צריכה גט משני שכל הבועל על דעת קידושין הראשונים הוא בועל ואותבינן עליה דרב מהא דתניא המקדש את הקטנה קידושיה תלויין מאי קידושיה תלויין לאו דכי גדלה גדלי בהדה ואע\"ג דלא בעל ופריק לא מילתא דקטנה מיתלא תליא וקיימא אי בעל אין ואי לא בעל לא וכתב הרי\"ף ולא איפסיקא הכא הלכתא בהדיא וחזינן מאן דכתב דהא מילתא ספיקא היא ועבדינן בה לחומרא דהא תניא המקדש את הקטנה קידושיה תלויים ואף ע\"ג דשניין לה אשינויי לא סמכינן ואי לא בעל וגדלה ונתקדשה לאחר צריכה גט מזה ומזה והאי סברא סברא מעליא היא דגרסינן בהדיא בפרק יוצא דופן (נדה מו.) אמר רב דימי מנהרדעא הלכתא חוששין שמא נשרו וה\"מ דקדיש תוך זמן ובעל לאחר זמן דהויא ספיקא דאורייתא אבל מעיקרא לא כגון דקידשה ובעל תוך זמן ולא בעל אחר זמן לא חיישינן שמא נשרו אלא בדקינן לה אי אייתא ב' שערות אמרינן גדולה היא ולא ממאנת ואי לא אשכחן ב' שערות אמרינן עדיין קטנה היא ותצא במיאון משום דנישואי קטנה דרבנן נינהו והו\"ל ספיקא דרבנן ולקולא וש\"מ דקטנה שלא מיאנה אף על פי שלא נבעלה לאחר שגדלה אינה יוצאה במיאון אלא צריכה גט מדרבנן וכיון דמדרבנן הוא דצריכה גט תפסי בה קדושי שני וצריכה ממנו גט ומסתברא לן שאם רצה השני לכנסה שמגרש ראשון ונושא שני אבל מגרש שני ונושא ראשון לא גזירה דילמא אתי למימר מחזיר גרושתו מן האירוסין כדגזרינן בפ' המגרש (גיטין פט:) בההיא דלא מצאו דבר על בוריו ודוקא היכא דלא בא עליה קודם גירושי ראשון אבל בא עליה קודם גירושי ראשון אסורה לתרווייהו וצריכה גט מתרווייהו דהו\"ל כאשה שהלך בעלה למ\"ה שהיא אסורה לזה ולזה וצריכה גט מזה ומזה אבל ממזר לית בה דנישואי דרבנן נינהו ולא נישואי תורה. והיכא דבעל לאחר שגדלה קנאה קנין גמור מדאורייתא ואינה צריכה גט משני כרב וליתא לדשמואל דאמר כל הבועל על דעת הקידושין הראשונים הוא בועל דהא דתניא המקדש את הקטנה קדושיה תלויים מ\"מ הויא תיובתא דשמואל עכ\"ל והשתא מה שאמר רבינו שאם היה ידוע שהיה לה שערות קודם שבא עליה הוי קידושין גמורים שודאי בעל לשם קידושין ואם קידשה אחר אינה צריכה גט ממנו היינו כדפסק הרי\"ף הלכתא כרב וכן פסק הרמב\"ם ז\"ל. ומ\"ש וכיון שהוא ספק דאורייתא חיישינן שמא הביאה סימנים קודם שבעל וצריכה גט מספק היינו מאי דאסיקנא בפרק יוצא דופן (נדה דף מו.) הלכתא חיישינן שמא נשרו והני מילי דקדיש תוך זמן ובעל לאחר זמן דאיכא ספיקא דאורייתא:","ומ\"ש ואם מיאנה בו אחר שנבעלה ולא נמצא לה כלומר שנבעלה אחר שגדלה ואחר שנבעלה בדקוה ולא נמצא לה סימנים ומיאנה בו והלכה ונתקדשה לאחר צריכה ממנו גט מספק ואסורה לחזור לו ואם ניסת תצא מזה ומזה והולד ספק ממזר הטעם בכל זה משום דהו\"ל ספק א\"א דאורייתא:","\u0003ומ\"ש רבינו שבספר התרומה החמיר וכו'\u0004 כבר כתבתי בסמוך שהוא מדברי התוס'. ומ\"ש עוד רבינו הביאה סימנים אחר י\"ב ולא בעל אח\"כ הוי ספק קידושין ואם בא להוציאה צריכה גט מדרבנן כבר נתבאר כן בסמוך מההיא דפרק יוצא דופן. ומ\"ש ומיהו אם לא גירשה ועמדה ונתקדשה לאחר צריכה גט משניהם ואם ירצו מגרש ראשון ונושא שני אבל לא יגרש שני ונושא ראשון שמא יאמרו מחזיר ראשון גרושתו משנתארסה כבר נתבאר כן בסמוך מדברי הרי\"ף:","ומ\"ש בשם הרמב\"ם דדוקא היכא שלא בעל אחר שגדלה ונתקדשה צריכה גט מהשני ואסורה לחזור לראשון אבל בעל אחר שגדלה ונתקדשה לאחר אפילו גט אינה צריכה מהשני ומותר לחזור לראשון איני יודע מה מלמדנו רבינו בכאן שהרי נתבאר כן בדבריו שכתב לעיל בסמוך כלשון הזה שאם היה ידוע שהיה לה שערות קודם שבא עליה הוו קידושין גמורים שודאי בעל לשם קידושין ואם קדשה אחר אינה צריכה ממנו גט ואע\"פ שי\"ל ששם לא כתבו אלא להוכיח שאם בא עליה אחר שהגיעה לכלל שנותיה אינה יכולה למאן לפי שהוא ספיקא דאורייתא ולפיכך חזר וכתבו כאן במקומו מכל מקום קשה למה כתבו בשם הרמב\"ם דמשמע שהוא לבדו סובר כן והרי רבינו כתב כן סתם לעיל בלי חולק וכך הוא האמת כי מדברי הרי\"ף הוא והרא\"ש העתיק דבריו וא\"כ הוה ליה לרבינו לכתבו סתם ולא לכתבו בשם הרמב\"ם ז\"ל:","ומ\"ש ואפילו לא בעל אחר שגדלה ונתקדשה שצריכה גט מהשני ואסורה לחזור לראשון אם חטפה אחר דרך אונס וקדשה בביאה אינה צריכה גט מהשני ומותרת לחזור לראשון נראה שכתב כן מדגרסי' בפ' ב\"ש (יבמות דף קי) אהא דאמרינן קטנה שלא מיאנה והגדילה ועמדה ונשאת רב אמר אינה צריכה גט משני ומי אמר רב אי בעל אין אי לא בעל לא והא ההיא עובדא דהוה בנרש ואיקדישה כשהיתה קטנה וגדלה ואותבוה אבי כורסייא ואתא אחרינא וחטפה מיניה ורב ברונא ורב חננאל תלמידי דרב הוו התם ולא אצרכוה גיטא מבתרא אמר רב פפא בנרש מינסב נסיבי והדר מותבי אבי כורסייא רב אשי אמר הוא עשה שלא כהוגן לפיכך עשו בו שלא כהוגן אפקעינהו רבנן לקידושי מיניה א\"ל רבינא לרב אשי תינח קדיש בכספא קדיש בביאה מאי שויוה רבנן לבעילתו בעילת זנות משמע ליה דכהא דאמר רב אשי קי\"ל דבתרא הוא אבל הרי\"ף והרמב\"ם והרא\"ש השמיטו זה משמע דס\"ל דכיון דלשינויא דרב פפא לא מפלגי בין חטפה ללא חטפה ה\"ל ספיקא ומספיקא לא מפקעינן לקידושי מיניה ואע\"ג דרב אשי דהוא בתרא אמר הכי איפשר דטעמייהו דרב ברונא ורב חננאל קאמר וליה לא ס\"ל : ומ\"ש בשם הרי\"ף דוקא שלא בא עליה שני קודם גירושי ראשון אבל אם בא עליה שני קודם גירושי ראשון אסורה לשניהם וכו' דבר פשוט הוא דלא קאי אמאי דסמיך ליה אלא למה שכתב לא בעל ראשון אחר שגדלה ונתקדשה לאחר מגרש ראשון ונושא שני וכבר העתקתי בסמוך דברי הרי\"ף ומ\"ש שסיים הרמב\"ם אבל אם בא עליה ראשון קודם גירושי שני הולד ממזר פשוט הוא דכיון דנישואי ראשון אינה אלא מדרבנן כשקדשה שני לאחר שגדלה תפסי קידושין מדאורייתא והו\"ל א\"א דאורייתא והלכך אם בא עליה ראשון הוי כאילו בא עליה אחר. ומ\"ש וא\"א ז\"ל התיר אפי' בא עליה שני קודם גירושי ראשון וכתב על דברי רב אלפס כדאי הוא הרב לסמוך עליו וכו' ט\"ס יש כאן וצריך להגיה ולכתוב והראב\"ד ז\"ל התיר במקום וא\"א ז\"ל התיר וכך הוא בפסקי הרא\"ש פ' ב\"ש:","ומ\"ש וכן הוא מסקנת א\"א ז\"ל בפרק הנזכר כתב אחר דברי הראב\"ד והרמב\"ן לחזק דברי רב אלפס והביא ראיה מכל פסולי גיטין של דבריהם כגון כתב שם שר שאין ראוי היה במזרח וכתב במערב וכן כנסה בגט קרח שבכל אלו לא עשתה לא איסור ערוה ולא איסור לאו דבר תורה ואין בהם אלא פסולי תקנות של דבריהם משום שלום מלכות ומשום דמיחזי כשקרא ואעפ\"כ תצא מזה ומזה וכל הדברים האלו בה כ\"ש בזו שיש כאן קידושין שלימים מדבריהם שהיא יוצאה מזה ומזה ואינו ענין לכאן כלום דהתם טבעו חכמים מטבע בגיטין וקנסו כל המשנה מטבע שלהם אבל בנדון זה שאין תקנה לחכמים בדבר זה אלא לפי שבא עליה באיסור יש לקונסו אין לחדש קנס זה מדעתינו אם לא שנמצא שקנסו כיוצא בזה עכ\"ל ועיין ברבי' ירוחם כתב נמוקי יוסף בפרק בית שמאי אהא דאמרי' דהיכא שלא בעל משגדלה ונתקדשה לאחר צריכה גט מזה ומזה יש אומרים דדוקא כשנתקדשה שלא בפני הראשון אבל אם קבלה קדושין בפני הראשון אינה צריכה גט מהראשון משום דהו\"ל כאומרת לו גרשתני שהיא נאמנת וכדרב המנונא ויש מחלקים דשאני הכא שהיא סבורה שאין קידושי ראשון כלום כתב הריב\"ש בסימן ו' על הא דקטנה שלא מיאנה והגדילה ונשאת לאחר אמר רב אינה צריכה גט משני דכיון שהגדילה עם הראשון מסתמא בעל לשם קידושין ואמרו בשם הרא\"ה דאפילו עדי יחוד אינה צריכה כיון שאשתו היא ועומדת תחתיו ע\"כ ידעי שנתייחד עמה ובא עליה זהו דעת יחיד שכל הראשונים כתבו שצריכה לעידי ייחוד עכ\"ל:"],["\u0003קטנה שאין לה אב וכו'\u0004 כתב נ\"י בפ' ב\"ש לדעתה כבת י' כבת י\"א שלא לדעתה כבת ה' כבת שש כו' וז\"ל הרמב\"ם בפי\"א מה\"ג איזו היא קטנה שצריכה למאן מבת שש ועד בת עשר שנים בודקין אותה לפי יופי דעתה אם יודעת לשמור קידושיה ושהן קידושין לא שתשמור אותן כדרך שמשמרת האגוז ותמרה וכיוצא בהן ה\"ז צריכה מיאון ואם אינה יודעת לשמור קידושיה א\"צ למאן אלא הולכת לבית אמה כאילו לא נתקדשה מעולם ופחותה מבת שש אפי' יודעת לשמור א\"צ מיאון ויתירה על בת י' אפי' סכלה ביותר צריכה מיאון עכ\"ל וע\"ל בסימן מ\"ג ובב\"י לשם שהביא דברי ה\"ה בפ\"ד דאישות:","\u0003והמיאון הוא שתאמר אי איפשי בפלוני בעלי ואי אפשי בקידושין וכו'\u0004 פי' הרמב\"ם לשם דר\"ל או אי אפשי בקידושין וכו':","\u0003ומ\"ש וממאנת בין מן האירוסין בין מן הנשואין וכו'\u0004 בפרק ב\"ש פליגי בה ב\"ש וב\"ה והלכה כב\"ה דאף בזמן נשואין דסד\"א דלאו אדעתא דהכי נסבה דתמאן ותהא בעילתו בעילת זנות קמ\"ל דאין כאן חששא דבעילת זנות כיון שעל ידי קידושין ונשואין בא עליה כ\"כ התוס' בפרק הזורק (גיטין דף פ\"א) בד\"ה ב\"ש:","ומ\"ש רק שיהא בפני שנים שיעידו על הדבר פי' אע\"ג דבחד נמי סגי אפ\"ה צריך שנים כדי שיעידו על המיאון דע\"א אינו נאמן וכ\"כ התוס' ולכן הוסיף רבינו בלשונו ואמר שיעידו על הדבר:","\u0003ומ\"ש וכשם שממאנת בבעל וכו'\u0004 כלומר ל\"ת הואיל וזיקתה הגיע מנשואי הבעל ולא מיאנה בו שוב אינה יכולה למאן ביבם קמ\"ל:","\u0003ומ\"ש לפיכך א\"צ לא כתיבה ולא מסירה וכו'\u0004 כלומר א\"צ לא כתיבה של בעל ולא מסירה של בעל כמו בגט:","\u0003קטנה שממאנת אין לה כתובה ק' או ר' אבל יש לה תוספת וכו'\u0004 פי' רש\"י ס\"פ אלמנה ניזונת אבל תוספת יש לה דמתנה בעלמא יהיב לה בחיבת ביאה עכ\"ל:","ואם אינם בעין א\"צ לשלם כצ\"ל וכ\"כ הרמב\"ם בפכ\"ד מהל' אישות ולפני הב\"י היה כתוב ואם אינן בעין צריך לשלם ופי' מה שפירש וספר מוטעה נזדמן לידו ומיהו אם כולן בבת אחת כגון שמכרן ואכל דמיהן דזהו קרנא מקרי חייב לשלם וע\"ל בסימן קי\"ו:","\u0003ואינה צריכה להמתין ג' חדשים וכו'\u0004 דליכא למיגזר אטו גדולה כיון דאין מיאון בגדולה משא\"כ בגרושה דגזרינן קטנה גרושה אטו גדולה:","\u0003הממאנת ביבם אסורה לאביו וכו'\u0004 פי' אף על גב דבסמוך כתבתי דממאנת בבעל מותרת בקרוביו דבכל קרוביו מותרת אף לאביו דעקרתינהו לנישואין והוי כאנוסה ומפותה אבל אם מת בעלה ולא מיאנה בו ומיאנה ביבם אע\"ג דנפקא בלא חליצה דעקרי לנשואי קמאי אפ\"ה אסורה לאביו מפני מראית העין דבשעת נפילה דאהנו נשואי קמאי למיפל קמי יבם ולהצריכה מיאון לגבי יבם נראית ככלתו של חמיה וסובר רבינו דה\"ט דשמואל דאמר מיאנה יבמה באחד מן האחין יבמין מותרת לשאר אחין דלאביו דוקא כיון דבשעת נפילה נראית ככלתו דאסורה לו לא הותרה לו לאחר המיאון מפני מראין העין אבל ליבמין דבשעת נפילה הותרה לכל האחד מהאחין הילכך אף לאחר שמיאנה באחד מן האחין נשארה בהיתרה לכולהו דאמרת לא רעינא בך ולא צבינא בך בך הוא דלא רעינא הא בחברך רעינא כדאיתא התם וז\"ל רבינו לפיכך מיאנה מאחד מהיבמים מותרת לשאר האחין דהקשה ב\"י ע\"ז וז\"ש ולשון רבינו שכתב לפיכך אינו מכוין יפה דהא הני תרי דיני לא תלו הא בהא עכ\"ל אבל למאי דפי' ניחא דרבינו ס\"ל דלא הותרה הממאנת אלא לקרובי היבם דהיינו האחין שהותרה להן בשעת נפילה אבל לקרובי המת דהיתה אסורה להן בשעת נפילה ודאי דאחר המיאון נמי אסורה כי היכי דאסורה לאביו ולכן אמר רבינו לשון לפיכך לאורויי דמ\"ש אבל מותרת לשאר קרוביו אינו אלא לומר דמותרת לשאר קרוביו של יבם ולפיכך אינה מותרת אלא לשאר אחין בדוקא לאפוקי לקרוביו של מת היא אסורה כשם שהיא אסורה לאביו וזהו ג\"כ דעת הרמב\"ם בפי\"א שכתב גם כן לשון זה דלפיכך כמ\"ש רבינו ותימה גדולה אמאי נתקשה לשון רבינו לב\"י יותר מלשון הרמב\"ם אין ספק דתקפה עליו משנתו אבל לפע\"ד לשון זה וזה מכוון מאד שאין הממאנת מותרת אלא לאחין בלבד וכ\"כ הריטב\"א כמ\"ש נ\"י ומה שהבינו מדברי הרמב\"ם שמתיר אפי' לקרובי המת והשיגו עליו כל הגדולים וכ\"כ ה\"ה בשם הרמב\"ן והרשב\"א ומביאו ב\"י נלפע\"ד דאין כאן מחלוקת אלא גם הרמב\"ם הכי ס\"ל ככל גדולי עולם דאינה מותרת אלא ליבמין והכינקטינן:","\u0003עד מתי הבת ממאנת וכו'\u0004 אבל כ\"ז שלא ילדה וכו' מדהאריך רבינו בלשונו זה נרא' שהוא סובר כמ\"ש ה\"ה פ\"ב דאישות שאיפשר לקטנה שתתעבר ולא תמות אבל כל זמן שילדה הרי בנים כסימנין משעת העיבור ואפילו מקודם זמן נערות ואינה יכולה למאן: והרמב\"ם כתב וכו' בפרק ב' דאישות ונ\"ל דט\"ס הוא וכו' גם הראב\"ד השיג עליו וכתב ה\"ה שכן פירשו כל המפרשים ושכן עיקר.","ומ\"ש שהן ל\"ו שנה פי' ל\"ה שנה ויום אחד וכ\"כ הרמב\"ם לשם דאפי' ביום א' בתוך ל\"ו הגיע לרוב שנותיו:","\u0003אין ב' שערות סימן גדלות וכו'\u0004 ואפילו לחליצה וכו' פי' לא מיבעיא דמחזיקין לה כגדולה לענין מיאון לחומרא שלא תמאן אלא אפי' לקולא מחזקינן לה כגדולה שתחלוץ לכתחילה אע\"פ שקידשה אביה דקידושיה דאורייתא ומת בעלה ולא חיישינן שמא באו תוך הזמן:","\u0003ומ\"ש ור\"ת כתב וכו'\u0004 פי' לסברא הראשונה ביום אחרון של שנת י\"ב נמי שומא היא והוא דעת הרמב\"ם לשם ומביאו ב\"י אבל ר\"ת חולק וטעמו מפורש בב\"י.","\u0003ולענין שיעור אורך השערות וכו'\u0004 והרמב\"ם כתב משיהיו ניטלות בפי הזוג חשיבא גדולה כלומר שהרמב\"ם לא כתב כסברא הראשונה להחמיר משיהיו נקרצין בציפורן עד שיהיו כדי לכוף ראשן לעיקרן אלא כתב להחמיר משיהיו ניטלות בפי הזוג עד שיהיו כדי לכוף ראשן לעיקרן ויראה מדבריו שהוא קודם קריצתן בציפורן דאילו לסברא הראשונה שהוא פי' רש\"י קריצתן בציפורן הוא שיהיו ניטלות בפי הזוג ותימא הלא קי\"ל דבין כך ובין כך להחמיר שלא תמאן ולא תחלוץ הואיל ולא הגיעו לכוף ראשן לעיקרן וא\"כ מאי נ\"מ אם זה קודם או זה קודם וכך הקשה מהרש\"ל ונלפע\"ד ליישב דלא קי\"ל להחמיר שלא תמאן ושלא תחלוץ אלא לכתחילה הואיל ולא הגיע ראשן לעיקרן אבל בדיעבד קי\"ל אין הלכה כיחיד במקום רבים והשתא לפי' רש\"י דקריצתן בציפורן הוא קודם אפי' בדיעבד אם חלצה בכדי קריצה בציפורן חליצתה פסולה דקי\"ל כר' ישמעאל ור\"ע דפליגי אר\"א דבכדי לקרוץ בציפורן לא חשיבי שערות ולגבי מיאון חשוב מיאון בדיעבד כיון דלא חשיבי שערות אבל בחלצה משיהיו ניטלות בפי הזוג חליצתה כשירה דקי\"ל כר\"ע ור\"א דפליגי ארבי ישמעאל דלא בעינן כדי לכוף ראשן לעיקרן ולענין מיאון אינו מיאון דגדולה היא ולהרמב\"ם הוי איפכא דבחלצה משיהיו ניטלות בזוג הויא חליצתה פסולה ואם מיאנה הוי מיאון בדיעבד אבל בחלצה בכדי לקרוץ בציפורן החליצה כשרה כר\"ע ור\"א דתרוייהו פליגי ארבי ישמעאל דלא בעינן כדי לכוף ראשן לעיקרן ולענין מיאון אינו מיאון אפי' דיעבד דגדולה היא ולענין הלכה נקטינן כדברי כולן להחמיר אפילו בדיעבד בפלוגתא דרבוותא אבל כשיהיו כדי לכוף ראשן לעיקרן חולצת לכתחילה כנ\"ל וכל זה לדינא דגמרא אבל עדיין צריכין אנו למודעי היאך יש לנהוג בזמן הזה כי בסימן קס\"ד כתב בפי' סדר חליצה סכ\"ז וז\"ל ולענין שיעור אורך השערות שסומכים עליהן כתוב בקונטרסים שהוא כרוחב אצבע שקורין אמה עכ\"ל. ולכאורה קשה דכאן מפורש דלהיותר מחמיר סגי בדבריו בכדי לכוף ראשן לעיקרן לחלוץ לכתחילה וכ\"פ כאן בש\"ע סי\"ח ולא בעינן כרוחב אצבע ולכאורה היה נראה דאידי ואידי חד שיעורא הוא ומילתא דפסיקא נקט בקונטרס דבאורך רוחב אצבע אין בו ספק דודאי יש בו כדי לכוף ראשן לעיקרן וגם דלפי דטורח הוא לבדוק ראשן לעיקרן ועוד דאין אנו בקיאין בכפיפה זו ע\"כ נתנו האחרונים גבול באורך רוחב אצבע דכל אדם יוכל להבין אם יש בהן אורך רוחב אצבע אם לאו ואין ספק שכך היא הקבלה מהגדולים הקדמונים ולאו דבעינן רוחב אצבע בצימצום מדינא אלא כדי לאפוקי נפשין מלעז שאין אנו בקיאין בכפיפה זו הניחו גבול זה דאורך אצבע לכתחילה אבל בדיעבד ודאי כשרה אף באין בו אלא כדי לכוף ראשן לעיקרן ואין בהן כדי רוחב אצבע מיהו ביבם שאינו אלא בן י\"ג שנה ויום אחד ולא נמצא לו אלא ב' שערות בלבד והן באורך אצבע לא ראיתי מרבותי שעשו כך מעשה לכתחילה וגם אנחנו לא עשינו מעשה בזה מעולם והוא דכיון דקי\"ל דב' שערות צריך לבדוק בעיקרן אם יש בהן גומות ואין אנו בקיאין להכיר הגומות א\"כ אפי' יש בהן כדי כפיפה או אפי' רוחב אצבע אין לחלוץ לכתחילה בשני שערות בלחוד דשמא אין להם גומות וכ\"כ בסה\"ת בסי' קל\"ג דאין לחלוץ אא\"כ יש ריבוי שערות או ב' שערות ארוכות הרבה כמו שרגילות לאיש גדול ולאשה גדולה וכ\"כ בסמ\"ג ע\"ש סה\"ת וכ\"כ רבי' בסימן קס\"ט וכ\"כ האגודה בפרק מ\"ח והוא מיסוד ה\"ר פרץ בסמ\"ק ה' חליצה וכ\"כ בש\"ע בסימן קס\"ט סי\"א: ומ\"ש רבינו וכ\"כ גם בש\"ע לסמוך ע\"פ השכנים או קול עם ב' שערות לא היה צריך לכותבו שהרי אפי' היו עדים כשרים מעידין על השנים שהוא בן י\"ג שנה ויום אחד לא היינו סומכין על ב' שערות בלחוד אא\"כ דאיכא ריבוי שערות או שערות ארוכות ואז א\"צ כלל עדים או חזקת שכנים וקול או קומה אלא דכן דרכו של רבינו לכתוב מה שעולה לפי ההלכה מדין התלמוד ומה שעולה מדין הגאונים והפוסקים אע\"פ שאין אנו סומכין ע\"ז בזמה\"ז ואחר זה נמשך גם הש\"ע ולכן בסי' ס\"ח כתב שיעור רוחב אצבע שהוא ניתן לשיעור הכפיפה וקודם זה בסימן קס\"ט סי\"א כתב וע\"ז סומכין שלא לבדוק אם יש גומות בשערות מאחר שיש ריבוי שערות או ארוכות אלמא דאם אין שם אלא ב' שערות שאינן ארוכות הרבה כמו שיש לאיש גדול ולאשה גדולה צריך לבדוק בגומות וכיון דאין בקיאין בגומות אין לחלוץ אלא בריבוי שערות או ארוכות וכ\"כ במרדכי פמ\"ח בשני מקומות ובשם סה\"ת ומקור דבריהם הוא מדברי ר\"י בתוס' פ' האומר דקידושין סוף (דף ס\"ג) בד\"ה בני זה ע\"ש מיהו אחר העיון ראיתי דטובא קשה לשיטה זו דפי' והוא דאי איתא דשיעורא דכפיפה ושיעורא דאצבע אידי ואידי חד שיעורא הוא וצריך לבדוק לגומות היאך אמר ולענין שיעור אורך השערות שסומכין עליהן וכו' הלא בזמן הזה דאין בקיאין בגומות אין לסמוך אשיעורא דאצבע כי היכי דאין סומכין אשיעורא דכפיפה דשמא אין בעיקרן גומות ולא כתב לן הילכתא למשיחא דאינהו בקיאין בגומות דאם כן לא איצטריך לשיעורא דאצבע אלא בשיעורא דכפיפה דקאמר תלמודא ולכן קרוב לומר דהקונטרסים באו לבאר ולפרש דמ\"ש רבינו ע\"ש ספר התרומה וז\"ל וע\"ז סומכין שא\"צ לבדוק אם יש בהם גומות אע\"ג דקי\"ל שצריך שיהיו בעיקרן גומות אם יש ריבוי שערות או שהן ארוכות א\"צ לבדוק על הגומות עכ\"ל דמדכתב בסתם או שהן ארוכות ולא נתן גבול לאותו אורך ע\"כ כתב לבאר זה ואמר ולענין אורך השערות שכתבו הטור והתרומה שסומכין עליהן הוא כשהן ארוכות כרוחב אצבע כי אז א\"צ לבדוק בגומות ולפ\"ז משמע דהקונטרסים לא ראה גוף סה\"ת שכתב לשם וכ\"כ בסמ\"ג בשמו או ארוכות הרבה כמו שרגילות לאיש גדול ולאשה גדולה וכו' אלא ראה מ\"ש הטור ע\"ש סה\"ת ופי' דבריו דהיינו ארוכות כרוחב אצבע וכך קיבל מהגדולים שאז הגיע לכלל גדלות וא\"צ לבדוק בגומות אי נמי ראה גוף סה\"ת וסמ\"ג וסמ\"ק והמרדכי אלא דמפרש לשונם שאמרו ארוכות הרבה דהיינו כשהן באורך רוחב אצבע והיינו גדולות שוכבות דכתב בסמ\"ק דכך רגילות באיש וכו' ומכל מקום איך שיהיה הפי' בב' שערות בלבד כשהן ארוכות אבל זה פשוט הוא בשיש שם ריבוי שערות דשוב א\"צ לבדוק באורך השערות כלל דמסתמא הגיע לכלל גדלות לד\"ה כשיש ריבוי שערות וא\"צ לבדוק אם יש בעיקרן גומות גם א\"צ לבדוק אם יש ביניהן על הפחות ב' שערות שיהא בהן שיעור כפיפה דאפילו אין שם גומות ולא שיעור כפיפה ודאי גדול הוא כיון דיש שם ריבוי שערות ואין ספק אצלי דלפי שיש פנים לפרש הך שיעורא דאצבע בשתי דרכים דפירושים לכך לא ראינו לרבותי שעשו מעשה החליצה לכתחילה כשלא היה שם אלא שתי שערות בלבד בשיעורא דאצבע אלא דוקא בשיש שם ריבוי שערות ומ\"מ אם יזדמן לפני ב\"ד יבם שאין לו אלא ב' שערות בלבד והן ארוכות כרוחב אצבע והיבמה שומרת ויושבת עגונה כמה שנים יכול לחלוץ לה לכתחילה כי לפע\"ד שיטה זו האחרונה היא עיקר במ\"ש הקונטרסים לפסק כ' ב\"י דסומכין עליהן אף בזמן הזה שאין בודקין בגומות ואף על פי שאין שם אלא ב' שערות בלבד ודלא כנראה משמעות הסה\"ת והסמ\"ק והסמ\"ג והמרדכי לכאורה דבעינן ארוכות הרבה כמו לאיש גדול אלא סומכין על שיעורא דאצבע דלזה אני קורא ארוכות הרבה כמו לאיש גדול אבל אין לסמוך כלל על שיעורא דכפיפה בזמן הזה חלילה וחס כיון דהיה צריך לבדוק בגומות ואין אנו בקיאין בגומות בזמן הזה וכך העליתי בתשובה שכתבתי בשנת הש\"צ לבני ישיבה דק\"ק פרנקפורט ע\"י הרב הגדול והישיש בתוכם כמוהר\"ר יוזפא במהר\"ר פינחס נוירלינגן ז\"ל:","בד\"א שיכולה למאן וכולי כל הסוגיא בפרק יוצא דופן (נדה דף מ\"ו) ובפרק בית שמאי (סוף יבמות דף ק\"ט) ומפורש היטב בב\"י:","\u0003ובסה\"ת החמיר וכו'\u0004 מבואר דלא החמיר אלא אחר י\"ב שנה דשמא איכא גומות אבל קודם י\"ב שנה אפי' איכא גומות לאו כלום הוא דהא לעיל קאמר דאין שערות סימן גדלות אלא כשבאו מי\"ב שנה ואילך וכשיש להן גומא אלמא דקודם י\"ב שנה אפי' אית להו גומא שומא נינהו דאי בדלית להו גומא אפילו לאחר י\"ב שנה לאו סימן גדלות הוא אלמא דקודם י\"ב שנה אפילו אית להו נמי גומא לאו סימן גדלות הוא ומיאונה מיאון וכן עשה מהר\"י פולק מעשה בימיו ומביאו בהגהת ש\"ע:","\u0003הביאה סימנין אחר י\"ב ולא בעל אחר כך הוי ספק קידושין וכו'\u0004 פי' הוי ספק קידושין דרבנן דשמא אף על גב דקידושי קטנה לאו כלום הן מ\"מ כי גדלה דיש לה סימנים ושנים אמרינן דקידושין גדלי בהדה ואע\"ג דלא בעל דנתקדשה השתא אפ\"ה תפסי קידושין דמעיקרא מדרבנן א\"ד לא תפסי כלום אפילו גדלה כיון דקידושי קמאי לאו כלום נינהו ואם בא להוציאה צריכה גט מדרבנן אבל בנ\"י פרק בית שמאי כתב וז\"ל אברייתא המקדש את הקטנה קידושי' תלויין דתלמודא מפרש לה בתרי גווני או לומר קידושיה תלויין עד שתהיה גדולה ואז גמרי הקידושין דהו\"ל בשעה שנתן לה כסף קידושיה כאילו התנה עמה הרי את מקודשת לי לאחר גדלות וכאותה ששנינו הרי את מקודשת לי לאחר ל' יום שאם לא חזרה בה בתוך ל' הויא מקודשת לו דאורייתא לאחר ל' יום אעפ\"י שנתאכלו המעות משום שנשאר עליה שעבוד הדינר והכא נמי כיון דתקינו רבנן נישואין ה\"ה משתעבדת בכסף קידושין ולפיכך כשגדלה גדלי קידושיה בהדה ד\"ת וה\"ה מקודשת גמורה לראשון וא\"כ א\"צ גט משני או ר\"ל תלויין דאי בעל לאחר שגדלה ה\"ה אשתו גמורה ולא תפסי בה קידושי שני כלל ואי לא בעל לא צריכה גט משני עכ\"ל משמע דספק דאורייתא הוא דלא כמ\"ש רבי' וצריך עיון:","\u0003ומ\"ש ומיהו ואם לא גירשה וכו'\u0004 כ\"כ לשם הרי\"ף והרא\"ש וכתב הרמ\"ה דוקא היכא שלא בעל וכו' אע\"ג דבמ\"ש רבינו קודם זה נמי משמע הכי שהרי אמר שאם היה ידוע שהיה לה שערות קודם שבא עליה הוו קידושין גמורין וכו' מ\"מ הביא כל לשונו של הרמ\"ה משום סוף דבריו דאם חטפה דרך אונס וכו' שפסק כרב אשי ודלא כהרי\"ף והרמב\"ם והרא\"ש שהשמיטוהו ובמקצת ספרים כתוב הרמב\"ם במקום הרמ\"ה וטעות הוא:","\u0003וכתב רב אלפס וכו'\u0004 כתב ב\"י דבר פשוט הוא דלא קאי אמאי דסמיך ליה אלא למ\"ש לא בעל ראשון אחר שגדלה ונתקדשה. לאחר ראשון מגרש ונושא שני עכ\"ל ופשוט הוא:"]],["\u0003הלכות יבום וחליצה \u0004\n\u0010y0\u0011כי ישבו אחים יחדו ומת אחד מהם ובן אין לו לא תהיה אשת המת החוצה לאיש זר יבמה יבא עליה מצות עשה היא מי שמת אחיו מאביו בלא זרע אפילו היה לו זרע ומת שייבם את אשתו או יחלוץ לה ולקמן יתבאר איזה מהן קודם \u0010c0\u0011\u0010y1\u0011לא שנא אשת אחיו מן האירוסין או אשתו מן הנישואין \u0010c1\u0011\u0010y2\u0011ובלבד שהיה להן ישיבה אחת בעולם \u0010y3\u0011ושלא תהיה היבמה ערוה עליו אבל אם היתה ערוה עליו או שנולד אחרי מות אחיו מותרת לזר בלא חליצה ולא יבום \u0010c2\u0011\u0010y4\u0011ואם הניח אחיו זרע ל\"ש בן או בת או זרע הבן או זרע הבת עד סוף כל הדורות אשתו פטורה מן החליצה ומן היבום \u0010c3\u0011\u0010y5\u0011ואפי' הניח זרע עובר עבירה או ממזר פוטר נשיו מן החליצה ומן היבום חוץ מבן שיש לו מן השפחה והכותית שאינו נקרא זרעו ואינו פוטר \u0010c4\u0011\u0010y6\u0011וכתב רב נטרונאי גאון דוקא בן שיש לו משפחה שאינה שלו אבל בן שיש לו משפחתו פוטר שאין אדם עושה בעילתו בעילת זנות ובודאי שחררה קודם שבא עליה \u0010y7\u0011וגאון אחר כתב דמספקא ליה בההיא מילתא ואזלינן ביה לחומרא שאם אין לו זרע אלא בן שיש לו משפחתו ויש לו אשה ומת בלא בנים חולצת ולא מתייבמת ולענין ממונא אזלינן ביה לקולא ולא ירית אבל איהו גופיה לא מצי מזבנא ליה ירתי ואינו יכול לישא לא שפחה ולא בת חורין ואם קדש בת חורין צריכה גט \u0010y8\u0011והרמב\"ם לא חילק בין שפחתו לאחרת שכתב שאפי' יש לו בן משפחתו אשתו מתייבמת וא\"א הרא\"ש ז\"ל הסכים לדברי רב נטרונאי. ואפי' היה הזרע גוסס או פצוע מכות שא\"א לו לחיות פוטר מן החליצה ומן היבום \u0010c5\u0011\u0010y9\u0011ואפילו זרע שיולד אחרי מותו כגון שמת והניח אשתו מעוברת פוטר ודוקא לאחר שיולד ויהיה בר קיימא \u0010y10\u0011כגון שידוע שנולד לט' חדשים ולא משכחת לה אלא כשפירש ממנה אחר טבילתה ולא קרב אליה אחר כך \u0010c6\u0011או \u0010y11\u0011אפילו אין ידוע וחיה שלשים יום אחר שנולד והוא שגמרו צפרניו ושערו אבל אם ילדה ולא היה ל' יום אחר שנולד \u0010c7\u0011אפילו מת ביום שלשים או אפי' היה ל' ולא גמרו צפרניו ושערו הרי זה ספק נפל ספק קיימא וחולצת ולא מתייבמת ל\"ש מת מחמת חולי \u0010c8\u0011ל\"ש נפל מן הגג או אכלו ארי ומת ואם אין ידוע שכלו לו חדשיו אלא על פיה אינה נאמנת להיות מותרת לזר אם מת תוך ל' יום \u0010c9\u0011\u0010y12\u0011ואם הפילה נפל אחרי מותו מתייבמת \u0010y13\u0011וה\"ר פרץ כתב היכא דאיכא לאיסתפוקי שמא כלו חדשיו או אפי' ילדתו מת אסורה להתייבם וחולצת כדמוכח בנזיר גבי אהא נזיר כשיהיה לי ולד והפילה דהוי נזיר ספק לר' שמעון. \u0010c10\u0011\u0010y14\u0011שאלה לא\"א הרא\"ש ז\"ל על יבמה שנישאת לשוק בחזקת שהיה לה ולד של קיימא והוציאו עליה לעז שלא היה של קיימא והביאה ב' עדים שהיה יותר מל' יום תשובה כיון שהביאה ב' עדים אפילו אם עדים אחרים מעידים שלא היה ל' יום מותרת לבעלה ואינה צריכה חליצה ואם אין העדים האחרונים מעידים עדות ברורה אלא הוציאו קול ולעז אפילו אי ליכא עדים שהיה ל' יום לא אסרינן לה בקלא דבתר נישואין. \u0010c11\u0011\u0010y15\u0011האומר זה בני או יש לי בנים נאמן לפטור אשתו מן היבום אפילו הוחזק באחים (ואפילו באו אח\"כ עדים שיש לו אחים מותרת) \u0010c12\u0011\u0010y16\u0011אבל אם יש עדים שיש לו אחים אינו נאמן לומר יש לי בנים להתירה \u0010c13\u0011\u0010y17\u0011אמר בשעת קידושין יש לי בנים וחזר ואמר בשעת מיתה אין לי בנים אינו נאמן לאוסרה \u0010c14\u0011\u0010y18\u0011והרמ\"ה כתב שחולצת ולא מתיבמת \u0010c15\u0011\u0010y19\u0011כתב הרמב\"ם עד אחד נאמן להעיד שנולד בן לבעלה להתירה \u0010c16\u0011\u0010y20\u0011וכתב עוד מי שזינה עם פנויה או עם א\"א ונתעברה ואמרה זה העובר ממנו הוא ואפילו הוא מודה לה אע\"פ שהוא בנו לענין ירושה ה\"ז ספק לענין יבום שכמו שזנתה עמו כך זנתה עם אחר ומאין יודע הדבר שזה בנו ודאי והרי אין לו חזקה ולעולם ספק הוא ולהחמיר דנין בו ולא מתייבמת ע\"כ \u0010y21\u0011וא\"א הרא\"ש ז\"ל כתב בתשובה על אחד שהיה לו משרתת בביתו והיתה מיוחדת לו וילדה ואמר שהוא בנו שפוטר את אשתו מן היבום אף על פי שלא רצה ליכנס למילה כשמלוהו והביא דברי הרמב\"ם וכתב דבריו תמוהין מאחר שקורהו ספק למה כתב שיורשו ומוציא הממון מחזקת היורשין הודאין ואי משום שהאב נאמן על בנו כרבי יהודה א\"כ לענין חליצה נמי יהא נאמן ואף לפי דבריו בנדון זה שהיתה מיוחדת לו בביתו וילדה ואומר שהוא בנו אפשר דבכה\"ג לא קאמר שתחלוץ כי הוא לא כתב אלא זנות באקראי פנויה דומיא דא\"א. \u0010c17\u0011\u0010y22\u0011האשה שהלך בעלה ובנה למדה\"י ובאו ואמרו לה מת בעלך מותרת לינשא לזר שנעמיד הבן בחזקת שהוא קיים. הלכה היא ובעלה ובנה ובאה ואמרה מת בעלי ואח\"כ בני נאמנת ומותרת לזר מת בני ואח\"כ בעלי אינה נאמנת שתתייבם אלא חולצת ולא מתייבמת. \u0010c18\u0011הלכה היא ובעלה לבד ובאה ואמרה ניתן לי בן במ\"ה ומת בני ואח\"כ מת בעלי נאמנת ומתייבמת מת בעלי ואח\"כ מת בני אינה נאמנת וחולצת ולא מתייבמת \u0010y23\u0011וכתב הרמב\"ם בד\"א כשהיתה פסולה מתחלה לכהונה כגון שהיא גרושה או חללה או שאמרה במערה היינו כשמתו אבל אם אין הדבר כן אינה חולצת שמא יבואו עדים ויעידו שהדבר כן כמו שאמרה שהבעל מת תחילה נמצא שחליצה זו אינה כלום ותינשא לכהן ויאמרו חלוצה מותרת לכהן לפיכך לא תחלוץ ולא תתייבם אלא תשאר בחזקת זקוקה כמו שיצאת עד שיבואו עדים \u0010c19\u0011\u0010c20\u0011\u0010y24\u0011האשה שהלך בעלה וצרתה למדינת הים ואין לה בנים ובאו עדים שמת בעלה לא תתייבם ולא תינשא לעולם עד שתדע אם ילדה צרתה או לא ילדה ולא אמרינן שתחלוץ אחר ט' חדשים למיתת הבעל ותינשא ממה נפשך שאם ילדה צרתה הולד פוטר ואם לא ילדה החליצה פוטרת דשמא ילדה ולד של קיימא והחליצה כמי שאינה ואולי תינשא לכהן ויאמרו חלוצה מותרת לכהן לפיכך אם היא גרושה או חללה תחלוץ אחר ט' חדשים ותינשא \u0010y25\u0011אבל לא תחלוץ בתוך ט' ותינשא אפי' אחר תשעה דשמא מעוברת היתה צרתה והפילה וכיון שהיתה צרתה מעוברת לא היתה חליצה זו חליצה:",["\u0003כי ישבו אחים יחדו ומת אחד מהם וכו'\u0004 מ\"ע היא מי שמת אחיו מאביו בלא זרע אפילו היה לו זרע ומת שייבם את אשתו או יחלוץ לה לקמן יתבאר איזה מהם קודם:","\u0003ומ\"ש לא שנא אשת אחיו מן האירוסין או אשתו מן הנשואין פשוט בכמה מקומות:\u0004 ","ומ\"ש ובלבד שהיה להם ישיבה אחת בעולם בריש פ\"ב דיבמות (דף יו) ומייתי לה בגמרא מדכתיב כי ישבו אחים יחדיו שהיתה להם ישיבה אחת בעולם:","\u0003ומ\"ש שלא תהיה היבמה ערוה עליו וכו'\u0004 בריש יבמות (דף ב.) ומייתי לה בגמרא מקרא:","ומ\"ש ואם הניח אחיו זרע ל\"ש בן או בת או זרע הבן או זרע הבת עד סוף כל הדורות אשתו פטורה מן החליצה ומן היבום בפ\"ב דיבמות מייתי לה התוס' והרא\"ש מקראי:","ומ\"ש ואפילו הניח זרע עובר עבירה או ממזר פוטר נשיו מן החליצה ומן היבום חוץ ממה שיש לו מן השפחה ומן הכותית שאינו נקרא זרע ואינו פוטר משנה פ\"ב דיבמות (ד' כב.) מי שיש לו בן מ\"מ פוטר את אשת אביו מן החליצה ומן היבום חוץ ממה שיש לו מן השפחה ומן הכותית ובגמרא שם מ\"מ לאתויי מאי אמר רב יהודה לאתויי ממזר מ\"ט דאמר קרא ובן אין לו עיין עליו וכתב הרמב\"ם דאפילו היה עובד כו\"ם פוטר את אשת אביו. דין המזנה עם אשה ונתעברה ממנו אם פוטר את אשתו כתב רבינו לקמן בסימן זה דעת הרמב\"ם ודעת הרא\"ש. ובנו מן השפחה ומן הכותית ממעט להו התם מקראי דלא מיקרו בניו וז\"ל הרמב\"ם בפרק א' מהלכות יבום בנו מן השפחה ומן הכותית אינו פוטר את אשתו שזרע הבא מן השפחה עבדים והבא מן הכותית עכו\"ם וכאילו אינם הרי הוא אומר בשפחה האשה וילדיה תהיה לאדוניה מלמד שולדה כמותה ובכותית הוא אומר כי יסיר את בנך מאחרי מסיר אותו מלחשב בקהל אע\"פ שנשתחרר בנו מן השפחה או נתגייר בנו מן הכותית הרי הן כשאר הגרים והמשוחררים ואינם פוטרים את אשתו עכ\"ל :","ומ\"ש רבי' בשם רב נטרונאי כתבוהו הרי\"ף והרא\"ש בפי\"ב דיבמות ומה שחילק בין שפחתו לשפחת חבירו הטעם משום דמסתמא אמרינן שחררה קודם שבא עליה דחזקה אין אדם עושה בעילתו בעילת זנות:","\u0003ומ\"ש דגאון אחד מספקא ליה בהאי מילתא ואזלינן ביה לחומרא וכו'\u0004 גם זה כתבו שם הרי\"ף והרא\"ש:","ומ\"ש שהרמב\"ם לא חילק בין שפחתו לאחרת שכתב שאפילו יש לו בן משפחתו אשתו מתייבמת ז\"ל בפ' הנזכר הרי שהיה לו בן מן השפחה שלו ושחררו ושחררה ונשאה ומת בלא זרע הרי זה תתייבם לאחיו ואע\"פ שבנה ממנה קיים שכבר שחררו עכ\"ל ובפרק י' מהלכות גירושין הביא דברי הגאונים וחלק עליהם ובפ\"ד מהלכות נחלות חילק בין אדם שהוא מוחזק בכשרות לאדם אחר וכתב שם ה\"ה שלא חילק בכך אלא לענין ירושה בלבד ולא לענין שאר דברים ונתן טעם לדבר. ומ\"ש וא\"א הרא\"ש ז\"ל הסכים לדברי רב נטרונאי בפ\"ב דיבמות אם היבם בן שפחה ונסתפקו אם היתה הורתו ולידתו בקדושה עיין בתשובות הרשב\"א סימן אלף ור\"מ. ומ\"ש ואפי' היה הזרע גוסס או פצוע מכות שא\"א לו לחיות פוטר מן החליצה ומן היבום משנה פ\"ק דאהלות:","ומ\"ש ואפילו זרע שיולד אחר מותו כגון שמת והניח אשתו מעוברת פוטר ודוקא לאחר שיולד ויהיה בר קיימא משנה בפ' החולץ (יבמות דף לה):","ומ\"ש כגון שידוע שנולד לט' חדשים ולא משכחת לה אלא כשפירש ממנה אחר טבילתה ולא קרב אליה אח\"כ הוא.","\u0003ומ\"ש ואפי' אין ידוע וחיה ל' יום אח\"כ וגמרו ציפורניו ושערו וכו'\u0004 פשוט בר\"פ החולץ (יבמות דף לו:) גרסי' התם תנן רשב\"ג אומר כל ששהה ל' יום באדם אינו נפל הא לא שהה ספיקא הוי פירש\"י ספיקא הוי וחולצת ולא מתייבמת ודוקא אי מספקא לן אי כלו לו חדשיו או לא אבל אי קים לן דכלו לו חדשיו תנן בפ' יוצא דופן (נדה מג:) תינוק בן יומו פוטר מן היבום ובפ' הערל (יבמות פ:) תניא איזהו בן ח' כל שלא כלו לו חדשיו רבי אומר סימנים מוכיחים עליו שערו וצפורניו אף על פי שלא כלו חדשיו טעמא דלא גמרו הא גמרו אמרי' האי בר ז' הוא ואשתהויי הוא דאשתהי וסובר רבינו דרשב\"ג ורבי לא פליגי וכל היכא דלא ידעינן דכלו לו חדשיו בעינן תרתי חדא שגמרו שערו וציפורניו ושישהה ל' יום ואיני יודע מאין לו זה דאין לומר דמשמע ליה האי מדברי התוספות שכתבו בפרק ר\"א דמילה (שבת קלו.) דליכא למימר דלא קאמר הלכה כר' משום דבעי הוכחת סימנים שערו וצפורניו אבל רשב\"ג לא בעי דהא פשיטא דבן ח' שלא גמרו שערו וצפורניו לכ\"ע לא חיי עכ\"ל דאין זו ראיה דהתם בבן ח' ודאי איירי אבל בשאינו ידוע אם הוא בן ח' או בן ט' משמע דלא בעי רשב\"ג שגמרו שערו וצפורניו ואפי' בבן ח' נמי איכא למימר דלא בעי רשב\"ג גמרו שערו וצפרניו אלא בדלא אשתהי אבל כל ששהה ל' יום באדם אינו נפל ואפילו לא גמרו שערו וצפרניו וגם אין לומר דמשמע ליה הכי מדכתב הרא\"ש בפרק הערל טעמא דלא גמרו סימנים הא גמרו אמרי' בר ז' הוא ואשתהויי אשתהי ויוצא מידי נפל בל' יום אליבא דר' כמו לרשב\"ג ע\"כ דאיכא למימר רבי אית ליה דרשב\"ג אבל רשב\"ג לית ליה דר' דנהי דלר' אע\"פ שגמרו שערו וצפרניו אינו יוצא מידי נפל עד ששהה ל' יום לרשב\"ג גמרו שערו וצפרניו אינם מעלים ולא מורידים ואין הדבר תלוי אלא בשהה ל' יום באדם בלבד וגם הרמב\"ם בפ\"א מה' ייבום לא הצריך אלא שיכלו חדשיו ויחיה ל' יום ולא הזכיר שם גמר שערו וצפרניו ולכן דברי רבינו צ\"ע: ומ\"ש אבל אם ילדה ולא חיה ל' יום אחר שנולד אפילו מת ביום ל' בר\"פ החולץ ובפ' ר\"א דמילה איתמר מת ביום ל' ועמדה ונתקדשה רבינא משמיה דרבא אמר אם אשת ישראל היא חולצת ואם אשת כהן היא אינה חולצת. ומ\"ש לא שנא מת מחמת חולי לא שנא נפל מן הגג או אכלו ארי ומת בפרק ר\"א דמילה שם אהא דתניא רשב\"ג אומר כל ששהה ל' יום באדם אינו נפל איבעיא להו מי פליגי רבנן עליה ואת\"ל פליגי עליה הלכה כמותו או לא ת\"ש דאמר רב יהודה אמר שמואל הלכה כרשב\"ג הלכה מכלל דפליגי ש\"מ אמר אביי פיהק ומת ד\"ה מת הוא כי פליגי בנפל מן הגג או אכלו ארי מר סבר מת הוא ומ\"ס חי הוא ופירש הר\"ן כי פליגי בנפל מן הגג או אכלו ארי כלו' שמת מחמת מיתה הבאה לו ממקום אחר מר סבר היינו רבנן חי הוא ומ\"ס היינו רשב\"ג מת הוא ופי' ה\"ר יונה דלאו דוקא פיהק אלא ה\"ה חלה ומת מדקא מסיים אביי למילתיה כי פליגי בנפל מן הגג או אכלו ארי ולא קאמר כי פליגי בחלה ומת וכן נראה דעת הרי\"ף שהשמיט הא דאביי ונראה שהוא דוחה אותה מהא דאמר רבא מת בתוך ל' יום ועמדה ונתקדשה אם אשת כהן היא אינה חולצת וטעמא משום דסמכינן ארבנן דאמרי לאו נפל הוא אלמא אפי' בשלא אכלו ארי פליגי רבנן אבל ה\"ר יונה כתב דלא פליגי אביי ורבא דהא דרבא מיתוקמא בנפל מן הגג או אכלו ארי והרז\"ה פירש דאביי בפיהק ומת דוקא הוא דקאמר דלא פליגי משום דכיון דאיכא ריעותא מוכחא מילתא דנפל הוא אבל חלה ומת הרי הוא כאכלו ארי דליכא ריעותא דאפילו בן קיימא נמי חלה ומת ולפי זה הא דרבא מיתוקמא בחלה ומת והוי כאכלו ארי ולא פליגי אדאביי כלל עכ\"ל ורבינו סובר דהלכה כרשב\"ג ולפיכך פסק דל\"ש מת מחמת חולה ל\"ש נפל מן הגג או אכלו ארי ומת הוי ספק נפל וכ\"כ הרמב\"ם בפ\"א מהלכות ייבום וז\"ל אם מת בתוך הל' אפילו ביום הל' בין שמת מחולי בין שנפל מן הגג או אכלו ארי הרי זה ספק נפל ספק בן קיימא וצריכה חליצה מד\"ס אבל לא תתייבם ע\"כ כתוב בהגהות מרדכי דכתובות שאם מת הולד תוך ל' יום נוטלת כתובתה לאלתר אע\"פ שהיבם קטן: ומ\"ש ואם אינו ידוע שכלו לו חדשיו אלא על פיה אינה נאמנת להיות מותרת לזר אם מת תוך ל' יום כ\"כ הרא\"ש בתשובה כלל נ\"ב וז\"ל הא דמספקא לך אם האשה נאמנת על עצמה לומר שכלו חדשי העובר שילדה אחרי מות בעלה כשלא שהה ל' יום כדי שלא תצטרך חליצה לא ידענא במה נסתפקת למה תהיה נאמנת אפי' לאחר אתתא לא מהימנא כ\"ש לעצמה להתיר יבמה לשוק ולא מצינו נאמנות לאשה אלא ההיא די' יוחסין (עד.) דקאמר התם ג' נאמנים על הבכור חיה אביו ואמו והתם גופיה לא אמרינן הכי אלא משום דגלי קרא יכיר יכירנו לאחרים ובשביל שהאמינה תורה לאב אע\"פ שהוא קרוב ויחיד וטעמא שאין אחר יכול להכירו עכ\"ל :","ומ\"ש ואם הפילה נפל אחר מותו מתייבמת כ\"כ רבינו ירוחם אם לא יצא לאויר העולם קיים או חולצת או מתייבמת וכך מבואר בדברי הרמב\"ם פ\"א מה' יבום ור\"פ החולץ (יבמות לה:) אמרינן אם יבא אליהו ויאמר דהא דאיעברא אפולי מפלה בת חליצה ויבום היא: \u0005ב\"ה ובהדיא תנן בפ' החולץ הכונס את יבמתו ונמצאת מעוברת וילדה אם אין הולד של קימא יקיים \u0006:","ומ\"ש בשם הר\"ף היכא דאיכא לאסתפוקי שמא כלו לו חדשיו או אפילו ילדתו מת אסור להתייבם וחולצת כדמוכח בנזיר (יג.) כו' יש לתמוה עליו דמאן מייתי מר\"ש דמשמע דלא קי\"ל כר\"ש דיחידאה הוא וי\"ל דע\"כ לא פליגי אלא בספק נזירות דרבנן סברי להקל ור\"ש סבר להחמיר אבל גבי ספק זיקה כ\"ע להחמיר (ועוד יש) \u0005(ב\"ה) צריך להעביר הקולמוס ע\"ז ולכתוב במקומו ואין \u0006לומר דמשמע ליה ז\"ל דהלכה כר\"ש מדאמר בגמרא אמילתא דת\"ק מאן תנא ר' יהודה משמע דלא אתא אלא לאשמועינן דלא פליג אר\"ש אלא יחידאה \u0005(ב\"ה) דאינן טענה כלום דאף ע\"ג דתיהוי מתני' כיחידאי הא קיימא לן דהלכה כסתם משנה וכן הלכה כר' יהודה לגבי ר' שמעון. \u0006ומ\"מ איני יודע למה הניח תלמוד ערוך שבר\"פ החולץ מפורש בענין יבום וחליצה ואהדר למילף מנזיר: כתוב בתשובת הרב שלמה בן הר\"ש בר צמח שמכלוף נפטר בח' לאלול והניח אשתו מעוברת ובאחד לאייר ילדה בן שלם בשערו וצפרניו ולבסוף ח' ימים מת והיה למכלוף הנזכר אח במ\"ה והתיר את אשתו מפני שביום ט' באב היה חולה כשבא לביתו כי כשהלך מביתו היה כ\"ו לתמוז ויש עד אחד מעיד שאז אמר שהיה חושש שאשתו מעוברת ולא אמר זה אלא על שהגיעה זמנה לראות ולא ראתה כשיצא הוא הניחה בחזקת טהורה אפי' שנאמר שמיד כשיצא הוא ראתה נחשוב י\"ד ימים על כ\"ו לתמוז ובא לי\"א יום לאב והרי הוא היה חולה ובני אדם נכנסים לבקרו והנשים אומרות שאמו ביום ובלילה עמו מיום שחלה עד שמת מסתמא לא טבלה אשתו א\"כ ע\"כ לומר שמקודם נתעברה כמו שאמר הוא וסומכין עליו דאיהו קים ליה בגווה ונאמן הוא לומר יש לי בן ומטעם שני מפני שגמרו שערו וצפרנייו ומטעם שלישי משום דהוי כבעל ופירש כיון דבכ\"ו לתמוז יצא ומיד כשבא חלה ולא היה שהות לטבילה אם היה אמת שראתה אחר שיצא הוא מביתו ואפי' לפי דברי אמו שטבלה בכ\"ב לאב נשארו מאב ט' ימים עד ר\"ח אייר הם ח' חדשים וט' ימים נסיר ה' ימים לתשלום החדשים החסרים לפי שחדשי ההריון הם מל' יום נשארו ד' ימים יותר מח' חדשים וכיון שנכנס בחדש הט' ואפי' יום אחד חוץ מיום שנתעברה בו אע\"פ שלא גמרו סימניו ולא שהה ל' יום הוי ולד גמור ואע\"פ שאמרו פ' בנות כותים (נדה לח:) יולדת לט' יולדת לשלמים כבר תמהו על זה רבים שהחוש מכזיב זה והתוס' כתבו שעתה נשתנו הענינים כמו שאמרו פ\"ג דבכורות (כ.) פרה וחמורה אינן יולדות אלא לג' שנים ועתה יולדות לב' שנים וכן תמצא בהרבה דברים והאריך בתשובה זו: ובתשובות הריב\"ש סי' תמ\"ו כתוב שנשאל על אשה כבת כ' שנישאת ושהתה עם בעלה ל\"ה יום ולסוף אלו הימים חזרה וטבלה לנדתה ונתייחדה עם בעלה ותוך ג' ימים מת בעלה ומיד נסתפקה בהריון ולבסוף ילדה בת ויתברר שמיום מיתת בעלה עד יום לידתה יש ט' חדשים וכ\"ב יום והבת גמרו שערותיה וצפרניה ומתה לכ\"ט יום והשיב אם מה שנולדה הבת באמצע חדש תשיעי אינו קרוי כלו לו חדשיו מה שגמרו סימניה אינו מוציאה מידי ספק נפל כיון שמתה תוך ל' יום דקי\"ל כרשב\"ג דכל ששהה ל' יום באדם אינו נפל דמשמע הא לא שהה הוי ספק נפל כדאיתא בפ' החולץ ואיתמר התם מת בתוך ל' יום ונתקדשה רבינא משמיה דרבא אמר אם אשת ישראל היא חולצת אם אשת כהן היא אינה חולצת ואסיק התם דבאשת ישראל חולצת כר\"ש בן גמליאל דקיימא לן כוותיה ובאשת כהן סמכינן ארבנן דאמרי אע\"ג דלא שהה ולד מעליא הוי וההיא ודאי לא בידעי' שכלו לו חדשיו כגון שבעל ופירש הוא דבכה\"ג אפי' רשב\"ג מודה דולד מעליא הוי אפי' לא שהה כדאיתא בפרק יוצא דופן ולא בבן ח' ודאי כגון שבעל ופירש הוא נמי דבכה\"ג לא אמרי רבנן דאע\"ג דלא שהה ולד מעליא הויא אדרבא אמרי דאע\"ג דשהה נפל ודאי הוי ואע\"ג דגמרו סימניו ואפי' שהה ל' יום אלא ודאי ההיא דפרק החולץ בסתם ולדות היא שבעל ולא פירש והם בספק בן ח' או בן ט' וגמרו סימניו ואף הרמב\"ם שפסק כר' דכל שגמרו סימניו הוי ולד מעליא אפי' בן יום א' כמ\"ש בפ\"א מהל' מילה כבר כתב בפ\"א מה' יבום שזהו בדין תורה אבל חכמים החמירו להצריכה חליצה כל שלא שהה ל' וא\"כ בנדון זה אם נחשוב אותה כסתם ולדות שהם ספק ב' ח' ספק בן ט' אף ע\"פ שגמרו סימני הבת כיון שלא שהתה ל' יום צריכה חליצה ובדיעבד נמי באשת ישראל אלא שאם נתקדשה לכהן אינה צריכה חליצה ועוד איפשר לומר דבנדון זה אפי' נתקדשה לכהן צריכה חליצה משום דהוי ספק נפל אפילו לרבנן מדאמר אביי פיהק ומת דברי הכל מת הוא וכו' ופירש\"י דלאו דוקא פיהק ומת אלא ה\"ה לחלה ומת וכ\"כ ה\"ר יונה והרא\"ש ולדבריהם הא דאמר רבא בפרק החולץ דבאשת כהן אינה חולצת משום דסמכינן ארבנן בנפל מן הגג או אכלו ארי הוא אבל חלה ומת בנדון זה אפי' רבנן מודו וא\"כ אפילו אשת כהן חולצת אלא שהרי\"ף השמיט להא דאביי משמע דס\"ל דפליג אדרבא דהא דרבא סתמא הוא בכל ענין וגם הרז\"ה סובר דאביי בפיהק ומת דוקא אבל חלה ומת הרי הוא כנפל מן הגג או אכלו ארי ולפי דברי שניהם אף בנדון זה שהוא חלה ומת פליגי רבנן אבל מה שראוי להסתפק בנדון זה הוא אם מה שנתברר שילדה לאחר מיתת הבעל ח' חדשים וכ\"ב יום הוי קים לן בגויה שכלו לו חדשיו או לא דאי הוי ככלו לו חדשים הדבר ברור שאפילו לא שהה ל' יצא מכלל נפל אפילו לרשב\"ג כדאמרינן בפרק יוצא דופן ומדברי הרמב\"ם נראה דבעינן ט' שלימים שכך כ' בפ\"א מהלכות יבום ונולד לט' חדשים גמורים וכ\"כ בסמ\"ק וכן נראה מפירש\"י בפרק רבי אליעזר דמילה וכו' ונראה שסמכו על ההיא דאמר שמואל בפרק בנות כותיים (נדה לח.) וכן משמע בהדיא בפרק החולץ וכו' אבל מצאתי להרמב\"ן בת\"ה דנולד לט' חדשים אפילו מקוטעים מתאבל עליו וא\"כ בנדון זה לפי סברת הרמב\"ן הרי כלו חדשיו ואינה צריכה חליצה כלל ודבר זה כיון שלא מצאנוה מבואר בתלמוד והראשונים זה אומר בכה וזה אומר בכה ובנדון זה אף אם נאמר דלא הוי כלו חדשיו אינה צריכה חליצה משום ספק גמור אלא משום חומרא דרבנן דהא באשת כהן אינה חולצת מעתה הרוצה להקל ולהתירה בלא חליצה הנה יש לו עמוד נכון להשען עליו הרמב\"ן שהוא כדאי לסמוך עליו וכ\"ש אם הוא שעת הדחק שהיבם קטן או שהוא במדינת הים והמחמיר להצריכה לכתחלה חליצה תבא עליו ברכה עכ\"ל:","\u0003שאלה לא\"א הרא\"ש ז\"ל על יבמה שנישאת לשוק בחזקת שהיה לה ולד של קיימא וכו'\u0004 בכלל נ\"ב וז\"ל התשובה הנה ב' עדים כשרים מעידים שחיה יותר מל' יום אבי היבם שהוא כשר לכלתו כיון שמת בנו ונתרחק ממנו וגם שאלתי השמש ואמר שנתאבל עליו ואלו מוציאי הדיבה לא כתבת שהעידו בפני ב\"ד עדות ברורה שידוע להם שמת הולד תוך ל' יום אלא שהוציאו קול לעז בעלמא וכל זמן שלא העידו בעדות אפילו אי ליכא עדות שחיה בן ל' יום לא אסרי' לה בקלא דבתר נישואין ואם יבואו ויעידו בפני ב\"ד בתורת עדות שיהא ידוע להם לידת הולד וגם היו בשעת פטירתו ולא חיה ל' יום הרי יש כאן עדות מוכחשת שנים מעידים שחיה ל' יום וב' מעידים שלא חיה ל' יום ?וקי\"ל כמ\"ש ?ר\"י י\"ל דתרי ותרי ספיקא דרבנן הוא ולא אמרינן אוקמה אחזקתה ועוד דאזלינן בתר רוב נולדים שהם של קיימא ולכן הקלו חכמים ואמרו אם אשת כהן היא אינה חולצת אע\"פ דספק חלוצה מותרת לכהן חשו חכמים מאחר שהצריכה חליצה אחר שנישאת יאמרו העולם חכמים עמדו על הדבר דודאי נפל היה והצריכוה חליצה ואתי למשרי חלוצה וכ\"ש בנדון זה שנישאת האשה במקומה והדבר ידוע אילו לא היה הדבר ברור להם שהיה הולד של קיימא לא היו מניחין אותה לינשא ועוד שיש כאן עדות מוכחשת והוי ספיקא דרבנן ועוד אם היתה חולצת מספק היינו מוציאים לעז על בניה כי ר\"י פסק כי ולד יבמה לשוק היינו דרבנן הילכך נ\"ל דהך אתתא שריא לבעלה ואינה צריכה חליצה עכ\"ל :","\u0003האומר זה בני או יש לי בנים נאמן וכו'\u0004 בפרק י\"נ (דף קלד.) תנן האומר זה בני נאמן ובגמרא למאי הילכתא לפטור אשתו מן היבום תנינא מי שאמר בשעת מיתתו יש לי בנים נאמן התם דלא מוחזק לנו באח הכא אף ע\"ג דמוחזק לן באח ופי' הר\"ן כלומר אי מהתם ה\"א דוקא בדלא מוחזק לן דאית ליה אחי הוא דנאמן אבל במוחזק לן לא מ\"ה תנא הכי לאשמועינן דאפילו היכא דמוחזק לן דאית ליה אחי נאמן וכתוב בקצת ספרי רבינו ואפילו באו אחר כך עדים שיש לו אחים מותרת וטעמא דמסתבר הוא דכיון שהאמינהו לומר יש לי בנים כי אתי בתר הכי סהדי דאית ליה אחי מאי הוי הרי כיון שהאמינו אותו שיש לו בנים מותרת היא:","ומ\"ש אבל אם יש עדים שיש לו אחים אינו נאמן לומר יש לי בנים להתירה כן משמע מדברי רשב\"ם שכתב שם הכא אתי לאשמעינן דאף ע\"ג דבמוחזק לן בגויה חזקה בעלמא בלא עדים אי אמר זה בני נאמן לפוטרה מייבום ע\"כ משמע בהדיא דדוקא משום דלא הוה אלא חזקה בעלמא הא אי הוו עדים לא הוה מהימן לומר זה בני והטעם דכיון שקדמו עדים דאית ליה אחי ולא הוה מוחזק דאית ליה בנים הרי היתה בחזקת איסור ותו לא אתיא אמירתו דאית ליה בנים ושריא לה וכן כתב רבינו ירוחם וז\"ל אם ידוע לנו בודאי בעדים שיש לו אחים אע\"ג דאמר בשעת קידושין שיש לו בנים אינו נאמן דלא אמרינן מה לו לשקר כיון שיש לו עדים שיש לו אחים עכ\"ל אבל אין נראה כן מדברי הרמב\"ם שסתם וכתב רפ\"ג האומר זה בני או שאמר יש לי בנים ה\"ז נאמן ופוטר את אשתו מן החליצה ומן היבום:","אמר בשעת קידושין יש לי בנים וחזר ואמר בשעת מיתה אין לי בנים נאמן לאוסרה כך הוא הגירסא בספרי רבי' ויש ספרים שכתוב בהם אינו נאמן לאוסרה ונראה שזו היא הגירסא הנכונה דתניא בקידושין פ' האומר (דף סד.) בשעת קידושין אמר יש לי בנים ובשעת מיתה אמר אין לי בנים נאמן להתיר ואין נאמן לאסור כלומר נאמן במ\"ש בשעת קידושין ואינו נאמן במ\"ש בשעת מיתה דברי ר' רבי נתן אומר אף נאמן לאסור ומשמע דהלכה כרבי מחבירו וכן פסק ברמזים וכתב הר\"ן דרבותא קמ\"ל דאע\"ג דאיכא למימר דמאי דאמר בשעת קידושין לא אמר אלא כדי שתתרצה אשתו בקידושיו ובשעת מיתה דלא איכפת ליה במידי קושטא קאמר אפ\"ה נאמן להתיר משום דאיכא למימר מה לו לשקר כדאמרינן לקמן ואינו נאמן לחזור בו מדיבורו הראשון ולאסור עכ\"ל ועוד יתבאר בדינים אלו בסימן שאחר זה:","יש קצת ספרי רבי' שכתוב בהם והרמ\"ה כתב שחולצת ולא מתיבמת ואיפשר שטעמו משום דמספקא ליה אי הלכה כר' או כרבי נתן ופסק לחומרא ורבי' ירוחם כתב שהרמ\"ה פסק כר' נתן ונראה שטעמו מדמתמה תלמודא בפרק האומר לימא מתני' דלא כר' נתן ודחיק לאוקמה כר' נתן ואין זה הכרע דהכי אורחא דתלמודא למהדר לאוקמי מתני' ככ\"ע:","כתב הרמב\"ם עד אחד נאמן להעיד שנולד בן לבעלה להתירה זה לשונו בפרק ג' נאמן עד אחד להעיד ליבמה שמת בעלה ומתיבמת על פיו או שמת יבמה או שניתן לבעלה בן להתירה לזר אפי' עבד או אשה או עכו\"ם מסיח לפי תומו מעיד במיתת היבם כמו שמעיד בא\"א להתיר כמו שבארנו בהל' גירושין ע\"כ והרב רבי' אברהם בר דוד השיג על הרמב\"ם במה שכתב שעד אחד נאמן להעיד שנולד בן לבעלה והרב המגיד כתב שהרב בעל המאור סובר כדברי הרמב\"ם ז\"ל וכן הכריע הרשב\"א ז\"ל ע\"כ ודברי הרא\"ש שכתבתי גבי שאין האשה נאמנת לומר שכלו חדשיו נוטים לדברי הראב\"ד ז\"ל :","\u0003וכתב עוד מי שזינה עם פנויה או עם א\"א ונתעברה וכו'\u0004 בפ' הנזכר וכן כתב רבי' ירוחם בשם ספר המצות וכתב ה\"ה זה ברור בא\"א שרוב בעילות אחר הבעל אבל בפנויה היה נראה לחלק בין אם חשודה ממנו או אם חשודה מאחרים שאם אינה חשודה מאחרים אלא ממנו בלבד הא אמרי' פרק אלמנה לכ\"ג (יבמות סט.) כהן שבא על בת ישראל וילדה תאכל בתרומה ואיכא לישני בגמרא לישנא קמא דוקא דלא דיימא מעלמא ולישנא בתרא אע\"ג דדיימא מעלמא ודעת רבינו פ\"ז מהלכות תרומות כלישנא קמא וכיון דלענין תרומה דאיכא ג\"כ איסורא דאורייתא שדינן הולד בתר דידיה גבי יבום נמי אמאי לא נהמניה וכ\"ש ללישנא בתרא והרשב\"א ז\"ל כתב בתשובה דכל שראינו שבא עליה או שהוא מודה שבא עליה בתר דידיה שדינן ליה והוא שלא ידענו שבא עליה אחר אבל אם ידענו שבא עליה אחר בכי הא לא אמרינן לישדייה בתר קמא דהוה ליה כספק בן תשעה לראשון או בן שבעה לאחרון דמספקא מילתא ולא שדינן ליה בתר קמא עכ\"ד ונראה בדעתו ז\"ל שהוא פוסק כלישנא בתרא דכל דלא ידעי' בבירור שבא עליה אחר אע\"ג דדיימא מעליא בתר דידיה שדינן ליה ובזה נראה להחמיר דה\"ל ספיקא דאוריית' ונקטינן חומרי דלישני כבל בדלא דיימא מעלמא איני מוצא טעם נכון לחלק בין דין זה לדין התרומה ואפי' בדדיימא איפשר שהלכה כלישנא בתרא דסוגיין בפ\"ק דכתובות (יג:) אתיא כי ההוא לישנא עכ\"ל ונמוקי יוסף בס\"פ אלמנה לכ\"ג כתב דפנויה שילדה ואמרה מפלוני הוא אף ע\"פ שנאמנת עליו להכשירו אינה נאמנת עליו לירושה ואפי' בפלגש המיוחדת לו אינה נאמנת עליו :","וא\"א ז\"ל כתב בתשובה על אחד שהיה לו משרתת בביתו והיתה מיוחדת לו וילדה ואמר שהוא בנו שפוטר את אשתו מן היבום וכו' כלל פ\"ב סימן ח' ועיין בתשובות הרשב\"א סי' תר\"י ועיין בנימוקי יוסף בס\"פ אלמנה לכ\"ג במ\"ש שם בשם הריטב\"א:","\u0003האשה שהלך בעלה ובנה למ\"ה ובאו ואמרו לה מת בעליך מותרת לינשא וכו'\u0004 הלכה היא ובעלה ובנה ובאה ואמרה מת בעלי ואח\"כ מת בני נאמנת ומותרת לזר מת בני ואח\"כ בעלי אינה נאמנת שתתייבם אלא חולצת ולא מתייבמת ויש בקצת ספרי רבי' חסרון הניכר וכאשר כתבתי כך הוא הגירסא הנכונה וכך מבואר במשנה פרק האשה שלום (יבמות קיח.) והטעם מבואר דכיון שבשעה שהלכה היתה בחזקת היתר לזר כי אמרה מת בעלי ואח\"כ מת בני הרי היא מעמדת עצמה על חזקתה ולפיכך נאמנת אבל כי אמרה מת בני ואח\"כ מת בעלי שמוציאה עצמה מחזקתה נאמנת להחמיר ואינה נאמנת להקל ולפיכך חולצת ולא מתייבמת ומ\"ש הלכה היא ובעלה לבד ובאה ואמרה ניתן לי בן במ\"ה ומת בני ואח\"כ מת בעלי נאמנת ומתייבמת מת בעלי ואח\"כ מת בני אינה נאמנת וחולצת ולא מתייבמת גם זה משנה שם והטעם מבואר כמו שכתבתי בסמוך:","ומ\"ש בשם הרמב\"ם הוא בפ\"ג והוא מבואר בגמ' פרק האשה בתרא (יבמות דף קיט:) דאמרינן התם אמתני' אחריתי דאינה חולצת גזירה שמא ימצא הדבר שאינה צריכה חליצה ונמצאת מצריכה כרוז לכהונה ואיכא דהוי בחליצה ולא הוי בהכרזה ואמרי הא שרו חלוצה לכהן ומותיב מהאי מתני' דאמרינן בה חוששין לדבריה וחולצת ולא מתייבמת וליחוש דילמא אתו עדים ואמרי כדקא אמרה ונמצא אתה מצריך כרוז לכהונה אמר רב פפא בגרושה רב חייא בריה דר\"ה אמר באומרת אני והוא נחבאנו במערה ופירש\"י בגרושה שהיתה גרושה כבר מאיש אחר שפסולה לכהונה אני ובעלי נחבאנו במערה ואין איש עמנו לבא ולהעיד הילכך ליכא למיחש דילמא אתו סהדי עכ\"ל ולפי שראה רבינו שבפרק האשה שלום שהוא מקום משניות אלו לא איתמר עלייהו בגמרא מידי ולא נזכר שבמקום אחר העמידום באוקימתות אלו לכך כתב אלה הדברים בשם הרמב\"ם ויש בלשון רבינו בדברי הרמב\"ם חסרון וכך הוא לשון הרמב\"ם ז\"ל שמא תחלוץ ויבואו עדים ויעידו שהדבר כמו שאמרו והבעל מת תחלה נמצאת חליצה זו אינה כלום ותינשא לכהן ויראה הרואה אותה שחלצה ונשאת לכהן וידמה שהחלוצה מותרת לכהונה ואינו יודע בעדים שבאו לפיכך לא תחלוץ ולא תתייבם וכו':","האשה שהלך בעלה וצרתה למ\"ה ואין לה בנים ובאו עדים שמת בעלה לא תתייבם ולא תינשא עד שתדע אם ילדה צרתה או לא ילדה משנה פ' בתרא דיבמות (שם) ומ\"ש ולא אמרינן שתחלוץ אחר ט' חדשים למיתת הבעל ותינשא ממ\"נ וכולי שם פלוגתא דאמוראי ופסקו הפוסקים כמ\"ד הכי כתוב בספר רבי' ירוחם נסתפק לר\"ש אם יש לדבר פתח היתר כשתדור אשה זו ע\"ד רבים שלא תינשא לכהן שכל עצמנו לא חששנו אלא מטעם דהצרכת כרוז ואחר שתדור נסתלקה חששא זו והאריך שם בזה ומ\"ש לפיכך אם היתה גרושה או חללה תחלוץ אחר תשעה חדשים מבואר שם כתוב בספר רבינו ירוחם:","ומ\"ש אבל לא תחלוץ בתוך ט' ותינשא אפי' אחר ט' דשמא מעוברת היתה צרתה והפילה וכיון שהיתה צרתה מעוברת לא היתה חליצה זו חליצה הכי איפסקא הלכתא בר\"פ החולץ (יבמות דף לה:) כר\"ל דאמר חליצת מעוברת לאו שמה חליצה וכתב הרמב\"ם בספ\"ג אבל זו הצרה שהיתה עם בעלה כשמת תמתין צ' יום כשאר היבמות ותחלוץ או תתייבם ולא תחוש לצרתה שבמדינה אחרת הואיל ולא היה בעלה עמה ופשוט הוא דין אשם שהלך בעלה למ\"ה ומת שם ונשארה זקוקה ליבם ויצא קול שהיה לבעלה אשה אחרת לשם אם מתירים אותה לחלוץ כתב הריב\"ש בתשובה סימן תק\"ט:"],["\u0003כי ישבו אחים יחדיו וגו'\u0004 מ\"ע היא וכו' פי' כשהוא אחיו מאביו לחוד נמי חולץ או מייבם אבל אחיו מאמו ולא מאביו לא וה\"א רפ\"ב דיבמות מימרא דרב יחדיו המיוחדין בנחלה הראויין לירש זא\"ז פרט לאחיו מן האם רבה אמר יליף אחוה אחוה מבני יעקב וכו' וסוגיא בפ\"ב אהא דתנן מי שיש לו בן מ\"מ וכו' אתיא כרבה וכפירש\"י בריש יבמות. ומ\"ש אפי' הי\"ל זרע ומת פשוט דלא ימחה כתיב וכשמת הזרע הרי שמו מחוי ועוד דכתיב ובן אין לו ולא כתיב ולא היה לו בן משמע אין לו בשעת מיתה קאמר והכי מוכח בפרק יש מותרות דפריך ולא נעשה מתים כחיים לענין ייבום מק\"ו ת\"ל דרכיה דרכי נועם וה\"א בפ' האשה רבה האשה שהלך בעלה ובנה למד\"ה ובאו וא\"ל מת בעליך ואח\"כ מת בנך ונשאת ואחר כך א\"ל חלוף וכו' ובפרק האשה שלום האשה שהלכה היא ובעלה ובנה למ\"ה ובאה ואמרה מת בעלי ואח\"כ מת בני וכו' ולקמן בסימן קס\"ה יתבאר אי מצות יבום קודמת או מצות חליצה קודמת:","\u0003ל\"ש אשת אחיו מן האירוסין וכו'\u0004 בפ\"ק אמתניתין דשש עריות חמורות מאילו איתא בגמרא דבין לב\"ש בין לב\"ה איצטריך לן החוצה לרבות הארוסה וכתבו התוספות דאיצטריך לרבות ארוסה משום דכתיב בית אחיו ובפרק קמא דיומא משמע דבית נשואה משמע עכ\"ל:","ובלבד שהיה להם ישיבה אחת בעולם ריש פ\"ב דיבמות אמר רב אמר קרא כי ישבו אחים שהיה להם ישיבה אחת בעולם. ומ\"ש ושלא תהיה היבמה ערוה עליו ריש יבמות ט\"ו נשים פוטרות צרותיהן וכו' ובגמרא אסיקנא דוקא ערוה אבל שאר נשים כגון צרת איילונית צרת ממאנת צרת מחזיר גרושתו משנשאת כולן צרותיהן מותרות חוץ מצרת סוטה ויתבאר לקמן בסימן קע\"ג:","\u0003ואם הניח אחיו זרע וכו'\u0004 משנה פ\"ב דיבמות מי שיש לו בן מ\"מ פוטר את אשת אביו מן החליצה ומן הייבום חוץ ממי שיש לו בן מן השפחה ומן הכותית ובגמרא מ\"מ לאתויי ממזר מ\"ט דאמר קרא אין לו עיין עליו ומשמע לכאורה דבן הבן וכו' נמי מהאי דרשא דעיין עליו נפקא לן דפוטרין וכ\"כ הרא\"ש בשם בעל הלכות וז\"ל והא דבת פוטרת כתב ב\"ה דילפינן נמי מבן אין לו עיין עליו אבל התוס' הקשו על זה וכתבו דבת נפקא לן מלא ימחה ובת הבן ובן הבת נפקא לן מהא דדרשינן גבי נחלה בן אין לו ע\"ע וכו' וכ\"כ גם הרא\"ש ועי' בתוס' ר\"פ יש נוחלין (בבא בתרא דף ק\"ט) בד\"ה כיון דלענין:","ומ\"ש ואפילו הניח זרע עובר עבירה וכולי משום דמדרשא עיין עליו משמע כל זרע בעולם פוטר אבל להתוס' והרא\"ש דמבן אין לו דגבי ייבום לא דרשי מיניה אלא ממזר קשה מנ\"ל זרע עוברי עבירה ויש לומר דמסברא אתא דהרי בנו הוא ולא אשכחן דנתבטל שם בן מרשעים והא דפליגי ר\"מ ורבי יהודה בספ\"ק דקידושין ומשמע דהלכה כרבי יהודה דאם אין נוהגים מנהג בנים אין קרויין בנים אינו אלא לומר שאין קרויין בנים למקום ב\"ה אבל ודאי דהוי בן לאביו המולידו אפילו היה רשע גמור תדע דהא לר' יהודה אפי' סכלים לא מקרי בנים אע\"פ דאין בהן אלא שטות ואינן רשעים אלא שאין מתנהגים בדרך ישר ותו דאם כן נתת דבריך לשיעורין אימתי הוא ע\"ע כל כך עד שאינו נקרא בנו ותו דילמא הרהר תשובה בלבו כדאמר פ' האיש מקדש וכ\"כ התוס' פ\"ב דיבמות דסתם בן הוי אפי' ממזר לא איצטריך ובן אין לו עיין עליו אלא משום דלא לילף אחוה אחוה מבני יעקב דלא זקיק דמה התם כשרים ולא פסולין וכולי ומדלא זקיק מיפטר נמי לא פטר אבל לענין עובר עבירה ליכא למילף מבני יעקב כיון דאינו מפורש בקר' שלא היו ע\"ע למילף מה התם וכו' דהתם גופה לא ידעי' ואדרבה אשכחן בקרא ראובן ויהודה שעברו אלא שהודו ועשו תשובה ותו דהרי כולם נשתתפו במכירת יוסף ואע\"פ שנפרש ע\"ע דקאמר על עון ע\"ז קאמר והשבטים כולם היו מאמינים בה' אחד כדאיתא פרק מקום שנהגו אפסוק ויקרא יעקב אל בניו וכו' ונילף מה התם לאו עע\"ז וכו' אפ\"ה לא שייך לומר מה התם וכו' כיון דאינו מפורש בקרא אלא מדרשא ותו דאפילו לענין אשת אחיו שלא היה בעולמו כתוב בתוס' לשם דאין סברא למילף מבני יעקב דלא מקרי אחים חלא א\"כ הם בעולם אחד כבני יעקב דפשיטא דמקרי אחים ואי לאו דמיעט קרא בהדיא לא הוה שיוך למילף מבני יעקב לענין הך מילתא עכ\"ל וא\"כ כל שכן היכא דלענין אח שהוא עע\"ז אין סברא למילף מבני יעקב דפשיטא דאחיו הוא דעשו ישראל מומר הוא כדאיתא ספ\"ק דקידושין ונקרא אח בכתוב הלא אח עשו ליעקב ותו דאי בן עע\"ז לא היה פוטר לא הוו שתקי מיניה תנאים ואמוראים לאודועי מהיכא נפקי לן אלא בע\"כ כל בן בעולם פוטר ואפי' רשע ועע\"ז וכך כתב הרמב\"ם והסמ\"ג בה' יבום ולא נמצא במחברים שנחלקו ע\"ז הארכתי בזה מפני שהוא צורך למחלוקת הגדולים באח מומר אם זוקק הוא לייבום אם לאו כמ\"ש סימן קנ\"ז:","\u0003וכתב רב נטרונאי וכו'\u0004 מחלוקת זו כתבוהו הרי\"ף והרא\"ש פרק ב' דיבמות ואיכא למידק דלעיל בסי' ט\"ו סתם רבינו דבריו כדעת הרא\"ש וא\"כ למה הביא כאן כל הדיעות ונראה דרבי' אתא לאורויי לן דכאן אין להקל כהרא\"ש לפוטרה לגמרי או להתייבם כהרמב\"ם אלא צריך להחמיר בפלוגתא דרבוותא כדעת הגאון דחולצת ולא מתייבמת דנראה שהסכים לזה הרי\"ף אבל לעיל לגבי איסור אחותו כתב בסתם כהרא\"ש להחמיר לחייב עלה משום אחותו כיון דלגאון נמי ספק חייב ולא חשש להרמב\"ם דמיקל שם שהוא סברת יחיד נ\"ל. ואכתי קשה הלא הרא\"ש הסכים בס\"פ הזורק לדעת הרמב\"ם דבראו עדים שבא על אשה דעלמא דלא חיישינן דבעל לשם קידושין וכדלעיל בסוף סימן קמ\"ט וכאן בשפחתו תופס דאין אדם עושה בעילתו בעילת זנות ומאי שנא וי\"ל דבשפחה שהוא עם הדומה לחמור והיא עבירה גדולה כדלעיל בסימן י\"ו תלינן דודאי לשחררה כי היכי דלא יעביד עבירה רבה מה שאין כן באשה דעלמא שאין שם אלא איסור פנויה דקיל ותו כיון דבידו הוא לשחררה לא שביק היתירא ועביד איסורא כדכתב הראב\"ד בהשגותיו פ\"י מה\"ג וסברתו בזה הוא היפך מסברת הרמב\"ם דכתב לשם בשאר נשים ה\"ה בחזקה שבעל לשם זנות עד שיפרש כי היא לשם קידושין ואצ\"ל בשפחה וכותית והפליג לסברא הגאונים שאמרו בשפחתו דבועל לשם קידושין ע\"ש ובתשובת בן לב (דף מ) הקשה על דברי הגאון וז\"ל וצ\"ע בדברי הגאון מהא דאמרינן ספק ויבם שבאו לחלוק בנכסי מיתנא ספק אמר אנא בר מיתנא ונכסי דידי הוא ויבם אמר את ברי את ולית לך בנכסי מידי הוה ליה ממון המוטל בספק וחולקין כדלקמן בסימן קס\"ג וא\"כ כאן נמי נימא שיחלוקו בן השפחה עם האח היורש או עם קרוביו ואפשר לתרץ דמאי דקאמר הכא ולענין ממונא אזלינן לקולא ולא ירית היינו דוקא היכא שיש לו בן אחר ודמי להא דאמרינן התם ספק ובני יבם שבאו לחלוק בנכסי יבם דאמרינן ליה אייתי את ראיה דאחונא את ושקול דהתם בני יבם הם בודאי יורשין וזה הספק הוא ספק ואין ספק מוציא מידי ודאי וא\"כ ה\"נ איירי בסיפא כשיש לו בנים אחרים אלא דקשה לי לישנא דקאמר אבל איהו גופיה לא מצי מזבני ליה ירתי דאי איתא דהשתא קמיירי דוקא היכא דיש לו בנים הל\"ל לא מצי מזבני ליה בני עכ\"ל ולפעד\"נ דקושיא מעיקרא ליתא דודאי מיירי הכא דלא שביק בני אלא האי בן משפחתו אלא מיהו ודאי שלא אמרו ממון המוטל בספק חולקין אלא בספק ויבם דהספק בשניהם הוא לכל העולם ומצי ספק טעין ליבם אין אתה מוחוק בנכסים יותר ממני דכשם שאני ספק יורש כך אתה ספק יורש אבל כאן דאין ספק זה אלא לאותו גאון והעומדים בשיטתו דמסתפקא להו אי אמרינן בשפחתו בודאי שחררה קודם שבא עליה אם לאו אבל לגדולים אחרים לא מספקא להו אלא פשיטא להו דאף בשפחתו בא עליה בזנות ולא שחררה כמ\"ש הרמב\"ם א\"כ חשוב האי בן כמו ספק לגבי שאר יורשים שהם ודאי ואין ספק מוציא מידי ודאי ודו\"ק:","\u0003ואפי' זרע שיולד אחרי מותו וכו'\u0004 ודוקא לאחר שיולד וכו' ר\"ל לאפוקי אם הפילה דאז מתייבמת דלא כה\"ר פרץ דבסמוך: ומ\"ש ולא משכחת לה וכו' כ\"כ סמ\"ק וכתב עוד די\"א דמשכחת לה נמי כגון שבא עליה ופירש ולא ידעה עד חדש ימים ולבסוף ב' חדשים לביאה שנייה הוכר עוברה הרי הדבר ידוע שמביאה ראשונה נתעברה והוכר העובר לג' חדשים כמשפט עכ\"ל ור\"ל דכיון שנולד לט' דראוי להיות בר קיימא אע\"פ דלא שהה ל' יום בר קיימא הוא לד\"ה וזהו דתנן בפרק יוצא דופן תינוק בן יום א' פוטר מן הייבום ומפרש בגמרא ובן אין לו אמר רחמנא והא אית ליה ובע\"כ דהיינו כשהוא בר קיימא כדתנן בפ' החולץ וכ\"כ סמ\"ג במצות ייבום ואפילו לא נגמרו סימניו כיון שכלו לו חדשיו היינו בר קיימא אבל הרמב\"ם כתב בפ\"א דד\"ת אפי' לא כלו לו חדשיו ומת בו ביום נמי פוטר והיינו בנגמרו סימניו כמ\"ש ה\"ה ולפ\"ז צ\"ל הא דתנן ר\"פ החולץ הכונס את יבמתו ונמצאת מעוברת וילדה אם אין הולד של קיימא יקיים היינו דלא נגמרו סימניו ולא כלו לו חדשיו דנפל גמור הוא:","\u0003ומ\"ש או אפילו אין ידוע וחיה שלשים יום וכו'\u0004 בפרק הערל אמר רבי אבהו סימני ח' אין עושין בו מעשה עד שיהא בן עשרים ופריך ובן ח' מי קא חיי והתניא בן ח' ה\"ה כאבן ואסור לטלטלו ומשני הב\"ע כשגמרו סימניו דתניא איזהו בן ח' כל שלא כלו לו חדשיו ר' אומר סימגים מוכיחים עליו שעריו וצפרניו שלא גמרו טעמא דלא גמרו הא גמרו אמרינן האי בר ז' הוא ואשתהויי הוא דאישתהי אלא הא דעבד רבה תוספאה עובדא באשה שהלך בעלה למה\"י ואשתהי עד י\"ב ירחי שתא ואכשריה כמאן כרבי דאמר אשתהי ומשני כיון דאיכא רשב\"ג דאמר אשתהי כרבים עבד דתניא רשב\"ג אומר כל ששהה ל' יום באדם אינו נפל כך הוא גירסת רש\"י והתוס' והרא\"ש וכתבו התוספות וז\"ל והתניא בן ח' אסור לטלטלו ואם יכול להיות בר קיימא לא היה אסור לטלטלו ומשני הב\"ע שגמרו סימניו דע\"י סימנים יש היכירא להוציאו מתורת נפל בעשרים שנה וכו' ס\"ל להתוס' דהסוגיא מוכרחת דכל שיכול להיות בר קיימא אינו אסור לטלטלו וטעמא דאיסור טילטול מדרבנן הוא ואין סברא לאסרו היכא שיכול להיות בר קיימא ומ\"ה פריך אדרבי אבהו דאמר דבן ח' יכול להיות בר קיימא מדתניא ה\"ה כאבן ואסור לטלטלו ולפי זה למאי דמשני הא דאסור לטלטלו בדלא גמרו סימניו אף בשהה ל' יום נמי הוי נפל ודאי בדלא גמרו דאם היה יכול להיות בר קיימא לא היה אסור לטלטלו וא\"כ לפ\"ז הא דקיי\"ל כרשב\"ג דבשהה ל' יום אינו נפל היינו דוקא בדגמרו סימניו דאי בדלא גמרו אפי' שהה נפל הוא דקי\"ל נמי כהא דתניא דאסור לטלטלו אם ידוע דבן ח' הוא ואם אינו ידוע ספק נפל הוא וכן מבואר עוד במ\"ש התוס' לשם דע\"כ רשב\"ג בסתם ולדות נמי מיירי דאי לא מיירי אלא בבן ח' מה בא להוסיף על רבי אלמא דרשב\"ג איירי נמי כשגמרו סימנים ור' איירי נמי דוקא בשהה ל' יום אלא דרשב\"ג הוסיף דאפי' בסתם ולדות נמי אפילו גמרו אי לא שהה ספיקא הוי כדתניא כל ששהה וכולי ולא נקט אם שהה וכמ\"ש התוס' ונראה נמי דאע\"ג דרבי לא איירי אלא בבן ח' בסתם ולדות נמי סובר דאי לא שהה אפילו גמרו ספיקא הוי לדברי התוס' שהרי כתבו דלרבי כי גמרו סימנים חשיב בר קיימא בל' יום כשאר ולדות ומילתיה דרבי אבהו כרבנן ומ\"ה פריך תלמודא ארבה תוספאה כמאן כרבי דהא רבי ס\"ל דאמר אשתהויי אשתהי בלא שום הוכחה יתירה אלא דבעינן ל' יום כשאר ולדות אפילו אינן ודאין בני ח' ע\"ש. ומ\"ש התוס' לשם ונראה דאפי' בגמרו סימנים דאסור לטלטלו וכו' וזה סותר תחילת דבריהם דבגמרו שרי לטלטלו ולפע\"ד באין ספק דהאי ונראה הוא מדברי בעל התוס' שבא להשיג על הסוגיא לפר\"י כלומר אע\"פ דנראה לפי הסוגיא דתלמודא אמאי דפריש ומשני דבגמרו סימניו שרי לטלטלו כפר\"י אבל לפי משמעות התוספתא נראה דאסור והשתא אין כאן סתירה על פר\"י כיון דמתוך הסוגיא מבואר דלא ס\"ל לאסור כל היכא שיכול להיות בר קיימא כדפי' ותו דאין כ\"כ נפקותא לענין פסק הלכה דאף למאי דכתבו ונראה דאפילו בגמרו סימנים דאסור לטלטלו וכו' היינו לרבנן אבל לרבי ודאי שרי והלכה כרבי וכ\"פ התוס' בפי' בשם ר\"י פרק רבי אליעזר דמילה בדיבור המתחיל בן ח' (דף קל\"ה) וכ\"כ הסמ\"ג בה' מילה נמשך מדברינו אלה שדעת רבינו כדעת התוס' וכך הוא דעת הרא\"ש בפרק הערל אבל ב\"י השיג על רבינו ואמר שאין ראיה מדברי התוספות לדבריו ואמר וגם הם סותרים למ\"ש הרמב\"ם ולפעד\"נ ודאי דהרמב\"ם סובר כל ששהה ל' אינו נפל אפילו לא גמרו כמ\"ש בפירוש בהלכות מילה וה\"ה בגמרו בלא שהה נמי אינו נפל כמבואר לשם אבל רבינו פוסק כדעת התוס' דבעינן תרתי דשהה ל' יום וגמרו סימניו דהשתא אפילו בן ח' ודאי בר קיימא הוה ואע\"פ שלא נתבאר זה בפי' בדברי רבינו ועוד שהרי כתב ואפילו אין ידוע וכו' מ\"מ הדבר מוכרח דלא היתה כוונתו לדיוקא ולומר דבידוע שהוא בן ח' אפילו תרתי דגמרו סימניו ושהה ל' דספק נפל הוא דא\"כ קשה הא דפסקינן הלכה כרשב\"ג ואיירי נמי בבן ח' ודאי כדאיתא להדיא בפרק הערל וכ\"כ הרא\"ש פר\"א דמילה דכל שגמרו סימניו אפי' בן ח' ודאי אמרינן אשתהויי אשתהי ויוצא מידי נפל בל' יום וכ\"כ בפרק הערל גם נ\"י פרק הערל כתב די\"מ דרשב\"ג תרתי בעי וכל שהוא ספק בן ט' ספק בן ח' אעפ\"י שגמרו סימניו ספק נפל הוא תוך ל' יום ע\"ש והיינו כדברי רבינו:","ומ\"ש ואפילו מת ביום ל' כ\"כ הרמב\"ם והסמ\"ג ביום ל' וכך הוא הגירסא במקצת ספרים בפרק החולץ וכך גורסים רש\"י ור\"ח בפר\"א דמילה אבל התוס' והרא\"ש בפרק החולץ גורסים בתוך ל' יום וכן הוא בשאלתות ומ\"מ כיון דלענין דינא אף הרא\"ש מודה דאין חילוק בין יום ל' לתוך ל' כתב רבינו בלשון הרמב\"ם:","\u0003ומ\"ש ל\"ש נפל מן הגג וכו'\u0004 כ\"כ הרא\"ש בפרק החולץ דהלכה כרשב\"ג דאפי' נפל מן הגג ספיקא הוי אם לא שהה כדאיתא פר\"א דמילה ואף על גב דלא חיישינן למיעוטא שאני הכא דמיעוטא דנפלים שכיח חיישינן למיעוט המצוי והוא ממ\"ש התוס' לשם ומ\"ש ואם אין ידוע שכלו לו חדשיו וכו' כ\"כ הרא\"ש בתשובה ומביאו ב\"י וע\"ש דפסק כך מסברא ולפעד\"נ דכיון דאין האשה נאמנת לומר מת יבמה שתינשא לשוק דהואיל ואינו אלא איסור לאו שמא יהא קל בעיניה כדלקמן בסי' קנ\"ח א\"כ בכלל זה כל מה שאומרת כדי שתינשא לשוק אינה נאמנת ועוד דכ\"ש הוא דאפילו במת יבמה דמילתא דעבידא לאיגלויי היא אינה נאמנת כ\"ש הא דלאו עבידא לאיגלויי היא אי כלו חדשיו אי לאו:","ואם הפילה נפל אחרי מותו מתייבמת כ\"כ הרמב\"ם והסמ\"ג והסמ\"ק במצות ייבום וכך מבואר בר\"פ החולץ בפלוגתא דר\"י ור\"ל דאר\"י החולץ למעוברת והפילה שמה חליצה סברא היא דאם יבא אליהו ויאמר דהא דאיעברה מפולי מפלה מי לאו בת חליצה וייבום היא השתא נמי תיגלי מילתא למפרע אלמא דהפילה בת יבום היא. ומ\"ש בשם הר\"פ איתיה בהגהת סמ\"ק והא פשיטא דלא פליג הר\"פ אתלמוד ערוך שהבאתי דבת חליצה וייבום אלא מפרש דלצדדין קאמר דבהפילה נפל גמור דלא כלו חדשיו הא ודאי בת יבום היא דלא הוי ולד כלל אבל אי איכא לאסתפוקי שמא כלו לו חדשיו אסורה להתייבם דחשיב ולד בכלו לו חדשיו כדמוכח בנזיר וחולצת ומיהו אם לדין יש חשובה דנזירות שאני דבנדרים הלך אחר משמעות הלשון אבל לגבי יבום נפקא לן מלהקים שם ומלא ימחה פרט לזה שאין שמו מחוי ובילדתו מת שמו מחוי ועיין בתוס' ר\"פ החולץ במ\"ש התוס' בד\"ה והא ל\"ל (דף ל\"ה) ותו דבפרק יוצא דופן תנן להדיא בן יום אחד פוטר מן היבום ומסיק הב\"ע דבן יום א' בן קיימא דקים ליה שכלו חדשיו אלמא דאפי' קים ליה שכלו חדשיו אינו פוטר אא\"כ חי שעה א':","\u0003שאלה לא\"א הרא\"ש וכו'\u0004 כלל נ\"ב וברור הוא דאיירי דידוע היה דנגמר שערו וצפרנו דאל\"כ אפי' חיה ל' הוי ספק נפל להרא\"ש אם אינו ידוע שנולד לט' חדשים. ודין נולד לט' חדשים דהוי בר קיימא לא ביארו רבינו ויש בזה מחלוקת בגמרא ובפוסקים דלרבי יהודה בפ' בנות כותיים ומייתי לה בסוף פרק הערל דאמר דיה חדשה וקסבר שיפורא גרים וקסבר יולדת לט' יולדת למקוטעים א\"כ הכל תלוי בחדשי לבנה ואם בעל ופירש אפי' לא נולד בסוף ט' אלא מיד בר\"ח של תשיעי הוי בר קיימא וגם לא בעינן ח' חדשים הראשונים שלימים אלא אפי' נתעברה בסוף החדש הראשון יולדת בתחלת תשיעי וכ\"כ התוס' להדיא בפרק בנות כותים וכתב הריב\"ש בסימן תמ\"ו דמדברי הרמב\"ן בספר תורת האדם נראה שפוסק כר' יהודה ומביאו ב\"י אבל מדברי הרמב\"ם בפ' א' דייבום מבואר שפוסק כשמואל דאמר כחסידים הראשונים ופליגי אר' יהודה ואומר שם דחדשי העיבור הוה חדשים שלימים כ\"א ל' יום ויולדת לט' אינה יולדת למקוטעין והילכך כל היכא שלא שהה ל' יום הוי ספק נפל אפי' נולד בחדש תשיעי ואפילו גמרו סימניו ואין ראיה לומר שהרי עינינו רואות בזמנינו שרוב נשים יולדות בר קיימא פחות מט' חדשים גמורים דכיון שאין בועלין ופורשין אין טבילתן ראייה וכ\"פ הריב\"ש לשם לאיסור גם הר\"ש בן הר\"ש בר צמח פוסק כך דבעינן שלימים כדעת הרמב\"ם ומביאו ב\"י אלא שבזה חולק שלדעתו אם בעל ופירש אפי' לא נגמרו ט' שלימים ולא שהה ולא נגמרו סימניו הוי ולד גמור ופוטר אמו מן החליצה ומן היבום וטעמו שעתה נשתנו הענינים ומיהו נ\"ל דאף לדעתו בעינן ח' חדשים הראשונים שלימים דהא איהו לא ס\"ל כרבי יהודה דאמר שיפורא גרים אלא בעינן ח' חדשים של ל' יום לה\"ר יונה אפילו הוא מתחיל באמצע חדש לבנה אלא דלא בעינן חדש התשיעי שלם לגמרי כדפי' ולענין מעשה צ\"ע. וכל זה לענין חליצה אבל לענין אם הולד ממזר כגון אשה שנתעברה מבעלה סוף סיון וילדה תחלת כסלו אע\"פ שאין ביניהם כ\"א ה' חדשים לא חיישינן לומר שהיתה מעוברת קודם לכן דהא ביולדת לז' הכל מודים לרבי יהודה דיולדת למקוטעין ומשמע דמודים נמי דשיפורא גרים דהכל תלוי בחדשי לבנה וחוזר דין בן ז' לרבנן כדין בן ט' לר' יהודה וכדאיתא בפרק בנות כותים וכדפי' בסמוך דכשתולין בחדשי לבנה אפילו נתעברה בסוף חדש מיד שיגיע תחלת החדש מונין לה חדש שני ולפ\"ז אפי' הפילה בתשרי ושמעו הולד בוכה לא חיישינן שהיתה מעוברת קודם לכן דאיפשר לו לבכות לה' חדשים דחדש חמישי לבן ז' כחדש שמיני לבן ט' ואין ספק שבן ח' בוכה ויונק אלא שהוא נפל וכך פסק ה\"ר דוראן כמו שכתב ב\"י בשמו לקמן בסוף הספר והרב בהגהת ש\"ע מבואר לעיל בסימן ד':","\u0003האומר זה בני וכו'\u0004 משנה ואוקימת' דגמרא פרק י\"נ (דף קל\"ד) ובקידושין פרק האומר (דף ס\"ד) פירש\"י דבדלא מוחזק לן באחי דקיימא הך איתתא בחזקת שאינה זקוקה ליבם הלכך אם אמר יש לי בנים דאחזקה קמייתא הוא דמוקים לה נאמן ואי אתי אח לאחר מכאן ואמר אחוה דמיתנא אנא לאו כל כמיניה דאהני דיבורא לחזקה עכ\"ל וכך פירשב\"ם בפרק י\"נ והוצרכו לפרש כך דאי לאו הכי קשה מה לנו לנאמנותו הלא כיון דלא הוחזק לן באח אינה זקוקה ליבום אלא ודאי אתי לאשמעינן אפי' אתי אח לאחר מכאן וכו' והרא\"ש בפרק האומר כתב ואפי' אתו סהדי דאית ליה אח מותרת לשוק עכ\"ל ולפ\"ז ודאי הך דיש נוחלין דהאומר זה בני נאמן דמוקמינן לה בדמוחזק לן באח ונאמן הואיל דבידו לגרשה ומה לו לשקר וכדאמר התם רב יוסף היינו נמי אפי' אי אתי אח לאחר מכאן וכו' אי נמי אפי' אתו סהדי דאית ליה אח נמי מותרת לשוק דהא הך די\"נ דמוקמינן בדמוחזק לן באח בגוונא דהאומר הוא דמוקמינן בדלא מוחזק לן דאית ליה אח וכי היכי דהתם אפי' אתו סהדי ה\"נ דכוותא ולכן כתב רבינו תרוייהו אפי' הוחזק באחים ואפי' אם באו אח\"כ עדים שיש לו אחין כפי הנוסחאות המדוייקות בספרי רבינו:","\u0003ומ\"ש אבל אם יש עדים שיש לו אחים וכו'\u0004 פי' כיון שקדמו עדים דאית ליה אחי ולא היה מוחזק דאית ליה בני לא אמרינן מה לו לשקר הואיל דבידו לגרשה דלא אמרינן מה לו לשקר כי עדים דמי ואתו עדים ועקרי לחזקה ודין זה הוא ע\"פ דעת הרי\"ף והרמב\"ם והרא\"ש גבי היה מוחזק באחין ואמר אין לי אחין וכו' דאינו נאמן דלקמן בסי' קנ\"ז ס\"ו אבל להרז\"ה שחולק דנאמן להתיר לעולם ופסק כשינוייא דאביי בפרק האומר והלכה כרבי דמ\"ל לשקר כי עדים דמי ואתו עדים ועקרי לחזקה א\"כ לפי זה האומר זה בני נאמן אפי' אי קדמו עדים דאית ליה אחי ולא הוה מוחזק דאית ליה בנים אפ\"ה אין כאן אלא חזקה לייבום ואתי מ\"ל לשקר ועקרה לחזקה ונאמן וב\"י הבין מדברי הרמב\"ם רפ\"ג דסובר כך ותימה דהלא לא פסק הרמב\"ם כאביי אלא ודאי אינו נאמן ס\"ל ולפי דפשוט הוא לפי שיטתו סתם דבריו ולא פירש. כתב רשב\"ם בפרק י\"נ דהא דקתני זה בני נאמן אע\"ג דמוחזק לן באח ה\"ה נמי אם אמר יש לי בנים נאמן להתירה אלא משום סיפא אצטריך ליה למיתני הכי וכו' וכ\"כ הרמב\"ם רפ\"ג האומר זה בני או שאמר יש לי בנים ה\"ז נאמן ואחריהם נמשך רבינו ודקדקו ג\"כ שכתבו בסתם לאורויי לן דהא דתנן בפ' האומר מי שאמר בשעת מיתתו יש לי בנים נאמן לאו דוקא בשעת מיתתו ודלא כתירוץ האחרון של תוס' לשם בד\"ה רבי סבר שכתבו די\"ל דאי מוחזק לן באחי לא יהא נאמן במ\"ש בשעת מיתתו יש לי בנים דבשעת מיתה לא שייך למימר מ\"ל לשקר אי בעי פטר לה בגט דשמא אין לו כח עכ\"ל דלפ\"ז מתני' די\"נ דמוקמינן לה בדמוחזק לן באחי דנאמן מטעם מ\"ל לשקר אינו אלא בדאמר כך קודם מיתתו ומ\"ה תנן התם בסתם האומר זה בני נאמן אבל בס\"פ האומר דאיירי בדלא מוחזק לן באחי תנן מי שאמר בשעת מיתתו:","\u0003אמר בשעת קידושין יש לי בנים וכו'\u0004 ברייתא בפרק האומר פליגי בה רבי ורבי נתן והלכה כרבי מחבירו דאינו נאמן לאוסרה וס\"ל לרבינו דהך פלוגתא איירי בדלא מוחזק לן בבני כלומר דלא ידעינן אי אית ליה בני אם לאו הלכך לר' נאמן לומר יש לי בנים אפי' מוחזק לן כאחין כדמוקמינן בפרק י\"נ ותו לא מהימן לומר בשעת מיתה אין לי בנים ורבי נתן פליג דנאמן אף לאסור לחומרא דמילתא דעבידא לאיגלויי הוא וחיישינן לדברי הבעל והכי הוה סלקא אדעתיה מעיקרא בפרק האומר דבהא פליגי רבי ורבי נתן וכחב הרא\"ש לשם דהכי הוה לפי המסקנא והסוגיא דפ' י\"נ ודלא כשינוייא דאביי פרק האומר וה\"ה נמי בפלוגתא דר' ור' נתן באומר בשעת קידושין אין לי אחים ובשעת מיתה אמר יש לי אחים נמי בכה\"ג היא בדלא מוחזק לן באחי ואע\"ג דמוחזק לן דלית ליה בני אפי' הכי לרבי נאמן לומר אין לי אחים הואיל ובידו לגרשה ומ\"ל לשקר ולפיכך אם חזר ואמר בשעת מיתה יש לי אחים אינו נאמן לחזור מדיבורו ור\"נ פליג דנאמן אף לאסור לחומרא והלכה כרבי אבל בדמוחזק לן דאית ליה אחי ואמר אין לי אחין אינו נאמן לסתור החזקה להרא\"ש כמ\"ש בסימן קנ\"ז. וממילא נמי בדמוחזק לן דלית ליה בני אינו נאמן לומר יש לי בנים לסתור החזקה ואיכא לתמוה למה לא כתב רבינו שני דינים אלו בפי' ואפשר דס\"ל לחלק דבחזקה דלית ליה בני כיון דאיפשר דיש לו בן ולא ידעינן ליה לפיכך נאמן לעולם לומר יש לי בנים ואינו דומה לאומר אין לי אחין דהתם ודאי איפשר דאית ליה אחין והוא לא ידע דלא ראיתי אינה ראיה כנגד חזקה דאית ליה אחים וכך חילק ה\"ה בפ\"ג דיבום אצל מ\"ש הרמב\"ם דעד א' נאמן להעיד שנולד בן לבעלה וכ\"כ בסמ\"ק דנאמן לומר יש לי בנים אפי' מוחזק לן בלא בנים אלא דהראב\"ד והרשב\"א ס\"ל דאין חילוק ולעולם אינו נאמן לסתור החזקה ע\"ש ומ\"ה ג\"כ לא היה צריך רבינו לפרש בדלא מוחזק לן באחי ואמר בשעת קידושין אין לי אחים וחזר ואמר יש לי אחים דאינו נאמן דזה נלמד במכ\"ש דכיון דאף במוחזק לן באחי ואמר יש לי בנים אינו נאמן לחזור מדיבורו בשעת מיתה ולומר דאין לו בנים כל שכן בדלא מוחזק לן לא בבני ולא באחי ואיפשר דיש לו בן ואמר בשעת קידושין אין לי אחין דאינו נאמן לחזור מדיבורו בשעת מיתה ולומר יש לי אחין ועוד דהוי בכלל מ\"ש בסימן קנ\"ז לא היה מוחזק באחים ואמר יש לי אחים אינו נאמן אלמא דאפי' היכא דלא אמר תחלה אין לי אחים אינו נאמן א\"כ כ\"ש דאינו נאמן אם חוזר מדיבורו שהרי בתרוייהו מיירי דלא מוחזק לן בבני כנ\"ל ליישב דברי רבינו:","והרמ\"ה כתב שחולצת ולא מתייבמת טעמו דפסק כר\"נ ואע\"ג דקי\"ל כרבי מחבירו שאני רבי נתן דרביה דרבי ורביה דאבוה הוה ואין הלכה כתלמיד במקום הרב ועוד דסוגיין דעלמא דמ\"ל לשקר לאו כעדים דמי ומפרש דר\"נ ה\"ק דכיון דמרע ליה לדבוריה בשעת מיתה עקריה מ\"ל לשקר לגמרי וקמה לה בחזקה דמעיקרא והילכך אי מעיקרא הוה מוחזק לן באחי ולא מוחזק לן בבני ודאי חולצת ולא מתיבמת דשמא יש לו בן כדבריו הראשונים ואפי' אי מעיקרא לא הוה מוחזק לן לא באחי ולא בבני ובחזקת שאינה זקוקה ליבם היא מ\"מ כיון דהשתא אתא אח ואמר אחוה דמיתנא אנא או אתו סהדי דאחוה דמיתנא הוא חיישינן נמי שמא יש לו בן וז\"ש ר' נתן אף נאמן לאוסרה כלומר דבריו האחרונים שקולים כמו הראשונים ולא ידעינן הי מינייהו שיקראו לפיכך חולצת ולא מתייבמת ועיין במ\"ש הר\"י בנכ\"ה ח\"ג. מיהו נראה דאף להרמ\"ה בדאחזוק לן בבני ואמר אין לי בנים אינו נאמן לאוסרה אפילו אתא חד ואמר אחוה דמיתנא אנא ואפילו אתו סהדי ואמרי דאית ליה אח וטעמא דמילתא דהשתא ליכא למימר מ\"ל לשקר והוציאה מחזקתה:","\u0003כתב הרמב\"ם ע\"א נאמן וכו'\u0004 בפ\"ג והראב\"ד השיג עליו וכתב ה\"ה שהרשב\"א ובעל המאור הסכימו לדעת הרמב\"ם גם הסמ\"ג והסמ\"ק פסקו כן אבל בתשובת הרשב\"א אלף רנ\"ב כתב איני רוצה להכניס ראשי בין המחלוקת אע\"פ שיראה לפשוטן של דברים כדברי הרמב\"ם וסוף דבריו ומ\"מ אפילו לדברי הראב\"ד חוששין לעד וחולצת ולא מתייבמת וכו' נראה דאף ע\"פ דלהלכה הסכים הרשב\"א לדעת הרמב\"ם כמ\"ש ה\"ה מ\"מ אמר הלכה ואין מורין כן ושלא תינשא לשוק עד שיחלוץ לה יבמה וע\"ל בסימן קנ\"ח בע\"א שמעיד שמת יבמה לשם נאריך בזה בס\"ד:","\u0003וכתב עוד מי שזינה וכו'\u0004 בס\"פ אלמנה לכ\"ג איתמר הבא על ארוסתו בבית חמיו רב אמר הולד ממזר ושמואל אמר הולד שתוקי פירש\"י ספק ממזר וקאמר רבא בלישנא קמא דרב דאמר ממזר דדיימא מעלמא פי' חשודה מאחרים אבל לא דיימא מעלמא בתר דידיה שדינן ליה אמר רבא מנא אמינא לה דקתני במתני' בכהן שבא על אשה באונס או בפתוי וילדה תאכל בתרומה משום בנה דמחזקינן ליה בכהן וה\"ד אילימא דדיימא מעלמא אמאי תאכל אלא לאו דדיימא מיניה לחודיה ולא דיימא מעלמא וקא שדינן ליה אבתריה וכ\"ש ארוסה א\"ל אביי לעולם אימא לך כל היכא דדיימא מיניה אף ע\"ג דלא דיימא מעלמא אמר רב הולד ממזר מ\"ט דאמרינן מדאפקרה נפשה לגבי ארוס אפקרה נפשה לעלמא ומתני' שהיו שניהם חבושים בבית האסורים ומפרש הרמב\"ם דהך סוגיא אתיא כמ\"ד תרומה בזמן הזה דאורייתא ולפיכך ס\"ל לאביי ורבא דתרומה דאורייתא דינו שוה לשאר איסורא דאורייתא אבל למאי דקי\"ל דתרומה בזמן הזה דרבנן וכמ\"ש הרמב\"ם בפ\"א דתרומות ובארתיו בארוכה בי\"ד סי' של\"א בס\"ד נשתנה דינם ולענין תרומה פסק הרב כלישנא קמא ולקולא כרבא וז\"ש לשם בפ\"ו מה' תרומה וז\"ל ואף ע\"פ שהדבר ספק הואיל ובלא קידושין הוא שמא מאחר נתעברה הרי הולד בחזקת זה שבא עליה והוא שלא יצא עליה קול עם אחר אלא הכל מרננין אחריה עם זה הכהן ע\"כ אבל לענין איסור יבמה לשוק דאורייתא פסק לחומרא וז\"ש הרמב\"ם אלא לעולם ספק הוא ולהחמיר דנין בו דמשמע לשונו הוא דמכח חומרא דנין בזה והיינו כדדחי אביי וס\"ל להרמב\"ם דאיפשר דאפילו רבא מודה ביבום דלהחמיר דנין בו ואפ\"ה לענין ארוסה שעיברה פסק הרב בפט\"ו מהא\"ב כרבא דלא הוי ספק ממזר אלא בדדיימא מעלמא וטעמו כיון דלהאי איסורא ולהאי היתירא יש להקל בדדיימא מיניה לחודיה אף ע\"ג דאיסורא דאורייתא הוא ובתר דידיה שדינן ליה וכמו שנתבאר לעיל בסי' ד' ובזה נתיישבו דברי הרמב\"ם על נכון וה\"ה נתקשה בהם. והקשה המרדכי בפ\"ב דיבמות על דברי הרמב\"ם מהא דתנן מי שיש לו בן מ\"מ לאתויי ממזר פוטר אשת אביו מן היבום אלמא דלא חיישינן לשמא זינתה עם אחר ותירץ דמיירי הך מתני' שהיו שניהם חבושים בבית האסורין וכדמוקי אביי למתני' דס\"פ אלמנה לכ\"ג כדפי' ואכתי איכא למידק בלשון הרמב\"ם שאמר ואמרה זה העובר ממנו הוא ואפי' הוא מודה לה אע\"פ שהוא בנו לענין ירושה וכו' דמאי ואפי' דקאמר דמשמע לא מיבעיא באינו מודה לה והלא באינו מודה לה פשיטא דאינו בנו כלל לשום דבר כדלעיל בסימן ד' ואפשר לומר דאינו מודה לה אין פירוש שהוא מכחישה אלא דהוא שותק או שהוא אלם או שהלך לו אבל העיקר הוא דה\"ק ל\"מ באינו מודה לה אלא מכחישה דהוי ספק לענין יבום וחולצת ולא מתייבמת אלא אפי' הוא מודה נמי הוי ספק לענין יבום אבל מ\"ש אעפ\"י שהוא בנו לענין ירושה וכו' לא קאי אלא על מ\"ש מקודם ואפילו הוא מודה לה כלומר אע\"פ שהוא מודה לה דאז הוא בנו לענין ירושה דבמה שנוגע בממון פשיטא דכיון שמחזיקו בבנו דיורש הוא נכסיו דלא יהא אלא אחר אילו בעי למיתב ליה מתנה מי לא מצי יהיב וכדאיתא בפי\"נ אבל לענין איסור יבמה לשוק לאו כל כמיניה לשוייה בנו ולעולם ספק הוא דמדאפקרה נפשה לגבי דידיה דילמא אפקרא נפשה לעלמא וחולצת ולא מתייבמת:","\u0003האשה שהלך בעלה ובנה למ\"ה וכו'\u0004 כ\"פ הרמב\"ם בפ\"ג ונראה מדבריו שם שלמד כך מדין היה לה חמות דר\"פ האשה בתרא דכיון דהתם אינה חוששת שמא ילדה חמותה וכבר ניתן לה יבם במ\"ה מפני שלא גזרו בדבר זה חלא נעמיד אותה על חזקתה ה\"נ הכא אמרינן העמד אותה על חזקתה ודין ה\"ל חמות כתבו רבינו בסוף סימן קנ\"ז:","\u0003הלכה היא ובעלה ובנה וכו'\u0004 משנה ס\"פ האשה שלום והטעם בכולן דאינה נאמנת להוציאה עצמה מחזקתה שהיתה בו בשעת הליכה להקל אלא להחמיר וחולצת ולא מתייבמת. ומ\"ש וכתב הרמב\"ם בד\"א וכו' בפ\"ג והכי מוקי לה בפרק האשה בתרא אבל הרי\"ף והרא\"ש השמיטו אוקימתא זו מפסקיהם ונראה דס\"ל דדוקא באשה שהלך בעלה וצרתה למ\"ה דכתב רבינו בסמוך התם הוא דאיכא למיחש לשמא ילדה צרתה ולד של קיימא דהא שכיח טובא ונמצא אתה מצריכה כרוז לכהונה וכו' ומ\"ה תנן בר\"פ האשה בתרא לא תינשא ולא תתייבם פי' לעולם וכאוקימתא דר' חנינא התם אבל בהלכה היא ובעלה וכו' דתנן בסתמא חולצת ולא מתייבמת משמע פשטא דלעולם שריא בחליצה ולא חיישינן הכא לדילמא אתו סהדי ואמרי כדקא אמרה איהי ונמצא אתה מצריכה כרוז לכהונה דאין לנו לחוש מעצמנו דילמא איכא סהדי אא\"כ שיצא קול בכאן דאיכא סהדי במ\"ה כמו שהוכיחו התוספות בפרק יש נוחלין (בבא בתרא דף קלה) ולפ\"ז הני אוקימתי דפרק האשה בתרא דרב פפא מוקי לה בגרושה ורב חייא בריה דרב הונא אמר באומרת אני והוא נחבאנו במערה אינו אלא לפי סברת המקשה שהשוה דינים אלו וקאמרי דאף לדידיה לא קשיא אבל לאו דסמכא נינהו הני אוקימתי דקושטא הוא דדיניהם חלוקים וכפשטא דמתני' דאיכא לחלק שפיר בין חששא דדלמא ילדה דשכיח ובין חששא דלמא אתי סהדי דלא שכיח כנ\"ל דעת הרי\"ף והרא\"ש ומיהו לענין מעשה יש להחמיר כהרמב\"ם ורבינו שהביא דבריו:","האשה שהלך בעלה וצרתה וכולי עד לא היתה זו חלוצה בריש פרק החולץ אפסיקא הילכתא כריש לקיש דפסולה מדכתיב ובן אין לו עיין עליו פירוש הואיל ובאותה שעה היה ראוי להתקיים אינה בת יבום וחליצה ולפי טעם זה אפילו היתה צרתה מעוברת בשעת חליצה של זו נמי לא פטרה ההיא חליצה כיון דההיא שעתא לא הוית שייכא ההיא חליצה הואיל ואחת מהן מעוברת ואיכא הכא עיין והכי מבואר בסוגיא ובפירוש רש\"י למאי דמייתי סייעתא לריש לקיש מהאשה שהלך בעלה וצרתה למ\"ה וכו' ואף על גב דדחינן לההוא סייעתא עיקר דבריו דחלוצה לא פטרה הואיל ואחת מהן מעוברת לא נדחה ע\"ש (בדף ל\"ו ע\"א):"]],["\u0010c0\u0011\u0010y0\u0011מי שיש לו אח מכ\"מ אפי' הוא ממזר זוקק אשת אחיו ליבום \u0010y1\u0011בין קטן בין גדול \u0010y2\u0011אפי' הוא גוסס או פצוע מכות שאינו יכול לחיות מהן לא תינשא כ\"ז שהוא חי ובלבד שנולד בחייו \u0010y3\u0011אפי' לא יצא אלא ראשו ורובו לאויר העולם קודם שימות \u0010c1\u0011\u0010y4\u0011ואפי' עבד או שפחה נאמנים להעיד עליו שהוא אחיו מאביו \u0010y5\u0011אבל אם נולד אחרי מותו או שהוא אחיו מאמו אינו זוקק אשתו ליבום \u0010y6\u0011גרים שנתגיירו ועבדים שנשתחררו הרי הם כזרים ואין להם אחוה זה עם זה לענין יבום אפי' אח' מהם הורתו שלא בקדושה ולידתו בקדושה והשני הורתו ולידתו בקדושה ואפי' הם תאומים ונולדו בקדושה הרי הם כזרים ואין להם אחוה עד שיהיו שניהם הורתם ולידתם בקדושה \u0010c2\u0011\u0010y7\u0011כתב רב שרירא גאון נפלה לפני מומר ביון שהורתו ולידתו בקדושה זקוקה ליבם ומתעגנה עד דחליץ לה ורב יהודה כתב אי כד נסבה בעלה הוי יבם מומר לא בעי חליצה מיניה ואם היה הבעל מומר ויושבת תחתיו ומת בהמרותו בלא בנים אינה צריכה יבום דהא לאו אחיו הוא ואין זקוק לה חליצה ע\"כ \u0010c3\u0011\u0010y8\u0011ולא ידענא למה לא תהיה אשת מומר זקוקה ליבם \u0010y9\u0011וגם מה חילוק יש בין אם היה יבם מומר כשנישאת או לא:\u0010c4\u0011\u0010y10\u0011 לא היה מוחזק באחין ואמר יש לי אחין אינו נאמן בא אחד ואמר אני אחיו אינו נאמן ואפי' עד אחד מעיד עליו שהוא אחיו אינו נאמן להוציאה מחזקתה \u0010c5\u0011\u0010y11\u0011היה מוחזק באחין ואמר אין לי אחין או שאמר על מי שהוא מוחזק שהוא אחיו אינו אחי כתב ה\"ר זרחיה הלוי שהוא נאמן להתירה והרמב\"ם כתב שאינו נאמן וכן דעת רב אלפס וכן הוא מסקנת א\"א הרא\"ש ז\"ל \u0010y12\u0011לא היה מוחזק באחין ויצא קול שיש עדים במדינת הים שיודעים שיש לו אחין הרי זו חוששת ותמתין עד שיבואו העדים ויעידו \u0010y13\u0011אשה שאין לה בן ולא אחין לבעלה וחמותה וחמיה במדינת הים \u0010y14\u0011ומת בעלה בכאן מותרת לינשא ולא חיישינן שמא ילדה חמותה זכר והיא זקוקה לו \u0010y15\u0011יצתה חמותה מכאן מעוברת חוששין שמא ילדה זכר:",["מי שיש לו אח מ\"מ אפילו אם הוא ממזר זוקק את אשת אחיו לייבום משנה וגמרא פ\"ב דיבמות (דף כב):","\u0003ומ\"ש בין קטן בין גדול משנה פרק יוצא דופן (נדה דף מג:\u0004 מד.) תינוק בן יום אחד זוקק ליבום:","ומ\"ש אפי' הוא גוסס או פצוע מכות שאינו יכול לחיות וכולי משנה פרק קמא דאהלות אפילו גוסס ואפילו מגוייד זוקק ליבום: ומ\"ש ובלבד שנולד בחייו כלומר שנולד יבם זה בחיי אחיו דאל\"כ אינו זוקק ליבום דהוה ליה אשת אחיו שלא היה בעולמו ואינה זקוקה ליבום דכי ישבו אחים יחדו כתיב שהיתה להם ישיבה אחת בעולם כדאיתא ברפ\"ב דיבמות (דף יז:) ובפ' יוצא דופן (נדה מד.):","\u0003ומ\"ש אפי' לא יצא אלא ראשו ורובו לאויר העולם קודם שימות אחיו כ\"כ הרמב\"ם בפ\"א:\u0004 ","ומ\"ש ואפי' עבד ואפילו שפחה כאמנין להעיד עליו שהוא אחיו מאביו כ\"כ הרמב\"ם בפ\"ד והוא מדאמרינן בפרק החולץ (יבמות ד' לט:) דאפי' קרוב ואשה נאמנים בזה משום דגלויי מילתא בעלמא הוא ומשמע דה\"ה לעבד ושפחה דמ\"ש וכתב הרמב\"ם דה\"ה לקטן שהוא מכיר ונבון כתב הרי\"ף דה\"מ דקרוב ואשה נאמנים היכא דליכא חשדא אבל היכא דאיכא חשדא לא וכתב הריב\"ש בסימן קפ\"ב שנראה לו לפי לשון הרי\"ף שאין אשה וקרוב נאמנים לומר זה אחיו של פלוני כשמעידין כן בשעת מעשה אלא שאם אמרו כן קודם מעשה שאין מעידין לא על ממון ולא על איסור הוחזק על פיהם ע\"כ ואין נראה כן מדברי הפוסקים אלא אפי' לא אמרו כן אלא בשעת מעשה סומכים עליהם וגם בהגמ\"י פ\"ד כתוב דמשמע מדברי הרי\"ף דלא סמכינן אהני אא\"כ הם מסיחים לפי תומם וכתבו דאין נראה לראבי\"ה אלא אפי' כמתכוונים להעיד נאמנים וכ\"כ במרדכי פרק מצות חליצה:","\u0003ומ\"ש אבל אם נולד אחר מותו כבר נתבאר.\u0004 ומ\"ש או שהוא אחיו מאמו ברפ\"ב דיבמות מייתי' מקראי דאינו זוקק ליבום אלא אחיו מאביו אבל אחיו מאמו ולא מאביו לא:","גרים שנתגיירו ועבדים שנשתחררו הרי הם כזרים ואין להם זה ע\"ז יבום אפילו אחד מהם הורתו שלא בקדושה והשני הורתו ולידתו בקדושה משנה בפרק נושאין (דף צז:) ומ\"ש ואפילו הם תאומים ונולדו בקדושה כלומר אבל הורתם היתה שלא בקדושה הרי הם כזרים ואין להם אחוה עד שיהיו שניהם הורתם ולידתם בקדושה ברייתא שם:","כתב רב שרירא גאון נפלה לפני מומר וכולי ורב יהודאי כתב אי כד נסבה בעלה הוי יבם מומר לא בעי חליצה מיניה ואם היה הבעל מומר ויושבת תחתיו וכולי עד ואינה זקוקה לחליצה כל זה כתוב במרדכי פרק החולץ שהעתיק מספר העיטור אלא שבמקום שכתוב בספרי רבינו ורב יהודאי כתב שנראה שבא לחלוק על דברי רב שרירא כתוב שם וכתב רב יהודאי שנראה שאינו חולק על דברי רב שרירא אלא מפרש דבריו וה\"א בפ\"א מהלכות יבום העתיק דברי רב שרירא ודברי רב יהודאי כמו שכתבם המרדכי וכתב שהרשב\"א תמה על כל דברי רב יהודאי ושמדברי הרמב\"ם נראה שלא כדברי רב יהודאי שכתב מי שיש לו אח מ\"מ אפילו ממזר או עובד כו\"ם הרי זה זוקק את אשתו לייבום ולא חילק בין אם היה עובד כו\"ם בשעת הנישואין בין המיר אח\"כ וכ\"ש בבעל מומר ואח כשר שאם מת שהיא זקוקה לחליצה וליבום וכמ\"ש הרשב\"א ז\"ל עכ\"ל :","ומ\"ש רבינו ולא ידענא למה לא תהיה אשת מומר זקוקה ליבום ודאי קושטא דמילתא הכי דאשת מומר זקוקה לייבום ואפילו קדשה אחר שהמיר ואפי' בנו או בן בנו עד כמה דורות אע\"פ שנשארו בהמרתם כ\"ז שהם בני ישראליות או מומרות קידושיהן קידושין ונשותיהם הישראליות או המומרות זקוקות ליבום כדמשמע בספ\"ק דיבמות אהא דאמר רב אסי עכו\"ם שקידש בזמן הזה חוששין לקידושיו חיישינן שמא מי' השבטים הוא ואסיקנא דלא היא משום דגמירי דבנתי דההוא דרא אצטרויי אצטרו משמע הא לאו הכי הוה חיישינן לקידושיו וזה דבר פשוט כביעתא דכותחא וכבר כתב כן מהר\"י קולין ז\"ל בשורש פ\"ה ויש לתמוה על מי שעלה על דעתו היתר זה ועל רב יהודאי שנכתב בשמו איני תמה משום דגמירי דמאור עינים הוה ולפעמים היו תלמידיו כותבין בשמו מה שלא עלה על דעתו וכמבואר אך על תלמידיו הכותבים כן יש לתמוה ועל בעל העיטור שהעתיק דבריהם יש לתמוה למה לא רדפם וכתתם עד החרמה דדבר פשוט הוא דאין לדברים אלו שורש וענף ולא שום צד סמך כלל ואוי לו למי שמיקל בזה ודבר פשוט הוא שאין דברים הללו אמורים אלא בבן ישראלית או מומרת אבל בן עכו\"ם או שפחה אפילו מישראל שלא המיר כבר נתבאר דינו בסימן שקודם זה:","ומ\"ש רבינו דלא ידע מה חילוק יש בין אם היה יבם מומר כשנשאת או לא זה נתבאר בהגהות מרדכי פרק החולץ דטעמא משום דס\"ל דנישואין מפילין וכיון דבשעת נישואי אחיו היה מומר היה אסור לה באותה שעה ושוב אינה נופלת לפניו וכתוב שם שיש סוברים דאפי' לא היה מומר בשעת נישואי אחיו כיון שהיה מומר בשעת מיתה אינה זקוקה דס\"ל דמיתה מפלת וכתוב בת\"ה סי' רכ\"ג דהיכא שהיבם נאנס בקטנותו ונטמע בין העכו\"ם ונתגדל ביניהם עד שנעשה גדול בשנים ואע\"פ כן לא חזר לדת האמת אם בעודו בקטנותו בין העכו\"ם נתקדשה יבמתו לאחיו ודאי זקוקה היא אפי' לדברי האומרים דנישואין מפילין דהוי כמו נתקדשה בעודו יהודי ואח\"כ המיר דכל מעשה קטן עד שיהא בן שלש עשרה שנה ויום אחד לא חשיב וכשגדל ועמד בהמרותו הוי כהמיר אז וכיון דנישואין מפילים הרי היא זקוקה לו וז\"ל המרדכי בפרק החולץ כתוב בתשובת הגאונים יבמה שנפלה לפני מומר פטורה מן החליצה ומן היבום היכא דליכא יבם אחר אלא הוא ולא הביאו שום ראיה לדבריהם וכתב רש\"י בתשובה דלא סמכינן עלייהו כלל ואע\"פ שחטא ישראל הוא ואם קדש קידושיו קידושין וחולץ ולא מייבם ונראה לה\"ר מאיר להביא ראיה לדברי הגאונים מדפריך פ' הגוזל (בבא קמא קי:) וכו' וכתב הר\"ם אע\"פ שהבאתי ראיה לדברי הגאונים לא מלאני לבי לעבור על דברי רש\"י כאשר בא מעשה לידי ושאלו להר\"מ על יבמה שהיו לה שני יבמים הגדול מומר והקטן הלך למדינת הים אם הגדול המומר יכול לחלוץ מפני תקנת העיגון והשיב שלא לעשות מפני שיש לה יבם ישראל ואזלינן הכא לחומרא והכא לחומרא עכ\"ל ובת\"ה כתב שאחד מהחכמים שהיו בימיו כתב שיש לסמוך על דברי המתירים וחכם אחד כתב דלית לן לאסוקי אדעתא להקל נגד דברי רש\"י שהרי מהר\"ם אף ע\"פ שהביא ראיה לדברי הגאונים כתב דעבדינן הכא לחומרא והכא לחומרא ונראה מדברי ת\"ה שכך הוא דעתו לאסור כדברי רש\"י ומהר\"ם ז\"ל והאריך הרבה בדבר עיין עליו ועיין בהגהות מדרכי פרק החולץ ומהרי\"ק ז\"ל כתב בשורש קע\"ז על יבמה שנפלה לפני יבם מומר ועד אחד מעיד שמת אותו מומר שהיא מותרת כיון שרוב הפוסקים מתירין יבמה ע\"פ עד אחד ואפי' אם היה המנהג כדברי האוסרים מ\"מ פשיטא שבזיקת יבם מומר שרבו הפוסקים המתירים אותה בלא חליצה ואע\"ג דפשיטא שאין לסמוך על דבריהם וחלילה להקל בשל ערוה שלא כדעת רש\"י אשר כל ישראל שותים מימיו הנאמנים וכמ\"ש הר\"מ עצמו שלא מלאו לבו לעבור על דברי רש\"י מ\"מ איכא תרי רובי להתיר אשה זו על דא אמינא דאתתא דא שריא עכ\"ל הרי כל האחרונים מסכימים לאסור יבמה שנפלה לפני מומר. אשה שנפלה לפני יבם מומר ונישאת לזר כתבתי משפטה בסימן קנ\"ט: כתוב בת\"ה סי' רכ\"ג יש נוהגים להתנות בשעת קידושין שלא תיזקק ליבם אם תפול לפניו וצ\"ע בדבר דבמרדכי פרק הפועלים מייתי ירושלמי דהמתנה על מ\"ש בתורה תנאו בטל כמו אם מתנה שלא תיזקק ליבום אמנם בתלמודא דידן לא משמע הכי מדפריך בפ' הגוזל אלא מעתה יבמה שנפלה לפני מוכה שחין תיפוק בלא חליצה דאדעתא דהכי לא קדשה נפשה וכו' מ\"מ גילוי דעת הוא דאין בדעתו לחול הזיקה שתתייבם מחמת הנישואין כמו שמחלקין התוס' דדוקא מן האירוסין אמרינן דאדעתא דהכי לא נתקדשה ולא מן הנישואין והאידנא רגילין לעשות קידושין ונישואין יחד בשעת חופה וכיון דבההיא שעתא מתנה אנישואין נמי מתנה ועיין בפ' המגרש (גיטין פד:) בגמרא ובתוס' פ' אע\"פ (כתובות נו:) דהתם מפרש כמה חילוקין במתנה על מ\"ש בתורה עכ\"ל. ואני תמה ע\"ז מאחר שאין ההיתר מבואר בתלמודא דידן ובתלמוד ירושלמי מבואר לאיסור היאך אפשר להקל בדבר וע\"כ נשתקע הדבר ולא ראינו ולא שמענו מי שהתנה כן :","לא היה מוחזק באחין ואמר יש לי אחין אינו נאמן בא אחד ואמר אני אחיו אינו נאמן וכו' בקידושין פרק האומר (סד.) תנן מי שאמר בשעת מיתתו יש לי בנים נאמן יש לי אחים אינו נאמן ובגמרא (שם) אלמא נאמן להתיר ואין נאמן לאסור נימא מתניתין דלא כר' נתן דתניא בשעת קידושין אמר יש לי בנים בשעת מיתה אמר אין לי בנים בשעת קידושין אמר אין לי אחים בשעת מיתה אמר יש לי אחים נאמן להתיר ואין נאמן לאסור דברי רבי ר' נתן אומר אף נאמן לאסור אמר אביי מתני' דלא מוחזק לן באחי ולא מוחזק לן בבני אמר יש לי בנים נאמן יש לי אחים אינו נאמן לאו כל כמיניה לאסור לה אכולי עלמא ברייתא דמוחזק לן באחי ולא מוחזק לן בבני דאמרינן מה ליה לשקר מאי קאמר מיפטרא מיבם מצי אמר פטרנא לך בגיטא רבי סבר מה לי לשקר כי עדים דמי ואתו עדים עקרי חזקה ור' נתן סבר מה לי לשקר כי חזקה דמי לא אתי חזקה ועקרא חזקה ופירש\"י דלא מוחזק לן האי גברא לא באחי ולא בבני וקיימא הך אתתא בחזקת שאינה זקוקה ליבם הילכך אמר יש לי בנים בחזקה קמייתא הוא דקא מוקים לה הילכך נאמן ואי אתי אח לאחר מכן ואמר אחוה דמיתנא אנא לאו כל כמיניה דאהני דיבורא לחזקה אמר יש לי אחים ואין לי בנים לאו כל כמיניה דמפיק לה מחזקה. ברייתא דקאמר ר' נתן נאמן לאסור עליו דמוחזק לן האי גברא באחי וכו' עד ואילו ה\"ל אחי הוה הדר ביה בשעת מיתה וכתב רבינו ירוחם אם יש לו עדים בודאי שיש לי אחים אינו נאמן כשאמר יש לי בנים אפילו לדברי ר' דע\"כ לא קאמר ר' אלא במקום חזקה אבל במקום עדים לא וכ\"כ מורי ה\"ר אברהם בן אסמעאל עכ\"ל וכתב הרא\"ש בתשובה (כלל נ\"ב סי' ה') שנשאל על אשה שנישאת לבעל ומעולם לא נשמע ולא נודע שהיה לו אח אמנם אחי האשה אמר שהיה באשכנז וראה שם אחד שאמר שהיה אחיו ועתה מת בעלה והיא רוצה לינשא והשיב הא מילתא דפשיטא כיון שהאשה זאת עומדת בחזקת שאין אחים לבעלה אינה נאסרת לשוק על מאמר אחיה דתנן בפרק האומר מי שאמר בשעת מיתתו יש לי אחים אינו נאמן ואמרינן עלה בגמרא לימא מתני' דלא כר' נתן וכו' הרי אנו רואים שהבעל אינו נאמן לומר יש לי אחים היכא דלא מוחזק לן באחי אפילו לר' נתן דלאו כל כמיניה דבעל להוציאה מחזקתה ולאסרה לעלמא ואע\"פ דאליבא דרבי דהלכתא כוותיה דנאמן להוציאה מחזקתה (ולהתירה לשוק אפ\"ה לאוסרה אין נאמן היכא דלא מוחוק לן באחי אליבא דכ\"ע וכ\"ש אחיה שאינו נאמן להוציאה מחזקתה) ולאסרה לעלמא ואפילו עד כשר לא היינו חוששין לעדותו דכל היכא דאיתחזק היתרא ואמר עד אחד שהיא אסורה אינו נאמן כדאיתא בפרק הניזקין (גיטין נד:) ת\"ר היה עושה עמו בטהרות וא\"ל טהרות שעשיתי עמך נטמאו וכו' היה עושה עמו בזבחים וכו' שעשיתי עמך ביום פלוני נתפגלו אינו נאמן מ\"ש רישא ומ\"ש סיפא אמר אביי כל שבידו נאמן רבא אמר כגון דאשכחיה ולא אמר ליה ובתר הכי אשכחיה וא\"ל ועוד בנדון זה אין זה אומר שהוא יודע שהוא אחיו אלא שא\"ל הלה שהוא אחיו של מת ואילו היה עומד בפנינו ואומר אני אחיו של מת לא היינו משגיחים על דבריו אא\"כ מביא עדים שהוא אחיו כדתנן בפרק יש נוחלין (בבא בתרא קלד.) האומר זה אחי אינו נאמן וכן עובדא דמרי בר איסק (כתובות כד:) דאתא ליה אחא מבי חוזאה והיינו לענין ממון והוא הדין לענין איסור שאינו נאמן להוציאה מחזקת היתר וכל שכן זה שאינו מעיד אלא מפיו ולא דמי להא דאמרינן בפרק י\"נ (קלה) ההוא דהוה מוחזק דלית ליה אחין ואמר בשעת מיתתו דלית ליה אחין אמר רב יוסף למאי ניחוש לה חדא דהא מוחזק לן דלית ליה אחי ועוד הא אמר בשעת מיתתו דלית ליה אחי אמר אביי והא אמרי דאיכא עדים במ\"ה דידעי דאית ליה אחי ומסיק התם דא\"ל רבא לרב נתן בר אמי זיל חוש לה דשאני התם שיש קול שיש עדים במ\"ה הילכך ראוי לחוש לקול ולהמתין עד שיחקרו אם יש עדים אבל בנדון זה אפילו אם הוא אמת מ\"ש אחיה אינו קול כלל הילכך אין לחוש כלל ומותרת לשוק עכ\"ל ואחר כך (כתב) הבנתי מתוך השאלה שלא היה אחי האשה מכיר לאחי בעלה אלא על פיו שא\"ל שהיה אחיו ולכך כתבתי בתשובה ועוד בנדון זה אין אחיה אומר שהוא יודע שהוא אחיו אלא שא\"ל אחר שהוא אחיו ומתוך כתבך הבנתי שאחי האשה הכירו שהיה אחי בעל אחותו ומעתה ידעו ועוד שכתבתי לחזק הדבר בטל מ\"מ האשה מותרת משאר טעמים שכתבתי עכ\"ל:","היה מוחזק באחים ואמר אין לי אחים או שאמר על מי שהוא מוחזק שהוא אחיו אינו אחי כ' הרז\"ה שהוא נאמן להתירה וכו' בקידושין פרק האומר על סוגיא זו שכתבתי בסמוך רי\"ף לא הביא כלל זה וכתב הרא\"ש וז\"ל הרז\"ה כ' מהלכו' הרב נראה דהלכה כרבי ואין נאמן לעולם לאסור דקיימא לן הלכה כרבי מחבירו ולפיכך לא הזכיר זאת הברייתא מחלוקת דרבי ורבי נתן והקשה עליו הרמב\"ן דאדרבה היה צריך להביאה כדי שנדע דרבי קאמר אפילו היכא דמוחזק לן באחי ובשעת מיתה קא הדר ביה ומרע לדיבוריה אפ\"ה נאמן להתיר ואין נאמן לאסור דלא שמעינן ליה ממתניתין ופירש הוא דלהכי השמיט רב אלפס דהך שינוייא דשני אביי לאו דסמכא היא דודאי היכא דמוחזק לן באחי לא מהימן למימר אין לי אחים להתירה לשוק ושינוייא דחיקא הוא דשני אביי לאוקומי מתני' כר' נתן וליתיה להך שינויא אלא ברייתא נמי בדלא מוחזק לן באחי ואפי' הכי לר' נתן נאמן אף לאסור לחומרא דמילתא דעבידא לאיגלויי חיישינן לדברי הבעל כדקס\"ד מעיקרא וכן מוכח הסוגיא דיש נוחלין דהיכא דמוחזק לן דאית ליה אחי דלא מהימן למימר דלית ליה אחי דתנן התם זה בני נאמן ואוקמוה דצריכא למימר דאע\"ג דמוחזק לן דאית ליה אחי נאמן לומר זה בני ומשמע דוקא זה בני הוא נאמן לומר שאינו סותר לגמרי החזקה אבל לסתור לגמרי החזקה ולומר אין לי אחים אינו נאמן ועוד אמרי' התם ההוא דהוה מוחזק לן דלית ליה אחי וכו' א\"ל אביי והא אמרי דאיכא עדים במ\"ה דידעי דאית ליה ומסיק אמר ליה רבא לרב נתן בר אמי חוש לה והשתא לקלא בעלמא חיישינן ועקרינן לחזקה וגם את דיבורו שאמר דלית ליה אחי כל שכן היכא דמוחזק לן דאית ליה אחי ואמר אין לי אחים שאינו נאמן להכחיש החזקה לגמרי אף על פי שנאמן להוציאה מחזקת יבום ולומר זה בני להתירה לשוק מ\"מ אינו נאמן לעקור חזקת אח דמגו להכחיש את החזקה לגמרי לא אמרינן ועוד דקי\"ל בפ\"ק דבתרא (ו.) לא אתי מה לי לשקר ועקרא החזקה ובפ' האשה (קטו.) מיבעיא לן הילכך לא סמך הרי\"ף אהך שינוייא להקל ולכך השמיטה עכ\"ל: והר\"ן ז\"ל כתב ולענין הלכה משמע דקי\"ל כרבי דאינו נאמן לאסור דקיי\"ל הלכה כר' מחבירו ויש לדקדק דאי קיימא לן כר' נקטינן דאפילו כדמוחזק לן דאית ליה אחי נאמן לומר אין לי אחים ואילו בפרק י\"נ אמרינן ההוא דהוה מוחזק לן דלית ליה אחים כו' ומסקנא א\"ל רבא לרב נתן בר אמי זיל חוש לה אלמא כל היכא דמוחזק לן דאית ליה אחין לא מהימן איהו למימר דלית ליה וניחא לי דהתם שאני דאיכא קלא דאיכא סהדי במ\"ה וכל היכא דאיפשר למיקם עלה דמילתא אפומיה דסהדי נטרינן להו ולא מקילינן באיסור א\"א אבל בחזקה שאין אנו יודעים שיש עדים בדבר שיהא איפשר להתברר על פיהם נאמן משום מה לי לשקר והרי\"ף השמיט כל זה וכתב הרמב\"ן בספר המלחמות שסמך לו על מה שהביא משנתינו דאמר ויש לי בנים נאמן שמשם יש ללמוד ג\"כ לאומר אין לי אחים שהוא נאמן דליכא למימר דלא דמי משום דאומר יש לי בנים לא מרע לחזקה דאחים ואומר אין לי אחים מרע לחזקה דליתא שהרי איפשר שהיו לו ומתו שאילו אומר לא היו לו אחים מעולם ודאי לא מהימן והיינו ההיא דבפרק י\"נ דאמרינן והאיכא עדים במ\"ה דאלמא משום מגו לא מהימן לאכחושי קלא וחזקה אלו דבריו ז\"ל ומ\"מ לפי זה מי שהיה מוחזק שיש לו אחים ואמר בשעת מיתה שאין לו אחים נאמן אבל הרמב\"ם כתב בפ\"ו מהלכות יבום שאינו נאמן ונראה שסמך לו על אותה סוגיא שבפרק י\"נ דאביי גופיה דאוקי הא אוקימתא הכא אמר התם הא איכא עדים במ\"ה וכולי ורבא נמי אסיק זיל חוש לה ולא הסכימה דעתו באלו החילוקים שכתבנו עכ\"ל: וכתב רבינו ירוחם רוב הפוסקים פסקו כרבי. והרמ\"ה פסק כרבי נתן דאף על גב דהלכה כרבי מחבירו שאני רבי נתן דרביה דרבי ודאבוה הוה עכ\"ל ולענין הלכה נקטינן הלכה כדברי רוב הפוסקים שפסקו כרבי ובפ\"ג מהלכות יבום על מ\"ש הרמב\"ם נאמן ע\"א להעיד ליבמה שמת בעלה ומתייבמת על פיו או שמת יבמה או שניתן לבעלה בן להתירה לזר וכתב עליו הראב\"ד זה הדמיון אינו מחוור אם אמרו בעדות מיתה דנאמן עד אחד אפילו בדבר שהיא אינה נאמנת משום דמילתא דעבידא לאיגלויי ולא משקר יאמרו בניתן לבעלה בן דאיפשר דמשקר אפי' בעל עצמו דאמר יש לי בנים והיה מוחזק באחים ובלא בנים אינו נאמן להתירה בלא חליצה עכ\"ל כתב ה\"ה הרב בעל המאור סבור כדעת רבינו וכן הכריע הרשב\"א ז\"ל וכתב דאין ראיה מבעל דשאני עד דאף היא דייקא ומינסבא משא\"כ בבעל דסמכא עליה לגמרי ע\"כ ואני אומר שאף בבעל אין הדין פשוט כן שכבר נתבאר למעלה שאם אמר יש לי בנים אף על פי שמוחזק באחים נאמן כדאיתא בהדיא בפרק י\"נ וסתמא קתני לה אע\"ג דמוחזק דלית ליה בני נאמן ואיפשר דכיון דמסקינן במוחזק באחים ואמר אין לי אחים אינו נאמן בדבוריה נגד חזקה וה\"ה נמי במוחזק דל\"ל בנים ואמר יש לי בנים אינו נאמן דכאן וכאן להתיר הוא בא וכי אמרינן דנאמן ה\"מ דלא ידעי אי אית ליה בני או לא אבל במוחזק דלית ליה בני לא ויש לחלק ביניהם ולומר דשאני אחים דלא תליא מילתא בדידיה ואיפשר דאית ליה אחים והוא לא ידע שהרי לא ראינו אינו ראיה נגד חזקה אבל באומר יש לי בנים דמילתא תליא בדידיה ואיהו אמר דאית ליה בכל גווני נאמן כנ\"ל עכ\"ל:","לא היה מוחזק באחין ויצא קול שיש עדים במ\"ה שיש לו אחים הרי זו חוששת ותמתין עד שיבואו עדים ויעידו היינו ההיא עובדא דבפרק י\"נ (דף קלה.) שכתבתי בסמוך ההוא דהוה מוחזק לן דלית ליה אחי ובשעת מיתה נמי אמר לית לי אחי א\"ר יוסף למאי ניחוש לה א\"ל אביי והא אמרי דאיכא עדים במ\"ה דידעי דאית ליה אחי ומסיק דא\"ל רבא לרב נתן בר אמי זיל חוש לה וז\"ל הרמב\"ם בפ\"ג לא היה מוחזק באחים ויצא עליה קול שיש שם עדים שיעידו שיש לבעלה אחים והעדים במדינה אחרת אפילו אמר הוא בשעת מיתתו אין לי אח הרי זו חוששת ותמתין עד שיבואו העדים שאמרו וישאלו וכתב ה\"ה בפרק יש נוחלין ההוא דהוה מוחזק דלית ליה אחי וכו' וכתב הרמב\"ן דלאו בקול בעלמא אסרוה אלא בדאמרי דאיכא עדים כלומר שהוחזקו קול בב\"ד וכן נראה דעת הרשב\"א ויש מהמפרשים אומרים דלא בעינן קול מוחזק בב\"ד וזה דעת רבינו עד כאן לשונו :","\u0003אשה שאין לה בן ולא אח לבעלה וחמותה וחמיה במ\"ה ומת בעלה בכאן מותרת לינשא וכו'\u0004 משנה ר\"פ בתרא דיבמות (קיט.) וטעמא משום דכולי האי לא חיישינן שמא נתעברה וילדה וזכר היה:","ומ\"ש רבינו ומת בעלה בכאן לאו דוקא בכאן אלא איידי דאמר דחמיה וחמותה במדינת הים אמר דבבעלה לא צריכין למימר שהיה במ\"ה דאפילו מת בכאן נמי הוי דינא הכי:","ומ\"ש יצתה חמותה מכאן מעוברת חוששין שמא ילדה זכר שם במשנה פלוגתא דתנאי והלכה כת\"ק דאמר הכי וכן פסק הרמב\"ם ודלא כדכתב רבינו ירוחם בשם הרמ\"ה והלכה כרבי יהושע :"],["\u0003מי שיש לו אח מ\"מ וכו'\u0004 משנה ואוקימתא דגמרא פרק ב' דיבמות (דף כ\"ב) ועיין לעיל במ\"ש ריש סימן קנ\"ו: ומ\"ש אפילו לא יצא אלא ראשו ורובו וכו' כך כתב הרמב\"ם בפרק א' וטעמו מדקאמרינן בסתמא שהיתה להם ישיבה אחת בעולם אלמא דאין לו שיעור אפי' שעה אחת בלחוד וכל שיצא ראשו ורובו חשיב ילוד בפרק המפלת וה\"ל נמי ישיבה יחד שעה אחת בעולם:","\u0003ומ\"ש ואפילו עבד וכו'\u0004 בפרק החולץ איפסיקא הילכתא דאפילו אשה וקרוב נאמנים גלויי מילתא בעלמא נינהו והרמב\"ם בפ\"ד מבאר דה\"ה עבד דדינו כאשה לכל דבר ורבינו כתב דה\"ה שפחה אע\"ג דאיכא תרתי אשה והיא שפחה דטעמא דאינן אלא מגלי דהדין גברא פלן והיא ניהי איתתא פלונית כדכתב הרי\"ף לשם אבל עדות עכו\"ם מל\"ת לא ואע\"ג דהרמב\"ם ז\"ל כתב לשם שטעם דין זה שוה לטעמו של דין עדות אשה אפ\"ה לא התיר כאן עדות עכו\"ם כיון דלא אשכחן בגמרא דהתירו אלא אשה וקרוב אין לנו להוסיף אלא מאן דדמי להו ושאני עדות אשה דהוחזקו כבר להשיא ע\"פ עכו\"ם מל\"ת מטעם דמתוך חומר וכו' ועי' במ\"ש לקמן על דין זה בסי' קס\"ט:","\u0003כתב רב שרירא גאון וכו'\u0004 כ\"ז כתוב במרדכי פרק החולץ וגם כתב שרש\"י חולק וס\"ל דזקוקה ליבם דאעפ\"י שחטא ישראל הוא וקידושיו קידושין וחולץ ולא מייבם ונראה להר\"ם להביא ראיה לדברי הגאונים מפ' הגוזל בתרא דבנפלה לפני מוכה שחין ה\"א דתיפוק בלא חליצה דאדעתא דהכי לא קידשה נפשה מעיקרא אי לאו מטעמא דמינח נייח לה דטב למיתב טן דו וכו' אבל לגבי מומר ליכא למימר הכי דאנן סהדי דלא ניחא לה כי יעבירנה על דת לבא עליה כל זמן שהיא נדה ובהגהות מרדכי כתב דלמהר\"ם אין חילוק בין אם היה מומר בשעת נשואי אחיו אם לאו דבכל ענין אדעתא דהכי לא קדשה נפשה עכ\"ל מיהו לפעד\"נ דאף למהר\"ם יש לחלק דכיון דלא התנה האשה בפירוש שלא תהא זקוקה לו אלא דאנן סהדי דכך היה דעתה מתחלת נישואיה ליכא למימר אנן סהדי בהא אא\"כ דהיה מומר בשעת נישואיה דכיון דסתמא דמילתא הכי הוא לא בעי לאתנויי וכמ\"ש התוס' פרק האיש מקדש ופרק אלמנה ניזונית דיש דברים כן אבל כשלא היה מומר בשעת נישואין דאיכא תרתי ספיקי שמא לא ישתמד יבמה ואת\"ל ישתמד שמא לא ימות בעלה בחיי מומר בלא בנים איפשר דמכנסת עצמה לספק שאפי' ימות בעלה תיזקק ליבום גם מ\"ש בהגמ\"ר לשם כמו השגה על מהר\"ם ממ\"ש התוספות בפ' הגוזל דדוקא מן האירוסין דלא ה\"ל ממנו שום טובה אמרינן אדעתא דהכי לא קדשה נפשה אבל לא במן הנישואין נלע\"ד ליישב דמהר\"ם מפרש דדוקא במוכה שחין איכא למימר האי סברא אבל במומר הדעת נותנת שאינה מכנסת עצמה בשום ספק מחמת חבת בעלה ואף במן הנשואין מיהו למ\"ש מהרא\"י בת\"ה בסימן רנ\"ג נראה דעת הגאונים בהיתר זה אינו מטעם שכתב מהר\"ם אלא מטעמא דנישואין מפילין כיון שהיה מומר בשעת נשואי אחיו לא חיילא עליה זיקה ולפ\"ז אם לא היה מומר בשעת נשואי אחיו חיילא עליה זיקה ההיא שעתא ושוב לא פקעא אפי' היה מומר בשעת מיתה ולפר\"ח דפסק מיתה מפלת אפילו לא היה מומר אלא בשעת מיתה נמי פטורה מן החליצה ומן הייבום וכבר השיב מהרא\"י עליהם בטוב טעם ולפעד\"נ ראיה ברורה לאיסור מדקאמר תלמודא בממזר כיון דלענין יבום מיפטר פטר מזקק נמי זקיק א\"כ מומר נמי דהכל מודים דמיפטר פטר כדלעיל בסימן קנ\"ו מזקיק נמי זקיק דאחיו הוא ואיכא לתמוה למה לא שתו לב הגדולים שלפנינו לראיה זו המפורשת לאיסור ואפשר דאיכא למדחי ולומר דממזר שאני דכיון דנקרא אחיו שהרי אחיו הוא במצות אלא דסלקא אדעתין למילף מאחוה דיעקב הלכך השתא דילפינן מבן אין לו עיין עליו דלא ילפינן מאחוה דיעקב ולא בעינן כשרין דאפילו פסול נמי פוטר הלכך מסתמא נמי זקיק ולא ילפינן מאחוה דבני יעקב כיון דאחיו הוא במצות אבל במומר אפילו לא נילף מאחוה דבני יעקב נמי לא זקיק כיון דלא נקרא אחיו במצות ואע\"ג דמיפטר פטר היינו משום דכתיב ובן אין לו עיין עליו אבל לענין זיקה אינה זקוקה לו ומ\"ה ס\"ל דאם לא היה מומר בשעת נישואין זקוקה לו כיון דנישואין מפילין ואז היתה זקוקה לו ושוב לא פקעה זיקה אף לאחר שנעשה מומר וזה טעם רב יהודאי דפוטר גם אשת מומר משום דלאו אחיו הוא במצות וכל זה דוחק דודאי הויא דמומר נמי נקרא אחיו כמו ממזר ובנ\"י כתב ראיה לאיסור מדתנן חוץ מן האח שיש לו מן השפחה ומן הנכרית משמע דוקא הא אבל מומר זוקק דאי משום דפלח ע\"ז הא ולד נכרית נמי פלח לע\"ז ואפילו הכי אי לאו דלאו אחיו הוא היה זוקק ליבום עכ\"ל. מיהו נראה דאין זה ראיה כלל דהולד שפחה ונכרית שנתגיירו נמי מיירי דאעפ\"י שנוהגים כמנהג ישראל לכל דבר אפ\"ה אינו זוקק ואינו פוטר וכך מבואר ברמב\"ם פ\"א להדיא אבל הראיה שכתבתי אין ספק בה והכי משמע מלשון הרמב\"ם דכתב אפילו היה לו זרע ממזר או עע\"ז ה\"ז פוטר וכו' מי שיש לו אח מ\"מ אפי' ממזר או עע\"ז וכו' מדסידר דינים אלו סמוכין ותכופין זה עם זה משמע דטעמו דכיון דלענין יבום מיפטר פטר מיזקק נמי זקיק וס\"ל דמומר נמי אחיו מקרי דעצמו ובשרו הוא. ולענין הלכה למעשה מהר\"ם גופיה כתב דאעפ\"י שהבאתי ראיה לדברי הגאונים לא מלאני לבי לעבור על דברי רש\"י כאשר מזה בא מעשה לידי ע\"כ. ותו נראה כיון דהגאונים עצמם פסקו להתיר מטעם ראיה אחרת כמ\"ש ועליה חלקו הבאים אחריהם מעתה אין כח לנו להתיר מטעם ראייתו של מהר\"ם כיון שהוא עצמו לא נסמך עליה וכן כתב מהרא\"י דאפילו היכא דהוא מומר גמור בשעת קידושין ומיתה אין להקל מדברי רש\"י ומהר\"ם לפוטרו מחליצה ועוד דהרמב\"ם והסמ\"ג כתבו להדיא דעע\"ז זוקק אשת אחיו ליבום וכיון דסתמא קאמרי משמע אפילו היה עע\"ז בשעת נישואי אחיו גם אין להקל ולחלק דאינהו מיירי בעע\"ז ומקיים שאר כל המצות אבל מומרים לכל התורה כאותו שלפנינו מודו דאינו זוקק דסתם עע\"ז דקאמר תלמודא היינו שהוא כופר בכל התורה מיהו מהרא\"י כתב תקנה לזה מה שנהגו להתנות בשעת קידושין שלא תיזקק ליבום אם תפול לפניו ומתנה כן בתנאי כפול דהשתא כשהיבם מומר נתבטלו הקידושין למפרע והוי מתנה בעלמא ונראה דתקנה זו יש לה סמוכות מההיא דריש כתובות דתקינו רבנן לגבי גיטין דלא מהני טענת אונס משום צנועות ומשום פרוצות ופרכינן ומי איכא מידי דמדאורייתא לא הוי גט ומשום צנועות ומשום פרוצות שרינן אשת איש לעלמא אין כל דמקדש אדעתא דרבנן מקדש ואפקעינהו רבנן לקידושין מיניה תינח דקדיש בכספא קדיש בביאה מאי איכא למימר שויוה רבנן לבעילתו בעילת זנות והשתא כל שכן הכא דמתנה בפירוש שלא תיזקק ליבום וכו' דפשיטא דנעקרו הקידושין למפרע כשתפול לפניו והוי מעות מתנה כדכתבו התוס' לשם להדיא וממילא יהיו כל בעילותיו בעילת זנות למפרע והא עדיפא דאין גורמין בידים אלא ממילא הוא וגם לא הוי מתנה על מ\"ש בתורה הא דכתב המרדכי פרק הפועלים דאיתא בירושלמי המתנה על מ\"ש בתורה תנאו בטל כמו אם מתי לא תיזקק ליבום ומייתי ליה בת\"ה יש לחלק דדוקא באומר אם מתי לא תיזקק ליבום אעפ\"י שכפל תנאו ה\"ל מעמ\"ש בתורה כיון שהוא רוצה בקידושין אלא שלא תיזקק לייבום אבל במתנה בפירוש שאם תיזקק לייבום שלא תהא מקודשת למפרע אין זה מעמ\"ש בתורה כיון שאם מת בלא בנים לא היתה אשתו מעולם ולא קשיא א\"כ בעילותיו למפרע הויין בעילות זנות כדאיתא להדיא פ' השולח ופ' האשה רבה דקא משני אין שויוה רבנן לבעילתו בעילת זנות כ\"ש כשהוא מתנה בפירוש שלא תהא מקודשת אם תפול לפני יבם דלית לן למיחש לבעילת זנות כיון דבשעת ביאה לא נתכוין לזנות. שוב מצאתי תשובת מהרא\"י כ\"י שכתב למהר\"ר יונה והר\"ר ידידיה שכך נהגו בנויישטט לאחר יום הרג רב להתנות בכה\"ג ותשובה אחרת השגה עליו מפרק המדיר דקדשה על תנאי וכנסה סתם וכו' דלדברי התוס' אפילו קדש וכנס על תנאי ואח\"כ בעל סתם צריכה גט ולהרי\"ף והרמב\"ם אפי' בעל לאלתר אחולי אחליה לתנאה וצריך גט ומהרי\"ח מוסיף דאפילו בעל ע\"ת צריכה גט דמסתמא התנאי לא היה אלא משום כתובה אא\"כ יתנה בפירוש אף לענין גט וא\"כ בעינן תנאי בשעת ביאה וא\"כ מסתברא נמי לפ\"ז דבעינן תנאי על כל ביאה וביאה ואם לא התנה צריכה גט דאין לומר כיון שהתנה בבעילה ראשונה דליהוי בעילת זנות אם לא יתקיים התנאי גם כל בעילותיו יהיו בחזקה זו מן הסתם דאדרבה יש לנו לומר אטו מי שאכל שום וריחו נודף יחזור ויאכל שום כו' ועוד אפי' יהא מתנה כך בכל ביאה וכו' מ\"מ לכתחלה אסור לעשות כן ע\"כ בקיצור וכל זה יש ליישב דאין דומה תנאי זה לשאר תנאים דכיון דהעונות גרמו לגזירות שנטמעו בין העכו\"ם א\"כ מוטל עלינו לתקן שלא יתערבו יותר בין העכו\"ם כי מי ירצה להתחתן עם זה על ספק שתתעגן כל ימיה וע\"י כך ילך וישא נכרית ויטמע בין העכו\"ם ולפיכך לא נקרא זה לכתחילה אלא כמו דיעבד הוא דמאחר דאחיו מומר צריכין אנו לתקן לזה שישא ישראלית וגם לא נקראו בעילותיו בעילות זנות שהרי היא אשתו ומיוחדת לו כל ימיו והויא למפרע כפלגש דשריא ולא נקרא בעילת זנות ועוד דאיהו ודאי בועל לשם נישואין אלא דאיהי רוצה בכך שלאחר מותו אם תפול לפני יבם שיהיו כל בעילותיו למפרע שלא לשם קידושין ואדעתא דהכי נתקדשה ונישאת לו אבל איהו גופיה ודאי בשעת ביאה בועל בלי תנאי שהרי הוא לא התנה עמה כלום ואינו דומה לקידש על תנאי וכו' דצריך שיתקיים התנאי בחייו ואם לא יתקיים יהיו בעילת זנות גם לשם הוא התנה עמה ובועל לשם זנות אם לא תקיים התנאי ואינו דומה להכא כל עיקר אחר שכתבתי זה ראיתי למהר\"ר דוד הכהן בתשובה בית תשיעי שכתב ג\"כ סברא זו דלא הויא בעילת זנות והאריך גם התיר אפילו בלא תנאי אלא שאותו נדון לא היה סתם מומר גם כתב דהרמב\"ם ר\"ל דוקא עע\"ז לחוד ולא מומר לכל התורה אבל אין נראה כלל לחלק בכך כדכתבתי לעיל:","ולא ידענא למה לא תהיה אשת מומר זקוקה ליבם כתב ב\"י ודאי קושטא דמילתא הכי דאשת מומר זקוקה ליבום ואפי' קידשה אחר שהמיר וכו': ומ\"ש ואפי' קידשה אחר שהמיר וכו' טעמו דלא מיבעיא קידשה קודם שהמיר דלמ\"ד נישואין מפילין פשיטא דזקוקה ליבום אלא אפילו קידשה אחר שהמיר דאינה זקוקה ליבום למ\"ד נישואין מפילין אפ\"ה יש להחמיר כיון דלמ\"ד מיתה מפלת זקוקה היא ליבום אבל לפעד\"נ דאיפכא מסתברא דבקידשה אחר שהמיר ודאי דקידושיו קידושין דכיון דאין אשה מתקדשת אלא לדעתה והיא פשטה ידה וקיבלה קידושין מן המומר א\"כ רצונה בכך ומקודשת דאעפ\"י שחטא ישראל הוא אבל היכא דקידשה ואח\"כ המיר אנן סהדי דלא קיבלה קידושין ממנו ולא נישאת לו אלא ע\"ד שיחזיק בדת ישראל אבל היכא שיהפוך דתו ע\"ז לא היה רצונה ולא היה דעתה שיהיו קידושין אלא המעות יהיו מתנה ונמשך שכל בעילותיו למפרע יהיו בעילות זנות וכדפי' לעיל ועי\"ל טעם אחר דמומר לא נקרא בשם אחיו דהא אין מצווין להחיותו ואי נקרא אחיו קרי כאן וחי אחיך עמך ומ\"ה שרי להלואתו בריבית דלגבי נשך כתיב אחוה והא דאמר אע\"פ שחטא ישראל הוא היינו בדברים דלא כתיב אחוה כגון קידושין וגיטין ומטעם דילמא הרהר תשובה בלבו אבל לענין יבום לא מהני טעם זה דסוף סוף לא נקרא אחיו כיון דלאו אחיו הוא במצות וכ\"כ בהגה\"ת מרדכי לדעת ר\"ח ואם כן טעם זה מספיק נמי להיכא דהבעל מומר. מיהו כיון דב\"י כתב אוי לו למי שמיקל בזה נהגינן לאיסור אבל לקדש ולהתנות אם יש לו אח מומר כדלעיל כתב בהג\"ה ש\"ע בשם מהר\"י ברי\"ן דשרי לכתחלה וכך עשה מעשה. ונראה דה\"ה מי שהיה לו אח שהלך מפניו ולא נודע ולא נשמע ממנו אם חי אם מת שיכול גם כן לקדש ולהתנות בתנאי כפול שאם ימות בלא בנים ולא יהא נודע אם האח הוא חי או מת כי יהיה בחזקת אבוד כמו עכשיו או יהא נודע שהוא מומר במקום פלוני שלא תהא מקודשת ושרי להתנות כך אפילו לכתחלה:","\u0003לא היה מוחזק באחין וכו'\u0004 משנה בקידושין פרק האומר מי שאמר יש לי אחים אינו נאמן ומוקמינן לה התם וכן בפרק י\"נ דמיירי בדלא מוחזק לן באחי ובחזקת שאינה זקוקה ליבם היא ולאו כל פמיניה דמפיק לה מחזקתו אפילו ע\"א נמי אינו נאמן כנגד חזקה כמו שהביא הרא\"ש ראיה לזה בתשובה הביאו ב\"י.","\u0003היה מוחזק באחין וכו'\u0004 שם בברייתא אמר בשעת קידושין אין לי אחים ובשעת מיתה אמר יש לי אחים נאמן להתיר ואינו נאמן לאסור דברי רבי רבי נתן אומר אף נאמן לאסור ומוקי לה אביי בדמוחזק לן באחי ואפילו הכי סבירא ליה לרבי דנאמן להתיר ולא לאסור וסבירא ליה להרז\"ה דכיון דהלכה כרבי מחבירו א\"כ נקטינן דאף במוחזק באחין ואמר אין לי אחים דנאמן וס\"ל להרז\"ה דזו היא דעת האלפסי אבל הרא\"ש ע\"ש הרמב\"ן כתב דלא קי\"ל כשינוייא דאביי ואף רבי לא קאמר דנאמן להתיר אלא דוקא בדלא מוחזק לן באחי אבל במוחזק לן באחי אינו נאמן לסתור החזקה לגמרי והוא דעת הרי\"ף ז\"ל לדעתו וכן כתב הרמב\"ם והסמ\"ג והסמ\"ק ונראה דלמה שכתב רבינו בסימן הקודם בדין האומר בשעת קידושין יש לי בנים וכו' דאינו נאמן לאוסרה והרמ\"ה חולק וחולצת ה\"ה כאן בלא הוחזק באחים ואמר בשעת קידושין אין לי אחים וחזר ואמר בשעת מיתה יש לי אחים דאינו נאמן לאוסרה אפילו בא אח אח\"כ ואמר אחוה דמיתנא אנא פטורה לגמרי ולהרמ\"ה חולצת ולא מתייבמת דכיון דחזר מדיבורו איתרע מה לי לשקר אבל אם לא היה חוזר מדיבורו נאמן במ\"ש אין לי אחים ואפילו אי אתי אח ואמר אחוה דמיתנא אנא פטורה לגמרי כיון דאיכא מ\"ל לשקר אבל בלא הוחזק באחי ואיהו לא אמר כלום או אפילו אמר יש לי אחים כיון דליכא מ\"ל לשקר מותרת לשוק ודוקא כל זמן שלא בא אח אין חוששין לומר שמא יבא אח דהעמידנה על חזקתה אבל אם בא אחד ואמר אחוה דמיתנא אנא אפילו לא אמר יש לי אחין מ\"מ איתרע לה חזקה ואזלינן בה לחומרא וחולצת ולא מתייבמת דשמא לאו אחיו הוא כיון דליכא סהדי כן נראה מפי' רש\"י פרק האומר שכתב בדלא מוחזק לן באח ואמר יש לי בנים נאמן ואפילו אתא אח וכולי משמע אבל בדלא אמר יש לי בנים צריכה חליצה דהא אתא אח ואיתרע לה חזקה אבל ממ\"ש הרא\"ש לשם וז\"ל נאמן לומר שיש לי בנים ואפילו אי אתי סהדי וכו' משמע מדבריו אבל בדלא אמר יש לי בנים אי אתי סהדי וכו' איתרע לה חזקה אבל באתא אח ואמר אחוה דמיתנא אנא לא איתרע לה חזקה ואחריו נמשך רבינו שאמר כאן בא אחד ואמר אני אחיו אינו נאמן ואפילו ע\"א אינו נאמן וטעמו מפורש בתשובת הרא\"ש שהביא ב\"י בסימן זה. ותו משמע לע\"ד מלשון רבינו ומסדורו דאפילו באומר יש לי אחין ואח\"כ בא אחד ואמר אני אחיו ואפילו ע\"א מעיד עליו כדבריו אינן נאמנין ובזה מתיישב הא דקשה למה לא כתב רבינו דין אמר בשעת קידושין אין לי אחי וכו' והוא דמדכתב באומר יש לי אחים אפילו שלא על ידי חזרה אינו נאמן כל שכן על ידי חזרה דאינו נאמן ואפילו אי אתא אח וכו' ואי אתו סהדי ואמרי דיש לו אח פשיטא דאסורה לשוק ואפילו אמר הבעל מתחילה אין לי אחין אינו נאמן להכחיש עדים דאפילו כנגד חזקה אינו נאמן לשיטת האלפסי והרמב\"ם והרא\"ש כל שכן כנגד עדים אפי' אתו עדים אחר כך ואף על גב דלהרמ\"ה דפסק כרבי נתן נאמן הבעל אף לאסור אפילו על ידי חזרה ומכל שכן דנאמן בלא חזרה לא חשש רבינו לכתוב דעתו כאן כיון דבפרק יש נוחלין תנן בסתמא זה אחי אינו נאמן ובפרק האומר נמי תנן יש לי אחים אינו נאמן דלא כרבי נתן אבל באומר יש לי בנים וחזר ואמר אין לי בנים דלא תנא בה מידי חשש רבינו וכתב מחלוקת הרמ\"ה דחולצת ולא מתייבמת כר\"נ מטעמא דקמה לה בחזקה דמעיקרא דאין לו בנים וה\"ה באומר אין לי בנים בלבד כיון דאף בלא אמירתו היא עומדת בחזקה שאין לו בנים אבל בכאן שעומדת בחזקה שאין לו אחים ואיהו אמר יש לי אחים אינו נאמן להוציאה מחזקתה ודלא כר' נתן כנלע\"ד:"]],["\u0010c0\u0011\u0010y0\u0011כשם שהאשה נאמנת לומר מת בעלה שתינשא כך נאמנת לומר מת בעלה שתתיבם \u0010c1\u0011\u0010y1\u0011והיבם נכנס לנחלה על פיה אבל אינה נאמנת לומר מת יבמה שתינשא לשוק ואין האיש נאמן לומר מת אחי ואייבם את אשתו לפיכך הלכה היא ובעלה ויבמה למ\"ה ובאה ואמרה מת בעלי ואח\"כ מת יבמי או מת יבמי ואח\"כ מת בעלי אינה נאמנת \u0010y2\u0011הלכה היא ובעלה לבד ובאה ואמרה ניתן לי יבם ומת בין שאומרת מת בעלה ואח\"כ מת יבמה או יבמה ואח\"כ מת בעלה נאמנת \u0010c2\u0011כתב הרמב\"ם שעד אחד נאמן ביבמה להעיד שמת בעלה שתתייבם או שמת יבמה שתינשא לשוק \u0010y3\u0011ואפילו עבד ושפחה או עכו\"ם מל\"ת נאמן להעיד במיתת היבם כמו שנאמן במיתת הבעל ודין עדות זה לענין עדים המכחישין זה את זה במיתת הייבם כדין עדים המכחישין זה את זה במיתת הבעל וכן כתב רב אלפס דעד אחד נאמן ביבמה בין להתירה ליבם בין להתירה לעלמא \u0010y4\u0011ואדוני אבי הרא\"ש ז\"ל כתב להתירה ליבם דוקא נאמן ובין אם אומר מת בעלך ובין אם אומר מת בנך ואח\"כ בעליך אבל להתירה לעלמא לא מהימן בין אם אומר מת יבמך בין אם אומר מת בעלך ואח\"כ בנך: \u0010y5\u0011חמש נשים שאינן נאמנות להעיד לאשה שמת בעלה כדפרישית לעיל אינם נאמנות ג\"כ להעיד לה שמת יבמה: \u0010y6\u0011לפיכך נשי ב' אחים שבאות וכל אחת ואחת אומרת מת בעלי ואין להם בנים כל אחת אסורה מפני בעלה של חבירתה שהיא יבמה והיא זקוקה לו ואע\"פ שאשתו נאמנת להעיד עליו שמת לגבי עצמה אין עדותה מועיל לזו שהיא יבמה ואם יש לזו עדים שמת בעלה ולזו אין עדים את שיש לה עדים אסורה משום יבמה ושאין לה עדים מותרת שעל בעלה נאמנת ועל יבמה יש עדים יש לזו בנים ולזו אין בנים ולשתיהן אין עדים את שיש לה בנים מותרת שאין לה בנים אסורה \u0010y7\u0011היו להם כאן שני יבמין ונתייבמו להן שהאשה נאמנת לומר מת בעלי שאתייבם ולענין יבום לא הוצרכו זו לעדות זו ומתו היבמין אסורות לינשא לשוק זו מפני בעלה הראשון של זו וזו מפני בעלה הראשון של זו דשמא עדיין הם חיים הרי זקוקות ליבום אע\"פ שכבר נתייבמו בחזקת שמתו בעליהן נאמנות הן אצל עצמן אבל אי איפשר להתירה לזר אלא בעדות יבמתה שמעידה לה שמת יבמה ואין יבמות מעידות זו לזו שום צד היתר נתייבמו ונתגרשו הרי אלו מותרות לזר:",["כשם שהאשה נאמנת לומר מת בעלה שתינשא כך נאמנת לומר מת בעלה שתתייבם משנה ריש פרק האשה שלום (יבמות דף קיד:):","ומ\"ש והיבם נכנס לנחלה על פיה מימרא דרב חסדא שם (דף קיז) ומ\"ש אבל אינה נאמנת לומר מת יבמה שתינשא לשוק ואין האיש נאמן לומר מת אחי ואייבם את אשתו לפיכך הלכה היא ובעלה ויבמה למ\"ה וכולי משנה שם (דף קיח:) ז\"ל הרמב\"ם בפ\"ג מהלכות יבום אף על פי שהאשה נאמנת לומר מת בעלי ותינשא או תתייבם אין היבמה נאמנת לומר מת יבמי שתינשא לזר הואיל והוא איסור לאו שמא יהא קל בעיניה וכן אין היבם נאמן לומר מת אחי שייבם את אשתו שמא עיניו נתן בה שלא האמינו ע\"א אלא משום התרת עיגונא:","\u0003ומ\"ש הלכה היא ובעלה לבד ובאה ואמרה ניתן לי יבם ומת וכו'\u0004 גם זה שם במשנה ופירש\"י נאמנת ומותרת לשוק בחזקתה הראשונה דהפה שאסר הוא הפה שהתיר כתב הרמב\"ם שע\"א נאמן ביבמה להעיד שמת בעלה שתתייבם וכולי עד כדין עדים המכחישין זה את זה במיתת הבעל בפ\"ג כ\"כ וכתב ה\"ה בפרק האשה רבה (יבמות צג:) בהל' בשם הגאון שנאמן ע\"א להעיד שמת בעלה כדי שתתייבם או שיאמר שמת יבמה כדי שתינשא לשוק:","ומ\"ש ואפילו עבד ואפילו שפחה פשוט הוא שכיון שע\"א נאמן הרי הוא כעדות מיתת הבעל וכ\"נ מן הסוגיא ע\"כ וז\"ל הרי\"ף בפ' הנזכר בעו מיניה מרב ששת ע\"א ביבמה מהו מי אמרינן טעמא דע\"א (משום מילתא דעבידא לאיגלויי לא משקר ה\"נ לא משקר או דלמא טעמא דע\"א) משום דהיא גופא דייקא ומינסבא והכא זימנין (דסניא) (דרחמי) ליה לא דייקא ומינסבא מאי ופשיט רב ששת דע\"א נאמן א\"ד הא לא תיבעי לך דאפי' היא נמי מהימנא דתנן האשה שאמרה מת בעלי תינשא מת בעלי תתייבם אלא כי קא מיבעיא לי למשרי יבמה לעלמא ופשט רב ששת דמהימן ורבא נמי פשט דע\"א נמי נאמן ביבמה מק\"ו לאיסור כרת התרת לאיסור לאו לא כ\"ש וקאמרי רבוותא אע\"ג דדחינן להא דרב ששת ולהא דרבא הנך דחייתא לאו דסמכא נינהו אלא קי\"ל דע\"א נאמן ביבמה כדפשט רב ששת וכדפשט רבא וכן הלכתא עכ\"ל:","ומ\"ש רבינו בשם הרא\"ש ז\"ל שם כתב על לישנא בתרא וא\"ת ביבמה ליבם אכתי מצי למיבעי במת בנך ואח\"כ מת בעליך דומיא דמתניתין דאם יהיה העד נאמן במקום שהיא אינה נאמנת וי\"ל דאה\"נ אלא דהכי הוי מעשה דעל יבמה לעלמא בעו מיניה מרב ששת א\"נ הא לא קא מיבעיא להו דכיון דנאמנת היא עצמה לומר מת בעלי ואתייבם ולא חיישינן שתשקר משום דרחמא ליה כ\"ש שיהיה ע\"א נאמן אפילו במקום שהיא אינה נאמנת דע\"א ודאי עדיף מינה ולא כדהוה קס\"ד מעיקרא דע\"א גרוע מינה להעיד שמת בעלה ותתייבם אלא כיון דהיא מהימנא לומר מת בעלי ואתייבם אע\"פ שהיא בעלת דבר כ\"ש ע\"א ולא חיישינן דילמא רחמא ליה ליבם וסמכא על העד ולא דייקא וכיון דלא חיישינן להכי א\"כ אפי' מת בנך ואח\"כ מת בעליך דהיא לא מהימנא ע\"א מהימן כי תיבעי לך יבמה לעלמא פירש\"י כגון שא\"ל ע\"א מת יבמך או מת בעלך ואח\"כ מת בנך וקשה לפי' מה קא מיבעיא ליה במת בנך ואח\"כ בעלך הא איהי גופה מהימנא וכ\"ש עד אחד כדקאמר הא לא תיבעי לך דהיא נמי מהימנא ועוד למאי דפרישית כיון דפשיטא ליה דע\"א מהני ביבמה ליבם משום דהיא גופא מהימנא לומר מת בעלי ואתייבם וכ\"ש ע\"א הילכך מהימן נמי העד לומר מת בנך ואחר כך מת בעלך אע\"ג דהיא גופה לא מהימנא יבמה לעלמא נמי תיפשוט ליה שע\"א נאמן לומר מת בעליך ואח\"כ מת בנך כמו שהיא עצמה נאמנת לומר מת בעלי ואח\"כ מת בני וכיון שנאמן בזה כמו שהיא עצמה נאמנת לומר מת בעלי ה\"ה נמי שיהא נאמן במת יבמיך שתינשא לשוק במה שהיא אינה נאמנת הילכך נראה דלא מיבעיא ליה אלא במת יבמיך אבל במת בעליך ואחר כך מת בנך פשיטא ליה דעד אחד אינו נאמן אף ע\"ג דהיא מהימנא לומר מת בעלי ואחר כך מת בני משום דלדידה יש להאמין במגו דאי בעיא אמרה מת בעלי ושתקה ממיתת הבן והיתה מותרת לשוק משום שהיינו מעמידין הבן בחזקת קיים אבל בע\"א ליכא מיגו (דאיכא) למיחש שמא שכרוהו שונאיה או הוא בעצמו רוצה לקלקלה וסבר אי מסהידנא אבעל לחודיה כי שמעה שמת גם הבן תחקור ותדע איזה מת תחילה ולא יוכל לקלקלה אבל אי מסהידנא אתרוייהו אבן ואבעל סמכה עלי ומיקלקלת וכתב רב אלפס דפשט רב ששת דמהימן ורבא נמי פשט דע\"א נאמן ביבמה כו' ונ\"ל דברי תימה איך פסקו להקל דע\"כ דחייה דרבא טובה וחזקה היא דחיישינן שמא תעיד שקר במזיד משום דסניא ליה כ\"ש שתסמוך על העד ולא דייקא ואף ע\"ג דפשיטא להו דמשום דרחמא ליה לא שבקה מלמידק איכא טעמא לחלק כמו שכתוב בתוספתא שגדולה שנאת השנואות מאהבת האהובות ושכיח נמי (טפי) דסניא ליה מדרחם ליה כדמוכח בסוף האשה שהלכה (יבמות קיח:) ועוד יותר קשה לה שאם תפול לפניו כשהיא (שונאה אותו ממה שנוח לה שתפול לפניו כשאוהבתו דאף אם תפול לפניו כשהיא) אוהבתו שמא יחלוץ לה ואפילו אם יכניסנה אינה מרווחת כ\"כ כי תוכל למצוא כיוצא בו או יותר טוב ממנו אבל אם תפול לפני מי ששונאתו ע\"כ צריכה היא לינשא לסנויי לה או תתעגן כל ימיה אם אינה רוצה לחלוץ וכן הא דמוקי רב אחא בר מניומי מתניתין בעידי הזמה בהא אידחו מילתא דרב ששת שפיר והא דלא דחי פשיטותא קמייתא דרב ששת ביבמה ליבם ומוקי לה בעידי הזמה לא חשש בעל התלמוד להאריך משום לישנא אחרינא דפשיטא להו דמהימן אבל פשיטותא בתרייתא דחי תלמודא משום דמסתבר דלא מהימן ע\"א כי היכי דאיהי לא מהימנא לכך קשה הדבר להקל וכן במת בעליך ואח\"כ מת בנך אף על גב דאיהי מהימנא ע\"א לא מהימן כדפרישית לעיל אבל מת בנך ואחר כך מת בעליך הוה פשיטא להו דע\"א נאמן אף על גב דאיהי לא מהימנא כדפרישית עכ\"ל. ומתוך זה יתבאר לך שהגירסא הנכונה היה בדברי רבינו אבל להתירה לעלמא לא מהימן בין אם אומר מת יבמיך בין אם אומר מת בעליך ואחר כך מת בנך ולא כספרים דגרסי מת בעליך ואחר כך יבמיך והגירסא בעצמה מוכחת דמשובשת היא דהא במת יבמה אטו מי שאני לן בין מת קודם מיתת הבעל או אחריו ודברים פשוטים הם ורבינו ירוחם כתב אמר ע\"א מת היבם אינו נאמן כך פשוט בפ' האשה רבה וכך הסכימו רוב הפוסקים וכ\"כ הרמ\"ה אבל הרי\"ף כתב בשם הגדולים דקי\"ל כרב ששת וכרבא ותמהו עליו עכ\"ל נראה מבין ריסי עיניו דהרי\"ף יחיד הוא בדבר זה ואין הדבר כן שהרי הרמב\"ם פסק כמותו ומדברי הראב\"ד שכתבתי בסימן שקודם זה על מ\"ש הרמב\"ם להתיר בע\"א מעיד שניתן לבעלה בן משמע שסובר דע\"א נאמן לומר מת יבמה להתירה לשוק וכ\"ש שהרשב\"א ובעל המאור מתירים בזו דהא בעדיפא מינה שרו ומעתה יש לתמוה מ\"ש רבינו ירוחם שרוב הפוסקים הסכימו דאינו נאמן דאדרבה רוב בנין ורוב מנין הסכימו דנאמן שגם הרא\"ש לא גזר אומר לאסור בהדיא ולא כתב אלא שקשה הדבר להקל הילכך כהנך רבוותא דשרו נקטי' עיין בתשובת הרשב\"א סי' אלף ורנ\"ב כי שם כתב דברים דשייכי לסי' זה \u0005וכתב בסי' הנזכר שכל שהאמינו בו ע\"א אפי' עד מפי עד וכל אותם שנאמנים במת בעלה נאמנים כאן וכך הם דברי הרמב\"ם בפרק ג'.\u0006","חמש נשים שאינן נאמנות להעיד לאשה שמת בעלה אינן נאמנות ג\"כ להעיד לה שמת יבמה כן משמע בפשיטות במשנה פ' האשה שלום (יבמות דף קיז) דבתר דקתני האשה שהלכה היא ובעלה למ\"ה ובאה ואמרה מת בעלי תינשא מת בעלי תתייבם קתני הכל נאמנים להעידה חוץ מחמותה ובת חמותה ויבמתה ובת בעלה ומ\"ש כדפרישית לעיל הוא בסי' י\"ז:","ומ\"ש לפיכך נשי שני אחים שבאות וכל אחת אומרת מת בעלי ואין להם בנים כל אחת אסורה מפני בעלה של חבירתה כו' משנה פ' בתרא דיבמות (קיט:)","\u0003ומ\"ש היו להן כאן יבמין ונתייבמו כו'\u0004 שם במשנה נתייבמו ומתו היבמים אסורות לינשא ר' אליעזר אומר הואיל והותרו ליבמים הותרו לכל אדם וידוע דהלכה כת\"ק ודבר פשוט הוא דהיינו דוקא כשמתו היבמים האלו בלא בנים אבל אם היו להם בנים מותרות לינשא לעלמא שהרי עכשיו אין שום אחת מהן זקוקה לעדות חבירתה שאפי' היה בעל חבירתא קיים היתה אסורה להתייבם לו כיון שיש לה בנים מאחיו וכן משמע מפירש\"י וכ\"כ ה\"ה בפ\"ג ומ\"ש נתייבמו ונתגרשו הרי אלו מותרות לזר כ\"כ הרמב\"ם ז\"ל בפ\"ג ופשוט הוא מהטעם שכתבתי בסמוך דשוב אין שום אחת מהן זקוקה לעדות חבירתה שאפילו אם היה בעל חבירתה קיים היתה אסורה לו מפני שהיא גרושת אחיו:"],["\u0003כשם שהאשה נאמנת וכו'\u0004 משנה ריש פרק האשה שלום והא דכתב רבינו כשם כו' נראה דרצה לומר שהטעם שוה בשניהם דכשם דלא חיישינן בדאמר מת בעלה שתינשא דקאמרה בדדמי משום דחיישינן לקלקולא שמא יבא בעלה לאחר שניסת לשוק ותהא מקולקלת הכי נמי חיישא באומרת מת בעלה שתתייבם:","ומ\"ש והיבם נכנס לנחלה על פיה שם מימרא דרב חסדא ריש (דף קי\"ז) מדכתיב יקום על שם אחיו לנחלה אמר רחמנא והרי קם. ומ\"ש אבל אינה נאמנת לומר מת יבמה וכולי כתב הרמב\"ם בפ' ג' הואיל ואינו אלא איסור לאו שמא יהא קל בעיניה וכן אין היבם נאמן לומר מת אחי שייבם את אשתו שמא עיניו נתן בה וכו' ופשוט הוא לשם במשנה בסוף הפרק ותו נראה דהא אפילו המביא גט ממדינת הים כיון שצריך לומר בפני נכתב ובפני נחתם לא ישאנה משום חשד וכדלעיל סימן י\"ב כל שכן במעיד מת אחי כדי שייבם את אשתו דלא ישאנה. ומ\"ש לפיכך הלכה היא ובעלה ויבמה וכו' גם זה פשוט במשנה סוף הפרק והני בין ובין לא איצטריך דפשיטא היא דאין חילוק אלא איידי דברישא תנא דאיכא לחלק וכדלעיל בסימן קנ\"ו. תנא בסיפא דאין חילוק:","כתב הרמב\"ם וכולי טעם מחלוקת זה מבואר בב\"י באורך ולענין הלכה אעפ\"י שהרמב\"ם השוה מדותיו דכשם דע\"א נאמן במיתת הבעל כך נאמן ביבמה להעיד שניתן לו בן להתירה לשוק מכל מקום הראב\"ד מחלק דבניתן לו בן דלאו מילתא דעבידא לאגלויי היא אין עד אחד נאמן ואע\"פ דבש\"ע בסימן קנ\"ו סעיף ח' וכאן ס\"ג פסק כהרמב\"ם בתרוייהו הנה בהגה\"ה כתב דיש חולקים ואם כן היה נראה דאין להקל אמנם לפע\"ד נראה דבעד אחד דמעיד במיתת הבעל דאיכא חששא דתתעגן כל ימיה דאי איפשר להשיג עדות אחר יש לסמוך על הרי\"ף והרמב\"ם וטובא רבוותא הסמ\"ג והסמ\"ק ובעל המאור והרשב\"א כמ\"ש ה\"ה פ\"ג ונ\"י פרק האשה רבה ומ\"ש בהגהות ש\"ע ויש אומרים דאין עד אחד נאמן לומר שמת יבמה להתירה לעלמא עכ\"ל. אלמא דחוששין לחומרא כהרא\"ש ובנו רבינו וה\"ר ירוחם ע\"ש הרמ\"ה נראה ודאי דלא בא הרב אלא לגלות דאיכא רבוותא דמחמירין ולכן יש ליזהר שלא להקל לכתחלה היכא דאיפשר להשיג עדות אחר על ידי טורח אבל במקום עגון ודאי דיש להתיר כהני רבוותא דמקילין שהם רוב בנין ורוב מנין וכ\"פ מהר\"ם פדוואה בסימן פ\"ט אבל בניתן לו בן דליכא חששא דעיגון כלל כשהיבם לפנינו אפילו היה הראב\"ד יחיד לא היה ראוי להקל ובתחילה להתירה לשוק בלא חליצה כ\"ש דאיכא הרא\"ש ובנו רבינו וה\"ר ירוחם ע\"ש הרמ\"ה וגם הרשב\"א דהכריח להקל כמ\"ש ב\"ה ונ\"י משמו הנה בתשובה סימן אלף רפ\"ב כתב למעשה יש להחמיר וחולצת ולא מתייבמת ומדברי רבינו נמי נראה דיש להחמיר בניתן לו בן מדלא הביא בסימן קנ\"ו דברי הרמב\"ם דמיקל גם בניתן לו בן ואע\"פ שלא הביא גם דעת המחמירים יש לומר דנסמך על מ\"ש כאן דיש מחמירים בע\"א שמעיד במיתת הבעל דעבידא לאיגלויי כל שכן דיש להחמיר במעיד שניתן לו בן דהא הראב\"ד מיקל בע\"א במיתת הבעל ומחמיר בניתן לו בן ואע\"פ דהראב\"ד אינו מחלק בין איכא עגונה לאין בו עגונה אלא מחלק בין עבידא לגלויי ללא עבידא לאיגלויי ולדידן יש להחמיר אפי' במידי דעבידא לאיגלויי מ\"מ לדידן ס\"ל ה\"ט דבניתן לו בן כיון שהיבמה עם היבם במדינה שיחלוץ לה אין לסמוך לכתחילה על ע\"א לפוטרה כיון דליכא עיגונא וכמ\"ש בהגהת ש\"ע דיש חולקים וכך הורתי הלכה למעשה והארכתי בתשובה על זה עוד כתב בתשובת הרשב\"א דכל שהאמינו בו ע\"א אפי' עד מפי עד וכל אותן שנאמנות במת בעלה נאמנות כאן להעיד ליבמה וכך פסק מהר\"ם פדוואה בסי' פ\"ט והכי נקטינן:"]],["\u0010c0\u0011\u0010y0\u0011אע\"פ שהיבמה אסורה לזר קודם שתתייבם או תחלוץ אם קדשה זר תפסי בה קידושין וצריכה גט \u0010c1\u0011\u0010y1\u0011ואם קדשה במזיד קנסינן ליה לאוסרה עליו אף אם ירצה היבם לחלוץ לה אלא יגרשנה ומותרת ליבם אם הוא ישראל וחפץ בה ואם הוא כהן אסורה לו וחולץ לה ומתירה ואם קדשה בשוגג שלא ידע שהיתה זקוקה ליבם אם ירצה היבם לייבם כופין את המקדש לגרש ואם לא ירצה לייבם חולץ לה ומותרת למקדש \u0010y2\u0011וצריך לקדשה פעם אחרת אחר שתחלוץ \u0010y3\u0011כתב הרמב\"ם אם חזר המקדש וקדשה אחר שחלץ לה יבמה אין מוציאין אותה ממנו ומשמע מדבריו אפי' אם קדשה תחלה במזיד ואדוני אבי הרא\"ש ז\"ל כתב כסברא הראשונה \u0010c2\u0011\u0010y4\u0011ואם נישאת לזר \u0010y5\u0011בין במזיד בין בשוגג בין שיש לו בנים ממנה בין שאין לו בנים ממנה תצא \u0010y6\u0011וכתב בעל העיטור אפי' מת היבם תצא \u0010y7\u0011ואפי' חזר ונשאה אחר שחלץ לה היבם תצא \u0010c3\u0011\u0010y8\u0011ודינה כדין האשה שהלך בעלה למד\"ה וניסת ואח\"כ בא בעלה שתצא מזה ומזה וכל י\"ג דרכים בה \u0010y9\u0011וי\"א אע\"פ שדינה שתצא אין הולד ממזר וכ\"כ הרמב\"ם האשה שהלך בעלה ובנה למדינת הים ואמרו לה מת בעלך ואח\"כ מת בנך וניסת ואח\"כ אמרו לה חלוף הדברים תצא והולד כשר וכאשר כתבתי תחלה \u0010y10\u0011כן הוא מסקנת א\"א הרא\"ש ז\"ל \u0010c4\u0011\u0010y11\u0011זינתה מותרת ליבם \u0010y12\u0011נתייבמה בטעות כגון ששמעה שמת בעלה ונתייבמ' ואח\"כ בא \u0010y13\u0011אם היתה נשואת אחיו אינה צריכה גט מהיבם ומותרת לחזור לבעלה ואם היתה ארוסה צריכה גט מהיבם שמא יאמרו תנאי היה לאחיו בקידושין ולא נתקיים ובדין נשאה זה וצריכה גט ולכך אסורה לחזור לבעלה \u0010c5\u0011\u0010y14\u0011אחר מיתת הבעל נזקקה אשתו לאחיו וזו היא שנקראת שומרת יבם ומחמת אותה הזיקה חשובה כארוסתו ליאסר בקרובותיה אפילו מת קודם שייבם או יחלוץ ואפילו נפלה לפני שני אחין שאין ידוע איזה מהם ייבם אותה או יחלוץ אפ\"ה שניהם אסורים בקרובותיה לפיכך אם קידש אחד מהם אחות זקוקתו אסור לו לכונסה שהיא כאחות ארוסתו עד שייבם אחיו או יחלוץ לזקוקה ותפקע הזיקה \u0010y15\u0011ופירש ר\"י דוקא כשקדש לאחותה משום שבשעת נישואין הוי כנושא אחות זקוקתו אבל אם כנסה לחופה אין צריך להמתין מלבעול דבשעה שכנסה אשתו גמורה היא ופקעה לה זיקה לגמרי ודוקא קדש לאחר שנזקקה לו שקדשה באיסור אבל אם קדשה קודם לכן כיון שלא היתה אחות זקוקתו מעולם לא גזור רבנן \u0010y16\u0011מת אחיו שלא נשארה זקוקה אלא לו מוציא את ארוסתו בגט ואת היבמה בחליצה \u0010y17\u0011מתה ארוסתו חוזרת היבמה להיתרה הראשון רצה חולץ רצה מייבם:",["אע\"פ שהיבמה אסורה לזר קודם שתתייבם או תחלוץ אם קדשה זר תפסי בה קידושין וצריכה גט בפרק האשה רבה (יבמות דף צב.) אמר ר\"י אמר רב מנין שאין קידושין תופסין ביבמה שנאמר לא תהיה אשת המת החוצה לאיש זר לא תהא בה הויה לזר ושמואל אמר בעניותינו צריכה גט מספקא לשמואל האי לא תהיה אשת המת אי ללאו הוא דאתא דלא תפסי בה קידושין הוא דאתא א\"ל רב מרי בר רחל לרב אשי הכי אמר אמימר הלכתא כוותיה דשמואל ודייק רבינו לכתוב תפסי בה קידושין וצריכה גט לומר דלא תפסי בה קידושין אלא לענין שצריכה גט אבל לא לענין שיהיו קידושין גמורים שהרי אין קידושין תופסין בה אלא מספק:","\u0003ומ\"ש ואם קדשה במזיד קנסינן ליה לאוסרה עליו וכו'\u0004 שם אמר שמואל אם היה יבמה כהן חולץ לה ושריא ליה איתגורי אתגר אם כן מצינו חוטא נשכר אלא אם היה יבמה ישראל נותן לה שני גט והותרה לו וכתבו התוס' ודוקא היכא דבעי יבם ליבומי הוא דאסורה לשני אבל אי לא בעי ליבומי חולץ לה ושריא ליה להאי שקדשה דבקידושין לא קנסינן אפילו בא\"א אלא דוקא בשנשאה וכן הורה ר\"ת הלכה למעשה באשה שלא ידעה שהיה לה יבם ונתקדשה והתירה למקדש אחר חליצת היבם והא דפריך הכא אתגורי איתגר היינו משום דקאמר חולץ לה יבם ושריא לבעלה דמשמע חולץ בע\"כ שכופין אותו ואע\"פ שברצוני היה מייבם אלו לא קדשה ומ\"ה פריך אתגורי איתגר אבל אם מדעתו היה חולץ היתה מותרת לו ואין זה אתגורי איתגר והא לא איצטריך ליה לרב אשי לאשמועינן וא\"ת והשתא נמי מאי קמשמע לן דקאמר נותן שני גט דלאשמועינן דבעיא גט לא איצטריך דכבר פסק אמימר בהדיא הלכה כשמואל ואומר ר\"ת דקמ\"ל דכופין אותו ליתן גט כדי שלא יהיה חוטא נשכר עכ\"ל וכתב הרא\"ש שבעל הלכות כתב שומרת יבם שנתקדשה נותן לה גט ומותרת ליבם אבל למקדש אסורה עולמית שלא יהא חוטא נשכר ושכן כחב ר\"ח מיהו דברי רבינו תם ז\"ל עיקר דהיכא דלא ידעה שהיה לה יבם ונתקדשה בשוגג דמותרת למקדש שאף לדברי בעל הלכות מוכח כך שלא אסרה למקדש אלא משום שלא יהא חוטא נשכר והיינו דוקא במזיד ע\"כ וכתב יש לפסוק הלכה למעשה: \u0005ב\"ה וכ\"כ הריב\"ש סי' תפ\"ב על יבמה שחלצה והלכה ונתקדשה לאחר ואח\"כ נודע שהיבם מסר מודעה והשיב שכופין ליבם לחלוץ ותינשא לשני. \u0006ועיין ברבי' ירוחם. וז\"ל ה\"ה בפ' כ\"ה אהא דאסיקנא אם היה יבמה ישראל נותן לה שני גט והותרה לו פירשו הגאונים למקדש ודאי בכל גווני אסורה כדי שלא יהא חוטא נשכר ואפילו חלץ לה היבם מדעת אסורה וכתב הרמב\"ן ז\"ל וזה תימה בעיני שנחמיר בזו יותר מן האשה שהלך בעלה למד\"ה ונתקדשה שמותרת לחזור לבעלה ואם נתגרשה מותרת נמי למקדש ושמא י\"ל התם הוא דנתקדשה ברשות הכא שלא ברשות נתקדשה ע\"כ וכ\"כ הרשב\"א שהטעם הוא מפני שהוא במזיד עכ\"ל. וגם נמ\"י כתב בשם הרשב\"א שהסכמתו והסכמת כל רבותיו שאם נתקדשה בשוגג מותרת לשניהם למקדש או ליבם אם רצה היבם חולץ ומותרת למקדש וכן אם היה היבם כהן חולץ לה ומותרת למקדש דליכא למקנסיה וגם ליכא למקנסה כיון שעשתה בשוגג והיא אינה אשת איש אלא יבמה עכ\"ל וכן הם דברי רבינו וכתב בת\"ה סי' רכ\"ב על אשה שהיתה סבורה שמת יבמה כי כן יצא הקול ונתקדשה לאחד מן השוק ואח\"כ בא היבם וחלץ לה ונשאת למקדש ודקדק להחמיר לאסרה לבעלה אפי' לדעת ר\"ת ואין דבריו נראים בעיני וכתב עוד דלדעת בה\"ג דשומרת יבם שנתקדשה אסורה למקדש אפילו נשאת אחר שחלץ לה היבם תצא ודייק לה מדכתב אסורה למקדש עולמית ואין הכרע גמור:","ומ\"ש וצריך לקדשה פעם אחרת אחר שתחלוץ פשוט הוא דכיון דאינה מקודשת אלא מספק צריך לחזור ולקדשה קידושי ודאי: וכתב עוד נ\"י דהא דאמרינן אם היה יבמה כהן כו' שפירש\"י שנשאת לשוק בעד אחד או בשני עדים שאמרו לה מת בעלך ואחר כך מת בנך הגאונים ז\"ל לא פירשו כן אלא כשנתקדשה ובמזידה גמורה שנתקדשה בלא שום עדים ואפ\"ה קס\"ד שאם היה יבמה כהן חילץ לה ושריא למקדש כיון דלא עבד איסור ביאה ולא כניסה לחופה ופרכינן דא\"כ מצינו חוטא נשכר דכיון דבלא שום עדות קדשה חוטא הוא אלא ה\"ק אם היה יבמה ישראל נותן לה גט והותרה לו כלומר שחוזרת ליבם ואע\"פ שנתקדשה במזיד דלמקדש הוא דקנסינן אבל ליבם לא קנסינן כיון דליכא אלא קידושין וכן פירש הראב\"ד ז\"ל דהא קמ\"ל דאע\"פ דנתקדשה במזיד הותרה ליבם אבל למקדש לא שריא ליה לעולם וכדברי הגאונים ז\"ל וכן נראה מדברי הרמב\"ם ז\"ל עכ\"ל:","ומ\"ש רבינו בשם הרמב\"ם ז\"ל אם חזר המקדש וקדש אחר שחלץ לה יבמה אין מוציאין אותה ממנו בפ\"ט ומדסתם ולא חילק משמע לרבינו דבכל גווני מיירי אפילו קדשה תחילה במזיד: וכתב הרשב\"א בתשובות סי' תת\"ב על יבמה זקוקה לכהן שהלכה ונתקדשה לאחר לענין אם נידונת כמורדת איפשר לדעת הרי\"ף גבי נודרת הנאה מיבמה אחר מיתת בעלה שהיא נדונת כמורדת וכן דעת הרמב\"ם אבל אין נראה כן לדעת מקצת שאר הגדולים ולדברי האחרונים דעתי נוטה ועל מה שהיא טוענת שיחלוץ לה כיון שאינה ראויה לו אין נ\"ל לכופו לחלוץ אע\"פ שנאסרה לו שהיא נתנה אצבע בין שיניה. ואם טוענת שהיא מעוברת אם הוא אחר ג' חדשים בודקין אותה ואם אין העובר ניכר דבריה שוא שא\"א שלא יהא ניכר אחר ג' חדשים ואם עוברה ניכר והיבם אומר שאינה מעוברת מאחיו אלא מאותו שנתקדשה לו ולנה עמו בתצרה תולין את הולד בראשון ולא בארוס ואפי' לנה עמו בבית אחד ונכנסה עמו לבית הסתר דקי\"ל רוב בעילות אחר הבעל ועל מה שתפסה מנכסי בעלה אע\"פ שהיא מעוברת ממנו כיון שנתקדשה לאחר הפסידה מזונותיה ומקבלת כל שתפסה בחשבון כתובתה עכ\"ל:","ואם נשאת לזר בין במזיד בין בשוגג בין שיש לו בנים ממנה בין שאין לו בנים ממנה תצא בפרק האשה רבה (שם) אמר רב גידל אמר רב חייא בר יוסף אמר רב יבמה קידושין אין בה נישואין יש בה משום דמחלפא באשה שהלד בעלה למד\"ה וכתב הרי\"ף פי' קידושין אין בה אם נתקדשה לאחר קודם שיחלוץ לה יבמה אינה נאסרת על יבמה אלא אם נשאת נאסרה על יבמה משום דמחלפא באשה שהלך בעלה למד\"ה וכתב דאיתמר משמיה דרב יהודה גאון שאם נשאת לישראל ויש לה בנים ממנו חולץ לה היבם ויושבת תחת בעלה כדי שלא להוציא לעז על בניה והוא ז\"ל חלק עליו ופסק דאפי' היו לה בנים תצא ואסורה לחזור לו לעולם והכריע כן מהירושלמי וכ\"פ הרא\"ש שם וכ\"פ הרמב\"ם ז\"ל בפ\"ב:","ומ\"ש רבינו בין בשוגג בין במזיד כ\"כ הרא\"ש שם וכתב הרמב\"ם בפרק הנזכר ונשאת לאחר ובעל לוקה הוא והיא ומוציאה בגט ואפי' היו לו כמה בנים ממנה ונאסרה עליו ועל יבמה ומשמע דוקא בשבעל אבל אם לא בעל אע\"פ שנשאה לא נאסרה עליהם ויש לדחות דלא נקט בעל אלא משום מלקות :","ומ\"ש רבינו בשם בעל העיטור ואפי' מת היבם פשוט הוא דכיון שנאסרה על זה וע\"ז כדין האשה שהלך בעלה למד\"ה כי מת יבם מאי הוי:","ומ\"ש רבי' ואפילו חזר ונשאה אחר שחלץ לה היבם תצא ג\"ז פשוט מהטעם הנזכר וכ\"כ הרמב\"ם ז\"ל בפ\"ב:","ומ\"ש ודינה כדין האשה שהלך בעלה למד\"ה וניסת ואח\"כ בא בעלה שתצא מזה ומזה וכל י\"ג דרכים בה ארישא דמילתא קאי דקאמר ואם נישאת לזר כו' תצא ומסיים השתא וקאמר דדינה כדין אשה שהלך בעלה למד\"ה וניסת ואח\"כ בא בעלה שתצא מזה ומזה וכל י\"ג דרכים השנויות בפרק האשה רבה (יבמות דף פז:) גבי אשה שהלך בעלה למד\"ה ונשאת כך הם באשה זו. והכי סתם לן תנא בפרק הזורק אע\"ג דבפרק האשה רבה (יבמות דף צב.) אהא דתנן דיבמה לשוק ולדה הוי ממזר אמרינן זו דברי ר\"ע שהיה אומר אין קידושין בחייבי לאוין אבל חכ\"א אין ממזר מיבמה כתבו התוס' בשם ר\"י דאפי' לרבנן הוי ממזר מדרבנן משום דמחלפא באשה שהלך בעלה למד\"ה וכ\"כ הרא\"ש פרק האשה רבה הלכה למעשה דיבמה שנישאת לשוק תצא וכל הדרכים האלו בה כסוגיא דפרק הזורק וכתרי לישני כתנאי דרב גידל וי\"ג דרכים הללו נתבארו בדברי רבינו סי' י\"ז:","ומ\"ש וי\"א אע\"פ שדינה שתצא אין הולד ממזר לפי שאחד מי\"ג דרכים הנזכר הוא שהולד ממזר מזה ומזה כתב שי\"א דבזו אין הולד ממזר וכ\"כ הרמב\"ם ז\"ל בסוף פ\"ג האשה שהלך בעלה ובנה למד\"ה ואע\"ג דסתם מתני' בפרק האשה רבה בההיא דהאשה שהלך בעלה ובנה למד\"ה וכו' דהולד ממזר הא איתמר עלה בגמרא זו דברי ר\"ע אבל חכ\"א אין הולד ממזר ומשמע להרמב\"ם דאין הולד ממזר כלל ואפי' מדרבנן דא\"כ לא הוה סתים לה תלמודא סתומי וכ\"נ שהוא דעת הרי\"ף ז\"ל:","ומ\"ש רבינו וכן הוא מסקנת א\"א הרא\"ש ז\"ל מתוך מ\"ש בסמוך בשם הרא\"ש יתבאר לך שט\"ס יש כאן וצריך להגיה וכאשר כתבתי תחילה כן הוא מסקנת א\"א הרא\"ש ז\"ל. מצאתי כתוב אשה שנפלה לפני יבם מומר והתירוה בית דין להנשא על פי עדות שהעידו שהיבם מת ואח\"כ נודע שהיבם חי כתבו גדולי' להתירה כיון שנשאת לא תצא כתב מהר\"י וויילא (סי' נ\"ד) על אשה שנפלה לפני יבם מומר והיתה סבורה שמת ואח\"כ בא המומר וחלצה לו הא דאמרו חכמים היכא דנשאת בלא חליצה מוציאין אותה מבעלה אינו אלא קנסא מדרבנן והכא לא קנסינן לה כיון דלגאוני' ומהר\"ם אפי' לכתחילה יכולה להנשא אנן בדיעבד נסמוך עלייהו כיון דליכא איסורא אלא מדרבנן ועוד דבפ\"ב דיבמות (כד:) אהא דתנן ב' שקדשו ב' אחיות וכו' ספק חלוצה לא גזרו רבנן ובפ' החולץ (יבמות לו:) מת בתוך ל' ועמדה ונתקדשה אם אשת כהן היא אינה חולצת אלמא כיון דלא הוי אלא איסור דרבנן לא מפקינא לה מבעלה כהן ואין לומר שאני הכא דאליבא דרש\"י הוי איסורא ודאי דהא בפרק החולץ גבי מעוברת חבירו דאינסיבא לכהן בשלמא התם כיון דאיכא רבנן דפליגי ארשב\"ג גבי הא דלא איפשר עבדינן אבל הכא כמאן נעביד וכו' אלמא אי אשכחן שום תנא דסבר דמותר עבדינן כוותיה היכא דלא איפשר אע\"ג דאיכא ודאי איסורא לאידך תנא כיון דלא הוי אלא איסורא דרבנן ולא איפשר עכ\"ל ואני ראיתי אשה נשואה ונודע שהיה לה יבם מומר והורה מורי הה\"ר יעקב בי רב ז\"ל שאין מוציאין אותה מבעלה כתב בתשובות המיי' דשייכי לספר נשים מעשה בא לפני ר\"ת ביבמה שמת בעלה ולא ידעה שהיה לה יבם והלכה ונתקדשה לשוק ולא היה יודע המקדש שהיא זקוקה ליבם ובעודה ארוסה נודע ולא נשאה המקדש שהיא זקוקה ליבם ושאלו את פי ר\"ת אי קנסינן למקדש להוציא והשיב כי לא מצינו קנס בשומרת יבם שנתקדשה לשוק אא\"כ נשאה ונמצאו הצרות עריות ואיילונית עכ\"ל ובמרדכי פרק האשה רבה (עיין בגיטין פ:) מסיים בה שאם היבם רוצה לחלוץ מותרת למקדש ואם לא ירצה לחלוץ לא יחלוץ ואף השני לא יכנוס: כתב ר\"י בשם הרמ\"ה הא דתנן האשה שהלך בעלה למד\"ה ואמרו לה מת בעליך ואח\"כ מת בנך ונשאת ואח\"כ אמרו לה שהבן מת תחילה והיתה זקוקה ליבם תצא דוקא שהזימום עדים אחרונים לראשונים אבל אם הכחישום לא תצא וכן מוכח מסוגיית הגמרא וכתב עוד אהא דתנן אמרו לה מת בנך ואח\"כ מת בעליך ונתייבמה ואח\"כ א\"ל חילוף היו הדברים תצא והולד ממזר מוכח שם דדוקא שבא עד אחד תחילה ואח\"כ באו שנים וכו' וע\"ש:","זינתה מותרת ליבם ספ\"ב דסוטה (דף יח.) אמרי במערבא לית הילכתא כרב המנונא דאמר שומרת יבם שזינתה אסורה ליבמה וכתב רבינו ירוחם דהיינו דוקא אם היבם ישראל אבל אם היבם כהן אסורה לו מאחר שנבעלה לפסול לה ודבר פשוט הוא :","נתייבמה בטעות כגון ששמעה שמת בעלה ונתייבמה ואח\"כ בא אם היתה נשואת אחיו אינה צריכה גט מהיבם ומותרת לחזור לבעלה וכו' בפ' האשה רבה (יבמות ד' צד:) תנן אמרו לו מתה אשתך ונשא את אחותה ואח\"כ באת אשתו מותרת לחזור לו בגמרא ואע\"ג דאזיל אשתו וגיסו למד\"ה דאהני הני נשואין דקא מיתסרא אשת גיסו אגיסו אפ\"ה אשת גיסו אסורה אשתו שריא ולא אמרינן מתוך שנאסרה אשת גיסו אגיסו תיאסר אשתו עליו לימא מתני' דלא כר\"ע דאי ר\"ע הו\"ל אחות גרושתו דתניא כל עריות שאמרו אין צריכות ממנו גט חוץ מא\"א שנשאת ע\"פ ב\"ד ור\"ע מוסיף אף אשת אח ואחות אשה וכיון דאמר ר\"ע בעיא גט ממילא איתסרא עליה דהו\"ל אחות גרושתו ולאו איתמר עלה א\"ר גידל א\"ר חייא בר יוסף אמר רב האי אשת אח ה\"ד כגון שקדש אחיו את האשה והלך למד\"ה ושמע שמת אחיו ועמד ונשא את אשתו דאמרי אינשי הך קמא תנאה הו\"ל בקידושין והא שפיר נסיב והאי אחות אשה נמי ה\"ד כגון שקדש אשה והלכה למד\"ה אלא נישואין מי איכא למימר תנאה הו\"ל בנישואין ופירש\"י מי איכא למימר תנאה ה\"ל בנישואין הא כ\"ע ידעי דאין אדם משים בעילתו בעילת זנות וכתב הרי\"ף ז\"ל הילכך הו\"ל מתני' כוותיה וכיון דמתני' כוותיה הילכתא כוותיה וכתב הרא\"ש עמקו ממני דברי רב אלפס שפסק כר\"ע נגד רבים משום דדחיק לאוקומי מתני' כוותיה דכ\"ש דאתיא כרבנן הן בקידושין הן בנישואין ואי משום דתלמודא שקיל וטרי לאוקומי מתני' כוותיה אורחא דתלמודא בכל דוכתא דמהדר לאוקומי המשניות אליבא דכלהו תנאי אע\"ג דלית הילכתא כוותיהו ונ\"ל להביא ראיה דהלכה כר\"ע מהא דאמר לקמן יבמה רב אמר הרי היא כא\"א ושמואל אמר אינה כא\"א ומוקי רב הונא פלוגתייהו כגון שחדש אחיו את האשה והלך למד\"ה ושמע שמת אחיו ועמד ויבם את אשתו רב אמר הרי היא כא\"א ואסורה ליבם משום דבעיא גט דאמרי אינשי תנאי היה לו לאחיו בקידושין והאי אוקימתא דרב הונא עיקר אע\"ג דפריך תלמודא דילמא ליתיה לדרב הונא ובדרב המנונא קא מיפלגי לא מסתבר דפליגי בדרב המנונא דהא בסוטה פסיק תלמודא דליתא לדרב המנונא וגם לא מסתבר דפליגי בקידושין תופסין ביבמה דהא איפליגו בה כבר חדא זימנא והילכתא כרב באיסורי אלמא חיישינן לתנאי קידושין כר\"ע עכ\"ל וכ\"ה ברמב\"ם ז\"ל שכתב בפ\"י מהל' גירושין האשה שנשאה ונמצא הגט בטל או בא בעלה אחר ששמעה שמת אין הבעל הראשון והאחרון זכאין לא במציאתה ולא במעשה ידיה וכו' וכן הדין באחיו שקדש אשה והלך ושמע בו שמת וייבם את אשתו ואח\"כ בא תצא מזה ומזה וצריכה גט מזה ומזה וכל הדרכים האלו בה: \u0005ב\"ה \u0006","ומ\"ש רבינו שאם היתה נשואת אחיו מותרת לחזור לבעלה דהיינו מההיא שכתבתי בסמוך יבמה רב אמר הרי היא כא\"א ואוקמה רב הונא דקדש אחיו את האשה וכו' ופירש\"י שאלמלא נשאה ראשון תרווייהו מודו דמותרת לחזור לו דליכא למימר מחזיר גרושתו הוא דהא הכל יודעים שטעות היתה שאם גירשה לא היתה נשאת לאחיו עכ\"ל. נראה מדבריו שהטעם שאמרו בהלך בעלה למד\"ה ואמרו לה מת בעליך ונשאת שנאסר על בעלה הראשון לא מן התורה נאסרה עליו שהרי היא כמו אנוסה אלא משום דכיון דצריכה גט משני חיישינן שמא יאמרו שהוא מחזיר גרושתו משנשאת וכיון דבנשואת אחיו ליכא למימר הכי לא אסרוה על הראשון ואע\"פ שבדברי רש\"י בראש הפרק גבי תצא מזה ומזה אינם בדרך זה מ\"מ לימדנו הרב שם דלא נאסרה על הראשון אלא מדרבנן ומעתה יש לנו לעיין ולכוון דבריו אלה עם אלה ומ\"מ לענין מעשה יש להתיישב בדבר לראות אם הפוסקים שם מסכימים בדבר שהרי\"ף השמיט הא דרב והרמב\"ם שכתבה אפשר דלא כתבה לענין נשואת אחיו אלא לענין שצריכה גט כשקידשה אחיו אבל לענין ליאסר עליו דא ודא אחת היא דאי הוה סבירא לן כפירש\"י לא הוי שתיק מלאגמורן :","אחר מיתת הבעל נזקקה אשתו לאחיו וזו היא שנקראת שומרת יבם ומחמת אותה הזיקה חשובה כארוסתו ליאסר בקרובותיה אפי' מת קודם שיחלוץ או ייבם ואפילו נפלה לפני ב' אחים שאין ידוע איזה מהם ייבם או יחלוץ לה אפ\"ה שניהם אסורים בקרובותיה לפיכך אם קדש אחד מהם אחות זקוקתו אסור לו לכונסה שהיא כאחות ארוסתו עד שייבם אחיו או יחלוץ לזקוקה ותפקע הזיקה ברפ\"ב דיבמות (דף יז:) א\"ר הונא א\"ר שומרת יבם שמתה מותר באמה אלמא קסבר אין זיקה ורב יהודה אמר שומרת יבם שמתה אסור באמה אלמא קסבר יש זיקה א\"ל אביי לרב יוסף הא דרב יהודה דשמואל הוא דתנן שומרת יבם שקדש אחיו את אחותה משום ר' יהודה בן בתירא אמרו אומרים לו המתן עד שיעשה אחיך הגדול מעשה ואמר שמואל הלכה כר' יהודה בן בתירא ופירש\"י עד שיעשה אחיך מעשה. עד שייבם אחיך את היבמה ותפקע זיקתה ממך ופסקו הפוסקים הלכה כשמואל ורב יהודה וכתב הרא\"ש אע\"ג דהילכתא כרב באיסורי בהא קי\"ל כשמואל דאמוראי בתראי שקלי וטרו לתרוצי אליבא דמ\"ד יש זיקה:","\u0003ומ\"ש בשם ר\"י דוקא כשקדש אחותה כו'\u0004 אבל אם כנסה לחופה א\"צ להמתין מלבעול כו' ודוקא קדשה לאחר שנזקקה לו כו' אבל אם קדשה קודם לכן וכו' לא גזרו רבנן כ\"כ התוס' בפרק הנזכר בשם ר\"י והביאו הרא\"ש בפסקיו פרק החולץ :","\u0003מת אחיו שלא נשארה זקוקה מוציא את הארוסה בגט וכו'\u0004 ט\"ס יש כאן וצריך להגיה שלא נשארה זקוקה אלא לו והדין הוא מבואר במשנה פרק החולץ (יבמות דף מח.) שומרת יבם שקדש אחיו את אחותה משום ר' יהודה בן בתורא אמרו המתן עד שיעשה אחיך מעשה מת היבם מוציא את אשתו בגט ואת אשת אחיו בחליצה ופי' רש\"י מת היבם ולא נותר לו אח אלא זה ואת אשת אחיו בחליצה אבל ייבומי לא דאחות גרושתו היא:","\u0003ומ\"ש מתה ארוסתו חוזרת היבמה להיתרה הראשון וכו'\u0004 שם פלוגתא דאמוראי ופסקו הפוסקים כאמוראי דשרו. מעשה שנהרג יהודי אחד והניח אשה ובן קיימא וביום שנהרג מת הולד וספק איזה מת תחילה ועמד האח וחלץ לאשה מספק והנה אותו אח רוצה ליקח אחות זקוקתו וספק אחות חלוצתו מדרבנן כתב המרדכי פרק החולץ שהשיב רבינו ברוך אע\"פ שיש למנות ולהתיר אינו רשאי לעשות מעשה לכתחילה :"],["אע\"פ שהיבמה אסורה לזר קודם שתתייבם או שתחלוץ כלומר אבל לאחר כך מותרת לזר ולצדדין הוא דלאחר שתתייבם מותרת לזר אם מת היבם או גירשה אבל כשיחלוץ לה מותרת לזר מיד אחר החליצה ומ\"ש אם קדשה זר תפסי בה קידושין וצריכה גט כתב ב\"י כלומר דלא תפסי בה קידושין אלא לענין שצריכה גט אבל לא לענין שיהיו קידושין גמורין שהרי אין קידושין תופסין בה אלא מספק כדאיפסקא הלכתא כשמואל בפרק האשה רבה (יבמות דף צ\"ב) ועיין לעיל בסימן ו':","\u0003ומ\"ש ואם קדשה במזיד וכו'\u0004 כ\"כ לשם התוספות והרא\"ש ומביאו ב\"י וכתב בת\"ה בסימן רכ\"ב על מעשה שיצא קול שמת היבם ונתקדשה לזר ואח\"כ בא היבם וחלץ לה מדעתו ונישאת אח\"כ למקדש ואוסרה לבעלה אפי' לדעת ר\"ת וכתב עליו ב\"י ואין דבריו נראים בעיני וגם בעיני יפלא הפלא ופלא להוציא אשה מבעלה בפלוגתא דרבוותא במידי דרבנן דהא פשט התוספות הוא דר\"ת מפרש הסוגיא דאף בנתקדשה מזיד כיון דלא עבדא איסורא שהרי חלץ לה מקמי שנישאת למקדש שריא לאינסיבא למקדש ואף ע\"פ שכתבו אח\"כ וכן הורה ר\"ת הלכה למעשה באשה שלא ידעה שהיה לה יבם וכו' לאו למימרא דוקא דלא ידעה אלא אפי' ידעה נמי ונתקדשה מזיד היה מתיר ר\"ת לישא אותה לאחר שחלץ לה יבם אלא המעשה שהיה כך היה בלא ידעה ותו נראה דהתוס' נקטו לא ידעה לאורויי דיוקא דוקא נתקדשה אבל נישאת אפילו לא ידעה תצא דעבדא איסורא קנסינן לה והכי מוכח להדיא באשר\"י דכתב תחלה דר\"ת מתיר בנתקדשה ואח\"כ כתב דה\"ג ור\"ת אוסרין מיהו דברי ר\"ת עיקר וכתב אחר כך דבנתקדשה שוגג אף לה\"ג שריא דלא אסרה למקדש אלא משום שלא יהא חוטא נשכר מכלל דלר\"ת דשריא למקדש אפי' נתקדשה מזיד שריא ותו איכא לתמוה על מ\"ש הרב דהך אתתא דהשגיחה לקול ונתקדשה חשיבא מזידה דכיון דאשכחן בדוכתא טובא דחיישינן לקלא לחומרא כדאיתא פ\"ב דכתובות דאמרינן כגון דמוחזק לן באבוה דהאי דכהן היא ונפיק עליה קלא דבן גרושה או בן חלוצה הוא ואחתינן ליה וכו' וכן בסוף גיטין דאמרינן חיישינן לקלא לחומרא בקלא דלא פסיק אע\"ג דלקלא דבתר נישואין לא חיישינן מעתה אין לתמוה על מה שטעתה האשה וחשבה דבכל דוכתא חיישינן לקלא בין לקולא בין לחומרא ולא נקראת מזידה אלא שוגגת והכי משמע בסמוך אצל נתייבמה בטעות שעל ידי שמועה ששמעה שמת בעלה נתייבמה ותו דמה שנסמך הרב על מ\"ש באשיר\"י בלשון ה\"ג דאם נישאת תצא מן המקדש לשון זה לא נמצא בספרי' שלנו לא בתוס' ולא באשיר\"י אלא כך הוא הלשון אבל בנתקדשה תצא מן המקדש וכך הוא הנכון וא\"כ משמע ודאי דלא אסרינן לה אלא שלא תינשא לכתחילה אבל אם נישאת לא תצא ותו דמה שנסמך הרב על מ\"ש ה\"ג דאסורה למקדש עולמית אין זה כלל הוכחה דאפשר דהכי קאמר דאע\"פ דגירשה המקדש וחלץ לה אחר כך יבמה אפ\"ה אסורה למקדש עולמית ור\"ל דאפילו חזר המקדש וקדשה אחר שחלץ לה יבמה מוציאין אותה ממנו ובא להוציא מלב סברת הרמב\"ם שכתב דאין מוציאין בזו וכמ\"ש רבינו לדעת הרמב\"ם דאפי' קידשה תחילה במזיד אין מוציאין ולכן כתב ה\"ג אסורה עליו עולמית דכיון דקידש מזיד מוציאין אותה ממנו אפי' חלץ כה יבמה כ\"ז שלא נשאת אבל בנשאת לאחר שחלץ לה יבמה הכל מודים דלא תצא דלא קאמר ה\"ג ור\"ח תצא בדנישאת אלא בנישאת מקמי שחלץ לה דעבדה איסורא אבל בדנישאת לאחר שחלץ לא מפקינן לה מבעלה דלא אמר אלא דתצא מן המקדש ולא תינשא לו לכתחילה אבל בדיעבד כשנשאת לא תצא כיון דלא עבדה איסורא אע\"פ שנתקדשה מזיד ואין בזה מחלוקת ואצ\"ל היכא דהוה קלא דלא פסיק דמת היבם דפשיטא דלא חשיבא מזידה אלא שוגגת וכ\"נ ממ\"ש מהרי\"ו בתשובה סי' נ\"ד וסי' ס\"ג דבנשאת לאחר שחלץ לה יבמה אפי' נתקדשה מזיד אין מוציאין אותה מבעלה וכ\"פ ב\"י בש\"ע בסתם דאם חזר ונשאת אחר שחלץ לה יבמה אין מוציאין אותה מידו דאלמא דאפי' קידשה מתחילה במזיד אין מוציאין כשנשאת לאחר שחלץ ומ\"ש בהגהת ש\"ע די\"א דבקדשה מתחילה במזיד אפי' נשאת אח\"כ מוציאין מידו וכתב כן לדעת ר\"ת נלפע\"ד דאינו כן וכ\"ש מה שהביא אח\"כ דעת מהרא\"י ביצא קול שמת יבמה וכו' דתצא אפילו נשאת דנראה דס\"ל דיש להורות כך לאיסור לא נהירא אלא כדפי' דאפילו קדשה מתחילה במזיד לא מפקינן לה כשנשאת את\"כ ולא הסכים הרא\"ש לסברא הראשונה לאסרה למקדש כשקידשה מתחילה במזיד אלא דוקא כשחזר וקידש לאחר שחלץ לה יבמה דאסור לו לישא אותה לכתחילה אלא צריך לחזור ולגרשה אבל אם עברה ונשאת אין מוציאין אותה מידו ודוק:","\u0003ואם נשאת לזר וכו'\u0004 חוזר אמ\"ש בתחילת הסימן אם קדשה זר וכו' מקמי שחלץ לה דאיכא חילוק בין מזיד לשוגג ובשוגג מותרת למקדש וקאמר השתא דאם נשאת לזר מקמי שחלץ לה אפי' בשוגג תצא והוא מימרא דרב גידל בפרק האשה רבה (יבמות דף צב):","\u0003ומ\"ש ודינה וכו'\u0004 פי' זו שנישאת מקמי שחלץ לה דקאמרינן דתצא דינה ג\"כ שכל י\"ג דרכים בה והולד ג\"כ ממזר ואע\"ג דאינו ממזר מן התורה מן היבמה שאינו בכרת אלא לאו גרידא כתבו התוס' בשם ר\"י דמ\"מ הוי ממזר מדרבנן משום דמיחלפא באשה שהלך בעלה למד\"ה ולי\"א והרמב\"ם הא דאמרינן בגמרא אין ממזר מיבמה ר\"ל אינו ממזר כלל אפילו מדרבנן אלא כשר לגמרי ועיין בב\"י:","זינתה מותרת ליבם כתב ה\"ר ירוחם דוקא אם היבם ישראל אבל אם היבם כהן אסורה לו מאחר שנבעלה לפסול לה. נתייבמה בטעות וכו' בפרק האשה רבה סוף (יבמות דף צ\"ה) מוקי לפלוגתא דרב ושמואל כגון שקדש אחיו את האשה והלך למד\"ה ושמע שמת אחיו ועמד וייבם את אשתו רב אמר הרי היא כאשת איש ניסת בע\"א שאסורה לבעלה וזו נמי אסורה לראשון שהוא עכשיו יבמה דאמרי אינשי תנאה הו\"ל בקידושין ולא נתקיים ומותרת לשני ועכשיו יוצאה בגט ונשאה ראשון ונמצא נושא את אשת אחיו ושמואל אמר אינה כא\"א ושריא לראשון וכו' והלכה כרב באיסורי דבארוסה אסורה לחזור לבעלה אבל בנשואה מותרת לחזור לבעלה כיון דאינה צריכה גט מהשני ואע\"פ דבא\"א הניסת ע\"פ ע\"א אפי' היתה נשואה אסורה לראשון שאני התם דכיון דנישאת על פי ב\"ד יאמרו העולם בודאי הראשון גירשה ונשאה השני ומש\"ה צריכה גט מהשני שלא יאמרו א\"א יוצאה בלא גט ומאחר שצריכה גט מן השני אסורה לחזור לראשון שלא יאמרו מחזיר גרושתו משנשאת אבל גבי יבמה ליכא למימר שאחיו גירשה והוא נשאה דכ\"ע ידעי שגרושת אחיו אסורה ובודאי יאמר דבטעות יבמה ע\"ש:","\u0003אחר מיתת הבעל וכו'\u0004 פלוגתא דאמוראי ריש פרק ב' דיבמות והלכה כמ\"ד יש זיקה אפילו מתה קודם שייבם ולא אמרינן דמיתה פקעה הזיקה ואפילו נפלה לפני שני אחין וכו' דהו\"א כיון דלא ידיע קמיה מאן מינייהו רמיא לא דמיא ככנוסה ולא חשיב למיסר קרובות:"]],["\u0010c0\u0011\u0010y0\u0011היבמה ג' חדשים הראשונים ניזונת משל בעלה מכאן ואילך אינה ניזונת לא משל בעלה ולא משל יבם \u0010c1\u0011\u0010y1\u0011עמדה בדין ותבעתו לייבם או לחלוץ ונתרצה לייבם ואירעו אונס שחלה או שהוצרך לברוח מחמת ממון או מחמת מרדין חייב במזונותיה \u0010c2\u0011\u0010y2\u0011וכתב א\"א הרא\"ש ז\"ל דוקא ברח יש לה מזונות אבל לא ברח אפילו אירע הדבר שנתאחר זמן מועט מלייבם לא תקנו לה מזונות דלא שכיח שיתאחר מלייבם כיון דאיתיה קמן ונתרצה ואין לה מזונות אם לא שתבא בפני ב\"ד ותתבע ממנו שייבם או שיתן לה מזונות: ואפילו אם ברח לא מיחייב אלא כשנתרצה לייבם דכיון דסופו לייבם הרי היא כאשתו וחייב במזונותיה אבל לא נתרצה לייבם אלא לחלוץ ואירעו אונס שהוצרך לברוח לא מסתבר שתקנו לה מזונות משל יבם ע\"כ \u0010c3\u0011\u0010y3\u0011והרמב\"ם אינו מחלק בין לייבם או לחלוץ ומחייב אפילו בלא נתרצה שכתב תבעתו לדין לייבם או לחלוץ וברח או חלה \u0010y4\u0011או שהיבם במדינה אחרת הרי זו ניזונת משל יבם בלא שבועה הניחה מעוברת ה\"ז ניזונת עד שתלד ילדה ולד של קיימא \u0010y5\u0011הרי זו ניזונת כל ימי אלמנותה כשאר כל הנשים ע\"כ \u0010y6\u0011נפלה לפני יבם קטן אין לה מזונות עד שיגדיל \u0010c4\u0011\u0010y7\u0011מעשה ידיה שלה לעולם אפילו היא ניזונית: \u0010c5\u0011\u0010y8\u0011נפלו לה נכסים בעודה שומרת יבם מוכרת ונותנת וקיים שאין ליבם בהם כלום עד שיכנוס \u0010c6\u0011\u0010y9\u0011ואפי' עשה בה מאמר \u0010c7\u0011\u0010y10\u0011בד\"א בנכסי מלוג אבל נכצ\"ב לא תמכור שיש ליבם זכות בהם \u0010c8\u0011\u0010y11\u0011ואם מתה כתובתה בחזקת יורשי הבעל ונ\"מ בחזקת יורשי האשה ובנכסי צאן ברזל איכא פלוגתא דרבוותא לרש\"י יחלקו בהן יורשי הבעל ויורשי האשה וכ\"כ הרמב\"ם ולר\"ת כולם בחזקת יורשי הבעל כמו הכתובה ולזה הסכים א\"א הרא\"ש ז\"ל \u0010c9\u0011\u0010y12\u0011וכי היכי דאיכא פלוגתא בנכסי צאן ברזל לאחר מיתה ה\"נ איכא פלוגתא בחייה ובפירות לרש\"י חולקים בהם היא והיבם ולר\"ת הוא נוטל הכל \u0010c10\u0011\u0010y13\u0011נפלו לה הנכסים בעודה תחת בעלה ומת ונפלה לפני יבם אצ\"ל שלא תמכור בנכסי צאן ברזל שהרי היבם אוכל כל פירותיה אלא אפילו נכסי מלוג נמי לא תמכור שגם בהם יש חלק ליבם בפירותיהן שחציים שלו והחצי שלה \u0010c11\u0011ואם מתה יחלקו בהם יורשיה ויורשי הבעל וכתובה ונכסי צאן ברזל הם בחזקת יורשי הבעל \u0010y14\u0011והרמב\"ם כתב שאפילו נכסים שנפלו לה תחת הבעל ומת אין ליבם בהם פירות ואפילו בנכסי צאן ברזל ולא נהירא:",["היבמה ג' חדשים ניזונת משל בעלה מכאן ואילך אינה ניזונת לא משל בעלה ולא משל יבם ברייתא בפרק החולץ (יבמות דף מא:) ופירש\"י ג' חדשים הראשונים שאינה יכולה להינשא מחמת בעלה ניזונת משל בעלה שכך כתב לה את תהא יתבא בביתי ומיתזנא מנכסי כל ימי מיגר אלמנותיך מכאן ואילך אינה ניזונת לא משל בעלה ולא משל יבם ואינה דומה לשאר אלמנה דהתם כ\"ז שלא נשאת לאחר ואומרת מחמת פלוני שכבודו גדול עלי יש לה מזונות אבל הך אגידא ביבם לפיכך אין לה על נכסי בעלה מזונות ולא משל יבם עד שתכנס לחופה. כתב הרא\"ש בתשובה כלל נ' סי' ד' באותם ג' חדשים שהיא ניזונת מעשה ידיה ליבם בכל מה שתרויח בין במלאכה ובסרסרות ובכל דבר ואינה יכולה לקנות חפצים ומלבושים במעשה ידיה בלא רשות היבם ואם קנתה ונשתמשה בהם הבלאות של היבם עכ\"ל. ועיין במה שאכתוב בסמוך אצל עמד בדין וברח:","\u0003עמדה בדין ותבעתו לייבם או לחלוץ ונתרצה לייבם ואירעו אונס שחלה כו'\u0004 שם בברייתא עמד בדין וברח ניזונת משל יבם וכתבו התוס' והרא\"ש לאו בברח בשבילה איירי שרוצה לעגנה ואין רוצה לא לייבם ולא לחלוץ דהא בפרק בתרא דכתובות (קז:) פריך מינה לשמואל דחייש לצררי ואם בשבילה ברח אמאי אית לן למיחש לצררי אלא דברח מחמת מרדין או מחמת ממון איירי ולאו דוקא ברח דה\"ה חלה דכיון דלא בשבילה ברח אלא מחמת אונס שאירע לו מה לי ברח מה לי חלה ובהדיא אמרו בירושלמי פרק אע\"פ דה\"ה חלה ולא כמו שפירש\"י דדוקא ברח אבל לא חלה והא דבעי בריש כתובות (ב.) חלה מאי היינו שחלה מיד בהגעת זמן אבל הכא שחלה אחר שעמד בדין דהו\"ל לכונסה לאלתר קודם שאירע לו אונס כתב הריב\"ש בתשובה סימן ק\"ד בנדון זה אין כאן העמדה בדין כי מה שתבעה לייבם או לחלוץ תוך ג' חדשים אינו כלום גם תביעתה להגבות לה הכתובה אינה כלום. בסימן שס\"ג כתב בנדון שלפנינו שנראה שלא עמד בדין אלא ששאלה בינה לבינו ולא בב\"ד דבר ברור הוא שאין לה. וכתב עוד דאפי' להרמב\"ם דסבר דאלמנה משביעין אותה בתחילה ובסוף יבמה אינה צריכה שבועה וכ\"כ הוא ז\"ל בפי\"ח מה' אישות :","וכתב א\"א הרא\"ש ז\"ל דוקא ברח יש לה מזונות אבל לא ברח אפי' אירע הדבר שנתאחר זמן מועט מלייבם לא תיקנו לה מזונות כו' וכתבו בספרי רבינו אבל לא נתרצה לייבם ולא לחלוץ וכ\"כ בספר א\"ח ונראה שהוא טעות סופר וצ\"ל אלא לחלוץ וכ\"כ המרדכי בפרק הנזכר בשם ר\"י וכן הוא בתוס':","והרמב\"ם אינו מחלק בין לייבם או לחלוץ ומחייב אפי' בלא נתרצה כלומר אינו מחלק בין נתרצה לייבם לנתרצה לחלוץ ולא עוד אלא אפילו לא בירר עדיין אם רוצה לייבם או אם רוצה לחלוץ כיון שברח או חלה אחר שתבעתו בדין חייב במזונותיה שהרי סתם וכתב בפי\"ח מה' אישות תבעתו לדין וברח או חלה כו' ה\"ז ניזונת משל יבם ונראה שהטעם משום דכל שתבעתו לדין אם אינו פוטרה לאלתר הרי אינה מעוכבת מלינשא אלא מחמתו ולפיכך חייבוהו חכמים במזונותיה:","ומ\"ש הרמב\"ם או שהיה היבם במדינה אחרת אין לפרש כדמשמע לכאורה שהיה כבר היבם במדינה אחרת דהא לא מחויב אלא דוקא כשברח אחר שהעמידתו בדין אלא היינו לומר שאחר שעמד בדין הלך לו למדינה אחרת וכ\"כ ה\"ה דבר פשוט ומבואר הוא בדברי רבינו שדין חלה והלך למד\"ה אינו אלא כשחלה והלך למד\"ה אחר העמידה בדין אבל חלה או הלך ולא עמד בדין קודם לכן אינה ניזונת משל יבם וכן מתבאר בירושלמי וכ\"כ ז\"ל עכ\"ל וז\"ל הירושלמי חלה כמי שברח הלך למדינת הים כמי שברת ע\"כ ומיהו אפשר לומר דמדשני הרמב\"ם לכתוב או שהיה היבם במדינה אחרת נתכוון לומר דהא דלא מיחייב במזונותיה אחר העמידה בדין אא\"כ ברח או חלה היינו דוקא כשהיה דר עמה במדינה אבל אם היה דר במדינה אחרת והעמידתו שם בדין היא או שלוחה מיד הוא חייב במזונותיה דכיון שאינו דר עמה במדינה דינו כברח או חלה:","\u0003ומ\"ש הרי זו ניזונת משל יבם בלא שבועה פשוט הוא:\u0004 ומ\"ש הניחה מעוברת ה\"ז ניזונת עד שתלד כתב ה\"ה הטעם מפני שכל ימי עבורה בג' חדשים הראשונים ככל יבמה שבעולם שכשם שאינה יכולה להתייבם ולא לחלוץ תוך ג' חדשים כך כל ימי עיבורה אינה יכולה לא להתייבם ולא לחלוץ וא\"צ לומר לינשא לאחר לפיכך ניזונת משל בעלה ודבר פשוט הוא:","ומ\"ש נפלה לפני יבם קטן אין לה מזונות עד שיגדיל בפרק החולץ נפלה לפני יבם קטן מיבם לית לה מבעל מאי פליגי בה רב אחא ורבינא ח\"א אית לה וחד אמר לית לה והילכתא לית לה משמיא קנסוה: כתוב בהגהות מרדכי דכתובות יבמה שנפלה לפני יבם קטן והיתה מעוברת וילדה ומת הולד בתוך ל' יום גובה כתובתה לאלתר : כתוב בתשובת רב שמואל בן חפני יבמה שנפלה לפני יבם קטן נותנים לה כלי תשמישי הבית לפי כבודה וכבוד בעלה ונדוניא וכל מה שכתב לה בכתובתה ולא עשה לה או כלים שעשה לה ובלו אם קבל אחריותן עליו וקנו מידו גובה מן הקרקע שלו עכ\"ל. ואיני מוצא מקום לתחילת תשובה זו דהיאך יתנו לה כלי תשמישי הבית כיון דאין לה מזונות כתב המרדכי בפרק החולץ יבמה שתפסה כל הממון ואומרת שאינה רוצה לחלוץ מוציאין מידה:","ומ\"ש מעשה ידיה שלה לעולם אפי' היא ניזונת שם אהא דתניא עמד בדין וברח ניזונת משל יבם כתבו התוס' והרא\"ש דאע\"פ שניזונת משלו אין מעשה ידיה שלו כדאמרינן פרק בתרא דכתובות (קז:) אי משום מעשה ידיה לא משעבדא ליה וכתב עוד הרא\"ש שכן נראה דקי\"ל מזוני עיקר ותקינו רבנן שיהא מעשה ידיה שלו משום איבה וכל זמן שאינה יושבת תחת בעלה אין לחוש לאיבה עכ\"ל ולעניות דעתי נראה דאי מהא לא איריא שהרי אלמנה דעלמא תוכיח שניזונת משל יתומים ומעשה ידיה שלהם. ויש לתמוה על הרא\"ש שבתשובה שכתבתי בראש סימן זה כתב שבג' חדשים שהיא ניזונת מעשה ידיה של יבם ושמא י\"ל דשאני ג' חדשים מדין עמד בדין וברח:","נפלו לה נכסים בעודה שומרת יבם מוכרת ונותנת וקיים שאין ליבם בהם כלום עד שיכנוס משנה בפרק החולץ (יבמות דף לח.) ופרק האשה שנפלו (כתובות דף פ:):","ומ\"ש ואפי' עשה בה מאמר כ\"כ הר\"ן בפרק האשה שנפלו נ\"מ שנפלו לה כשהוא שומרת יבם מוכרת ונותנת וקיים ואפי' עשה בה מאמר דמאמר לב\"ה אינו עושה ספק נשואין וכדאמר עולא בריש סוגיא דפרק החולץ ולא אשכחן מאן דפליג וכ\"נ מדברי הרמב\"ם בפכ\"א מה\"א: \u0005ב\"ה וכתב הה\"מ ה\"ח אם נשארה אלמנ' מהאירוסין שאפילו נפלו לה בעודה ארוסה שמוכרת דלא עדיף יבם מבעל:\u0006","ומ\"ש בד\"א בנכסי מלוג אבל נכצ\"ב לא תמכור שיש ליבם זכות בהם דברים תמוהים הם דבנכסי שומרת יבם מאי מלוג ומאי צ\"ב שייך בהו ודוחק לומר דבעודה שומרת יבם הכניסתם לו בנ\"מ או בנכצ\"ב ואין לפרש דבנכסים שהכניסה לבעלה הראשון במלוג או בצ\"ב מיירי דא\"כ מאי בד\"א דקאמר דמשמע דאנפלו לה בעודה שומרת יבם קאי ועוד דאי בנכסים שהכניסה לבעלה הראשון מיירי הכא כתב דמוכרת ונותנת וקיים ולקמן בסימן זה כתב דאפי' בנ\"מ נמי לא תמכור וצ\"ע:","ואם מתה כתובתה בחזקת יורשי הבעל בנ\"מ בחזקת יורשי האשה ובנכסי צ\"ב איכא פלוגתא דרבוותא כולי בפרק החולץ שם ובפרק האשה שנפלו תנן גבי שומרת יבם מתה מה יעשה בכתובתה ובנכסים הנכנסים והיוצאים עמה ב\"ש אומרים יחלוקו יורשי האב עם יורשי הבעל וב\"ה אומרים נכסים בחזקתן כתובה בחזקת יורשי הבעל נכסים הנכנסים והיוצאין עמה בחזקת יורשי האב ופי' רש\"י בכתובתה בנדוניא שהכניסה לו ושמאתן לו בכתובתה וקבל עליו אחריותן: ובנכסים הנכנסים והיוצאים עמה. הן נ\"מ שאין שמין אותן עליו ואינו רשאי להוציאן אלא כשנכנסה לרשותו נכנסין עמה וכשהיא יוצאה יוצאין עמה: יחלוקו יורשי הבעל עם יורשי האב. בנ\"מ אבל יורשי האב לא יחלוקו בכתובת הבעל ואע\"ג דנקט רישא מה יעשה בכתובתה תניא ושבקה: ובה\"א נכסים. דצ\"ב בחזקתן ובפרק מי שמת מפרש בחזקת מי הם: כתובתה בחזקת יורשי הבעל. ק\"ק ותוספת הראויים לבא לה משל בעלה בחזקת יורשי הבעל וכתב הרא\"ש בפרק החולץ וז\"ל בפרק מי שמת תנן כי הא מתני' גבי מי שנפל הבית עליו ועל אשתו ופליגי בגמרא בחזקת מי ר' אלעזר אמר בחזקת יורשי האשה ר' יוחנן אמר בחזקת יורשי הבעל בר קפרא אומר יחלוקו ופירש\"י בפ' האשה שנפלו דכי היכי דפליגי התם פליגי הכא ובפרק מי שמת פסק רב אלפס כבר קפרא דהוה רביה דר' יוחנן ועוד דהויא מסקנא דשמעתא. ור\"ת אומר דלא דמיא ההוא דהתם לדהכא דהכא לא פליגי ב\"ש וב\"ה אלא בנ\"מ דוקא כדקאמר בגמרא דכתובתה שיירא ודייק מדתנן יחלוקו יורשי הבעל עם יורשי האב אבל התם קתני סתמא יחלוקו ומשמע דבכתובתה נמי איירי והיינו טעמא דהתם אם הבעל מת תחילה הויא האשה כאילו גבתה כתובתה אבל הכא שהיא זקוקה ליבם אין לה כלום עד אחר חליצה ועוד את\"ל דפליגי הכא בנצ\"ב כי התם א\"כ למ\"ד בחזקת יורשי האשה הוי נצ\"ב בחזקת יורשי האשה לב\"ש טפי מנ\"מ דבנכסי מלוג יחלוקו ובנכסי צ\"ב מודו ב\"ש לב\"ה ולקמן בפרק אלמנה ובכמה דוכתי מוכח איפכא אלא הכא כ\"ע מודו שהם בחזקת יורשי הבעל ורבינו מאיר נדחק ליישב פירש\"י ומ\"מ לפי' ר\"ת רווחא שמעתתא הוא עיקר עכ\"ל: ומ\"ש רבי' שהרמב\"ם פסק כרש\"י הוא בפכ\"ב מה\"א וכתב ה\"ה שהרשב\"א כתב דלשיטת רש\"י הא דנ\"מ בחזקת יורשי האב דוקא בשנפלו לה ועודה שומרת יבם אבל בנפלו לה בחיי בעלה ונתאלמנה מן הנישואין דינם כנצ\"ב וחולקין בהן ורבינו אינו מחלק בנ\"מ בין נפלו לה בעודה שומרת יבם לנפלו לה מחיים דבעל אלא בכל גווני הם דוורשים ויש בזה שיטה אחרת לקצת גאונים ז\"ל והם גורסים במשנה כתובה בחזקת יורשי הבעל ואינם גורסים וכתובה וזהו פירושם נכסים בחזקתן כיצד הכתובה ר\"ל העיקר ותוספת ונכסי צ\"ב בחזקת יורשי הבעל ונכסים הנכנסים והיוצאים ר\"ל נ\"מ בחזקת יורשי האב ודוקא נפלו לה בעודה שומרת יבם אבל נפלו לה בחיי בעלה ונתאלמנה מן הנישואין דינן כנצ\"ב ואם מתה יורשי הבעל יורשים אותה וזה דעת קצת מפרשי אחרונים ולר\"א שיטה אחרת בהשגות שהוא סבור שנצ\"ב כולם ליבם ונכ\"מ שנפלו תחתיו דבעל יחלוקו ושנפלו לה בעודה שומרת יבם כולם שלה ולברר דעות אלו מן הגמרא יארכו הדברים וכבר פי' הרמב\"ן הסוגיא ביבמות לדעת רבינו ונראה שהוא מסכים לדעתו ודע שאין המאמר מועיל בזה כלום וכ\"כ רבינו בפ\"ג מה' נחלות עכ\"ל. והר\"ן כתב שיטות אלו בארוכה בפרק האשה שנפלו ודקדק מדברי הרי\"ף בפרק הכותב שהוא מפרש משנה זו כפי' הגאונים שכתבתי בסמוך וכתב הר\"ן בתשובה סי' מ\"ו אחר דברי רש\"י ודברי הגאונים ואנו בעניותינו שאין לנו להכריע כך אני דן שנצ\"ב שהאשה באה להוציא מיד יורשי הבעל לא כל הימנה שאין עושין מעשה להוציא כנגד הגאונים אבל נ\"מ אפי' נפלו לה תחת הבעל כל שהם קיימים בזה נותנים מקצתה ליורשיה כדברי רש\"י כיון שאותם נכסים ממש הוחזקו למשפחת בית אביה עכ\"ל ובסימן נ\"ט כתב על ענין תנאי השיור אינו אנא אם תמות אשתו בחייו אבל בחיי יבם אין לנו (וע\"ל סי' קי\"ח):","ומ\"ש וכי היכי דאיכא פלוגתא לאחר מיתה ה\"נ איכא פלוגתא בחייה ובפירות לרש\"י חולקין בהן היא ויבם ולר\"ת הוא נוטל הכל והרמב\"ם ז\"ל כתב בפרק כ\"ב מה\"א אין ליבם פירות אפילו בנצ\"ב שהכניסה לאחיו אין לו פירות עד שיכנוס וכתב ה\"ה מ\"ש ואין ליבם פירות כולי בנ\"מ הוא מפני שאין היבם חייב לפדותה כנזכר פרק י\"ח וכבר נתבאר פרק י\"ב שפדייתה כנגד אכילת פירות נכסיה ועוד שאם מתה יורשי אביה יורשים נ\"מ שלה כנזכר בסמוך אבל מ\"ש שאפילו בנצ\"ב אין לו פירות הוא תמוה למה לא יזכה במחציתן כמבואר בסמוך ואולי שהוא סובר שאין לו זכות אלא בגוף הקרקע ליורשה אם תמות אבל לא בפירות ולא ידעתי מאין הוציא זה והרבה מן המפרשים חלוקים עליו בזה ודעת הרמב\"ן ז\"ל ביבמות שבפירות יש לו המחצית עכ\"ל והר\"ן ג\"כ בפרק האשה שנפלו כתב על דברי הרמב\"ם ז\"ל שהרמב\"ם ז\"ל חולק על מה שכתב שאפי' בנצ\"ב שהכניסה לאחיו אין לו פירות עד שיכניס וזה ודאי תימא למה לא יזכה במחצית כיון שאם מתה יורש מחציתן עכ\"ל וז\"ל ריב\"ש בתשובה סימן ק\"ד אע\"פ שהרמב\"ם כתב שאין ליבם פירות כבר דחו דבריו וגם מגיד משנה לא מצא לו זכות בפירות נצ\"ב ובתשובה אחרת סימן שפ\"ה כתב אין בכל הפוסקים שראיתי דבריהם שיהיה דעתו שאין לו פירות כלל זולתי הרמב\"ם שכתב כן ונדחו דבריו מההיא דאמרינן בפרק החולץ אדמיפלגי בגופה לאחר מיתה ליפלגו בחייה ולפירות ואף הרב בעל מ\"מ המהפך בזכותו של הרמב\"ם בכל מה שאפשר לא מצא לו זכות בנצ\"ב כי אם בנ\"מ ואמר כי היה דעת הרמב\"ם בנ\"מ מפני שפרקונה תחת פירות נ\"מ וכיון שאין היבם חייב לפדותה אין לו פירות ולי נראה שמפני טעם זה אין לנו לדחות אותה סוגיא שבפרק החולץ דמה שתקנו פרקונה תחת פירות היינו תחת כל פירות ר\"ל נ\"מ שנפלו לה קודם שנשאת ושנפלו בעודה תחתיו אבל יבם אין לו פירות בנכסי מלוג שנפלו לה בעודה זקוקה אלא בפירות נכסים שנפלו לה בעודה תחתיו דבעל משום דיבם במקום בעל קאי עכ\"ל. כתב רב סעדיה בתשובה שאין היבם חייב ברפואתה בק\"ו מפרקונה ולענין קבורתה הא איפשיטא בר\"פ אלמנה ניזונת שאין \u0005ב\"ה טעות סופר יש כאן וצריך להעביר הקולמוס על תיבת שאין וכך צריך לכתיב הא איפשטא בפרק האשה שנפלו שהיבם חייב בקבורתה\u0006 היבם חייב בה דינים דשייכים לסימן זה עיין במישרי' נכ\"ג חי\"ב: וכתב עוד הר\"ן ז\"ל בפרק הנזכר כתב הרשב\"א דבנ\"מ שנפלו לה תחתיו דבעל דאמרי' בהו יחלוקו אם רצתה למכור מחציתן מוכרת ונותנת דהא אין ליבם במחציתן כלום והרי זה במחציתן כמי שנפלו לאחר שנעשית שומר' יבם אבל המחצית האחר לא תמכור שהרי הוא יורשה אם מתה ואין היבם מוציא מיד הלקוחות עד שתמות לפי שאין היבם אוכל פירות קודם כניסה כלל דבגופו של קרקע הוא שיש לו זכות שאם מתה יירשנה אבל פירות בחייה לית ליה כלל דהא לא תקינו פירות ליבם ואפילו לבעל לא תיקנו אלא משום פרקונה ויבם אינו פודה וכדתניא בפרק נערה שנתפתתה ונראה היה לומר דאין היבם אוכל פירות נ\"מ שלה ואפילו לאחר שכנס שהרי אין לה כתובה עליו וכיון דאין לה כתובה עליו תנאי כתובה נמי אין לה עליו דמההיא דפרק החולץ משמע דאית ליה כדאמרינן התם אדמיפלגי בגופה של קרקע ולאחר מיתה ליפלגו מחיים ולפירות. והר\"ן ז\"ל כתב דודאי ההיא דהחולץ מוכחא בהדיא דאותו זכות עצמו שיש ליבם בגופה של קרקע יש לו באכילת פירות ויישב מה שהוקשה להרשב\"א ז\"ל על זה:","נפלו לה נכסים בעודה תחת בעלה ומת ונפלה לפני יבם אצ\"ל שלא תמכור בנצ\"ב שהרי היבם אוכל כל פירותיה אלא אפי' נ\"מ נמי לא תמכור שגם בהם יש חלק בפירותיהן שחציים שלו והחצי שלה דברי רבינו בכאן תמוהים שכ' שנ\"מ נמי לא תמכור שגם בהם יש חלק ליבם בפירותיהן שחציין שלו ולפי טעם זה חציין מיהא יש לה רשות למכור וכמו שכתבתי בסמוך בשם הרשב\"א: \u0005ב\"ה והיאך כתב שלא תמכור דמשמע שלא תוכל למכור כלל \u0006: והר\"ן ז\"ל וגם מ\"ש בסתם ואם מתה יחלקו בהן יורשיה ויורשי הבעל וכתובה ונצ\"ב הם בחזקת יורשי הבעל והרי בסמוך במחלוקת שנאה שרש\"י והרמב\"ם חולקים ואומרים דנצ\"ב נמי יחלוקו ואם נתכוון לסתום דבריו כר\"ת ללמדינו דהלכה כוותיה כבר כתב בסמוך שהרא\"ש הסכים לדעת ר\"ת וכבר נודע שדעת רבינו מסכמת לדעת הרא\"ש אביו ורבו ז\"ל וכן יקשה על מ\"ש בסתם אין צ\"ל שלא תמכור בנצ\"ב שהרי היבם אוכל כל פירותיה והיינו לדעת ר\"ת אבל לדעת רש\"י והרמב\"ם אינו אוכל אלא חציים ואין לומר דלעיל מיירי בנכסים שנפלו לה בעודה שומרת יבם וקודם שיכנוס הכניסתם לו בתורת נ\"מ או נצ\"ב והתם הוא דאיפלגו רבוותא אבל בנפלו לה בעודה תחת בעלה ומת ונפלה לפני יבם לד\"ה נצ\"ב כולם לבעל דא\"כ תחלה ה\"ל להשמיענו זה ואח\"כ הוה ליה להשמיענו דין המכירה:","ומ\"ש בשם הרמב\"ם ז\"ל כבר נתבאר בסמוך כתב הרשב\"א בתשובה סי' תפ\"ו על ראובן שמת ולו שתי נשים ונשארו זקוק ת ליבם ומתה אחת מהן אין ליבם שום טענה בנכסים לפי שהשנייה בפניו ואם יבם סילק זיקת יבום מעל זו ואינו יורשה וכן אם חלץ סילק זיקת יבום מעל כל הבית ואם עדיין לא ייבם ולא חלץ מ\"מ כיון שזו לפניו ומצוה עליו לחלוץ או לייבם לזו שהראשונה כבר מתה וכבר נסתלקה זיקתו מהראשונה ועמדה על זו מה שאין כן בשומרת יבם אחת שמתה שכיון שהיתה זקוקה לו ואין אחרת שיחול זיקתו עליה ה\"ה יורשה כפי הדינים שנאמרו בגמרא כתב הר\"ש בן הר\"ש בר צמח על ראובן שייבם יבמתו ולו בנים במ\"ה ומתו הוא ובניו ואין ידוע אם האב מת תחלה או הבנים ואח\"כ מתה האשה ולוי אחי ראובן רוצה לירש והשיב כיון שהוא ספק אם מת ראובן קודם בניו או אח\"כ יורשי האשה הם ודאי בירושה ולוי היבם הוא ספק ואין לספק במקום ודאי כדאיתא בפרק החולץ. ומה שצוה ראובן שימכרו הספרים ויקנו ס\"ת וגם הניח הקדשות אחרות ופרעה האשה מקצתן ועכשיו יורשיה אינם רוצים למכור הספרים לקנות ספר תורה מן הדין היה שכיון שהנכסים מטלטלים ותפסתם האשה לאחר מיתת בעלה הרי הם בחזקת יורשיה בפרעון כתובתה ואם יש קרקעות כיון שלא נשבעה האלמנה ימכרו הקרקעות ויקנו ס\"ת וישלימו ההקדשות אבל אם הדבר ברור שכשהתחילה לפרוע ההקדשות היה בדעתה להשלים צוואת בעלה אלא שקפצה עליה מיתה הרי היא כמו שהודית בשעת מיתה שנשארו בנכסי בעלה לקיים מצותו וחייבים היורשים לקיימה אפילו ממטלטלי ואם אין הדבר ברור אין מוציאין מיורשים :"],["\u0003היבמה ג' חדשים הראשונים וכו'\u0004 ברייתא פרק החולץ סוף (יבמות דף מ\"א) ופי' רש\"י ג' חדשים הראשונים שאינה יכולה להינשא משמת בעלה ניזונית משל בעלה וכו' כלומר דצריכה להמתין ג' חדשים דלא תתייבם תוך ג' שמא היא מעוברת ויהיה בר קיימא וקא פגע באיסור אשת אח דאורייתא וגם לא תחלוץ דכתיב אם לא יחפוץ וכל שאינו עולה לייבום אינו עולה לחליצה ולמסקנא אפי' שאר כל הנשים צריכות להמתין ג\"ח כדי להבחין בין זרעו של ראשון לזרעו של שני וכיון דמחמת בעלה מעוכבת מלהינשא ניזונת משל בעלה מכאן ואילך שאינה מעוכבת מחמת בעלה אינה ניזונת משל בעלה וגם משל יבם אינה ניזונית דכיון שלא כנסה לא עדיפא מארוסה שאין לה מזונות:","\u0003עמדה בדין וכו'\u0004 פירוש תבעתו בבית דין בהגעת הזמן לייבם או לחלוץ דהיינו אחר ג\"ח ונתרצה לייבם ונתאחר עד שאירעו אונס חייב במזונותיה דהו\"ל לכונסה לאלתר קודם שאירע לו אונס אבל אם לא תבעתו בב\"ד ואירעו אונס אפי' תבעתו בינו לבינה אינו חייב במזונותיה ונראה מדברי רבי' שהיה גורס עמדה בדין פי' תבעתו בב\"ד אבל בכל הספרים גרסינן עמד בדין משמע דאפילו תבעתו בב\"ד אינו חייב אא\"כ שבא לפני ב\"ד ועמד בדין וכך כתב הרמב\"ם פ' י\"ח דאישות ע\"ש:","\u0003ומ\"ש וכתב א\"א הרא\"ש דוקא ברח וכו'\u0004 פי' אף על פי שתבעתו בתחילה לייבם או לחלוץ ונתרצה לייבם ונתאחר אינו חייב במזונות אם לא שחזרה ותבעתו בב\"ד שייבם או יתן לה מזונות ופסקו ב\"ד לה מזונות אם לא ייבם מיד ולפ\"ז נראה ודאי דאם מתחילה תבעתו בהגעת הזמן שייבם או יחלוץ או יתן לה מזונות ונתרצה לייבם ופסקו לה ב\"ד שאם לא יהא מייבם מיד שנתן לה מזונות חייב מיד במזונות ואינה צריכה לתבעו שנית:","\u0003והרמב\"ם אינו מחלק וכו'\u0004 שכתב תבעתו לדין לייבם או לחלוץ ועמד בב\"ד וברח וכולי כצ\"ל דתרתי בעינן דתבעתו וגם עמד בדין ופסקו לו דין שחייב לזונה מיד אם לא ייבם או יחלוץ לה מיד לאחר ג\"ח כדפי' בסמוך:","ומעשה ידיה שלה לעולם אפי' היא ניזונית פי' לאחר ג\"ח לעולם מעשה ידיה שלה דבין לא תבעתו בב\"ד דאין לה מזונות ובין תבעתו ועמד בדין דיש לה מזונות מ\"מ מעשה ידיה שלה לעולם דכיון דלא כנסה לא משעבדא ליה ומה שניזונת אינו אלא מתורת קנס לפי שלא פטרה כמו שפסקו לו ב\"ד וכמו שפירש\"י להדיא דקנסינן ליה אבל בג' חדשים הראשונים ביבמה וכן כל אלמנה דניזונת מדינא משל בעלה מתנאי ב\"ד גם מעשה ידיה של יורשים דמשעבדא להו משעה שנכנס לחופה עם בעלה וכדלעיל בסימן צ\"ה וכן ביבמה בג' חדשים הראשונים כמ\"ש הרא\"ש בתשובה ומביאו ב\"י ועיין בתוס' לשם בד\"ה עמד וברח:","\u0003נפלו לה נכסים בעודה שומרת יבם מוכרת ונותנת וכו'\u0004 משנה פרק החולץ (יבמות דף לח) ומשמע מדכתב רבינו בסתם דבין בנפלו כשהיא ארוסה ובין נפלו כשהוא נשואה מוכרת וכו' דרבה ואביי ורבא כולהו ס\"ל דרישא איירי אפי' בנשואה דמוכרת ונותנת וקיים ואפילו לעולא דמוקי רישא דוקא בנפלו כשהיא ארוסה אבל נישואין לא היינו דוקא לב\"ש אבל לב\"ה דפליג בסיפא בדנפלו כשהיא נשואה וס\"ל דנ\"מ בחזקתן היינו נמי שמוכרת ונותנת וקיים:","ומ\"ש ואפילו עשה בה מאמר ה\"א התם לאוקימתא דאביי רישא דלא עבד בה מאמר קודם שנפלו לה נכסים הילכך זיקה לא מהני ולא מידי אף לב\"ש ומוכרת ונותנת וקיים סיפא דעבד בה מאמר ומאמר לב\"ש קני ועושה ספק נישואין וחולקין ולב\"ה אפי' מאמר לא קני ומוכרת ונותנת בנ\"מ וקיים ולא אשכחן מאן דפליג עליה דאפשר דעולא ורבה ורבא מודו לאביי בהא דאפי' עשה בה מאמר לב\"ה לא קני מידי בנ\"מ וכך כתב הר\"ן ומביאו ב\"י:","\u0003בד\"א בנכסי מלוג אבל נצ\"ב וכו'\u0004 הקשה ב\"י דמאי מלוג ומאי צאן ברזל שייך בנכסים שנפלו לה בעודה שומרת יבם וצ\"ע ותימה הלא בתוספות לשם בד\"ה ובית הילל מחלקין ג\"כ בשומרת יבם שנפלו לה נכסים בין נ\"מ לנצ\"ב ורבינו לא כתב פסקיו אלא על פי מסקנת הרא\"ש שהוא כמ\"ש התוס' לר\"ת אבל הדבר פשוט שגם בנכסים שנפלו לה כשהיא שומרת יבם אפשר שהיבמה קודם שנתייבמה עשתה עם היבם מעמד באלו הנכסים שנפלו לה עתה שהשדות כך וכך יקבל עליו אחריות ויהיו נצ\"ב ושדות כך וכך יהיו נ\"מ ויאכל בהם פירות ואין זה דוחק כלל וכך מוכח בסוף סימן זה:","\u0003ואם מתה וכו'\u0004 עיין בב\"י מבואר טעם מחלוקת רש\"י ור\"ת ע\"פ דברי התוספות והרא\"ש ולשם מבואר דל\"ק לר\"ת דהכא כולהו ליורשי הבעל ולעיל בסימן צ' כתב דיחלוקו דהתם גבי נפל הבית עליו ועל אשתו אם הבעל מת תחלה חשובה האשה כאילו גבתה כתובתה אבל הכא שהיא זקוקה ליבם אין לה כלום עד אחר חליצה עכ\"ל ומביאו ב\"י:","\u0003ומ\"ש וכי היכי וכו'\u0004 שם בגמ' א\"ל רבה לעולא אדמיפלגי בגופא ולאחר מיתה ליפלגו בחייה ולפירות אלמא דחד דינא אית להו ומשמע דכל היכא דאית ליה פירות למר כדאית ליה ולמר כדאית ליה אם מכרה מוציא היבם מיד הלקוחות דהא זכה בנכסים לאכול הפירות וכ\"כ ב\"י על שם הר\"ן בשם הרשב\"א:","\u0003נפלו לה הנכסים בעודה תחת בעלה וכו'\u0004 שם אוקמה אביי רישא דנפלו לה כשהיא שומרת יבם הלכך מודים ב\"ש דמוכרת לכתחילה סיפא דנפלו לה כשהיא תחת בעלה הראשון וקסבר אביי ידו כידה פי' נשואה ידו כידה ולא יותר וכשמת ואין ליבם אלא זיקה ידו גרועה מידה ונ\"מ בחזקתן לב\"ה ואין ליבם בהם כלום ולב\"ש נשואה ידו עדיפא מידה וכשמת ידו כידה ויחלוקו ופליג עליה רבא ואמר לב\"ה נמי נשואה ידו עדיפא מידה וכשמת ידו כידה ויחלוקו בנ\"מ והלכה כרבא כדכתב הרא\"ש ושכך הוא דעת האלפסי וז\"ש רבינו שחציים של נ\"מ הם ליבם ולפ\"ז משמע דכך הם פי' דברי רבינו נפלו לה הנכסים בעודה תחת בעלה וכו' א\"צ לומר שלא תמכור בנצ\"ב בין נצ\"ב שהכניסה לבעל הראשון קודם כניסה לחופה ובין נכסי צאן ברזל מאותן נכסים שנפלו לה בעודה תחת בעלה כשקבל הבעל עליהם באחריותו שהרי היבם אוכל כל פירותיה אלא אפילו נ\"מ מאותן נכסים נמי לא תמכור שגם בהם יש חלק ליבם וכו' כלומר לא תמכור כולם אבל חציין ודאי יכולה למכור וכמ\"ש ב\"י בשם הרשב\"א והר\"ן אבל הב\"י הבין מלשון רבינו שהיבמה אינו יכולה למכור כלל בנ\"מ ותמה עליו ואין כאן קושיא ועי\"ל דאפילו נאמר דדעת רבינו שלא תמכור כלל בנ\"מ ודלא כהרשב\"א והר\"ן נמי ניחא דס\"ל לרבינו דאעפ\"י שחציין שלה אפ\"ה לא תמכור בלא רשותו דכיון דידו כידה יש לו זכייה בכל הנכסים וצריכין לחלוק בפני ב\"ד וכל זמן שלא עשו חלוקה בפני ב\"ד לא תוכל למכור ואם מכרה אינה מכירה וז\"ש אצ\"ל שלא תמכור בנצ\"ב אלא אפילו נ\"מ נמי לא תמכור דמשמע הלשון דכי היכי דבנצ\"ב לא תמכור כלל ואם מכרה אינה מכירה ה\"נ בנ\"מ כל הדין כמו בנצ\"ב:","ומ\"ש ואם מתה יחלקו בהם יורשיה ויורשי הבעל זה פשוט דכיון דבחייה אין ליבם בהם אלא חציים א\"כ אף אם מתה אינן יכולין לירש אלא החציה ול\"ד לנפלו לה נכסים בעודה שומרת יבם דכיון דהכל מודים דבחייה מוכרת כל הנכסים ונותנת וקיים דאין ליבם בהם כלום א\"כ אם מתה הכל ליורשיה וכן בנצ\"ב בנכסים שנפלו בעודה תחת בעלה כיון שהבעל קבל עליו אחריות בעודה נשואה חשובים הם כנצ\"ב שקיבל עליו אחריות בשעה שכנסה לחופה ואם מתה הם בחזקת יורשי הבעל ול\"ד לנצ\"ב שקיבל עליו היבם אחריות בנכסים שנפלו לה בעודה שומרת יבם דכתב לעיל לרש\"י דזיקת נשואה עושה ספק נשואה וחולקין דשאני הכא דבאים הנצ\"ב מכח ודאי נשואה שנפלו לה בעודה תחת בעלה וקיבל עליו אחריותו דאף רש\"י מודה שהכל ליורשי הבעל וב\"י לא נתיישב לו דברי רבינו ולפע\"ד דבריו נכונים אין בהם גמגום כי כל דבריו ע\"פ סוגיית הגמרא והרמב\"ם כתב וכולי ולא נהירא עיין בב\"י שהאריך בזה מדברי האחרונים כולם תפסו על הרמב\"ם בזה:"]],["\u0010c0\u0011\u0010y0\u0011מי שהיו לו נשים רבות ומת ולו אח ביאתה או חליצתה של אחת מהם פוטרת כולן \u0010y1\u0011ואין היבם יכול ליבם אלא אחת מהם \u0010y2\u0011ולא חולץ אלא אחת מהן \u0010y3\u0011היו בהן כשרות לכהונה ופסולות כמו גרושה או חללה בא לייבם מייבם לאיזו שירצה בא לחלוץ חולץ לפסולה ולא לכשרה כדי שלא לפוסלה לכהונה בחליצה \u0010y4\u0011היו לו אחין רבים ונפלו נשותיו לפניהם אחד מייבם או חולץ לאחת מהיבמות והותרו שאר הצרות \u0010c1\u0011\u0010y5\u0011ומצוה על הגדול שבהם לייבם או לחלוץ לא רצה \u0010y6\u0011חוזרים על כל האחין זה אחר זה דרך גדילתן \u0010c2\u0011לא רצו חוזרים אצל גדול ואומרים לו עליך המצוה או חלוץ או יבם \u0010c3\u0011\u0010y7\u0011וכופין אותו לחלוץ אבל אין כופין אותו לייבם אמר הגדול המתינו עד שיגדל הקטן או שהיה אחיו חרש ואמר המתינו עד שיבריא אין שומעין לו אלא אומרים לו עליך המצוה או חלוץ או יבם וכן אם היה גדול במדינה אחרת אין הקטן ממנו בשנים שהוא כאן יכול לומר על אחי הגדול המצוה המתינו לו עד שיבא אלא אומרים לזה שבכאן חלוץ או יבם: \u0010y8\u0011לא רצה הגדול לייבם אלא לחלוץ והקטן ממנו רוצה לייבם ביאת הקטן עדיפא אבל אם שניהם אין רוצים לייבם אלא לחלוץ חליצת הגדול עדיפא מהקטן אע\"פ שמצוה בגדול לייבם קדם הקטן ויבם זכה \u0010c4\u0011\u0010y9\u0011היו לו אחים רבים ומתו ונפלו נשותיהם לפניו אם אפשר לו לייבם את כולם מייבם ואם לאו חולץ למי שירצה מהן ומייבם למי שירצה מהן אחת מכל בית ובית:",["מי שהיו לו נשים רבות ומת ולו אח ביאתה או חליצתה של אחת מהן פוטרת את כולן משנה בפרק החולץ (יבמות דף מג מד.) ובגמרא מייתי לה מקרא:","ומ\"ש ואין היבם יכול לייבם אלא אחת מהן פשוט הוא דכיון דבביאת או חליצת אחת מהן נפטרו כולן אם היה בא אח\"כ על צרתה הו\"ל אשת אח שלא במקום מצוה ובפרק הנזכר מייתי לה מדכתיב אשר לא יבנה את בית אחיו בית אחד הוא בונה ואינו בונה ב' בתים.","ומ\"ש ולא חולץ אלא אחת מהן כלומר א\"צ לחלוץ אלא אחת מהן וכדי נסבה שלא היה צריך לכתוב זה שכבר כתב שחליצתה של אחת מהן פוטרת את כולן:","\u0003היו בהן כשרות לכהונה ופסולות כו'\u0004 בא לייבם מיובם לאיזו שירצה בא לחלוץ חולץ לפסולה ולא לכשרה שם במשנה וכתב ר\"י בשם הרמ\"ה כופין אותו לחלוץ לפסולה ואם עבר על דברי המזהירים על כך מנדין אותו ואם התרו בו למלקות מלקין אותו עכ\"ל:","היו לו אחים רבים ונפלו נשותיו לפניהם א' מייבם או חולץ לא' מהיבמות והותרו שאר הצרות ומצוה על הגדול לייבם או לחלוץ לא רצה חוזרין על כל האחין כו' כך הוא הגירסא הנכונה בספרי רבינו המדוייקים ובקצתם יש חסרון הניכר. ומ\"ש היו לו אחים רבים ונפלו נשותיו לפניהם אחד מהם מייבם או חולץ לאחד מהיבמות והותרו שאר הצרות מתבאר במקומות הרבה ממסכת יבמות.","\u0003ומ\"ש מצוה על הגדול לייבם או לחלוץ לא רצה חוזרין על כל האחין וכו'\u0004 משנה בפרק החולץ (יבמות ד' לט ) מצוה בגדול לייבם לא רצה מהלכין על כל האחין לא רצו חוזרין אצל הגדול אומרים לו עליך מצוה או חלוץ או יבם. ומ\"ש רבי' מצוה על הגדול לייבם או לחלוץ נ\"ל דהיינו דוקא כשאין הקטן רוצה לייבם אלא לחלוץ אבל אם הקטן רוצה לייבם ביאת קטן עדיפא מחליצת גדול כמ\"ש לקמן בסמוך. והא דמצוה בגדול מייתי לה מקרא בפרק כיצד (ד' כד):","\u0003ומ\"ש חוזרין על כל האחין דרך גדילתן זה אחר זה:\u0004 \u0005ב\"ה יתבאר בדברי ה\"ה שכתבתי בסימן קס\"ה\u0006:","ומ\"ש וכופין אותו לחלוץ ואין כופין אותו לייבם כ\"כ הרמב\"ם ז\"ל בפ\"ב ועיין עוד שם ובתשובת הרשב\"א סי' אלף וקס\"ה כ' הר\"ש בן הר\"ש בר צמח אם האח הגדול במ\"ה וכתב שאינו רוצה לייבם הרי הוא כמי שאינו ואם האח הגדול השני אינו רוצה לייבם ולא לחלוץ חוזרת המצוה אצל הקטן ואם רוצה לייבם אין כופין אותו לחלוץ. ומ\"ש הרמב\"ם והטור כופין אותו לחלוץ ואין כופין אותו לייבם אינו אלא במי שלא רצה לא לחלוץ ולא לייבם כי איך יכופו אותו לייבם ואין אדם דר עם נחש עכ\"ל: ומ\"ש אמר הגדול המתינו עד שיגדיל הקטן או שהיה אחיו חרש ואמר המתינו עד שיבריא אין שומעין לו כו' וכן אם היה הגדול במדינה אחרת אין הקטן ממנו בשנים שהוא כאן יכול לומר על אחי הגדול המצוה המתינו לו עד שיבא כו' משנה בפרק החולץ (יבמות דף לט.) ומפרש טעמא בגמרא (שם) משום דשהויי מצוה לא משהינן ודבר פשוט הוא שמ\"ש וכן אם היה הגדול במדינה אחרת אין הקטן ממנו בשנים שהוא כאן יכול לומר וכו' היינו לומר דקטן זה אינו קטן ממש דא\"כ לאו בר חליצה ויבום הוא וע\"כ לומר דגדול הוא מבן י\"ג ומעלה והביא ב' שערות אלא שהוא קטן בשנים מאחיו הגדול:","לא רצה הגדול לייבם אלא לחלוץ והקטן ממנו רוצה לייבם ביאת קטן עדיפא אבל אם שניהם אינם רוצים לייבם אלא לחלוץ חליצת גדול עדיפא מהקטן שם איתמר ביאת קטן וחליצת גדול פליגי בה רבי יוחנן וריב\"ל חד אמר ביאת קטן עדיפא וח\"א חליצת גדול עדיפא איכא דאמרי בביאה דכ\"ע לא פליגי דביאת קטן עדיפא כי פליגי בחציצת קטן והכי איתמר חליצת קטן וחליצת גדול פליגי בה רבי יוחנן וריב\"ל חד אמר חליצת גדול עדיפא וח\"א כי הדדי נינהו ופסק רבינו כלישנא בתרא דאמר דכ\"ע ל\"פ דביאת קטן עדיפא ובפלוגתא דחליצת קטן וחליצת גדול פסק כמ\"ד חליצת גדול עדיפא וז\"ל ר\"י כתב הרמ\"ה כיון דלא איפסיקא הלכתא עבדינן לחומרא וכל היכא דאיפשר בגדול עושין ואם לא ירצה הגדול אין כופין אותו כיון דאיכא קטן שרוצה לחלוץ ודבר פשוט הוא דהאי קטן היינו לומר שהוא צעיר מאחיו אבל הביא שתי שערות והוא בן י\"ג שנה ויום אחד דאל\"כ לאו בר חליצה ויבום הוא: אע\"ג שמצוה בגדול לייבם קידם הקטן ויבם זכה משנה בפרק החולץ (דף כד):","\u0003היו לו אחים רבים ומתו ונפלו נשותיהם לפניו אם איפשר לו לייבם את כולם מייבם וכו'\u0004 משנה וגמרא בפרק החולץ (יבמות דף מג:) ומ\"ש אם איפשר לו כלומר אם עשיר היא ויכול לזונן וכן פירש\"י כתב הריב\"ש בתשובה סימן א' שנשאל על יבמה שנשארה זקוקה לב' אחים והגדול הוא מאנוסי הזמן והשני יהודי מי קודם לחלוץ וכן אם קדם הגדול וחלץ אם צריכה לחזור גם על השני לחלוץ ממנו. והשיב היהודי קודם לחלוץ שלעולם יש לחזר אחר חליצה מעולה וכיון שיהודי יכול לחלוץ או לייבם חליצתו מעולה אמנם אם הגדול קדם וחלץ ודאי הותרה לשוק ואינה צריכה חליצה מן השני שהרי אין כאן חליצה פסולה דישראל הוא לענין גיטין וקידושין ואם בא עליה קנאה ויוצאה בגט ואינה צריכה חליצה ובסימן קנ\"ט כתב שנשאל על יבמה שנפלה לפני ב' יבמין וקפץ הגדול ונשבע שלא ייבם ולא יחלוץ והשני אומר עליך המצוה כי אתה הגדול והשיב שמנדי' אותו עד שיפטור אותה לכל הפחות בחליצה אם לא ירצה ביבום ואם ירצה ביבום יהיה נשאל על שבועתו וייבם או יחלוץ וטוב לו זה להסיר כל ספק ולא יחשדוהו כעובר על שבועת דלאו כ\"ע דינא גמירי ואין כופין כלל את הקטן כיון שהגדול הוא בעיר ונתבאר בתשובה זו שאם היו ג' יבמים והגדול אסור בה מפני שהוא נשוי אחותה הו\"ל כמאן דליתיה והשני נכנס תחתיו והוא הגדול :"],["\u0003מי שהיו לו נשים רבות וכו'\u0004 משנה וגמרא פרק החולץ (יבמות דף מ\"ד) וכתב ב\"י דמ\"ש ואינו חולץ אלא א' מהן כדי נסבא שכבר כתב שחליצתה של א' מהן פוטרת את כולן ושרי ליה מריה דא\"כ מ\"ש דאינו יכול לייבם אלא אחת מהן נמי כדי נסבא שכבר כתב דביאה של א' מהן פוטרת את כולן אלא צריך לפרש דלאו כדי נסבא דלעיל קאמר דפוטרת את כולן ואין צריך לייבם עוד וכאן אשמועינן דאיסורא קא עביד דבית א' הוא בונה ואינו בונה ב' בתים והויא אשת אח שלא במקום מצוה כדאיתא התם וא\"כ בחליצה נמי איסורא דאורייתא היא לחלוץ יותר מאחר כדאיתא התם בית חלוץ הנעל בית אחד הוא חולץ ואינו חולץ ב' בתים וכך מבואר לשם בתוספות בד\"ה ונייבם לחדא דאסור ד\"ת לחלוץ ב' בתים ועיין עוד בתוס' בפ\"ק סוף (דף י\"ב) בד\"ה איהו כתבו כך בפי' ולפ\"ז הא דכתב רבינו ואין היבם יכול לייבם אלא אחת מהם ולא חולץ אלא אחת מהן הא דכתב ואין היבם יכול חוזר גם על מ\"ש ולא חולץ אלא אחת מהם דגם לחלוץ אינו יכול כלומר אינו רשאי דאיסורא דאורייתא היא דלא כמה שפי' ב\"י ולא חולץ אלא אחת מהן כלומר א\"צ לחלוץ אלא אחת מהן דאלמא דליכא איסורא דליתא אלא איסורא דאורייתא הוא כדפירש' ונראה דאם עבר וחלץ לב' בתים אעפ\"י דשנייה מותרת לכהן כיון דלא היה צריך לחלוץ לה אפ\"ה אסורה מדרבנן לינשא לכהן שמא יאמרו חלוצה מותרת לכהן כדלעיל בסוף סימן קנ\"ו:","\u0003ומצוה על הגדול שבהם וכו'\u0004 משנה וגמרא לשם (ד\" ל\"ח) ואע\"ג דבמשנה תנן מצוה בגדול לייבם לא רצה לייבם מהלכין על כל האחין אין פירושו לא רצה לייבם אלא לחלוץ דהתם אין מהלכין על כל האחין אלא כיון שהגדול רוצה לחלוץ חולץ והא דאמרינן ביאת קטן עדיפא מחליצת גדול היינו דוקא כששניהם לפנינו והגדול רוצה לחלוץ והקטן רוצה לייבם אבל הכא מיירי דלא ידעינן מאי דעתיה דקטן דבתחילה חייבת היבמה לתבוע את הגדול לייבם או לחלוץ כדכתיב בקרא והיה הבכור ואז אם אינו רוצה לייבם אלא לחלוץ חולץ דעל הבכור קאמר קרא אם לא יחפוץ וגו' ואינה צריכה לילך אל הקטן ולשאול את פיו אם רוצה לייבם אלא כיון שהגדול רוצה לחלוץ חולץ וכ\"כ הרמב\"ם בפ\"ב:","ומ\"ש לא רצה חוזרין על כל האחין דרך גדילתן בפרק כיצד (דף כ\"ד) תני אביי קשישא מצוה בגדול לייבם לא רצה הולכין אצל אחיו לא רצה חוזרין אצל גדול ופירש\"י הולכין אצל קטן משמע קטן הימנו וגדול משאר אחיו אלמא מהדרינן אגדול דגדול קודם וכו' כ\"כ התוספות לשם יותר בביאור והוא דעת הראב\"ד בהשגות פ\"ב וגורס בהך דאביי קשישא מצוה בגדול לייבם לא רצה הולכין אחר גדול אלמא כל הגדול מחבירו הוא קודם למצוה וכך הוא דעת הרשב\"א כמ\"ש ה\"ה לשם משמו דלא כדעת הרמב\"ם לשם דמאחר שנסתלק הגדול שוב אין דין קדימה לאחד על השאר וז\"ש רבינו חוזרין על כל האחין זא\"ז דרך גדילתן והכי נקטינן:","וכופין אותו לחלוץ ואין כופין אותו לייבם וכ\"כ הרמב\"ם לשם ואעפ\"י דלהרמב\"ם מצות יבום קודמת אפ\"ה אין כופין לייבם דאין אדם דר עם נחש ב\"י בשם הר\"ש בן הרשב\"ץ וכן אם היה גדול במדינה אחרת וכו' אע\"ג דבמשנה נקט מדינת הים לאו דוקא מ\"ה אלא לכל מקום רחוק קרו לה מ\"ה ולפי שלא נמצא גבול לריחוק זה נקט רבינו מדינה אחרת שכל שהוא מדינה אחרת דהיינו דחלוקים בלשונם הו\"ל מקום רחוק ואיכא למיחש לענין אם תמתין עליו וכ\"כ נ\"י שהויי מצוה לא משהינן ולא נעגן אותה עכ\"ל וכ\"כ הרמב\"ם וכן אם היה הגדול במדינה האחרת דס\"ל דלמדינה אחרת שהוא מקום רחוק קרי לה מ\"ה וכ\"כ התוס' ריש גיטין בהא דתנן המביא גט ממ\"ה דפירש\"י כל ח\"ל דלהכי נקט ממ\"ה דמשמע רחוק כמו האשה שהלך בעלה למ\"ה פרעתיך בפני פלוני ופלוני והלכו למ\"ה לאפוקי רקם וחגר דפליג בהו ר\"ג עכ\"ל לפ\"ז משמע להדיא דדוקא מדינה אחרת אבל היה הגדול בעיר אחת מאותה הארץ שאינם חלוקין בלשונם שפיר יכול לתלות בגדול או תלך היא אליו ויחלוץ לה לשם ואשכחן דקרי לה מדינה אחרת בחלוקים בלשונם לעיל ריש סימן ע\"ה:","\u0003היו לו אחים רבים וכו'\u0004 משנה פרק החולץ סוף (יבמות דף מ\"ג) ואיכא למידק דבגמ' לשם מסיק דאעפ\"י דאפשר לו לפרנס את כולן דעשיה הוא עצה טובה קמ\"ל דלא לייבם אלא ד' ולשאר יחלוץ אבל טפי מד' לא לייבם כי היכי דנמטייה עונה בחדש ואמאי לא כתבו רבינו כאן ולא הרמב\"ם בפ\"ב דיבום ויש לומר דהרמב\"ם נסמך על מ\"ש בפי\"ד דאישות שלא ישא אדם יותר על ד' נשים דבכלל זה גם כן שלא ייבם יותר מד' גם רבינו נסמך על מ\"ש דברי הרמב\"ם בזה לעיל בסימן ע\"ז:"]],["\u0010c0\u0011\u0010y0\u0011הכונס את יבמתו נאסרו צרותיהן עליו ועל שאר האחין ואם בא הוא או אחד משאר האחין על הצרה אין עוברין אלא בעשה לפיכך תפסי בה קידושין ואין הולד ממנה ממזר \u0010y1\u0011החולץ ליבמתו נאסרה החלוצה היא וצרותיה עליו ועל שאר האחין ואינה אלא בעשה לפיכך תפסי בהו קידושין ואין הולד ממזר \u0010y2\u0011וכשם שהחולץ אסור בחלוצה כך אסור בכל קרובותיה \u0010c1\u0011כגון באמה ובבתה והיא אסורה בבנו ובאחיו ואפילו באיסור שניות כגון אם אם אמה ובת בן בנו כמו בגרושתו \u0010c2\u0011לפיכך מתה מותר באחותה והאחין מותרין בכל קרובות החלוצה \u0010y3\u0011החולץ מותר באחות צרת החלוצה ובשאר קרובותיה ואסור בצרת אחות החלוצה ופירש\"י אפילו אם נשואה לאיש נכרי ור\"י פירש אם היא נשואה לאיש נכרי מותרת ואינה אסורה לו אא\"כ נשואה לאחין וכן הוא מסקנת א\"א ז\"ל:",["הכונס את יבמתו נאסרו צרותיהן עליו ועל כל שאר האחין פשוט הוא בפ\"ק דיבמות (י:) ואם בא הוא או א' משאר האחין על הצרה אין עוברין אלא בעשה לפיכך תפסו בה קידושין ואין הולד ממנה ממזר שם :","החולץ ליבמתו נאסרה החלוצה היא וצרותיה עליו ועל שאר האחין ואינה אלא בעשה לפיכך תפסי בהו קידושין ואין הולד ממזר בפרק החולץ (יבמות דף מ:) אמר רב טובי בר קיסנא אמר שמואל הבא על צרת חלוצתו הולד ממזר מאי טעמא באיסורא קיימא וכתבו הרי\"ף והרא\"ש ז\"ל וליתא להא דשמואל דגרסינן בפרק קמא איתמר החולץ ליבמתו וחזר וקדשה אר\"ל הוא אינו חייב על חלוצתו כרת והאחין חייבים על חלוצתו כרת בין הוא ובין אחין חייבין על צרתה כרת ור\"י אמר בין הוא בין האחין אין חייבין לא על החלוצה כרת ולא על הצרה כרת ואמרי' מ\"ט דר\"ל אמר קרא אשר לא יבנה כיון שלא בנה שוב אינו בונה איהו הוא דקאי בלא יבנה הא אחין באיסור אשת אח כדקיימי קיימי ועלה דידה הוא דקאי בלא יבנה הא צרה כדקיימי קיימי ור\"י מי איכא מידי דמעיקרא איבעי האי חליץ ואי בעי האי חליץ ואי בעי להאי מייבם ואי בעי להאי מייבם והשתא קאי עלה בכרת אלא איהו שליחותא דאחין קא עביד איהי נמי שליחותא דצרה קא עבדת ואמרינן תו איתמר הבא על יבמתו וחזר ובא הוא או אחד מן האחין על צרתה פליגי בה רב אחא ורבינא חד אמר בעשה וחד אמר בכרת מ\"ד בעשה כר\"י ומ\"ד בכרת כר\"ל וקי\"ל היכא דפליגי רב אחא ורבינא הלכה כדברי המיקל וכ\"ש הכא דקאי ר\"י כוותיה ופירש\"י בעשה דכתיב אשר לא יבנה את בית אחיו בית אחד הוא בונה ואינו בונה ב' בתים ולאו הבא מכלל עשה עשה והרמב\"ם כ' בפ\"א דעשה היינו מדכתיב יבמה יבא עליה ולא על צרתה ולאו הבא מכלל עשה עשה ודע שהרמב\"ם כתב בפ' הנזכר גבי חולץ ליבמתו נאסרה היא וכל צרותיה עליו ועל שאר האחין וכולן אסורות עליהן מד\"ס כשניות שמאחר שמת אחיו נסתלק איסור ערוה מעל כל נשיו וה\"ה תמה עליו דהא משמע בגמרא דלר\"י בלאו קיימא ושהרבה מפרשים כתבו כן שהרמב\"ם השיג על הרמב\"ם בזה:","וכשם שהחולץ אסור בחלוצה כך אסור בכל קרובותיה כגון באמה ובבתה והיא אסורה בבנו ובאביו משנה בפרק החולץ (שם). ומ\"ש ואפילו באיסור שניות כגון אם אם אמה ובת בן בנו כמו בגרושתו שם בעיא דאיפשיטא. ומ\"ש לפיכך מתה מותר באחותה משנה שם יבמתו שמתה מותר באחותה וכבר אמרו בגמרא דמשנה דאינה צריכה היא דזיל קרי בי רב הוא דאפילו אשתו גמורה לא נאסרה אחותה עליו אלא בחייה ולשון לפיכך שכתב רבינו אינו מכוון וצריך לדחוק ולפרש דה\"ק לפיכך כיון שהוא אסור בקרובותיה אינו מותר באחותה אא\"כ מתה. ומ\"ש והאחין מותרין בכל קרובות החלוצה משנה שם:","החולץ מותרת באחות צרת החלוצה ובשאר קרובותיה ואסור בצרת אחות החלוצה משנה שם מותר אדם בקרובת צרת חלוצתו ואסור בצרת קרובת חלוצתו ובגמרא (שם) מאי שנא האי ומ\"ש האי הך דאזלא בהדה לב\"ד גזרו בה רבנן הך דלא אזלא בהדה לב\"ד לא גזרו בה רבנן ופירש\"י מ\"ש. רישא קרובת צרת חלוצה דשריא. ומ\"ש סיפא צרת קרובת חלוצתו ששתיהן נכריות היא וצרתה ונשואות לנכרי וקתני אסור: הא דאזלא בהדה לבית דין. כשלאה חולצת מוליכה אחותה עמה לב\"ד וכ\"ע לא ידעי הי מינייהו יבמתו ואיכא דסבר דלרחל חלץ וכי נסיב צרת רחל דהיינו צרת קרובת חלוצתו אמרי צרת חלוצתו נסיב ואינהו סברי שרחל וצרת נשי אחיו הוו שהרי לרחל חלץ: הא דלא אזלא בהדה לב\"ד. כשהיבמה חולצת אין צרתה הולכת עמה הילכך כי נסיב אחות הצרה לא אמרי אחות חלוצתו נסיב עכ\"ל והתוס' תמהו על פירושו והקשו עליו כמה קושיות ונראה לר\"י דגרסי' הא דאזלא בהדה לב\"ד פי' שהולכת לחלוץ וכיון דחלצה דמיא לגרושה טפי ואסרו גם צרת קרובתה כשנשואה לאחיו דדמיא לצרת ערוה אבל כשחולצת צרת לאה ולא לאה לא דמיא לאה לגרושה הילכך קרובתה שריא: ומ\"ש וכן הוא מסקנת א\"א ז\"ל שם:"],["\u0003הכונס את יבמתו נאסרות צרותיה וכו'\u0004 עד אלא בעשה בפ\"ק (דף י') איתמר החולץ ליבמתו וחזר וקדשה פליגי בה ר\"ל ור' יוחנן ר\"ל אמר בין הוא בין האחין חייבין על צרתה כרת ועל החלוצה הוא אינו חייב כרת והאחין חייבין עליה כרת ור\"י אמר בין הוא בין אחין אינן חייבין לא על החלוצה כרת ולא על הצרה כרת ומפרש התם פלוגתייהו (ובדף י\"א) איתמר הבא על יבמה ובא א' מן האחין על צרתה פליגי בה רב אחא ורבינא חד אמר בכרת כריש לקיש וחד אמר בעשה כרבי יוחנן וקי\"ל כל היכא דפליגי רב אחא ורבינא הלכה כדברי המיקל וכן כתב האלפסי והרא\"ש פרק החולץ ופירש\"י בעשה בית א' הוא בונה ואינו בונה ב' בתים ולאו הבא מכלל עשה עשה עכ\"ל והא דקאמר איתיביה ר\"י לר\"ל החולץ ליבמתו וחזר וקדשה צריכה חליצה מן האחים בשלמא לדידי דאמינא חייבי לאוין נינהו וכו' היינו לומר חייבי לאוין הבאים מן העשה אבל התוספות בד\"ה חד אמר בעשה הקשו על גירסת הקונטרס ושר\"ת גורס חד אמר בלאו וכן פי' ר\"ת וכו' וכן כתבו עוד התוס' בפרק ואלו נערות בדף ל' בד\"ה אי לאפוקי אבל רבינו נמשך אחר גירסת רש\"י והרי\"ף והרא\"ש מיהו קשה תינח בבא על יבמתו ובא הוא או אחד מן האחין על צרתה דאינו אלא בעשה כדפי' אבל בחולץ לה ובא הוא או אחד מן האחין על צרתה דקאי עלה בלאו דלא יבנה כיון דלא בנה שוב לא יבנה דהוי לאו גמור ואפ\"ה כתב רבינו דאינו אלא בעשה וצ\"ע:","כגון באמה ובבתה לאו דוקא דה\"ה באחותה נמי אסור כיון שחלץ לה ואם לא חלץ לה היה מותר באמה ובבתה ובאחותה וכן מ\"ש והיא אסורה בבנו ובאחיו היינו מפני שחלץ לה דאי לא חלץ לה היתה מותרת לבנו ולאחיו דאחיו היה מייבם אותה אבל לאביו אסורה אפי' לא חלץ לה שהרי היא כלתו אשת המת וכלשון רבי' כ\"כ הרמב\"ם בפ\"א ה\"ג כגון אם אם אמה ובת בן בנה דבהני תרתי אסור החולץ כמו בגרושתו וי\"ס גורסין ובן בן בנו וקאי אחלוצה דהיא אסורה לבן בן בנו וכ\"כ הרמב\"ם בפ\"א:","לפיכך מתה מותר באחותה הלשון מגומגם וב\"י נדחק בפירושו ואפשר דלפי שהתוס' הקשו על פירש\"י בסמוך שפירש דאפילו בנשואות לאיש נכרי אסור בצרת אחות החלוצה דסברי אינשי דחזו דאזלא אחותה עמה לבית דין דלאחותה חלץ וקנסיב צרת חלוצתו דא\"כ אפילו מתה נמי ליתסר באחותה ומכח קושיא זו הסכים הרא\"ש לפר\"י כמו שכתב רבינו בסמוך לכן הקדים לומר לפיכך מתה מותר באחותה להוציא מפירש\"י ולפ\"ז יותר מתוקן היה לגרוס האי לפיכך מתה מותר באחותה בסוף פירוש ר\"י:"]],["\u0010c0\u0011\u0010y0\u0011המייבם זוכה בנכסי המת ועומד במקומו ליטול חלקו בנכסי אביהן \u0010y1\u0011ודוקא במוחזק כגון שמת אביהם ואח\"כ מת אחיו \u0010c1\u0011קודם שחלקו אז נוטל חלק אחיו בנכסי אביהם אבל לא בראוי כגון אם מת אחיו ואח\"כ אביהם לא יטול חלק אחיו ואפי' במוחזק לא יטול אלא בגוף הנכסים אבל אם ישביחו הנכסים אינו נוטל חלק אחיו באותו שבח אפילו אם שבחו אחר יבום קודם חלוקה החולץ הוא כאחד משאר האחין לנחלה ואם האב קיים הוא יורש הכל \u0010y2\u0011ואם מת יחלקו האחין ביניהם \u0010c2\u0011\u0010y3\u0011יבם היבם לסוף ב' חדשים למיתת אחיו וילדה לסוף ט' חדשים ספק אם הוא בן ט' חדשים לראשון או בן ז' לשני ותובע הספק נכסי המת שאומר שהוא בנו והיבם אומר אני יורשו כי אתה בני \u0010c3\u0011אם אבי המת קיים אז יחלקו היבם והספק ביניהם אפילו אחד מהם מוחזק אין שומעין לו לחזקתו אלא חולקין ואם מת הסבא אז יטול היבם הכל ואם הסבא קיים דהוי דינא דיחלוקו הספק והיבם ומת הספק קודם חלוקה יחלקו הסבא והיבם \u0010y4\u0011ספק ובני יבם שבאו לחלוק בנכסי המת הוא אומר אני בן המת ואטול הכל והם אומרים אחינו אתה ואין לך חלק אלא כאחד ממנו החלק שהם מודים לו יטול הכל והשאר יחלקו ביניהם ויטול הוא החצי והן כולם החצי \u0010y5\u0011ספק ובני יבם שבאו לחלוק בנכסי יבם לאחר שחלק היבם בנכסי המת ואומר הספק ממ\"נ אם אחיכם אני תנו לי חלק עמכם ומה שלקחתי בנכסי המת עם אביכם אחזיר ונחלוק הכל ואם אינני אחיכם תחזרו לי נכסי אבי שלקח אביכם מנכסי המת בזה מחלוקת בין הפוסקים י\"א שהדין עמו וי\"א שהדין עם בני היבם וכתב א\"א ז\"ל כיון דאיכא פלוגתא דרבוותא לא מפקינן מבני יבם \u0010c4\u0011\u0010y6\u0011ספק ויבם שבאו לחלוק בנכסי סבא ואומר הספק אני בן המת ויש לי ליטול החצי אין שומעין לו ספק ובני יבם שבאו לחלוק בנכסי הסבא אומר הספק אני בן המת ויש לי ליטול החצי והם אומרים לא כי אלא אתה אחינו ואין לך אלא השליש כאחד ממנו בחצי שהוא מודה להם יטלו הם והשליש שהם מודים לו יטול הוא והשתות הנשאר שהם חולקים עליו יחלקו ביניהם ויטול הוא חציו והם חציו \u0010y7\u0011סבא ויבם בנכסי ספק או ספק וסבא בנכסי יבם חולקים:",["המייבם זוכה בנכסי המת בפרק החולץ (יבמות דף מ:) ומייתי לה בגמרא מדכתיב יקום על שם אחיו.","\u0003ומה שכתב ודוקא במוחזק כו'\u0004 ואפילו במוחזק לא יטול אלא בגוף הנכסים כו' בפרק יש בכור (בכורות דף נא: נב.) תנן דיבם אינו נוטל בשבח ולא בראוי כבמוחזק ויהיב טעמא בגמרא משום דבכור קרייה רחמנא דכתיב והיה הבכור ובכור מייתי התם מקראי דאינו נוטל בשבח ולא בראוי כבמוחזק. ומ\"ש אפילו אם שבחו אחרי יבום קודם חלוקה שם פלוגתא דאביי ורבא והלכה כרבא דאמר הכי. כתב הריב\"ש בתשובה סימן ת\"ע על מי שמת והניח ג' בנים וציוה שתהא אשתו רשאה ושלטאה בכל נכסיו ומת אחד מהם וייבם השני את אשתו שהוא נוטל חלק אחיו המת כולה ולא נגרע כחו מפני מ\"ש לאשתו שתהא רשאה ושלטאה בנכסים ומיהו בשטרות אינו נוטל חלק המת יתר על החי משום דמלוה הוי ראוי ואינו נוטל בראוי כדבסמוך עיין במישרים נכ\"ג חי\"ב לענין שבחו נכסים אחרי יבום קודם חליצה: תחולץ הרי הוא כאחד מן האחים לנחלה ואם האב קיים הוא יורש הכל משנה בפרק החולץ (שם) ובגמרא הרי הוא כאחד מן האחין פשיטא סד\"א הואיל ואפסדה מיבום ליקנסיה קמ\"ל. אם יש אב נכסים של אב דאמר מר האב קודם לכל יוצאי יריכו לנחלה:","\u0003ומ\"ש אם מת יחלוקו האחים ביניהם פשוט הוא:\u0004 ","ייבם היבם לסוף ב' חדשים למיתת אחיו וילדה לסוף ט' חדשים ספק אם הוא בן ט' חדשים לראשון או בן שבעה לשני ותובע הספק נכסי המת שאומר שהוא בנו והיבם אומר אני יורשו כי אתה בני כו' בפרק החולץ (יבמות דף לז:) ספק ויבם שבאו לחלוק בנכסי מיתנא ספק אמר אנא בר מיתנא ונכסי דידי הוא ויבם אמר את בראי דידי את ולית לך ולא מידי בנכסי' הוי ממון המוטל בספק וממון המוטל בספק חולקין וכתב הרא\"ש ואפילו רבנן דפליגי עליה דסומכוס מודי הכא שאין שייך כאן המע\"ה שאין זה מוחזק יותר מזה והוי כמו הללו באים לירש והללו באים לירש דאמרי' במי שמת (קנא:) יחלוקו ואפילו אחד מהם מוחזק בנכסים אינה חזקה כיון דנכסי בחזקת מיתנא הוו ותרווייהו אתו בטענת ספק ואם הוא כדברי אחד מהם אין לשני זכייה בהם הילכך הוי ספק וחולקין ותימה ולימא היבם דל מהכא היבום שזכיתי בנכסים מכח היבום מ\"מ אני יורש דמיתנא ואתה ספק ותנן (יבמות ק:) הוא אינו יורש אותו אלא הקרוב קרוב יורש כי הוחזקה הנחלה לאותו השבט והוא לא יוציא הנחלה מחזקתה מספק וצ\"ל דמיירי שהסבא קיים הילכך מכח קורבה אין היבם זוכה בנכסים כי האב קודם והוא צריך לזכות מכח טענה דאת ברי דידי וזו טענת ספק הוא ומ\"מ הסבא נסתלק מן הנכסים בין שהוא בר מיתנא בין שהוא בן היבם הילכך חולקין הנכסים ביניהם ואם מת ספק מקמי חלוקה וסבא אמר בר מיתנא היה ונכסי דידי נינהו חולקין עכ\"ל:","ה\"ג ספק ובני יבם שבאו לחלוק בנכסי המת ספק אומר אני בן המת ואטול הכל ובני היבם אומרים אחינו אתה ואין לך בנכסים אלא חלק אחד כאחד ממנו החלק שהם מודים יטול הכל והשאר יחלוקו ביניהם ויטול הוא החצי ובין כולם החצי ובקצת ספרי רבינו חסר בבא זו וטעות סופר הוא שדילג הבבא הזאת והתחיל הבבא שאחריה המתחלת ספק ובני יבם שבאו לחלוק בנכסי יבם לאחר שחלק יבם בנכסי המת וכו' ודין זה שם בפרק החולץ ספק ובני יבם שבאו לחלוק בנכסי מיתנא ספק אמר ההוא גברא בר מיתנא ונכסי דידי הוו ובני יבם אמרי את אחונא את ומנתא אית לך בהדן סבור רבנן קמיה דרב משרשיא למימר מתניתין היא דתנן הוא אינו יורש אותם והם יורשים אותו והכא איפכא התם אמרו ליה הבא ראיה ושקול הכא אמר להו הביאו ראיה ושקולו א\"ל רב משרשיא מי דמי התם אינהו ודאי והוא ספק הכא אידי ואידי ספק אלא אי דמיא למתני' להא דמיא ספק ובני יבם שבאו לחלוק בנכסי יבם גופיה דהתם אמרי ליה אייתי ראיה דאחונא את ושקול וכתב הרא\"ש ז\"ל א\"ל רב משרשיא מי דמי התם אינהו ודאי ואיהו ספק הכא אידי ואידי ספיקי נינהו שגם הספק אינו טוען טענת ודאי שאינו יודע מכח מי בא לירש ובשביל שיש לו זכייה במקצת הנכסים לא חשיב כמוחזק בשאר הנכסים שהוא בא עליהם בטענת ספק אלא הכי הוי דינא מנתא דקא מודו ליה שקיל ואידך הוי ממון המוטל בספק וחולקין הוא נוטל החצי ובין כולם החצי עכ\"ל:","\u0003ספק ובני יבם שבאו לחלוק בנכסי יבם לאחר שחלק היבם בנכסי המת כו'\u0004 שם ספק ובני יבם שבאו לחלוק בנכסי יבם לבתר דפליג יבם בנכסי מיתנא בני יבם אמרי אייתי ראיה דאחונא את ושקול א\"ל ספק מה נפשייכו אי אחוכון אנא הבו לי מנתא בהדייכו ואי בר מיתנא אנא הבו לי פלגא דפליג אבוכון בהדאי רבי אבא אמר קם דינא רבי ירמיה אמר הדר דינא ופירש\"י אי אחוכון אנא הבו לי מנתא בהדייכו אי משום דשקלי אנא פלגא בנכסי מיתנא מהדרנא לכו ההוא פלגא ונחלוק עתה הכל בשוה בין נכסי הראשון בין נכסי האחרון וכגון שהיו נכסי היבם מרובים ואחיו מועטים. קם דינא. אחר שנעשה דין בנכסי המת אין זה יכול לחזור ולערער ומה שהוא שואל בנכסי היבם אמרינן ליה אייתי ראיה: הדר דינא. ומהדרי ליה פלגא דנכסי מיתנא או פלג כולהו נכסי בשוה וכתב רב אלפס כתבו רבוותא דהלכתא כרבי אבא משום דקים ליה כרבנן: \u0005ב\"ה וכן פסק הרמב\"ם בפ\"ה מה' נחלות \u0006וכתב הרא\"ש הראב\"ד כתב ליתא להאי טעמא דהא א\"ר ירמיה אנא דאמרי אפי' לרבנן וכו' ומ\"מ הלכתא כרבי אבא משום דר' אבא דיינא הוא ונחית לעומקא דדינא והרמב\"ן השיב דכיון דלכאורה נראה לבני הישיבה דרבי אבא כרבנן ורבי ירמיה כאדמון סברתם עיקר ולא סמכינן אשינוייא דשני מילתייהו כתרווייהו כי דרך התלמוד לדחותה בסברא מועטת ועוד דלא תהא אלא ספיקא והיבם תופס ברשות והנכסים ביד בניו ועל הספק להביא ראיה כדין כל ספיקא ותיקו שבדיני ממונות והר\"ז הלוי כתב ממאי דאיפסקא הלכתא בפ\"ק דבתרא (ד:) כרבי יוסי דאמר מגלגלין עליו את הכל מטעם הדר דינא ובפרק בית כור (בבא בתרא קו:) איפסקא הלכתא כרב דאמר בטלה מחלוקת וא\"ל רב נחמן אלמא הדר דינא מכל זה הדעת מכרעת כרבי ירמיה דאמר הדר דינא וכיון דאיפליגו בה רבוותא לא מפקינן מבני יבם עכ\"ל: \u0005ב\"ה עיין במ\"מ פ\"ה מהלכות נחלות: \u0006ספק ויבם שבאו לחלוק בנכסי סבא כו' פשוט שם (לח.) בגמרא משום דהוי יבם ודאי וספק ספק ואין ספק מוציא מידי ודאי:","ספק ובני יבם שבאו לחלוק בנכסי סבא כולי גם זה שם בגמרא פלגא דקא מודה להו שקלי תילתא דקא מודו ליה שקיל פש להו דנקא הוי ממון המוטל בספק וחולקין:","סבא ויבם בנכסי ספק או ספק וסבא בנכסי יבם חולקין גם זה שם בגמרא משום דהוי ממון המוטל בספק כתב בתשובות הרשב\"א סימן אלף ור\"מ אחד מן האחים שהיה בן שפחה ונסתפקו אם היתה הורתו ולידתו בקדושה אפילו ייבם את אשת אחיו אינו זוכה בנחלת אחיו המת בידם. \u0005ב\"ה כתב נ\"י בפרק הנזכר הכונס את יבמתו זכה בנכסי אחיו ואפילו גרשה למחר דכתיב יקום על שם אחיו והרי קם ומיהו אמרו בירושלמי שאם היא אסורה שאינו רשאי לקיימה אפילו מדרבנן כגון שתי יבמות שעשה מאמר בזו וכנסה לזו לא זכה בנכסים כלל עכ\"ל \u0006:"],["\u0003המייבם זוכה בנכסי המת וכו'.\u0004 ","ומ\"ש קודם שחלקו כלומר אף על פי שעדיין לא חלקו חשוב מוחזק דאם כבר חלקו נכסי המת ממש הן ולא איצטריך לאשמועי' דזכה בהן היבם דפשיטא דלא גרעי משאר נכסיו אלא מיירי קודם שחלקו דנקראו עדיין הנכסים על שם אביהם ואפי' הכי חשוב מוחזק דמיד שמת אביהם נפלו לפני בניו זכה כל אחד בחלק ירושתו אף על פי שלא חלקו והו\"ל מוחזק וכן מה שאינו נוטל בשבח מיירי דוקא בשבח ששבחו קודם חלוקה דבהא לא זכה בשעה שנפלו הנכסים לפני יורשים שלא היו בעולם ולא נקרא מוחזק אבל בנכסי המת ממש זכה בין בגוף בין בשבח וה\"ה דזכה בשבח ששבח חלקו בנכסי אביהם לאחר חלוקה דנכסי המת נקראו כדפרישית:","ייבם היבם לסוף ב' חדשים פי' דלא הגיע עדיין חדש שלישי אפילו יום אחד בחדשו לא היה ניכר עיבורה תלינן דבן שני הוא מדכתיב ויהי כמשלש חדשים וגו' דאלמא דהעובר ניכר מיד כשהגיע חדש שלישי אלא מיירי שיבמה לסוף ב' חדשים מקמי שהתחיל השלישי ומכ\"ש אם יבמה בתוך חדש השני או בתוך חדש הראשון דספק הוא ואף ע\"פ דבעינן צ' יום כמ\"ש לקמן בריש סימן קס\"ד היינו דלכתחילה אזלי' לחומרא אבל מדינא סגי ברובו של ראשון ורובו של שלישי ואמצעי שלם דהיינו ב' חדשים ויום אחד וכן היה מעשה כדאיתא בפ' החולץ (יבמות דף מ\"ג):","\u0003ומ\"ש אם אבי המת קיים וכו'\u0004 כך כתב הרא\"ש לחלק בכך וכתב טעמו ומביאו ב\"י. ומ\"ש אם מת ספק קודם חלוקה וכו' כ\"כ הרא\"ש וטעמו דלאחר חלוקה חשובים הנכסים שהגיעו לחלק הספק מן המת כשאר נכסי הספק ממש דחולקין בהן הסבא והיבם ולא יגיע לסבא אלא רביע מנכסי המת אבל כשמת הספק קודם חלוקה אז חולקין הסבא והיבם בנכסי המת בשוה ומגיע לסבא מחצה בנכסי המת וכן ליבם מחצה:","\u0003ספק ויבם שבאו לחלוק בנכסי סבא וכו'\u0004 פירש רש\"י בגמרא כיון דיבם אמר את בראי דידי ולית לך ולא מידי הוי יבם ודאי יורש ויודע מכח מי הוא בא ומוחזק בנכסים וספק ספק ואין ספק מוציא מידי ודאי ולא דמי לספק ובני יבם שבאו לחלוק בנכסי המת דספק אמר אני בן המת ונכסי כולהו דידי הוא ובני יבם אמרי אחינו אתה ואין לך אלא חלק כאחד ממנו ואפ\"ה לא אמרינן דהספק הוי ודאי יורש ובני יבם ספק ואין ספק מוציא מידי ודאי דהתם אע\"ג דספק אית ליה זכייה בנכסי ממ\"נ אפ\"ה לא חשיב ודאי דלא ידע מכח מי הוא בא לירש ע\"כ שיטת רש\"י ואכתי קשה בספק וסבא בנכסי יבם אמאי חולקין נימא נמי האב ודאי יורש והספק ספק כבר נשמר רש\"י לשם מקושיא זו שכתב וז\"ל וא\"ל האב ודאי מוחזק דאם זה בנו אין כאן לאב כלום וכיון דאיכא ספק דילמא כולהו דהאי או כולהו דהאי חולקין עכ\"ל פירוש לפי' דלא אמרינן הכא אין ספק מוציא מידי ודאי אלא דבאיכא תרתי חדא דהוא ודאי יורש לזה ויודע מכח מי הוא בא וגם מי דודאי מגיע לו עכ\"פ מקצת נכסיו ממ\"נ אבל אם הוא ודאי יורשו ויודע מכח מי הוא בא אלא דאיכא ספק דילמא אין מגיע לו כלום א\"נ מגיע לו ודאי דאית ליה זכייה בנכסים אבל אינו טוען טענת ודאי דאינו יודע מכח מי הוא בא לירש אין זה ודאי אלא אידי ואידי ספיקא נינהו ודו\"ק:"]],["\u0010c0\u0011\u0010y0\u0011היבמה לא תחלוץ ולא תתייבם עד שיהיו לה צ' יום ממיתת הבעל חוץ מיום המיתה ויום היבום ויום החליצה \u0010y1\u0011חלצה או נתייבמה תוך שלשה חדשים ולא נמצאת מעוברת הרי זו פטורה ואינה צריכה כלום אבל לא תינשא לאחר אע\"פ שחלצה עד שיהיו לה ג' הדשים ומיהו בשישלימו לה ג' חדשים למיתת הבעל תינשא אע\"פ שאין לה ג' חדשים אחר החליצה \u0010y2\u0011אבל אם מת היבם תוך ג' חדשים או אפילו אחר הג' צריכה להמתין שלשה חדשים אחרי מיתתו \u0010c1\u0011\u0010y3\u0011חלצה ונמצאת מעוברת וילדה אם הולד של קיימא אין החליצה כלום ומותרת לכהונה ומותר בקרובותיה \u0010y4\u0011ואם הפילה \u0010y5\u0011או ילדה ולא היה ל' יום צריכה חליצה אחרת שחליצת מעוברת לא שמה חליצה \u0010y6\u0011וכתב הרמב\"ם וחולץ לה או הוא או אחד משאר האחין \u0010y7\u0011וא\"א הרא\"ש ז\"ל כתב שלא יחלוץ לה הוא אע\"ג דחליצה קמייתא לאו כלום היא מ\"מ הורעה זיקתו והרי הוא כאילו נתן גט ולא מצי חליץ חליצה כשירה ע\"כ \u0010y8\u0011וכן ביאת מעוברת לא שמה ביאה \u0010c2\u0011\u0010y9\u0011לפיכך הכונס או חולץ ליבמתו תוך ג' חדשים ולה צרה לא תינשא עד שתלד זו דשמא תפיל ולא היתה הביאה והחליצה כלום והולד אינו פוטר עד שיצא לאויר העולם \u0010y10\u0011היבמה לא תתייבם בעת נדותה אבל חולצת היא ואם עבר ויבם ובא עליה בעת נדותה קנאה \u0010c3\u0011\u0010y11\u0011הכונס יבמתו ונמצאת מעוברת מפרישין אותה ממנו ואם הפילה יחזור ויקיים \u0010y12\u0011ואם ילדה ולא שהה הולד שלשים יום הרי זו ספק וצריכה גט וחליצה \u0010c4\u0011\u0010y13\u0011והרמ\"ה כתב כיון דספק הוא אין מוציאין אותה ממנו ואם שהה ל' יום ה\"ז של קיימא ויוציא ואינה צריכה כלום \u0010y14\u0011ואם יש לספקו בראשון כגון שכנסה לסוף ב' חדשים וילדה לסוף ז' ספק אם הוא בן ט' לא' או בן ז' לשני יוציא בגט והולד כשר \u0010y15\u0011ואם בא עליה אח\"כ וילדה הוי ספק ממזר \u0010y16\u0011יבמה שילדה אחר מיתת הבעל ומת הולד בתוך ל' יום או ביום ל' חולצת ולא מתייבמת ואם עמדה ונתקדשה לשוק אם לישראל נתקדשה חולצת ואם לכהן נתקדשה שתיאסר עליו אם תחלוץ לא תחלוץ \u0010y17\u0011ואם נתייבמה כ' הרמ\"ה כיון דספיקא הוא אין מוציאין אותה ממנו ולא נהירא דהא טעם דשרינן לה לכהן מספק משום דסמכינן אדרבנן דאמרי אע\"פ שלא שהה הוי בר קיימא והיא מותרת לשוק וא\"כ אדרבא מהאי טעמא נמי תצא מיבם דלרבנן הוי בר קיימא והוי אשת אחיו שלא במקום מצוה:",["\u0003היבמה לא תחלוץ ולא תתייבם עד שיהיו לה תשעים יום ממיתת הבעל כו'\u0004 משנה בפרק החולץ (יבמות דף מא) היבמה לא תחלוץ ולא תתייבם עד שיהיו לה ג' חדשים וכן שאר כל הנשים לא יתארסו עד שיהיו להן שלשה חדשים ומסיק בגמרא צריכה להמתין ג' חדשים חוץ מיום שמת בו וחוץ מיום שנתארסה בו:","חלצה או נתייבמה תוך ג' חדשים ולא נמצאת מעוברת הרי זו פטורה ואינה צריכה כלום אבל לא תינשא לאחר אף ע\"פ שחלצה עד שיהיו לה ג' חדשים ומיהו כשישלמו ג' חדשים למיתת הבעל תינשא ואף ע\"פ שאין לה ג' חדשים אחר החליצה בפ' החולץ (שם) ת\"ר יבמה שחלצו לה אחין בתוך ג' צריכה להמתין ג' חדשים לאחר ג' אין צריכה להמתין ג' חדשים הני ג' חדשים שאמרו משעת מיתת הבעל ולא משעת חליצת היבם: אם חלצה תוך ג' חדשים למיתת בעלה אם צריכה לחזור על כל האחים עיין בהגהות מרדכי דסוף גיטין :","ומ\"ש אבל אם מת היבם תוך ג' חדשים או אפי' אחר ג' צריכה להמתין ג' חדשים אחר מיתתו כ\"כ שם התוס' ז\"ל והרא\"ש והמרדכי בשם ר\"ת דדוקא חלץ שהחליצה מוכחת שלא בא עליה מידי דהוה אממאנת לפי שמיאונה מוכיח עליה שהיא קטנה אבל אם מת היבם אחר ג' חדשים צריכה להמתין שלשה חדשים דיותר קרובה היבמה לביאה מארוסה דגזרינן אטו נשואה וכתוב בת\"ה סימן רכ\"ד דהיינו דוקא היכא שאין שם אלא יבם אחד אבל אם היו ב' יבמים ומת אחד מהם מותרת להתייבם לשני תוך ג' חדשים למיתתו של ראשון:","חלצה ונמצאת מעוברת וילדה אם הולד של קיימא אין החליצה כלום ומותרת לכהונה ומותר בקרובותיה משנה ר\"פ החולץ (יבמות דף לה.):","ומ\"ש ואם הפילה או ילדה ולא חיה שלשים יום צריכה חליצה אחרת שחליצת מעוברת לא שמה חליצה שם איתמר החולץ למעוברת והפילה ר\"י אמר אינה צריכה חליצה אחרת מן האחין דחליצת מעוברת שמה חליצה ור\"ל אמר צריכה חליצה מן האחין דחליצת מעוברת לא שמה חליצה ואיפסיקא בגמ' בהא הלכה כר\"ל:","ומ\"ש או ילדה ולא חיה ל' יום הוא ע\"פ שנתבאר בסימן קנ\"ו שכל שלא חיה באדם ל' יום דינו כנפל אא\"כ ידוע שכלו לו חדשיו:","\u0003וכתב הרמב\"ם וחולץ לה הוא או אחד משאר האחין בפ\"א וכ\"כ התוס' בר\"פ החולץ:\u0004 ","\u0003וא\"א ז\"ל כתב שלא יחלוץ לה הוא וכו'\u0004 ז\"ל בר\"פ החולץ אהא דאמר ר\"ל צריכה חליצה מן האחין לאו דוקא דאיהו נמי מצי חליץ לה דחליצה קמייתא לאו כלום הוא ולא פקע זיקתו א\"נ אחין של מת קאמר א\"נ אע\"ג דחליצה קמייתא לאו שמה חליצה מ\"מ הורעה זיקתו והוי כאילו נתן גט ולא מצי תו חליץ חליצה כשרה עכ\"ל ומשמע לרבינו דלשון אחרון עיקר וכ\"כ ר\"י בשם הרמ\"ה וכתב עוד שאם כנס אין מוציאין מידו וכל זה מיירי שיצא לאויר העולם קיים דאם לא יצא לאויר העולם קיים או חולצת או מתייבמת :","וכן ביאת מעוברת לא שמה ביאה שם פלוגתא דר\"י ור\"ל והא איפסיקא בגמ' הלכתא כר\"ל דלאו שמה ביאה:","ומ\"ש לפיכך הכונס או חולץ ליבמתו תוך ג' חדשים ולה צרה לא תינשא עד שתלד זו דשמא תפיל ולא היתה ביאה והחליצה כלום והולד אינו פוטר עד שיצא לאויר העולם ברייתא שם:","היבמה לא תתייבם בעת נדותה אבל חולצת היא ואם עבר ויבם ובא עליה בעת נדותה קנאה ז\"ל הרא\"ש בריש יבמות יש שואלים אשה שהיתה נדה כשמת בעלה תאסר להתייבם אפילו טבלה כמו אחות אשה שאינה מתייבמת אף ע\"פ שמתה אשתו תשובה לדבריהם דלא שייך למילף מאחות אשה דלא דמיא לעריות שאסורות ליבם משום קורבא ומותרת לשאר העולם אבל נדה אסורה לכל ואף על גב דלאו בת ייבום היא חליצתה חליצה בעת נדתה ולא דמי לחליצת מעוברת דלא שמה חליצה לר\"ל משום דאינה עולה לייבום דשאני נדה שהיא עומדת לטבול ולטהר כדרך כל הנשים אבל מעוברת שמא תלד ועוד דאף אם בא עליה בעת נדתה קנאה כדמוכח בפסחים פרק אלו דברים (פסחים עב:):","הכונס יבמתו ונמצאת מעוברת מפרישין אותה ממנו ואם הפילה יחזור ויקיים כן כתב הרמב\"ם ז\"ל בפ\"א וכתב ה\"ה מ\"ש רבינו מפרישים אותה פשוט הוא שהרי ספק אשת אח שלא במקום מצוה הוא ומ\"ש אם הפילה הוא כשילדה ולד שלא נגמרו סימניו ולא כלו לו חדשיו שהוא קרוי נפל כנזכר למעלה בדעתו ז\"ל וכתב ר\"י יקיים ויחזור ויבעול דביאה ראשונה שהיתה מעוברת לא שמה ביאה וכתב הרמ\"ה ואם רוצה לחלוץ אינו די לה בחליצה אלא צריכה נמי גט כדי שלא יאמרו יבמה כנוסה יוצאה בחליצה:","ומ\"ש רבינו ואם ילדה ולא שהה הולד שלשים יום הרי זו ספק וצריכה גט וחליצה ז\"ל הרמב\"ם שם ואם ילדה אפי' מת ביום שנולד ה\"ז מוציאה בגט וחולץ לה ואח\"כ תהיה מותרת לאחרים וכתב ה\"ה מ\"ש ואם ילדה הוא בשלא נודע בבירור שכלו לו חדשיו אלא שנגמרו סימניו ולפיכך אינה צריכה חליצה בהכרח שכבר נתבאר למעלה שולד כזה פוטר מן התורה ואינו פוטר מדבריהם ולפי שאינו פוטר מדבריהם צריכה חליצה לזיקתו שאין ביאת המעוברת ביאה לפטור מן הייבום כנזכר למעלה וסבור ג\"כ רבינו שא\"כ צריכה גט לביאתו דדמיא לכנוסה וכן דעת קצת המפרשים וכ\"נ שהסכים הרא\"ה ז\"ל עכ\"ל:","\u0003ומ\"ש רבינו בשם הרמ\"ה כיון דספק הוא אין מוציאין אותה ממנו.\u0004 ואם שהה ל' יום ה\"ז של קיימא ויוציא ואינה צריכה כלום זה פשוט דכיון שהיא ערוה עליו אינה צריכה לא גט ולא חליצה. וכתב ה\"ה בפ\"א דה\"ה אם נודע בבירור שכלו לו חדשיו שיוציא ואינה צריכה כלום (וע\"ל סימן קנ\"ו):","\u0003ומ\"ש ואם יש לספקו בראשון כגון שכנסה לסוף ב' חדשים וכו'\u0004 יוציא בגט והולד כשר דמספיקא צריכה גט והולד כשר ממ\"נ והכי איתא במתני' פ' החולץ (יבמות ד' לה:):","ומ\"ש ואם בא עליה אח\"כ וילדה הוי ספק ממזר כלומר הבנים שהוליד ממנה הוו ספק ממזרים דהו\"ל ספק אשת אח והכי איתא בברייתא בפרק הנזכר:","יבמה שילדה אחר מיתת הבעל ומת הולד בתוך ל' יום או ביום ל' חולצת ולא מתייבמת ואם עמדה ונתקדשה לשוק אם לישראל נתקדשה חולצת ואם לכהן נתקדשה שתיאסר עליו אם תחלוץ לא תחלוץ בפרק החולץ (יבמות דף לו:) ובפרק ר\"א דמילה (שבת קלה.) אמר רבינא משמיה דרבא אם אשת ישראל היא חולצת ואם אשת כהן היא אינה חולצת ורב שרביא אמר אחד זו ואחד זו חולצת וכתב הרי\"ף בפרק החולץ וקי\"ל כרבינא דכיון דאיכא רבנן דפליגי עליה דרשב\"ג דאמרי אע\"ג דלא שהה ולד מעליא הוא גבי אשת כהן דלא איפשר דאי חליץ לה איתסרא על בעלה עבדינן כרבנן ולא מצרכינן לה חליצה ולגבי ישראל דלית בה פסידא עבדינן כרשב\"ג הילכך חליץ לה ועיילא לה לגבי גברא ואי כשנתקדשה מותבינן לה תותי גברא כ\"ש אם נישאת דלא מפקינן לה מתותי גברא והך דאמרינן התם לענין שומרת יבם שנישאת בלא חליצה לא שייך בהא מילתא דהתם ודאי בעיא חליצה אבל הכא כיון שמת תוך ל' יום ספיקא הוי ומספיקא לא מפקינן איתתא מתותי גברא וכ\"כ שם הרא\"ש ז\"ל: \u0005(ב\"ה וכן פי' הרמב\"ם בס\"פ שני ועיין עוד שם:) \u0006וכתב עוד אהא דאמר גבי אשת כהן דאי חלצה מיתסרא על בעלה עבדינן כרבנן ולא מצרכינן לה חליצה ואע\"ג דהשתא נשארת תחת בעלה בספק יבמה לשוק דאורייתא ואם היתה חולצת ונשארת תחת בעלה היתה עומדת בספק חלוצה דרבנן מ\"מ הא עדיפא טפי דאי חלצה אמרי קמו רבנן בולד דנפל הוא ולהכי הצריכוה חליצה ואתי למשרי חלוצה לכהן אבל כי לא מצרכת לה חליצה אמרי קמו רבנן בולד דולד מעליא הוי ולהכי לא אצרכוה רבנן חליצה ולא אתי למשרי יבמה לשוק עכ\"ל:.","ואם נתייבמה כתב הרמ\"ה כיון דספיקא הוא אין מוציאין אותה ממנו ולא נהירא דהא טעם דשרינן לה לכהן מספק משום דסמכינן אדרבנן וכו' וא\"כ אדרבא מהאי טעמא נמי תצא מיבם וכו' דברי רבינו ברורים בטעם שכבר נתבאר בסמוך דטעמא דשרינן לה לכהן מספיקא משום דסמכינן אדרבנן כולי ולהרמ\"ה צ\"ל שהוא סובר דלא הוי טעמא משום הכי דכיון דקי\"ל דהלכה כרשב\"ג לא חיישינן לרבנן אלא טעמא הוי משום דלא מפקינן לה מיניה מספיקא ולטעמיה אזיל שכתב גבי הכונס את יבמתו ונמצאת מעוברת וילדה ולא שהה ל' יום כיון דספק הוא אין מוציאין אותה ממנו ומיהו יש לתמוה עליו דכיון דספיקא דאורייתא ה\"ל למיזל הכא והכא לחומרא (וצ\"ע): \u0005ב\"ה צריך להעביר הקולמוס על וצ\"ע ולכתוב במקומו וי\"ל דמשמע ליה שזו ספיקא דרבנן היא כמו שכתב הרמב\"ם בסוף פרק שני:\u0006"],["\u0003היבמה לא תחלוץ וכו'\u0004 הכי אסיקנא פ' החולץ (יבמות דף מ\"ג) וחומרא מדרבנן הוא דלא צריך מדינא אלא ב' חדשים ויום אחד כמ\"ש בסימן קס\"ג ס\"ב: כתב בהגהות מרדכי סוף גיטין דבחלצה תוך ג' נחלקו בה רבותינו אם חליצה פסולה היא וצריכה לחזור על כל האחין או יחלוץ לה החולץ פעם שנית ולא תחזור על האחין משמע דאפי' למ\"ד א\"צ לחזור על כל האחין מ\"מ החולץ צריך שיחלוץ לה פעם שנית לאחר ג' ותימה על מ\"ש הרמב\"ם בפ\"א ורבינו דאין צריך כלום אלמא דאין צריך לחלוץ לה פעם שנית וצ\"ע:","\u0003חלצה ונמצאת מעוברת וכו'\u0004 פי' ובשעת חליצה לא היה ניכר כלל עוברה ונראית חליצה מעולה ואפ\"ה אם ילדה בר קיימא לא פסלה מן הכהונה ואם הפילה צריכה חליצה אחרת ומ\"ש שאם הפילה צריכה חליצה אחרת כ\"כ הרמב\"ם ספ\"א וכתב ה\"ה לשם דאסור בקרבותו בחליצה זו אע\"פ שאינה פוטרת ואף רבינו סבר כן וקצר בלשונו כמנהגו הטוב עכ\"ל","\u0003ומ\"ש לפיכך הכונס או חולץ ליבמתו תוך ג' חדשים ונמצאת מעוברת ולה צרה וכו'\u0004 והולד אינו פוטר וכו' ריש פ' החולץ ריש (יבמות דף ל\"ו) אסיקנא דברייתא הכי קתני הכונס יבמתו ונמצאת מעוברת ה\"ז לא תינשא צרתה שמא לא יהא ולד בן קיימא וחליצת מעוברת לא שמה חליצה וביאת מעוברת לא שמה ביאה וא\"ת הלך אחר רוב נשים ורוב נשים ולד מעליא ילדן ולד אינו פוטר עד שיצא לאויר העולם:","הכונס יבמתו ונמצאת מעוברת מפרישין אותה ממנו ואם הפילה יחזור ויקיים משנה וגמ' ר\"פ החולץ ובנ\"י לשם כתוב שהקשו למה לא קנסו חכמים שיוציא בגט (ובחליצה) כי היכי דקנסו בנשא מעוברת חבירו כדלעיל בסימן י\"ג ותירצו דכיון שלא הוכר עוברה וסבור היה לעשות מצוה לא רצו לקונסו ומיהו אם הוכר עוברה כתבו הריטב\"א ורבותיו ז\"ל דבהא ודאי קנסינן ליה להוציא בחליצה (ובגט) ואף ע\"פ שאין הולד של קיימא עכ\"ל מיהו לפי מ\"ש הרא\"ש בהא דיוציא מעוברת חבירו שהוא כדי שלא יבא עליה א\"כ הכא דאיסורא דאורייתא קעביד אם יבא עליה ל\"ח שיבא עליה ולא בעיא גיטא אלא הפרשה בעלמא כמ\"ש הרא\"ש לשם ר\"פ החולץ (סוף דף קל\"ג) ול\"ק מידי מיהו נראה דבהוכר עוברה וכנסה מודה גם הרא\"ש דלא סגי בהפרשה אלא צריך שיוציא בגט ובחליצה כיון דהוכר עוברה וכנסה א\"כ אינו חושש לאיסור דאורייתא ויבא עליה והכי נקטינן דבהוכר עוברה וכנסה דאסור לקיימה אלא יוציא לכל הדיעות ודו\"ק:","והרמ\"ה כתב כיון דספק הוא אין מוציאין ממנו פי' כיון דפליגי בה רשב\"ג ורבנן דלרשב\"ג לא שהה ספיקא הוא אי הוו בר קיימא ולרבנן ולד מעליא הוא ולא איפסיקא הילכתא מצי אמר קים לי כרשב\"ג ואין מוציאין ממנו ובסמוך נמי היכא דילדה ולא שהה ונתייבמה אח\"כ אין מוציאין מה\"ט דמצי אמר קים לי כרשב\"ג ורבינו ס\"ל דכיון דגבי כהן אין מוציאין אלמא דסמכינן אדרבנן שהם רבים ודבריהם עיקר ולכן השיג על הרמ\"ה בסמוך ואינה השגה דלגבי כהן מצי אמר קים לי כרבנן ולגבי יבם מצי אמר קים לי כרשב\"ג דהא לא איפסיקא הילכתא לא כמר ולא כמר ומה שלא השיג רבינו על הרמ\"ה הכא בנתייבמה ונמצאת מעוברת ה\"ט דכיון דבשעה שכונסה לא הוכר עוברה ואנוס היה שפיר הוא דאין מוציאין ממנו כיון דלא איפסיקא הילכתא ומצי אמר קים לי כרשב\"ג אבל בכנסה לאחר שילדה ולא שהה דבמזיד עבר אדרבנן סבירא ליה לרבינו דכיון דגבי כהן סמכינן אדרבנן הכא נמי סמכינן אדרבנן ולא מצי אמר קים לי כרשב\"ג ומוציאין אותה ממנו כנ\"ל לפרש דעת הרמ\"ה ודלא כפי' ב\"י ואח\"כ חזר ותמה עליו והניחו בצ\"ע גם נתיישב אמאי השיג רבינו אהרמ\"ה גבי ילדה ולא שהה ונתייבמה ולא השיג עליו בייבמה ונמצאת מעוברת וילדה ולא שהה וסברא זו לחלק בכך ס\"ל לנ\"י שהבאתי בסמוך ס\"ג ע\"ש:"]],["\u0010c0\u0011\u0010y0\u0011רב אלפס פסק שמצות יבום קודמת למצות חליצה וכ\"כ הרמב\"ם \u0010c1\u0011ורש\"י כתב שמצות חליצה קודמת ומכל מקום אם שניהם לפנינו ורוצין לייבם שומעין להם ולא חיישינן שמא אינם מכוונים לשם מצוה אבל אם אמרה לא בעינא ליה ואמרה דברים הנכרים אם יכולין להטעותו שיאמרו לו חלוץ לה על מנת שתתן לך מנה מטעינן ליה ואי לא כייפינן ליה וחליץ בכל אמתלא שתתן לדבריה \u0010c2\u0011ורבינו תם כתב דמצות חליצה קודמת ואפילו אם שניהם רוצים לייבם אין שומעין להן אא\"כ ידוע שמכווני' לשם מצוה כגון שבא לב\"ד לחלוץ ואמרו לו אי צבית ליבומי יבם מאז ודאי אי מייבמים מכוונין לשם מצוה כיון שבא לחלוץ מתחלה וכיוצא בזה אם רוצה לייבם וידוע שמכוין לשם מצוה והיא ממאנת אם יש לה טענה שהיתה מועלת לה אפילו כנגד בעלה כגון שהוא מאותן שכופין אותו להוציא כופין אותו נמי לחלוץ ואם לאו אם יכולין להטעותו שיחלוץ לה הרי טוב ואם אין יכולים להטעותו אין כופין לחלוץ \u0010y1\u0011וכן הוא מסקנת א\"א הרא\"ש ז\"ל \u0010y2\u0011וכתב עוד בתשובה על יבמה שנפלה לפני יבם נער ולא רצתה להתייבם בטענה שאמרה שהוא נער ובער ואין לו במה לפרנסה והוא לא רצה לחלוץ עד שיתנו לו דבר קצוב וכתב שאם יכולים להטעותו שיחלוץ מטעין ליה ואם לאו כופין אותו לחלוץ בחנם ובספר המצות כתב שאם יש לו אשה אחרת שכופין אותו ומנדין אותו עד שיחלוץ \u0010c3\u0011\u0010y3\u0011מתוך שפסק רב אלפס שמצות יבום קודם משמע שיבמה שאינה רוצה להתייבם שדינה כדץ מורדת \u0010c4\u0011\u0010y4\u0011וכ\"כ הרמב\"ם יבמה הראוי להתייבם ולא רצתה לתתייבם דינה כדין מורדת על בעלה וכופין אותו לחלוץ ותצא בלא כתובה \u0010y5\u0011הניח אחיו נשים רבות \u0010y6\u0011כל מי שתובע היבם לייבם ולא רצתה היא המורדת \u0010y7\u0011וחולץ לה ותצא בלא כתובה ושאר צרותיה שלא נתבעו נוטלות כתובתן כשאר האלמנות \u0010y8\u0011היו היבמים רבים ותבע אותה הגדול לייבם והיא אינה רוצה בו ורוצה באחיו אין שומעין לה שמצוה בגדול לייבם \u0010y9\u0011אמר הגדול איני רוצה לא לייבם ולא לחלוץ הרי אחי לפניך ותבע אותה אחד מן האחין לייבום והיא אומרת איני רוצה בו ורצתה באח אחד והוא רוצה בה אין זה מורדת מאחר שנסתלק הגדול שמצוה בו כולן שוין הואיל והיא רוצה באחד מהן והוא רוצה בה הרי לא מרדה ולא עוד אלא אם היה אחד מהם במדינה אחרת ואמרה הריני ממתנת עד שיבא וייבם אותי אבל זה איני רוצה בו אין זו מורדת ואומרים לזה שאינו הגדול ותובע אותה אם תרצה לחלוץ וליתן לה כתובה חלוץ ואם לאו הרי רצתה שתשב עד שיבא אחיך הואיל ואין לך דין קדימה עליו \u0010y10\u0011בא אותו שתלתה בו ולא רצה בה חוזרין אצל זה שתבע אותה לייבם והיא אינה רוצה ואומרים לה אין כאן מי שירצה לייבם אלא זה ומצות יבום קודמת או תתייבם או תצא בלא כתובה כדין כל מורדת ע\"כ \u0010y11\u0011אבל לר\"ת שמצות חליצה קודמת אין לה דין מורדת אלא כופין אותו לחלוץ אם הוא מאותן שכופין ואם לאו מטעין אותו אם יוכלו ואם לא יוכלו להטעותו אין כופין אותו אם ידוע שמכוין לשם מצוה אלא תשב לעולם: \u0010c5\u0011\u0010y12\u0011יבמה שנדרה הנאה מיבמה בחיי בעלה שיש הוכחה שלא כיונה לאסור עצמה על היבם \u0010y13\u0011או שנדרה הנאה מכל העולם בחיי בעלה כופין אותו לחלוץ ונותן לה כתובה נדרה מהיבם אחר מיתת הבעל או אפילו בחיי בעלה ונתכוונה בנדרה כדי לאסור עצמה על היבם מבקשין ממנו לחלוץ ואם אינו רוצה אין כופין וכתב רב אלפס שדינה כדין מורדת וכ\"כ הרמב\"ם שתצא בלא כתובה \u0010y14\u0011והראב\"ד כתב שאין כופין אותו לחלוץ ומ\"מ אין לה דין מורדת שתצא בלא כתובה \u0010c6\u0011\u0010y15\u0011וכן הוא מסקנת א\"א הרא\"ש ז\"ל דאפילו למאן דאית ליה מצות יבום קודמת אין לה דין מורדת שתפסיד כתובתה \u0010y16\u0011כתב הרמב\"ם יבמה שתבעה היבם לחליצה והיא אומרת איני חולצת ולא נוטלת כתובה אלא אשב בבית בעלי כשאר כל האלמנות אין שומעין לה אלא רצה מייבם רצה חולץ ונותן לה כתובה ולא עוד אלא אפי' אומרת אני ניזונת משלי ואשאר עגונה כל ימי אין שומעין לה שהיבם אומר כל זמן שאת זקוקה לי אין נותנין לי אחרת ואפילו היה נשוי איפשר שישא אשה אחרת או שתהיה לו מריבה בתוך ביתו מפני היבמה כל יבמה שדינה שתחלוץ ולא תתייבם הרי זו נוטלת כתובתה אם יש לה כתובה כשאר כל האלמנות \u0010y17\u0011וכן אם היה יבמה מוכה שחין או שיש בו שאר מומי אנשים חולץ לה ונוטלת כתובתה \u0010y18\u0011נולדו בה מומין כשהיא שומרת יבם נסתחפה שדהו ואם אינו רוצה לייבם חולץ לה ונותן לה כתובה ע\"כ:",["רב אלפס פסק שמצות יבום קודמת למצות חליצה בפרק החולץ (יבמות דף לט:) גרסינן תנן התם מצות יבום קודמת למצות חליצה בראשונה שהיו מתכוונים לשם מצוה עכשיו שאינם מתכוונים לשם מצוה אמרו מצות חליצה קודמת למצות יבום אמר רב אין כופין כי אתו לקמיה דרב א\"ל אי בעית חלוץ אי בעית יבם בדידך תלה רחמנא אם לא יחפוץ הא אם חפץ אי בעי חולץ אי בעי יבם ואף רב יהודה סבר אין כופין ואמרינן תו התם (שם) אהא דתנן בראשונה שהיו מתכוונים לשם מצוה מצות יבום קודמת עכשיו שאין מתכוונים לשם מצוה אמרו מצות חליצה קודמת אמר רמי בר חמא חזרו לומר מצות יבום קודמת א\"ל רב נחמן בר יצחק אכשור דרי מעיקרא סברי לה כאבא שאול ולבסוף סברי לה כרבנן דתניא אבא שאול אומר הכונס את יבמתו לשם נוי לשם אישות לשם דבר אחר כאילו פוגע בערוה וקרוב אני בעיני להיות הולד ממזר וחכ\"א יבמה יבא עליה מכל מקום ופסק הרי\"ף הלכה כחכמים וכ\"פ הרמב\"ם בפ\"א ורש\"י כתב אהא דא\"ר אין כופין אי ניחא לתרוייהו לייבומי אין כופין אותו לחלוץ דנימא לא למצוה מכווני ופגע באיסור אשת אח אלא אי בעי מייבם ומיהו היכא דאיהו צבי ייבומי ואיהי אמרה לא בעינא ליה ואמרה דברים הניכרים אי מצינא לאטעויי ולומר לו חלוץ לה ע\"מ שתתן לך מאתים זוז מטעינן ליה ואי לא כפינן ליה וחליץ דא\"ר ששת מנין ליבמה שנפלה לפני מוכה שחין שאין חוסמין אותה ולא תימא מוכה שחין דוקא אלא כל אמתלאה שתתן לדבריה דאמרינן בהמדיר (עז.) מעשה בצידן בבורסי שמת ולו אח בורסי ואמרו חכמים יכולה שתאמר לאחיך הייתי רוצה לקבל ולך איני יכולה לקבל ועוד פסקינן הילכתא בפרק אף ע\"פ (כתובות סד.) אין כותבין אגרת מרד על שומרת יבם ומכל הלין טעמי כפינן ליה דחליץ ושקלה כתובה וכל הני אין כופין דהכא היכא דתרוייהו ניחא להו וכתבו התוספות והרא\"ש דאין דבריו נראין במה שפירש דבשאר אמתלאה כופין דלא דמי למוכה שחין ובורסי דאפי' מתחת בעלה כופין להוציא ועוד דבפ' מצות חליצה (יבמות קו.) מייתי כמה מעשים שהיתה נותנת אמתלאה לדבריה והיו טורחים הרבה כדי להטעותו וטורח זה למה יכפוהו לחלוץ הלכך נראה דבשאר אמתלאות מטעין ואין כופין ומה שהביא ראיה מאגרת מרד זו אינה ראיה דא\"כ אפילו בלא אמתלאה נמי והתם היינו טעמא משום דסבר דמצות חליצה קודמת כדמסיק התם ור\"ת מפרש התם דקאי ארישא בראשונה שהיו מתכוונים וגרסי' הכי מצות יבום קודמת למצות חליצה אמר רב אין כופין כלומר אע\"פ דמצות יבום קודמת אין כופין אותו לקיים המצוה וכי אתאן לקמיה דרב באותם שהיו מתכוונים לשם מצוה איירי ורב יהודה נמי דאתקין אי צבית לייבומי מסתמא איירי באותם שהיו באים לפניו לחלוץ והיה אומר להם אי בעית לייבומי שאם היו מייבמים הא ודאי מתכוונים לשם מצוה כיון דמעיקרא באו לחלוץ אבל אחריני אין מניחין אותם לייבם אלא אדרבא כופין אותם לחלוץ דהלכתא כמתני' דפ\"ק דבכורות (יג.) דעכשיו מצות חליצה קודמת דקי\"ל כאבא שאול ולעיל נמי בריש מכילתין סתמא דמתניתין כאבא שאול ודלא כרמי בר חמא דאמר חזרו לומר מצות יבום קודמת ובפרק מצות חליצה תני בר קפרא לעולם ידבק אדם בחליצה כאבא שאול וסתמא דתלמודא כאבא שאול בפרק אע\"פ וכולה שמעתין דלעיל דמשמע דביאה עדיפא במתכוין לשם מצוה איירי ור\"ח פסק כאן דמצות יבום קודמת ולקמן בפרק מצות חליצה חזר בו עכ\"ל. ודע שבפ' אע\"פ כתבו התוספות דנראה לר\"י דבכל ענין אין כופין ואפי' לפי' ר\"ת דמפרש דא\"ר אין כופין קאי למשנה ראשונה דאין כופין לייבם אע\"פ שמצות יבום קודמת ונ\"מ דבזמן הזה היכא שמתכוונים לשם מצוה כגון שבאים לחלוץ דאותם ודאי אין מתכוונים לשם נוי וכו' אבל היכא דלא ברור לן שמתכוונים למצוה כופין במילי ומרחיקין אותם מן הייבום כמו שפירשתי ביבמות וגם לפירושו אם אם תבע לייבם לא כייפינן ליה לחלוץ אלא מטעינן ליה אם אינה חפצה אבל אם אינו רוצה לא לייבם ולא לחלוץ נראה דכופין עכ\"ל והוכרחו לפרש דברי ר\"ת כן משום דאל\"כ יקשה ג\"כ על ר\"ת מה שהקשו לפירש\"י מהנהו עובדי דפרק מצות חליצה ומפני כך צ\"ל דמאי דמשמע מדברי רבינו כאן ולקמן בסימן זה דלר\"ת כופין כשאינו מכוין לשם מצוה כפיית מילי הוא :","ומ\"ש רבינו אחר דברי ר\"ת וכן הוא מסקנת א\"א הרא\"ש ז\"ל איכא למידק עליה שאע\"פ שאחר שכתב סתירת דברי רש\"י כתב דברי ר\"ת אין להוכיח משם שסובר כר\"ת דאפשר דאינו סובר כמותו ואעפ\"כ כ' דבריו וליה לא ס\"ל אלא מצות יבום קודמת כרבנן שהרי כתב שם לקמן בסמוך גבי פלוגתא דאבא שאול ורבנן פסק הרי\"ף כרבנן ולא חלק עליו אבל טעמו של רבינו מדכתב בפ' אע\"פ גבי ההיא דאמר שמואל אין כותבין אגרת מרד על שומרת יבם כתב הרי\"ף דליתא למשנה אחרונה הילכך ליתא נמי להא דשמואל ואני כתבתי בפ' החולץ בשם ר\"ת דהלכה כמשנה אחרונה איתא נמי להא דשמואל וכן עמא דבר עכ\"ל. והריב\"ש כתב בתשובה סימן תק\"ט הרי\"ף והרמב\"ם וכל האחרונים פסקו דמצות יבום קודמת והוא הפסק הנכון עכ\"ל ועיין עוד בדבריו סימן ר\"ט וכתב בסימן ש\"ב שאפי' לדברי הפוסקים דמצות יבום קודמת אם היבם נשוי לכ\"ע מצות חליצה קודמת והביא ראיה לדבר . ובסימן א' כ' על יבמה שנשארת זקוקה לשני יבמים והגדול הוא מאנוסי הזמן והשני הוא יהודי והיהודי רוצה לייבם והיא אינה רוצה ואומרת באחיו הגדול הייתי רוצה ואם הוא אינו יכול אנא הא קאמינא אם דנין אותה כדין מורדת ודאי לדידן דאית לן מצות יבום קודמת לעולם חוזרין לייבום על כל האחים אלא שכל שנסתלק הגדול האחרים שוים ביבום ויכולה היא שתאמר לשני בג' אני חפצה יותר ממך כיון שאין לך דין קדימה שהרי נסתלק הגדול ואין דנין אותה בדין מורדת עד שנדע אם השלישי חפץ בה ואם אין השלישי חפץ בה אומרים לה הרי אין כאן מי שחפץ ביבום אלא זה או תתייבם לו או תצא בלא כתובה כדין כל מורדת כמו שביאר זה הרמב\"ם בפ\"ב מה' יבום וחליצה ובנדון זה ג\"כ שאין כאן מי שיוכל לייבם אלא זה אם תבע אותה לייבם והיא לא רצתה דנין אותה כדין מורדת אלא שיש לב\"ד לעיין בדבר הרבה אם זה השני נשוי אשה אחרת אם אפשר לו לפרנס שתיהן לפי כבודו וכבודן שאל\"כ לא שבקינן ליה אלא משיאין לו עצה ההוגנת לו כדאיתא בפרק החולץ גבי מתני' דד' אחים נשואים ד' נשים ומתו וכו' עכ\"ל ועיין במהרי\"ק שורש צ\"א וק\"ב","\u0003וכתב עוד בתשובה על יבמה שנפלה לפני יבם נער וכו'\u0004 בכלל נ\"ב וכתב שם שהיבם לא היה רוצה לחלוץ עד שיתנו לו דבר קצוב והיבמה היתה עניה ואינה חפצה להתייבם לו והשיב שאם יכולים להטעותו שידרו לו ממון ע\"מ שיחלוץ הרי טוב ולא יתנו לו כי חליצה מוטעת כשירה ואם אינם יכולים להטעותו יראה כי בנדון זה שאינו מכוין לשם מצות יבום אלא תובע ממון כדי לחלוץ כופין אותו כדי לקיים מצות חליצה בלי ממון ואם היה תובע לייבם נראה דאמתלאה גדולה נותנת לדבריה שאינה רוצה להתייבם לו כיון שהוא נער ובער ואין לו במה לפרנסה ורש\"י כתב דלאו דוקא מוכה שחין אלא בכל אמתלאה שתתן לדבריה וכו' ור\"ת פסק הלכה כסתם משנה דפ\"ק דבכורות (יג.) ולפי פסק שלו אף בלא אמתלאה אמנם בפסק זה רבו החולקים ובירושלמי דמצות חליצה גרסינן הוא רוצה פי' לייבם והיא אינה רוצה שומעין לה היא רוצה והוא אינו רוצה שומעין לו ובנדון זה כופין אותו לחלוץ בלא ממון דמצות לאו ליהנות ניתנו ואין נוטלין שכר עליהם ע\"כ. ובספר המצות כתב שאם יש לו אשה אחרת שכופין אותו וכו' בסמ\"ק אם יש לו אחרת מנדין אותו בהדיא עד שיחלוץ אך בהגהות מרדכי פרק החולץ כתוב בלשון הזה כתב רבינו אביגדור הכהן מי שנפלה לפני יבמה ויש לו אשה אחרת קבלתי ממורי רבי' שמריה שבזמן הזה כופין אותו לחלוץ לה וראייתו מפרק ב\"ש (יבמות קיא:) הנודרת הנאה מיבמה בחיי בעלה כופין אותו שיחלוץ לה ואע\"פ שהיא גרמה הואיל ולא נתכוונה לכך כ\"ש הכא שלא גרמה היא כלל אלא גזירת הגאון ר\"ג מ\"ה היא מבדלת ביניהם עכ\"ל : יבמה שיש לה ג' יבמין והיא אינה רוצה לחלוץ ולא לייבם ולא לחלוק בנכסים אלא רוצה לישב עגונה ואם חלץ אחד מהם ולקח חצי הנכסים אם צריך לחלוק אותם נכסים עם אחיו ואם יש ליבמה נכסים יתר על כתובתה איך יתנהגו בו הכל בת\"ה ובכתביו סימן רס\"ב ורס\"ג ורס\"ד: מצאתי כתוב יבם שדוחה את יבמתו מלחלוץ ולייבם יטעוהו בכל מה שיוכלו להטעותו שיחלוץ כגון שתמחול לו כל ממון שיש בידו משל אחיו אפילו בקנין ותמסור מודעא מקודם ואחר שיחלוץ יגבו ממנו הממון דכיון דניתן רשות להכותו כ\"ש דיש לנו רשות להפקיע ממון ממנו מה שאנו נותנים לו כדי שיקיים המצוה דהפקר ב\"ד הפקר במיגדר מילתא כ\"ש כשעוברים על ד\"ת ואם אין יכולין להטעותו כופין אותו בשוטים ובמילי דאמרינן בגמרא הולכין אצל הגדול למכפייה וכל היכא דאיכא כפייה פר\"י אפי' בשוטים ועוד דמצוה הוא על היבם לחלוץ או לייבם ומ\"ש משאר מצות דאמרינן בפרק הזרוע (חולין קלב:) דמכין אותו עד שתצא נפשו ע\"כ ועיין בהגהות מרדכי פרק החולץ : כתב הריטב\"א שאלת על יבם שנשבע לחלוץ ליבמתו ליום ידוע אם כופין אותו לחלוץ. תשובה הא ודאי למאן דסבר דחליצה מעושית שלא כדין פסולה ואפילו למ\"ד מצות חליצה קודמת אף לזה אין כופין כי אף ע\"פ שעל השבועה אתה בא לכופו כיון שמחמת אותה כפייה הוא חולץ החליצה מעושית היא ממילא ולדידיה הכי ס\"ל דאין כופין אלא באותם שכופין להוציא בגט וכדמשמע בפרק מ\"ח שהשוו גט וחליצה בענין זה ומה שאמרת שיש לו אשה ובנים מ\"מ אינו מאותם שכופין להוציא אלא דכל שיש יבם אחר שאין לו אשה בו המצוה יותר ובו משיאין עצה ומבקשים אף ע\"פ שאינו גדול לדעת מורי הרא\"ה אבל לכופן בכך לא מצינו ומ\"מ זה שלא קיים שבועתו מעצמו עונשין אותו על עבריינותו השבועה מדין שבועת ביטוי או מדין שבועת שוא ממ\"נ דאת\"ל שזה נשבע לקיים את המצוה למ\"ד מצות חליצה קודמת מ\"מ הא קי\"ל שנשבעין לקיים את המצוה ושבועה חלה כדאיתא בפ\"ק דנדרים (ח.) ואת\"ל דמצות יבום קודמת ונשבע לבטל את המצוה הוא א\"כ הו\"ל שבועת שוא אף ע\"ג דלדידיה לא חשיב נשבע לבטל את המצוה כיון דבדידיה תלא רחמנא עכ\"ל :","מתוך שפסק רב אלפס שמצות יבום קודם משמע שיבמה שאינה רוצה להתייבם שדינה כדין מורדת לא היה צריך רבינו ללמוד זה בדרך ילפותא שמבואר הוא בדבריו פרק אף ע\"פ דליתא לדשמואל דאמר אין כותבין אגרת מרד על שומרת יבם משום דאתיא כמשנה אחרונה וליתא למשנה אחרונה מדקאמרינן בפרק החולץ חזרו לומר מצות יבום קודמת משום דסברוה כרבנן וכיון דלבסוף סברוה כרבנן נפקא לה משנה אחרונה מהלכתא ובטיל לה מימרא דשמואל מהלכתא וכ\"כ עוד בס\"פ ב\"ש:","ומ\"ש בשם הרמב\"ם הוא בפ\"ב וז\"ל יבמה הראויה להתייבם ולא רצתה להתייבם דינה כדין מורדת על בעלה וכופין אותו לחלוץ ותצא בלא כתובה:","הניח אחיו נשים רבות כל מי שתובע היבם לייבם ולא רצתה היא המורדת וחולץ לה ותצא בלא כתובה ושאר צרותיה שלא נתבעו נוטלות כתובתן כשאר האלמנות היו היבמים רבים ותבע אותה הגדול לייבם וכי' ובקצת ספרי רבינו חסר בבת הניח אחיו נשים רבות וכו' וט\"ס הוא שדילגו מתצא בלא כתובה הכתוב בבבא ראשונה עד תצא בלא כתובה בבבא שנייה ועוד יש ט\"ס בספרי רבינו שכתוב בהם הואיל והיא רוצה באחד מהם והוא לא רוצה בה הרי לא מרדה וצריך למחוק תיבת לא וכבר כתב ה\"ה שבקצת ספרי הרמב\"ם כתוב תיבת לא והוכיח שהוא גירסא משובשת: וכתב ה\"ה מ\"ש הרמב\"ם ז\"ל יבמה הראוייה לייבום שלא רצתה להתייבם דינה כדין מורדת על בעלה כך העלו בהלכות פרק אע\"פ וכן דעת המפרשים האחרונים ז\"ל וכתב רבינו וכופין את היבמה זהו כפי דעתו ז\"ל שכתב בה' אישות פי\"ד שכופין את הבעל לגרש את אשתו כשהיא מורדת ואומרת מאיס עלי וכ\"ש יבמה שכופין את היבם לחלוץ לה ומה שאמרו מבקשים בקצת מקומות הוא בנתינת הכתובה אבל אם היא מפסדת כתובתה כופין הבעל לגרש והיבם לחלוץ וזה דעתו ז\"ל וכבר הארכתי שם בדעות החולקים עליו וכתבתי שאין לסמוך ע\"ז ומקצת מפרשים כתבו שאם היה היבם שאינו הגון שאין כותבין אגרת מרד וכ\"נ עיקר שלא על זה אמרו מצות יבום קודמת ומ\"ש הניח נשים רבות וכו' דינים אלו לא נתבארו בפרט בגמ' אבל הם יוצאים מהיקש סברא כמו שאבאר בכל א' מהם:","ומ\"ש שאותה שהיבם תובע לייבם היא המורדת הוא ברור שכיון שא\"א לייבם אלא א' והרשות בידו לייבם איזו שירצה כמו שנתבאר אותה שהוא רוצה היא המורדת שהרי הדבר תלוי בו:","\u0003ומ\"ש יחלוץ לה ר\"ל שכופין אותה לחליצה והוא כפי דעתו שכתבתי בסמוך:\u0004 ","\u0003ומ\"ש היו היבמים רבים תבע וכו'\u0004 זה מתבאר ממ\"ש למעלה מצוה בגדול לייבם וכיון שהיא אינה רוצה להתייבם למי שהמצוה בו ה\"ז מורדת:","\u0003ומ\"ש אמר הגדול איני רוצה וכו'\u0004 ג\"ז מהיקש סברא כיון שמצוה בגדול והוא אינו רוצה לייבמה אין כאן בחירה לאחד משאר האחים שהרי היתה מזומנת למי שהמצוה בו והעיכוב בא מחמתו לא מחמתה וכתב רבינו מאחר שנסתלק הגדול שמצוה בו כולם שוין וע\"ז כתוב בהשגות א\"א ואיך יאמר שכולן שוין ואני רואה בגמרא דתני אביי קשישא מצוה בגדול אלמא לא רצה הולכין אחר גדול כל הגדול מחבירו הוא קודם למצוה ע\"כ. והא דתני אביי קשישא הוא בפרק כיצד (כד.) ויש שם גירסאות חלוקות וגירסת רבי' היתה מצוה בגדול לייבם לא רצה הולכין על כל האחים לא רצו הולכין אצל הגדול וכ\"נ שהיתה גירסת ההלכות שלא הביאוה כלל וסמכו לפי שכתבו המשנה שבפרק החולץ הנזכר למעלה אבל רש\"י גורס כגירסת הראב\"ד ואמר דאל\"כ מתניתין דפ' החולץ היא ולמה לן אביי קשישא ולגירסא זו הסכים הרשב\"א ז\"ל וז\"ל הרשב\"א בתשובה ח\"א סימן אלף קס\"ה יבמה שנפלה לפני ב' או ג' יבמין והיא רוצה באחד מהם והוא אינו רוצה בה איפשר שאין דנין אותה כמורדת מאחר שהיא רוצה באחד מהם מיהו אם הגדול רוצה לייבם והיא אינה רוצה הרי היא כמורדת:","\u0003ומ\"ש בא אותו שתלתה בו וכו'\u0004 יש לזה סמך בגמרא ממה שאמרו בגמרא ביאת קטן וחליצת קטן ביאת קטן עדיפא וכיון שכן כיון שיש כאן מי שרוצה לייבם ושאר האחים אינם רוצים בין שיהיה גדול או קטן ה\"ז מורדת שהרי מצות יבום קודמת עכ\"ל ועיין בתשובת הרשב\"א סימן אלף וקס\"ה:","ומ\"ש רבינו אבל לר\"ת שמצות חליצה קודמת אין לה דין מורדת אלא כופין אותו לחלוץ אם הוא מאותן שכופין וכו' פשוט הוא וכתב הרא\"ש בפרק אע\"פ אהא דכתב רב אלפס דליתא למשנה אחרונה הילכך ליתא נמי לדשמואל דאמר אין כותבין אגרת מרד על שומרת יבם אני כתבתי בפרק החולץ בשם ר\"ת דהלכה כמשנה אחרונה ואיתא נמי להא דשמואל וכן עמא דבר עכ\"ל. וז\"ל הריב\"ש אם היבם תובע אותה בבית דין והיא אינה רוצה כותבין עליה אגרת מרד דהא קי\"ל דמצות יבום קודמת כפסק הרי\"ף והרמב\"ם וכל האחרונים כמו שהוכיחו זה בראיות ברורות עכ\"ל וכ\"כ עוד בתשובה אחרת וכתב עוד שם דבין שאומרת בעינא ליה ומצערנא ליה בין שאומרת מאיס עלי כותבין עליה אגרת מרד וכתב עוד דאפילו שמואל דאמר אין כותבין לאו בדאמרא בעינא ליה ומצערנא ליה כלומר שאינה רוצה לא ביבום ולא בחליצה דאם כן אמאי אין כותבין שתבא לייבם ואפילו למשנה אחרונה דאף ע\"ג דמצות חליצה קודמת מיהו גם ביבום יש מצוה שהרי אמרו קודמת למצות יבום וכיון שהוא רוצה בייבום שיש בו מצוה והיא אינה רוצה לא בייבום ולא בחליצה כותבין ושם האריך וכתב בדין יבמה המורדת מה הפסידה בסימן שס\"א ושס\"ב וז\"ל הר\"ן בתשובות סימן פ\"ט על יבמה שאינה רוצה לחלוץ ולא להתייבם הרי זה כדין המורדת שמכריזין עליה ד' שבתות ואחר כך אם לא רצתה להתייבם הפסידה כתובתה אלא שמשהין אותה י\"ב חדש דאי בעיא למיהדר תיהדר ולאחר זמן זה אף על פי שהפסידה כתובתה נראין הדברים שכופין אותה בנידוי וגם בכפיות אחרות עד שתתרצה לחלוץ או להתייבם לפי שהיבם מעוכב ליקח אשה מחמתה כדאמרינן בפרק אף על פי (נא.) כמה דאגידא ביה לא יהבו ליה אחריתא וכך נראה דברי הרמב\"ם ז\"ל עכ\"ל וכתוב בת\"ה סימן ר\"כ דאפי' נשוי נמי אית ליה האי טענה דכל כמה דאגידא ביה אפי' איתתא דידיה מרגלת ביה קטטה ודילמא אימרדא ביה מי ששידך אשה וקודם שכנס נפלה לו יבמה בהגהות מרדכי דכתובות:","יבמה שנדרה הנאה מיבמה בחיי בעלה שיש הוכחה שלא כיונה לאסור עצמה על היבם או שנדרה הנאה מן העולם בחיי בעלה כופין אותו לחלוץ ונותן לה כתובה נדרה הנאה מהיבם אחר מיתת הבעל וכו' כך הוא הגירסא הנכונה בדברי רבינו ובקצת ספרים יש חסרון הניכר ודינים אלו משנה ס\"פ ב\"ש (יבמות ד' קיא:) הנודרת הנאה מיבמה בחיי בעלה כופין שיחלוץ לה לאחר מיתת בעלה מבקשין ממנו שיחלוץ לה ואם נתכוונה לכך אפילו בחיי בעלה מבקשין ממנו שיחלוץ לה. ופירש\"י בחיי בעלה. ולא נתכוונה לפטור עצמה הימנו לאחר מיתת בעלה אלא שהיה להם כעס זה עם זה וכתב ה\"ה בפ\"ב פירוש לפירושו שכל שהיה שם כעס חוששין שמא נתכוונה לכך ואין כופין אותו לחלוץ שמה ששנינו במשנה ואם נתכוונה לכך אינו ר\"ל כשידוע בבירור שלכך נתכוונה אבל כל שיש לומר שלכך נתכוונה ורישא דקתני כופין אותו משום דאמרינן דלא מסקא אדעתה דמיית בעלה וכדאיתא בגמרא ע\"כ:","ומ\"ש רבינו או שנדרה הנאה מן העולם שם (דף קיב.) איבעיא להו נטולה אני מן היהודים ליבם מהו מי מסקא אדעתה דמיית בעלה ונפלה קמי יבם או לא רב אמר יבם אינו כבעל ושמואל אמר יבם הרי הוא כבעל ומסקנא דגמרא כרב ופירש רש\"י ליבם מהו. מי אסירא ליבם מפני נדר זה שנדרה בחיי בעלה ומדברי הרי\"ף נראה שהוא מפרש דלא משום איסור נדר קאמר אלא לענין אי הויא כנדרה הנאה מיבמה בחיי בעלה שכופין אותו לחלוץ לה שכתב יבם אינו כבעל וכופין אותו לחלוץ ונ\"מ דלא הויא מורדת וטעמא דנדרה בחיי הבעל [חבל] לאחר מיתת בעלה הויא מורדת ושמע מינה דליתא לדשמואל דאמר אין כותבין אגרת מרד על שומרת יבם ע\"כ וכן נראה מדברי הרמב\"ם ז\"ל שכתב בפרק שני יבמה שנדרה הנאה מיבמה בחיי בעלה או שנדרה הנאה מכל היהודים כופין אותו שיחלוץ לה ותיטול כתובתה ואם נדרה לאחר מיתת בעלה מבקשין ממנו שיחלוץ לה ואם לא רצה הרי זו מורדת וכן אם נתכוונה בנדרה אפי' בחיי בעלה כדי שלא ייבם אותה אין כופין אותו לחלוץ אלא א\"כ מרדה ותצא בלא כתובה ע\"כ. כתב הר\"ש בן הר\"ש בר צמח בתשובה מה שאמרו בנודרת הנאה מיבמה מבקשין ממנו וכופין אינו אלא כשהנדר קיים אבל אם מצאה פתח לנדרה מתייבמת ולא אמרינן בה כל יבמה שאין אני קורא בה יבמה יבא עליה בשעת מיתה הרי היא כאשת אח שיש לו בנים והביא ראיה לדבר וה\"ה אם היה בעל מום בשעת נפילה ונתרפא שהוא מייבם. וכתב עוד שם ביבם שהיה נכפה בחיי אחיו וטוען שנתרפא עליו להביא ראיה וכיון דנכפה הוי מומין שבסתר וא\"א להביא ראיה הרי הוא בחזקת בעל מום ואין חוסמין אותה: כתב הרשב\"א סימן אלף ר\"ב שאלת העושה מאמר ביבמתו וחזרה וקבלה מאמר מאחיו ואסרה עצמה על שניהם או שרקקה וקי\"ל דנאסרה איבמה מי דיינינן לה כמורדת כמי שנדרה הנאה מיבמה אחר מיתת בעלה. תשובה כל כה\"ג לא מצינו שכותבים עליה אגרת מרד אלא כדי שתחזור בה ותתייבם לו אבל זו שנאסרה על האחים לעולם למה כותבין עליה והא א\"א לה להתייבם מעתה ותדע שאין לך גורמת לאסור על בעל יותר מן המזנה ואפי' הכי אין דנין אותה כמורדת שהרי לא הפסידה בלאותיה ועוד דההיא דנודרת שאמרת באמת כי הרי\"ף למד ממנה למורדת ואין הכל מודים לו שהר\"א תלמידו חלוק עליו ואמר דכופין ומבקשין שאמרו שם בשילהי בית שמאי בפלוגתא דרב ושמואל לא שייך במורדת כלל דאם כן קשיא דשמואל אדשמואל אלא לא שמענו ממנה אלא לאחר מיתת בעלה אין כופין לחלוץ כפשטא דמתניתין ועוד שרש\"י פירש אותה שמועה בע\"א והוא הנכון לפי דעתי וכל שכן כשרקקה דהא אפילו לא נתכוונה אסורה עליו ואם אתה מפסידה כתובתה לקתה מדת הדין בכך ע\"כ וכתב הרב המגיד מ\"ש רבינו או שנדרה הנאה מכל היהודים הוא ממה שאמרה נטולה אני מן היהודים מאי וכו' ויש לזה פירוש אחר ולזה הסכים הרמב\"ן ז\"ל וכן עיקר: ומ\"ש אא\"כ מרדה ותצא בלא כתובה הוא לפי דעתו שנתבאר למעלה שהיבמה מורדת כופין יבמה לחלוץ לה ומפסדת כתובתה ומה שאמרו כאן מבקשין הוא כשאינה רוצה להפסיד כתובה אבל בהפסד כתובה כופין על החליצה וכבר כתבתי למעלה שאין לסמוך על דברי רבינו בזה והראב\"ד ז\"ל נראה שמודה לו בדין המורדת בין ביבם בין בבעל אבל כתב שאין זו כדין המורדת וז\"ל א\"א אין הדעת מודה בזה שאמרו או כופין או מבקשין לחלוץ נראה שאינה מורדת שהמורדת אין חוששין להתירה אלא לאחר כמה שנים אבל כאן כופין מיד או מבקשים מיד לפי שאין מורדת לכתחילה ע\"כ ולא נתבררו לי דבריו שהרי לפי שיטה זו ג\"כ יש מורדת שכופין לאלתר והוא באומרת מאיס עלי ונזכר פרק י\"ח מהלכות אישות וזו הנודרת מיבמה אין לך אומרת מאיס עלי גדול מזה ומ\"מ עיקר הדין שאין כאן כפייה לא לאלתר ולא לאחר כמה שנים שלא כדעתם ז\"ל עכ\"ל:","\u0003ומ\"ש רבי' בשם הראב\"ד כבר נתבאר בסמוך וכ\"כ הרא\"ש בשמו סוף פרק ב\"ש:\u0004 ","ומ\"ש וכן הוא מסקנת א\"א הרא\"ש ז\"ל דאפילו למאן דאית ליה מצות יבום קודמת אין לה דין מורדת שתפסיד כתובה איפשר שכתב כן רבינו ממה שכתב הרא\"ש ס\"פ ב\"ש בשם ה\"ר אפרים ז\"ל אע\"פ שאין זה מבואר כ\"כ בדבריו. כתב הרשב\"א בתשובות סי' אלף ורמ\"ז על ש\"מ שגירש ויש ספק בגט והיבם רוצה לעגנה כל שיש ספק בגט ונאסרה עליו כופין אותו מן הדין לחלוץ כדי שלא לעגנה וכ\"ש בבאה מחמת טענה דבעיא חוטרא לידא ומרא לקבורה ואפילו במותרת לייבם ואינו רוצה לחלוץ ולא לייבם וכדאיתא בפרק אף על פי (כתובות סד.) דאפילו תבעה היא ובאה מחמת טענה כותבין לה אגרת מרד על היבם ובאסורה לו כופין אותו לחלוץ כדאיתא בפרק מצות חליצה (יבמות קו.) גבי עובדא דבתי עמודי:","כתב הרמב\"ם יבמה שתבעה היבם לחלוץ וכולי עד סוף הסימן הכל בפ\"ב וכתב הרב המגיד יבמה שתבעה היבם וכולי בסוגיא פרק אף ע\"פ (כתובות סד.) ודעת רבינו דאפי' למסקנא דקי\"ל כמשנה ראשונה דמצות יבום קודמת כשהוא תובע לחלוץ נזקקין לו וההיא סוגיא קושטא היא אפילו למסקנא דגמרא והרשות בידו אם רצה לייבם מייבם ואם רצה לחלוץ חולץ ויש מן המפרשים חולקים בזה ואומרים דכיון דמצות יבום קודמת אם תבע הוא לחלוץ והיא רוצה להתייבם אין כופין אותה לחלוץ והיא סוגיא דלא כמשנה ראשונה היא ויש מי שסובר כדעת רבינו עכ\"ל: ועל מה שכתב הרמב\"ם כל יבמה שדינה שתחלוץ ולא תתייבם הרי זו נוטלת כתובתה אם יש לה כתובה וכו' כתב ה\"ה זה מתבאר בפרק יש מותרות (יבמות פה.) כמו שאכתוב בפרק זה:","ומ\"ש וכן אם היה יבמה מוכה שחין מימרא פרק א' דיבמות (ד:) מנין ליבמה שנפלה לפני מוכה שחין שאין חוסמין אותה וכו' ומתבאר בפרק המדיר במשנה שכל המומין כן ונזכר שם שאפילו היו המומים ההם בבעל יכולה היא לומר לאחיך הייתי יכולה לקבל ולך איני יכולה לקבל וכבר נתבאר זה בפרק כ\"ה מהלכות אישות ושם נזכרו פרטי המומין שהיא יכולה לטעון בהם:","ומ\"ש נולדו בה מומין זה פשוט ונלמד מדין האשה שנולדו בה מומין אחר שנתארסה כנזכר שם עכ\"ל:"],["רב אלפס פסק דמצות יבום קודמת בפרק החולץ (יבמות דף ל\"ט) מייתי פלוגתא דאבא שאול ורבנן ומסקנא דגמ' דהלכה אף בזמן הזה כרבנן דאמרי יבמה יבא עליה מ\"מ אפי' מתכוין לשם נוי או לדבר אחר אפ\"ה מצות יבום קודמת:","\u0003ומ\"ש ורש\"י כתב דמצות חליצה קודמת ומ\"מ אם שניהם לפנינו וכו'\u0004 רש\"י לא כתב בפירוש דמצות חליצה קודמת כאבא שאול אלא דמשמע הכי מדפי' הא דאמר רב אין כופין פי' אין כופין לחלוץ אי ניחא לתרוייהו לייבומי אבל אם האשה אינה רוצה בייבום מטעינן ליה ואם לא מצינן לאטעויי כפינן ליה לחלוץ אלמא דמצות חליצה קודמת וכך מבואר ממ\"ש הרא\"ש וז\"ל וג\"ז קשה לפירש\"י שפירש אע\"פ שמצות חליצה קודמת אין כופין אותו לחלוץ דסוגיא דתלמודא דהתם (פ' מ\"ח) מוכחא דלמ\"ד מצות חליצה קודמת כופין אותו לחלוץ ור\"ת מפרש (דרב דאמר אין כופין) דקאי ארישא וכו' עד אע\"פ שמצות יבום קודמת אין כופין אותו לקיים עיקר המצוה ובאותן שודאי הוא שמתכוונים לשם מצוה מניחין אותן לייבם אבל לאחרונים אין מניחין אותן לייבם אלא אדרבה כופין אותן לחלוץ דעכשיו מ\"ח קודמת עכ\"ל ודברים אלו צריכין ביאור דמ\"ש וגם זה קשה לפירש\"י וכו' ר\"ל דמה שפירש\"י היכא דשניהם רוצים בייבום אין כופין אותן בשום דבר אף במילי כדי שיחלוץ לה אלא מניחים אותם לייבם דאין לנו לחוש דמתכוונים שלא לשם מצוה והא ליתא דסוגיא דתלמודא מוכחא דכופין אותו במילי כיון דמצות חליצה קודמת וכן מ\"ש אח\"כ בדברי ר\"ת אבל לאחריני אין מניחין אותם לייבם ר\"ל דמרחיקין אותם וכופין אותם במילי שיחלוץ לה דכיון שאינו ידוע שמכוונים לשם מצוה מחזקינן אותם במן הסתם באינן מתכוונין לשם מצוה וכאבא שאול ואמאי דקאמר עוד אלא אדרבא כופין אותו לחלוץ ה\"ק דלפעמים כופין אותו אף בשוטים לחלוץ כגון דידוע שאינן מתכוונים לשם מצוה:","\u0003ומ\"ש רבינו ע\"ש ר\"ת בידוע שמכוין לשם מצוה והיא ממאנת וכו'\u0004 רצונו לומר אם יש לה טענה דכופין אותן בשוטים להוציא כופין אותו נמי בשוטים לחלוץ ואם אין לה טענה אע\"ג דידוע שמכוין לשם מצוה אין כופין אותה בשוטים ליבום דפשיטא דאף עכשיו בזמן הזה לאבא שאול היכא דידוע שמכוין לשם מצוה ה\"ל כמשנה ראשונה דאין כופין ליבום שהיא עיקר המצות לפי פר\"ת וכמ\"ש התוס' בפרק אע\"פ (כתובות דף ס\"ד) בסוף ד\"ה מאי שנא מיהו במילי ודאי כופין כיון דידוע דנתכוין לשם מצוה וכדאתקין רב יהודה אי צבית לייבומי וכו' והשתא מדיוקא משמע דהיכא דידוע דאינו מכוון לשם מצוה לאבא שאול דקי\"ל כמותו וקאמר כאילו פגע בערוה וקרוב להיות ממזר ודאי דכופין אותו בשוטים לחלוץ וכדפירש' דלזה נתכוין ר\"ת במ\"ש אין מניחין אותה לייבם אלא אדרבה כופין אותו לחלוץ ועוד דהלא אפי' כשהיא תובעת אותו לפוטרה והוא אינו חפץ לא לייבם ולא לחלוץ כופין אותו בשוטים לחלוץ כל שכן היכא דידוע שאינו מכוין לשם מצוה דפוגע בערוה והיה לו לרבינו לפרש זה ולבארו אלא שקיצר ותו דמתוך תשובת הרא\"ש וספר המצות שהביא רבינו בסמוך דכופין בשוטים לחלוץ לה כשהוא נער ובער או יש לו אשה ורוצה בייבום ואין זה אלא לפי דבידוע הוא שאינו מכוין לשם מצוה אלא לשם ממון הארכתי בכל זה לפי שהב\"י כתב וז\"ל דמאי דמשמע מדברי רבינו כאן ולקמן בסי' זה דלר\"ת כופין כשאינו מכוין לשם מצוה כפיית מילי הוא עכ\"ל דמשמע מלשונו אפי' ידוע שאינו מכוין לשם מצוה והא ליתא דבידוע שאינו מכוין לשם מצוה כופין בשוטים כדפי' וכמ\"ש ב\"י גופיה בד\"ה מצאתי כתוב והכי נקטינן מיהו אעפ\"י דמדינא הכי הוא לר\"ת והרא\"ש וגם רש\"י וההולכים בשיטתן מודים בהא מ\"מ אין לכוף כלל לחלוץ אפילו בידוע שאינו מכוין לשם מצוה דדילמא הלכה כרבנן דמצות יבום קודמת ואפילו ידוע דאינו מכוין לשם מצוה דיבמה יבא עליה כתיב מ\"מ וכרבנן ואסור לכופו לחלוץ הילכך נהגינן לפשר ביניהם כדי שיחלוץ ברצון ואע\"פ שנתקשר בק\"ס ובחרם קודם החופה לחלוץ לה בחנם ובשעת חליצה אינו רוצה לחלוץ אלא תבעה להתייבם אין כופין אותו לחלוץ משום דאם מצות יבום קודם ה\"ל מתנה על מ\"ש בתורה ויכול לחזור בו ולתבוע הייבום ועיין בתשובת מהר\"ם פדו\"אה סי' י\"ח גם נראה דלהר\"א ממי\"ץ שהיה מתיר חרם דר\"ג מ\"ה שלא לישא ב' נשים כשהיה נשוי אשה ובא לחלוץ כדי שיהא ראוי לייבמה ומדעולה לייבום עולה נמי לחליצה דאל\"כ היתה חליצה פסולה וצריכה לחזר על כל האחין לפ\"ז צריך ג\"כ להתיר השבועה והחרם שנתקשר בו לחלוץ לה בחנם אלא שלא נהגו כהרא\"ם וע\"ל בפי' סדר חליצה סמ\"ו ולעיל סוף סי' א' הבאתי לההוא דהרא\"ם:","\u0003מתוך שפסק רב אלפס שמצות יבום קודם משמע וכו'\u0004 הקשה ב\"י לא היה צריך ללמוד זה בדרך ילפותא שמבואר הוא בדבריו פרק אף ע\"פ וכו' עכ\"ל ולפעד\"נ דמ\"ש רבינו משמע וכו' רצונו לומר דלרב אלפס משמע ליה כיון דמצות יבום קודם דלא כמשנה אחרונה משמע נמי דהויא מורדת וכותבים עלה אגרת מרד דלא כשמואל ומסיק רב אלפס בפרק אע\"פ דחולקין בפסק זה תרתי מתיבתא והכריע הוא כהך מתיבתא דהויא מורדת וז\"ש משמע וכו' דלרב אלפס משמע ליה הכי:","\u0003ומ\"ש וכ\"כ הרמב\"ם יבמה הראוייה וכו'\u0004 עד אין זה מורדת מאחר שנסתלק הגדול וכו' מיהו לעיל בסי' קס\"א ס\"ב כתבתי דהתוס' והראב\"ד ורשב\"א ורבי' חולקים אהרמב\"ם בזה דאפי' נסתלק הגדול חוזרין עליהן דרך גדילתן והכי נקטינן דלא כהרמב\"ם ע\"ש:","\u0003יבמה שנדרה הנאה וכו'\u0004 משנה ס\"פ ב\"ש (יבמות דף קי\"ב) ופירש\"י בחיי בעלה ולא נתכוונה לפטור עצמה הימנו לאחר מיתת בעלה אלא שהיה להם כעס זע\"ז עכ\"ל פירוש בא ליישב אמאי תנן בחיי בעלה כופין שיחלוץ הא בעל כרחך נתכוונת לפטור עצמה דאל\"כ למה היתה נודרת הנאה ומיישב דאיכא למימר שמתוך כעס שהיה להם זה עם זה נדרה הימנו משמע דאם ידוע שהיה להם שלום זה עם זה בשעה שנדרה בחיי בעלה אין ספק שלא נתכוונה בנדרה אלא לפטור עצמה הימנו ואין כופין אותו שיחלוץ לה ודו\"ק ונראה דהיינו דוקא כשלא מצאה פתח לנדרה אבל מצאה פתח לנדרה מתייבמת וכ\"כ ב\"י בשם הרשב\"ץ בתשובה:","ומ\"ש וכן הוא מסקנת א\"א הרא\"ש וכן נראה דלעיל גבי סתם יבמה שאינו רוצה להתייבם כתב רבינו דלהרא\"ש דמסיק כר\"ת דמ\"ח קודמת אינה מורדת אבל אי מצות יבום קודמת הויא מורדת אבל יבמה שנדרה אפי' מצות יבום קודמת לא הויא מורדת וכהראב\"ד וה\"ר אפרים הביאו בעל המאור והרא\"ש ס\"פ ב\"ש: מצאתי בין הגהות וז\"ל מעשה באחד ששידך בת ישראל וקודם שנשאה נפלה יבמתו לפניו והשיב מה\"ר יחזקיה אמת הדבר דקי\"ל יש זיקה אפי' בתרי אחי (כדלעיל בסוף סי' קנ\"ט) אם כן יש לחוש דשייך כאן חרם דר\"ג מ\"ה שלא לישא שתי נשים או דילמא הכא לא גזר ר\"ג מלישא אשה דזכו לו מן שמיא דלא גזרו אלא שלא לישא מעצמו ודבר זה תלוי בקבלה ועוד מאחר שכבר שידך קודם נפילתה איך תיאסר עליו משום חרם הגאון עכ\"ל הרי התיר מהררי\"ח בשידך כבר ונראין דבריו ודוקא לכתחלה הוא דאסור לשדך משום דמכוער הדבר מפני מראית העין תשובת מהר\"ם מ\"ץ ועיין בגוף התשובה דמהר\"ר חזקיה על זה בהגהות מרדכי דכתובות המתחיל אלכה לי אל הגדולים גם שם תשובת מהר\"ר אביגדור כהן על זה באורך."]],["\u0010c0\u0011\u0010y0\u0011מצות יבום וחליצה כך הוא שתלך היבמה אחר היבם למקום שהוא שם אפילו מב\"ד הגדול לקטן ממנו \u0010y1\u0011ובאה לדיינים והם קוראין לו ונותנין לו עצה ההוגנת לשניהם אם הוא עצה לייבם שייבם ואם הוא עצה לחלוץ כגון שהוא זקן והיא ילדה או איפכא שיחלוץ \u0010c1\u0011\u0010y2\u0011בא לייבם דבר תורה א\"צ לקדש שמן השמים הקנוה לו אלא בא עליה \u0010y3\u0011וכתובתה על נכסי בעלה הראשון \u0010y4\u0011ואם אין לראשון נכסים כתובתה על נכסי היבם \u0010y5\u0011וחכמים תקנו שלא יבא עליה עד שיקדשה קידושין גמורים בפני עדים ובשוה פרוטה וזהו שנקרא מאמר ואינו קונה קנין גמור כדלקמן \u0010y6\u0011ואין עושין בה מאמר אלא מדעתה כמו שהאשה אינה מתקדשת אלא מדעתה \u0010y7\u0011וקטנה שנתאלמנה מן האירוסין אין עושין בה מאמר אלא מדעת אביה \u0010y8\u0011וכותב לה כתובה כדין כל הנושא אלמנה דעלמא \u0010y9\u0011ואם בא עליה בלא מאמר קונה קנין גמור וא\"צ לחזור ולקדש ומכין אותו מכת מרדות כדין מקדש אשה דעלמא בביאה וכותב לה כתובה \u0010y10\u0011ואם נולד לו בן ממנה א\"צ לקרותו על שם אחיו המת \u0010y11\u0011מדברי בעל העיטור כתב הרב המחבר לעניות דעתי הכונס יבמתו מצוה רבה היא ומברך אקב\"ו על בעילת יבמה ככל המצות דאע\"ג דפליגי גבי מצות בעילה דלאו דיבמה איכא מ\"ד דלא צריכא לברוכי ביבמה דברי הכל דצריך לברך ואיכא למ\"ד דעל כניסת יבמה כשקדש יבמתו צריך לברך על כניסת יבמה וליתא דהא בריך ברכת אירוסין ואי משום דמוסיף מצות יבום הא ליתא למצוה אלא בביאה ואנן כתבינן דכל מצוה התלויה באחר לא מברכינן עובר לעשייתן ע\"כ: \u0010y12\u0011טופס כתובת יבמין: ביום פלוני כך וכך לשנת פלוני וכו' איך פלוני בר פלוני אתא קדמנא וכן אמר לנא אחי דמן אבא שכיב וחיי לרבנן ולכל ישראל שבק ובר וברת מורית ומחסין ומוקים שמא בישראל לא שבק ושבק הדא אתתא דשמה פלונית בת פלוני דממתא פלונית דהות נסיבא ליה וחזי לי מן דאורייתא לייבומה כדכתיב בספר אורייתא דמשה יבמה יבא עליה ואנא אפלח ואיזון ואפרנס יתיכי כהלכות גוברין יהודאין דפלחין ומוקרין וזנין ומפרנסין ומכסין ית נשיהון בקושטא ויהיבנא ליכי כסף עשרין וחמשה זוזי דחזי ליכי כדהוו כתיבי בכתובה דכתב לך בעלך קדמאה ועלי מזונייכי וכסותייכי וסיפוקייכי ומיעל עלייכי כאורח כל ארעא וצביאת פלונית בת פלוני דנא ואתייבמת לפלוני בר פלוני יבמה כדי לאוקמי שמיה בישראל כדכתיב והיה הבכור אשר תלד יקום על שם אחיו המת ודא נדוניא דהנעלת ליה מבי אבוה כך וכך וצבי הוא ואוסיף לה מדיליה כך וכך וקבל עלוהי פלוני דנא אחריות תוספת כתובה דנא עלוהי ועל ירתוהי בתריה מקרקעי ומטלטלי ואפילו מן גלימא דעל כתפיה: וכו' כדכתבינן בשאר כתובה דעלמא \u0010y13\u0011וצריך לשרטט אותה בשביל הפסוקים שכותבין בה \u0010y14\u0011והבא על יבמתו בין בשוגג בין במזיד בין באונס כנון שאנסוהו עכו\"ם והדביקוהו ביבמתו בעל כרחו ע\"י קושי בין ברצון בין שהיה הוא מזיד והיא שוגגת או אנוסה כין שהיתה היא מזידה והוא שוגג או אנוס בין שהיא ערה או ישנה בין כדרכה בין שלא כדרכה אפילו בהעראה קנה בד\"א כשנתכוין לשום ביאה בעלמא ואפילו לא נתכוין אלא לביאת בהמה ובא על יבמתו קנאה אבל לא נתכוין לשם ביאה כלל כגון שהוא ישן או שכור שאינו מכיר כלום או שנתכוין להטיח בכותל והטיח ביבמתו \u0010y15\u0011או שנתקשה לאשתו ונפל מן הגג ונתקע ביבמתו \u0010y16\u0011לא קנה וכן אם הדביקוהו ביבמתו בלא קישוי באבר מת לא קנה \u0010y17\u0011והא דביאת שוגג קנה ביבמתו בכל דרך דוקא כשנפלה לו מן הנישואין אבל נפלה לו מן האירוסין אינו קונה בביאה שוגג אלא לירש בנכסי אחיו ולהוציאה בגט ולפטור צרתה אבל אינו קונה ליורשה ולטמא לה ולהפר נדריה אבל בהעראה קונה לכל דבר אף כי נפלה לו מן האירוסין:",["מצות יבום וחליצה כך היא שתלך היבמה אחר היבם למקום שהוא שם אפילו מבית דין הגדול לקטן ממנו בסוף פרק זה בורר (סנהדרין ד' לא:) היבמה הולכת אחר היבם להתירה עד כמה אמר רבי אמי אפי' מטברי' לצפורי אמר רב כהנא מאי קרא וקראו לו זקני עירו ולא זקני עירה ומשמע לרבי' דאפי' מטבריא לצפורי היינו לומר דאפי' מטבריא שהיו שם כמה בתי דינים חשובים לצפורי שלא היו הבתי דינים שבה חשובים כמו אותם שבטבריא אפילו הכי היבמה הולכת שם וכן פירש בנמוקי יוסף והרמב\"ם בפ\"ב סתם דבריו וכתב היבמה הולכת אחר היבם במקום שהוא שם ויש בכלל דבריו דברי רבינו: וכתוב בנמוקי יוסף כתבו בשם הרא\"ה דדוקא שמקום דירתו בצפורי אבל אם הלך לעיר אחרת אין היבמה הולכת אחריו אלא כופין אותו לבא אחריה דלא מיקרי זקני עירו אלא במקום דירתו ובירושלמי נמי משמע הכי וכדכתיבנא בפרק החולץ עכ\"ל :","ומ\"ש ובאה לדיינים והם קוראים לו והם נותנים עצה ההוגנת לשניה' אם הוא עצה לייבם שייבם ואם הוא עצה לחלוץ כגון שהוא זקן והיא ילדה וכו' משנה בסוף פרק מצות חליצה (יבמות דף קו:) ואיתא נמי בריש ההיא פירקא (דף קא:):","בא לייבם א\"צ לקדש שמן השמים הקנוה לו אלא בא עליה מבואר פרק ר\"ג (יבמות ד' נב.):","ומ\"ש וכתובתה על נכסי בעלה הראשון משנה בפרק החולץ (יבמות ד' לח.) ומפרש בגמרא (דף לט.) מ\"ט אשה הקנו לו מן השמים ופי' רש\"י אשה הקנו לו ליבם מן השמים ולא שיעבד נכסיו לכתובתה ויכול למוכרם בכל עת שירצה:","ומ\"ש ואם אין לראשון נכסים כתובתה על נכסי היבם שם בגמרא ויהיב טעמא כדי שלא תהא קלה בעיניו להוציאה:","ומ\"ש וחכמים תקנו שלא יבא עליה עד שיקדשה קידושין גמורים בפני עדים ובשוה פרוטה וזהו הנקרא מאמר ברייתא וגמרא בפרק ר\"ג (יבמות דף נב.) ומתבאר שם בגמרא שהמאמר ג\"כ איפשר בשטר כדין קידושי אשה וכתבו ה\"ה בפ\"א:","\u0003ומ\"ש ואין עושין בה מאמר אלא מדעתה וכו'\u0004 בפרק האיש מקדש (קידושין ד' מד.) תניא העושה מאמר ביבמתו שלא מדעתה רבי אומר קנה וחכמים אומרים לא קנה וידוע שהלכה כחכמים והכי תניא בפרק כיצד (ד' יט:) כרבנן ודלא כרבי וכתב הריב\"ש בתשובה סי' א' שיכול לעשות בה מאמר ע\"י שליח דומיא דקידושי אשה. ובסימן קס\"ב כתב שאם בא על יבמתו ולא עשה בה מאמר קנה קנין גמור ואינו צריך לקדשה אחר הבעילה אלא שמכין אותו מכת מרדות משום דרב מנגיד אמאן דמקדש בביאה וכתב עוד שם על יבם שעשה מאמר ביבמתו ובלשון הקידושין אמר לה הרי את מקודשת לי בקידושי אחי ובטבעת זו נהי שאם לא נתן לה טבעת אלא שקידשה בקידושי אחיו לבד לא עשה כלום ואפילו היה בעין הדבר שקידשה אחיו בו מ\"מ כיון שקידשה גם בטבעת הרי אלו קידושין דדעתה אטבעת דומיא דמלוה ופרוטה דדעתה אפרוטה:","ומ\"ש וקטנה שנתאלמנה מן האירוסין אין עושין בה מאמר אלא מדעת אביה ברייתא שם ופירש\"י מן האירוסין דעדיין רשות אביה עליה כל זמן שלא השיאה:","ומ\"ש וכותב לה כתובה כדין כל נושא אלמנה דעלמא בפרק ר\"ג (יבמות ד' נב.) תניא שטר כתובת יבמין כיצד כותב לה אנא פלוני בר פלוני קבילת ית פלוני' יבמתי עלי לזון ולפרנסה כראוי וכו':","ומ\"ש ואם בא עליה בלא מאמר קונה קנין גמור וא\"צ לחזור ולקדש ומכין אותו מכת מרדות וכו' בפרק ר\"ג (שם):","ומ\"ש ואם נולד לו בן ממנה א\"צ לקרותו על שם אחיו המת ברייתא בפ\"ב דיבמות (ד' כד.) יקום על שם אחיו לנחלה אתה אומר לנחלה או אינו אלא לשם יוסף קורין אותו יוסף יוחנן קורין אותו יוחנן נאמר כאן יקום על שם אחיו ונאמר להלן על שם אחיהם יקראו בנחלתם מה שם האמור להלן לנחלה אף שם האמור כאן לנחלה:","מדברי בעל העיטור כתב הרב המחבר הכונס את יבמתו מצוה רבה היא ומברך אקב\"ו על בעילת יבמה וכו':","\u0003טופס כתובת יבמין ביום פלוני כך וכד וכו'\u0004 זה הטופס שכתב רבינו יש בו תוספת דברים והטופס המכוון כתבוהו הרי\"ף והרא\"ש ז\"ל סוף פרק מצות חליצה והרמב\"ם בפ\"ד מה' יבום:","ומ\"ש וצריך לשרטט אותה בשביל הפסוקים שכותבין בתוכה הכי אמרינן בסוף פ' מצות חליצה (יבמות דף קו:) וכתבו הרמב\"ם בפ\"ד:","\u0003והבא על יבמתו בין בשוגג בין במזיד וכו'\u0004 ברפ\"ו דיבמות (דף נג:) תנן הבא על יבמתו בין באונס בין ברצון בין בשוגג בין במזיד אפילו הוא שוגג והיא מזידה הוא מזיד והיא שוגגת הוא אנוס והיא לא אנוסה היא אנוסה והוא לא אנוס קנה ולא חלק בין ביאה לביאה ופירש\"י שוגג. כסבור שהיא אשתו או אשה אחרת: מזיד. לשם זנות ולא לשם מצוה: קנה. וזכה בנחלה ומוציאה בגט אם בא להוציא ובגמרא תני רבי חייא שניהם שוגגים שניהם מזידים שניהם אנוסים אנוס דמתני' ה\"ד אילימא דאנסוהו עכו\"ם ובא עליה והא אמר רבא אין אונס לערוה לפי שאין קשוי אלא לדעת אלא בישן והא אמר רב יהודה ישן לא קנה ביבמתו אלא בנתקע והא אמר רבא נפל מן הגג ונתקע ביבמתו לא קנה אלא שנתכוין באשתו ותקפתו יבמתו ובא עליה. שניהן אנוסים דבי רבי חייא היכי דמי כגון שנתכוין לאשתו ותקפוהו עכו\"ם ודבקום זה בזה ובא עליה תניא יבמה יבא עליה כדרכה ולקחה שלא כדרכה גופא אמר רב יהודה ישן לא קנה ביבמתו דאמר קרא יבא עליה עד דמכוין לשם ביאה והא תניא בין ער בין ישן בין ערה בין ישנה הב\"ע במתנמנם מתנמנם ה\"ד אמר רב אשי נים ולא נים תיר ולא תיר כגון דקרו ליה ועני ולא ידע לאהדורי סברא וכי אדכרו ליה מדכר אמר רבא נתכוין להטיח בכותל והטיח ביבמתו לא קנה להטיח בבהמה הטיח ביבמתו קנה דהא קמכוין לשם ביאה בעולם:","ודע שהנוסחא האמיתית בספרי רבינו כך היא או שנתקשה לאשתו ונפל מן הגג ונתקע ביבמתו לא קנה וכן אם הדביקוהו ביבמתו בלא קישוי באבר מת לא קנה ודין זה כתבו התוספות והרא\"ש שם אהא דאקשינן והא אמר רבא אין אונס בערוה שאין קישוי אלא לדעת יש לדקדק מכאן דאין יבמה נקנית אלא בקישוי מדלא משני כגון שהדביקוהו עכו\"ם על יבמתו בלא קישוי ואיכא למימר דאתיא הך סוגיא כמ\"ד [המשמש] מת בעריות פטור ולכך אינה נקנית אלא בקישוי דילפינן קיחה קיחה מעריות א\"נ אפילו למ\"ד [חייב] בעינן ביאת יבום דרך הקמת שם וגרע מהעראה ושלא כדרכה דאין דרך ביאה בכך ע\"כ:","ומ\"ש דשכיר שאינו מכיר כלום לא קנה כ\"כ הרמב\"ם בפ\"ב וכתב ה\"ה השוה רבינו שכור לנפל מן הגג ונתקע וישן והוא שיגיע לשכרותו של לוט וזהו שכתב שאינו מכיר כלום ובפ\"ד מה\"א כתב דאין קידושיו קידושין ומתיישבין בדבר זה עכ\"ל:","והא דביאת שוגג קונה ביבמתו בכל דרך דוקא כשנפלה לו מן הנישואין אבל אם נפלה לו מן האירוסין אינו קונה בביאה שוגג אלא לירש בנכסי אחיו וכו' שם בגמרא אהא דתנן אחד המערה ואחד הגומר קנה מאי קנה רב אמר קנה לכל ושמואל אמר לא קנה אלא לדברים האמורים בפרשה לירש בנכסי אחיו ולפוטרה מן היבום מן הנישואין ד\"ה אכלה דהא הות אכלה מעיקרא כי פליגי מן האירוסין רב אמר אוכלת דהא רבי רחמנא ביאת שוגג כמזיד ושמואל אמר כי רבי רחמנא לאוקומי במקום בעל לאלומי מבעל לא ואיכא דאמרי מן האירוסין ד\"ה לא אכלה דהא לא אכלה בחיי בעל כי פליגי מן הנישואין רב אמר אוכלת דהא הות אכלה מעיקרא ושמואל אמר אינה אוכלת כי רבי רחמנא ביאת שוגג כמזיד לדברים האמורים בפרשה אבל לכל מילי לא ופסקו הרי\"ף והרא\"ש ז\"ל כרב אליבא דלישנא בתרא וכתבו התוספות והרא\"ש לענין תרומה לאו דוקא דה\"ה ליורשה וליטמא לה ולהפר נדריה ובביאת שוגג פליגי דוקא אבל בהעראה לא פליגי דביאה היא לכל דבר וקני נמי בעלמא אבל בשוגג דרבי רחמנא דוקא הכא פליגי ואע\"ג דקבעו מחלוקתם על אחד המערה ואחד הגומר לאו משום דקאי עלה אלא משום דמסיים בה קנה וקאי נמי אשוגג ומזיד ובירושלמי משמע דפליגי בהעראה עכ\"ל ומשמע לרבינו ממה שכתבו דבהעראה לא פליגי דביאה היא לכל דבר דאף מן האירוסין קנה לכל ומכל מקום יש לתמוה עליו דכיון שכתבו בירושלמי משמע דפליגי בהעראה מידי ספיקא מיהא לא נפקא ולא ה\"ל לפסוק סתם דקונה לכל דבר אף כי נפלה לו מן האירוסין והרמב\"ם לא הזכיר דבר מזה בהלכות יבום משמע דסבירא ליה דלענין תרומה דוקא הוא דאיפליגו אבל לשאר דברים אפילו מן האירוסין קנה:"],["\u0003מצות יבום וחליצה כך היא שתלך היבמה אחר היבם וכו'\u0004 בס\"פ זה בורר אפי' מטבריה לצפורי משמע מלשון אפי' דאתא לאשמועי' אפילו מב\"ד הגדול לב\"ד הקטן דבשאר משפטים כתיב צדק צדק תרדוף הלך אחר ב\"ד יפה אבל ביבמה צריכא היא לילך אחריו אפי' מב\"ד הגדול לב\"ד קטן ומיהו דוקא בדאיכא ב\"ד בעירו וכדהוה בצפורי וכדכתיב וקראו לו זקני עירו אבל אם אין לשם ב\"ד אין היבמה חייבת להביא ב\"ד עמה לעירו אלא חייב הוא לילך אחריה לפני ב\"ד שבעירה ואי ליכא ב\"ד לא בעירו ולא בעירה אזי חייבים שניהם לילך לפני ב\"ד הסמוך לעירו:","\u0003בא לייבם ד\"ת וכו'\u0004 עד על נכסי היבם כלומר כל זה דין תורה וא\"צ לכתוב לה כתובה אבל חכמים תקנו שלא יבא עליה עד שיקדשה וכו' ואינו קונה קנין גמור לפוטרה שוב בגט בלחוד אלא צריכה גט למאמרו וחליצה לזיקתו ועוד תקנו שכותב לה כתובה כדין כל הנושא אלמנה דעלמא פירוש מלבד כתובתה מאתים כשהיתה בתולה שיש לה מבעלה הראשון ועל נכסי בעלה הראשון ואם אין לראשון נכסים כתובתה על נכסי היבם דתקינו לה מנה משני כדי שלא תהא קלה בעיניו להוציאה כלומר דיש לה כך מתנאי ב\"ד אבל בתר דתיקנו שלא יבא עליה עד שיקדשה תקנו ג\"כ שיהא כותב לה כתובה מנה לשעבד לה נכסיו כדין כל הנושא אלמנה דעלמא דאע\"פ דאם היו לראשון נכסים כתובתה על נכסי בעלה הראשון ואין נכסים של יבם משועבדים ויכול למוכרם בכל עת שירצה אבל עכשיו שכותב לה כתובה אין רשאי למוכרם וכן אפי' לא קידשה אלא בא עליה דקונה ק\"ג לפוטרה בגט בלחוד תקנו חכמים שכותב לה כתובה מנה כדי שישתעבדו נכסיו ולא יכול למוכרם וע\"ל ריש סי' קס\"ח: כתב הרב המחבר נראה דלשון בעל העיטור הוא שאמר על הרב שהיה מחבר ספר אחד וכתב בחיבורו לברך ברכה בשעה שנכנס לייבמה דיברך אקב\"ו על בעילת יבמה דאע\"ג דאיכא פלוגתא גבי בעילת מצוה דהיינו כשנושא אשה בין בתולה בין אלמנה דבביאה ראשונה שהיא נקראת בעילת מצוה לפי שכנסה בחופה וקידושין לבא עליה דאיכא למ\"ד דיברך אקב\"ו על כניסת אשה בחופה ובקידושין בשעת בעילת מצוה ואיכא למ\"ד דא\"צ לברך דנפטר בז' ברכות שמברכין בחופה אבל ביבמה ד\"ה דצריך לברך דאין ז' ברכות שבחופה שייך כלל ליבמה ואיכא למ\"ד דעל כניסת יבמה כשקידש יבמתו צריך לברך על כניסת יבמה וליתא דהא בריך ברכת אירוסין כשעשה בה מאמר דכך היתה תקנת חכמים שיקדש יבמתו וינהג עמה מנהג שאר נשים שנישאו לאנשים בחופה ובקידושין דמברכין ברכת אירוסין וז' ברכות ותו לא צריך לברך עוד על כניסת יבמה כשעושה בה מאמר ואי משום דמוסיף וכו' ולפי דכתב המחבר דמברך על בעילת יבמה דמשמעו להבא אלמא דסבירא ליה שיברך עובר לעשייתו לכך כתב בה\"ע ואנן כתבינן דכל מצוה התלויה באחר כגון הכא דתלויה ביבמה דאיכא לחיש שמא לאחר הברכה תהא מסרבת והויא ברכה לבטלה לפיכך אינו מברך אלא לאחר בעילה ומברך אקב\"ו לבעול יבמה:"]],["\u0010c0\u0011\u0010y0\u0011קטן פחות מבן תשע שנים אין ביאתו כלום ומבן תשע שנים ואילך ביאתו ביאה וקונה ביבמתו \u0010y1\u0011ודוקא ביבמתו ביאתו ביאה אבל באשה דעלמא לא לפיכך נשא אשה ולו אח אשתו פטורה מן החליצה ומן היבום \u0010y2\u0011ואפילו ביבמתו אין ביאתו קונה בה קנין גמור אלא כמאמר לפיכך בן ט' שנים ויום אחד שבא על יבמתו קנאה אבל אינו יכול לפוטרה בגט עד שיגדיל ויבא עליה אחר בך ואם לא בא עליה אח\"כ ובא להוציאה צריכה גט וחליצה \u0010c1\u0011\u0010y3\u0011ואם בא עליה כשהוא קטן ומת קודם שהגדיל או מת אחר שהגדיל אבל לא בא עליה משהגדיל ולו אח חולצת ולא מתייבמת ואם משהגדיל נשא אשה אחרת ולא בא על יבמה משהגדיל ומת שתיהן חולצות ולא מתייבמות \u0010y4\u0011קטן אינו חולץ עד שיגדיל ויבדקוהו שהביא ב' שערות אחר שהגדיל \u0010y5\u0011אבל אם היו לו שערות קודם שהגדיל אינו נחשב גדול על ידם אא\"כ יביא אחרות אחר שהגדיל ומ\"מ אם מוצאין לו ב' שערות אחר שהגדיל לא חיישי' שמא היו לו קודם לכן: \u0010y6\u0011קטנה מבת נ' שנים ויום אחד ביאתה ביאה לכל דבר ואם בא עליה יבם קנאה קנין גמור \u0010y7\u0011שיכול להוציאה בגט אבל אינה חולצת עד שתגדיל ויבדקוה אם הביאה ב' שערות \u0010c2\u0011\u0010y8\u0011יבם קטן שבא על יבמה קטנה יגדלו זה עם זו \u0010c3\u0011\u0010y9\u0011היבמה שנתייבמה ובא להוציאה ואמר שעדיין לא בעל וצריכה חליצה והיא אומרת שנבעלה ודי לה בגט \u0010c4\u0011בתוך ל' יום נאמן וצריכה חליצה \u0010c5\u0011וכיון שהיא אומר' שבעל ולפי דבריה צריכה גט אין די לה בחליצה \u0010y10\u0011ומבקשין אותו שיתן גט אבל אין כופין אותו \u0010c6\u0011\u0010y11\u0011ואם היא אומרת לא נבעלתי וחוא אומר שבעל נאמנת וכופין אותו לבעול או לחלוץ ואם גט יוצא מתחת ידה והוא אומר שבעל קודם הגט ודיה בגט והיא אומרת שלא בעל עדיין והשתא א\"א לו לבעול כיון שלפי דבריה פסלה עליו בגט קודם שבעל כופין אותו לחלוץ \u0010c7\u0011\u0010y12\u0011ואם אחר ל' יום אומר לא בעלתי וצריכה חליצה והיא אומרת נבעלתי נאמנת ודיה בגט \u0010y13\u0011ואם היא אומרת לא נבעלתי והוא אומר שבעל נאמן ואין כופין אותו לחלוץ ומ\"מ היא שויתה עצמה חתיכה דאיסורא להצטרך חליצה ומבקשין אותו שיחלוץ לה ואפי' אם חזר והודה לדבריה שלא בעל ודי לה בחליצה אין שומעין לו וצריכה גט וחליצה \u0010y14\u0011ואפילו אם יש לה גט ממנו והוא אומר שנתנו לה קודם שבעל צריכה גט שני וחליצה \u0010c8\u0011\u0010y15\u0011ולענין איסור הצרה לדעת ר\"י אינו נאמן לאוסרה אפילו הוא והיא אומרים שלא בעל אפילו תוך ל' יום \u0010y16\u0011ולדעת א\"א הרא\"ש ז\"ל תוך ל' יום אם הוא אומר שלא בעל נאמן לאסור הצרה \u0010c9\u0011ואפי' אם היא אומרת שבעל אבל לאחר ל' יום אפי' אם שניהם אומרים שלא בעל אינם נאמנים לאוסרה:",["\u0003קטן פחות מבן ט' שנים אין ביאתו כלום ומבן ט' שנים ואילך ביאתו ביאה וקונה וכו'\u0004 משנה פרק יוצא דופן (נדה דף מה.) בן ט' שנים ויום א' שבא על יבמתו קנאה ואינו נותן גט עד שיגדיל:","ומ\"ש ודוקא ביבמתו ביאתו ביאה אבל באשה דעלמא לא לפיכך נשא אשה ולו את אשתו פטורה מן החליצה ומן היבום משנה בסוף פרק האשה רבה (יבמות דף צו.):","ומ\"ש ואפילו ביבמתו אין ביאתו קונה בה קנין גמור אלא כמאמר לפיכך בן ט' שנים ויום א' שבא על יבמתו קנאה אבל אינו יכול לפוטרה בגט עד שיגדיל יבא עליה אח\"כ ואם לא בא עליה אח\"כ ובא להוציאה צריכה גט וחליצה בפרק יוצא דופן (נדה דף מה) אמתני' שכתבתי בסמוך דקתני בן ט' שנים שבא על יבמתו קנאה ואינו נותן גט עד שיגדיל פריך בגמרא ולכשיגדיל בגט סגי לה והתניא עשו ביאת בן ט' כמאמר בגדול מה מאמר בגדול צריך גט למאמרו וחליצה לזיקתו אף ביאת בן ט' צריך גט לביאתו וחליצה לזיקתו א\"ר ה\"ק לכשיגדיל יבעול ויתן גט ופירש\"י קנאה. וזכה בנכסי אחיו ואע\"פ שאין קנין לקטן הרי קנויה לו ועומדת: אינו נותן גט עד שיגדיל. אם בא לגרשה דקידושי אחיו קידושין גמורים וגירושין של זה אינם גירושין דאינו בן דעת: וחליצה לזיקתו. דאין קידושין גומרין ביבמה לקנות כאשתו לצאת בגט בלא חליצה אבל ביאה גומרת בה דכתיב יבמה יבא עליה: לכשיגדיל יבעול. והך ביאה הוי קנין גמור ואם בא לגרשה אינה צריכה חליצה דכתיב ולקחה לו לאשה כיון שלקחה נעשית כאשתו לכל דבר:","ומ\"ש ואם בא עליה כשהוא קטן ומת קודם שהגדיל או מת אחר שהגדיל ונא בא עליה משהגדיל ולו אח חולצת ולא מתייבמת ואם משהגדיל נשא אשה אחרת ולא בא על היבמה משהגדיל ומת שתיהן חולצות ולא מתייבמות משנה ס\"פ האשה רבה (יבמות דף צו.) בן תשע שנים ויום אחד שבא על יבמתו ומת חולצת ולא מתייבמת נשא אשה ומת ה\"ז פטורה בן ט' שנים ויום אחד שבא על יבמתו ומשהגדיל נשא אשה אחרת אם לא ידע הראשונה משהגדיל הראשונה חולצת ולא מתייבמת השנייה או חולצת או מתייבמת ופירש\"י בן ט' שנים ויום אחד שבא על יבמתו ומת חולצת ולא מתייבמת שיש עליה זיקת שני יבמים שבמאמר זה לא יצתה מידי זיקת נפילה ראשונה וחלה עליה זיקת נפילה שנייה ותנן בפ' ד' אחין מי שיש עליה זיקת יבם אחד ולא שעליה זיקת שני יבמים. נשא אשה שאינה יבמתו ולו אחים ה\"ז פטורה. אע\"ג דביאתו ביאה קידושיו אינן קידושין ואין קנין קטן כלום עד שיביא ב' שערות אבל יבמה הואיל וזקוקה לו שויוה רבנן כמאמר אם לא ידע את הראשונה משהגדיל ראשונה חולצת ולא מתייבמת דזיקת שני יבמים עלה הואיל ולא ידעה משהגדיל ולא יצאה מידי נפילה ראשונה ובגמרא (שם) פריך אהא דקתני השנייה או חולצת או מתייבמת ויעשו ביאת בן תשע כמאמר בגדול ותדחה צרה מיבום ופירש\"י ויעשו ביאת בן ט' כמאמר בגדול לדחות אשתו גמורה מיבום כי ההיא דפ' ד' אחין דקתני הרי אלו חולצות ואפי' אשתו גמורה נדחית מפני שהיא צרת זיקת ב' יבמים ואמאי קתני מתני' שנייה או חולצת או מתייבמת א\"ר לא עשו ביאת בן ט' כמאמר בגדול ושמואל אמר עשו ועשו וכן אר\"י עשו ועשו תנאי היא הך תנא דפרק ד' אחין גזר משום צרה ואשמועינן בגדול והוא הדין בקטן וכו' והאי תנא דהכא סבירא ליה לא גזר משום צרה וכו' וכתב הרא\"ש נראה דהלכה כר' יוחנן וכתנא דפרק ד' אחין דהא רבא מפרש אליביה דקאמר בשמעתין הא דקאמרי רבנן זיקת יבמין חלוצי מחלצה יבומי לא מייבמה לא תימא ה\"מ היכא דאיכא צרה וכו' וכן לעיל פרק ד' אחין אמר רבא נתן גט למאמר והיתר צרתה עכ\"ל וכ\"נ שהוא דעת הרי\"ף שהשמיט משנה זו בסוף פרק האשה רבה ובפרק ד' אחין כתב הא דאמרי רבנן זיקת יבמין חלצה מיחלץ יבומי לא מייבמה לא תימא ה\"מ היכא דאיכא צרה כו' וכ\"נ מדברי הרמב\"ם בסוף פרק ו':","קטן אינו חולץ עד שיגדיל ויבדקוהו שהביא ב' שערות אחר שהגדיל אבל אם היה לו שערות קודם שהגדיל אינו נחשב גדול על ידו אא\"כ יביא אחרות אחר שהגדיל ומ\"מ אם מוצאין לו ב' שערות אחר שהגדיל לא חיישינן שמא היו לו קודם לכן בפרק מצות חליצה (יבמות דף קה:) אמרינן דבין לר\"מ בין לחכמים איש כתוב בפרשה:","\u0003ומ\"ש אבל אם היו לו שערות קודם שהגדיל וכו'\u0004 ומ\"מ אם מוצאין אחר שהגדיל וכו' כ\"כ הרמב\"ם בפ\"ב מה\"א והוא מבואר פרק בא סימן (נדה מח:) וכתבתיו בסימן קנ\"ה ושם נתבאר דין קטנה שלא נודעה שהגיעה לכלל שנותיה והביאה סימנין שמטילין אותה לחומרא:","קטנה מבת שלשה שנים ויום אחד ביאתה ביאה לכל דבר ואם בא עליה יבם קנאה משנה בפרק יוצא דופן (נדה דף מד:) ופירש\"י קנאה וזכה בנכסי אחיו ליורשה וליטמא לה:","ומ\"ש שיכול להוציאה בגט אבל אינה חולצת עד שתגדיל ויבדקוה אם הביאה שתי שערות מסקנא דגמרא בפרק מצות חליצה (יבמות דף קה:) והלכתא עד שתביא שתי שערות כתב הרב המגיד בפרק י\"א פירוש ואפי' בדיעבד אין חליצת קטנה חליצה:","יבם קטן שבא על יבמה קטנה יגדלו זה עם זו משנה בסוף פרק ב\"ש (יבמות דף קיא:) ופירש רש\"י יגדלו זה עם זו ואם בא לגרשה אינו יכול עד שיגדיל דגט קטן אינו גט:","היבמה שנתייבמה ובא להוציאה ואמר שעדיין לא בעל וצריכה חליצה והיא אומרת שנבעלה ודי לה בגט וכו' משנה בסוף פ' ב\"ש (שם) יבמה שאמרה בתוך שלשים יום לא נבעלתי כופין אותו שיחלוץ לה לאחר ל' יום מבקשים ממנו שיחלוץ לה ובזמן שהוא מודה אפילו לאחר י\"ב חדש כופין אותו שיחלוץ לה ובגמרא (דף קיב.) עד שכופין אותו לחלוץ נכפנו לייבם א\"ר בשגיטה יוצא מתחת ידה כלומר שכיון שנתן לה גט קודם בעילה פוסלת ע\"י עצמו מיתיבי יבמה שאמרה בתוך ל' יום לא נבעלתי בין שהוא אומר בעלתי בין שהוא אומר לא בעלתי כופין אותו שיחלוץ לה לאחר ל' יום מבקשין ממנו שיחלוץ לה היא אומרת נבעלתי והוא אומר לא בעלתי הרי זו יוצאה בגט הוא אומר בעלתי והיא אומרת לא נבעלתי אף על פי שחזר ואמר לא בעלתי צריכה גט וחליצה א\"ר אמי צריכה חליצה עם גיטה רב אשי אמר התם גט לזיקתו הכא גט לביאתו הנהו שניהם מודים דאתו לקמיה דרבא א\"ל רבא חלוצו ושרו לה תיגרא א\"ל רב שרביא לרבא והתניא צריכה גט וחליצה א\"ל אי תניא תניא. ופירש\"י היבמה שאמרה בתוך ל' יום. שכנסה היבם לא נבעלתי לו ליבם וגט יבמין יוצא מתחת ידה כדמפרש בגמרא והוא אומר בעלתיך ודייך בגט כופין אותו לחלוץ דהיא נאמנת דעד ל' יום מוקי איניש נפשיה מלבעול [לאחר ל' יום הוא נאמן דלא מוקים איניש אנפשיה מלבעול] ומיהו איהי לא משתריא דשויתה [לנפשה] חתיכה דאיסורא ובעיא חליצה ומבקשין הימנו אבל כופין לא דהא בעל ובגמרא פירש\"י היא אומרת נבעלתי. לאחר ל' יום האי: יוציאה בגט. אם בא להוציאה דיה בגט דהיא נאמנת דכולי האי לא מוקים נפשיה מלבעול: צריכה גט לביאתו. משום דאמר בעלתי ולאחר שלשים יום איהו מהימן: וחליצה. משום דאיהי שויתה לנפשה חתיכה דאיסורא ומדקאמר צריכה גט מכלל דבאין לה גט עסקינן ואמאי קתני רישא כופין לחלוץ נכפינהו לייבם א\"ר אמי לעולם בשגיטה בידה והכי קאמר צריכה חליצה עם גיטה ואף על גב דקתני אמבקשין קאי והכי קאמר אף על פי שחזר ואמר לא בעלתי דאיכא למימר כופין הואיל ומודה אפי' הכי אין כופין אלא צריכה חליצה ואי לא בעי למיחלץ לא כייפינן דסמכינן אדיבוריה [קמא] הואיל ולאחר ל' יום הוא: רב אשי אמר. לעולם צריכה גט אחר לבד גט הראשון דהתם גט לזיקתו ונפסלה עליו לפיכך לא נכפנו לייבם וכיון דאמר בעלתי צריכה גט לביאתו דיש ביאה אחר הגט והשתא מסתברא אף על פי דקתני והכי קאמר אף על פי שחזר ואמר לא בעלתי ואיכא למימר לא תיבעי גט אלא חליצה אפ\"ה בעי גט: שניהם מודים. שלא נבעלה מעיקרא אמר בעלתי עכ\"ל: והשתא מ\"ש רבינו היבמה שנתייבמה ובא להוציאה ואומר שעדיין לא בעל וכו' והיא אומרת שנבעלה ודי לה בגט בתוך ל' יום נאמן וכו' היינו מדתניא היא אומרת נבעלתי והוא אומר לא בעלתי הרי זו יוצאת בגט ופירש רש\"י דלאחר שלשים יום קאי ומ\"ה דיה בגט וכו' משמע הא בתוך ל' יום דליכא למימר כולי האי לא מוקים אנפשיה אין די בגט וצריכה נמי חליצה:","ומ\"ש ומבקשין אותו שיתן גט אבל אין כופין אותו הטעם דכיון דלפי דברי אינה צריכה גט אין כופין אותו:","ומ\"ש ואם היא אומרת לא כבעלתי והוא אומר בעלתי שנאמנת וכופין איתו לבעול או לחלוץ ואם גט יוצא מתחת ידה והוא אומר שבעל קודם הגט וכו' כופין אותו לחלוץ היינו מתניתין דקתני יבמה שאמרה בתוך ל' יום לא נבעלתי כופין אותו שיחלוץ לה ואוקימנא כשגיטה יוצא מתחת ידה הא לאו הכי כופין אותו לייבם או לחלוץ:","ומ\"ש ואם אחר ל' יום אומר לא בעלתי וצריכה חליצה והיא אומרת כבעלתי נאמנת ודיה בגט היינו דתניא היא אומרת נבעלתי והוא אומר לא בעלתי הרי זה יוציא בגט ופירש\"י דבתוך ל' יום מיירי:","ומ\"ש ואם היא אומרת לא נבעלתי והוא אומר שבעל נאמן ואין כופין אותו שיחלוץ לה וכולי ומבקשין אותו שיחלוץ לה היינו מתני' דקתני לאחר ל' יום מבקשים ממנו שיחלוץ לה: ודי אפי' חזר והודה לדבריה שלא בעל ודי לה בחליצה אין שומעין לו וצריכה גט וחליצה היינו דתניא הוא אומר בעלתי והיא אומרת לא נבעלתי אף ע\"פ שחזר ואמר לא בעלתי צריכה גט וחליצה:","ומ\"ש ואפי' יש לה גט ממנו והוא אומר שנתנו לה קודם שבעל צריכה גט שני וחליצה היינו מאי דא\"ר אשי התם גט לזיקתו והכא גט לביאתו. ויש לתמוה על רבי' למה השמיט סיפא דמתני' דקתני ובזמן שהוא מודה אפי' לאחר י\"ב חדש כופין אותו שיחלוץ: והרמב\"ם ז\"ל כתב בפ\"ב בלשון הזה יבמה שנתייבמה ואמרה בתוך ל' יום לא נבעלתי ואף על פי שהוא אומר בעלתי וגירשה כופין אותו שיחלוץ לה הואיל וקדם וגירשה בגט ואם עדיין לא גרש כופין אותו שיבעול או יחלוץ ויוציא בגט גירשה לאחר שלשים יום והיא אומרת לא נבעלתי מבקשין ממנו שיחלוץ לה ואם היה מודה שלא בעל כופין אותו לחלוץ היא אומרת נבעלתי והוא אומר לא בעלתי אינה צריכה חליצה שאין זה נאמן לאוסרה על כל אדם אחר שכנסה עכ\"ל. וכ' ה\"ה דעת רבינו מ\"ש יבמה שנתייבמה וכו' דין המשנה שהעמידוה כשהגט יוצא מתחת ידה ופירשו ז\"ל דהגט הזה נתן עכשיו דאי קודם כניסה אפי' לאחר ל' יום היתה היא נאמנת לומר לא נבעלתי דכיון דאיכא איסורא מוקי נפשיה מלבעול וכתב רבינו ואם עדיין לא גירש שיכופו אותו לבעול או שיחלוץ ויוציא בגט כך הוא עיקר הנוסחא ויש ספרים שכתוב בהן או יוציא בגט וט\"ס הוא דודאי דגט בלבד אינו פוטר כיון שאומרת לא נבעלתי אלא תרתי בעינן והטעם לזה דכיון דאיהו אמר בעלתי חיישינן לה וצריכה גט וכיון דאיהי אומרת לא נבעלתי צריכה חליצה דלענין איסורא ספיקא הוא לדידן וזהו דין הברייתא דקתני הוא אומר בעלתי והיא אומרת לא נבעלתי אף על פי שחזר ואמר לא בעלתי צריכה גט וחליצה וי\"מ אותה לאחר ל' יום ונראה מדבריהם דתוך ל' יום אינה צריכה אלא חליצה אבל לאחר ל' יום צריכה גט לפי שהוא נאמן לומר בעלתי וחליצה משום דאיהי שוייה אנפשה חתיכה דאיסורא ואין נראה מדברי רבינו כן אלא תרי בבי דסיפא [דברייתא] בכל זמן הן בין בתוך ל' בין לאחר ל' ועוד י\"ל שמה שאמר הנהו שניהם מודים וכו' שהוא אפי' תוך ל' יום ואף על פי שלא אמר מעיקרא בעלתי [שלא] כדברי רש\"י ז\"ל שפירש ומעיקרא אמר בעלתי והטעם דכל שכנסה אינה יוצאה אלא בגט אף על פי ששניהם מודים שלא בעל משום דכיון שכנס מסתמא בעל שמא יאמרו יבמה שנתייבמה יוצאה בחליצה ונ\"ל ראיה לזה ממה שאמרו שם בעא מיניה הון בריה דרב נחמן מרב נחמן צרתה מהו א\"ל וכי מפני שאנו כופין ומבקשים נאסור צרה ופירש\"י דאף על גב דאמרה יבמה לא נבעלתי צרתה ודאי לא מיתסרא דחזקה כונס את האשה בועל לאלתר [אלמא אפי' לקולא אמרינן שנבעלה] ואם כן האיך תהיה מותרת לאלתר בלא גט וזה נראה דעת רבינו שכתב או יחלוץ ויוצאה בגט ומשמע דבכל גווני צריכה גט שאם דוקא כשהוא אומר בעלתי ה\"ל לכתוב אף על פי שחזר ואמר בעלתי וכן נראה מן ההלכות שאם כפירוש רש\"י לא היו צריכין להביא ההוא דהנהו שניהם מודים כיון שכבר כתבו הברייתא כן נראה לי: ומ\"ש רבינו גירשה לאחר ל' הוא מבואר במשנה והטעם דאיהי שוייה אנפשה חתיכה דאיסורא ולפיכך צריך חליצה: ומ\"ש היא אומרת נבעלתי הוא בברייתא ונראה שרבי' מפרשה אפי' תוך שלשים יום וזהו שכתב שאין זה נאמן לאוסרה על כל אדם אחר שכנסה ולא כתב אחר ששהה שלשים יום אבל רש\"י פירשה דוקא לאחר ל' ודברי רבינו נראין לי עיקר דחזקת כנוסה בעולה וכיון שהיא אומרת נבעלתי נאמנת ולא גרעה מצרה שאמרנו שהיא מותרת בחזקה לא נתבאר לי למה לא נזכר דין הצרה בהלכה ובדברי רבינו עכ\"ל:","\u0003ולענין איסור הצרה לדעת ר\"י אינו נאמן לאוסרה וכו'\u0004 שם בעא מיניה הון בריה דר\"נ מרב נחמן צרתה מהו א\"ל וכי מפני שאנו כופין ומבקשים תיאסר הצרה ופירש\"י צרתה מהו. יבמה שכנסה היבם ונפטרה צרתה ואמרה יבמה לאחר זמן לא נבעלתי מהו ליאסר צרתה מפני דיבורה של זאת: מפני שאנו כופין ומבקשין. לצרתה דאיהי שויתה לנפשה חתיכה דאיסורא נאסרה צרתה ודאי לא מיתסרא דחזקה כונס את האשה בועל לאלתר וכתב הרא\"ש משמע מתוך פירושו אף על פי שהיא אומרת לא נבעלתי וגם הוא אומר לא בעלתי לא מהימני לאסור הצרה מדפירש שאחר הסתירה הרי היא בחזקת בעולה מיד והותרה צרתה ודוקא לגבי דידה אהני דיבורה דשויתה לנפשה חתיכה דאיסורא אבל לא לגבי צרה ונ\"ל לדקדק מתוך פירש\"י דאם אמר בתוך ל' יום לא בעלתי דהצרה אסורה שהרי פירש שהיא אומרת נבעלתי והוא אומר לא בעלתי דיוצאה בגט דלאחר ל' יום איירי ולכך לא בעיא חליצה דהיא נאמנת דכולי האי לא מוקים נפשיה אבל תוך ל' יום דהוא נאמן ובעיא חליצה ומדנאמן לאוסרה אף על פי שהיא מכחישתו כ\"ש שהוא נאמן לאסור הצרה ומה שפירש\"י דכיון שנסתרה הרי היא בחזקת בעולה אכופין בתוך ל' ומבקשין אחר ל' קאי דמיירי כשהוא אומר בעלתי ואהא קאמר שהיא נאמנת לשוייה אנפשה חתיכה דאיסורא אבל לא אצרה אבל לאחר ל' אפילו שניהם מודים צרה מותרת דלא מוקים אנפשיה כולי האי עכ\"ל. ומתוך לשון זה יתבאר לך שמה שכתוב בספרי רבינו בדעת הרא\"ש נאמן לאסור הצרה ואפי' אם אומר שבעל ט\"ס הוא וצריך להגיה ואפילו אם היא אומרת שבעל:","\u0003ומ\"ש רבינו דלדעת הרא\"ש אינו נאמן לאוסרה וכו'\u0004 מדברי התוס' נראה שתופסים דברי רש\"י כפשוטה דצרה שריא בכל גווני וכתבו שכן פר\"ת ובחד לישנא מפרש ר\"י כוותייהו בענין צרה ופליג עליה רש\"י במה שפירש דברייתא דקתני היא אומרת נבעלתי והוא אומר לא בעלתי דאאחר ל' קאי ובאידך לישנא פליג עלייהו בענין צרה וקאמר דלא שריא צרה אלא לאחר ל' דוקא ובסוף דבריהם כתבו ומחמת ב' הלשונות שפר\"י נראה לאסור הצרה עד לאחר ל' אף אם יודו שניהם שבעל ולהצריך גט לכונסה אפי' תוך ל' אפי' שניהם מודים שלא בעל עכ\"ל (וכ\"ד המ\"מ) ורבי' כתב בשם ר\"י כלישנא דשרי ולא היה ראוי לכתוב כן בשמו כיון דאיהו גופיה ספוקי מספקא ליה. והרי\"ף והרמב\"ם ז\"ל השמיטו דין זה דצרה וצריך טעם למה והרא\"ש תמה על הרי\"ף למה השמיטו והניח הדבר בתימה ולע\"ד נראה שהם ז\"ל מפרשים כפר\"ח וכדמשמע מפשטא דפירש\"י דצרה בכל גווני שריא ומפני כך לא הזכירוה דכיון שלא נזכר מהי תיתי לן לאוסרה: \u0005(ב\"ה) וכיון דמהרי\"ף והרמב\"ם משמע דשרי ורבי' חננאל סבר הכי ודברי רש\"י כפשטן הכי מוכח ומה שרצה הרא\"ש לפרש דבריו לאסור אינו מוכרח כדבריו ויש לדחות ונקטינן להתיר ואע\"ג דר\"י משמע דמספקא ליה לא שבקינן פשיטותא דכל הני דכוותא משום ספיקא דידיה:\u0006"],["\u0003קטן פחות מבן ט' שנים אין ביאתו כלום ומבן ט' ואילך וכו'\u0004 פי' קטן לא תקינו ליה רבנן נישואין ולא קידושין דאין קנינו בקנין ובג' דרכים שהאשה נקנית בהן בכסף בשטר ובביאה אינה ניקנית לקטן ויוצאה ממנו בלא גט ובלא מיאון אלא דביבמה כיון דהקנו לו אשה זו מן השמים עשו רבנן ביאת קטן שיהא קונה כמאמר בגדול וכשיגדיל ולא בא עליה צריכה גט לביאתו וחליצה לזיקתו אבל מיהו קנאה לענין שזכה בנכסי אחיו:","\u0003ואם בא עליה כשהוא קטן ומת וכו'\u0004 משנה ס\"פ האשה רבה (יבמות דף צ\"ו) ופסק הלכה כרבי יוחנן דכי היכי דיבמה שיש עליה זיקת שני יבמין אינה מתייבמת כך אשתו שנשאת משהגדיל כיון שהיא צרת זיקת שני יבמין גם כן חולצת ולא מתייבמת והב\"י הביא כל הסוגיא:","יבם קטן שבא על יבמה קטנה יגדלו זה עם זה משנה סוף פרק ב\"ש ואין הטעם דכיון דשניהם אינן בני עונשין לא חיישינן שמא ימצא הוא סריס או היא תמצא איילונית והוי אשת אח שלא במקום מצוה דקי\"ל קטן אוכל נבילו' אין ב\"ד מצווין להפרישו האי טעמא ליתא דא\"כ קשה הא דתנן בא על יבמה גדולה תגדלנו הא כל ביאה וביאה דאיסורא הוא אלא אתא לאשמועינן דאעפ\"י דכתיב להקים שם אחיו והני לאו בר הכי אפ\"ה יגדלו זה עם זו דיבמה יבא עליה כל דהו קאמר גמרא לשם:","\u0003היבמה שנתייבמה וכו'\u0004 עד סוף הסימן שם במשנה ובגמרא וכמו שפירש\"י ע\"ש ומביאו ב\"י:","\u0003ומ\"ש בתוך ל' יום הוא נאמן וצריכה חליצה כצ\"ל:\u0004 ","\u0003ומ\"ש וכיון שאומרת שבעל ולפי דבריה צריכה גט וכו'\u0004 הקשה מהרש\"ל כיון שכנסה ועשה בה מאמר א\"כ אף לדבריו שלא בעל צריכה גט למאמרו ויש לתרץ דמשנתינו זו מדברת ביבמה שנתייבמה מה\"ת דא\"צ לקדשה כדלעיל בתחילת סימן הקודם ומיהו אפי' את\"ל דמיירי הכא בשעשה בה מאמר כתקנת חכמים אפ\"ה איכא נפקותא דלפי דבריו א\"צ לכוין בגט אלא להפקיע מאמרו שאינו קונה אותה בו אלא מדרבנן אבל לפי דבריה אינה נפטרת ממנו אלא א\"כ נתכוין בגט לפטור את אשתו שהיא קנויה לו מן התורה בביאתו ודו\"ק: ומ\"ש ומבקשין אותו שיתן גט אינו מפורש בסוגיא ורבינו למד להורות כך מדין חליצה לאחר ל' דמבקשין שיחלוץ דה\"ה נמי תוך ל' לגבי גט דמבקשין אותו שיתן גט ויש לדחות דלאחר ל' שאני כיון דלא מוקים אנפשיה ודאי נאמן הוא דבעל הלכך מבקשין שיחלוץ אבל תוך ל' דאינו ודאי דלא בעל דאפשר דבעל כופין אותו שיתן גט כיון שהיא אומרת נבעלתי:","ואם היא אומרת לא נבעלתי והוא אומר שבעל נאמנת וכופין אותו לבעול או לחלוץ כך הוא לשון הרב רבינו משה בר מיימוני ולשיטתו הלשון מתוקן דר\"ל שכופין אותו לבעול דמצות יבום קודמת ואם לא חפץ ביבום כופין אותו שיחלוץ אבל לרבינו דמסקנת הרא\"ש כרש\"י ור\"ת דמ\"ח קודמת אין כופין אותו לבעול אלא שיחלוץ והכי מוכח בסוגיא דקא מקשה אהא דתנן היא אמרה לא נבעלתי תוך ל' דנאמנת וכופין אותו שיחלוץ ועד שכופין אותו שיחלוץ נכפינו לייבם וכו' וכתבו התוס' לא בעי לאוקומי הך משנה כמשנה אחרונה דמצות חליצה קודמת וכו' אלמא למ\"ד מ\"ח קודמת אין כופין אותו לבעול אלא כופין שיחלוץ לה וי\"ל דרבינו נמי ה\"ק כופין אותו לבעול למ\"ד מצות יבום קודמת או כופין לחלוץ למ\"ד מ\"ח קודמת והאי כופין לחלוץ לצדדין קאמר דאם רוצה לבעול כפינן ליה במילי לחלוץ ואם אינו רוצה לא לבעול ולא לחלוץ אלא ליתן גט בלחוד לפי שאומר בעלתי כופין אותו בשוטים לחלוץ ועיין במ\"ש בסימן קס\"ה ס\"ב. ונראה מדלא כתב רבי' או לחלוץ ויוציא בגט כלשון הר\"ר משה בר מיימוני אלמא דא\"צ גט וכ\"כ התוס' לפי פירש\"י בד\"ה היא אומרת אבל למ\"ש לשם התוס' בשם ר\"י צריכה גם כן גט ואפי' שניהם מודים שלא בעל:","\u0003ומ\"ש ואם אחר שלשים יום וכו'\u0004 עד וצריכה גט וחליצה וכו' משמע מלשון רבינו דאף לאחר שהודה לדבריה מבקשין ואין כופין לחלוץ דסמכינן אדיבוריה קמא הואיל שהוא לאחר ל' וכן פי' רש\"י להדיא אבל התוס' כתבו דבחזר והודה כופין לחלוץ ועוד כתבו דאפי' מתחילה הודה שלא בעל צריכה נמי גט:","\u0003ומ\"ש ולענין איסור הצרה לדעת ר\"י וכו'\u0004 פירוש משום דאף בתוך שלשים בחזקת שבא על יבמתו ונפטרה צרתה ואינו נאמן לאוסרה וכו' אלא דכשאומרת היא שלא נבעלה חוששין לדבריה בתוך שלשים יום וכופין שיחלוץ דתלינן דמוקי איניש אנפשיה מלבעול עד ל' יום:","\u0003ומ\"ש ואפילו אם יש לה גט ממנו והוא אומר שנתנו לה קודם שבעל וכו'\u0004 נראה דהיינו לומר שנתן לה גט לזיקתו קודם כניסה ואחר כך כנסה ובעל דיש ביאה אחר הגט וצריכה גט שני לביאתו כ\"כ הרי\"ף שנתן לה גט קודם בעילה פסלה על עצמה וכ\"כ הרא\"ש כשגיטה יוצא מתחת ידה ואח\"כ יבמה שע\"י הגט פסלה על עצמו אבל ה\"ה כתב דפירשו ז\"ל דהגט נתן עכשיו דאי קודם כניסה אפי' לאחר ל' היתה היא נאמנת לומר לא נבעלתי דכיון דאיכא איסורא מוקי אנפשיה מלבעול עכ\"ל ומביאו ב\"י ויש לדחות ולומר דאף ע\"ג דאיכא איסורא דילמא לא מצי מוקים אנפשיה:"]],["\u0010c0\u0011\u0010y0\u0011משייבם היבם היבמה הרי היא כאשתו לכל דבר שיכול להוציאה בגט ולהחזירה ולא אמרי' כיון שכבר קיים מצות יבום חזר איסור אשת אח למקומה \u0010c1\u0011וכתובתה על נכסי בעלה הראשון ואם אין נכסים לראשון \u0010y1\u0011יש לה כתובה מנה משני כדין אלמנה כדי שלא תהא קלה בעיניו להוציאה \u0010y2\u0011אבל כ\"ז שיש לראשון אפילו הן ביד לקוחות אין לה מנכסי שני כלום \u0010c2\u0011\u0010y3\u0011גירשה והחזירה קודם שפרע לה כתובתה דינה כאשה אחרת שגירשה והחזירה שאין לה אלא כתובה אחת שהמגרש אשתו והחזירה על דעת כתובתה הראשונה הוא מחזירה \u0010y4\u0011וכיון שכתובתה על נכסי המת אין היבם רשאי למכור כלום מנכסי אחיו אלא יהיו כולם קיימין לשיעבוד כתובתה ואם מכר או נתן מהם מעכשיו בטלים לא שנא אם מכר או נתן קודם יבום או אחרי יבום \u0010y5\u0011ואפילו אם הניח מטלטלין כגון מעות או פירות תלושין ימכרם וילקח בהן קרקע והוא אוכל פירות והגוף יהיה קיים לשיעבוד כתובתה \u0010y6\u0011ואפי' היה הוא חייב לאחיו מנה לא יאמר הואיל ואני יורשו אחזיק במה שבידי אלא מוציאין אותו מידו וילקח בהם קרקע והוא אוכל פירות והראב\"ד כתב בזה שאין מוציאין אותו מידו והרמב\"ם ז\"ל כתב דאפילו בשאר מטלטלין שהניח אחיו משתמש בהן כמו שירצה ואינה יכולה לעכב עליו כיון שאין כתובה נגבית ממטלטלין אלא מתקנת הגאונים אין כח בתקנה זו למונעו מנכסי אחיו לאוסרו באחריות זו שלא ישא ויתן בהם ע\"כ ורב אלפס כתב כסברא ראשונה ולזה הסכים א\"א הרא\"ש ז\"ל \u0010y7\u0011ואפילו גירשה וכנסה אח\"כ סתם אינו יכול למכור דכיון שכנסה סתם לא נתחייב לה בכתובה אא\"כ יתנו בשעה שמחזיר שכתובתה על נכסיו ואז יכתוב לה כתובה באחריות על כל נכסיו שקנה ושיקנה ויכול למכור וה\"ה נמי בלא גירושין אם מתרצת לו שימכור ע\"מ שיתחייב לה באחריות כתובתה שיכתוב לה אחריות על כל נכסיו שקנה ושיקנה יכול למכור: \u0010c3\u0011כתב הרמב\"ם יבמה שלא היתה לה כתובה או שמחלה כתובתה זכה בנכסי אחיו ויכול למכור וליתן כחפצו וכשיכנוס יבמתו יכתוב לה מנה ויהיו כל נכסיו אחראין לכתובתה כשאר כל הנשים \u0010c4\u0011וכתב עוד יבמה שלא היה לה על בעלה כתובה מפני שהיבמה אסורה עליו והרי היא מותרת לאחיו אם רצה היבם לייבם כונס ואין לה כתובה כדרך שלא היה לה על בעלה ודינה עם יבמה בתוספת כמו שהיה לה על בעלה אבל לא כתב לה בעלה כתובה או שמכרה לו או שמחלה צריך היבם לכתוב לה כתובה כדרך כל האלמנות:",["משייבם היבם היבמה הרי היא כאשתו לכל דבר שיכול להוציאה בגט ולהחזירה ולא אמרינן דכיון שכבר קיים מצות יבום חזר איסור אשת אח למקומו בפרק החולץ (יבמות דף לט.) ובס\"פ האשה שנפלו (כתובות דף פב:) ומייתי לה מדכתיב ולקחה לו לאשה כיון שלקחה הרי היא כאשתו לכל דבר: ומ\"ש וכתובתה על נכסי בעלה הראשון ואם אין נכסים לראשון יש לה כתובה מנה משני וכו' שם (לח.) במשנה כנסה הרי היא כאשתו לכל דבר ובלבד שתהא כתובתה על נכסי בעלה הראשון ובגמ' (לט:) מ\"ט אשה הקנו לו מן השמים ואי לית לה מראשון תקינו לה משני כדי שלא תהא קלה בעיניו להוציאה ופירש\"י אשה הקנו לו מן השמים. ולא שיעבד נכסיו לכתובה ויכול למוכרם בכל עת שירצה: ואי לית לה מראשון. דלית ליה נכסי:","\u0003ומ\"ש רבינו יש לה כתובה מנה משני פשוט הוא וכ\"כ הרמב\"ם בפ' כ\"ב מהל' אישות:\u0004 ","ומ\"ש אבל כל זמן שיש לראשון אפי' הן ביד לקוחות אין לה מנכסי שני כלום התוס' הקשו אהא דאמרינן מאי טעמא אשה הקנו לו מן השמים וא\"ת מה מרויח בכך היבם כיון דאי לית לה מראשון תקינו לה משני וכי תימא שאם מכר הראשון נכסיו טרפה מלקוחות אע\"פ שיש בני חורין לשני א\"כ תהא קלה בעיניו להוציאה ואומר ר\"י דנפקא מינה שיכול היבם למכור שדותיו ואפי' אשתדוף שדותיו של מת לא טרפה ממשעבדי אי נמי נפקא מינה אם גירשה ואח\"כ אשתדוף שדותיו של מת דלא גבי מבני חרי לשני והר\"ן כתב אי נמי נפקא מינה לענין נדוניא דאפי' ליכא נכסים משני אין לה על השני אלא עיקר כתובה אף ע\"פ שהוציא נכסים משל אחיו שהיו מספיקים לנדוניתא ע\"כ ורבינו כתב כתירוצא קמא דתוס' ולא חש לחששא דתהא קלה בעיניו להוציאה ולא ידעתי למה ועיין בר\"י:","גירשה והחזירה קודם שפרע לה כתובה דינה כדין אשה אחרת שגירשה והחזירה שאין לה אלא כתובה אחת כו' משנה וגמרא בסוף פרק האשה שנפלו (כתובות דף פ:) אם תפסה האלמנה מנכסי בעלה נתבאר בסימן צ\"ג:","\u0003וכיון שכתובתה על נכסי המת אין היבם רשאי למכור כלום מנכסי אחיו וכו'\u0004 שם (דף פא) תניא רבי אבא אומר שאלתי את סומכוס הרוצה שימכור בנכסי אחיו כיצד הוא עושה אם הוא כהן יעשה סעודה ויפייס אם ישראל הוא מגרש בגט ויחזור ההוא גברא דנפלה ליה יבמה בפומבדיתא בעא אחוה למיפסלה בגיטא מיניה א\"ל מאי דעתיך משום נכסי בנכסי פליגנא לך אמר רב יוסף כיון דאמור רבנן לא ליזבון איניש אף ע\"ג דזבין לא הוי זביניה זביני ופירש\"י ומה שעשה זה שהתנה עמו לחלוק לו וקנו מידו הרי הוא כמוכר ומסיק התם דבין יבם ואחר כך חלק בין חלק ואחר כך יבם לא עשה כלום וכ\"פ הרמב\"ם ז\"ל בפ\"ב מהל' אישות. וכתבו התוס' הרוצה שימכור בנכסי אחיו לפי שאינו יכול למכור ומכר בטל לאלתר אפי' קודם שתבא לידי גבייה דהחמירו חכמים ביבמה לפי שלא כתב לה כל נכסי אחראין לכתובתה לכך תיקנו שאינו יכול למכור כלל שלא תצטרך לחזור ולטרוח ולטרוף מהלקוחות ואפי' ישאיר לה כנגד כתובתה אינו רשאי למכור השאר דחיישינן שמא יאבדו או ישתדפו השדות שישאר עכ\"ל:","ומ\"ש ואפי' אם הניח מטלטלין כגון מעות או פירות תלושים ימכרו וילקח בהן קרקע והוא אוכל פירות וכו' משנה שם (דף פ.) ופירש\"י דקסבר מטלטלי משתעבדי לכתובה:","ומ\"ש ואפי' אם הוא חייב לאחיו מנה לא יאמר הואיל ואני יורשו אחזיק במה שבידי אלא מוציאין אותו מידו וילקח בהן קרקע והוא אוכל פירות ברייתא שם (דף פא.) ואמר ר\"נ עלה זו אינה משנה מאי טעמא אילימא משום דהוה ליה מטלטלי ומטלטלי לכתובה לא משתעבדי דילמא ר\"מ הוא דאמר מטלטלי משתעבדי לכתובה ואלא משום דא\"ל לאו בעל דברים דידי את דילמא רבי נתן הוא דאמר מנין לנושה בחבירו מנה וחבירו בחבירו מנין שמוציאין מזה ונותנין לזה שנאמר ונתן לאשר אשם לו לא אשכחן תנא דמחמיר תרי חומרי בכתובה והרי\"ף הביא ברייתא זו וכתב עליה הא מתניתא ר\"מ הוא דאמר מטלטלי משתעבדי לכתובה ואף ע\"ג דלית הלכתא כוותיה וכיון דתקינו רבנן השתא למגבי כתובה ממטלטלי עבדינן כוותיה וכתב הרא\"ש תמה הראב\"ד איך הביא הרי\"ף ז\"ל ברייתא זו לפסק הלכה הא אמרינן דזו אינה משנה ולא עבדינן תרי חומרי בכתובה ואי משום דתיקנו רבנן בתראי דכתובה גבי ממטלטלי מי עדיפא תקנתא דבתראי ממילתא דר\"מ דאמר מטלטלי משתעבדי לכתובה ואפ\"ה אמרינן דדוקא במטלטלי דאיתנהו בעין ברשות היורשים אבל מלוה דאיתא ברשות אחרים לא מפקינן מלוה בע\"כ ויהבינן לאשה בכתובתה מדר' נתן דלא מחמירין תרי חומרי בכתובה וכ\"ש שהיורש גופיה הוא הלוה דלא כייפינן ליה למפרע הנהו זוזי ולא ידענא מאי קשיא ליה דהא דחשיב תלמודא להא מתניתין טעות לפי שודאי מעצמו שנאה התנא ומשבשתא היא לפי שא\"א לקיימה אם לא שנעשה המחלוקת תרי זוגי תנאי ר\"מ ובר פלוגתיה ורבי נתן ובר פלוגתיה אפי' אי ס\"ל הלכה כר\"מ וכרבי נתן תרי חומרי בכתובה לא מחמרינן אף כי ר\"מ סבר כרבי נתן ור\"נ כרבי מאיר מודו תרוייהו דלא עבדינן כהך ברייתא אבל השתא דתיקנו רבנן כתובה דגביא ממטלטלי יחזרו המטלטלין להיות כמקרקעי ואין כאן אלא חומרא אחת כרבי נתן עכ\"ל וגם הר\"ן כתב כדברי הרא\"ש ז\"ל ומ\"ש רבינו בשם הרמב\"ם ז\"ל הוא בפ' כ\"ב מהל' אישות וכתב ה\"ה שהרמב\"ן והרשב\"א ז\"ל כתבו כדעת הרי\"ף ובעיטור כתב בשם גאון כדעת הרמב\"ם ז\"ל וכתב עוד הרב המגיד דאפי' לדעת רבינו אם כתב בכתובה מטלטלי אגב מקרקעי שלוקחין קרקע מן המטלטלין שהניח האח שהרי הן משועבדים לה מן הדין ולא מן התקנה כנזכר פי\"ו עכ\"ל וכ\"כ הריב\"ש דעכשיו שכותבים בכתובות שיעבוד מטלטלין הדין עמה שיוציאו כל הנכסים מידן וילקח בהם קרקע שיהיה קיים לשיעבוד כתובתה והיבם אוכל פירות ואפי' כתובתה אינה אלא מנה והנכסים הם ק' מנה הדין כן כמו שמפורש בברייתא עכ\"ל. וכתב עוד הנכסים שביד היבמה מבואר שהדין הוא להוציאם מידה שהרי אין לה עליהם אלא שיעבוד כתובה והיבם אוכל פירות אבל לאחריות כתובתה ילקח בהם קרקע וכתב הרשב\"א בתשובה הטעם לשומרת יבם שהוא מעכב ביד היבם לרדת לנכסים ולאכול ולמכור ולהתעסק בהם לפי שאינה יכולה לכוף את היבם לפרוע לה כתובתה עכשיו לפי שהיא שומרת יבם ועוד שאין לה אחריות על נכסי היבם ואפי' לאחר שנשאה אלא נכסי הבעל הראשון. וכתב עוד שומרת יבם הדין הוא שיעמדו הנכסים המטלטלים מחמתה ומחמת היבם ביד ב\"ד או אפוטרופין עד שילקח בהם קרקע ויאכל היבם אז הפירות אבל הקרקעות שנשארו מן המת לא תרד בהם האלמנה וגם לא האפוטרופא בשבילה וגם לא תאכל היא הפירות אלא היורש לפי שאין מזונות לשומרת יבם אלא ג' חדשים הראשונים בלבד או אם עמד בדין וברח עכ\"ל. ובקצת ספרי רבינו כתב קודם סברת הרמב\"ם כלשון הזה והראב\"ד כתב בזה שאין מוציאין אותו מידו:","ואפילו גירשה וכנסה אח\"כ סתם אינו יכול למכור דכיון שכנסה סתם לא נתחייב לה בכתובה אא\"כ יתנה בשעה שמחזיר שכתובתה על נכסיו ואז יכתוב לה כתובה באחריות על כל נכסיו ושקנה ושיקנה ואז יכול למכור כ\"כ התוספות והרא\"ש ז\"ל בפ' האשה שנפלו \u0005\"ב\"ה ומפורש הוא בברייתא הנזכרת אם נתן הוא יעשה סעודה ויפייס \u0006על הברייתא שכתבתיה בסמוך הרוצה שימכור בנכסי אחיו כיצד יעשה וכו' ומ\"ש וה\"ה נמי בלא גירושין אם מתרצה לו שימכור על מנת שיתחייב לה באחריות כתובה וכו' ג\"ז כתבו שם התוס' והרא\"ש ז\"ל: כתב הרמב\"ם יבמה שלא היה לה כתובה או שמחלה כתובתה זכה בנכסי אחיו ויכול למכור וליתן כחפצו וכשיכנוס יבמתו יכתוב לה מנה וכו' בפרק כ\"ב מהלכות אישות וכתב הרב המגיד דהיינו מדתנן פרק החולץ ופרק האשה שנפלו כנסה הרי היא כאשתו לכל דבר ובלבד שתהא כתובתה על נכסי בעלה הראשון ובגמרא אי לית לה מראשון תקינו לה משני כדי שלא תהיה קלה בעיניו להוציאה ע\"כ וכבר כתב רבינו זה בסי' זה ולא חזר לכתבו אלא כדי לסמוך דברי הרמב\"ם ז\"ל שכתב לקמן בסמוך לדברים אלו וכתב עוד יבמה שלא היה לה על בעלה כתובה מפני שהיבמה אסורה עליו והרי היא מותרת לאחיו אם רצה היבם כונס ואין לה כתובה \u0005(ב\"ה בפ\"ב מיבום וע\"ש בדברי ה\"ה):\u0006"],["משייבם היבם היבמה ה\"ה כאשתו לכל דבר משנה פרק החולץ (יבמות דף ל\"ט) וקאמרינן פשיטא דמגרשה בגט סד\"א הואיל וכתיב ולקחה לו לאשה ויבמה עדיין יבומין הראשון עליה אף על פי שלקחה קרי לה ויבמה בחליצה אין בגט לא קמ\"ל ומחזירה פשיטא סד\"א מצוה דרמיא עליה עבדה השתא תיקום עליה באשת אח קמ\"ל ואימא ה\"נ אמר קרא ולקחה לו לאשה ל\"ל דכתב לאשה ש\"מ ה\"ה כאשתו וקרא ויבמה לכדרבנן ויבמה בעל כרחה:","\u0003וכתובתה על נכסי בעלה הראשון וכו'\u0004 עד אלא יהיו כולם קיימין לשיעבוד כתובתה כלומר דאף על פי דנכסי הראשון מרובים הרבה יותר מכדי כתובתה חיישינן דילמא ישתדפו מקצתם ותצטרך לחזר אחר הלקוחות הוא בפרק האשה שנפלו (דף פ\"ח) בד\"ה הרוצה שימכור:","\u0003גירשה והחזירה וכו'\u0004 עד סוף הסימן הכל בפרק האשה שנפלו (כתובות דף פ\"א) וכתב הר\"ן דקשה וכי חוב זה שחייב לאחיו עדיף טפי שאם מכרו לה דאם חזר ומחלו מחול וה\"נ למחול לנפשיה דאין לחייבו לשלמו מדינא דגרמי כיון דאין כוונתו להזיק אלא כדי לפטור לעצמו וכדלעיל בסי' ק\"ה ובח\"מ סימן ס\"ו ובמרדכי ס\"פ האשה שנפלו תירץ דכיון שנשתעבד מקודם לכתובתה אלים שיעבודא ולא מני מחיל דכל היכא דחב לאחרים לא מצי מחיל מדרבי נתן ע\"ש והראב\"ד כתב בזה כלומר בזה שחייב לאחיו וטעם מחלוקת זה הביא ב\"י ע\"ש:","כתב הרב רבי' משה בר מיימוני יבמה שלא היה לה כתיבה וכולי בפרק כ\"ב מאישות כ\"כ ואף ע\"ג דאסור לאדם שישהה עם אשתו בלא כתובה אפי' מחלה לו כתובתה ואפילו התנה בשעת קידושין שלא יהא לה כתובה וכדלעיל בסימן ס\"ו אפ\"ה כתב הרב רבינו משה בר מיימוני דין יבמה זו שבעלה עבר עבירה ושהה עם אשתו בלא כתובה דהיבם זכה בנכסי אחיו וכו' וכתב ה\"ה דהיינו מדתנן כתובתה על נכסי בעלה הראשון ואי לית לה מראשון תקינו לה משני עכ\"ל ואע\"ג דבריש סי' זה כתב רבינו ע\"פ פירש\"י דאי לית לה מראשון היינו שאין נכסים לראשון חזר והביא דברי הרמב\"ם דמפרש ואי לית לה מראשון כגון שעבר ושהה עם אשתו בלא כתובה או שמחלה לו כתובתה ולא כתב לה אחרת סבירא ליה לרבינו דב' הפירושים אמת:","\u0003וכתב עוד יבמה וכו'\u0004 בפ\"ב מהלכות יבום כ\"כ והוא בעיא דאיפשיט' מברייתא בפרק יש מותרות(יבמות דף פ\"ה) דהכי קתני כתובתה על נכסי בעלה הראשון ואי לית לה מראשון תקינו לה משני ואם היתה שנייה לבעל אפי' מיבם אין לה ואפשר דמכאן הוציא הרמב\"ם דדוקא בהיתה שנייה אבל בהיתה כשרה אלא דהבעל עבר עבירה ולא כתב לה כתובה אית לה מיבם כמ\"ש בפרק כ\"ב דאישות שהביא רבינו קודם זה דאל\"כ למה תני שנייה ה\"ל לאשמועי' דאפי' כשרה נמי אם לא ה\"ל כתובה מבעל אין לה נמי מיבם ומיהו קצת קשה כיון דדין שנייה מפורש בגמרא אמאי כתבו רבי' ע\"ש הרמב\"ם ואיפשר ליישב דה\"ה כתב דהרמב\"ן והרשב\"א פירשו דאפילו היתה שנייה אם לאחר שכנסה היבם הוא בא לשהות עמה הא קי\"ל שאסור לאדם לשהות עם אשתו בלא כתובה אלא הכא כשבא עליה וקנאה והוא בא להוציאה קודם שיכתוב לה קאמר דלית לה עכ\"ד אבל מלשון הרמב\"ם שכתב מייבם ואין לה עליו כתובה כדרך שלא היה לה על בעלה משמע ליה לרבינו דאפילו הוא בא לשהות עמה אין לה כתובה ולא עבר עבירה דלא אסור לשהות עם אשתו בלא כתובה אלא באשה שקנאה לו לדעתו שלא תהא קלה בעיניו להוציאה אבל זו שלא היה לה כתובה מבעלה והקנוה לו מן השמים ושלא תהיה לה כתובה גם ממנו אינה קלה בעיניו להוציאה א\"נ איפכא באשה כשרה חששו שלא תהא קלה בעיניו להוציאה אבל זו שנישאת לאחיו באיסור ולא היתה לה כתובה ממנו ומדינא מיבם נמי לית לה כתובה אין לנו לחוש אם תהא קלה בעיניו להוציאה דלא כהרמב\"ן והרשב\"א והשתא ניחא הא דכתב רבינו דין זה ע\"ש הרמב\"ם ומה שהקשה ב\"י בריש סימן זה על מ\"ש רבינו דכ\"ז שיש לראשון אפילו הן ביד לקוחות אין לה מנכסי שני כלום דאם כו תהא קלה בעיניו להוציאה וכמו שהקשו התוספות בפרק החולץ י\"ל דרבינו ס\"ל דביבמה שיש לה כתובה מנכסי ראשון שביד הלקוחות כיון דעכ\"פ יש לה כתובה שוב אינה קלה בעיניו להוציאה ולא חשש לקושיית התוספות בפרק החולץ לפי דבתוספות פרק האשה שנפלו (דף פ\"ה) בד\"ה הרוצה שימכור כתבו כך בדברי רבינו ולא הקשו קושיא זו אלמא דמסקנת התוספות דביבמה אינה קלה בעיניו להוציאה: ומ\"ש בגמרא תקינו לה משני שלא תהא חלה בעיניו להוציאה היינו דוקא דלית ליה נכסים לראשון כלל לא בני חורין ולא משועבדים:"]],["\u0003הלכות חליצה \u0004\n\u0010c0\u0011\u0010y0\u0011בא לחלוץ \u0010y1\u0011יועדו ג' דיינים לחלוץ בפניהם שמצות חליצה בג' דיינים \u0010y2\u0011ישראלים \u0010y3\u0011כשרים שלא יהיו קרובים זה לזה ולא ליבם ויבמה \u0010y4\u0011ואפי' הם הדיוטות \u0010y5\u0011רק שידעו להקרות את היבם והיבמה \u0010y6\u0011נמצא אחד מהם קרוב או פסיל או גר \u0010c1\u0011אפילו היה אביו גר ואמו מישראל פסול עד שיהא אביו ואמו מישראל \u0010y7\u0011ובספר המצות הכשיר אמו מגרים רק שיהא אביו מישראל \u0010y8\u0011ומיהו חליצה פסולה מיהא הוי לפוסלה על האחים אפילו ביחיד ואפילו בינו לבינה נמצאו עמי הארץ שאין יודעין אפילו להקרות החליצה כשרה \u0010c2\u0011\u0010y9\u0011ולכתחילה מצוה שיוסיפו שנים על הג' לפרסומי מילתא ואפילו הן ע\"ה \u0010c3\u0011חלצה בג' חליצה כשרה כתב בעל הלכות צריכין למיתב חמשה בההוא בי דינא וכד כתבי גיטא לכתבו במותב תלתא הוינא וכן אמר רב צמח גאון \u0010c4\u0011\u0010y10\u0011ויקבעו מקום תחילה לומר נחלוץ במקום פלוני וכתב אבי העזרי רבותי אומרים בההוא יומא ואני ראיתי לאבא מורי שקבע מקום בערב ביום שלפניו: \u0010y11\u0011כתב הרמב\"ם צריכין הדיינין לקבוע מקום ואח\"כ תחלוץ לפניהם לא נועדו ולא קבעו מקום אלא נקרה מקרה והקרו הוא והיא לפניהם וחלצה חליצתם כשרה ע\"כ אין חליצה כשרה אלא ביום חלצה בלילה חליצתה פסולה \u0010y12\u0011וצריך שיכירו אותו שאומר שהוא היבם שהוא אחי המת ושהיה בעולמו ושזאת היא אשת המת ומיהו \u0010y13\u0011אפילו אין כאן אלא עד אחד שמעיד עליהם שפיר דמי ואפילו הוא עבד או שפחה \u0010y14\u0011וצריך שידעו הדיינים שיש שלשה חדשים ממיתת הבעל \u0010c5\u0011\u0010y15\u0011ויבדקו היבם והיבמה אם הביאו ב' שערות ואם הוא בן י\"ג שנה ויום אחד ואם היא בת י\"ב שנה ויום אחד \u0010y16\u0011והיא נבדקת ע\"פ נשים \u0010c6\u0011\u0010y17\u0011ואם רואים שגדלו דדיה \u0010y18\u0011ושנתמלא זקנו א\"צ לבדוק יותר \u0010y19\u0011כתב הרמב\"ם אין סומכין במנין השנים לא ע\"פ קרובים ולא ע\"פ נשים אלא ע\"פ עדים כשרים להעיד \u0010c7\u0011\u0010y20\u0011ובסה\"ת כתב אם אין השנים ידועות אלא ע\"פ האב כגון שבאו ממקום אחר ואין מכירין אותו אינו נאמן להחזיקו בגדול אבל במקום שהוא דר והוחזק בעיני השכנים שלא על פי האב שבא לכלל שנים או שיצא עליו קול שבא לכלל שנים נאמנים להחזיקו בגדול אם הביא ב' שערות ולא חיישינן שמא עדיין לא בא לכלל גדול ושומא נינהו ואפילו בלא חזקת השכנים אם יש להם ריבוי שערות או שהן ארוכות חזקה שבאו לכלל שנים \u0010y21\u0011ועל זה סומכין שא\"צ לבדוק אם יש בהן גומות אע\"ג דקי\"ל שצריך שיהיו בעיקר גומות אם יש רבוי שערות או שהן ארוכות א\"צ לבדוק על הגומות \u0010y22\u0011וישבו הדיינין כמו שצריכין לישב בדין \u0010c8\u0011ויעמדו לפניהם היבם והיבמה שמצות חליצה מעומד לא עמדו אלא חלצו מוטין או יושבין חליצתם כשרה \u0010y23\u0011וישאלוהו אם ירצה לייבם או לחלוץ \u0010y24\u0011ואם אמר שרוצה לחלוץ יאמרו לו לבטל כל מודעות שמסר כמו גבי גט שאם מסר מודעא תחלה החליצה פסולה \u0010y25\u0011מי שכופין אותו לחלוץ בדין ומסר מודעא תחלה ולא בטלה משמתינן ליה \u0010y26\u0011ויתנו לו מנעל החליצה במתנה שצריך שיהא שלו אף ע\"פ שמחזירו אח\"כ קרינן ביה שפיר שלו \u0010y27\u0011וי\"א שצריך שיהלך בו מעט כדי שיהא נראה כשלו ואם לא נתנוהו לו כשר \u0010c9\u0011\u0010y28\u0011והמנעל צריך שיהא כולו של עור לפיכך צריך לתופרו בעור \u0010c10\u0011\u0010y29\u0011אבל רצועותיו א\"צ שיהא מעור \u0010y30\u0011וכתב בסה\"מ צריך שיהיה העור קשה קצת שיהיה דומה קצת לסנדל שמן הדין לא היה ראוי לחלוץ אלא בסנדל \u0010c11\u0011אלא שאינו מצוי לכך צריך שיהא דומה קצת לסנדל ולא יהיה תפור בו בגד בפנים \u0010c12\u0011\u0010y31\u0011ומאיזה עור שיהיה הסנדל שפיר דמי ולא כדברי ר\"ת שכתב שצריך שיהיה עור בהמה טהורה דוקא \u0010c13\u0011\u0010y32\u0011ויהיה לו רצועות לקושרו בהן ולהדקו על הרגל וגם כמין קשר באזנו האחת שיכניסוה בנקב שיהיה לו באזנו השנית כדי להדקו יפה \u0010c14\u0011\u0010y33\u0011וכתב בסה\"מ צריך שיהו הרצועות לבנות ושלא יהיה לו לשון כמו שרגילין לעשות במנעלין כדי שלא יהא מעל דמעל \u0010y34\u0011ושיהיה התפירה מבחוץ ושיהיה עשוי לצורת הרגל הימנית וינעלנו ברגלו הימני \u0010y35\u0011ויהיה למדת רגלו שלא יהיה גדול עד שאין ראוי להלוך בו ולא קטן עד שאין מכסה רוב רגל ולא יהיה קרוע עד שאינו יכול להלוך בו \u0010c15\u0011\u0010y36\u0011היה בגד פשתן תפור בו מבפנים או שתפירותיו בפשתן \u0010c16\u0011או שהוא של עץ או של סיב או שעם ומחופה עור \u0010y37\u0011או שהוא גדול ממדת רגלו ויכול להלוך בו או שהוא קטן ממדת רגלו ומכסה רוב הרגל ויכול להלוך בו או שלא היה שלו או שהוא עשוי בצורת רגל שמאלי ונועלו בימין או שחלץ באנפיליא של עור או בסמיכת הרגלים או במוק החליצה כשרה בדיעבד והרמ\"ה כתב דבמנעל התפור בפשתן פסול אפילו בדיעבד אבל חלצה בשל עץ או של שעם שאינו מחופה עור או ברגל שמאל או שיהיה המנעל גדול עד שאינו יכול להלך בו או קטן שאינו מכסה רוב רגלו או קרוע שאינו יכול להלך בו או בסנדל שאין לו עקב או באנפיליא של בגד חליצתה פסולה \u0010c17\u0011\u0010y38\u0011כתב הרמב\"ם חלצה במנעל של בגד אינה חליצה כלל אפילו לפסול על האחין: \u0010c18\u0011\u0010y39\u0011מנעל של עכו\"ם שמניחין אותו ברגלי הדמות כו\"ם לא תחלוץ בו ואם חלצה בו חליצתה כשרה אבל סנדל של תקרובת עכו\"ם או של עיר הנדחת או שנעשה למת שנקבר בו אם חלצה חליצתה פסולה שהרי אינו עשוי להלוך בו \u0010c19\u0011\u0010y40\u0011כתוב בסה\"מ אפי' אטר חולץ בימין של כל אדם אע\"פ שהוא שמאלו \u0010y41\u0011וי\"א שהוא חולץ בשתיהן במנעל של ימין לימין ובמנעל של שמאל בשמאל \u0010y42\u0011אבל אם שולט בשתי רגליו וכן היא בשתי ידיה אז יעשו בשל ימין וי\"א שאיטר חולץ בימין שלו שהוא שמאל של כל אדם והכי מסתברא דבכה\"ג אמרינן בתפילין שמניח בשמאלו שהוא ימין של כל אדם \u0010c20\u0011\u0010y43\u0011וינעול המנעל על רגלו כשהוא יחף ולא על בתי שוקים שלא יהא מעל דמעל ומטעם זה יש מדקדקים שלא יהא טיט דבוק במנעל בפנים שלא יהא מעל דמעל \u0010y44\u0011ויקשרנו קשר גמור ולא בעניבה וי\"א שצריך שני קשרים זה על זה וכתב בספר המצות צריך שיהא הקשר על בשר שוקו ולא על אזני המנעל לכך כתב בספר המצות שצריך שיחתוך ממנו לפניו ולאחריו כמו פגימה ויכוין שיבא הקשר באותו מקום ולא באזני המנעל כדי שיהיה על בשרו ויכניס הקשר שבאזנו בנקב שבאזנו השנית \u0010y45\u0011וצריך שיקראו אותה בעמידה מאן יבמי להקים לאחיו שם בישראל לא אבה יבמי \u0010y46\u0011ואפי' אם היא מאותן שחולצות ולא מתייבמות שלא התירו להתייבם אפ\"ה צריכה קריאה \u0010y47\u0011ויקראו אותה מלה במלה זו אחר זו בלשון הקדש \u0010c21\u0011רק לא אבה צריך שיקראוהו בנשימה אחת בלא הפסק והרמב\"ם כתב מלמדין אותה שתהא רגילה לקרות לא אבה בנשימה אחת שלא יהיה משמע דבריה אבה יבמי ומאחר שתהיה רגילת לקרות אע\"פ שלא קראה בנשימה אחת אין מקפידין על זה אבל אם אינה יכולה מרגילין אותה עד שתדע ע\"כ \u0010c22\u0011\u0010y48\u0011וכן יראה מדברי רב אלפס שאם אינה יודעת לקרות כאחת אינו מעכב וא\"א הרא\"ש ז\"ל כתב שצריך שתקרא אותו בלי הפסק \u0010y49\u0011ויקראוהו מעומד לא חפצתי לקחתה \u0010y50\u0011ואין לחוש אם יפסיק בין לא חפצתי \u0010y51\u0011וידחוק רגליו בקרקע \u0010y52\u0011ותגביה היא בידיה רגלו מעל הקרקע ותחלוץ המנעל \u0010y53\u0011ויעמוד היבם אצל הכותל או אצל עמוד וישען עליו כדי שיוכל לדחוק רגליו בקרקע \u0010c23\u0011\u0010y54\u0011וכיצד הוא חליצת המנעל שתתיר היא קשירת המנעל בידה הימנית ותתפוש רגלו בידה השמאלית ותחלוץ המנעל בידה הימנית כדי שתהא התרה וחליצה בידה הימנית ר\"ת כתב שולפתה בימין ושמאל מסייעתה \u0010y55\u0011ובספר המצות כתב שצריך שיהא הכל בימין בלא סיוע השמאל ואם עשתה בשמאל או אפילו בשיניה כשרה \u0010y56\u0011וגדמת חולצת בשיניה לכתחילה \u0010y57\u0011התיר הוא הקשר ושמטה היא המנעל מרגלו או שהתירה היא ושמט הוא חליצתה פסולה עד שתתיר היא ותשמוט וכתב א\"א הרא\"ש ז\"ל הא דפסיל כשהתיר הוא דוקא שהוא בענין שלא היה יכול להלוך בו אם לא שהוא קשור לפי שהתרתו הוי כאילו שמטו כיון דסופו ליפול מעצמו אבל מנעל שיכול לעמוד ברגלו ולהלוך בו בלא קשירה וחלץ בו כשרה בדיעבד בלא קשירה \u0010y58\u0011לשון הרמב\"ם ינעץ בארץ רגלו והיא יושבת ופושטת ידה בב\"ד ומתרת רצועות המנעל וחולצת המנעל ומשלכת אותו לארץ ע\"כ. \u0010c24\u0011ואיני יודע למה כתב ויושבת והלא מצות חליצה מעומד ועיקר חליצה התרת המנעל וחליצתה ועוד למה הצריכה להשליכו לארץ \u0010c25\u0011\u0010y59\u0011אמר אמימר מאן דחליץ צריך למדחפיה לכרעיה פי' צריך לדחוק רגלו בארץ \u0010y60\u0011ופירש רב אלפס שאם לא עשה כן החליצה פסולה שהוא מדמה אותו לאידך דאמימר דאמר דמאן דמסני אלוחתא דכרעיה וחלץ חליצתו פסולה פירוש מי שרגליו הפוכות שכף רגלו למעלה ודורס על עליונו שפי' טעמא דלא חליץ מאן דמסגי אלוהתא דכרעיה משום דבעי למידחפיה אארעא וכיון דלא מצי למדחפיה לא חליץ \u0010y61\u0011וכן כתב הרמב\"ם היתה רגלו עקומה לאחור או הפוכה על צדה או שמהלך על אצבעות רגלו אינו חולץ שהחולץ צריך לנעוץ עקבו בקרקע וזה אינו יכול חלצה למי שהולך כך חליצתה פסולה \u0010y62\u0011והראב\"ד כתב שאין טעם שתי מימרות דאמימר אחד דטעמא דמאן דמסגי אלוחתא דכרעיה פסולה לפי שנעלו נחלצת מעל כף רגלו ולא מעל רגלו וגם כשהוא הולך ראש נעלו הולך למטה מרגלו אבל אי לא דחיף לכרעיה לא מיפסיל החליצה בהכי \u0010y63\u0011וכ\"כ א\"א הרא\"ש ז\"ל טעם שצריך לדחוק רגלו אינו אלא כדי שתהא טורחת לחלוץ רגלו דלפעמים מנעל של ב\"ד גדול ממדת רגלו ונראה כיוצא מאיליו אם לא ידחוק רגלו בקרקע \u0010c26\u0011\u0010y64\u0011חלצה מן הארכובה ולמטה חליצתה כשירה מן הארכובה ולמעלה חליצתה פסולה פירש רב אלפס דאקשירה קאי שאם יהיה הקשר למעלה מן הארכובה הרי החליצה פסולה \u0010y65\u0011וכן כתב הרמב\"ם ולדבריהם לא מצינו חליצה לקוטע אפילו נקטעה רגלו מן הארכובה ולמטה וכ\"כ בסה\"ת דקיטע פסול לחלוץ \u0010c27\u0011ור\"ח פירש דאנקטעה רגלו קאי שאם נקטעה מהארכובה ולמטה חולץ מהארכובה ולמעלה אינו חולץ ולזה הסכים א\"א הרא\"ש ז\"ל וכתב דוקא שישאר כל כך משוקו שיכול להכניס המנעל בשוקו ולקושרו למטה מן הארכובה אבל אם נחתך שוקו סמוך לארכובה שאינו יכול לקשור המנעל בשוקו אלא למעלה מהארכובה פסולה \u0010y66\u0011קרעה המנעל מעל רגלו או ששרפתו פסולה \u0010y67\u0011היה לבוש שני מנעלים זה על גב זה וחלצה שניהם כשירה קרעה העליון בענין שחלצה התחתון ונשאר העליון במקומה חליצתה פסולה \u0010c28\u0011\u0010y68\u0011ותרוק בארץ כנגד פניו רוק הנראה לדיינים כשיוצא מפיה \u0010y69\u0011כתב הרמב\"ם לא ראו הדיינים הרוק שיצא מפיה כשירה \u0010y70\u0011רקקה וקלטתו הרוח קודם שהגיע נגד פניו כגון שהיא ארוכה ממנו צריכה לרוק פעם אחרת אבל לאחר שהגיע הרוק כנגד פניו אפילו לא הגיע לארץ כשירה לפיכך אם הוא ארוך והיא קצרה קרינן ביה שפיר בפניו \u0010c29\u0011\u0010y71\u0011יבמה שרקקה דם אינה צריכה לרוק פעם אחרת וכתב רב אלפס דוקא במוצצת דאז אי אפשר לה בלא צחצוחי רוק אבל אם שותתת צריכה לרוק פעם אחרת \u0010y72\u0011אמר רבה יבמה שאכלה שום או גרגישתא וירקה לאו כלום הוא \u0010y73\u0011ורב אלפס לא הביא דברי רבה אולי רוצה לומר משום שאי אפשר בלא צחצוהי רוק שיוצא עם מה שאבלה ונהגו למונעה מלאכול כלום ע\"כ \u0010y74\u0011והרמב\"ם כתב אכלה שום וגרניר וכיוצא בו או מדברים המזיבין הרוק והיה רוק זב מפיה אינו כלום עד שיהיה הרוק מעצמה יראה מדבריו שאין לחוש אלא בדברים ידועים המזיבין הרוק \u0010y75\u0011ובספר התרומה כתב שצריך שלא תאכל כלום \u0010y76\u0011ואחר כך מקרין אותה ככה יעשה לאיש אשר לא יבנה את בית אחיו ונקרא שמו בישראל בית חלוץ הנעל \u0010y77\u0011ומצוה על כל העומדים שם לומר חלוץ הנעל שלשה פעמים \u0010y78\u0011נמצא סדר חליצה קוראה מאן יבמי וקורא לא חפצתי לקחתה וחולצת ורוקקת וקוראה ככה יעשה לאיש ואין הסדד מעכב שאפילו לא קראו תחילה לא היא ולא הוא או שהקדימה רקיקה לחליצה או שקראוה ואח\"כ רקקה חליצתה כשירה \u0010y79\u0011ולא עוד אלא אפי' לא קראה ולא רקקה אלא שחלצה בלבד החליצה כשירה. \u0010c30\u0011\u0010y80\u0011צריך שיכוונו היבם והיבמה שתהא מותרת לזר בחליצה זו נתכוין הוא ולא היא או היא ולא הוא לא הותרה ומיהו חליצה היא לפוסלה על האחין \u0010y81\u0011לפיכך יבמה שגדלה בין האחין וראינו שחלצה נעלו של אחד מהם אסורה להתייבם שמא כיוונו לשם חליצה אבל כל זמן שלא ראינו שחלצה לאחד מהם מותרת להתייבם ולא חיישינן שמא חלצה \u0010c31\u0011\u0010y82\u0011וכן אם \u0010y83\u0011רקקה לפני היבם בפני בית דין אסורה להתייבם ומיהו \u0010c32\u0011\u0010y84\u0011דוקא כשרקקה רוק אבל רקקה דם לפניו אינה נפסלת בכך אא\"כ יהא רוק מעורב בו \u0010y85\u0011ואם קראה לבד לא נפסלה בכך מלהתייבם \u0010y86\u0011הסומא לכתחילה לא יחלוץ ואם חלצה מהסומא חליצתה כשירה והראב\"ד כתב שאם אין אח אלא הוא חולצת לכתחילה \u0010y87\u0011חליצת \u0010c33\u0011חרש וחרשת ואלם ואלמת פסולה ופוסלת אבל שוטה וקטן אין חליצתם כלום אפי' לפסול על האחין \u0010y88\u0011קטנה שחלצה לגדול נפסלה על האחין \u0010c34\u0011\u0010y89\u0011וא\"א הרא\"ש זכרונו לברכה השוה חליצת קטנה לחליצת קטן \u0010y90\u0011חליצה מוטעת כשרה היכי דמי חליצה מוטעת שאומר לו חלוץ לה על מנת שתתן לך כך וכך החליצה כשרה \u0010y91\u0011אפי' אינה נותנת לו כלום ואע\"פ שהחליצה כשרה אף אם לא תתן לו \u0010y92\u0011מ\"מ היא חייבת ליתן לו מה שהתנה כשאר שוכר שכיר לעשות מלאכתו שצריך ליתן לו שכרו אבל אם יש טענה שאינה חפצה בו והוא חייב לחלוץ אלא שאינו רוצה וצריכים להטעותו כדי שיחלוץ לה יכולה לומר משטה אני בך ואינה צריכה ליתן לו כלום \u0010y93\u0011אמרו לו חלוץ לה ובכך אתה כונסה אינה חליצה להתירה כיון שלא כיון להתירה ומ\"מ נפסלה בכך להתייבם וכופין אותו לחלוץ חליצה כשרה \u0010y94\u0011חליצה מעושת שלא כדין ע\"י דייני ישראל שטעו וכפו לחלוץ פסולה ופוסלת ואם בדין כפו כשרה ועכו\"ם שכפו מעצמו אפילו כדין פסולה ופוסלת כפוהו שלא כדין אינו כלום אפילו לפוסלה כפוהו דייני ישראל על ידי עכו\"ם שכפוהו עכו\"ם לעשות מה שישראל אומרים לו כשרה והרמב\"ם כתב עכו\"ם שכפו מעצמן אם הדין שיחלוץ חליצתה כשרה ולא נהירא \u0010y95\u0011חליצה פסולה אע\"פ שהיא פסולה פוסלה על האחין ופוסל לכהונה ואוסרת עליו קרובותיה ואינה נישאת לזר עד שתחלוץ חליצה כשרה עכרה ונישאת לזר קודם שתחלוץ חולץ לה חליצה כשרה והיא תחת בעלה ואין מוציאין אותה ממנו: \u0010c35\u0011\u0010y96\u0011לאחר שחלצה כותבין לה ב\"ד שחלצה בפניהם גט חליצה להתירה לינשא ואם לא כתבוהו לה כל שנים שראו החליצה יכולין לכותבה אע\"פ שאינם מכירים לא היבם ולא היבמה שב\"ד לא היו חולצין להם אם לא שהיו מכירי' אותם \u0010y97\u0011וצריכין לשרטטו מפני מקראות שבו \u0010y98\u0011לשון א\"א הרא\"ש ז\"ל סידוד חליצה מצות חליצה בג' שיודעים להקרות ויקבעו דוכתא שאומרים נלך למקום פלוני ונחלוץ שם ומוסיפין עליהם עוד ב' אפילו עמי הארץ לפרסומי מילתא וחולצין ביום ולא בלילה בב\"ד של ישראל ולא בב\"ד של עכו\"ם וצריכים הדיינים שיכירו שהיא אשת המת והוא אחי המת מאביו והכרה זו סגי בקרובים ונשים וצריכים לידע שהיא בת י\"ב שנה ויום אחד והוא בן י\"ג שנה ויום אחד ושהביאו ב' שערות והיבמה נבדקת ע\"פ נשים ואם רואין שגדלו דדיה ושנתמלא זקנו אין צריכין בדיקה וצריך שישבו הדיינים והיבם והיבמה יעמדו וראיתי לרבותי שהעמידו היבם אצל הכותל או עמוד כי היכי דמצי למדחסיה לכרעיה ואומרים ליבם אם ירצה לייבם ואם אומר שרוצה לחלוץ אומרים לו בטל מודעא כמו בגט דחליצה מעושה פסולה ונותנים לו ב\"ד המנעל שיהא שלו \u0010y99\u0011ואחר החליצה יחזור ויתנהו לדיינים והמנעל צריך שיהא בו שתי רצועות לקושרו בהן על רגלו אע\"נ דאית ליה חומרתא כמין קשר עגול ומכניסו בחור של רצועה וצריך שיהיו כל תפירות המנעל ברצועות ולא בפשתן ונועלו ברגלו וקושרו ברצועות על רגלו בקשר ולא בעניבה וברגל של ימין ומקרין ליבמה בלשון הקודש מאן יבמי להקים לאחיו שם בישראל לא אבה יבמי מלה במלה זו אחר זו רק לא אבה יבמי יקראוה בפעם אחת ומקרין ליבם לא חפצתי לקחתה והיא מתרת בימינה קשר המנעל ושולפתו מעל רגלו בימינה וזורקה רוק מפיה לפניו וצריכים הדיינים לראות הרוק כשיוצא מפיה ולא תאכל היבמה כלום קודם חליצה ומקרין לה ככה יעשה לאיש אשר לא יבנה את בית אחיו ונקרא שמו בישראל בית חלוץ הנעל וכל הנמצאים שם אומרים חלוץ הנעל ג' פעמים ומשרטטים קלף וכותבין לה: \u0003ביום פלוני כך וכך לירח פלוני בשנת כך וכך לבריאת עולם למנין שאנו מונין בו כאן במקום פלוני אנחנא דייני דמקצתנא חתימי למטה במותב תלתא כחדא הוינא וסליקת קדמנא פלונית בת פלוני ארמלת פלוני בר פלוני והקריבה לקדמנא חד גברא דשמיה פב\"פ וכך אמרת לנא פליניתא דא פב\"פ דנא אחוהי דפלוני בעלי מאבוה הוא דהוינא נסיבא ליה ושכיב וחיי לרבנן ולכל ישראל שבק ובר וברת וירית ומחסין ומוקים שמו בישראל לא שבק והדין פלוני אחוהי חזר ליבומי יתי וכען רבנן דייני אמרו ליה אי צבי ליבומי יתי ייבם ואי לא ליטלע לי קדמיכון רגליה דימינא ואשרי מסאנא מעל רגליה וארוק באפוהי ואישתמודענוה לפלונית דא דהיא אנתתיה דפלוני מיתנא ואישתמודענוהו דפלוני דנא אחוהי דפלוני מאבוהי הוא ואמרינן ליה אי צבית ליבומי יתה ייבם ואי לא איטלע לה קדמנא רגלך ימינא ותשרי סינך מעל רגלך ותירוק באנפך ועני ואמר לנא לית אנא צבי ליבומי יתה מיד אקרינוה לפלונית דא מאן יבמי להקים לאחיו שם בישראל לא אבה יבמי ואף להאי פלוני אקרינא ליה לא חפצתי לקחתה ואטלע לה רגליה דימינא ושריא סיניה מעל רגלוהי ורקת באנפוהי רוקא דאיתחזי לנא בפומה על ארעא ותוב אקרינוה לפלונית דא ככה יעשה לאיש אשר לא יבנה את בית אחיו ונקרא שמו בישראל בית חלוץ הנעל ואנחנא דייני וכל דהוו יתבין תמן ענינא בתרה חלוץ הנעל תלתא זימנא ומדאיתעבידא עובדא דנא קדמנא שרינוה לפלונית דא למהך להתנסבא לכל גבר די תיצביין ואינש לא ימחה בידה מן יומא דנן ולעלם ובעת מיננא פלונית דא גיטא דחליצתא דנא וכתבנא וחתמנא ויהיבנא לה לזכות ולראיה כדת משה וישראל:\u0004 \u0010y100\u0011וחתמין עליה תלתא \u0010y101\u0011ולא בעיא לאמתוני לבתר חליצה תלתא ירחא אלא שריא לאלתר לאינסובי לכל מאן דבעיא:",["\u0003בא לחלוץ יועדו ג' דיינים:\u0004 ","\u0003ומ\"ש יועדו יתבאר בסמוך:\u0004 ומ\"ש ג' דיינים שמצות חליצה בג' דיינים משנה בר\"פ י\"ב דיבמות (דף קא.)","\u0003מ\"ש ישראלים הוא לאפוקי עכו\"ם כדבסמוך:\u0004 ","מ\"ש כשרים שלא יהיו קרובים זה לזה ולא ליבם וליבמה נראה דתרתי קתני חדא שיהיו כשרים דהיינו שלא יהא בהם שום פסול ועוד שלא יהיו קרובים זה לזה והטעם משום דחליצה היא דין כמו שיתבאר בס\"ד וכתוב בת\"ה סי' רכ\"ו דאפי' אם נשואים ב' בנות אחים או ב' בנות אחיות או אשה ובת אחותה יש להקפיד מפני מראית העין ורבותא זו היא לדעת הרא\"ש דסבר דלא אמרינן תרי בעל כאשתו אבל להרי\"ף דסבר דאמרינן תרי בעל כאשתו מדינא נמי פסולים וכתב בכתבי מה\"ר איסרלן בסי' רט\"ז דשני ושלישי שפיר דמי :","\u0003ומ\"ש ואפילו הם הדיוטות משנה ר\"פ י\"ב דיבמות (שם) מצות חליצה בג' דיינים אפילו שלשתן הדיוטות:\u0004 ","ומ\"ש רק שידעו להקרות את היבם ואת היבמה שם מצית חליצה בג' שיודעין להקרות כעין דיינים ופירש\"י שיודעין להקרות לא חפצתי לקחתה מאן יבמי ככה יעשה לאיש וכו' וכתבו התוספות שאפילו אינם בקיאים בשאר דברים שרי מאחר שבקיאים בקריאה וטעמא מפני שאר דברים אם לא עשו בטוב יוכלו לשאול לבקיאים ונראה מדבריהם דכי תנן הדיוטות הדיוטות ממש קאמר אבל בנ\"י כתוב בשם המפרשים דלא קרי להו הדיוטות אלא משום דלא בעינן סמוכים אבל צריך שידעו הלכות חליצה דכי קאמר בגמרא שיודעים להקרות כעין דיינים בכלל זה הלכות קריאה וחליצה שיודעים הדיינים ע\"כ. ודברי רבינו נראה שהן כדברי התוספות:","נמצא אחד מהן קרוב או פסול או גר ואפי' היה אביו גר ואמו מישראל פסול עד שיהא אביו ואמו מישראל פרק מצות חליצה (יבמות דף קב.) אמר רבא גר דן את חבירו דבר תורה ולענין חליצה עד שיהא אביו ואמו מישראל שנאמר ונקרא שמו בישראל ופירש\"י בישראל משמע שיהא ישראל מכל צדדין. וכך הם דברי הרמב\"ם ז\"ל שכתב בפ\"ד אם אחד מהג' גר פסול ואפי' היה אביו גר ואמו ישראלית לא תחלוץ עד שיהא אביו ואמו מישראל:","ומ\"ש רבי' בשם ספר המצות להכשיר אמו מגרים רק שיהא אביו מישראל כ\"כ התוס' שם משום דאפי' לענין יחס כהונה סגי באביו מישראל כדאמרי' בפ' י' יוחסין (קידושין עז:) וסמ\"ק והכל בו כתבו דאפילו היתה אמו לבדה מישראל כשר ע\"כ וט\"ס הוא וצריך להגיה אביו במקום אמו:","ומיהו חליצה פסולה מיהא הוי לפוסלה על האחין אפילו ביחיד אפילו בינו לבינה נמצאו עמי הארץ שאין יודעים אפי' להקרות החליצה כשרה כ\"כ הרמב\"ם בפ\"ד ויש לתמוה ע\"ז דכיון דאינם יודעים להקרות א\"כ לא קראו היבם והיבמה והיאך תהיה כשרה החליצה ואיפשר דהב\"ע כשהיבם והיבמה יודעים לקרות בעצמם מבלי שיקרא להם אחר א\"נ אפילו לא קראו כלל החליצה כשרה דיעבד כל שאינם חרשים או אלמים כמו שיתבאר:","ולכתחילה מצוה שיוסיפו שנים על הג' לפרסומי מילתא הכי איתא בפרק מצות חליצה שיחלצו בה' לפרסומי מילתא כלומר דאלו מדינא בג' סגי ואפילו לכתחלה חולצת בג' כדאמרינן התם בסוף פירקין ורבי' שכתב חלצו בג' חליצתן כשרה דמשמע דוקא בדיעבד איני יודע לו טעם ועוד שכבר כתב מצות חליצה בג' דיינים ופירש\"י לפרסומי מילתא דחלוצה היא ולא לינסבא לכהן א\"נ דליתי אינשי וליקפצו עלה. ומ\"ש ואפילו הן עמי הארץ כ\"כ הרמב\"ם ז\"ל ופשוט הוא וכתב נ\"י בשם הריטב\"א שאם הזמינו ג' לב\"ד בפירוש וקראו האחרים למילי בעלמא אפילו גרים ואפילו פסולים נמי ומיהו דייק מדברי הרמב\"ם ז\"ל שכתב אפי' עמי הארץ דפסולים לא וכ\"כ בהגהות וכן יש לדקדק מלשון רבינו וכן דעת ת\"ה ודחק דברי א\"ז שמכשיר פסולים בשנים ונ\"ל דהיינו לכתחלה אבל בדיעבד כיון שהג' המיוחדים לדיינים כשרים לא נפסלה החליצה מפני פסול השנים שהוסיפו וכתוב בת\"ה דקרובים קורבא שאינה פוסלת מן הדין מותר בשנים הנוספים. כתב ב\"ה צריכי למיתב ה' בההוא ב\"ד וכדכתבי גיטא לכתבו במותב תלתא כחדא הוינא וכן אמר רב צמח גאון זה פשוט דכיון דלכתחלה נמי חולצת בג' אין לכתוב אלא במותב תלתא הוינא שהשנים הנוספים אינם אלא לפרסומי מילתא:","ויקבעו מקום תחלה לומר נחלוץ במקום פלוני בפרק מצות חליצה (יבמות דף קא:) אמר רבא צריכי דיינים למקבע דוכתא שנאמר ועלתה יבמתו השערה ופירש\"י השערה מקום מזומן לכך משמע: וכתוב בת\"ה סי' רכ\"ו דשנים הנוספים לא צריכי למקבע דוכתא אבל בהגהות מרדכי כתוב ויאמרו הג' דיינים אל השנים נלך ונשב במקום פלוני וכ\"נ מדברי רבינו שכ' תוספת השנים קודם קביעות מקום ומצאתי כתוב בשם מה\"ר ישראל דיברונא דאע\"ג דכתב אשירי יקבעו דוכתא ויאמרו נלך במקום פלוני לחלוץ אין צריכים כולם לומר כן אלא החכם שבהם וכן משמע בגמרא דא\"ל רבא לרב פפא תא לזירזא דקני וכו' לא אשכחן שהם אמרו כלום אע\"ג דנקט לשון רבים ה\"נ נקט לקמן מקרין ליבמה אע\"ג דלא מקרי לה אלא אחד עכ\"ל ובהגהות מרדכי שכתבתי נראה שכל הג' צריכים לומר כן . ועוד מצאתי בשם מה\"ר ישראל דיברונא משמע דלקביעות מקום א\"צ לישב שם כלל אבל ראיתי רבותי שהלכו שם ואמרו בכאן נשב לחלוץ למחר אמנם בא\"ז משמע דאפילו הליכה כלל לא צריך רק אמירה בעלמא אכן נכון לעשות מעשה שתהא מוכח לשם מצוה עכ\"ל. וכתב אבי\"ה רבותי אומרים בההיא יומא ואני ראיתי לאבא מרי שקבע מקום בערב ביום שלפניו כך כתבו המרדכי ובהגהות מיימוניות ומשמע קצת מדברי בעל תרומת הדשן סימן רכ\"א דלא אמרינן דדוקא ערב יום שלפניו לאפוקי שחרית יום שלפניו דכל שקובעים ביום שלפניו ואפילו בשחרית שפיר דמי ומיהו דבריו נוטים דנכון לקבוע בערב דוקא ולי נראה דאין קפידא בדבר ואם באנו להקפיד בדבר איפשר דטפי עדיף קביעות בו ביום מקביעות יום שלפניו ואבי\"ה איפשר דה\"ק רבותי אומרים בההוא יומא כלומר דוקא בההוא יומא דמוכחי טפי וראיתי לאבא מרי שלא הקפיד בכך וקבע מקום מערב יום שלפניו . עוד מצאתי כתוב בשם מה\"ר ישראל מווירנא שאם אירע עיכוב שלא יוכלו לחלוץ באותו יום בטל קביעות הלילה וצריך לקבוע פעם שנית וכן שלישית ורביעית והן ראיתי רבותי עושים כן עכ\"ל עוד כתוב שם דנ\"ל דאפילו בלילה יכולים לזמן המקום דאין כאן משום תחילת דין אלא כאילו בונה מקום להיות מזומן לב\"ד. וכתוב בת\"ה סימן רכ\"א שאם החליצה ביום ראשון אין קובעין מקום ביום השבת משום דמחזי כבונה ומתקן אלא מע\"ש קובעים. ומ\"ש שאם קובעים מקום בשבת מיחזי כבונה ומתקן אין לו טעם כתוב בספר התרומה ובהגהות מרדכי בשם סיפרי שהמקום שיקבעו לחלוץ שם צריך שיהיה בגובה של עיר ויליף לה מדכתיב ועלתה ובהגהות מרדכי פי' בגובה של עיר כלומר מקום מפורסם:","כתב הרמב\"ם ז\"ל צריכים הדיינים לקבוע מקום וכולי לא נועדו ולא קבעו מקום חליצתה כשרה בפ\"ד אין חליצה כשרה אלא ביום חלצה בלילה חליצתה פסולה אע\"ג דתנן בפרק מצות חליצה (יבמות דף קד.) חלצה בלילה חליצתה כשרה רבי אליעזר פוסל בההוא עובדא דמייתי התם (שם) דחלץ במוק ביחיד ובלילה אמרינן בשינוייא בתרא דכולהו נמי יחידאה קתני להו ופסקו הרי\"ף והרא\"ש ז\"ל כההוא שינוייא למימרא דחליצה בלילה פסולה וכ\"פ הרמב\"ם ז\"ל וטעמא מפרש בגמרא משום דחליצה הוי כתחלת דין זה ואין דנין בלילה ופי' נמוקי יוסף דחליצה דיני ממונות היא שגובה כתובתה בפ' משילין (ביצה לו:) תנן אין חולצין בשבתות ולא בימים טובים ומיהו בחול המועד שפיר דמי דהא תניא בפ' א\"מ (יד:) דנין דיני נפשות ודיני ממונות במועד כתוב בתרומת הדשן סימן רכ\"ז שאין חולצין בערבי שבתות וימים טובים ונ\"ל שאין לדבר זה עיקר:","וצריך שיכירו אותו שאומר שהוא היבם שהוא אחי המת ושהי' בעולמו וזאת היא אשת המת בפ' החולץ (יבמות דף לח:) אמרי' ואשתמודענוהו דאחוה דמיתנא הוא ובס\"פ מצות חליצה (יבמות דף קו) אסקינן אין חולצין אא\"כ מכירין ורבינו ירוחם כתב שה\"ר אברהם בן אשמעאל השיב שא\"צ שיכירו שזאת הא אשת המת והוא הסכים לדעת האומרים שצריך וכ\"כ הרמ\"ה וכ\"כ הרמב\"ם ז\"ל וכ\"כ הרא\"ש בסדר חליצה שלו וכן נראה מדברי הרי\"ף:","ומ\"ש ואפילו אין כאן אלא ע\"א שמעיד עליהם שפיר דמי ואפי' עבד או שפחה בפרק החולץ אסיקנא דאפילו אשה או קרוב מהימני משום דלא אמילתא דאיסורא ולא אממונא קא מסהדי אלא גילוי מילתא בעלמא הוא דהאי גברא הוא פלוני והא איתתא איהי פלוניתא וכמו שכתבו שם הרי\"ף והרא\"ה ז\"ל והרמב\"ם ז\"ל כתב דה\"ה עבד או קטן שהוא מכיר ונבון נאמן בכך ועי' במה שאכתוב לקמן בסימן זה ובמה שכתבתי בסימן קנ\"ז ונראה שגם להעיד שהיה להם ישיבה אחת בעולם סגי בחד מהני דהא נמי גילוי מילתא הוא וכן משמע מדברי רבינו ומדברי סמ\"ק:","וצריך שידעו הדיינים שיש שלשה חדשים ממיתת הבעל כ\"כ ספר התרומה וסמ\"ק וטעמא משום דתנן בפרק החולץ (יבמות דף מא.) היבמה לא תחלוץ ולא תתייבם עד שיהיו לה ג' חדשים כלומר דתוך ג' חדשים איכא למיחש שמא מעוברת היא ואסיקנא בר\"פ החולץ (יבמות לה:) דהלכה כר\"ל דאמר חליצת מעוברת לא שמה חליצה וכמו שנתבאר בסימן קס\"ד ונראה דגם בזה מהני עדות אשה או קרוב דגילוי מילתא בעלמא הוא:","ויבדקו היבם והיבמה אם הביאו ב' שערות ואם הוא בן י\"ג שנים ויום אחד טעמא משום דחליצת קטן או קטנה פסולים כדתנן בפרק מצות חליצה (יבמות דף קד.) החולצת לקטן חליצתה פסולה קטנה שחלצה תחלוץ משתגדיל ואם לא חלצה חליצתה פסולה ואסיקנא דאינה חולצת עד שתביא שתי שערות ויש קיצור בדברי רבינו דהוה ליה למיכתב שצריך גם כן שידעו אם היבמה בת י\"ב שנה ויום אחד משפט ב' שערות נתבאר יפה בסימן קנ\"ה ובסימן קס\"ז:","ומ\"ש והיא נבדקת ע\"פ נשים נתבאר ג\"כ בסי' קנ\"ה כתבו התוס' בפרק בא סימן (נדה מט.) ד\"ה ואבע\"א יבם קטן או קטנה שבאו לחלוץ טוב לכתחלה לבדקם לפני הפרק אם יש להם שתי שערות וכן לאחר הפרק ואם הן אותן שהביאו קודם נמתין עד שיביאו שערות אחרות אבל יבם גדול ויבמה גדולה דלא איפשר עוד לברר חלצה שפיר אם יש להם שערות ולא חיישינן שמא לפני הפרק באו עכ\"ל וכן נתבאר בדברי רבי' בסי' קנ\"ה וסימן קס\"ז:","ומ\"ש ואם רואים שגדלו דדיה ושנתמלא זקנו אין צריך לבדוק יותר כ\"כ הרא\"ש ז\"ל בסדר החליצה שכתב בס\"פ מצות חליצה גם הרשב\"א כתב בתשו' אפי' בסי' העליון די כלומר אם יש לה דדים וז\"ל ספר התרומה אם ירצה יבדוק האשה בדדין אם הטו הדדין גדולה היא ומסתמא יש לה שערות כדתנן בפ' בא סי' שזהו סי' העליון וא\"א לבא העליון עד שיבא התחתון ע\"כ וכך כתבו התוס' בפרק בא סימן וז\"ל ואם יש ליבמה דדים גדולים א\"צ לבדוק אחר השערות דהא אמרי' לעיל אי אפשר שיבא העליון עד שיבא התחתון:","ומ\"ש שאם רואים שנתמלא זקנו א\"צ לבדוק יותר בס\"פ הערל (יבמות דף פ) כתבו התוס' אומר ר\"י דאין חשוב בהבאת ב' שערות לבד יש לו זקן אא\"כ נתמלא זקנו:","\u0003כתב הרמב\"ם ז\"ל אין סומכין במנין השנים לא ע\"פ קרובים וכו'\u0004 בפ\"ב מהלכות אישות וכתב ה\"ה ז\"ל זה נלמד מהסוגיא שבפרק האומר בקידושין (סג.) דמשמע מיניה דעדות בעינן יתבאר בסמוך שאפילו האב אינו נאמן לכל דבר עכ\"ל וכ\"כ המרדכי בפרק מצות חליצה בשם כמה גדולים וכתב דאין להביא ראיה מאשתמודענוהו דפרק החולץ דהתם גילוי מילתא בעלמא הוא דבלאו הכי תופסים אותו בחזקת אחיו מן האב אבל אם לא היינו מוחזקים בו שהוא אחיו מן האב והביא קרובים לעדות הא לא הוי גילוי מילתא וכל שכן הכא שהיינו מוחזקים בו בחזקת קטן אין הקרובים נאמנים להוציאו מאותה חזקה ומ\"ש ר\"ת כל אשה שהגיעה לכלל שנותיה והוחזקה לסי' ע\"פ שכנותיה לא צריכה בדיקה י\"ל דוקא גבי אשה אבל גבי איש לא משום שיש בני אדם שנוהגים לקרות בניהם לס\"ת כשנכנסים לתוך י\"ג וגם כשהקטן עושה מעצמו אין מוחים בו ונותנים לו לברך ויורד לפני התיבה ומתפלל ואין חוששין הלכך כל הני לא הוי חזקה וע\"כ צריך עדות ברורה על מספר שניו להחזיקו בגדול וגם צריך לבדקו וגם היתר יבמה לשוק היא ערוה כדאמר בפרק האשה רבה (יבמות צב:) בעניותינו צריכה גט מספק והולד ספק ממזר ואין דבר שבערוה פחות משנים ורבינו יואל כתב אב שמעיד על בנו שהוא בן י\"ג שנים ויום אחד כדי שיהא ראוי לחליצה ולהתיר יבמה לשוק אינו נאמן אם לא יצטרף אחר עמו כמו שאר עריות וכגון שאין קרוב ליבמה ואח\"כ כתב ומיהו בספר התרומה פסק דאם יש להם ריבוי שערות או ארוכות כמו שיש לאיש ולאשה גדולים מותרת לחלוץ דמסתמא הגיע לכלל שנות הגדולות או אם יש קול [בדבר] שהחזיקו השכנים (בבגרות) שלא ע\"פ האב שיש לאיש י\"ג שנים ויום אחד ולאשה י\"ב שנים ויום אחד סגי בכך להחזיקם בגדולים על השערות שאנו רואים וא\"צ עדות על הלידה וראבי\"ה כתב נראים הדברים כשיש לו הכרת זקן סגי עכ\"ל:","\u0003ובסה\"ת כתב אם אין השנים ידועות אלא ע\"פ האב וכו'\u0004 אינו נאמן להחזיקו בגדול אבל במקום שהוא דר והוחזק בעיני השכנים שלא ע\"פ האב שבא לכלל שנים או שיצא עליו קול שבא לכלל שנים נאמנים להחזיקו בגדול וכולי ז\"ל סה\"ת אומר מורי ריב\"ש דאין האב והאם נאמנים כדתניא פרק האומר בקידושין (סג:) נאמן האב לומר על בנו בני זה יש לו י\"ג שנים ויום אחד ובתי זו בת שנים עשר שנים ויום אחד לנדרים ולערכין ולהקדשות אבל לא למכות ולעונשין ומסתמא כמו שאין נאמן למכות ועונשים ה\"ה לחליצה דהוי דבר שבערוה אינו נאמן ואפי' ראינו שעמד להתפלל והשלים לי' בב\"ה אין בכך כלום דשמא על פי האב עשו שנאמנים לנדרים והקדשות מיהו ברייתא מיתוקמא במקום שלא הוחזקו ע\"י שכנים שלא נולדו באותו מקום שאין אנו יודעים כי אם ע\"פ האב אבל אם הוחזקו שהגיעו לכלל שנים אז יועילו השערות שהרי הוחזקה נדה בשכנותיה (כתובות עב.) בעלה לוקה עליה עכ\"ל ומ\"ש ואפילו בלא חזקת השכנים אם יש להם ריבוי שערות או שהן ארוכות חזקה שבאו לכלל שנים ג\"ז בסה\"ת וז\"ל הילכך אם יש להם ריביי שערות ארוכות הרבה או ריבוי שערות כמו שרגילות לאיש גדול ולאשה גדולה אז מותרת לחלוץ דמסתמא הגיעו לכלל שנת גדלות עכ\"ל. וז\"ל התוס' בקידושין פרק האומר אהא דתניא דאין האב נאמן לומר בני זה בן י\"ג שנה ויום אחד למכות ולעונשין פירש רש\"י דמיירי שהביא שתי שערות ואפ\"ה צריכין אנו לידע שנותיו וקשה דא\"כ כל הנשים הבאות לפנינו לחלוץ היאך יחלוצו אע\"פ שיש להם סימנים כיון שאין אנו יודעים שנותיהם לא מהני ואומר ר\"י דאי איכא ריבוי שערות סמכינן אריבוי שערות דאין דרכם לבא קודם י\"ג שנה אי נמי אם הם גדולים בקומה יש לסמוך על הסימנים והקומה ואפ' אין לו כ\"א ב' שערות אבל הכא מיירי שלא הביא רק ב' שערות ולא הגדיל בקומה עכ\"ל :","\u0003ומ\"ש ועל זה סומכין שא\"צ לבדוק אם יש בו גומות וכו':\u0004 ","ומ\"ש וישבו הדיינים כמו שצריכין לישב בדין כ\"כ הרא\"ש בסדר החליצה וכ\"כ בסה\"ת ויעמדו לפניהם היבם והיבמה שמצות חליצה מעומד לא עמדו אלא חלצו מוטים אין יושבים חליצתם כשרה ובפרק מצות חליצה (יבמות דף קג:) תניא דחליצה כשרה בין עומד בין יושב בין מוטה וכתבו התוס' והרא\"ש ואע\"ג דכתיב ועמד ואמר אין עמידה מעכבת מדלא כתיב ויעמוד ויאמר אבל ועמד ואמר סיפור דברים בעלמא הוא והכי מפרש במ\"ק (כא.) גבי קריעה והא דדריש בסיפרי ועמד ואמר אין דברים הללו אלא בעמידה אסמכתא בעלמא היא ולכתחלה בעי' עמידה משום דדמיא לגמר דין כדאמרינן לקמן עכ\"ל וכן כתב בסה\"ת וסמ\"ג והרמב\"ם כתב יושבת וחולצת המנעל וכו' ועומדת ורוקקת בארץ כנגד פניו וכו' שמצות חליצה שיהיו עומדים בשעת קריאה ובשעת רקיקה כתב ה\"ה מ\"ש רבינו שמצוה שיהיו עומדים בשעת רקיקה ובשעת קריאה הוא מן הברייתא השנויה בספרי ועמד ואמר מלמד שאין אומרים דברים אלו אלא בעמידה ורקיקה סובר רבינו דכיון דאמר רבא דצריכי דייני למיחזי רוקא כי נפיק מפומה דכתיב לעיני וירקה הרי הוא כדין וצריכים לעמוד לכתחלה אבל החליצה אפילו לכתחלה מיושב כמ\"ש רבינו וכתב הרשב\"א שכן מוכיח בגמרא דאפי' לכתחלה מיושב ואף רקיקה מסתפק הוא וז\"ל למה הצריכה רבינו מעומד ויש מן המפרשים סוברים שהכל לכתחלה מעומד וכן נהגו עכ\"ל וכתוב בכתבי מה\"ר איסרלן סימן ק\"צ דחולה שלא היה לה כח לעמוד וחלצה מיושבת פשיטא דכשרה לכתחלה וראיה מבתי עמודי לחד פירש\"י ועוד דכל דבר שאין לו תקנה חשיב דיעבד כפר\"י פ' כ\"ש (ל. ד\"ה לשהינהו) אההיא דקדרות בפסח:","וישאלוהו אם ירצה לייבם או לחלוץ כ\"כ בסה\"ת יאמרו לו אי ניחא לך יבם אי ניחא לך לחלוץ וכ\"כ הרא\"ש בסדר חליצה וטעמם מדאמרי' בפרק החולץ דכי אתו לקמיה דרב יהודה אמר להו הכי וסמ\"ג כתב דלכל הפירושים אין אומרים אי ניחא לך יבם אא\"כ חפצה ולא כמו שכתוב בסה\"ת שלעולם אומרים אותו :","ואם יאמר שרוצה לחלוץ יאמרו לו לבטל כל מודעות שמסר (כמו) גבי גט שאם מסר מודעא תחלה החליצה פסולה כן כתב הרמב\"ם וסמ\"ג והרא\"ש בסדר החליצה וכתב ה\"ה שטעמו מדאמרינן ס\"פ מצות חליצה חליצה מעושית וגט מעושה זימנין כשר וזימנין פסול הא דאמר רוצה אני הא דלא אמר רוצה אני והביאו שם מתני' דערכין (כא.) דקתני וכן אתה אומר בגיטי נשים כופין אותו עד שיאמר רוצה אני ועל זו המשנה אמר רב ששת האי מאן דמסר מודעא אגיטא מודעיה מודעא וממה שהשוו החליצה לגט כתב רבי' שאף בחליצה נכון הוא למסור מודעא וכתב דין העשוי כדין ושלא כדין והחילוק שיש בין ישראל לעכו\"ם על הדרך שכתב פרק ב' מה' גירושין כדין הגט עכ\"ל ובסימן זה לקמן כתב רבי' דין חליצה מעושית:","מי שכופין אותו לחלוץ בדין ומסר מודעא תחלה ולא בטלה משמתינן ליה לטעמיה אזיל שכ' בסימן קל\"ד מי שכופין אותו לגרש בדין אם מסר מודעא תחלה כדי לבטלו משמתינן ליה וכבר כתבתי שם שיש לתמוה עליו:","ויתנו לו מנעל החליצה במתנה שצריך שיהיה שלו כ\"כ סה\"ת והרא\"ש ז\"ל בסדר החליצה וטעמם מדאמרינן בפ' מצות חליצה (יבמות דף קא) במתני' דחלצה בסנדל שאינו שלו חליצתה כשרה ובגמ' (קג:) אביי הוה יתיב קמי' דרב יוסף א\"ל הב לי סנדלך יהיב ליה סנדלא דשמאלא א\"ל אימור דאמור רבנן בדיעבד לכתחלה מי אמור א\"ל אי הכי סנדל שאינו שלו נמי אימור דאמור רבנן דיעבד לכתחלה מי אמור א\"ל הכי קאמינא לך הב ליה ואקני ליה ופירש\"י הב ליה ואקני ליה שיהא שלו במתנה ע\"כ כלומר שיאמר לו בהדיא אני נותן לך במתנה ואע\"פ שכתוב בהגהות מרדכי דהיינו דוקא במנעל שאינו מיוחד לכך אבל אם הוא מיוחד לכך א\"צ להקנותו שאר פוסקים לא חלקו בכך ומ\"ש אע\"פ שמחזירו אח\"כ קרינן ביה שפיר שלו כלומר אע\"ג דמסתמא אין נותנים המנעל ליבם אלא על דעת שיחזירנו אח\"כ חשיב שפיר שלו דמתנה ע\"מ להחויר שמה מתנה.","ומ\"ש שי\"א שצריך שיהלך בו מעט כדי שיהא נראה כשלו כ\"כ בהגמ\"ר סוף פרק החולץ ובמרדכי פרק מ\"ח כתוב שיהלך בו שעה אחת ומ\"ש ואם לא נתנוהו לו כשר כבר כתבתי דמתני' היא חלצה בסנדל שאינו שלו חליצתה כשרה כתוב בא\"ח צריך שיעבור החולץ בפני הדיינים מרוח לרוח עד שיראו באיזה רגל יפסיע תחלה לפי שהרגל המפסיע תחלה הוא של ימין ובו חולץ וגם מצריך לבדוק באשה אם היא אטרת עכ\"ל:","והמנעל צריך שיהיה כולו עור לפיכך צריך לתופרו בפמ\"ח (דף קב:) א\"ר יהודה א\"ר סנדל התפור בפשתן אין חולצין בו שנאמר ואנעלך תחש ופירש\"י התפור בפשתן שתפור בתוכו בגד פשתן ל\"א התפור בפשתן שתפרו במשיחה כעין שלנו וכתב הרא\"ש ז\"ל דלשון שני עיקר דהיינו דתפרו במשיחה כעין שלנו דבעי' כוליה עור וכתב נראה דאין חולצין בו לכתחלה קאמר דדרשא דתחש אסמכתא בעלמא היא. ורבינו כתב לקמן בסמוך דהרמ\"ה פוסל אפי' בדיעבד :","ומ\"ש אבל רצועותיו אין צריך שיהיו מעור שם בעא מיניה ר\"א מרב הוא של עור ותרסיותיו של שער מהו א\"ל מי לא קרית ביה ואנעלך תחש אי הכי אפי' כולו שער נמי ההוא קורקא מיקרי ופירש\"י תרסיותיו רצועותיו ולכאורה משמע דדוקא בתרסיות של שער הוא דקרינן ביה ואנעלך תחש משום דדבר הבא מן העור הוא אבל אם הם מדבר שאינו בא מן העור לא וזה דעת נ\"י שכתב מיתנא של עור או של שער אבל לא של דבר אחר כדאיתא לקמן עכ\"ל אבל רבינו נראה שאינו סובר הכי אלא מכל דבר נמי כשרות ולפיכך סתם וכת' רצועותיו א\"צ שיהיו מעור ולפ\"ז צ\"ל דשל שער לאו דוקא אלא אורחא דמילתא נקט:","וכתוב בספר המצות צריך שיהיה העור קשה קצת שיהיה דומה קצת לסנדל שמן הדין לא היה ראוי לחלוץ אלא בסנדל אלא שאינו מצוי לכך צריך שיהיה דומה קצת לסנדל בפ' מצות חליצה (שם) אמר רבא א\"ר כהנא א\"ר אם יבא אליהו ויאמר חולצין במנעל שומעין לו אין חולצין בסנדל אין שומעין לו שכבר נהגו העם בסנדל ורב יוסף א\"ר כהנא א\"ר אם יבא אליהו ויאמר אין חולצין במנעל שומעין לו אין חולצין בסנדל אין שומעין לו שכבר נהגו העם בסנדל מאי בינייהו א\"ב מנעל לכתחלה ופירש\"י דללישנא קמא אין חולצין במנעל לכתחלה דמדקאמר אם יבא אליהו וכו' משמע דכל כמה דלא אתי אליהו ואמר לא חולצין אלמא מנעל לכתחלה לא והרי\"ף והרא\"ש ז\"ל כתבו כי האי לישנא וגם שאר פוסקים נראה שתופסים לשון זה עיקר זולתי הרמב\"ם ז\"ל לאחת מהדרכים שאכתוב בו בס\"ד וטעם הפוסקים שתפסו האי לישנא עיקר אע\"ג דללישנא קמא הוא היינו משום דמתני' דקתני חלצה במנעל חליצתה כשרה אתיא שפיר לדידיה דמשמע דיעבד אין לכתחלה לא ואידך לישנא צריך לשנויי בדוחק כדאיתא בגמרא א\"נ משום דאמרינן בגמרא (שם) דמנעל לכתחלה תנאי היא דר' יוסי אמר מה ראה ר\"מ לומר חלצה במנעל חליצתה כשרה ורבי יעקב אומר משמו של רבי מאיר חולצין במנעל לכתחלה והלכה כר' יוסי דאמר דר\"מ לא מכשיר במנעל אלא דיעבד ואין לומר א\"כ אפי' בדיעבד תהא פסולה דהכי משמע דס\"ל לר' יוסי כדמוכח מדקאמר מה ראה ר\"מ לומר חליצתה כשרה דכיון דלא חלק רבי יוסי בהדיא אלא מתמה ואמר מה ראה ר\"מ לומר וכו' לא שבקינן מאי דפשיטא ליה לר\"מ משום מאי דמתמה רבי יוסי ותלמודא נמי משמע דהכי ס\"ל דקאמר תנאי היא דלר\"מ אליבא דר' יוסי חליצה כשרה היא בדיעבד דוקא ואליבא דרבי יעקב לכתחלה נמי ולא אשכחן אמורא דס\"ל דאפי' דיעבד חליצתה פסולה אלמא דר\"י ודאי לא חלק על ר\"מ ולית לן לספוקי אלא אי ס\"ל לר\"מ חליצתה כשרה או אי ס\"ל חולצין לכתחלה וכר' יוסי נקטינן לר\"מ דיעבד כשרה אבל לא לכתחלה ולענין חילוק שבין מנעל לסנדל רש\"י פי' במתני' קמייתא דפרק מ\"ח (קא.) דסנדל הוא של עור קשה ומבושל ונ\"י כתב בשם הרבה מהמפרשים דסנדל כולו מחתיכה אחת מה שעל גבי הרגל והשואיל\"ה תחת הרגל וכתב הריטב\"א וראוי לחוש לשניהם עוד מצינו חילוק אחר בין מנעל לסנדל דאמרינן בפרק במה אשה (שבת ס:) שאם תפרו מבפנים הוי מנעל ולא סנדל ופירש\"י דהיינו שנתן העור לפנים מן הסנדל ותפרו ומדברי סמ\"ג וסמ\"ק נראה דתפרו מבפנים היינו שאם תפירותיו לצד פנים הוי מנעל ואם תפירותיו לצד חוץ הוי סנדל וטעמא דאין חולצין לכתחלה במנעל מפרש בגמרא (קב.) גזירה משום מנעל המרופט אי נמי משום חצי מנעל. ופירש\"י מרופט מבוקע קרוע מלמעלה דכיון דרכיך אף ע\"ג דקרוע מייתב אכרעיה אבל סנדל שהוא קשה אין יכול ליישבו על רגלו משנפחת וליכא למיגזר מידי עכ\"ל. ועפ\"ז יתפרש משום חצי מנעל דאם נתאכל חצי המנעל יכול לישבו ברגלו ואם נתאכל חצי הסנדל א\"א לישבו ברגלו ולדברי המפרשים דסנדל היא מחתיכה אחת יש לפרש דמרופט קרוע והילכך מנעל שהוא מב' וג' חתיכות איכא למיחש שמא יקרע ולאו אדעתיה ונמצא שאינו חופה את רוב רגלו ופסולה אבל סנדל שכולו חתיכה אחת ליכא למיחש להכי וכעין זה יש לפרש בחצי מנעל דחיישינן שמא תינטל חתיכה אחת ולאו אדעתיה או לא יקפיד עליה אבל בסנדל שכולו חתיכה אחת ליכא למיחש להכי והיכא דלא שכיח סנדל כתבו העיטור והרא\"ש ז\"ל דחולצין במנעל והביאו ראיה מהירושלמי וכ\"כ נ\"י בשם התוס' וכ\"כ סמ\"ג ור\"י ז\"ל. ואיפשר שזה היה דעת הרמב\"ם ז\"ל שכתב כיצד חולצין מביאין לו מנעל של עור וכו' ולא הזכיר חליצת סנדל לפי שאינו מצוי בינינו אי נמי דס\"ל דהילכתא כלישנא בתרא דחולצין לכתחלה אי משום דבכל דוכתא קי\"ל כלישנא בתרא ואי משום דרבי יוסי פליג ארבי יעקב ליכא לאכרועי מידי דכיון דר\"י לא קאמר סברא דנפשיה אלא משמיה דר\"מ קאמר לה בטיל ליה כללא דהלכה כרבי יוסי דאיכא למימר דרבי אף ע\"ג דלא חשיב כוותיה הוה דייק טפי אי נמי הוה בחזרה וכיון דלישנא בתרא כרבי יעקב הכי נקטינן. ואף על פי שכתב נ\"י שהרמב\"ן ז\"ל דחה ראיית הירושלמי וכתב דאדרבא משם ראיה דאפי' לא היה מצוי סנדל אין חולצין במנעל לכתחלה כבר נתבאר שדעת כל הפוסקים אינו כן אלא דכיון דאין סנדל מצוי בינינו חולצין במנעל לכתחלה והרמב\"ן נמי אפשר דלהלכה אמרה ולא למעשה ואף על פי שעכשיו אנו חולצין במנעל לכתחלה לפי שאין סנדל מצוי בינינו כתבו קצת מהפוסקים שצריך לעשות המנעל שידמה לסנדל בכל מאי דאיפשר וזהו שכתב רבי' בשם סמ\"ק שיהא העור קשה קצת שיהא דומה קצת לסנדל וכ\"פ הגה\"מ והגהות מרדכי בשם סמ\"ק ונ\"י בשם הריטב\"א ז\"ל וגם לתנאי השני של סנדל דהיינו שלא יתפרנו מבפנים חששו קצת מהפוסקים שכתבו סמ\"ג וסמ\"ק וכתבו הגה\"מ והמרדכי בשמם שהתפירה תהיה מבחוץ ולא מבפנים כדי שיהא דומה לסנדל וגם רבינו כתב כן בסמוך. וגם לתנאי הראשון של סנדל לפי דעת קצת מפרשים חששו קצת שכתב נ\"י בשם הריטב\"א ז\"ל שצריך לעשותו מחתיכה אחת וכן נמצא בתשובת הרשב\"א ז\"ל שהעתיקו הקונדרס צורת המנעל כצורת בית רגל שעושין מן הבגד לבתי שוקים אלא שהעקב הוא עור שלם והכל הוא עור אחד ותפירתו מן הצד במקום אחד וכן הוא תפור למטה בצד הרגלים ואין למנעל צורת כף רגל שקורין שול\"א אלא כעין בית רגל שעושים לבתי שוקים שלנו עכ\"ל ונראה שביאור דבריו הוא שלא יהיו בו אלא ב' תפירות אחת בגב המנעל מן הצד והיא קצרה כי אינה רק משפת המנעל ועד השואיל\"ה ויש לו תפירה שנית ארכה לאורך המנעל מראשו לסופו אלא שתפירה זו איפשר לעשותו בא' מב' פנים האחד שמגב המנעל ירד העור שלם ויכפל תחת המנעל לשואיל\"ה עד קצת השני של גב המנעל ויתפור שם לאורך המנעל שנמצא לפי זה השואיל\"ה שלימה ואינה תפורה אלא מן הצד וגם קצת תפירות בצד החד של המנעל וכן לצד אחוריו. הדרך השני שהתפירה הארוכה הזאת תהיה באמצע השואיל\"ה כעין קצת בתי רגלים שקורין פיאלי\"ש ואם כוונתו ז\"ל לדרך הראשון מ\"ש שהעקב הוא עור שלם עקב הוא השואיל\"ה: ומ\"ש וכן הוא תפור למטה בצד הרגלים היינו לומר שהוא תפור למטה ברגלים מן הצד ולא באמצע: ומ\"ש ואין למנעל צורת כף רגל היינו לומר שמתוך שבצדו אחד אינו תפור אלא שהוא יורד ונכפל למטה נמצא שאין לו צורת כף רגל ואם כוונתו לדרך השני מה שכתב שהעקב הוא עור שלם האי עקב לאו היינו שואיל\"ה אלא עקב שקורין טאלי\"ן: ומ\"ש והוא תפור למטה בצד הרגלים היינו לומר שהוא תפור באמצע השואיל\"ה אע\"פ שמלת בצד אינו מכוון כל כך לדרך זה מה שכתבו ואין למנעל צורת כף רגל אתי שפיר טפי לדרך זה שמתוך שהוא תפור באמצע אין לו צורת כף רגל והעידו לפני שפעם אחד הובא לב\"ד הרב מה\"ר אליהו המזרחי ז\"ל כמה מנעלי חליצה וכולם היו תפורים באמצע השואיל\"ה וכתב בתשובות הרשב\"א לענין סנדל חליצה שאמרו לך משמי שאם היה החלק תחתון הדבוק לארץ חלח בפני עצמו שהוא פסול אני לא כך אמרתי אלא מכלל מה שנהגתי אמר כן מי שאמרה בשמי שאני הנהגתי לרווחא דמילתא בסנדל דטייעי כדאמר רב (שם) אי לאו דחזיתה לחביבי כו' ופי' הרי\"ף כגון האי דקרו ליה ישמעאלים תאסומא וכו' וחכם אחד מזקני צרפת אמר לנו צורת אותו סנדל שכתב הרב ז\"ל וקורין אותו תאסומ\"א ועל פיו עשינו אותו והנהגתי לחלוץ ולא לפסול סנדל אחר שהנהגתם בו אתם עכ\"ל. וגם רבינו ירוחם כתב שראה שרוב העולם נוהגין לעשותו מחתיכה א' ושאין חשש בזה ע\"כ. ויש שהפריזו על מדותיהם שגם הרצועות התלויות בו והרצועה שתפרו בו הכל חתיכה אחת שכתב נ\"י בשם הריטב\"א שמעתי מפי מורי הר\"ם כי הסנדל שהיו נוהגים חכמי נרבונא הובאה לפני רבינו רבו ז\"ל לצורך חליצה והיו הרצועות מגוף המנעל ואינם תפורות שם וגם הרצועה שתפרוהו בו היתה מקוצה ממנו כדי שתהא כל הסנדל עור אחד ונראה שכל זה חומרא יתירה דעד כאן לא אסתפק לן לקמן אלא בתרסיותיו של שער והנהו מסתמא אינם מגופו אלמא דכוותה של עור כשרים בלא ספק ובשל שער נמי איפשיטא לן בתפירה נמי דוקא בחוט של פשתן אסרו הא של עור דומיא דפשתן שאינו מעצמו שרי ואריך ואין בזה בית מיחוש ומיהו ראוי לחוש לדבר למעשה כל מאי דאפשר עכ\"ל ועוד נראה לי דבהדיא אשכחן שלא היו נוהגים בימי חכמי התלמוד שיהיו הרצועות מגוף הסנדל דהא אסיקנא בפרק מצות חליצה והאי דידן אף על גב דאית בה חומרתא קטרינן ביה מיתנא וקטרינן היינו קושרים אלמא דלכתחלה קושרין בו רצועה שאינה מגוף הסנדל ואם כן אנן מהי תיתי לן לחומרא כיון שאין לה על מה לסמוך :","ומאיזה עור שיהיה הסנדל שפיר דמי ולא כדברי ר\"ת שכתב שצריך שיהיה עור בהמה טהורה דוקא התוס' כתבו בפרק מ\"ח (קב: ד\"ה ואנעלך) שטעמו של ר\"ת מדאמרינן בההוא פירקא דסנדל התפור בפשתן אין חולצין בו שנאמר ואנעלך תחש ובפרק במה מדליקין (שבת כח:) אמרינן דתחש טהור הוא וכתבו עליו שאין נראה כי אין להקפיד אם חלץ במנעל בהמה טמאה והרא\"ש ג\"כ חלק על רבינו תם וכתב עליו ונראה דאין להקפיד דנעל נעל ריבה וכן נראה שהוא דעת רבינו ירוחם ז\"ל גם סמ\"ג וסה\"ת תמהו על ר\"ת ומ\"מ כתב סמ\"ג דרגילות הוא להחמיר כדבריו וסה\"ת כתב כיון דנפק מפומיה דר\"ת יעשו לחומרא כדבריו וסמ\"ק והעיטור וכלבו בשם מהרי\"ף והמרדכי בשם הגהות סמ\"ק כתבו כדברי ר\"ת וכיון דכל הני רבוותא חששו לדברי ר\"ת לא ידעתי למה דחה רבי' דבריו בב' ידים וה\"ל לחוש להא לכתחילה מיהא וכתבו עוד סמ\"ק והכלבו בשם מהרי\"ף שגם רצועות המנעל והקרסים והלולאות ורצועות התפירה הכל מעור בהמה טהורה :","ויהיה לו רצועות לקשרו בהן ולהדקו על הרגל וגם כמין קשר באזנו האחד שיכניסוהו בנקב שיהיה לו באזנו כדי להדקו יפה בר\"פ מצות חליצה שם אמר רב אי לאו דחמיתיה לחביבי דחלץ בסנדל שיש לו שנצי אנא לא הוה חליצנא אלא בסנדלא דטייעי דמיהדק טפי והאי דידן אף ע\"ג דאית ביה חומרתאק טרינן ביה מיתנא. ופירש\"י שנצי אשטר\"ל ונוח לחלצו: אף ע\"ג דאית ביה חומרתא. קשר קשור על שפתו ומעמידו שלא יצא מן הרגל אפ\"ה בשעת חליצה קטרינן ביה מיתנא כי היכי דתיתי היא ותשרי והדר תחלוץ ותיהוי חליצה מעלייתא עכ\"ל ומשמע דה\"ק סנדל דאית ביה שנצי רחב והוא נוח לחלצו ואפ\"ה חליץ ביה כיון דאית ביה שנצי שמהדקו בהן וסנדל דטייעי עדיף דמיהדק טפי וכ\"כ הגהות מרדכי בשמו וחומרתא פי' הערוך הוא כעין טבעת כמו לולאות ורבינו ירוחם פירש שהוא קשר עגול שנקרא לאז\"ו ונכנס בעקב הרצועה שבצד האחת וכך הם דברי רבינו וסמ\"ק וכלבו בשם הרי\"ף והמרדכי בשם הגהת סמ\"ק כתבו שצריך קרסים וכן נראה מדברי סה\"ת וקרסים הם חומרתא וכל הני רבוותא כתבו שצריך שיהיו במנעל רצועות לקשרו בהם וסמ\"ק וכלבו בשם מהר\"ף כתבו שהרצועה האחת באזן מכאן והאחת באזן מכאן ונראה שדעת כל הני רבוותא לפרש דכי אמרינן והאי דידן אע\"ג דאית ביה חומרתא קטרינן ביה מיתנא ה\"ה נמי מיתנא בלא חומרתא לא סגי דתרווייהו צריכי להדוקי ליה שפיר ואין כן דעת הרשב\"א בתשובה שכתבו הקונ' שלא הזכיר חומרתא כלל אלא רצועה משמע דס\"ל דכי אמרינן אע\"ג דאית ביה חומרתא קטרינן ביה מיתנא היינו לומר דבלא מיתנא לא סגי אבל חומרתא זו לא מעלה ולא מורדת וזה דעת הרמב\"ם ז\"ל שלא הזכיר קרסי' כלל אלא רצועות וכן דעת סמ\"ג שכתב ומשמע הלשון שהרצועות עיקר ואיפשר דהנך רבוותא נמי הכי ס\"ל אלא דלרווחא דמילתא הצריכו לשום בו קרסים ורצועות כעין חכמי התלמוד כי היכי דליהדק טפי. ואם לא היו בו לא חומרתא ולא מיתנא ואית ביה שנצי שפיר דמי דהא ר' חייא הוה חליץ ביה ובסידור החליצה של הרי\"ף כתוב ועבדין סנדלא דאית ליה עקב ושנצי ולא הזכיר חומרתא ולא מיתנא ומש\"ה גם לדעת ראבי\"ה שכתב המרדכי אי אית ביה שנצי עדיף מחומרתא ומיתנא מיהו שאר פוסקים שכתבתי לא כתבו אלא חומרתא ומיתנא והרמב\"ם והרשב\"א ז\"ל לא כתבו אלא מיתנא וכ' הרא\"ש גבי מאן דמסגי אלוחת' דכרעיה דסנדל שלהם נראה שלא היה יכול לעמוד ברגל בלא קשירה אבל מנעל שיכול לעמוד ברגל להלוך בו בלא קשירה לא ידענא למה תפסל החליצה אפילו אם חולץ בלא קשירה שלא נאמרה קשירה בתורה ולא נאמרה הל\"מ עכ\"ל ובענין מיתנא זו לא נתבאר בתלמוד אם היא רצועה אחת או ב' והרשב\"א בתשובה לא הזכיר כי אם רצועה אחת אבל הרמב\"ם ז\"ל כתב וקושר רצועותיו וכן בדברי רי\"ף גבי האי מאן דמסגי אלוחתא דכרעיה לא חליץ הוזכרו רצועות לשון רבים וגם בירושלמי הוזכרו בלשון רבים ואפשר דלאו לעיכובא קאמר אלא אורחא דמילתא נקט וסמ\"ג וסה\"ת כתבו וצריך שיהיו במנעל ב' רצועות וכ\"כ הרא\"ש בסידור החליצה וכ\"כ רבינו ירוחם ז\"ל. ובענין החומרתא מלישנא דגמרא משמע דלא צריך אלא אחת לבד וכן נראה מדברי רבינו ורבינו ירוחם ז\"ל אבל סמ\"ק וסמ\"ג וסה\"ת הזכירו קרסים לשון רבים והמרדכי בשם הגהות סמ\"ק והכלבו בשם מהרי\"ף כתבו וצריך ג' קרסים או לכל הפחות ב' וכתב עוד וטוב שלא יהיו הלולאות מהאזן עצמה כ\"א רצועה קטנה מחוברת בראש האזנים וכתבו עוד שצריך שיהו אזניו קצרות שלא יגעו זה בזה כדי שיהיו הקרסים והלולאות שבהם תחובים על שוקו ממש ולא על האזנים ממש משום מעל דמעל וכ\"ש דבעינן שיהיו האזנים על שוקו ולא על סנדל דאז הוא ממש מעל דמעל ע\"כ ובסמוך יתבאר בס\"ד:","וכתב בספר המצות צריך שיהיו הרצועות לבנות כ\"כ בהגהות סמ\"ק וז\"ל הרצועות יהיו לבנות כי כן היו בימיהם כדמפרש בתוס' (סנהדרין עד:) בההוא דאפי' ערקא דמסאנא אסור לשנויי וכו' וכן מההוא דהוה מסיים מסאני אוכמי בפרק הכונס (בבא קמא נט:) עכ\"ל. ומ\"ש ושלא יהיה לו לשון כמו שרגילין לעשות במנעלים כדי שלא יהיה מעל דמעל גם כן בסמ\"ק: וכתב עוד בשם מהר\"פ וז\"ל לא יהיה שום לשון תחת הקרסים ולא יהיה לשון בין האזנים דאם כן הוי מעל דמעל והפותין שקורין אינפיל\"א לא תגיע רק עד האזנים ולא תחת האזנים ויש לתמוה על זה מדגרסינן בר\"פ מ\"ח (קב.) ומ\"ד מנעל לכתחילה לא מ\"ט משום דהויא פנתא מעל וערקתא מעל דמעל אי הכי דיעבד נמי לא גזירה משום מנעל המרופט ופירש\"י ערקתא שרוך הנעל שכופלים רצועות על אזניו והו\"ל כשני נעלים זה על גב זה אבל סנדל אין קושרין רצועות על אזניו שהרי קשה הוא ואין הרצועות דוחקתו אבל בשפת פיו יש כמו קשר לקצר את פיו אי הכי אפי' דיעבד נמי אלא מדאמרינן חליצה כשרה ש\"מ גלוי כרעיה בעינן ואפילו שני מנעלים זה על גב זה וכי שלפא לתרווייהו ש\"ד כדאמרינן לקמן שני מנעלים כו' ועד כאן לא איבעיא לן אלא דקרעתיה לעילאי ושלפתיה לתתאי אבל שלפתינהו לתרווייהו ש\"ד עכ\"ל וכ\"כ הרא\"ש וכ\"כ רבינו ירוחם בשם המפרשים ובשם הרמ\"ה ז\"ל הרי בהדיא דלא אמר בכי הא ולא מעל דמעל ואיפשר דסובר סמ\"ק דע\"כ לא מכשר רש\"י אלא דיעבד אבל לכתחילה מודה דחיישינן כיון דאיפשר לפרושי קרא הכי ובענין צורת מנעל חליצה כתוב בכתבי מה\"ר איסרלן סימן ר\"מ וברבינו ירוחם בשם הרמ\"ה:","\u0003ומ\"ש רבינו ושיהיה התפירה מבחוץ כבר נתבאר בסימן זה.\u0004 ומ\"ש שיהיה עשוי לצורת רגל נראה דמילתא באנפי נפשה היא ואינו מקושר עם מה שלמעלה ממנו כי אינו ענין לו ומ\"מ איני יודע מה מלמדה ומצאתי ספר מוגה ומצאתי כתוב שיהיה עשוי לצורת רגל הימנית וגירסא נכונה היא וכן נראה ממ\"ש לקמן או שהוא עשוי במדת רגל שמאל. ומ\"ש וינעלנו ברגלו הימנית משום דתנן בפרק מ\"ח (דף קד) חלצה בשמאל חליצתה פסולה:","ומ\"ש ויהיה למדת רגל שלא יהיה גדול עד שאין ראוי להלוך בו ולא קטן עד שאינו מכסה רוב הרגל דתנן בפ' הנזכר (דף קא.) חלצה בגדול שאינו יכול להלוך בו ובקטן שאינו חופה רוב רגלו חליצתה פסולה. ומ\"ש ולא יהיה קרוע עד שאינו יכול להלוך בו מדאמרינן גבי אין חולצין גזירה משום מנעל המרופט וכתבו התוספות והרא\"ש והא דתניא בס\"פ תולין לא תצא אשה במנעל המרופט ולא תחלוץ בו ואם חלצה חליצתה כשרה התם מיירי שאינו מרופט כ\"כ דעדיין יכול להלך בו:","ומ\"ש היה בגד פשתן תפור בו מבפנים או שתפירותיו בפשתן כבר כתבתי שב' פירושים אלו פירש\"י אהא דאמר רב יהודה אמר רב סנדל התפור בפשתן אין חולצין בו שנאמר ואנעלך תחש. וכתב הרא\"ש רש\"י פירש בלשון אחר שיש תחתיו בגד כמו שנותנין לבד בתוך המנעל בימות החורף ולא נ\"ל דלא גרע מסנדל של עץ דתני מתניתין דחליצתה כשרה. ואוקמוה אבוה דשמואל במחופה עור וד\"ה ואביי נמי אוקי הך ברייתא דקב הקיטע כרבנן ובמחופה עור ונראה כפירוש שני שתפרו במשיחה כעין שלנו דבעינן כוליה עור גם נראה דאין חולצין בו לכתחילה קאמר דדרשא דתחש אסמכתא בעלמא היא עכ\"ל. ומ\"ש או שהוא של עץ או של סיב או שעם ומחופה עור נתבאר בסמוך ומשמע דהא דמכשירין במחופה עור היינו דוקא במחופה מכל צד דומיא דואנעלך תחש וכן נראה קצת מדברי נ\"י שכתב שהסוקו\"ש של עץ שנותנים עור בראשם שנכנס בו הרגל אינו חשוב חפוי:","ומ\"ש או שהוא גדול ממדת רגלו ויכול להלוך בו או שהוא קטן ממדת רגלו מכסה רוב הרגל ויכול להלוך בו כך היא הגירסא הנכונה בדברי רבינו ודברים אלו מבוארים מהמשנה שכתבתי בסמוך דלא פסלה אלא בחלצה בגדול אינו יכול להלוך בו ובקטן שאינו חופה רוב רגלו: ומ\"ש או שלא היה שלו או שהיה עשוי בצורת רגל שמאלו ונועלו בימין שם במשנה חלצה בסנדל שאינו שלו או בשל שמאל בימין חליצתה כשר וקאמר בגמרא דאינה כשרה אלא דיעבד אבל לכתחילה לא אלא צריך שיהא שלו או שיקנוהו לו בעליו וגם צריך שיהא של ימין: ומ\"ש או שחלץ באנפיליא של עור או בסמיכת הרגלים או במוק החליצה כשרה דיעבד שם בברייתא (דף קב:) בקב הקיטע במוק בסמיכת הרגלים באנקיליא של עור חליצתה כשרה ופירש\"י במוק. קילצון של לבד קשה ומגין: בסמיכת הרגלים. מי שמהלך בידיו שגורר את רגליו עושה להם סמיכה של עץ או של עור שמכניסן לתוכו עכ\"ל ואיכא למידק אנפיליא של עור אמאי אינה כשרה אלא דיעבד וצ\"ל דצורת אנפיליא משונה מצורת מנעל וסנדל ומש\"ה לכתחילה אנפיליא לא אע\"פ שהיא של עור ורבינו ירוחם כתב דאנפיליא הוא מנעל החופה עד למעלה מן הפרק ויש לתמוה על רבינו שכתב סתם במוק חליצתה כשירה דיעבד ולא פירש שהוא של לבד דרבותא רבה היא שאע\"פ שאינו של עור חליצתה כשרה וכן יש לתמוה עליו אמאי השמיט דין קב הקיטע ומצאתי לרבינו ירוחם שכתב מוק הוא מנעל גבוה שחופה את הרגל ואת השוק עד הארכובה אלא שהוא גורם במוק פסולה ועל מה שאמרו בסמיכת הרגלים כשרה כתב רבינו ירוחם כל אלו שאמרו שכשרה דוקא שיש להם עקב ויש להן רצועות וכ\"כ הרמ\"ה. ומ\"ש בשם הרמ\"ה דבמנעל התפור בפשתן פסול אפילו דיעבד דבר פשוט שהוא ז\"ל מפרש הא דסנדל התפור בפשתן כפי' שני דרש\"י וסובר דדיעבד נמי פסול ליה כדמשמע דמייתי לי' מקרא דואנעלך תחש ומ\"ש אבל חלצה בשל עץ או של שעם שאינו מחופה עור ברגל שמאל או שהיה המנעל גדול שאינו יכול להלוך בו או שהוא קטן שאינו מכסה רוב רגלו או קרוע שאינו יכול להלוך בו או בסנדל שאין לו עקב או באנפיליא של בגד חליצתה פסולה הכל מבואר שם במשנה ובגמרא:","ומ\"ש בשם הרמב\"ם ז\"ל שאם חלצה במנעל של בגד אינה חליצה כלל אפילו לפסול על האחין כתב ה\"ה ז\"ל שטעמו משום שהוא סבור דכיון דאסיקנא בפרק מצות חליצה דלר\"מ דסבר דשל שעם ושל סיב אע\"פ שאינם מחופים עור חליצתן כשרה מודה דבשל בגד דחליצתה פסולה משום דלא מגין לדידן דקי\"ל כרבנן דבשל שעם ושל סיב שאינם מחופים עור חליצתן פסולה אע\"פ שמגינים בשל בגד נמי כיון דלא מגין מעלין ליה דרגא ואמרינן דאינה חליצה ומתני' דקתני באנפיליא חליצתה פסולה ר\"מ הוא דסתם מתניתין ר\"מ הוא ולא קי\"ל כוותיה זה נראה בדעתו ז\"ל ואינם דברים מוכרחים אבל הרשב\"א ז\"ל כתב שכולם שוים ובשל בגד נמי חליצה פסולה הויא דכולהו לרבנן ממעטינן להי מדכתיב בהו ואנעלך תחש אלמא עור בעינן הילכך כולן שוין ור\"מ הוא דהוה מפליג בינייהו דלית ליה האי דרשא אלו דבריו ז\"ל ולמטה בפ' זה מתבאר החילוק שיש בין חליצה פסולה לאינה חליצה עכ\"ל:","מנעל של עכו\"ם שמניחין אותו ברגלי הדמות כו\"ם לא תחלוץ בו ואם חלץ בו חליצתה כשרה אבל סנדל של תקרובת עכו\"ם או של עיר הנדחת או שנעשה למת שנקבר בו אם חלצה בו חליצתה פסולה כולו בפרק מ\"ח (דף קג:) אמר רבא הלכתא סנדל של עכ\"ם לא תחלוץ ואם חלצה חליצתה כשרה של תקרובת כו\"ם ושל עיר הנדחת ושל זקן העשוי לכבודו ולא תחלוץ ואם חלצה חליצתה פסולה ופירש\"י של עכו\"ם. הואיל ולהילוכא עבידא ומשמשי עכו\"ם לאו לשריפה קיימי דאית ליה תקנתא בביטול ואי משום הנאת חליצה לאו הנאה היא דמצות לאו ליהנות ניתנו: של תקרובת כו\"ם. שהקריב ומסרו לפניו לשם דורון וקי\"ל (ע\"ז כ) תקרובת עכו\"ם אין לה ביטול עולמית דאיתקש למת הילכך לית לה תקנתא וכתותי מכתת שיעוריה: של זקן העשוי לכבודו. לתכריכי מיתה הואיל ולאו להילוכא עבדי לאו נעל הוא וכתבו התוספות סנדל של עכו\"ם פירש רש\"י דמיירי בשל עכו\"ם וקודם ביטול דכיון דראוי לבטל לא מכתת שיעוריה וא\"ת והא מכי אגבהה הו\"ל דישראל ויש לומר כגון שהגביהו על מנת שלא לקנותו דהא תנן במנעל שאינו שלו חליצתה כשרה ורבינו תם מפרש דאחר ביטול מיירי ולכתחילה לא תחלוץ דמאיס לענין מצוה לפי שהיה עליו שם עכו\"ם ואמרינן בגמרא אהאי מימרא דרבא אמר ליה רבינא לרב אשי מ\"ש זקן העשוי לכבודו דלאו להילוכא עביד דבי דינא נמי לאו להילוכא עביד אמר ליה אילו מסגי ביה שליחא דבי דינא מי קפיד עליה דיינא:","כתב בספר המצות אפי' אטר חולץ בימין של כל אדם אע\"פ שהוא שמאלו ז\"ל סמ\"ק צריך ליתנו ברגל ימין אבל בשל שמאל פסול ואפי' אטר ע\"כ וז\"ל סמ\"ג תנן חלצה ברגל שמאל חליצתה פסולה שאנו למדים רגל רגל ממצורע שכתוב בו רגלו הימנית כתב מורי אפי' הוא אטר חשוב כימין מאחר שהצריכה תורת ימין בפי' תדע שהרי באזן אזן לרציעה (יבמות קד.) שאנו למדין ימין שם אין שייך לחלק שהרי אין כח בזו יותר מבזו ע\"כ:","ומ\"ש רבינו וי\"א שהוא חולץ בשתיהן במנעל של ימין בימין ובמנעל של שמאל בשמאל כ\"כ במרדכי שי\"א כן ובסמוך אכתוב דברי הר\"ן בדין זה.","ומ\"ש אבל אם שולט בשתי רגליו וכן היא בב' ידיה אז יעשו בשל ימין כ\"כ המר' בשם אבי\"ה והוא פשוט דהכי אמרינן (מנחות לז:) גבי תפילין דשולט בב' ידיו דינו ככל אדם: ומ\"ש רבינו וי\"א שאיטר חולץ בימין שלו שהוא שמאל של כל אדם והר\"ן כתב בר\"פ גיד הנשה איכא לספוקי ביבם איטר אי חולץ בשמאלו שהוא ימינו וניזיל בתר דידיה או בימינו שהיא שמאלו וניזיל בתר מיניה ולפ\"ז חולץ בשתיהן וסגי בהכי אלא דאיכא ספיקא אחרינא במילתא מדתנן בס\"פ מומין אלו (בכורות מה.) ת\"ר איטר בין ביד בין ברגל פסול ופירש\"י משום דבעי ימין כדגמר יד יד לקמיצה ממצורע וזה אין לו ימין וכ\"ת תינח איטר ביד אבל איטר ברגל למה הוא פסול כבר פירש\"י שם מדכתיב לעמוד לשרת בעינן שיעמוד כדרך שאר עמידות שעיקרן בימין כיון דאיטר אין לו ימין יבם איטר אין לו תקנה וכן דעת הרמב\"ן ז\"ל אבל אחרים אומרים דאיטר משום מום הוא נפסל ולא מפני שאין לו ימין ולפ\"ז חולץ בשניהם משום ספיקא אי אזלינן בתר דידיה או בתר מיניה עכ\"ל ובנימוקי יוסף פמ\"ח הביא סברות אלו וכתב שהרשב\"א ז\"ל הניח הדבר בצ\"ע :","וינעול המנעל על רגלו כשהוא יחף ולא על בתי שוקים שלא יהא מעל דמעל כ\"כ המרדכי בפרק מ\"ח וכתב ואע\"ג דסנדל של עץ כשר ומוקי לה בגמרא במחופה עור וכן אנפילאות של בגד היינו לפי שתפורי' יחד והוי מנעל א' אבל מנעל על בתי שוקים איקרו מעל דמעל עכ\"ל וכ\"כ בסה\"ת. ומ\"ש ומטעם זה יש מדקדקים שלא יהיה טיט דבוק במנעל מבפנים שלא יהא מעל דמעל כ\"כ שם המרדכי בשם אבי\"ה ומטעם זה כתב עוד וצריך לרחוץ רגלו הימיני יפה יפה וכתוב בהגהות מרדכי שהיבם קושר כנף המכנסים למעלה משוקו כדי שתהא ראיית הדיינים היטב שלא יהא חציצה בין רגלו ובין המנעל:","ויקשרנו קשר גמור ולא בעניבה וי\"א שצריך ב' קשרים זה על זה ז\"ל סמ\"ג יכרוך הרצועות סביב למנעל ברגלו ויקשור שניהם יחד שני קשרים ומפרש בירושלמי כיצד היה עושה כדי שיוכל להלוך בו ואח\"כ קאמר רבי חנינא בריה דרבי הכל עונבו כדי שתוכל להתיר באחת מידיה כיצד הוא עושה מתירתו בימין ותופסתו בשמאל ושומטת עקב בימין וגוררתו בימין כדי שתהיה חליצה והתרה בימין ויש שעושים קשר ועניבה על הקשר לקיים דברי הירושלמי עכ\"ל והתוספות והרא\"ש ז\"ל כתבו בריש פרק מ\"ח אהא דאמרינן והאי דידן אע\"ג דאית ביה חומרתא קטרינן ביה מיתנא כי היכי דתיהוי חליצה מעלייתא ירושלמי כיצד הוא עושה קושרו כדי שיהא יכול להלוך בו מאליו רבי חנינא בריה דרבי הלל אומר עונבו כדי שתהא יכולה להתירו באחת מידיה וכו' ונהגו האידנא לקשרו בקשר גמור עכ\"ל וסיים בה הרא\"ש דקי\"ל דעניבה לאו קשירה היא לענין שבת ע\"כ. והמרדכי כתב זה הירושלמי וכתב עליו נראה דרבי חנינא עיקר א\"כ לא יהדק הקשר השני ע\"כ וסמ\"ק כתב שם בשם ר\"פ כשקושר צריך שני קשרים זה על גב זה ע\"כ. וז\"ל סה\"ת ויש שעושין קשר ועניבה על הקשר לקיים דברי הירושלמי וטוב יותר לעשות ב' קשרים זה ע\"ג זה שמה שאומר בירושלמי עניבה היינו כדי שתוכל להתיר בקל בידה אחת בימין וכתוב בספר המצות צריך שיהא הקשר על בשר שוקו ולא על אזני המנעל כן כתוב בסמ\"ק ונראה שהטעם כי היכי דלא ליהוי מעל דמעל ובהגהת מרדכי כתוב כורכין הרצועות סביב למנעל ה' קשרים סביב השוק ואויר גדול בין כרך וכרך ומיהו אין קפידא בכרכים אם הם זה ע\"ז וגם על המנעל דלאו היינו מעל דמעל ע\"כ ולכתחילה ודאי יש לעשות כדברי הסמ\"ק ורבינו והגהות הנזכרים כתבו אח\"כ וז\"ל וב' הרצועות יסבבם פעמים סביב לשוק עד שישובו ראשי הרצועות על השוק לפנים ממעל לאזני המעל דהיינו על שוקו ערום עכ\"ל. ומ\"ש לכך כתב בספר המצות שצריך שיחתוך לפניו ולאחריו כמו פגימה כו' דבר זה לא מצאתי לא בסמ\"ג ולא בסמ\"ק אלא במרדכי פרק מ\"ח בשם אבי\"ה כתוב בלשון הזה יחתיך ממנו מעט לפניו ולאחריו כדי שתהא הרצועה החוזרת דבוקה ממש על רגלו יחף וכן בצדיו ויכוין הקשר של הרצועה שיהיה מלפניו ומלאחריו ממש על בשרו עכ\"ל. ומ\"ש רבינו ויכניס הקשר שבאזנו בנקב שבאזנו השנית פשוט הוא: וכתב בקונדריסים יהיו הקשרים על צידי השוק החיצונות על פני השוק ולא מאחוריו:","וצריך שיקראו אותו בעמידה מאן יבמי להקים לאחיו שם בישראל לא אבה יבמי כבר נתבאר בסימן זה שמצות חליצה לכתחילה מעומד:","ומ\"ש ואפילו היא מאותן שחולצות ולא מתייבמות שלא התירו להתייבמה אפ\"ה צריכה קריאה כ\"כ בתשובת הרא\"ש כלל נ\"ב סימן ב' ז\"ל וששאלתם נשים שחולצות ולא מתייבמות אם צריכות קריאה משום דלא חפצתי לקחתה משמע דאי בעי יבם והא לא מצי לייבומי פשיטא שצריכות קריאה אע\"ג דקריאה לא מעכבא מ\"מ לכתחילה כל דין חליצה בעינן וכל החולצות ולא מתייבמות כגון איסור מצוה ואיסור קדושה מדאורייתא עולה לייבום אלא משום גזירה ביאה ראשונה אטו ביאה שנייה וכן עריות שיש בהן ספק קידושין הצרה עומדת בחזקת היתר ליבם הילכך כולם עולים ליבום מדאורייתא ולא פלוג חכמים בכל החולצות וצריכות קריאה עכ\"ל וגם בתשובה להרמב\"ן ז\"ל כתוב שאלה יבמה שאינה רוצה ביבם והוא רוצה בה איך איפשר שתאמר מאן יבמי תשובה אחר שנותנים לו עצה ההוגנת אם הוא ילד והיא זקנה או הוא זקן והיא ילדה שאומרים לו כלך אצל הראוייה לך ואל תכניס קטטה בתוך ביתך וכיוצא בזה והוא שומע לכך ומתרצה שכבר גמר בדעתו למאן ושלא ייבם כלל א\"כ יכול הוא שיאמר לא חפצתי לקחתה והיא יכולה לומר מאן יבמי דמ\"מ מתבטלים הן היבומים וחולצין הם וגזירת הכתוב שכל חולצת תקרא מאן יבמי ושיקרא הוא לא חפצתי לקחתה עכ\"ל:","ויקראו אותה מלה במלה זו אחר זו בלשון הקדש רק לא אבה צריך שיקראו בנשימה אחת בלא הפסק מ\"ש שהקריאה תהיה בלשון הקדש מבואר במשנה בסוטה פ' אלו נאמרים (סוטה לב.) ומ\"ש רק לא אבה צריך שיקראוהו בנשימה אחת בלא הפסק ס\"פ מ\"ח (דף קו:) אמר אביי האי מאן דמקרי גט חליצה לא ליקרי לדידה לא לחודיה ואבה יבמי לחודיה דמשמע אבה יבמי אלא לא אבה יבמי ולא ליקרי לדידיה לא לחודיה חפצתי לחודיה דמשמע חפצתי לקחתה אלא לא חפצתי לקחתה רבא אמר אסוקי מילתא היא ואסוקי מילתא לית לן בה רב אשי אשכחיה לרב כהנא דקמצטער ומקרי לה לא אבה יבמי א\"ל לא ס\"ל למר להא דרבא א\"ל מודה רבא בלא אבה יבמי ופירש\"י דמקרי. גט חליצה המקרא את האשה בשעת חליצה. מודה רבא בלא אבה יבמי. דבעינן שלא יפסיק דאי מפסיק משמע דהאי לא ארישא קאי דאמר מאן יבמי להקים לאחיו שם בישראל לא כלומר לא מאן אלא אבה יבמי אבל בלא חפצתי לקחתה שהיא פתיחת קריאתו ליכא למימר הכי לא לעיל קאי ואי מפסיק לית לן בה עכ\"ל והרי\"ף גורם א\"ל מודה רבא בלא אבה יבמי כרבי זירא דאמר (קד:) כל הראוי לבילה אין בילה מעכבת בו וכל שאינו ראוי לבילה בילה מעכבת בו הכא נמי אם ראוייה למיקריא בבת אחת אין קריאתה מעכבתה ואי לא מעכבא ופירש נמוקי יוסף מודה רבא בלא אבה ה\"ה בלא חפצתי מטעמיה דרבי זירא והא דנקט בלא אבה משום שאין דרכן של נשים לידע לקרות וכולן אינן ראויות לבילה חשיבי עד שילמדם אבל סתמן של אנשים יודעים הם וראויים לבילה מיקרו עכ\"ל וז\"ל הרמב\"ם ומלמדין אותה ואת היבם לקרות עד שהוא והיא יהיו רגילין ותהיה יכולה לקרות לא אבה בנשימה אחת ואח\"כ תאמר יבמי כדי שלא יהא משמע דברים אבה יבמי ומאחר שתהיה רגילה אע\"פ שלא קראה בנשימה אחת אין מקפידין ע\"ז אבל אם אינה יכולה מרגילין אותה עד שתדע וכתב ה\"ה ומלמדין אותה כולי אמר אביי האי מאן דמקרי גט חליצה לא לקרי לא לחודיה אבה לחודיה וכולי עד א\"ל מודה רבא בלא אבה יבמי כדר' זירא דאמר כל הראוי לבילה בילה מעכבת בו ופי' זה מבואר בהלכות כדברי רבי' וכתב הרשב\"א ז\"ל וכפי דבריהם אפי' בלא חפצתי לקחתה צריך שידע לומר לא חפצתי בבת אחת והא דנקט בלא אבה משום דאין דרכן של נשים לקרות ואינן ראויות עד שילמדו' ראוים הם לקרות והוא ז\"ל הקשה עליהם וכתב שיש גירסא אחרת בזה והראשונה נוסחת הגאונים והספרים וכן הוא בעיטור עכ\"ל והרא\"ש כתב א\"ל מודה רבא בלא אבה יבמי פירש\"י משום דאיכא לפרושי לא אדלעיל מיניה קאי אבל לא חפצתי תחלת דבור הוא וגירסת רב אלפס ז\"ל אינה נכונה דמה ענין רבי זירא לכאן מ\"מ יש לטעות בפירוש דבריהם עכ\"ל ויש בדברי הרמב\"ם שכתב רבינו חסרון הניכר והוא ט\"ס כי בקצת ספרי רבינו המדוייקים כתיב כתקנה:","ומ\"ש רבינו וכן יראה מדברי רי\"ף אם אינה יודעת לקרות כאחת אינו מעכב עכ\"ל צ\"ל דה\"ק אם בשעת קריאה לא קראה כאחת אבל מ\"מ צריכה שתהיה רגילה לקרותו כאחת דתיהוי ראויה לבילה וכמו שנתבאר ומ\"מ לשון אינו מעכב אינו מדוקדק דהא אפילו לא קראה כלל חליצתה כשרה כמו שיתבאר בסימן זה: ומ\"ש וא\"א ז\"ל כתב שצריך שתקרא אותו בלי הפסק כבר נתבאר:","\u0003ומ\"ש קראוהו מעומד לא חפצתי לקחתה כבר נתבאר בסימן זה דלכתחילה בעי' מעומד:\u0004 ","\u0003ומ\"ש ואין לחוש אם יפסיק בין לא לחפצתי כבר נתבאר בסמוך:\u0004 ","ומ\"ש וידחוק רגליו בקרקע בפמ\"ח (ד' קג:) אמר אמימר האי מאן דחליץ צריך למדחקיה לכרעיה ופירש\"י לדחוף רגלו בקרקע וכתב הרא\"ש ז\"ל למדחקיה לכרעיה כדי שיהא ניכר שטורח לחלוץ מנעלו דלפעמים מנעל ב\"ד גדול ממדת רגלו ונראה כיוצא מאיליו אם לא שידחוק רגלו מעט ולקמן בסמוך יתבאר אי לא דחקיה לכרעיה אי הוי חליצה פסולה או לא:","\u0003ומ\"ש ותגביה היא בידיה רגלו מעל הקרקע ותחלוץ המנעל:\u0004 ","ומ\"ש ויעמוד היבם אצל הכותל או אצל עמוד וישען עליו כדי שיוכל לדחוק רגליו בקרקע כ\"כ הרא\"ש ז\"ל בסדר החליצה שכתב בס\"פ מ\"ח וכתבו רבינו בסוף סימן זה:","וכיצד היא חליצת המנעל שתתיר היא קשירת המנעל בידה הימנית כולי בפמ\"ח אהא דאמרינן והאי דידן אע\"ג דאית ביה חומרתא קטרינן ביה מיתנא כתבו התוספות בירושלמי דפירקין גרסינן כיצד הוא עושה קושרו עד שיהא יכול להלוך בו מאליו וכו' כיצד הוא עושה מתירתו בימין ותופסת בשמאל ושומטת עקב בימין וגוררתו בשמאל עד שתהא התרה וחליצה בימין ע\"כ ירושלמי ומיהו נהגו לקשור היטב בקשר גמור וגם צריך שתתירנו בידה הימנית לפי הירושלמי ואע\"פ שלא מצינו שפוסל בשמאל אלא ברגל אבל ביד כשר לחלוץ אפי' בשמאל ואמרינן נמי לקמן בסוף פירקין גדמת חולצת בשיניה משמע דלא מיפסלא אם לא חלצה בידה הימנית עכ\"ל וגם הרא\"ש כתב ובגמרא דידן לא אשכחן שצריך התרה ביד ימין דלא אשכחן שמצריך ימין אלא ברגל ולקמן נמי אמרינן דגדמת חולצת בשיניה ומיהו נהגו העולם כן על פי הירושלמי עכ\"ל וכ\"כ נ\"י וסה\"ת והמרדכי גורסים בירושלמי ושומטת עקב בימין וגוררתו בימין וכן גורס ה\"ה ז\"ל: ומ\"ש רבינו בשם ר\"ת שולפתו בימין ושמאל מסייעתה כ\"כ המרדכי וסה\"ת בשמו וכתבו שאין נראה:","ומ\"ש רבינו בשם ספר המצות כ\"כ בסמ\"ק וסה\"ת וז\"ל תתיר האשה קשר הרצועות והקרסים מן הלולאות הכל בידה הימנית ולא תהא שמאל מסייעתה כדאיתא בירושלמי וכתב עוד בסמ\"ק תתיר האשה קשר הרצועות קודם ואח\"כ הקרסים הכל בידה הימנית ותגביה רגל היבם מן הארץ ותשמוט המנעל מן העקב בימין בלא סיוע השמאל ותחלוץ כל המנעל חוץ מן הרגל בימין:","ומ\"ש וגדמת חולצת בשיניה לכתחילה כבר נתבאר דהכי איתא בגמרא ס\"פ מ\"ח (דף קה.) וכן כתבו הפוסקים ז\"ל והרמב\"ם ז\"ל לא הזכיר יד ימין לענין חליצה וכתב הרב המגיד דאע\"ג דבירושלמי קאמר שהיא ביד ימנית לא סמך עליו הרמב\"ם משום דבגמרא דידן לא הוזכרה יד ימין לענין חליצה כלל וגבי יבמה גדמת אמרו מי כתיב וחלצה ביד ורגל ימיני נמי אי לאו דגמרי ליה ממצורע היו מכשירין אפילו של שמאל ויד דלא כתיב מנ\"ל ואפי' לכתחילה וכ\"כ הרשב\"א ז\"ל עכ\"ל:","התיר הוא הקשר ושמטה היא המנעל מרגלו בר\"פ מ\"ח (דף קב.). א\"ר ינאי בין שהתיר הוא ושמטה היא בין שהתירה היא ושמט הוא חליצתה פסולה עד שתתיר היא ותשמוט היא: ומ\"ש רבינו בשם הרא\"ש ז\"ל הא דפסול בשהתיר הוא דוקא שהוא בענין שלא יכול להלוך בו אם לא שהוא קשור כו' כן נראה ממ\"ש בפסקיו בפרק הנזכר אהא דאמר אמימר האי מאן דמסיק אלוחתא דכרעיה לא חליץ:","לשון הרמב\"ם ינעוץ בארץ רגלו והיא יושבת ופושטת ידיה בב\"ד ומתרת רצועות המנעל וחולצת המנעל ומשלכת המנעל לארץ ע\"כ ואיני יודע למה כתב ויושבת והלא מצות חליצה מעומד ועיקר החליצה התרת המנעל וחליצתו ועוד למה הצריכה להשליך אותו לארץ כך היא הנוסחא האמיתית בספרי רבינו המדוייקים ויש ספרים שכתוב בהם חסרון הניכר וט\"ס הוא ומה שתמה על הרמב\"ם ז\"ל למה כתב ויושבת כבר נתן טעם ה\"ה לדבר וכתב שכן דעת הרב הרשב\"א דאפילו לכתחילה מיושב וכתבתיו בסי' זה. ומ\"מ שאר הפוסקים כתבו דלכתחילה חולצת מעומד וראוי לחוש לדבריהם וכן נוהגים וז\"ל סה\"ת ותהא שומטת על המנעל מן העקב ותחלוץ כל המנעל והכל מעומד או מוטה ולא יושב וכ\"כ סמ\"ג וז\"ל סמ\"ק ונגשה יבמתו מעומד או תכוף עצמה ולא מיושב ולא על ברכיה ע\"כ ומה שתמה רבינו על הרמב\"ם למה הצריכה להשליך המנעל לארץ י\"ל דהרמב\"ם אורחא דמילתא נקט ולא משום דבעינן השלכה לארץ:","אמר אמימר מאן דחליץ צריך למדחפיה לכרעיה בפ' מ\"ח (דף קג):","ומ\"ש ופי' רב אלפס שאם לא עשה כן החליצה פסולה שהוא מדמה אותו לאידך דאמימר דאמר דמאן דמסגי אלוחתא דכרעיה וחלץ חליצתו פסולה שפי' טעמא דלא חלץ מאן דמסגי אלוחתא משום דבעי למדחפיה אארעא כולי אין דברי הרי\"ף מבוארים שאם לא עשה כן החליצה פסולה דהא איכא למימר דהא דכתב דמאן דמסגי אלוחתא דכרעיה חליצתו פסולה משום דבעי למדחפיה לכרעיה אארעא היינו משום דאינו ראוי למדחפיה אבל מי שהוא ראוי למדחפיה אע\"ג דלא דחיף חליצתו כשירה וכמ\"ש ה\"ה ז\"ל וכ\"נ מדקדוק לשון הרמב\"ם ז\"ל שכתב היתה רגלו עקומה לאחור וכולי שהחולץ צריך לנעוץ עקבו בארץ וזה אינו יכול ואם חלצה למי שרגלו כך הרי חליצתה פסולה דמשמע בהדיא דלא פסל אלא דוקא בחלצה למי שרגלו כך לפי שאינו יכול לנעוץ עקבו הא אם חלצה למי שאין רגלו כך אע\"פ שלא נעץ עקבו חליצתו כשירה כיון שהוא יכול לנעוץ עקבו דכל הראוי לבילה אין בילה מעכבתו ומ\"מ מדכתב הרא\"ש שהראב\"ד כתב על דברי הרי\"ף הני תרתי שמעתתא דאמימר לאו חד טעמא נינהו דהא דאמר צריך למדחפיה כרעיה אארעא אי לא דחיף לא מיפסלא חליצה בכך והא דקאמר האי מאן דמסגי אלוחתא דכרעיה לא חליץ ואי חליץ חליצתה פסולה והרמב\"ן השיב על דבריו לקיים דברי רב אלפס ז\"ל וכתב לפסול את שתיהן ועדיין נראין דברי הראב\"ד דלא קאמר אמימר אלא צריך למדחפיה לכרעיה משמע בהדיא דמשמע להו להני רבוותא ז\"ל דלהרי\"ף כל דלא דחפיה לכרעיה חליצתו פסולה אע\"פ שהוא ראוי למדחפיה וכ\"נ דברי רבינו ירוחם וכתב שדעת הרמ\"ה כדעת הרי\"ף:","ומ\"ש רבינו וכ\"כ הרמב\"ם ז\"ל היתה רגלו עקומה לאחור או הפוכה על צדה או שמהלך על אצבעות רגליו אינו חולץ שהחולץ צריך לנעוץ עקבו בקרקע וזה אינו יכול חלצה למי שהולך כך חליצתה פסולה והראב\"ד כתב שאין טעם שתי מימרות דאמימר אחד דטעמא דמאן דמסגי אלוחתא דכרעיה פסול לפי שנעלו נחלצת מעל כף רגלו ולא מעל רגלו וגם כשהוא הולך ראש נעלו הולך למטה מרגלו אבל אי לא דחיף לכרעיה לא מיפסל החליצה בהכי וכ\"כ א\"א ז\"ל טעם שצריך לדחוק רגלו אינו אלא כדי שתהא טורחת לחלוץ רגלו וכו' כך היא הנוסחא האמתית בספרי רבינו המדוייקים ויש קצת ספרים שטעה הסופר והשמיט קצת לשון וחסרון הניכר הוא ולענין מה שהשוה רבינו דעת הרמב\"ם ז\"ל לדעת הרי\"ף לפסול בלא דחיף כרעיה אע\"פ שהוא ראוי כבר כתבתי שאין נראה כן מדקדוק לשונו:","ומ\"ש בסברת הראב\"ד וגם כשהוא הולך נעלו הולך למטה מרגלו נראה שהוא ט\"ס כי בפסקי הרא\"ש כתוב בסברת הראב\"ד ז\"ל כל' הזה וגם כשהוא חולץ נעלו חולץ למטה מרגלו והתורה אמרה נעלו מעל רגלו:","ומ\"ש וכן כתב א\"א הרא\"ש ז\"ל טעם שצריך לדחוק רגלו אינו אלא כדי שתהיה טורחת לחלוץ רגלו כו' כלומר וא\"כ אינו ענין לאידך מימרא דמאן דמסגי אלוחתא דכרעיה לא חליץ:","חלצה מן הארכובה ולמטה חליצתה כשירה מן הארכובה ולמעלה חליצתה פסולה משנה בפרק מ\"ח (דף קא) ואהא דאמר אמימר האי מאן דמסגי אלוחתא דכרעיה לא חליץ פירש\"י ואע\"ג דתנן מן הארכובה ולמטה כשירה התם הוא דכי נחתך רגלו קם ליה שוקו במקום רגלו ורחמנא אמר מעל רגלו דהיינו שוקו אבל האי לאו רגלו הוא וכתב הרא\"ש ור\"ח פי' בשם גאון דכיון דמסגי אלוחתא לא יכיל למיתרץ כרעיה דעל גבי ההוא לתחת ולתחת דידיה היא לעיל וכיון דאיתיה לכרעיה ולא תריצא הו\"ל כמו (שאינו ראוי לבילה שבילה מעכבת בו אבל היכא דהוי תריץ כרעיה מעיקרא ואי לא פסיק היה יכול למתרציה אע\"ג דאיפסיק חליץ למטה מן הארכובה דהו\"ל ראוי) לבילה שבילה אין מעכבת בו. לכל הפירושים האלו משמע דקטע חליץ אבל בירושלמי לא משמע הכי דאמרינן בירושלמי אמתני' דמן הארכובה ולמטה כיני מתני' בקושר מן הארכובה ולמטה כשירה מן הארכובה ולמעלה פסולה ומשמע דלא איירי בקטע אלא במי שרגלו שלם וקושר את הרצועות מן הארכובה ולמעלה וכן פי' רבינו ניסים ז\"ל במגילת סתרים וכן פי' רב אלפס ומיהו תימה לומר לפסול חליצה אם לקשרו רצועות הסנדל מן הארכובה ולמעלה דמה נפקא מינה היכי דנתקשרו הרצועות רק שחלצה נעלו מעל רגלו והא דקאמר בירושלמי דעיקר חליצה הסרת רצועות נראה שהסנדל שלהם לא היה יכול לעמוד ברגל בלא קשירה וכן משמע מתוך לשון הירושלמי דאמר קושרו עד שיכול להלוך בו אלמא דעיקר הקשירה כדי שיעמוד על רגליו ויכול להלוך בו וכיון שאין יכול לעמוד ברגל בלא קשירה אם התיר הרצועות הו\"ל כאילו שמט הסנדל כיון דסופו ליפול מעצמו וכן אם קשרו למעלה מן הארכובה שעיקר עמידת הסנדל ע\"י הקשירה ולא קרינן ביה וחלצה נעלו מעל רגלו אבל מנעל שיכול לעמוד ברגל (להלוך בו) בלא קשירה לא ידענא למה תפסל החליצה אם קשר למעלה מן הארכובה או אפי' אם חולץ בלא קשירה שלא נרמזה קשירה בתורה ולא נאמרה הלכה למשה מסיני והא דקאמר בירושלמי כיני מתני' בקושר מן הארכובה ולמטה כשירה מן הארכובה ולמעלה פסולה לא בא למעוטי קטע אלא לאשמועינן דבעינן שתהא אף הקשירה מן הארכובה ולמטה בסנדל שלהם שאינו יכול לעמוד ברגל בלא קשירה אי נמי בקטע איירי ואתא לאשמועינן דבעינן שישאר כל כך בשוקו שיוכל להכניס הסנדל בשוקו ולהוציא למטה מן הארכובה אבל אם נחתך שוקו בסמוך לארכובה שאינו יכול לקשור הסנדל אלא בשוקו למעלה מן הארכובה פסולה עכ\"ל:","ומ\"ש שדעת הרמב\"ם ז\"ל כדעת רב אלפס מבואר בדבריו שכתב שאם היה המנעל קשור למעלה מן הארכובה חליצתה פסולה וכתב עוד יבם שרגלו הימנית חתוכה אינו חולץ בשמאל ואם חלצה מנעל שמאלו חליצתה פסולה וכתב ה\"ה שכן דעת בעל העיטור ושדעת בעל המאור כפירש\"י דכל שנחתך רגלו מן הארכובה ולמטה חולץ וכן דעת הרשב\"א ז\"ל וכתב הוא ז\"ל והוא דדחיס מה דאשתאר על ארעא כדאמר אמימר האי מאן דחליץ צריך למדחסיה לכרעיה אארעא ע\"כ כתב בא\"ח כתב הרמב\"ם יבם שרגלו הימנית חתוכה אינו חולץ בשמאל ואם חלצה בשמאל חליצתה פסולה מכאן דקדק מורינו ז\"ל שדעת הרמב\"ם שאם חלצה בימין חליצתה כשירה שאל\"כ הול\"ל ואם חלץ חליצתו פסולה ואע\"פ שכתב בפירושיו בלשון ערב שהוא פסולה ולא יתכן בו חליצה אני אומר שחזר בו [וכן דעת רש\"י שאם נחתך רגלו מן הארכובה ולמטה חולצת בשוקו דמעל רגלו קרינן ביה וכ\"כ הר\"ן וכ\"כ העיטור והראב\"ד וכ\"פ הרשב\"א בחידושיו וז\"ל הילכך אם נקטעה רגלו חולץ בשוקו כל שהוא מן הארכובה עכ\"ל ומ\"ש הרמב\"ם ספר מוטעה נזדמן לו שהיה כתוב בו ואם חלצה בשמאל חליצתה פסולה אבל בנוסחי דידן בספרי הרמב\"ם אין כתוב תיבת בשמאל ואפילו לפי נוסחתו אין דקדוקו דקדוק דאיכא למימר דה\"ק בימין לא שייך חליצה כיון שרגלו חתוכה ואם חלצה בשמאל דשייך ביה חליצתה פסולה מפני שהוא בשמאל ועי\"ל לפי נסחו דמ\"ה כתב בשמאל לומר דמ\"ה חליצתה פסולה ולא בטלה אבל אם חולץ בימנית החתוכה אינה חליצה כלל וכבר ביאר בסוף אותו הפרק מה בין אמרו חליצתה פסולה לאמרו אינה [חליצה] ואף לפי נוסחתינו הדין הזה דין אמת שאם חלצה בשמאל חליצתה פסולה ואם חלצה בימנית החתוכה אינה חליצה:","קרעה המנעל מעל רגלו או ששרפתו פסולה שם (דף קב.) בעי רבי ינאי קרעתו מהו שרפתו מהו גלויי כרעא בעינן והא איכא או דילמא חליצה בעינן והא ליכא תיקו וספיקא דאורייתא לחומרא וכ\"כ הרמב\"ם ז\"ל:","ומ\"ש היה לבוש שתי מנעלים זה ע\"ג זה וחלצה שניהם כשירה קרעה העליון בענין שחלצה התחתון וכו' שם בעא מיניה רבי נחמיה מרבה ב' מנעלים זה ע\"ג זה ה\"ד אילימא דשלפתיה לעילאי וקאי תתאי מעל אמר רחמנא ולא מעל דמעל לא צריכא דקרעתיה לעילאי ושלפתיה לתתאי וקאי עילאי מאי חליצה בעיא והא איכא או דילמא גלויי כרעא בעינן וליכא וכתב הרא\"ש ז\"ל ולא איפשיטא אבל אם חלצה שניהם כשירה ואין בו משום מעל דמעל והרמב\"ם ז\"ל נראה שהיה לו גירסא אחרת בגמרא שכתב היה לבוש ב' מנעלים וחלצה העליון אע\"פ שקרעה התחתון עד שנגלית רגלו חליצתה פסולה:","ותרוק בארץ כנגד פניו רוק הנראה לדיינים כשיצא מפיה בס\"פ מ\"ח (ד' קי:) תנן וירקה בפניו רוק הנראה לדיינים ובגמרא שם אמר רבא צריכי דייני למיחזי רוקה היכא דנפיק מן פומא דיבמה דכתיב לעיני וירקה ומשמע דיליף רבא הכי מדלא כתיב וירקה לעיני דאז הוה משמע שאחר שיצא הרוק מפיה יראוהו דמהאי טעמא לא בעינן דליחזי בעלה כי נפיק רוק מפומה דכתיב וירקה בפניו אבל גבי דיינים דכתיב לעיני וירקה בעי' דליחזי כי נפיק רוק מפומה: כתב סמ\"ק רוקקת רוק גדול הנראה להדיינים משעה שיצא הרוק מפיה עד שיגיע לפני היבם:","כתב הרמב\"ם לא ראו הדיינים הרוק כשיצא מפיה כשירה כתב ה\"ה שלמד כן מדאמר רבא צריכי דייני למיחזי רוקא ולא אמר אי לא חזי דייני רוקא לאו חליצה היא כחו שאמרו בההיא דאכלה תומא הסמוכה לה:","רקקה וקלעתו הרוח קודם שהגיע נגד פניו כגון שהיא ארוכה ממנו צריכה לרוק פעם אחרת אבל לאחר שהגיע הרוק נגד פניו אפילו לא הגיע לארץ כשירה לפיכך אם הוא ארוך והיא קצרה קרינן ביה שפיר בפניו כך היא הגירסא הנכונה בספרי רבינו המדוייקים ואיתא שם בס\"פ מ\"ח (קו:) אמר אביי רקקה וקלטתו הרוח לא עשה ולא כלום מ\"ט וירקה בפניו בעי' וליכא הילכך הוא ארוך והיא גוצא וקלטתו הרוח הא איכא בפניו היא ארוכה והוא גוץ בעינן עד דמטי רוק לאפי דידיה והדר אזיל וכתבו התוס' והא דאמרינן בהחולץ ורקתה קדמנא רוקא בב\"ד דמתחזי על ארעא ובכל הספרים איתיה וכן בסנהדרין בירושלמי שמא למצוה מן המובחר בעינן הכי: כתב ב\"י בשם הרמ\"ה דהא דאמרינן דקלטתו הרוח אינו כלום וצריכה לחזור ולרוק בפניו דוקא לכתחילה אם עומדת שם אבל אם נתפזרו והלכו להם כשירה:","\u0003יבמה שרקקה דם אינה צריכה לרוק פעם אחרת וכתב רב אלפס דוקא במוצצת כו'\u0004 (שם דף קה.) שלחו ליה לאבוה דשמואל יבמה שרקקה דם תחלוץ לפי שא\"א לדם בלא צחצוח רוק מיתיבי יכול יהא דם היוצא מפיו ומפי האמה טמא ת\"ל זובו טמא הוא טמא ואין הדם היוצא מפיו טמא אלא טהור לא קשיא כאן במוצצת כאן בשותת ופירש\"י מוצצת א\"א בלא צחצוח רוק ופסקו כן הרי\"ף והרמב\"ם ז\"ל וכתב ה\"ה ז\"ל בשם הרשב\"א אם רקקה ואינה שותתת ואינה מוצצת איכא למימר דאף היא אפשר שתרוק דם בלא צחצוחי הרוק עכ\"ל ועיין בר\"י: ודע דמקמי הכי אמרי' בגמרא דלוו שאיל בי מדרשא יבמה שרקקה דם מהו א\"ל מי כתיב וירקה רוק ואהא דשלחו ליה לאבוה דשמואל יבמה שרקקה דם תחלוץ ואוקימנא במוצצת כתב הרא\"ם ז\"ל ואני כתבתי כדפירשתי דהנהו דבי מדרשא דאמרי מי כתיב וירקה רוק סברי דאפילו שותתת דלא בעינן צחצוחי הרוק וכ\"כ הראב\"ד ז\"ל דטעמא דמסתברא הוא דהא רוק לא כתיב באורייתא וגבי זב נמי דכתיב וכי ירוק הזב אי לאו זובו טמא ה\"א דם היוצא מפיו טמא וכתב דלא פליגי אהדדי דלעיל דלא בעי לצחצוחי הרוק כשרקקה במקום חליצה דסגי לה בהכי והך ברייתא דבעי צחצוחי הרוק כשרקקה שלא במקום חליצה דלפוסלה מן הייבום אי איכא צחצוחי הרוק הוא דפסלה דגזרינן משום רקיקה דבתר חליצה אבל לית בה צחצוחי הרוק לא גזרינן עכ\"ל ורבינו סתם וכתב יבמה שרקקה דם אינה צריכה לרוק פעם אחרת ולא חילק בין מוצצת לשותתת וזהו כדעת הרא\"ש ז\"ל ואח\"כ כתב שרב אלפס כתב דוקא במוצצת כו' לומר שרב אלפס חולק על זה והוא מחלק בין מוצצת לשותתת.","אמר רבה יבמה שאכלה שום או גרגישתא וירקה לאו כלום הוא בס\"פ מ\"ח שם ומפרש טעמא משום דבעינן וירקה מעצמה וליכא:","\u0003ומ\"ש ורב אלפס לא הביא דברי רבה אולי ר\"ל מפני שא\"א בלא צחצוחי רוק וכו'\u0004 ז\"ל הרא\"ש שם רב אלפס לא הביא הא מילתא דרבה אולי ס\"ל דלא גרע מרקקה דם ולא דמי להא דהא אפילו צחצוחי הרוק מעצמה אין כאן אם לא נאמר א\"א בלא לחלוחית רוק ואותו מעט יצא עם רוק זה ונהגו העם למונעה מכל מאכל קודם חליצה עכ\"ל ונראה שיש חסרון לשון בדברי רבינו וצריך להגיה וא\"א הרא\"ש ז\"ל כתב רב אלפס לא הביא דברי רבה אולי ר\"ל כולי:","ומ\"ש רבינו בשם הרמב\"ם וכיוצא בו מדברים המזיבים הרוק נראה דט\"ס הוא וצריך להגיה המרבים במקום המזיבים.","ומ\"ש בשם סה\"ת ז\"ל יזהרו ב\"ד שלא תאכל האשה עדיין באותו יום דשמא אכלה דברים הגורמי' רוק לבא דאמר רבה אכלה תומא או גרגישתא לא חולצת דכתיב וירקה מעצמה וה\"ה רימונים כדאיתא בפרק אע\"פ ושאר דברים שאין עולין על לב אדם עכ\"ל. וכבר כתבתי בסמוך שגם הרא\"ש כתב שנהגו למונעה מלאכול כלום וכ\"כ סמ\"ג וסמ\"ק: כבר נתבאר בסמוך בסימן זה שמצות קריאה ורקיקה לכתחילה מעומד וז\"ל סמ\"ק ובשעת הרקיקה תעמוד היבמה נגד היבם עכ\"ל והטעם שצריכה לעמוד נגד היבם כדי שתרוק נגד פניו:","ואח\"כ מקרין אותה ככה יעשה לאיש אשר לא יבנה את בית אחיו ונקרא שמו בישראל בית חלוץ הנעל משנה ס\"פ מ\"ח (שם) וענתה ואמרה ככה יעשה לאיש אשר לא יבנה את בית אחיו ע\"כ היו מקרין וכשהקרא רבי הורקנוס תחת האלה בכפר. עיטם וגמר את כל הפרשה הוחזקו להיות גומרין כל הפרשה:","ומ\"ש ומצוה לכל העומדים שם לומר חלוץ הנעל ג\"פ שם במשנה ונקרא שמו בישראל בית חלוץ הנעל מצוה בדיינים ולא מצוה בתלמידים ר' יהודה אומר מצוה לכל העומדים שם לומר חלוץ הנעל ג\"פ וגמרא שם תניא א\"ר יהודה פעם אחת היינו יושבים לפני ר' טרפון ובאת יבמה לחלוץ ואמר לנו ענו כולכם חלוץ הנעל חלוץ הנעל חלוץ הנעל וכתבו הרי\"ף והרא\"ש ז\"ל לההוא ברייתא משמע דס\"ל דהכי הילכתא כיון דמייתי לה הלכה למעשה וכן פסקו שאר הפוסקים ז\"ל. וכתב בהג\"מ בשם ר\"י גאון שגם היבמה אומרת ג\"פ חלוץ הנעל וכ\"כ המרדכי:","\u0003נמצא סדר חליצה קוראה מאן וכו'\u0004 עד או שקראה ואח\"כ רקקה חליצתה כשירה מימרא וברייתא שם:","ומ\"ש ולא עוד אלא אפי' לא קראה ולא רקקה אלא שחלצה בלבד החליצה כשירה משנה שם (דף קד י) חלצה ורקקה אבל לא קראה חליצתה כשירה קראה ורקקה אבל לא חלצה חליצתה פסולה חלצה וקראה אבל לא רקקה ר\"א אומר חליצתה פסולה ר' עקיבא אומר חליצתה כשירה א\"ל ר\"א ככה יעשה כל דבר שהוא מעשה מעכב א\"ל ר' עקיבא משם ראיה ככה יעשה לאיש כל דבר שהוא מעשה באיש ופירש\"י דכתיב ככה יעשה דבר שהוא מעשה מעכב דכי כתיב ככה דמשמע עיכוב אמעשה כתיב וקריאה דיבור בעלמא הוא: מעשה באיש. חליצה שהאשה עושה מעשה בגופו של איש לאפוקי רקיקה דלאו מעשה באיש הוא ובגמרא (דף קה.) תניא חלצה ולא רקקה ולא קראה חליצתה כשירה ואוקימנא כר\"ע וידוע דהלכה כמותו: וכתב הרמב\"ם אהא דאמרינן דקריאה לא מעכבא בד\"א כשהיו יכולים לדבר שהרי הן ראויים לקרות אבל אלמת או אלם אינם חולצין ואם חלצו חליצתן פסולה ואינן כחרש וחרשת שחלצו שלא עשו כלום לפי שהחרש או החרשת אינן בני דעת עכ\"ל:","צריך שיכוונו היבם והיבמה שתהא מותרת לזר בחליצה זו נתכוין הוא ולא נתכוונה היא או נתכוונה היא ולא נתכוין הוא לא הותרה ומיהו חליצה היא לפוסלה על האחין בסוף פרק מ\"ח (דף קו.) א\"ר יוחנן אני שונה בין שנתכוין היא ולא נתכוונה היא בין שנתכוונה היא ולא נתכוין הוא חליצתה פסולה עד שיתכוונו שניהם כאחת:","ומ\"ש לפיכך יבמה שגדלה בין האחים וראינו שחלצה נעלו של אחד מהן אסורה להתייבם שמא כיוונו לשם חליצה אבל כל זמן שלא ראינו שחלצה לאחד מהם מותרת להתייבם שמא וכו' בריש פרק מ\"ח (דף קב:) אמר רב יבמה שהגדילה בין האחין מותרת לינשא לאחד מן האחין ואין חוששין שמא חלצה סנדל לאחד מהם טעמא דלא חזינא הא חזינא חיישינן והא תניא בין שנתכוין הוא ולא נתכוונה היא בין שנתכוונה היא ולא נתכוין הוא חליצתה פסולה עד שיתכוונו שניהם כאחד ה\"ק אע\"ג דחזינא אין חוששין שמא כיונו וא\"ד טעמא דלא חזינא הא חזינא חוששין ודקאמר תנא בעי כוונה ה\"מ לאישתרייא לעלמא אבל לאחין מיפסלא וידוע דהלכה כלישנא בתרא: \u0005ב\"ה ויש לתמוה על הרמב\"ם ורבינו גבי יבמה שגדלה בין האחים שמא כיוונו לשם חליצה מאי איריא שכיונו אפילו לא כיונו נמי מיפסלא על האחים ונ\"ל דלרווחא דמילתא נקטו הכי אבל אין ה\"נ דאפי' לא כיונו נמי מיפסלא על האחים ועי\"ל דהא דמיפסלא היינו משום דחיישינן שמא נתכוונה היא אבל אם היה ידוע לנו שגם היא לא נתכוונה לא מיפסלא:\u0006","ומ\"ש וכן אם רקקה לפני היבם בפני בית דין אסורה להתייבם שם (ד' קד.) שלחו ליה לאבוה דשמואל יבמה שרקקה תחלוץ מכלל דאיפסלא לה מן האחין ואוקימנא כר\"ע דאמר רקקה ולא חלצה ולא קראה חליצתה פסולה קראה ולא חלצה אין כאן בית מיחוש. ופירש\"י חליצתה פסולה. ופוסלת על האחין אין כאן בית מיחוש ואפילו מייבום לא פסלה: ומאי שנא רקיקה ומ\"ט קריאה קריאה דאיתא בין בתחילה בין בסוף לא מיחלפא ליה רקיקה דבתחילה ליתא ולבסוף איתא מחלפא ליה ואתי למישרי חלוצה לאחין ופי' רש\"י קריאה. בין קודם חליצה מאן יבמי בין לאחר חליצה ככה יעשה א\"נ אמרינן תתייבם לא מיחלפא לאינשי בחלוצה דליכא למימר הך בתר חליצה אתייבם דאמרי הך קריאה דמקמי חליצה הואי אבל רקיקה דליתא אלא בתר חליצה מיחלפא לאינשי ויאמרו הך מדרקקה ודאי חלצה לה ברישא ואפ\"ה הדרא ומתייבמה ואתי למישרי חלוצה לאחין:","ומ\"ש רבינו דדוקא ברקקה בפני ב\"ד הוא דאסורה להתייבם מתבאר ממה שכתבתי בסמוך דטעמא משום דמיחלפא להו לאינשי ואתו למשרי יבמה לאחין והאי טעמא לא שייך אלא ברקקה בפני ב\"ד ובפני היבם. וכ\"כ ה\"ה בפ\"ד על ההיא דיבמה שגדלה בין האחין אין חוששין שמא חלצה לאחד מהן מכאן כתבו קצת מן המפרשים שמה שנזכר למעלה רקקה בלבד ה\"ז חליצה פסולה אינו אלא כשרקקה בב\"ד אבל רקקה בינו לבינה או בפני שנים אינה פוסלת וזה דעת הרמב\"ן והרמב\"ם ז\"ל עכ\"ל וכ\"כ נמק\"י אההיא דיבמה שגדלה בין האחין אין חוששין שמא חלצה לאחד מהם דאסיקנא טעמא דלא חזינא הא חזינא חיישינן ש\"מ דאפי' שלא בב\"ד חיישינן שמא כיונו ופסולה על האחין ומיהו כיון דלא פסלי' להו מדינא אלא מפני מראית העין מסתברא דהיינו דוקא במעשה כי האי דלאו אורח ארעא בהכי אבל רקיקה דלא איפשר בלאו הכי לא חיישינן לה למיפסלא בהכי דאלת\"ה כל יבמה סנדלה בין אחין תאסר להם דהא א\"א שלא רקקה בפניהם ולקמן פסלינן רקיקה בב\"ד אלא לאו ש\"מ כדאמרן וכ\"נ מדברי הרמב\"ן ז\"ל עכ\"ל:","ומ\"ש ומיהו דוקא כשרקקה רוק אבל רקקה דם לפניו אינה נפסלת בכך אא\"כ יהא רוק מעורב בו כ\"כ הרא\"ש בפסקיו בפרק מ\"ח בשם הראב\"ד ז\"ל וכתבתיו לעיל בסימן זה גבי דין יבמה שרקקה דם: וכתב הרא\"ש ק\"ל כיון דאמרינן יבמה שרקקה תחלוץ אמאי אדחיקו הנך אמוראי לקמן להטעותו כיון שעמדו היבם והיבמה לפניהם יאמרו לה שתרוק בפנינו ונפסלה לו ואח\"כ יכפוהו לחלוץ ואי לית להו להנהו אמוראי הא דשלחו לאבוה דשמואל א\"כ לאו דהלכתא היא ורב אלפס הביאה לפסק הלכה ונ\"ל דשפיר אית [להו] להנהו אמוראי והא דלא אמרו לה לרוק בפנינו משום דלא מהניא רקיקה הכא לפסול כדאמרינן לעיל יבמה שגדלה בין האחין מותרת לינשא לאחד מהן ואין חוששין שמא חלצה סנדל לאחד מהם ופריך טעמא דלא חזינא הא חזינא חיישינן שמא כיונה והא תניא בין שנתכוין הוא ולא נתכוונה היא וכולי חליצתה פסולה עד שיתכוונו שניהם ומסיק דכי [חזינן] חיישינן שמא כיוונו אלמא אף חליצת הסנדל לא מהניא לפסול בלא כיונה כ\"ש רקיקה והני עובדי דלקמן דידעי ביה שלא היה רוצה לחלוץ רקיקה לא פסלה ידוע הוא שלא כיון עכ\"ל: כתבו הגהות מיי' צריכה היבמה להזהר שלא תרוק לפני היבם שהרקיקה פוסלת לייבום וא\"כ תהיה החליצה פסולה כיון שאינה ראויה ליבום ותצטרך לחזור על כל האחים וכ\"כ במרדכי מקבלת אבי\"ה וכתב ואע\"פ שיש להשיב טוב הדבר ליזהר בכך:","\u0003ומ\"ש רבינו ואם קראה לבד לא נפסלה בכך מלהתייבם כבר נתבאר:\u0004 ","הסומא לכתחילה לא יחלוץ ואם חלצה מהסומא חליצתה כשירה בפ' מ\"ח (דף קג:) תניא חולצת מן הסומא חליצתה כשירה וכתבו התוס' וא\"ת מהיכן ס\"ד למעוטי סומא וי\"ל מדכתיב לעיני הזקנים ס\"ה לעיני יבם א\"נ משום דכתיב וירקה בפניו דהוי כמו לעיניו קמ\"ל דלא עכ\"ל: והרמב\"ם ז\"ל כתב בלשון הזה סומא אינו חולץ שנאמר וירקה בפניו ואין זה רואה הרוק וכתב ה\"ה ממ\"ש בברייתא החולצת מן הסומא חליצתה כשירה למד רבינו שאין חולץ לכתחילה ונתן טעם לדבר משום דכתיב וירקה בפניו אבל בדיעבד כשירה שהרי אין הרקיקה מעכבת ובהשגות א\"א והוא שיש שם מי שיחלוץ ע\"כ סבור הוא ז\"ל דכל היכא דליכא אחרינא אפי' לכתחילה חולץ וברייתא דמשמע דוקא דיעבד הוא בשיש שם אחר ואיני יודע הכרח בזה עכ\"ל ואני מצאתי כתוב בשם גדולי אשכנז דטעמא דהראב\"ד משום דאין לך דיעבד גדול מזה שלא תתעגן ומצאתי עוד דלענין הלכה למעשה יש לחוש דדילמא הראב\"ד ס\"ל כמ\"ד מצות חליצה קודמת ולהכי חשיב כדיעבד משום עיגונא אבל לפוסקים כמ\"ד מצות יבום קודמת מנא לן דחשיב דיעבד ע\"כ :","חליצת חרש ואלם ואלמת פסולה ופוסלת אבל שוטה וקטן אין חליצתן כשירה בפרק מ\"ח (דף קד:) תנן החרש שנחלץ והחרשת שחלצה והחולצת לקטן חליצתה פסולה ובגמרא (שם) אמר רבי ינאי דטעמא דחרש וחרשת לפי שאינן בואמר ואמרה אמר רבא השתא דאמרת קריאה מעכבא לפיכך אלם ואלמת שחלצו חליצתן פסולה ומתניתין דקתני לא קראה חליצתה כשירה כר' זירא דאמר כל הראוי לבילה ואמאי דתנן דחולצת לקטן חליצתה פסולה א\"ר יהודה אמר רב זו דברי ר' מאיר אבל חכמים אומרים אין חליצת קטן כלום כלומר ואינה נפסלת לאחין ויכולה להתייבם להם ולו. והרמב\"ם ז\"ל כתב בלשון הזה אלם או אלמת אינם חולצין ואם חלצו חליצתן פסולה ואינן כחרש וחרשת שלא עשו כלום מפני שהחרש והחרשת אינן בני דעת וכתב ה\"ה מ\"ש שחליצת חרש או חרשת אינה כלום נראה שסמך לו על התוספתא ששנינו שם חרש שנחלץ וחרשת שחלצה והחולצת מן השוטה וכן שוטה שחלצה והחולצת מן הקטן כו' תצא וי\"ג דברים בה הרי השוו דין חרש שוטה וקטן ויתבאר בגמרא שאין חליצת קטן כלום וכן השוום חכמים בכל מקום לכל דבר שצריך דעת ויש מי שהקשה על רבינו מדאמר בגמרא אבל חכמים אומרים אין חליצת קטן כלום ולא אמר אין חליצתן כלום אלמא מודו חכמים בחליצת חרש וחרשת דחליצה פסולה היא ועוד ממ\"ש שם בגמרא דטעמא דמתניתין לפי שאינן באמר ואמרה ואמר רבא השתא דאמרת קריאה מעכבא וכו' אלמא טעמא דמתני' אינו משום דלאו בני דיעה נינהו אלא לפי שאינם ראויים לקריאה והרי הם כאלם ואלמת ויש לדחוק בזה לדעת רבינו דלהכי מפרשים טעמא דמתניתין משום קריאה לאשמועינן דאפילו אלם ואלמת חליצתן פסולה ומיהו אינן שוין בדינן אלא הא כדאיתא והא כדאיתא ושמואל דאמר אין חליצת קטן כלום ולא קאמר אין חליצתן כלום משום דמשמע ליה דמשום קטן בלחוד תני במתני' חליצה פסולה אבל בחרש וחרשת אפילו תנא דמתניתין מודה דאינו כלום ואגב גררא דקטן נקט בהו פסולה הילכך לא איצטריך ליה אלא קטן א\"נ דפלוגתא דר\"מ וחכמים בקטן שמיע ליה באינך לא שמיע ליה ומש\"ה לא כייל להו ומיהו אנן סמכינן על התוספתא שהיא משוה אותן וזה התירוץ יותר נכון כנ\"ל לדעת רבינו אבל הרמב\"ן והרשב\"א ז\"ל סוברים שהחרש והחרשת הרי הם כאלם ואלמת ואינן כשוטה לכל דבר וכ\"נ מן ההלכות עכ\"ל :","קטנה שחלצה לגדול נפסלה על האחין בפרק מצות חליצה (שם) תנן קטנה שחלצה תחלוץ משתגדיל ואם לא חלצה חליצתה פסולה ובגמרא (דף קה:) אמר רב יהודה אמר רב זו דברי ר\"מ אבל חכמים אומרים איש כתיב בפרשה אבל אשה בין קטנה ובין גדולה רבא אמר עד שתגיע לעונת הנדרים והלכתא עד שתביא ב' שערות וכיון דאסיקנא דעד שתביא שתי שערות משמע דכל שחלצה קודם לכן הויא פסולה וכך הם דברי הרמב\"ם ז\"ל:","ומ\"ש רבינו וא\"א הרא\"ש ז\"ל השוה חליצת קטנה לחליצת קטן לא מצאתי כן בדברי הרא\"ש אלא בדברי התוס' שכתבו וא\"ת כיון דתנא פסולה אמאי תני שתחלוץ משתגדיל ועוד דלא תני ליה גבי קטן וי\"ל דאי לא הוה תני גבי קטנה ה\"א דחליצתה פסולה דהא מקשינן אשה לאיש מן התורה להכי תני תחלוץ משתגדיל ייתור לשון לאשמועינן דחליצת קטנה אינה כלום כמו חליצת קטן ע\"כ ומ\"מ יש לתמוה היאך כתב רבינו כן בשם הרא\"ש כיון שלא נמצא כן בדבריו ועוד שגם התוספות לא כתבו כן לקושטא דמילתא שהרי כתבו אח\"כ ומיהו בירושלמי גרסינן בסדר המשנה תחלוץ משתגדיל ואם לא חלצה חליצתה כשרה ע\"כ וכיון שהם מסופקים אי גרסינן חליצתה כשרה היאך אפשר לכתוב בשמם דחליצת קטנה אינה כלום כמו חליצת קטן ודע שגירסת רב אלפס כגירסת הירושלמי ומ\"מ כיון דאסיקנא דהלכתא עד שתביא שתי שערות משמע דקודם לכן חליצתה פסולה :","חליצה מוטעת כשרה ה\"ד חליצה מוטעת שאומרים לו חלוץ לה ע\"מ שתתן לך כך וכך ברייתא בפרק מ\"ח (דף קו.).","ומ\"ש אפילו אינה נותנת לו כלום כך פירש\"י ונתן טעם כדמפרש בפרק המדיר (כתובות עד.) דכל תנאי מתנאי בני גד ובני ראובן ילפינן ליה שהיה איפשר לעשות ע\"י שליח וכל שא\"א לעשות על ידי שליח כגון חליצה אין תנאי מועיל בה ואע\"פ שלא נתקיים התנאי המעשה קיים וכ\"כ הרא\"ש ז\"ל וכ\"פ הרמב\"ם ז\"ל שאע\"פ שלא נתנה ולא נתקיים התנאי חליצתה כשרה: וכתב ר\"י ואפי' התנה בתנאי כפול ופשוט הוא וכן כתב הרא\"ש בתשובה שאכתוב בסמוך:","\u0003ומ\"ש רבינו דמ\"מ היא חייבת ליתן לו מה שהתנה כשאר שוכר כו'\u0004 אבל אם יש טענה שאינה חפצה בו והוא חייב לחלוץ אלא באינו רוצה יכולה לומר משטה אני בך ואינה צריכה ליתן לו כלום שם בת חמוה דרב פפא נפלה לפני יבם שאינו הגון לה אתא לקמיה דאביי אמר ליה חלוץ לה על מנת שתתן לך ק\"ק זוג לבתר דחלץ לה אמר לה זיל הב ליה אמרה ליה משטה אני בך עבדא ליה וכתב הרא\"ש ז\"ל ופירש\"י זיל הב ליה דהא קבילת עלך ואף על גב דחליצה בהכי לא מיפסלא מיהו מיחייב לקיומי תנאי מדינא כשאר שכירות דעלמא ולהכי פירש מטעם שכירות ולא מתנאי שהתנה מתחלה ליתן לו משום דהאומר ע\"מ אין מחייבין אותו לקיים התנאי אלא אם ירצה לקיים התנאי יתקיים המעשה מעכשיו ואם ירצה לא יקיים התנאי ויתבטל המעשה למפרע הילכך בנדון זה משום תנאי לא מיחייבה למיתב ליה אלא הכי קאמר ליה כיון דאי איפשר לה לחליצה להתבטל ה\"ל כשכירות דעלמא א\"ל משטה אני בך עבדא ליה דכיון דלא הוה הגון לה ולא בעיא ליה מה שקצבה ליתן לו דמי יתירי כעין אנוסה היא וגם איהו לא פסיד מה מידי עכ\"ל. וכן כתב עוד הרא\"ש בתשובות ודברי ר\"י שכתב בשם הרמ\"ה והתוספות נראה בחולקים על זה כתוב בתשובות הרשב\"א סימן אלף ור\"מ אם הקדימה ונתנה לו אין השטאה אחר נתינה וקרוב בעיני בכל שחלץ קודם שנטל מעות באין מוציא מיד האשה ואפילו חייבה עצמה לו בשטר ואפילו בקנין ועיין במרדכי בפרק החולץ:","אמרו לו חלוץ לה ובכך אתה כונסה אינה חליצה להתירה ומ\"מ נפסלה בכך להתייבם וכופין אותו לחלוץ חליצה כשרה בסוף פ' מ\"ח (שם) ת\"ר חליצה מוטעת כשרה אי זו היא חליצה מוטעת אמר ר\"ל כל שאומר לו חלוץ לה ובכך אתה כונסה א\"ל ר\"י שונה אני בין שנתכוין הוא ולא נתכוונה היא בין שנתכוונה היא ולא נתכוין הוא אני שונה חליצתה פסולה עד שיתכוונו שניהם כאחד ואת אמרת חליצתה כשרה אלא כל שאומרים לו חלוץ לה על מנת שתתן לך ק\"ק זוז ובר\"פ (קב:) גבי הא דא\"ר יהודה אמר רב יבמה שהגדילה בין האחים מותרת לינשא לאחד מהם ואין חוששין שמא חלצה סנדל לאחד מהם אסיקנא דטעמא דלא חזינא הא חזינא חיישינן דהא דתניא דבעינן כוונה ה\"מ לאשתרויי לעלמא אבל לאחין מיפסלא ובסוף הפרק הנזכר (דף קו.) מייתי עובדא ביבמה שאמרה לרבי חייא בר אבא שאינה רוצה להתייבם מפני בלא היה רוצה היבם ליבמה אלא משום דחזאי לה ממונא ורוצה לאכלו ולכלותו ולגרשה וכתב הרא\"ש שהיתה כעורה ומפני כך האמינה ר' חייא בר אבא א\"ל חלוץ לה ובכך אתה כונסה א\"ל השתא מינך איפסלא לה חלוץ לה חליצה מעלייא כי היכי דתשתרי לעלמא וכתב ה\"ה על מעשה זה שכתב הרשב\"א ז\"ל מסתברא שכופין אותו בכך עד שיאמר רוצה אני ואפילו בשוטים דכיון דאסירא ליה מעתה ה\"ז חייב להוציאה והכי איתא בירושלמי וטעמא דמילתא דכיון דאסור ליה מדרבנן לא מעגנין לה עכ\"ל כתב הרא\"ש בתשובה כלל נ\"ב ס\"ו חלוץ ע\"מ שתתן לך ר' זוז אפילו אם כפל התנאי ואמר אם לא תתני לי ק\"ק זוז לא תהיה החליצה חליצה אפ\"ה החליצה כשרה דאין תנאי מועיל בחליצה משום דלא איפשר למעבד ע\"י שליח כתנאי בני גד ובני ראובן שיהושע היה שלוחו של משה ליתן להם את הארץ וכתב עוד שם שאפילו אמר בשעת חליצה אני חולץ ע\"מ שלא תנשאי לשום אדם ואם תנשאי לשום אדם לא תהיה החליצה חליצה מותרת לינשא עכ\"ל: \u0005ב\"ה ואני תמה על זה דאע\"ג דמדין תנאי לא הוי תנאי כדבסמוך מ\"מ כיון שהוא סובר שתנאו קיים שלא תינשא לשום אדם נמצא שלא נתכוין להתירה בחליצה זו וכל שלא נתכוין להתירה בחליצה זו לזר לא הותרה כמו שנתבאר בסימן זה ושמא יש לחלק דשאני הכא שהוא סובר חליצה זו מתירה להנשא לזר ולכך מתכוון ואינה נאסרת לפי דעתו אלא מצד התנאי \u0006 ועיין ברבינו ירוחם: כתב הרמב\"ם ז\"ל חליצה מוטעת פסולה כיצד כגון שאמרו לו חלוץ לה ובכך אתה כונסה או שאמרו לו חלוץ לה שזו מצוה היא ואינה מפסדת עליך כלום ואם תרצה אחר כך לייבם תייבם וכיוצא בדברים אלו פסולה וכתב ה\"ה מ\"ש רבינו או שאמרו לו חלוץ לה שזו מצוה היא וכו' נראה שהוציאו ממה שאמרו בירושלמי רשב\"ל אומר כל שאומר לו חלוץ לה והיא ניתרת לך לאחר זמן ונחלק עליו רבי יוחנן עוד שם בירושלמי אתא עובדא קמיה דר' חייא בר אבא א\"ל האשה הזאת אינה רוצה לך דרך יבום אלא חלוץ לה ועקור זיקתה הימנה והיא נישאת לך דרך נישואין מדחלץ לה א\"ל אי אתי משה ושמואל לא שרו לה: וכתב הרשב\"א ז\"ל שהמעשה הזה הלכה הוא ואפילו רבי יוחנן מודה בזה דכיון שהוא מתכוין לחלוץ להתירה באותה חליצה אף על פי שטועה שיועיל לו מצד אחר כשרה ואין נראה כן מדברי רבינו אלא המעשה אתא כר\"ל ואינו כהלכה ומה בין זה למה שאמר ר\"ל שם חלוץ לה והיא ניתרת לך לאחר זמן ואיפשר שכיון שפירשו לו בכאן שהוא עוקר זיקתה הימנה חליצתה כשרה היא עכ\"ל:","\u0003חליצה מעושת שלא כדין על ידי דייני ישראל שכפו לחלוץ וכו'\u0004 עד כפוהו דייני ישראל ע\"י דיוני עכו\"כ. סככוהו עכו\"ם לעשות מה שישראל אומרים לו כשרה כל זה נתבאר בסי' קל\"ד לענין גט ובפמ\"ח שם ת\"ר חליצה מוטעת כשרה גט מוטעה פסול חליצה מעושית פסולה גט מעושה כשר ה\"ד אי דאמר רוצה אני אפי' חליצה נמי ואי לא אמר רוצה אני גט נמי לא ה\"ק חליצה מעושית וגט מעושה זימנין כשר וזימנין פסול הא דאמר רוצה אני הא דלא אמר רוצה אני ומדהשוו חליצה מעושית לגט מעושה משמע דשוים הם לכל דיניהם וכן פסק הרמב\"ם ז\"ל ומ\"ש רבינו שהרמב\"ם חילק בדין כפו עכו\"ם מעצמם והדין נותן שיחלוץ נוסחא משובשת נזדמנה לו בדברי הרמב\"ם: כתב בתשובות הרשב\"א בסי' אלף ור\"מ מדברי בעל הלכות נראה דכל שהיבמה אינה רוצה להתייבם וב\"ד רואים שיכניס קטטה לתוך ביתו כאותה שאמרו ב\"ד קורין אותו ונותנים לו עצה ההוגנת לו וכו' שאם לא יקבל מהם כופין אותו שיאמר רוצה אני אלא שדברים אלו אינם ברורים בעיני עכ\"ל. והרא\"ש בתשובה חולק על זה : דין מי שחלץ ואח\"כ הראה מודעא שמסר קודם לכן כתב הרא\"ש בתשובות סוף כלל נ\"ב עיין בתשובת הריטב\"א שכתבתי בסימן קס\"ה:","חליצה פסולה אע\"פ שהיא פסולה פוסלת על האחין ופוסלת לכהונה ואוסרת עליו קרובותיה ואינה נישאת לזר עד שתחלוץ חליצה כשרה עברה ונישאת לזר קודם שיחלוץ חולץ לה חליצה כשרה והיא תחת בעלה ואין מוציאין אותה ממנו כך היא הנוסחא האמתית בספרי רבינו המדוייקים וכך הוא לשון הרמב\"ם ז\"ל ומ\"ש דחליצה פסולה פוסלת על האחים ופוסלת לכהונה ואוסרת עליו קרובותיה ואינה נישאת לזר עד שתחלוץ בפרק כל הגט (גיטין דף כד:) א\"ר נחמן אמר שמואל כל מקום ששנו חכמים גט פסול פסול ופוסל חליצה פסולה פסולה ופוסלת ופירש\"י פסולה. להתירה לשוק אבל פוסלת מן האחים שלא תתייבם להם עוד ואע\"ג דבגט לא קי\"ל כשמואל דאמוראי טובא פליגי עליה התם בחליצה משמע דהלכתא כוותיה ואף אם נאמר דהלכה כרבי אלעזר דפליג עליה התם הא לא פליג אלא בקטן ואנפליא בלבד ואע\"ג דנקט במילתיה שמאל ולילה פסולים ופוסלים לאו דוקא הני ולדוגמא נקטינהו ולפי' כתב הרמב\"ם בכולם חליצה פסולה פסולה ופוסלת ובקטן ואנפליא כתב שאינה חליצה כלל. וכתב הריב\"ש בתשובה בסימן תפ\"ב על המוסר מודעא על החליצה אפילו נאמר שהמודעא קיימת אין החליצה בטלה לגמרי אלא שהיא חליצה פסולה דומיא דחליצה מעושית וחליצה מוטעת ואף על פי שהרמב\"ם כתב בפ\"ו מהלכות גירושין דמוסר מודעא על הגט הגט בטל וכל מקום שכתב בטל ר\"ל בטל לגמרי ואפילו ריח גט אין בו כמו שכתב בפרק י' כבר כתב בפ\"ד מה' יבום שהמוסר מודעא על החליצה חליצתה פסולה ושחליצה מעושית על ידי ישראל שלא כדין או ע\"י עכו\"ם שאנסוהו מעצמם כדין פסולה וע\"י עכו\"ם שלא כדין אינה חליצה וכתב בסמוך כל מקום שאמרנו אינה חליצה לא נאסרו עליו קרובותיה ולא נפסדה מן הכהונה ומותרת להתייבם הנה שאינו משוה דין החליצה לדין הגט בזה שאע\"פ שהמוסר מודעא על הגט רוצה שיבטל בטל הוא ואינו כלום אין כן בחליצה אלא חליצה פסולה היא ומועלת לפוסלה מן האחים ולאוסרה בקרובותיה ופסול מן הכהונה ונראה לי שטעם החילוק הזה לדעתו הוא וכו' עכ\"ל וכתב עוד שם חליצה אינה יכול לבטלה קודם חליצה בלא אונס שהרי כשאומר אני רוצה שכל חליצה שאחלוץ תהיה בטלה וידענו שאינו אנוס או שהוא מודה בזה אין בדבריו כלום דהא אתיא מעשה החליצה ומבטל דבריו הראשונים ואם נאמר שדעתו לומר שהוא מבטלה מעתה לאחר שתחלץ הרי לאחר החליצה אינו יכול לבטלה שכבר הותרה לשוק אבל מודעת החליצה הוא שיאמר שהוא אנוס ואנו מאמינים אותו בזה משום דגלויי מילתא בעלמא הוא דומיא דגט או מתנה או אף אם לא יאמר שהוא אנוס אלא שהוא מבטלה סתם נאמר שאומר כן מפני שהוא אנוס על החליצה שאם לא כן מה לו לחלוץ ושיצטרך לבטל קודם לא יחלוץ ולא יבטל וכיון שאין מודעת החליצה אלא מחמת אונס אין החליצה בטלה מחמתה אלא שהיא חליצה פסולה ופוסלת כמו בחליצה מעושית עכ\"ל ועיין עוד שם. וכתב הרב המגיד מ\"ש שאם עברה ונישאת בחליצה פסולה שאין מוציאין אותה מידו נראה ודאי שמפריש אותה עד שיחלוץ לה חליצה כשרה ואם לא כן כוונת רבינו קי\"ל שהרי משמע בגמרא במקצת מקומות שהזכירו חליצה פסולה שמן התורה אינה כלום ואם כן היאך תעמוד עם בעלה בלא חליצה וצריך עיון עד כאן לשונו ודברים פשוטים הם בעיני שהרי לא בא הרמב\"ם ז\"ל אלא ללמדנו שאין אוסרים אותה עליו אף על פי שעברה ונישאת בלא חליצה כשרה אבל דבר פשוט הוא דכיון שהיא צריכה לחלוץ שמפרישין אותה עד שתחלוץ חליצה כשרה:","לאחר שתחלוץ כותבים לה בית דין שחלצה בפניהם גט חליצה להתירה לינשא ואם לא כתבוהו לה כל שנים שראו החליצה יכולים לכתבו אע\"פ שאינם מכירים וכו' מימרא דרבא בסוף פרק מצות חליצה (יבמות דף קו:):","\u0003וצריך לשרטטו מפני מקראות שבו שם מר זוטרא משרטט וכתב לה לכולה פרשתא:\u0004 ","\u0003לשון א\"א ז\"ל סדור חליצה מצות חליצה בשלשה שיודעים להקרות וכו'\u0004 עד סוף הסימן הכל בפסקים ס\"פ מצות חליצה:","ומ\"ש ואחר החליצה יתנהו לדיינים היינו לומר שחוזר ונותנו להם במתנה כדי שיוכלו להקנותו לאחרים אי נמי מפני שמתחלה לא נתנוהו לו אלא על מנת שיחזירהו להם ואם לא יחזירהו להם נמצא שלא זכה במתנה והוי ליה חולץ במנעל שאינו שלו.","ומה שאמרו חותמין עליה תלתא כתב רבינו ירוחם בשם הרמ\"ה ואם לא יחתמו אלא שנים עדות הוא וכשר: וכתב הרשב\"א בתשובה יחתמו הג' שנעשו ב\"ד ולא השנים שניתוספו :","ומ\"ש ולא בעיא לאמתוני לבתר חליצה ג' ירחי כ\"כ ר\"י והטעם מפני שאינה חולצת עד שיעברו ג' חדשים ממיתת הבעל כמבואר בראש סי' זה. כתב הריב\"ש סי' שפ\"ב על גט חליצה שזמנו מוקדם שהיה זמנו שנת ה' אלפים וקל\"ד וחסר ממנו ל' וכתב וק\"ד ורצה לפסלו והאריך בדבר וכתב על זה להר\"ן בתשובות הר\"ן סי' י' כתוב שהשיב להתיר ומיהו כתב בסוף דבריו ומ\"מ אם הדבר מזדמן שיתוקן המעשה ב\"ד קודם שתינשא הנה מה טוב ואם אין אין ראוי לעגנה בשביל זה והריב\"ש סי' שפ\"ה כתב לחכם אחד ע\"ז וז\"ל ואתה האדון הפרזת על מדותיך והכשרת מוקדם בגט חליצה אפי' הקדימוהו לדעת לפי שלדעתך אין בהקדמתו תועלת והפסד ואפי' בעל הריב לא אמר להתיר אלא מפני שתולה שנעשה בשכחת הסופר אבל להתיר מוקדם לדעת ראה זה חדש הוא ומה שכתבת שיש לחוש שגט חליצה זה נעשה בזמנו לאשה אחרת ששמה כשמה ושם היבם ובעלה כשם אלו זה ודאי אמת ויציב אין ספק בו וגם אני הרגשתי בטענה זו ובספק הזה כתב לי החכם אחי כי הוא ודון חסדאי עוררהו לרבינו הר\"ן והודה בו להצריך בדיקה אם ימצא שם מי ששמה כשמה ושמו כשמו מן היום ההוא והלאה והתנצל על התירה סתם בתשובתו לשואל ולא אמר להצריכה בדיקה זו באמרו כי לרוב פשיטותו לא היה צריך לבאר זה ואין בזה די התנצלות כבודו במקומו מונח עכ\"ל וכתב עוד שם דגט חליצה לעולם צריך קיום אף בלא ערער אפי' יוצא מתחת ידה אף למי שאינו מצריך בגט אשה משום דליכא טעמא להאמינה משום חומר שהחמרת בסופה וא\"כ בנדון זה שהוא יבמה ובמקום שאין עדים מצויים לקיימו דהא ממדינה למדינה הוא צריכה היא קיום וכ\"ש למ\"ש הרשב\"א בשם ר\"ת דהאידנא כל שבא מחוץ לעיר הוי כמו ממדינה למדינה דדיינינן להו כבני מחוזא דניידי עכ\"ל:"],["\u0003בא לחלוץ וכו'\u0004 ישראלים כשרים שלא יהיו קרובים כו' פירוש ישראלים ולא גרים כשרים ולא פסולים מחמת עבירה ושאר פסולים שפוסלים את הדיין ושלא יהא קרובים וכו' אח\"כ אמר נמצא אחד מהם קרוב או פסול או גר כו' החליצה פסולה כיון דליכא אלא ב' דיינים ומיהו חליצה פסולה מיהא הוי אפילו ביחיד ואפילו בינו לבינה לפוסלה על האחין:","\u0003ומ\"ש אפי' היה אביו גר ואמו מישראל פסול וכו'\u0004 כך הוא משמעות פשט הסוגיא בפ' מ\"ח ריש (דף ק\"ב) וכך פירש\"י בישראל משמע שיהא ישראל מכל צדדין ומ\"ש ובסמ\"ק הכשיר אמו מגרים רק שיהא אביו מישראל כ\"כ התוספות בפרק מ\"ח אבל בסמ\"ק שלנו כתוב בסימן קפ\"ה וצריך שלא יהא אחד מהדיינים גר ואם היתה אמו מישראל כתב ב\"י דכ\"כ בספר כל בו וט\"ס הוא וצ\"ל אביו במקום אמו וכ\"כ בפירוש סדר חליצה ס\"ה דנראה ט\"ס בסמ\"ק ובכל בו שאין לישבה ע\"פ הגמרא גם מהרש\"ל הגיהו וכן הגיהו בכל בו בדפוס ויניציאה שנת ש\"ז אכן ספרי הסמ\"ק הישנים שבכולן כתב דבאמו מישראל כשר וכמ\"ש ב\"י בשמו ובשם הכל בו לא הניחו דעתי להסכים ולומר דט\"ס הוא אלא נראה דתפס לו דרך אחר בסוגיית הגמרא דרך ישר בלי מכשול ובלי דוחק והוא דה\"א התם אמר רבא גר דן את חבירו ד\"ת שנא' שום תשים עליך מלך וגו' עליך הוא דבעינן מקרב אחיך אבל גר דן את חבירו גר ואם היתה אמו מישראל דן אפי' ישראל ולענין חליצה עד שיהא אביו ואמו מישראל שנאמר ונקרא שמו בישראל ומפירש\"י והתוס' מבואר דמפרשים והא דקאמר ולענין חליצה וכו' פירושו ולענין חליצת ישראל אלא דלפירש\"י בעינן תרוייהו מישראל ולפי' התוספות סגי באביו לחוד מישראל אלא שהקשו מנ\"ל דבעינן אביו מישראל בחליצת ישראל דילמא סגי באמו מישראל בלחוד כיון דהוי מקרב אחיך וקרא דנקרא שמו בישראל לא אתא אלא ללמד דלחליצת גרים צריך שיהא ישראל מעלמא דהיינו שהיתה הורתו ולידתו בקדושה כדקאמר תלמודא בפרק נערה שכתפתתה (דף מ\"ד) ואור\"י כיון דחליצת גרים לא משכחת לה אלא בשני אחים דהורתן ולידתן בקדושה דהוו ישראל מעליא וקרינן בהו עליך א\"כ בלא ונקרא שמו בישראל נפקא לן דפסול גר לחליצת בני גרים דבעינן מקרב אחיך עד שתהא אמו מישראל אבל בהורתו ולידתו בקדושה אעפ\"י דישראל מעליא הוא וקרינן בהו עליך מכל מקום לא קרינן בהו מקרב אחיך אם אין אמו מישראל וא\"כ בע\"כ דאייתר בישראל לאצרוכי אביו מישראל ולפ\"ז הא דרב שמואל בר יהודה דלא רצה לישב בב\"ד של חליצה לפי שהיה גר ותנינא בישראל בב\"ד של ישראל ולא בב\"ד של גרים צ\"ל דהיתה אמו מישראל דהא לא איצטריך לאתויי לברייתא למיפסליה אלא באותו שאמו מישראל עכ\"ל וכ\"כ בפרק נערה ופירוש זה הוא סותר מה שפי' רש\"י ואנא גר אנא הוא ואביו נתגיירו וסותר ג\"כ מ\"ש התוספות לשם בשם ר\"ת בד\"ה ואנא גר אנא דרב שמואל בר יהודה היה בן רב יהודה הינדווא דגר שאין לו יורשין הוה דנתגייר הוא ובניו ומפני סתירות אלו ס\"ל לסמ\"ק ליישב מה שהקשו התוספות לפרש דהקושיא שהקשו התוספות הוא בעצמו פשט הסוגיא וה\"ק רבא בשאר דינים גר דן את חבירו גר ולישראל אינו דן אלא אם כן באמו מישראל שנאמר מקרב אחיך וגו' וה\"ה אם הורתו ולידתו בקדושה דקרינא ביה מקרב אחיך ולענין חליצה בין חליצת ישראל בין חליצת גרים עד שיהא אביו או אמו מישראל ולשון אביו ואמו דקאמר פי' אביו או אמו כמו מכה אביו ואמו ומייתי מקרא ונקרא שמו בישראל דכל שהוא מישראל או אביו או אמו בישראל קרינן ליה וליכא למימר דקרא בישראל אתא לאורויי דלחליצת גרים סגי בהורתו ולידתו בקדושה דישראל מעליא הוא דא\"כ ונקרא שמו בישראל ל\"ל הא ודאי כיון דישראל מעליא הוא מקרב אחיך נמי קרינן ליה ודלא כמה שכתבו התוספות אלא בע\"כ אתא קרא ללמד איפכא דבעינן אמו מישראל או אביו מישראל ואף בחליצת גרים לא סגי בהורתו ולידתו בקדושה אלא בישראל דוקא ולפ\"ז חליצת גרים וחליצת ישראל שוין הן דבאביו או אמו בלחוד כשר והשתא ניחא הא דהשיב רב שמואל לרב יהודה תנינא בישראל וכו' דאף להושיבו בחליצת גרים נמי פסול דגר אנא: ומ\"ש רבינו בסברא הראשונה דאפילו היה אביו גר ואמו מישראל פסול עד שיהא אביו ואמו מישראל כך הוא לשון הרמב\"ם בפ\"ד וקשה דה\"ל לאשמועינן ברישא רבותא טפי דאפילו באביו מישראל ואמו מגר פסול וי\"ל דלישנא דרבא בגמרא נקיטו דקאמר דגר אינו דן לישראל אלא אם כן דאמו מישראל דאשמועינן רבותא דהיתירא בשאר דינים דאפילו באמו מישראל לחוד כשר והדר קאמר ולחליצה עד שיהא אביו ואמו מישראל ולא סגי באמו מישראל כשאר דינים והוא הדין באביו בלחוד מישראל נמי לא סגי בחליצה וכדקאמר עד שיהא אביו ואמו מישראל דמשמעות הלשון דבעינן תרוייהו מישראל ופשוט הוא:","ולכתחילה מצוה שיוסיפו שנים על הג' לפרסומי מילתא ה\"א ר\"פ מ\"ח ופירש רש\"י לפרסומי דחלוצה היא ולא לינסבא לכהן אי נמי דליתו אינשי וליקפצו עליה עד כאן לשונו ונראה דבגרושה לא צריך לפרסומי דמפורסם הוא כיון שהגט בידה ועוד דביבמה סברי אינשי דעלתה ליבום צריך לפרסם דחלוצה היא והעיקר נראה דבגרושה דאין צריך דיינים דסגי בשני עדים לא הצריכו פירסום אבל יבמה דכתיב זקנים ואיכא רבי יהודה דאמר בחמשה אף על גב דהלכה כרבנן דאמרו בשלשה הצריכו חמשה לפרסומי מילתא מדכתיב זקנים:","חלצו בשלשה חליצתן כשרה כתב ב\"י משמע דוקא דיעבד והא ליתא דאפי' לכתחלה סגי בשלשה כדאיתא בס\"פ מ\"ח וכן כתב רבינו גופיה שמצות חליצה בשלשה דיינים עכ\"ל ונראה ליישב דה\"ק דלכתחלה יוסיפו שנים על השלשה ואפי' הן עמי הארץ דליכא למיגזר שמא יושיבו עם הארץ גם בתוך הג' כיון דבדיעבד כשר אם נמצאו עם הארץ בתוך הג' ומכללא נשמע אבל קרובים ופסולים אין להושיב בתוך השנים דכיון דהחליצה פסולה אם הושיבום בתוך הג' איכא למיגזר וקאמר השתא חלצו בשלשה חליצה כשרה כלומר דבדיעבד אפילו הוסיפו בתוך השנים קרובים או פסולים כיון שהשלשה כשרים חליצתן כשרה בדיעבד אף על גב דלאו שפיר עבדי לכתחילה והכי נקטינן:","\u0003ויקבעו מקום וכו'\u0004 כתב הב\"י בפי' סדר חליצה סימן י\"ב ודע שכתוב בקונטרסים ויאמרו זה לזה נלך למקום פלוני ונקבע מקום לחליצה של פלוני וילכו וישבו שם לשם חליצה שנאמר ועלתה יבמתו השערה ויעקרו ממקומם הראשון וילכו למקום השני לחלוץ שם עכ\"ל והבין הב\"י מדקאמר וילכו למקום השני לחלוץ שם דעכשיו הולכים שם לחלוץ מיד בו ביום שקבעו מקום והבין עוד שרוצה לומר שצריכין לקבוע מקום שילכו לישב בו כדי שמשם יקבעו המקום שיחלצו בו כדמשמע מפשטא דלישניה אלא דכתב דדוקא כשהם עומדים ולהכי צריך שישבו במקום קבוע כדי שמשם יקבעו מקום לחליצה כדי שיעקרו משם וילכו למקום שקבעו ואז יהיה היכירא לקביעות שאם היו קובעים מקום לחליצה ועודם עומדים ובו ביום ילכו וישבו שם ויתנו חליצה מיד לא מינכרא מילתא שהיו קובעים מקום אבל אם היו יושבין כבר או במקומם יקבעו מקום פלוני לחלוץ שם שיאמרו זה לזה נלך וכו' ויעקרו ממקומם וילכו למקום ההוא ויחלצו שם מיד דהא איכא היכירא במה שעקרו ממקומם הראשון והלכו למקום אחר וכל זה כשחולצין בו ביום שקבעו מקום אבל אם קובעין מקום ביום שלפני החליצה אפשר דאפי' הם עומדים יכולים לקבוע דשפיר מינכרא מילתא דקביעותא כיון שקבעו מיום לחבירו: וכתב עוד דכשקובעים ביום שלפני החליצה אין צריך שישבו במקום אחד ויקבעו מקום אחר אלא יכולים לקבוע המקום שיושבים בו עכשיו שיאמרו זה לזה במקום הזה שאנחנו יושבים בו עכשיו אנו קובעים לחלוץ בו למחר ושפיר איכא היכירא לקביעות כל זה הוא דעת הבית יוסף לשם כמבואר למדקדק בלשונו ותימה גדולה לפ\"ז חדא הא דמחלק בין עומדים ליושבין כשקובעין מקום ביום שחולצין בו לקובעין מקום ביום שלפניו דאין רמז לחלוקים אלו בתלמודא ולא בפיסקי הגאונים ועוד דלפי פירושו דמה שכתב בתחלה ויאמרו זה לזה נלך למקום פלוני וכולי היינו לומר שצריכין לקבוע מקום שילכו לישב בו כדי שמשם יקבעו מקום שיחלצו בו ואין זה אלא כשהם עומדים הוא תמוה מאוד דלמה הוא קורא למקום הראשון שישבו בו קביעות מקום הלא אין יושבין בו אלא כדי לקבוע מקום אחר לחליצה ועוד היאך אמר על מקום הראשון וילכו וישבו שם לשם חליצה הלא אין ישיבתם לשם אלא כדי לקבוע מקום אחר לחליצה ועוד דמביא על מקום הראשון קרא ועלתה יבמתו השערה ומקרא זה לא נאמר אלא על מקום שחולצין בו לא על מקום הראשון שמשם קובעין מקום אחר לחליצה לפיכך נראה ודאי דאין חילוק בין עומדים ליושבים ובין קובעין מקום ביום שחולצין ובין קובעין מקום ביום שלפני החליצה ולשון קונטרסים הכי פי' ויאמרו זה לזה נלך למקום פלוני ונקבע מקום לחליצה של פלוני לחלוץ שם וילכו וישבו שם לשם חליצה לחלוץ בו ומביא קרא ועלתה יבמתו השערה דמשמע מקום מזומן לכך כדאיתא בריש פרק מ\"ח וכפירש\"י אלמא שצריך לקבוע מקום לחלוץ בו והאי ויאמרו זה לזה וכולי בין עומדים בין יושבים קאמר דיאמרו זה לזה נלך וכו' ויקבעו מקום לחלוץ בו כפי רצונם לחלוץ בו ביום או למחר: ומ\"ש אח\"כ ויעקרו ממקומם הראשון וכו' ה\"ק אל יעלה על דעתיך דלאו דוקא קאמינא שיאמרו זה לזה נלך למקום פלוני וכו' וישבו שם לשם חליצה דה\"ה כשהם אומרים במקום הראשון שעומדים בו או יושבים בו דבאמירה בעלמא שאומרים אנחנו קובעין מקום פלוני לחלוץ בו היום או שאומרים לחלוץ בו למחר שפיר קא עבדי דה\"ל קביעות מקום דאפילו הליכה לא צריך אלא באמירה סגי לכך אמר דליתא אלא צריך שיעקרו ממקומם הראשון בין שהיו עומדים לשם או יושבים בו יעקרו משם וילכו למקום השני דהיינו שיאמרו זה לזה נלך וכו' וילכו וישבו שם לשם חליצה לחלוץ שם כפי רצונם בו ביום או למחר אלא דאם יחלצו בו ביום אין חולצין בשעה שישבו לשם קביעות מקום אלא עומדין משם לאחר שקבעו מקום והולכים לביתם ולאחר שעה או שתים חוזרים והולכים שם לחלוץ בו דמדכתיב השערה אלמא דבעינן מקום מזומן לכך קודם שחולצין ואם היו חולצין מיד בשעה שישבו וקבעו מקום לא היה המקום מזומן לכך מקמי חליצה. וקרוב בעיני דגם הב\"י חזר בו מדבריו הראשונים שהרי בסי\"ג לשם כתב וז\"ל אחר שכתבתי זה ימים רבים מ\"כ בשם מהר\"י ברונא וז\"ל דלקביעות מקום א\"צ לישב שם כלל וכולי אכן נכון לעשות מעשה שתהא מוכח לשם מצוה עכ\"ל נראה דר\"ל דלפ\"ז גם מ\"ש בקונטרסים כך פירושו דנכון לעשות מעשה שתהא מוכח לשם מצוה ולכן יעקרו ממקומם הראשון וילכו למקום השני לחלוץ שם ויאמרו זה לזה נלך למקום פלוני וכו' כמ\"ש בתחלה ולא סגי באמירה בעלמא בלא ישיבה ובלא הליכה וכדפי' ופי' זה הוא האמת ואין חילוק בין עומדים ליושבים ובין חולצים בו ביום ובין חולצין למחר מיהו בכל הקהלות נוהגים לקבוע מקום ביום שלפני החליצה דטפי משמע השערה מקום מזומן לכך כשהוא מזומן ביום שלפניו אבל לקבוע מקום שילכו לישב בו כדי שמשם יקבעו מקום לחליצה נלפע\"ד דאינו נכון אלא אומרים זה לזה נלך למקום פלוני ונקבע מקום לחליצה של פלונית וילכו וישבו שם לשם חליצה ושפיר דמי אפילו אם היו עומדים במקום הראשון ואפילו רצונם לחלוץ בו ביום וכן נוהגין בכל הקהלות שאומר הגדול לחביריו נלך למקום פלוני וכו' ואפילו עומדים. ובבואי לקראקא אמרו לי שמנהגם הוא שאין פותחין דלת בית הכנסת עד שיתאספו הקהל להתפלל מנחה ואז יבואו הדיינים לאולם בית הכנסת ויושבים שם ואומרים זה לזה נלך למקום פלוני ונקבע מקום לחליצה של פלונית והולכים ויושבים שם לשם חליצה ומנהג זה ודאי אינו אלא עפ\"י פי' הב\"י בתחלה במ\"ש בשם הקונטרסים ואף על פי שכתב דבקובעין ביום שלפני החליצה אפשר שאפילו הם עומדים וכו' כיון שלא כתב כך אלא בדרך אפשר חששו והצריכו שיהיו יושבים כדי לקבוע משם מקום אחר לחליצה ואף על פי שנראה פשוט לפע\"ד שדבר זה אינו צריך כלל כדפרישית לא בטלתי המנהג כיון שאין בזה חששא דאיסורא: כתב בת\"ה שאם החליצה ביום ראשון אין קובעין מקום ביום השבת משום דמיחזי כבונה ומתקן אלא בערב שבת קובעין וכתב עליו ב\"י דמה שכתב דמיחזי כבונה ומתקן אין לו טעם עד כאן לשונו. אבל לפעד\"נ דיש לו טעם כעיקר והוא דבפרק כירה (שבת דף מ\"ב) בהא דאין נותנים כלי תחת הנר לקבל שמן המטפטף משום דמבטל כלי מהיכנו פירש רש\"י דהוי כקובע לו מקום ומחברו בטיט ודמי למלאכה עד כאן לשונו אלמא דבקובע מקום לדבר הוי ליה כאלו עושה מלאכת בנין והכי נקטינן דאין קובעין מקום בשבת אלא בין מנחה למעריב כמו בחול ויש מקומות שקובעין מקום קודם תפלת מנחה בין בחול בין בשבת וכך נוהגין בקראקא:","\u0003ויבדקו היבם והיבמה אם הביאו שתי שערות ואם הוא בן י\"ג שנה ויום אחד וכו'\u0004 פירוש דתרתי בעינן שתי שערות ושני גדלות אבל שערות לחוד שומא נינהו ושני גדלות בלחוד נמי לאו כלום הוא ואפי' איכא תרתי לא מהני אלא אם כן דהביא שערות לאחר שהגיעו לכלל שנים וכל זה התבאר לעיל בסימן קנ\"ה וסימן קס\"ז ע\"ש:","\u0003ומ\"ש ואם רואים שגדלו דדיה וכו'\u0004 כ\"כ הסמ\"ק וכתב עוד דהבדיקה ע\"פ נשים כיון שהוחזקה גדולה בשנים וכו' ומשמע דאם אין עדות כשרים ולא הוחזקה בשנים אין לה היתר בעדות נשים אלא בודקין בהטיית דדין ע\"פ אנשים וטוב הדבר בלא גנות וכ\"כ בסה\"ת ובתוס' קידושין (דף סג) כתב ע\"ש ר\"י דסמכינן אקומה כשהיא בעלת קומה כדרך נשים גדולות וחשוב כאילו היו עדים כשרים גם על השנים:","\u0003ומ\"ש ובסה\"ת כתב אם אין השנים ידועות וכו'\u0004 עד א\"צ לבדוק על הגומות איכא לתמוה דלמאי שכתב סה\"ת גופיה דאין אנו בקיאין בגומות כמ\"ש רבינו בשמו בסי' קנ\"ה א\"כ ודאי דלא סמכינן אחזקת השכנים או קול עם ב' שערות וכן אין סומכין על הקומה אם בדקו ולא מצאו אלא ב' שערות דאפילו בעדים כשרים שמעידין על השנים שהוא בן י\"ג ויום א' והיא בת י\"ב שנה ויום א' לא סמכינן על ב' שערות כיון דאין אנו בקיאין בגומות וצריך שיהיו ריבוי שערות או ארוכות כדרך שהם באיש גדול ובאשה גדולה ואם יהיו ריבוי שערות או ארוכות מסתמא הגיע לכלל שני גדלות וא\"צ לא עדים ולא חזקה כלל דעיקר הבירור הוא בריבוי שערות וארוכות והשתא קשה כיון דרבינו כתב כבר בסי' קנ\"ה דבזמן הזה אינן בקיאין להבחין בגומות לא היה צריך לכתוב כאן מ\"ש דסומכין על חזקת שכנים או קול עם ב' שערות כיון דאין אנו סומכין ע\"ז בזמן הזה וקושיא זו קשיא ג\"כ בש\"ע סעיף י\"א מיהו יש ליישב דלא נמנע רבי' מלכתוב כל הדרכים שסומכין עליהם כשבקיאין בגומות וכן מה שסומכין עליו בזמן הזה שאין בקיאין בגומות ולענין שיעור אורך השערות כתוב בפי' סדר חליצה סכ\"ז שהוא כרוחב אצבע שקורין אמה ועיין במ\"ש בסימן קנ\"ה בדין זה באורך:","\u0003ויעמדו לפניהם וכו'\u0004 לא עמדו חליצתם כשרה כתבו התוס' והרא\"ש והא דדריש בספרי ועמד ואמר אין דברים הללו אלא בעמידה אסמכתא בעלמא הוא ולכתחילה בעינן עמידה משום דדמיא לגמר דין עכ\"ל נראה דר\"ל כיון דקודם חליצה היתה זקוקה לו ועכשיו נפטרה ממנו דמיא לגמר דין אבל מדינא כל חליצה תחלת דין הוא ומ\"ה חלצה בלילה פסולה כדלעיל אלא מדרבנן מיחזי כגמר דין: ויעמדו לפניהם וכו' היבם והיבמה וכו' הב\"י בפי' סדר חליצה סכ\"ב נדחק במ\"ש שיעמדו היבם והיבמה ע\"ש ולי נראה דכיון דחליצה דין הוא כתיב ועמדו שני האנשים אלו בעלי דינים הלכך צריך שיעמדו ואסור להם לישב עד שא\"ל הדיינים שבו:","\u0003והמנעל צריך שיהא כולו של עור וכו'\u0004 מימרא דרב בפרק מ\"ח סנדל התפור בפשתן אין חולצין בו שנאמר ואנעלך תחש וז\"ל הרא\"ש פירש\"י בלשון ראשון שיש תחתיו בגד כמו שנותנין לבד בתוך המנעל בימות החורף ולא נהירא לי דלא גרע מסנדל של עץ דקתני מתני' דהחליצה כשרה ואוקמה אבוה דשמואל במחופה עור וד\"ה ואביי נמי אוקי הך ברייתא דקב הקיטע כרבנן ובמחופה עור ונראה דלשון שני שפירש שתפרו במשיחה כעין שלנו דבעי' כוליה עור גם נראה דאין חולצין בו לכתחלה קאמר דדרשא דתחש אסמכתא בעלמא היא עכ\"ל ונ\"ל דלשון גם נראה וכו' ה\"פ דאף ללשון שני ודאי דכשרה דיעבד דאין חולצין לכתחלה קאמר וא\"כ לפ\"ז פשיטא ג\"כ דלא קשיא ללשון ראשון דלא גרע מסנדל של עץ במחופה עור דכשרה דהתם נמי כשרה דיעבד אבל לכתחלה לא ומ\"מ צריך יותר ליזהר שלא יהא תפור במשיחה של פשתן דא\"כ לא הוי כולו של עור אבל אם כולו של עור אלא שתפור בו בגד בפנים אע\"פ דלכתחלה יחלוץ באותו שאין בו בגד מ\"מ אם אין שם מנעל אחר אלא שתפור בו בגד יחלוץ בו דזה חשוב דיעבד מה שאין כן בתפור במשיחה של פשתן דאין חולצין בו כלל לכתחלה אפי' אין שם אחר וזה שכתב רבינו תחלה והמנעל צריך שיהא כולו של עור לפיכך צריך לתופרו בעור ואח\"כ כתב ולא יהיה תפור בו בגד מלפנים ולא כתב וצריך שלא יהיה תפור בו בגד מבפנים והיינו כדפי' לחלק בין זה לזה בלכתחלה גם הרמ\"ה בסמוך מחלק ביניהם בדיעבד דבתפור בפשתן אפי' בדיעבד פסול כיון דאין כולו של עור ובתפר בו בגד מבפנים כשר בדיעבד אבל להרא\"ש ורבינו תרוייהו כשרים בדיעבד כמ\"ש בסמוך אלא דבלכתחלה איכא לחלק ביניהם כדפרישית נ\"ל ועיין לקמן בסעיף י\"ג מ\"ש עוד בדין זה:","ומ\"ש אבל רצועותיו א\"צ שיהיו מעור לכאורה משמע דאפי' ברצועות של פשתן נמי מכשיר וכך הבין ב\"י וקשה דהא קא בעי ר\"א מרב הוא של עור ותרסיותיו של שער מהו א\"ל מי לא קרינן ביה ואנעלך תחש פי' דהשער ג\"כ מתחש הן א\"ה אפי' כולו שער נמי ההוא קורקא מיקרי אלמא דאי הוה מיקרי נעל אפי' כולו שער הוי כשר כיון דאתא מתחש ובהוא של עור דאקרי נעל ותרסיותיו של שער כשר כיון דשער כמו תחש הוא אבל כל שאין תרסיותיו של תחש פסול ונראה דגם רבי' הכי ס\"ל ומ\"ש אבל אין צריך שיהיו מעור אין כוונתו דכשר בשל ד\"א ואפי' של פשתן דא\"כ ה\"ל לומר בפירוש אבל רצועותיו כשרין בשל פשתן או ד\"א אלא רצונו לומר דא\"צ שיהיו מעור אלא אפי' של שער או מגידין שנעשו מיריכים של בהמה דכל שהוא של תחש כשר ומה שלא כתב רבי' דמשל שער כשר כדאיתא בגמ' היינו משום דה\"א דוקא של שער שגידולן מן העור אבל של גידין לא לכך קאמר רבי' א\"צ שיהיו מעור דאפי' אינו מעור אלא מגידין נמי כשר וה\"ה מרצועות שנעשו מבני מעיים של בהמה כמו הנימין של נבל וכינור נמי כשר אבל רצועות של פשתן או ד\"א פשיטא דפסול וכ\"כ נ\"י ומביאו ב\"י וגם רבינו מודה כדפי' והכי נקטינן: וכתב בספר המצות צריך שיהיה העור קשה וכו' ה\"א בגמרא ריש (דף קב) דאפי' יבא אליהו ויאמר אין חולצין בסנדל אין שומעין לו שכבר נהגו העם בסנדל אבל במנעל פליגי בה תרתי לישני דרב ללישנא קמא אין חולצין במנעל לכתחלה וללישנא בתרא חולצין לכתחילה וקאמר ומנעל לכתחלה תנאי היא דתניא אמר רבי יוסי פעם אחת הלכתי לנציביו ומצאתי זקן אחד אמר ליה כלום אתה בקי בר\"י ב\"ב אמר ליה הן ועל שלחני הוא תדיר כלום ראית שחלץ ביבמה אמר ליה ראיתי שחלץ הרבה פעמים או במנעל או בסנדל אמר ליה וכי חולצין במנעל אמרתי לו א\"כ מה ראה ר\"מ לומר חלצה במנעל חליצתה כשרה רבי יעקב אומר משמו [דר\"מ] חולצין במנעל לכתחלה ומ\"ד לכתחילה לא מ\"ט גזירה משום מנעל מרופט א\"נ משום חצי מנעל וצריך לפרש דמ\"ש א\"כ מה ראה ר\"מ וכו' ה\"ק דמדקאמרת בלשון תימה וכי חולצין במנעל מכלל דסבירא לך דאפי' דיעבד פסול ולכן תימה היא היאך עלתה ע\"ד לחלוץ לכתחלה והא ליתא דא\"כ מה ראה ר\"מ לומר חלצה במנעל חליצתה כשרה ור' יעקב אומר עוד משמו דר\"מ דחולצין אף לכתחלה כל זה דברי רבי יוסי משמו דרבי מאיר אלא ודאי בדיעבד פשיטא דכשרה אלא דלכתחלה אין חולצין לרבי יוסי ומשמע דהזקן נמי הכי ס\"ל כר' יוסי אלא דתמה על שאלתו ששאל אם ר\"י ב\"ב היה חולץ לכתחלה במנעל וכי חולצין במנעל לכתחלה הלא כבר נהגו העם לחלוץ בסנדל והשתא ליכא מאן דקאמר דבמנעל פסול דיעבד דלר' יוסי ולההוא זקן דיעבד כשר ולרבי יעקב אפי' לכתחלה חולצין ומדברי ב\"י נראה שהבין דר' יוסי דאמר א\"כ מה ראה ר\"מ וכו' דאפי' בדיעבד פסול וליתא אלא כדפרישית:","ומ\"ש אלא שאינו מצוי פי' דכיון דאין סנדל מצוי במקומותינו נהגו לחלוץ במנעל לכתחלה וה\"א בירושלמי מביאו הרא\"ש פרק מ\"ח (דף קמ\"ג ע\"ב) אלא דמ\"מ צריך לעשותו שיהא דומה לסנדל בכל מאי דאיפשר וב\"י האריך בזה ע\"ש:","\u0003ומאיזה עור שיהיה הסנדל שפיר דמי ולא כר\"ת וכו'\u0004 כלומר שפיר דמי דהחליצה כשרה דיעבד ולא כר\"ת שכתב שצריך שיהיה עור בהמה טהורה דוקא דמדהוסיף לומר דוקא משמע דאפי' בדיעבד פסול דאי צריך לכתחלה קאמר ה\"ל לומר בסתם צריך שיהיה עור בהמה טהורה ואע\"פ דבתוס' ואשיר\"י לא כתב דוקא אלא בסתם הנה רבי' ראה אף דברי ר\"ת שכתב דוקא וטעמו דכי היכי דאם כולו אינו של עור פסול דלאו תחש הוא ה\"ה בכולו של בהמה טמאה נמי פסול דלאו תחש הוא והכי נקטינן לחוש לר\"ת ואפי' בדיעבד פסול כדמשמע מדברי רבינו אליבא דר\"ת נ\"ל וב\"י הבין מדברי רבינו דאפי' לכתחלה לא צריך בהמה טהורה ותמה עליו למה לא חשש לדברי ר\"ת ע\"ש ולא נהירא אלא כדפי' הוא העיקר:","\u0003ויהיה לו רצועות וכו'\u0004 וגם כמין קשר וכו' בפ' מ\"ח (דף ק\"ב) אמר רב אי לאו דחמיתיה לחביבי דחלץ דאית ליה שינצין אנא לא הואי חליצנא אלא בסנדלא דטייעא דמיהדק טפי והאי דידן אע\"ג דאית ביה חומרתא קטרינן ביה מיתנא ואיכא להקשות דה\"ל לומר תחלה דעושה בו כמין קשר באזנו וכו' וגם יהיו לו רצועות וכו' כלשון הגמרא ולמה כתב איפכא וצ\"ל דרבינו סובר כפירשב\"א דתלמודא ה\"ק דבלא מיתנא לא סגי אע\"ג דאית ליה חומרתא אבל חומרתא זו לא מעלה ולא מורדת וכך הוא דעת הרב רבינו משה בר מיימוני והסמ\"ג כמו שפי' ב\"י ולכן כתב רבי' תחילה ויהיו לו רצועות כו' דלא סגי בלא רצועות דחומרתא מדינא לא מעלה ולא מורדת אלא דלרווחא דמילתא כתב וגם כמין קשר באזנו וכולי דלחומרא מצריכין גם קרסים ולשון זה שכתב רבינו הוא לשון הסמ\"ק ושאר גדולים הביאם ב\"י:","\u0003וכתב בספר המצות וכו'\u0004 ושלא יהא לו לשון וכו הקשה ב\"י דהלא בגמ' מפורש דבמנעל אף על פי שכופלין רצועות על אזניו אין בו משום מעל דמעל ואפילו לכתחילה הוי כשר מדינא אלא דאסרו לכתחילה גזירה משום מנעל המרופט ול\"ד למ\"ש בסמוך דאם נעל מנעלו על בתי שוקיים הוי מעל דמעל דהתם שאינן תפורין יחד ודאי אפילו בדיעבד פסול דלא דמי לסנדל של עץ מחופה עור דכשר דיעבד דהתם תפורין יחד והוו מנעל אחד וכ\"כ ב\"י לקמן ע\"ש המרדכי וסה\"ת ול\"ד לשני מנעלים היכא דשליף לתרוייהו דכשרה בדיעבד דהתם גם התחתון הוא של עור אבל מנעל שכופלין רצועותיו על אזניו דתפור הכל יחד והוי מנעל אחד וכולו של עור אפילו לכתחילה כשר וב\"י כתב ואיפשר דע\"כ לא מכשר אלא דיעבד וכו' ושרי ליה מריה דעל מה שאי איפשר אמר דאיפשר אלא לפע\"ד דספר המצות לא כתב דמדינא הו\"ל מעל דמעל דהא ודאי אף לכתחילה כשירה כדפי' אלא כיון דמיחזי כמעל דמעל וכדקס\"ד בגמרא דקאמר אילימא משום דהויא פנתא מעל וערקתא מעל דמעל א\"ה אפילו דיעבד נמי לא וכו' הלכך מחמרינן דלכתחילה לא כדי דלא ליתי למטעי להכשיר חליצת מנעל גם מעל בתי שוקים דהוי מעל דמעל ופסול דאורייתא זהו דעת סמ\"ק באין ספק:","\u0003היה בגד פשתן תפור וכו'\u0004 החליצה כשרה בדיעבד כבר כתבתי למעלה שזו היא דעת הרא\"ש וטעמו דדרשא דתחש אסמכתא בעלמא היא ואיכא להקשות קב הקיטע דקי\"ל כרבנן דפסולה החליצה בשאינו מחופה עור וטעמייהו דבעינן תחש דלא כר\"מ דלא מצריך אלא מידי דמגין וכמ\"ש התוס' (דף ק\"ב) בד\"ה סנדלא התפור אלמא דלאו אסמכתא היא אלא דרשא גמורה היא. ונראה דפשיטא דלאו דרשא גמורה היא ופיסול דקב הקיטע נמי אינו אלא מדרבנן כיון דאינו מחופה עור והרא\"ש הכי קאמר דכיון דתחש אינו אלא אסמכתא בעלמא הילכך כל שאינו מפורש דפסול מפרשינן לקולא ובתפור בפשתן נמי דאמר רבא אין חולצין בו מפרשינן דאין חולצין בו לכתחילה אבל בדיעבד כשר ולא דמי לשל עץ דלשם מפורש דהחמירו בו חכמים לפסול בחליצה מדרבנן אעפ\"י דמדאורייתא כשרה אפילו במנעל של עץ דלא כתיב תחש באורייתא ודוק ועיין במ\"ש לעיל ס\"ז:","ומ\"ש בשם הרב רבינו משה בר מיימוני דבמנעל של בגד אינה חליצה כלל אפי' לפסול על האחין האריך בטעמו הרב המגיד ושהרשב\"א חלוק עליו דכולן שוין לפסול מן האחין ותימה הלא תלמוד ערוך הוא בפרק כל הגט במערבא אמרי משמיה דר\"א שמאל ולילה פסולות ופוסלות קטן ואנפיליא פסולות ואינן פוסלות אלמא דאנפיליא אינה חליצה כלל ואינה פוסלת מן האחין והתוס' לשם הביאו בפירוש מפרק האשה רבה ומפ' מ\"ח דפשוט הוא דלרבנן אין חליצת קטן כלום וא\"כ ה\"ה באנפיליא דדמיא ליה וכדפירש\"י דאיש ונעל כתובים בפרשה והיאך חולק הרשב\"א על זה וצ\"ע וכתב במרדכי פ' מ\"ח היאך קאמר קטן ואנפליא אינה פוסל' הלא רקקה ופוסלת ברקיקה בכל האחין ותירץ ברקיקה לבד פסולה על כל האחין דהא לשם חליצה איכוונא אבל היכא דרקקה לשם חליצה קטן ואנפליא אינה כלום עכ\"ל כלומר באנפליא וקטן כ\"ע ידעו דלאו כלום הוא אבל ברקיקה לחוד סברי מדרקקה ודאי חלצה ברישא ובהך רקיקה איכוונא לחליצה ואי שרינן לה להתייבם אמרי דחלוצה שריא להתייבם:","ומ\"ש רבינו או שהוא של עץ או שהוא של סיב או שעם ומחופה עור שם בגמרא מוקמינן הא דכשר בסנדל עץ לרבנן היינו דוקא במחופה עור דלא כר\"מ דמכשר אפילו בלא עור השתא לפ\"ז של סיב ושעם דהוא גם כן עץ אינו כשר לרבנן אלא במחופה עור ודכוותא קאמר תלמודא באנפליא לרבנן לא כשר אלא בשל עור אבל בשל בגד פסול אבל במוק דלא אדכר תלמודא מידי משמע ליה לרבינו דאף לרבנן כשר אפילו אינו מחופה עור וטעמו משום דהמוק הוא לבד קשה ומגין כפירש\"י וחשוב הוא כמנעל של עור וחליצתה בו כשרה. ומיהו צריך לומר דהמוק נעשה מצמר ומשער של בהמה ונקרא בשם מנעל ואעפ\"י דאינו עור קרינן ביה ואנעלך תחש שהרי אפילו כולו של שער נמי אי לאו דקירקא מיקרי הוה כשר א\"כ מוק דמיקרי בשם מנעל ודאי דכשר דלא דמי לבגד אף על גב דנעשה כולו מתחש ונקרא בשם אנפליא דהוא לשון מנעל מ\"מ לאו קשה ולאו מגין הוא זהו דעת רבינו שפסק בסתם מוק כשר ולא פירש דבשל לבד שהוא קשה כשר אפילו אינו מחופה עור דאי איתא דאיננו כשר לרבנן אלא במחופה עור ה\"ל לתלמודא לפרושי לרבנן כי היכי דקא מפרשי לסנדל עץ ולאנפליא אלא בע\"כ סתמא משמע דכשר אפילו אינו מחופה עור ואפילו לרבנן והא דקאמר התם רבה בר חייא קטוספאה עבד עובדא במוק ביחידי בלילה ופסק האלפסי והרא\"ש למימרא דלית הילכתא כוותיה נראה דלצדדין אפסיקא הילכתא דביחידי ובלילה החליצה פסולה דיעבד אבל במוק לכתחילה לא אבל דיעבד כשרה כסתמא דברייתא דמוקמינן לה דאתיא נמי כרבנן וכשרה דיעבד ואעפ\"י דרבא מוקים הא דמפליג בין קב הקיטע לאנפליא של בגד כר\"מ ובאינו מחופה בעור מ\"מ הך דמוק מוקים לה דאתיא אפילו לרבנן כי היכי דכל אינך מילי דקתני ברישא דכשרה דאתיא אפי' לרבנן ומה שהקשה ב\"י דהו\"ל לרבינו לפרושי דמוק כשר אפילו בלא עור אינה קושיא דמסתמא הכי משמע ועוד כיון דתלמודא נקט סתמא מוק כשר ולא פירשה כלום אף רבינו לא פירש כלום ומה שהקשה עוד ב\"י אמאי השמיט דין קב הקיטע אינה קושיא כלל דקב הקיטע דהוא של עץ היינו סנדל של עץ דהכי מוכח בגמרא דקאמר סנדל של עץ מאן תנא אמר שמואל ר\"מ דחנן הקיטע יוצא בקב שלו דר\"מ ר' יוסי אוסר אבוה דשמואל אומר במחופה עור ודברי הכל כנ\"ל דעת רבינו אבל מדברי הרי\"ף והרמב\"ם משמע להדיא דמפרשים דבמוק דתניא סתמא בברייתא דכשר ר\"מ הוא וכדאסיק רבא דקב הקיטע ר\"מ ה\"נ מוק ר\"מ הוא ולכך לא כתב הרב רבינו משה בר מיימוני בפ\"ג דבמוק חליצתה כשרה וכך היא משמעית שאר פוסקים והכי נקטינן:","\u0003מנעל של עכו\"ם שמניחין אותו ברגלי הדמות נראה דאפי' אין מניחין וכו'\u0004 וכדין שופר ולולב של עכו\"ם אלא נקט מניחין כלומר שלא הובא לשם דורון לעכו\"ם דאז דין תקרובת עכו\"ם יש לו כמ\"ש בסיפא. ומ\"ש שהרי אינו עשוי להלוך בו קאי אהיכא שנעשה למת וכפירש\"י אבל התוספות הקשו בסנדל של ע\"ז של עכו\"ם מכי אגבהה הו\"ל ע\"ז של ישראל ומכתת שיעוריה ופסול לחליצה וי\"ל שהגביהו על מנת שלא לקנותו עכ\"ל וקושיא זו ופירוקה אינו אלא בדהוי של הפקר אבל איכא לפרש בענין אחר דקושיא מעיקרא ל\"ק דמיירי בסנדל של ע\"ז של עכו\"ם דלא אפקריה דאע\"ג דאגביה ישראל לא קני ליה כיון דעכו\"ם לא אפקריה ולא קא מייאש מיניה הו\"ל ע\"ז של עכו\"ם וכמ\"ש בא\"ח בה' ר\"ה:","\u0003כתב בספר המצות אפילו אטר וכו'\u0004 וב\"י בפירוש סדר חליצה סימן מ' כתב לחלוץ בשתי רגליו בבת אחת ורבותי לא נהגו כמותו אלא חולצת בזה אחר זה ותקנה למה שחשש ב\"י שמא תהיה חליצה פסולה הוא שיזהירו הדיינים ליבם שיהא דעתו בשעת חליצה שבאותו חליצת רגל שהדין הוא לחלוץ בו הוא מכוין לפטור בו יבמתו וכן היבמה תהא דעתה וכוונתה שלא להיות פטורה מזיקתה אלא באותו חליצת רגל שהדין נותן לחלוץ בו הן הדין הוא לחלוץ ברגל ימין הן הדין הוא לחלוץ ברגל שמאל דהשתא אין כאן חששא שמא תהא החליצה פסולה דכיון דשניהם נתכוונו שלא תהא נפטרת מזיקתה כלום בחליצת אותו רגל שאינו בדין אינה חליצה כלל וכאילו לא חלץ לה ולא פסלה על האחין בחליצה זו והכי נקטינן וכך אני נוהג:","\u0003וינעול המנעל על רגלו וכו'\u0004 עד כמו פגימה וכו' וז\"ל הראב\"ן בספרו (דף קכ\"ג) אהא דקאמר בפ' מ\"ח דאין חולצין במנעל לכתחילה מ\"ט אילימא משום דהוי פנתא מעל וערקתא מעל דמעל וכו' פנתא הוא עור המנעל עצמו שנוגע לרגל וערקתא הוא הרצועה שקושרין בו המנעל והוא על הפנתא שעל הרגל וקרא כתיב וחלצה נעלו מעל רגלו ולא מעל הפנתא ולהכי ראיתי זקנות שהיו נוקבים המנעל נקבים נקבים סמוך לרגל לקיים וחלצה מעל רגלו שהתרת הרצועה אתחלתא דחליצה היא דאמר ר' ינאי בין שהתיר הוא וכולי וקושרין הרצועה למטה במנעל סמוך לרגל וחותכין מן הגובה של מנעל ומן השפה של פיו שיהא מקצת רגלו גלוי שם ושם כנגד הבשר תהא קשר הרצועה וקושרין קשר ולא עניבה דוחלצה נעלו מעל רגלו בעינן גם התרת הרצועה עם שמיטת הרגל שלא יהא דבר חוצץ בין רגלו לקשר הרצועה ולא בין מנעל לרגלו אלא המנעל וקשר הרצועה יהיו על בשר רגלו עכ\"ל:","רק לא אבה צריך שיקראוהו בנשימה אחת בלי הפסק ס\"פ מ\"ח קאמר רב כהנא לרב אשי מודה רבא בלא אבה יבמי ופירש\"י דאי מפסיק משמע דהאי לא ארישא קאי דאמר מאן יבמי להקים לאחיו שם בישראל לא כלומר לא מאן אלא אבה יבמי אבל בלא חפצתי לקחתה שהיא פתיחת קריאתו ליכא למימר הכי לא לעיל קאי ואי מפסיק לית לן בה עכ\"ל אלא דמאי דמשמע מגירסא זו דכל שלשה תיבות לא אבה יבמי צריך לקרות בנשימה אחת וזהו דעת האחרונים גם בלא חפצתי לקחתה לקרות כל הג' בנשימה אחת אבל הרב רבינו משה בר מיימוני וסה\"ת וסמ\"ג וסמ\"ק כתבו דלא בעינן לכתחילה בנשימה אחת אלא לא אבה וכך כתבו התוספות לא אבה כתיב בספרים מדוייקים והכי נקטינן דאם אי איפשר להם לקרות בטוב כל הג' תיבות בנשימה אחת אז סגי בלא אבה מיהו צ\"ע היאך מקרין לא אבה בלי הפסק הלא צריך ליתן ריוח בין הדבקים ואיפשר דהכא חששו חכמים שלא להעלות קריאה פסולה בחליצה והקילו שלא צריך ליתן ריוח בין הדבקים ואיפשר שלכוונה זו כתב רבינו שתי לשונות צריך שיקראוהו בנשימה אחת בלי הפסק דבנשימה אחת הוה משמע דמ\"מ צריך הפסק וריוח בין הדבקים ולכן אמר עוד בלי הפסק דאף בין הדבקים לא יפסוק כלל ולא יתן שום ריוח כנ\"ל:","וכן יראה מדברי רב אלפס וכולי כתב בית יוסף בע\"כ דה\"ק אם בשעת קריאה לא קראה כאחת אבל מ\"מ צריכה שתהיה רגילה לקרותו כאחת דתיהוי ראויה לבילה ומ\"מ לשון אינו מעכב אינו מדוקדק דהא אפילו לא קראה כלל חליצתה כשרה עכ\"ל ולא קשה מידי דהלא הרי\"ף כתב וז\"ל מודה רבא בלא אבה יבמי כדר' זירא דאמר כל הראוי לבילה וכו' ה\"נ אם ראוייה למיקרייה בבת אחת לא מעכבא קריאתה ואי לא מעכב עכ\"ל ורצונו לומר דמעכבא לכתחילה קאמר דמצריכים אותה שתהיה רגילה לקרותה כאחת ואם אינה רגילה אין חולצין לה עד שתהא רגילה אם כן לשון מעכב מדוקדק שפיר:","\u0003וכיצד היא חליצת המנעל וכו'\u0004 ותתפוס רגלו בידה השמאלית וכו' פי' בשעה שתתפוס בידה הימנית בעקב המנעל לחלוץ אותו אז תתפוס בידה השמאלית עובי בשר השוק באויר כדי שלא ינוד ויזוז ותשמיט המנעל מן העקב בידה הימנית ותחלוץ אותו ואפשר שמ\"ש רבינו בשם ר\"ת שולפתו בימין ושמאל מסייעתה ר\"ל ג\"כ שהשמאל מסייעתה במה שאוחז' בו בבשר השוק שלא ינוד באויר ותוכל לחלוץ אותו מן הרגל בימינה בטוב אלא לפי שאפשר לפרש לשון ר\"ת כפשוטו דמתיר לכתחילה שהשמאל תהא מסייע בחליצה ממש לכן הביא רבינו עליו הא דכתב בסמ\"ק שכל החליצה תהא בימין דהיינו התרת קשר הרצועות וקשר הלולאות וחליצת המנעל הכל בידה הימנית כדמוכח בירושלמי וא\"כ ממילא צריך לפרש דברי ר\"ת דלא תהא שמאל מסייעה אלא לאחוז בבשר השוק בלחוד כדפי' וצ\"ל דגירסת הסמ\"ק בירושלמי היא ושומטת העקב הימין וגוררתו בימין כמו שגורסים סה\"ת והסמ\"ג והמרדכי והרב המגיד דלא כגירסת התוספות והרא\"ש ושומטת עקב בימין וגוררתו בשמאל ומיהו איפשר דר\"ת היה גורס ג\"כ וגוררתו בשמאל כמ\"ש התוספות והרא\"ש וס\"ל כיון דשומטת עקב המנעל מן עקב הרגל בימין זהו עיקר החליצה ומה שהשמאל גורר ושולף המנעל מן הרגל כשאוחזו בראש השני במקום האצבעות אינו אלא מסייע ומסייע אין בו ממש כדמסיק תלמודא פ' המצניע (שבת דף צ\"ג) ולכן שרי אפילו לכתחילה לגוררו בשמאל לאחר שכבר שמטה העקב בימין וזה נראה עיקר ומיהו כבר נהגו כהסמ\"ק שהכל יהא בימין אלא שתופסת בשר השוק בשמאל וז\"ל בירושלמי ותופסת בשמאל. והכי נקטינן:","\u0003ואיני יודע למה כתב ויושבת וכו'\u0004 ה\"ה הליץ ואמר שגם דעת הרשב\"א הוא שאפי' לכתחילה חולצת מיושב. ומה שהקשה למה הצריכה להשליכו לארץ מצאתי שזה צריך כדי להראות שמה שחלצה המנעל מעל רגלו לא בשביל שהמנעל הוא שלה ולקחה אותה לרשותה דאינו שלה ועל כי משלכת אותו מידה לארץ כי לא חלצה אותו אלא לשם מצות חליצה שלא תהא עוד זקוקה לו ונכון הוא:","\u0003אמר אמימר מאן דחליץ וכו'\u0004 ופי' רב אלפס שאם לא עשה כן החליצה פסולה וכו' כך הוא מבואר בפסקי הרא\"ש אבל בדברי הרי\"ף גופיה איכא לפרש דאינה פסולה בדיעבד גם בדברי הרמב\"ם אפשר לפרש דאין דעתו לפסול בדיעבד אם לא נעץ עקבו בארץ כיון שהוא יכול לנעוץ בארץ דכל הראוי לבילה אין הבילה מעכבת וכ\"כ ב\"י ודבריו נכונים מיהו צריך ליזהר הרבה שיהא מבורר להדיינים שנועץ רגלו בארץ וגם כשהוא הולך ראש נעלו הולך למטה מרגלו והתורה אמרה וחלצה נעלו מעל רגלו אבל אי לא דחיס וכו' כצ\"ל אבל באשר\"י כתב וז\"ל וגם כשהוא חולץ נעלו חולץ למטה ברגלו והתורה אמרה וכו' וזה עיקר:","\u0003חלצה מן הארכובה וכו'\u0004 פירוש רב אלפס דאקשירה קאי וכו' כלומר כיון דלדבריהם לא מיירי תלמודא בקיטע לאפלוגי בין קיטע למטה מהארכוב' ובין קיטע למעלה מהארכובה א\"כ אין לנו ראיה דחולצין לקיטע ומסתמא ודאי אין חולצין לקיטע דהא כתיב וחלצה נעלו מעל רגלו וזה אין לו רגל והא דתני בברייתא סוף (דף קב) בקב הקיטע חליצתה כשירה היינו שנותן לאחר לחלוץ בו וכ\"כ הרא\"ש ומיהו קשה דבספרי הרי\"ף שבידינו כתוב וז\"ל דס\"ל לאמימר דמאן דאיפסקא רגליה מארכובה ולמטה דבעי לתרוצי לשארא על ארעא וחליץ וכן נמי בדלא אפסיקא רגליה דבעי לתרוצי לרגליה על ארעא וחליץ וכו' אלמא דמפרש הרי\"ף בדאמימר דקיטע נמי חליץ ותו קשה טובא דאח\"כ כתב הרי\"ף ומתני' דקתני מן הארכובה ולמטה חליצתה כשירה לאו דנקטעה רגלו אלא כגון דקשר רצועות המנעל למטה מארכובה וכו' וא\"כ דבריו סותרים מסופו לראשו ונראה דמ\"ש תחילה הוא מה שפי' הרי\"ף במהדורא קמא ואח\"כ הגיה וכתב כלשון שכתב הרא\"ש ונמ\"י בשם הרי\"ף דמתניתין לאו בנקטעה רגלו אלא כגון שקשר וכו' וכמו שכתב בעל המאור לשם דאחר כך הגיה הרי\"ף והמדפיסים טעו ושמו בהעתק שני הפירושים הראשון והאחרון והם סותרין והאחרון הוא מה שהגיה הרי\"ף וכתבו כך כל המפרשים בשמו ופשוט הוא:","\u0003ומ\"ש ור\"ח פי' וכן רש\"י דאנקטעה רגלו קאי וכו'\u0004 ולפ\"ז לא איירי תלמודא בלא נקטעה רגלו ולאפלוגי בין היה הקשר למעלה מן הארכובה ובין הוא למטה מהארכובה ומשמע דאפילו קשר למעלה מהארכובה חליצתה כשירה והכי משמע להדיא מדברי הרא\"ש דבלא נקטעה רגלו לעולם כשירה החליצה ומביאו ב\"י ואיכא לתמוה למה לא כתב כך רבינו לפי דעת ר\"ת ופי' רש\"י והסכמת הרא\"ש דבלא נקטעה רגלו יכול לקשור אף לכתחילה למעלה מן הארכובה:","ותרוק בארץ כנגד פניו וכולי עד שפיר בפניו כ\"ז בסוף פרק מ\"ח ויליף לה מדכתיב לעיני וירקה ומדברי התוס' משמע דדרשא גמורה היא ואם לא ראו הדיינים הרוק שיצא מפיה חליצתה פסולה דאהך ברייתא דהחולצת מן הסומא חליצתה כשירה בריש (דף ק\"ג) הקשו התוספות מהיכא ס\"ד למעוטי סומא וי\"ל מדכתיב לעיני הזקנים וה\"א ה\"ה לעיני היבם א\"נ משום דכתיב וירקה בפניו דהוי כמו לעיניו קמ\"ל דלא עכ\"ל השתא כיון דמן הסומא אינה כשירה אלא דיעבד אלמא דבדיינים אם לא ראו הרוק חליצתה פסולה אפילו דיעבד וה\"א דה\"ה מן הסומא נמי פסולה דיעבד קמ\"ל דלא אבל להרמב\"ם בפכ\"ד דמכשיר בלא ראו הדיינים הרוק היוצא מפיה ס\"ל איפכא דבדיינים שלא ראו הרוק פשיטא דהחליצה כשירה דהך דרשא לעיני וירקה אסמכתא בעלמא היא וזהו שלא אמר רבא לשם אי לא חזו דייני רוקא לאו כלום הוא כמ\"ש בההוא דאפלה תומא הסמוכה שם אלא אמר צריכי דייני למיחזי דוקא דמשמע דצריך לכתחילה אבל אם לא ראו כבר עשתה חליצה כהילכתא שהרי רקקה בפניו וכמ\"ש ה\"ה לשם והברייתא אתא לאשמועינן דאפי' היה היבם סומא שאינו רואה הרוק וכתיב וירקה בפניו דמשמע פשוטו שיהא רואה הרוק אפ\"ה חליצה כשירה אלא שאינו חולץ לכתחילה אם יש שם אחר שיחלוץ וכמ\"ש הרב רבי' משה בר מיימוני והראב\"ד וה\"ה ברפ\"ד ומביאו רבינו בסמוך. והנ\"י תפס לו שיטה שלישית וז\"ל בסוף מ\"ח והא דאמרינן דבעינן שיהא הרוק בפניו מדכתיב וירקה בפניו מסתברא דלא קאמר אלא שיהא כנגד פניו בין רואה בין שאינו רואה ואפילו סומא חולץ לכתחילה ודוקא לב\"ד הוא דבעינן שיראו הרוק מדכתיב לעיני הזקנים והא דתניא החולצת מן הסומא כשירה בדיעבד משום סיפא דקתני פסולה נקט הכי אלא שהרמב\"ם כתב דאין סומא חולץ לכתחילה עכ\"ל משמע דס\"ל דב\"ד צריך שיראו לכתחילה הרוק יוצא מפיה אבל דיעבד כשר אפי' לא ראו דלעיני הזקנים אינו אלא אסמכתא דבהא מודה הרב נ\"י להרמב\"ם ולא נחלק עליו אלא לענין זה דהיבם א\"צ לראות הרוק אפילו לכתחילה ואפי' הוא סומא דוירקה בפניו לא משמע אלא כנגד פניו ואפילו אינו רואה דלא כהרמב\"ם ואפשר דאף התוס' תופסים שיטת נ\"י וקושייתם אינה אלא הלא פשיטא דסומא כשר לחלוץ אפי' לכתחילה דמהיכא ס\"ד למעוטי סומא ותירצו מדכתיב לעיני הזקנים וכו' דה\"א כי היכי דב\"ד צריך לכתחילה לראות הרוק יוצא מפיה הכי נמי גבי יבם קמ\"ל דלא דוירקה בפניו משמע אפי' אינו רואה ואפי' סומא נמי לכתחילה חולץ אלא דלפי זה היו דבריהם סתומים והוה ליה לפרש ועוד דבריש מ\"ח כתבו התוס' בד\"ה זקני דב\"ד אם לא ראו הרוק אפילו בדיעבד החליצה פסולה ובסומא כשירה בדיעבד ע\"ש ולפיכך נראה דדעת התוס' כדפי' לעיל ולענין מעשה נראה דאזלינן לחומרא הכא והכא דבב\"ד אפי' בדיעבד החליצה פסולה כמו שנראה פשט התוס' ואפילו את\"ל דאינה פסולה מדאורייתא דלעיני הזקנים לאו דרשה גמורה היא אפ\"ה פסולה מדרבנן וביבם אפי' הוא סומא כשירה בדיעבד ואם אין אח אחר כשירה אפי' לכתחילה דהיינו דיעבד דלא תתעגן כיון שאין נוהגין בייבום ואם אינו סומא נראה ממה שכתב הרב בפירוש סדר חליצה דמסתפק אם היבם צריך לראות את הרוק אם לאו ואע\"ג דבסדר חליצה סי\"ז כתב צריך שלא יהא היבם החולץ סומא אם יש לו אח שאינו סומא וכה\"ג כתב קודם זה סמ\"ח שאני סומא בשתי עיניו שאינו יכול לראות כלל אבל מי שאינו סומא כלל או אפי' סומא באחד מעיניו שיכיל לראות אפשר שחולץ אפילו לכתחילה וא\"צ לראות הרוק וכדר' זירא דכל הראוי לבילה אין בילה מעכבת בו ושאני ב\"ד מדכתיב לעיני הזקנים ומ\"מ מאחר שאיפשר דהיבם פשיטא דצריך לראות את הרוק דפשטיה דוירקה בפניו איבם קאי וכו' וכדכתב ב\"י הילכך לכתחילה צריך להזהיר לחולץ שיהא נותן דעתו לראות את הרוק והכי נקטינן:","\u0003יבמה שרקקה דם וכו'\u0004 עד צריכה לרוק פעם אחרת כך היא גי' ב\"י ולכן פי' ורבינו סתם וכתב וכו' עד לשותתת אבל במדוייקים כתוב אחר זה וכ\"כ הרב רבינו משה בר מיימוני ז\"ל וא\"א הרא\"ש ז\"ל כתב דאפי' בשותתת אינה צריכה לרוק פעם אחרת ולפי נוסחא זו פי' ולא סתם:","\u0003צריך שיכוונו היבם והיבמה וכו'\u0004 בפרק מ\"ח (דף ק\"ב) א\"ר יהודה אמר רב יבמה שהגדילה בין האחין מותרת לינשא לאחד מן האחין ואין חוששין שמא חלצה סנדל לאחד מהן טעמא דלא חזינא הא חזינא חיישינן והא תניא בין שנתכוין הוא ולא נתכוונה היא בין שנתכוונה היא ולא נתכוין הוא חליצתה פסולה עד שיתכוונו שניהם כאחד (פי' דמדקתני עד שיתכוונו שניהם כאחד משמע דבעינן שנדע ששניהם מתכוונין לחליצה וכשלא נדע אינה חליצה ומותרת לינשא לאחד מהן והא דקאמר חליצתה פסולה לאו דוקא פסולה קאמר אלא כלומר אין בחליצה זו כלום כאילו לא חלצה כלל ומותרת לינשא לאחד מהן) ה\"ק אע\"ג דחזינן אין חוששין שמא כיונו ואיכא דאמרי טעמא דלא חזינן הא חזינא חוששין ודקא תנא בעי כוונה ה\"מ לאישתרויי לעלמא אבל לאחין מיפסלא ופסק רבינו כלשון האחרון אלא דלפי זה צריך להגיה שמא כיונה לשם חליצה דלהך לישנא אפי' לא כיון הוא אלא היא כיונה חליצה פסולה היא וכ\"כ האלפסי והרמב\"ם כלשון אחרון וכתב חיישינן שמא כיונה וכ\"כ הרא\"ש כלשון הרי\"ף וכן ראיתי בספרי רבינו שהגיהו כיונה במקום כיונו ולפי עניות דעתי דאין צורך להגיה דרבי' נקט כיונו לאורויי בחזינא דחלצה לאחד מהן אע\"פ דידעינן ביבמה דלא כיונה חיישינן שמא היבם נתכוין וכן בדידעינן דהיבם לא כיון חיישינן שמא היבמה כיונה ולכן אמר שמא כיונו לשם חליצה פירוש בשניהם חוששין שמא נתכוין אחד מהם אכן איכא לתמוה במ\"ש הרא\"ש אח\"כ (דף קמ\"ד ע\"א) ומביאו ב\"י וז\"ל יבמה שרקקה תחלוץ מכלל דמיפסלא מאחין קשיא לי אמאי אדחיקו הנך אמוראי להטעותו יאמרו לה שתרוק בפניו ונפסלה לו ואח\"כ יכפוהו לחלוץ ונ\"ל משום דלא מהניא רקיקה ליפסל כיון דידעינן ביבם שלא היה רוצה לחלוץ וכדמסיק בלישנא קמא דכי חזינא חיישינן שמא כיונו שניהם וכשידעינן דאחד מהן לא כיון לא נפסלה החליצה עכ\"ד אע\"פ שאין זה לשונו ואיכא להקשות דעדיין קושייתו במקומה עומדת ללישנא בתרא. ותו קשה דאיהו גופיה הביא לשון הרי\"ף דפסק כלישנא בתרא ואם כן כך הלכה וכאן כתב כלישנא קמא כדי לתרץ קושייתו והוא סותר למ\"ש מתחילה ונראה דדעת הרא\"ש היא לתרץ דהני אמוראי דנטרחו להטעותו ולא אמרו ליבמה לרוק בפניו כדי שתיפסל עליו סבירא להו כלישנא קמא אי נמי חששו ג\"כ לחומרא דלישנא קמא דכיון דאינה נפסלת ברקיקה זו א\"כ אינו בדין לכופו לחלוץ מיהו ודאי קי\"ל כלישנא בתרא דחליצה פסולה היא בנתכוין אחד מהם לפוסלה על האחין ולפוסלה לכהונה ואזלי הכא והכא לחומרא:","\u0003וכן אם רקקה לפני היבם בפני בי\"ד וכו'\u0004 פי' לא מיבעיא בראינו שחלצה דכיון דלאו אורח ארעא הוא שתהא אשה חולצת המנעל מרגל איש אם לא שמכוונת לפטור עצמה ממנו מזיקתה הילכך חיישינן שמא כיונה לשם חליצה ואסורה להתייבם אע\"פ שלא חלצה בפני ב\"ד אבל ברקיקה דאורח ארעא לרוק לפני איש ואין אשה יכולה ליזהר מזה לא חיישינן שכיונה לשם חליצה אלא ברקקה בפני ב\"ד:","\u0003ומ\"ש ומיהו דוקא כשרקקה רוק וכו'\u0004 כ\"כ הרא\"ש בשם הראב\"ד (דף קמ\"ד סוף ע\"א) דברקקה דם במקום חליצה לא בעינן צחצוחי רוק דמי כתיב באורייתא וירקה רוק אבל ברייתא דמצרכה צחצוחי רוק הוא דוקא כשרקקה שלא במקום חליצה דלפוסלה מן היבום משום דגזרינן שמא יאמרו מדרקקה ודאי חלצה לה ברישא ואפ\"ה הדרא ומתייבמה ואתא למשרי חלוצה לאחין כי איכא צחצוחי הוא דגזרינן אבל לית בה צחצוחי רוק לא גזרינן:","\u0003חרש וחרשת וכו'\u0004 משנה פרק מ\"ח (דף ק\"ד) החרש שנחלץ והחרשת שחלצה והחולצת לקטן חליצתה פסולה קטנה שחלצה תחלוץ משתגדיל ואם לא חלצה חליצתה פסולה ומסקנת הגמ' דרבא ה\"ק השתא דאמרת חרש וחרשת פסולה דאינן בואמר ואמרה אלם ואלמת נמי פסולה ומתני' דקריאה לא מעכבא כדרבי זירא דכל הראוי לבילה אין בילה מעכבת בו ואמרינן תו אמר רב יהודה אמר רב זו דברי ר\"מ דחליצת קטן בן ט' כגט בגדול אבל חכמים אומרים אין חליצת קטן כלום אפי' לפוסלה עליו דלאו בר דיעה הוא ודינו כשוטה ולא דמי לחרש וחרשת דחשיבי בני דיעה טפי משוטה וקטן לענין חליצה ולכן יש ממש בחליצתה קצת דפוסלת ופסולה וכך כתבו הרי\"ף והרא\"ש אבל הרב רבינו משה בר מיימוני השוה חרש וחרשת לשוטה וקטן ועיין טעמו במ\"ש ה\"ה ומביאו ב\"י אבל רבינו תפס שיטת הרי\"ף והרא\"ש ודחה דעת הרמב\"ם בזה ולא הביאו: והרמב\"ם כתב קטנה וכו' שם (דף ק\"ה) קאמרינן קטנה שחלצה וכו' א\"ר יהודה אמר רב זו דברי ר\"מ דאמר איש כתיב בפרשה ומקשינן אשה לאיש אבל חכ\"א איש כתיב בפרשה אשה בין גדולה בין קטנה ואמר תו קטנה חולצת בפעוטות כבר שית כבר שבע ופירש\"י לענין חליצה כשירה משהיא בפרק הזה שיודעת מעט להבחין רבא אמר עד שתגיע לעונת נדרים שנה אחת קודם לזמן ב' שערות והילכתא עד שתביא ב' שערות וכתב ה\"ה ומשמע דכיון דמסקנא דגמרא והילכתא עד שתביא ב' שערות שאפי' בדיעבד פסולה וכדברי הרב רבינו משה בר מיימוני וכ\"כ בנ\"י וז\"ל ומיהו מדקי\"ל דאינה חולצת עד שתביא ב' שערות איפשר דבדיעבד נמי פסלינן כרבי אליעזר בתוספתא וכתב הריטב\"א ומיהו לא איתברר לן שפיר ונקטינן לחומרא עכ\"ל ואיפשר שזאת היתה דעת הרב רבינו משה בר מיימוני דכיון דלא איתברר בסוגיא היכא דחלצה קודם שהגיע זמן ב' שערות דחליצתה פסולה או אינה כלום ומותרת להתייבם אזלינן לחומרא והעיקר דס\"ל להרמב\"ם דקי\"ל כחכמים דאשה בין גדולה בין קטנה אלא דהאמוראים החמירו דלכתחילה לא תחלוץ עד שתביא ב' שערות מ\"מ ודאי אפי' לא הביאה ב' שערות חליצה היא כחכמים ונפסלה על האחין:","וא\"א הרא\"ש השוה חליצת קטנה לחליצת קטן כתב ב\"י לא מצאתי כן בדברי הרא\"ש אלא בדברי התוס' שכתבו וא\"ת כיון דתנא פסולה אמאי תני תחלוץ משתגדיל ועוד דלא תני גבי קטן וי\"ל דאי לא הוה תני גבי קטנה ה\"א דחליצתה פסולה מדרבנן דהא דמקשינן אשה לאיש אינו מה\"ת להכי תני תחלוץ משתגדיל ייתור לשון אתא לאשמועי' דחליצת קטנה אינה כלום כמו חליצת קטן ע\"כ ומ\"מ יש לתמוה היאך כ' רבינו כן בשם הרא\"ש כיון שלא נמצא כן בדבריו ועוד שגם התוס' לא כתבו כן לקושטא דמילתא שהרי כתבו אח\"כ מיהו בירושלמי גרסי' בסדר המשנה תחלוץ משתגדיל ואם לא חלצה חליצתה כשרה ע\"כ וכיון שהם מסופקים אי גרסי' חליצתה כשרה היאך אפשר לכתוב בשמם דחליצת קטנה אינה כלום כמו חליצת קטן עכ\"ל ושרי ליה מאריה במה שהיה מפרש דבריהם שאמרו אינו כלום היינו שמותרת להתייבם דהלא לפרש דברי ר\"מ באו התוס' ומפורש בגמרא דלר\"מ חליצת קטן וקטנה שוין ופוסלין על האחין דאסורה להתייבם אלא דעת התוס' ליישב הייתור לשון גבי קטנה לר\"מ והוא דגבי קטן פשיטא דהחליצה אינה כלום מן התורה דאיש כתיב בפרשה אבל באשה סד\"א דאשה בין גדולה בין קטנה ולא מקשינן אשה לאיש מן התורה אלא דס\"ל לר\"מ דמדרבנן מקשינן אשה לאיש וחליצת קטנה פסולה מדרבנן להכי נקט ייתור לשון דחליצת קטנה נמי אינה פלוני מן התורה כמו חליצת קטן מיהו ודאי ר\"מ לטעמיה דחליצת קטן וקטנה פסולים ופוסלים מדרבנן אלא דמן התורה אינו כלום וכן מ\"ש אחר כך ומיהו בירושלמי גרסי' וכו' הוא לתרץ הייתור לשון גבי קטנה דכיון דחליצתה כשרה צריך לפרש דאעפ\"י דחליצתה כשרה בדיעבד מ\"מ לכתחלה תחלוץ משתגדיל אבל בקטן דחליצתו פסולה א\"צ לפרש דפשיטא דצריך שתחלוץ משיגדיל כ\"ז כתבו התוס' לר\"מ אבל לחכמים שהם רבי יוסי דאשה בין גדולה בין קטנה ומן התורה חליצתה כשרה אלא דהאמוראים החמירו דמדרבנן עד שתביא ב' שערות איכא ספק אם חלצה מקמי שתביא ב' שערות דשמא חליצה פסולה היא דהא מן התורה לר' יוסי אפילו חליצה גמורה היא או שמא האמוראים הכריעו דמקמי ב' שערות איכו כלום ומותרת להתייבם כר\"מ וספק זה אינו מתברר לא במ\"ש התוספות ולא במ\"ש הרא\"ש לכאורה מיהו נראה לפע\"ד ליישב דברי רבינו דהיה מדקדק בדברי הרא\"ש דלא היה צריך להביא בפסקיו הא דאמר רב יהודה אמר רב זו דר\"מ דאמר מקשינן אשה לאיש אבל חכמים אומרים איש כתיב בפרשה אבל אשה בין גדולה ובין קטנה דכיון דקיימא לן עד שתביא ב' שערות אם כן לית הילכתא כחכמים אדרבה הלכה כר\"מ דאמר דמקשי' אשה לאיש ועד שתביא ב' שערות וכ\"כ סה\"ת וסמ\"ג וזה לשונו וצריך שיהא היבם והיבמה גדולים דאיש כתיב בפרשה ומקשינן אשה לאיש וקאמרינן והלכתא עד שתביא ב' שערות אלא בע\"כ משום דסד\"א דמקמי שתביא ב' שערות חליצה פסולה היא כר\"מ לכך הביא דרב יהודה אמר רב זו דברי ר\"מ וכו' לאורויי דהלכה כחכמים דליכא חליצה פסולה לא בקטן ולא בקטנה דבקטן אין חליצתו כלום ומותרת להתייבם ובקטנה החליצה כשרה לגמרי וכשבאו האמוראים והחמירו עד שתביא ב' שערות לא אתו לדחות לדחכמים ולומר דמקמי שהביאה ב' שערות חליצה פסולה היא כר\"מ דודאי קי\"ל כחכמים דליכא חליצה פסולה אלא או כשרה או אינו כלום ולא באו האמוראים אלא להחמיר דלכתחילה לא תחלוץ עד שתביא ב' שערות וכרבי מאיר אבל אינה חליצה פסולה אם חלצה בעודה קטנה כר\"מ זה נראה דלמד רבינו מדברי הרא\"ש ואע\"ג דגם מדברי הרי\"ף איכא ללמוד כך שלא כתב הרא\"ש בזה אלא כלשון הרי\"ף אפי' הכי תלאו רבינו בהרא\"ש לומר דאע\"פ דהרמב\"ם ראה דברי הרי\"ף וכתב שלא כדבריו אפילו הכי הרא\"ש שבא אחריו וראה דבריו לא הכריע כך אלא השוה קטנה לקטן בזה וכדעת הרי\"ף ולא כהרמב\"ם ולענין הלכה נקטינן כדברי הרמב\"ם המפורשין דחליצה פסולה היא ואף הרי\"ף והרא\"ש כך דעתם שהביאו לדרב לאורויי דאע\"פ דהחמירו האמוראים דעד שתביא ב' שערות אפ\"ה קודם ב' שערות חליצה פסולה היא שהרי לחכמים חליצה פסולה זו יש בה ממש וכשרה לגמרי וא\"כ פשיטא דע\"י חליצה זו אסורה להתייבם ונפסלה על האחין וכדפי' בסמוך דזהו העיקר בדעת הרמב\"ם והכי נקטינן ודלא כרבינו:","\u0003לאחר שחלצה כותבין לה ב\"ד וכו'\u0004 עד שב\"ד לא היו חולצין להם אם לא היו מכירין אותם נראה דרבינו כ\"כ ע\"פ גי' רש\"י דגרס בדרבה ס\"פ מ\"ח אין חולצין אא\"כ מכירין לפיכך כותבין אעפ\"י שאינן מכירין דלא חיישינן לב\"ד טועין ופי' דעדים שראו שחלצה יכולין לכתוב לה גט חליצה ואעפ\"י שאין מכירין דלא חיישינן שמא טעו ב\"ד הראשון בהלכה זו לומר אעפ\"י שאין מכירין ושחלצו לה ממי שאינו יבמה ולכן אמר רבינו שב\"ד לא היו חולצין להם וכו' כלומר דאלו שכותבין להם גט חליצה אין להם לחוש שב\"ד הראשון טעו וחלצו להם אעפ\"י שאין מכירין דלא חיישינן לב\"ד טועין וכ\"כ הרי\"ף אך קשה הלא התוס' הקשו על גירסת רש\"י ופירושו וגורסי' איפכא ורבא הוא דקאמר דחיישינן לב\"ד טועין פי' דנותן טעם על מה שב\"ד ראשון אין חולצין אלא אם כן מכירין משום דחיישינן שמא יטעו ב\"ד האחרון להשיאה ויאמרו שלא עשו ב\"ד הראשון כי אם ע\"י הכרה וכ\"כ הרא\"ש לשם גירסת התוס' ונראה דרבינו סובר דכיון דאין חילוק בין הגרסאות בעיקר הדין כמ\"ש ה\"ה בספ\"ד דייבום ולפי האמת תרוייהו איתנהו לרבא והוא דהעדים כותבין אעפ\"י שאין מכירין משום דאין חוששין דב\"ד הראשון טעו כדפי' וב\"ד הראשון דאין חולצין אא\"כ מכירין היינו משום דחוששין שמא יבואו ב\"ד האחרון לטעות ולומר דב\"ד הראשון לא חלצו אא\"כ הכירו ויסמכו עליהם ויתירום וכדאיתא להדיא בפ' י\"נ דילפינן מדרבא דחיישינן לב\"ד טועים וכ\"כ נ\"י לפיכך לא דק רבינו וכתב לשונו ע\"פ גירסת רש\"י והרי\"ף כיון שאף התוס' והרא\"ש מודים דכך הוא האמת מיהו קשיא ליה לרבא אמאי לא תהא הלכה שב\"ד ראשון לא יחלצו אף ע\"פ שאין מכירין וגם העדים יכתבו אף עפ\"י שאין מכירין כיון דליכא חורבה דאע\"פ שתראה גט זה לב\"ד אחר לא יתירוה לינשא כיון דלא כתב בו ואישתמודענוהו שאין ב\"ד האחרון טועין לומר שאין ב\"ד הראשון חולצין אא\"כ מכירין כיון דהלכה הוא דחולצין אפי' אין מכירין וי\"ל דכשהלכה הוא דאין חולצין אא\"כ מכירין ודאי לא חיישינן דב\"ד טעו וקעבדי איסורא לחלוץ אפילו אין מכירין אבל אם הלכה הוא דרשאין לחלוץ אפי' אין מכירין ודאי דאין זה אלא היכא דהיבם רוצה לילך למ\"ה ומפני הדחק צריכין לחלוץ אעפ\"י שאין מכירין שלא תתעגן אבל ודאי כל ב\"ד יפה מהדרין שיכירו היבם והיבמה קודם שיחלצו לה ומצוה מן המובחר הוא שיכירום לכתחילה ולפיכך חיישינן דב\"ד האחרון יהיו טועים לומר דב\"ד הראשון לא חלצו אא\"כ הכירו דעשו מצוה מן המובחר:"]],["\u0010c0\u0011\u0010y0\u0011אע\"פ שמן התורה גט לא מעלה ולא מוריד ביבמה תקנו חכמים \u0010c1\u0011שכל גט שפוסל באשתו לכהונה כיוצא בו ביבמתו מועיל שאם א' מהאחין נתן לה גט פסלה ואת כל צרותיה עליו ועל כל האחין ואינה ניתרת בו לזר עד שיחלצו לה \u0010c2\u0011וכן המאמר שתקנו בה חכמים אינה קונה בה קנין גמור שאם בא להוציא אחר המאמר אינו יכול להוציאה בגט לבד שלא נפקעה הזיקה ע\"י המאמר \u0010c3\u0011אלא צריכה גט למאמרה וחליצה לאפקועי הזיקה \u0010c4\u0011\u0010y1\u0011וכיון שאין מאמר קונה קנין גמור ולא גט דוחה דחייה גמורה לפיכך מועיל המעשה שנעשה אח\"כ בין גט אחר גט או מאמר אחר מאמר או גט חליצה וביאה אחר המאמר או מאמר וביאה וחליצה אחר גט \u0010c5\u0011בין ביבם אחד וב' יבמות בין ביבמה אחת ושני יבמין בין בשתי יבמות וב' יבמין: \u0010c6\u0011כיצד יבם שנתן גט ליבמתו וחזר ונתן גט לצרתה נאסר בקרובות שתיהן או שני יבמים שנתנו שניהם גט ליבמה אחת זה אחר זה שניהם נאסרו בקרובותיה או שני יבמין ושתי יבמות כל אחד נתן גט לאחת כל אחד נאסר בקרובות של אותה שנתן לה גט \u0010c7\u0011\u0010y2\u0011וכשבאים להוציאה למ\"ד חליצה פסולה צריך לחזור על כל האחין בב' יבמין ויבמה אחת צריכה חליצה מכל אחד ואחד \u0010c8\u0011וכתב הרמב\"ן והוא הדין נמי ביבם אחד וב' יבמות ונתן גט לשתיהן שצריך לחלוץ לשתיהן\u0010c9\u0011 מדברי רש\"י יראה דאפי' אם נאמר בשני יבמין ויבמה אחת צריכה חליצה מכל אחד ואחד ביבם אחד ושתי יבמות נפטרה אחת בחליצת חבירתה ולמ\"ד חליצה פסולה אינה צריכה לחזור על כל האחין בין בשני יבמין ויבמה אחת בין ביבם אחד וב' יבמות סגי בחליצה אחת וכן הוא דעת א\"א הרא\"ש ז\"ל \u0010c10\u0011\u0010y3\u0011וכן יש מאמר אחר מאמר שאם עשה מאמר בזו ואח\"כ בזו או אחין בה או בחבירתה כל אחת צריכה גט למאמרה \u0010c11\u0011וחליצה לאחת מהן לפטור שתיהן \u0010c12\u0011\u0010y4\u0011וכן אם עשה \u0010y5\u0011מאמר בזו ואחר כך נתן גט או חלץ לה או לצרתה או שבא על צרתה או שאחר המאמר שלו נתן לה אחיו גט או חלץ לה או לצרתה או שבא עליה או על צרתה מועיל מה שנעשה אחר מאמר לאסור בעלת המאמר וליאסר בקרובותיה במעשה שנעשה אחר המאמר ולהצריך גט למאמר וביאה שנעשה אחריו וזה תקנתם עשה בה מאמר ונתן לה גט צריכה חליצה עשה בה מאמר וחלץ צריכה גט \u0010c13\u0011עשה מאמר בזו ונתן הוא או אחיו גט לזו נותן גט לבעלת המאמר \u0010y6\u0011והוא או אחיו חולצין לאחת מהן לאיזו שירצה ותפטר האחרת דקי\"ל בעלת גט ובעלת המאמר כי הדדי נינהו \u0010y7\u0011ופירש\"י כי הדדי נינהו וחולץ לאיזו שירצה ותפטר צרתה והריב\"ם פירש ששתיהן צריכות חליצה וא\"א הרא\"ש ז\"ל הסכים לפירש\"י עשה מאמר בזו ובעל הוא או אחיו צרתה צריכות ב' גיטין וחליצה לאחת מהן \u0010c14\u0011עשה מאמר בזו וחלץ הוא או אחיו לזו בעלת המאמר צריכה גט \u0010y8\u0011וכן אם נתן לה גט ואח\"כ בא עליה או עשה בה מאמר או בחבירתה או שחלץ לחבירתה \u0010c15\u0011או שאחר הגט שלו עשה בה אחיו מאמר או בא עליה \u0010c16\u0011או חלץ לה או לחבירתה מועיל מה שנעשה אחר הגט ליאסור בקרובותיה ולהצריך גט למאמר שנעשה אחריו \u0010c17\u0011\u0010y9\u0011וזה תקנתא נתן לה גט ואח\"כ בא עליה או עשה בה מאמר צריכה גט וחליצה נתן לה גט ואח\"כ בא הוא או אחיו על צרתה או שעשו בה מאמר זו שבא עליה או שעשו בה מאמר צריכה גט וחליצה לא' מהן לפטור שתיהן \u0010c18\u0011\u0010y10\u0011הבעילה קונה קנין גמור וכן חליצה דוחה דחייה גמורה לפיכך אין המעשה שנעשה אחריהן מועיל לא לפסול את זו ולא ליאסור בקרובות \u0010c19\u0011כיצד בא על יבמתו וחזר הוא או אחיו וחלץ לה או לצרתה אין אותה החליצה כלום וכן אם אחיו חזר ונתן לה גט או לצרתה אינו כלום \u0010c20\u0011וכן אם חזר ועשה בה מאמר או בעל אינו כלום שכבר היא אשתו של אחיו ואין הקידושין תופסין באשת איש \u0010c21\u0011\u0010y11\u0011אבל אם בא הוא או אחיו על צרתה או עשו בה מאמר צריכה גט וכן אם חלץ ליבמתו וחזר הוא או אחיו וחלצו לצרתה אין אותה חליצה כלום ליאסור בקרובותיה או ב' יבמים שחלצו ליבמה אחת זה אחר זה אין חליצת האחרונה כלום ומותר בקרובותיה \u0010c22\u0011\u0010y12\u0011אבל אם אחד שחלץ ליבמתו בעל או קדש הוא או אחיו אותה או צרתה תפשי להו \u0010y13\u0011בהן קידושין וצריכה גט \u0010c23\u0011בין קדשה לשם אישות כגון שקדשה סתם בין לשם יבמות כגון שאמר לה הרי את מקודשת לי לזיקת יבמין \u0010y14\u0011והראב\"ד כתב קדשה לשם יבמין אינו כלום ואינה צריכה גט וכ\"כ הרמב\"ם ורב אלפס כתב כסברא ראשונה ולזה הסכים א\"א הרא\"ש ז\"ל \u0010y15\u0011והא דאין מעשה מועיל אחר ביאה דוקא בביאה כשירה שלא קדם לה מעשה אחר אבל ביאה פסולה כגון שנתן גט לזו ובעל את זו או \u0010c24\u0011\u0010y16\u0011עשה מאמר בזו ובעל את זו מועיל מעשה שיעשו אחריה שאם יחלוץ הוא או אחיו לשלישית יאסרו בקרובותיה וגם היא לא סגי לה בגט דאכתי נשאר בה זיקה אבל חליצה אפי' היא פסולה שקדם לה מעשה אחר כגון שנתן גט בזו או מאמר בזו ואח\"כ חלץ לה או לצרתה אפ\"ה אין מועיל אחריה כלום עשה מאמר ביבמתו ואח\"כ נתן לה גט לזיקתו פסלה עליו ועל כל האחין וצריכה גט למאמרה וחליצה לזיקתה נתן גט למאמרה ולא לזיקתה נשארה זקוקה כמו שהיתה ופירש\"י שאינה מותרת אלא לשאר האחין אבל המגרש אסור בה \u0010y17\u0011וכן כתב הרמב\"ם וא\"א הרא\"ש ז\"ל כתב שהיא מותרת אף למגרש וכן כתב הראב\"ד \u0010c25\u0011ביאת בן ט' כמאמר בגדול לפיכך בא על היבמה פסלה על כל האחין ואם אהר שבא עליה חזר אחיו הגדול ובא על צרתה או שנתן לה גט או חלץ לה או לצרתה פסלה על הקטן וכן אם חזר הקטן ובא על צרתה או שאחיו \u0010y18\u0011בן ט' בא עליה או על צרתה פסלה עליו כדין מאמר אחר מאמר \u0010y19\u0011וכן אם עשה הגדול מאמר ביבמה וחזר אחיו בן ט' ובא עליה או על צרתה פסלה עליו כדין מאמר אחר מאמר ומאמרו של בן ט' אינו חשוב כמאמר בגדול ואינו מועיל אלא בתחילה אבל לא בסוף כיצד עשה קטן מאמר מועיל לפוסלה על האחין אבל אם עשה הגדול מאמר וחזר בן ט' ועשה בה מאמר או בצרתה אינו מועיל לפוסלה על האח הגדול אבל מאמרו של בן ט' אחר מאמר בן ט' איכא למימר שמועיל כיון שמאמר הראשון מבן ט' וגט וחליצה אין לקטן כלל לא בתחילה ולא בסוף \u0010c26\u0011גדול שעשה מאמר ביבמה או נתן לה גט ולה צרה כשבא לחלוץ א' מהן ולהתירן אין חליצת בעלת הגט או בעלת מאמר פוטרת הצרה אבל חליצת הצרה פוטרת לבעלת הגט לגמרי ולבעלת המאמר מחליצה וצריכה עוד גט למאמר ואם עשה מאמר בזו ונתן גט לזו חולץ לאיזו שירצה ופוטר השנייה כדפרישית לעיל \u0010y20\u0011וכתב הרמב\"ם וכן אם נפלו לפניו איסור לאו או איסור עשה וצרתה חלץ לאסורה לא הותרה הצרה חלץ לצרה הותרה האסורה \u0010c27\u0011\u0010y21\u0011ג' אחיות יבמות שנפלו לפני ב' אחין יבמין אם נפלו כאחד שלא הספיקה ראשונה לחלוץ עד שנפלה שנייה ושלישית קאמר רב ששלשתן צריכות חליצה מכל אחד מהאחין ואם נפלה האחת תחילה וחלץ לה א' מהם כשתפול השנייה יחלוץ השני וכשתפול השלישית צריכה חליצה מכל אחד ואחד שחליצה פסולה צריכה לחזר על כל האחין ושמואל אמר בין שנפלו כאחד כין בזה אחר זה חולץ לכולן ואיכא תרי שינויין בגמר' לשינוייא קמא אחד חולץ לאחת והשני לשנייה ואחד מהם איזה שירצה חולץ לשלישית דכל היכא דמצי למיחלץ חליצה כשרה לא תחלץ חליצה גרועה ולאידך שינוייא אחד חולץ לכולן אפילו בתחילה דלפטור נפשה פטרה אפילו בחליצה גרועה ופסק הרמ\"ה כרב וכ\"פ הרמב\"ן \u0010c28\u0011\u0010y22\u0011והרמב\"ם כתב יבמות רבות שנפלו מבית אחד שנבעלה אחת מהן ביאה פסולה או שניתן לה מאמר פסול כולן נאסרות ליבום וצריכה גט אותה שנבעלה או שניתן לה המאמר וצריכה אחת מהן חליצה להתירה לשוק נחלצה אחת מהן חליצה פסולה הותרה לינשא לזר אותה שנחלצה אבל צרתה אסורה עד שתחלוץ גם היא או עד שיחלצו כל האחין לאותה שנחלצה חליצה פסולה שאין חליצה פסולה מסלקת היבום עד שתחזור על כל האחין ע\"כ \u0010c29\u0011\u0010y23\u0011ויראה מדבריו שפוסק כשמואל וכשינויא קמא דלפטור נפשה פטורה בחליצה גרועה והראב\"ד פסק ג\"כ כשמואל וכשינויא בתרא דאפילו לפטור נפשה אם אפשר בחליצה כשירה לא תחלוץ חליצה גרועה הילכך לכתחלה זה חולץ לאחת וזה חולץ לאחת ואחד מהם לשלישית ואי עבר חד וחלץ לכולהו מאי דעבד עבד ולזה הסכים א\"א הרא\"ש ז\"ל \u0010c30\u0011\u0010y24\u0011כתב הרמב\"ם שני יבמין שייבמו שני יבמות הבאות מבית אחד ולא נודע מי ייבם תחילה שניהם יוציאו בגט ויותרו לזרים ואסורות ליבמיהם לפיכך ראובן שהיה בירושלים ולו ב' נשים אחת בעכו ואחת בצור ושמעון אחיו בעכו ולוי אחיו בצור ושמעו שמת ראובן לא ייבם אחד מהם עד שידע מה עשה אחיו קדם אחד מהם וייבם אין מוציאין מידו עד שיודע שאחיו ייבם תחלה רצה לחלוץ קודם שידע מה שעשה אחיו אין מונעין אותו:",["אע\"פ שמן התורה גט לא מעלה ולא מוריד ביבמה תקנו חכמים שכל גט שפוסל באשתו לכהונה כיוצא בו ביבמתו מועיל כולי וכן המאמר שתקנו בה חכמים אינו קונה בה קנין גמור כו' כל זה פשוט בפרק ר\"ג (יבמות דף נ:) ואמרו שם מ\"ט אמור רבנן גט ביבמה מהני משום דמהני בעלמא דאי אמרת לא מהני אמרי גט להוציאה וחליצה להוציאה ומדגט לא מהני חליצה נמי לא מהני ואתי למיבעל אחר חליצה ומ\"ט אמור רבנן מאמר ביבמה מהני משום דמהני בעלמא דאי אמרת לא מהני אמרי מאמר לקנות וביאה לקנות ומדמאמר לא מהני ביאה נמי לא מהני ואתי למיבעל אחר ביאה ופירש\"י מ\"ט אמור רבנן מאמר ביבמה מהני לאסור חבירתה עליו ואתו למיבעל אחר ביאה וה\"ל בונה ב' בתים דאיסורא דאורייתא ומה שתלה רבינו הדבר בגט שפוסל באשתו לכהונה שם (דף נב:) בעא מיניה אביי מרבה נתן לה גט וא\"ל הרי את מגורשת ממני ואי את מותרת לכל אדם מהו גט יבמה דרבנן הוא גט שמהני בא\"א מהני ביבמה גט דלא מהני בא\"א לא מהני ביבמה או דילמא אתי לאיחלופי בגיטא מתקיף לה רבה בר חנן אלא מעתה יהיב לה ניירא בעלמא הכי נמי דפסלה א\"ל התם לא פסיל בכהונה הכא קפסיל בכהונה דתניא אשה גרושה מאישה לא יקחו אפי' לא נתגרשה אלא מאישה לא יקחו היינו ריח הגט שפוסל בכהונה ומשמע דלמיפשט בעיא אמר רבא הכי וכן כתב הרא\"ש וז\"ל א\"ל חיישינן דילמא אתי לאיחלופי בגיטא דגט ביבמה אינו אלא לפסול וגט זה הואיל ופוסל בכהונה אי לא פסיל הכא אתי למימר דגט מעליא נמי לא פסיל וכן פסק הרמב\"ם ז\"ל בפ\"ה:","וכיון שאין מאמר קונה קנין גמור ולא גט דוחה דחייה גמורה לפיכך מועיל המעשה שנעשה אח\"כ בין גט אחר גט או מאמר אחר מאמר או גט חליצה וביאה אחר המאמר או מאמר וביאה וחליצה אחר גט בין ביבם אחד וב' יבמות בין ביבמה אחת וב' יבמין בין בב' יבמין וב' יבמות כיצד יבם שנתן גט ליבמתו וחזר ונתן גט לצרה נאסר בקרובות שתיהן או ב' יבמים שנתנו גט ליבמה אחת זה אחר זה שניהם נאסרו בקרובותיה או ב' יבמין וב' יבמות כל אחת נתן גט לאחת כל אחד נאסר בקרובות של אותה שנתן לה גט כך היא הגירסא האמיתית בספרי רבינו המדוייקים ודברים אלו מבוארים בפרק ר\"ג (יבמות דף נ: נא.) אליבא דחכמים דסברי יש גט אחר גט ויש מאמר אחר מאמר והלכתא כותייהו:","וכשבאים להוציא' למ\"ד חליצה פסולה צריך לחזור על כל האחין בשני יבמים ויבמה אחת צריכה חליצה מכל א' וא' וכתב הרמב\"ן וה\"הנמי ביבם א' וב' יבמות וכו' ולמ\"ד חליצה פסולה אינה צריכה לחזור על כל האחין כולי וכן הוא דעת א\"א ז\"ל הא דחליצה פסולה צריכה לחזור על כל האחין או לא איתיה בריש פרק ד' אחין (יבמות כז:) ויתבאר בסוף סי' זה:","וכן יש מאמר אחר מאמר שאם עשה מאמר בזו ואח\"כ בזו או אחין בה או בחבירתה כל אחת צריכה גט למאמרה וחליצה לאחת מהן לפטור את שתיהן מבואר בפרק ר\"ג שם:","וכן אם עשה מאמר בזו ואח\"כ נתן גט או חלץ לה או לצרתה או שבא על צרתה או שאחר המאמר שלו נתן לה אחיו גט או חלץ לה או לצרתה או שבא עליה או על צרתה מועיל מה שנעשה אחר מאמר לאסור בעלת המאמר וליאסר בקרובות במעשה שנעשה אחר המאמר ולהצריך גט למאמר וביאה שנעשה אחריו כך הוא הנוסחא האמיתית בספרי רבי' המדוייקים ודברים אלו מתבארים והולכים בסמוך ומ\"ש וזה תקנתם עשה בה מאמר ונתן לה גט צריכה חליצה עשה בה מאמר וחלץ צריכה גט עשה מאמר בזו ונתן גט לזו נותן גט לבעלת המאמר והוא או אחיו חולצין לאחת מהן שם במשנה ופירש\"י צריכה הימנו חליצה ואם רצה לכנוס לא יכנוס דכיון דהתחיל בגירושי' קיימא עליה בלא יבנה: צריכה הימנו גט. דחליצה אפקעתא לזיקה ובעיא גט לאפקועי קידושין דיליה דחליצה לא מפקעא קידושין:","מאמר בזו וגט לזו פסל גט של אחרונה את הראשונה דקם ליה בלא יבנה וצריכה גט למאמרו וחליצה לזיקתו דחליצה לא מפקעא קידושין וגט לא מפקע זיקה:","ומ\"ש והוא או אחיו חולצין לאחת מהן לאיזו שירצה ותפטר האחרת דקי\"ל בעלת הגט ובעלת המאמר כי הדדי נינהו בר\"פ ד' אחין (יבמות כז:) איבעיא להו בעלת הגט ובעלת מאמר איזו מהן קודמת ופירש\"י אחיו שמת ולו ב' נשים ועשה זה מאמר לזו וגט לזו ושוב אסור לייבם דקם ליה בלא יבנה כיון שהתחיל לגרש אי זו מהן הגונה לחלוץ ולפטור צרתה ואסיקנא דכי הדדי נינהו:","\u0003ומ\"ש ופירש\"י דכי הדדי נינהו וחולץ לאי זו שירצה ותפטר צרתה:\u0004 ומ\"ש והריב\"ם פירש ששתיהן צריכות חליצה וא\"א הרא\"ש ז\"ל הסכים לפירש\"י שם עשה מאמר בזו ובעל הוא או אחיו לזו בעלת המאמר צריכה גט שם במשנה מאמר בזו ובעל את זו צריכות ב' גיטין וחליצה ופירש\"י מאמר לזו ובעל את זו אסור לקיימה דהואיל וקמייתא אגידא ביה ה\"ל ב' בתים וצריכות שני גיטין זו גט למאמר וזו גט לביאתו וחליצה לאחת מהן ופוטרת צרתה אבל בגט לחודיה לא נפקא בעלת ביאה הואיל דביאה פסולה היא ע\"כ ויש לתמוה על רבינו למה לא כתב כן:","וכן אם נתן לה גט ואח\"כ בא עליה או עשה בה מאמר או בחבירתה או שחלץ לחבירתה או שאחר הגט שלו עשה בה אחיו מאמר או בא עליה או חלץ לה או לחבירתה מועיל מה שנעשה אחר הגט ליאסר בקרובותיה ולהצריך גט למאמר שנעשה אחריו מתבאר והולך בסמוך:","וזה תקנתא נתן לה גט ואח\"כ בא עליה או עשה בה מאמר צריכה גט וחליצה נתן לה גט ואח\"כ בא הוא או אחיו על צרתה או שעשו בה מאמר זו שבא עליה או שעשו בה מאמר צריכה גט וחליצה לאחד מהן לפטור שתיהן כך הוא הנוסחא האמיתית בספרי רבי' המדוייקים ודברים אלו מבוארים במשנה פרק ר\"ג ופירש\"י נתן גט ועשה מאמר. באותה יבמה עצמה אפי' ר\"ג מודה דיש מאמר אחר הגט דמספקא ליה אי גט דחי או לא ודילמא גט לא דחי ואהני מאמר יבמין בה וכ\"ש לרבנן דאמרי גט דוחה קצת ומשייר קצת אהני מאמר למיקני שיורא דגט וצריך גט למאמרו וחליצה לזיקתו וייבומי לא דמגט קמא קיימא עליה בלא יבנה נתן גט ובעל אסור לקיימה דקמה עליה בלא יבנה וצריכה גט לביאתו וחליצה לזיקתו ובגט לחודיה לא מיפטרא כשאר כונס את יבמתו שיכול לפוטרה בגט משום דהא ביאה פסולה משום גט קמא ולא קניא לגמרי: גט לזו ובעל את זו צריכה גט וחליצה. ואסור לקיימה דקמה עליה בלא יבנה משום גט דראשונה ובגט לחודיה לא נפקא משום דביאה פסולה היא:","הבעילה קונה קנין גמור וכן החליצה דוחה דחייה גמורה לפיכך אין המעשה שנעשה אחריהם מועיל לא לפסול את זו ולא לאסור בקרובות כיצד בא על יבמתו וחזר הוא או אחיו וחלץ לה או לצרתה אין אותה החליצה כלום וכן אם אחיו חזר ונתן לה גט או לצרתה אינו כלום וכן אם חזר ועשה בה מאמר או בעל אינו כלום שכבר היא אשתו של אחיו ואין הקידושין תופסין בא\"א הכל מבואר במשנה פ' רבן גמליאל שם:","ומ\"ש אבל אם בא הוא או אחיו על צרתה או עשו בה מאמר צריכה גט יתבאר בסמוך וכן אם חלץ ליבמתו וחזר הוא או אחיו וחלצו לצרתה אין אותה החליצה כלום ליאסר בקרובותיה או ב' יבמים שחלצו ליבמה אחת זה אחר זה אין חליצת האחרונה כלום ומותר בקרובותיה מבואר במשנה פ' ר\"ג שם:","ומ\"ש אבל אם אחר שחלץ ליבמתו בעל או קדש הוא או אחיו אותה או צרתה תפסי להו בהן קידושין וצריכה גט במשנה פרק ר\"ג קתני בהני אין אחר חליצה כלום ואיתמר עלה בגמרא אמר רב יהודה א\"ר זו דברי ר\"ע דאמר אין קידושין תופסין בחייבי לאוין אבל חכמים אומרים יש אחר חליצה כלום וידוע הוא דהלכה כחכמים וכתבו הרי\"ף והרא\"ש ז\"ל והא נמי דתנן אבל לא אחר בעילה כלום ותנן נמי הבעילה בזמן שהיא בתחלה אין אחריה כלום אליבא דהאי תנא הוא אבל לרבנן הבעילה נמי יש אחריה כגון שני יבמות הבאות מבית אחד שנפלו לפני ב' אחים ובא אחד מהן על אחת וחזר הוא או אחיו וקדש צרתה צריכה הימנו גט דקי\"ל דחייבי עשה הוא כדאמרינן בפ\"ק (יא.) איתמר הבא על יבמתו וחזר הוא או אחד מן האחין ובא על צרתה פליגי בה רב אחא ורבינא חד אמר בעשה וחד אמר בכרת וקי\"ל (פסחים עד:) היכא דפליגי רב אחא ורבינא הלכה כדברי המיקל עכ\"ל וזהו שכתב רבינו לעיל בסמוך אבל אם בא הוא או אחיו על צרתה או עשו בה מאמר צריכה גט וכ\"פ הרמב\"ם ז\"ל בפ\"ה:","ומ\"ש רבינו בין קדשה לשם אישות כגון שקדשה סתם בין לשם יבמות כגון שאמר לה הרי את מקודשת לי לזיקת יבמין בפרק ר\"ג (יבמות דף נב:) תנ\"ה א\"ר אין הדברים הללו אלא לדברי רבי עקיבא שהיה עושה חלוצה כערוה אבל חכמים אומרים יש אחר חליצה כלום ואני אומר אימתי בזמן שקדשה לשם אישות אבל קדשה לשם יבמות אין אחר חליצה כלום תניא אידך החולץ ליבמתו וחזר וקדשה רבי אומר אם קדשה לשם אישות צריכה הימנו גט אבל קדשה לשם יבמות אינה צריכה הימנו גט וחכ\"א בין שקדשה לשם אישות בין שקדשה לשם יבמות צריכה הימנו גט אמר רב יוסף מ\"ט דרבי עשאוהו כעודר בנכסי הגר וכסבור שלו הן דלא קני א\"ל אביי מי דמי התם לא קא מכוין למיקני הכא קא מכוין למיקני הא לא דמיא אלא לעודר בנכסי גר זה וכסבור של גר אחר הוא דקני אלא אמר אביי הב\"ע כגון דא\"ל התקדשי לי במאמר יבמין רבי סבר מאמר עילוי זיקה קא רמי ואתיא חליצה אפקעתא לזיקה ורבנן סברי האי לחודיה קאי והאי לחודיה קאי מעיקרא אילו א\"ל התקדשי לי במאמר יבמין מי לא מהני השתא נמי מהני רבא אמר אי דאמר לה במאמר יבמין כ\"ע ל\"פ דמהני הב\"ע כגון דאמר לה התקדשי לו בזיקת יבמים רבי סבר יש זיקה ואהני חליצה אפקעתיה לזיקה ורבנן סברי אין זיקה מעיקרא אילו א\"ל התקדשי לי בזיקת יבמין מי לא מהני השתא נמי מהני. רב שרביא אמר בחליצה כשרה אי דא\"ל התקדשי לי בזיקת יבמין כ\"ע ל\"פ דלא מהני והכא בחליצה פסולה קמיפלגי מר סבר חליצה פסולה פוטרת ומ\"ס אינה פוטרת רב אשי אמר דכ\"ע חליצה פסולה אינה פוטרת והכא ביש תנאי בחליצה קמיפלגי מ\"ס יש תנאי בחליצה ומ\"ס אין תנאי בחליצה רבינא אמר דכ\"ע יש תנאי בחליצה והכא בתנאי כפול קמיפלגי מ\"ס בעינן תנאי כפול ומ\"ס לא בעינן תנאי כפול ופירש\"י אימתי. יש אחר חליצה תפיסת קידושין: בזמן שקדשה לשם אישות. בקידושין גמורין ולא במאמר יבמים דודאי קידושין תופסין בחייבי לאוין: אבל קדשה לשם יבמות אינם קידושין. שהרי אין כאן צד ייבום וה\"ל קידושי טעות: יש זיקה. האי דתפיס מאמר בעלמא בכי האי לישנא משום דיש זיקה והשתא אתאי חליצתה פקעתה וליכא למימר הכי: אין זיקה. אין כח לזיקה ואפ\"ה הוי מעיקרא מאמר: רב שרביא אמר אי דא\"ל בזיקת יבמין כ\"ע ל\"פ דלא מהני. דיש זיקה ואתאי חליצתה ואפקעתה: והכא בחליצה פסולה. כגון שחלץ אחר הגט קמיפלגי רבנן סברי לא אפקעתה שפיר ויש אחריה כלום הילכך קני מאמר וכתב הרי\"ף בהך פלוגתא דרבי ורבנן קא שקלי וטרו טובא לפרושי פלוגתייהו וכולהו טעמי דאיתאמרו בהאי פלוגתא לא סמכינן עלייהו דלאו אליבא דהילכתא נינהו אלא אוקימתא בעלמא נינהו וליתא לדרבי דקי\"ל הלכה כרבי מחבירו ולא מחביריו הילכך בין שקדשה לשם אישות בין שקדשה לשם יבמות צריכה הימנו גט כרבנן עכ\"ל:","וכתב הרא\"ש ע\"ז כתב הראב\"ד ז\"ל האי פיסקא לא מחוורתא שפיר דהני אוקימתות איכא מינייהו דהילכתא כרבי דהכא ודאי לכולהו דא\"ל התקדשי לי בזיקת יבמין עסקינן ופליגי רבי ורבנן אי אית בה זיקה אחר חליצה אי לאו הילכך לרבא דאמר דפליגי ביש זיקה או לא הא קי\"ל דיש זיקה ובתר חליצה ודאי אין זיקה וכי א\"ל התקדשי בזיקת יבמים לאו כלום הוא ולדברי רב שרביא נמי הא קי\"ל דהאי חליצה פסולה פוטרת כשמואל הלכך בתר חליצה אין כאן זיקה כלל ולדברי רב אשי נמי דאמר ביש תנאי בחליצה פליגי הא קי\"ל דאין תנאי בחליצה ל\"ש כפול ולא שנא שאינו כפול וחליצה מעלייתא היא ואין כאן זיקת יבמין הילכך קידושין לאו כלום הוא עכ\"ל. והרמב\"ן הודה לדבריו ואני אומר שהדין עם הרי\"ף ז\"ל ומה שהקשה עליו דלרבא דאמר דפליגי ביש זיקה הא קי\"ל דיש זיקה ובתר חליצה ודאי אין זיקה אני אומר דהך פלוגתא אי יש זיקה או אין זיקה לא בפלוגתא דיש זיקה ואין זיקה דאיפליגו בה תנאי ואמוראי לעיל אלא ה\"פ רבי סבר יש זיקה כלומר כיון דלא הזכיר מאמר אלא אמר התקדשי לי בזיקת יבמין לא הוי קידושין אי לא דיש זיקה ואתאי חליצה ואפקעיה לזיקה הילכך אי איפשר לקידושין שיחולו אחר שפקעה הזיקה ורבנן סברי אין זיקה אף ע\"פ שלא הזכיר מאמר אלא זיקת יבמין אפילו אין זיקה התקינו רבנן קידושין ביבמה דהא זקוקה ועומדת היא לו ומעיקרא אילו אמר לה התקדשי לי בזיקת יבמין מי לא אהני אף ע\"פ שאין הזיקה גורמת לו שיחול השתא נמי מהני אף ע\"ג דפקעה הזיקה וגרסינן רב שרביא אומר אי א\"ל התקדשי לי בזיקת יבמין כ\"ע ל\"פ דמהני וכן כל האוקימתות על דרך זה לכ\"ע מהני והשתא אין נפקותא בכולהו אליבא דרבנן ומה שהקשה דק\"ל לדברי רב שרביא דהא חליצה פסולה פוטרת כשמואל לא קשה מידי דתיקשי לך רב אשי דאמר דכ\"ע חליצה פסולה אינה פוטרת אמאי קאמר דהני תנאי סברי דלא כהילכתא דכיון דמצי למימר דכולהו סברי דפוטרת והכא לא מיירי בחליצה פסולה אלא ביש תנאי בחליצה קא מיפלגי וכן רבינא דאמר דכולהו סברי יש תנאי בחליצה ופליגי בתנאי כפול אמאי דחיק לאוקומי פלוגתייהו דלא כהלכתא דקי\"ל דאין תנאי בחליצה אלא נראה להני אמוראי דבסברא מועטת אמרינן דלרבנן מהני מאמר יבמין או זיקת יבמין ואף אחר החליצה הילכך לרבא אף ע\"ג דרבנן סברי יש זיקה הכא אין הקידושין תופסין מכח הזיקה כדפרישית הילכך מהני אף אחר חליצה ורב שרביא אמר דבזיקת יבמין אף רבי מודה ופליגי בחליצה פסולה דרבנן סברי דאינה פוטרת לענין זה שלא יועילו בה קידושין לשם יבמות אחריה דבקל אמרינן דמהני קידושין לשם יבמות אחר חליצה ורב אשי אמר דבחליצה פסולה אף רבי מודה ופליגי ביש תנאי בחליצה דרבנן סברי דיש תנאי בחליצה לענין זה שנשאר אחריה זיקה לתפוס בה קידושין לשם יבמות ורבינא אמר דאף בזה מודה רבי ופליגי בתנאי כפול עד כאן לשונו וכ\"פ הרמב\"ם ז\"ל בפ\"ה דבין שקדשה לשם אישות בין קדשה לשם יבמות תפסו בה קידושין כרבנן ועיין בר\"י:","והא דאין מעשה מועיל אחר ביאה דוקא בביאה כשרה שלא קדם לה מעשה אחר אבל ביאה פסולה כגון שנתן גט לזו ובעל לזו או עשה מאמר בזו ובעל את זו מועיל מעשה שיעשה אחריה שאם יחלוץ הוא או אחיו לשלישית יאסרו בקרובותיה וגם היא לא סגי לה בגט ואכתי נשאר בה זיקה אבל חליצה אפי' היא פסולה שקדם לה מעשה אחר כגון שנתן גט בזו או מאמר בזו ואחר כך חלץ לה או לצרתה אפי' הכי אין מועיל אחריה כלום בפרק ר\"ג (יבמות דף נ:) תנן אין אחר חליצה כלום בין בתחלה בין באמצע בין בסוף והבעילה בזמן שהיא בתחילה אין אחריה כלום באמצע ובסוף יש אחריהן כלום נחמיה אומר אחת חליצה ואחת ביאה בין בתחלה בין באמצע בין בסוף אין אחריהם כלום וידוע דהלכה כת\"ק ופירש רש\"י בין בתחלה בין באמצע. בין מאמר לגט כגון גט לזו וחלץ לזו וחזר ועשה בה מאמר או בבעלת הגט לא מהני מאמר ולא בעיא גט למאמרו: בסוף. אחר גט ומאמר חלץ אין אחריה כלום וחליצה גמורה היא ואי הדר עביד מאמר לא בעיא גט דחליצה גירושין גמורים היא וקמה עליה בלאו גמור ואף ע\"ג דחליצה פסולה הואי: הביאה באמצע. כגון גט לזו ובעל לזו וחזר ועשה מאמר בשלישית אסור בקרובותיה: בסוף. גט לזו ומאמר לזו וחזר ובא על האחת יש אחר ביאה זו זיקת יבמין וכי מפיק לה בעיא חליצה ולא סגי לה בגט: וה\"ז דפירש\"י דאחר חליצה לא מהני מאמר כבר נתבאר דהיינו לר\"ע דסבר אין קידושין תופסין בחייבי לאוין אבל לרבנן דפליגי עליה מהני מאמר אחר חליצה ולפיכך סתם רבינו דבריו וכתב אבל חליצה אפי' היא פסולה כו' אפ\"ה אין מועיל אחריה כלום וסמך על מ\"ש קודם לכן דהיינו דוקא בחזר הוא או אחיו וחלץ לה או לצרתה אבל אם בעל או קידש תפסי בה קידושין אחר חליצה כשרה וכ\"ש אחר חליצה פסולה:","עשה מאמר ביבמתו ואחר כך נתן לה גט לזיקתה פסלה עליו ועל כל האחים וצריכה גט למאמרה וחליצה לזיקתה נתן גט למאמרה ולא לזיקתה נשארה זקוקה כמו שהיתה ופירש\"י שאינה מותרת אלא לשאר האחין וכו' בפרק ד' אחין (יבמות דף לב.) אמר רבא נתן גט למאמרה הותרה צרתה אבל היא אסורה דמיחלפא בבעלת הגט איכא דאמרי אמר רבא נתן גט למאמרה הותרה אפי' היא מ\"ט מאי דעבד בה שקליה ופירש\"י מאי דעביד שקליה. ודוקא שפי' למאמרו ולא לזיקתו אבל סתמא קיימא בלא יבנה אכולהו אחים. וכתב הרא\"ש ז\"ל ואזלינן לקולא בשל סופרים כלישנא בתרא והוא שפירש למאמרו ולא לזיקתו ובפרק ר\"ג (יבמות דף נב:) גרסינן בעי רב חנניא כתב גט למאמרו ולא לזיקתו לזיקתו ולא למאמרו מהו מאמר עילוי זיקה רמי וה\"ל כמגרש חצי אשה ולא עשה כלום או דילמא האי לחודיה קאי והאי לחודיה קאי ותפשוט ליה מדרבא דאמר נתן גט למאמרו הותרה צרתה לרבא פשיטא ליה לרב חנניא מיבעיא ליה וכתב הרא\"ש ז\"ל ומדפשיטא ליה לרבא עבדינן כוותיה ומהני אם נתן גט למאמרו ולא לזיקתו לזיקתו ולא למאמרו דהאי לחודיה קאי והאי לחודיה קאי. ורש\"י פי' אם נתן גט למאמרו. ולא לזיקתו אסור. לו ומותרת לאחיו דמאמר דעבדיה שקליה ופש לה זיקה כדמעיקרא והתוספות כתבו דאין חילוק בין לו ובין אחיו דממ\"נ להאי לישנא דאמר רבא הותרה אפי' היא אם כן ה\"נ שריא אפילו לדידיה ולהך לישנא דאמר רבא דהיא אסורה משום דמחלפא בבעלת הגט א\"כ ה\"נ אסורה אפילו לאחיו דהא אם נתן גט ליבמתו אסרה על כל האחין ולא דמי להא דשרי רבא צרתה כשנתן גט למאמרו דהתם בב' יבמות הבאות מב' בתים איירי שאפילו היה נותן גט אף לזיקתה היתה האחרת מותרת לו ומיהו בזה יש חילוק אם נתן גט למאמרו חולץ לה ושריא ואם נתן לזיקתו צריכה עוד גט שני למאמרו כי הגט הראשון לא הפקיע המאמר עכ\"ל:","ומ\"ש רבינו שהרמב\"ם כתב כפירש\"י ז\"ל הרמב\"ם בפ\"ה נתן מאמר ליבמתו וחזר ונתן גט למאמרו מה שעשה הרי בטלו והותרה ויראה לי שלא הותרה אלא לאחיו אבל זה שנתן הגט אסורה היא לו נתן גט לזיקתו ולא למאמרו פסלה עליו ועל שאר האחין כמו שביארנו וצריכה גט למאמרו וחליצה להתירה לזר עכ\"ל: וכתב ה\"ה נתן מאמר ליבמתו כו' בפ' ד' אחין אמר רבא נתן גט למאמרו כו' ופסק כלישנא בתרא להקל בשל דבריהם ופירש\"י הותרה אפילו היא לאחין אבל לא לדידיה וזהו כדעת רבינו ובהשגות א\"א בגמרא בלישנא בתרא אמרינן הותרה לו אפילו היא ע\"כ סובר הרב ז\"ל שכיון שאמרו סתם הותרה לו אפילו היא משמע אפילו לדידיה וכבר דחו טעם זה ואמרו דהתם קאי אמתני' דג' אחין נשואין ג' נשים נכריות ומת א' מהן ועשה בה הב' מאמר ומת הרי אלו חולצות ולא מתייבמות לפי שיש אחת מהן שיש עליה זיקת ב' יבמין ועלה קאמר רבא שאם נתן גט למאמרו הותרה אפילו היא לאח הנשאר ויכול לייבמה אם ירצה ומ\"ה לא איצטריך לפרושי דלדידיה אסורה וזה דעת הרשב\"א ז\"ל וכ\"נ מדברי הרמב\"ן ז\"ל עכ\"ל ועיין בר\"י:","ביאת בן ט' כמאמר בגדול ברייתא סוף פרק האשה רבה (יבמות דף צו.) ומ\"ש לפיכך בא על היבמה פסלה על כל האחין ואם אחר שבא עליה חזר אחיו הגדול ובא על צרתה או שנתן לה גט או חלץ לה או לצרתה פסלה על הקטן וכן אם חזר הקטן ובא על צרתה או שאחיו בן ט' בא עליה או על צרתה פסלה עליו כדין מאמר אחר מאמר וכן אם עשה הגדול מאמר ביבמה וחזר אחיו בן ט' ובא עליה או על צרתה פסלה עליו כדין מאמר אחר מאמר ומאמרו של בן ט' אינו חשוב כמאמר בגדול ואינו מועיל אלא בתחלה אבל לבסוף לא כיצד עשה קטן מאמר מועיל לפוסלה על האחין אבל אם עשה הגדול מאמר וחזר בן ט' ועשה בה מאמר או בצרתה אינו מועיל לפסלה על האח הגדול אבל מאמרו של בן ט' אחר מאמר בן ט' איכא למימר שמועיל כיון שמאמר הראשון מבן ט' וגט וחליצה אין לקטן כלל אלא בתחלה ולא בסוף בסוף פרק האשה רבה (שם) תנן בן ט' שנים ויום אחד הוא פוסל ע\"י אחין והאחין פוסלין על ידו אלא שהוא פוסל תחלה והאחין פוסלין תחלה וסוף כיצד בן ט' שנים ויום אחד שבא על יבמתו פסל ע\"י אחין באו עליה אחין עשו בה מאמר נתנו גט או חליצה פסלו ע\"י בן ט' שנים ויום אחד שבא על יבמתו ואח\"כ בא עליה אחיו שהוא בן ט' שנים ויום אחד פוסל על ידו ר\"ש אומר לא פוסל בן ט' שנים ויום אחד שבא על יבמתו ואח\"כ בא על צרתה פוסל ע\"י עצמו ר\"ש אומר לא פוסל וידוע דהלכה כת\"ק ופירש\"י פוסלין על ידו דביאתה לא קניא לגמרי אלא כמאמר בעלמא והא קי\"ל דיש מאמר וגט וביאה וחליצה אחר מאמר: פוסל על ידו. דה\"ל כמאמר אחר מאמר דשניהם תופסין בה וכיון דבעיא גט משני קם כוליה ביתא עליה בכיון שלא בנה שוב לא יבנה ובכגון דבביאת שני שגגה דאי במזיד הא קי\"ל ביאתו ביאה ונהרגת עליו: פסלה. לראשונה על עצמו כ\"ש לשנייה דבית אחד הוא בונה ואינו בונה ב' בתים וכיון דאין ביאתו בראשונה קנין גמור מהניא ביאת שנייה להצריכה גט וכיון דצריכה גט קם כוליה ביתא בלא יבנה ובגמרא (שם) בן ט' שנים ויום אחד תחלה פסיל בסוף לא פסיל והא תני רב זביד בר אושעיא העושה מאמר ביבמתו ואח\"כ בא אחיו בן ט' שנים ויום אחד עליה פסלה אמרי ביאה פסיל אפילו בסוף מאמר תחלה פסיל בסוף לא פסיל וביאה אפי' בסוף פסיל והא קתני אלא שהוא פוסל תחלה והן תחלה וסוף כיצד בן ט' שנים ויום א' שבא על יבמתו כו' חסורי מחסרא וה\"ק בן ט' שנים ויום א' הוא פוסל תחלה והם פוסלים תחלה וסוף בד\"א במאמר אבל ביאה פוסלת אפי' בסוף כיצד בן ט' שנים ויום אחד הבע\"י פסל ע\"י אחין ומי אית ליה מאמר כלל ע\"י אחין והתניא בן ט' שנים ויום אחד הוא פוסל בדבר אחד והאחין פוסלין על ידו בד' דברים הוא פוסל ע\"י אחים בביאה והאחין פוסלין על ידו בביאה במאמר בגט ובחליצה ביאה דפסלה בין בתחלה בין בסוף פסיקא ליה מאמר דבתחלה פסיל בסוף לא פסיל לא פסיקא ליה איתמר נמי א\"ר יהודה אמר שמואל יש לו גט וכן א\"ר תחליפא בר אבימי יש לו מאמר תנ\"ה יש לו גט ויש לו מאמר דברי ר\"מ וסבר ר\"מ יש לו גט והתניא עשו ביאת בן תשע כמאמר בגדול ר\"מ אומר עשו חליצת בן ט' כגט בגדול ואם איתא ליתני כגיטו א\"ר הונא בריה דרב יהושע אית ליה וזוטר לר\"ג דאמר אין גט אחר גט ה\"מ בגדול אחר גדול וקטן אחר קטן אבל קטן אחר גדול מהני לרבנן דאמרי יש גט אחר גט ה\"מ בגדול אחר גדול וקטן אחר קטן אבל קטן אחר גדול לא מהני וכ' הרא\"ש נראה דלר\"מ דאמר יש לו חליצה כ\"ש ביאה אבל לרבנן דוקא ביאה יש לו אבל חליצה אין לו כלל ומתני' וברייתא דלעיל דקתני בן ט' פוסל ע\"י אחין בדרך אחד והאחין פוסלין על ידו בד' דרכים רבנן הוא דלר\"מ חליצה פוסלת תחלה וסוף כגט של גדול והשתא לר\"מ יש לו גט וכ\"ש מאמר אבל לרבנן מאמר יש לו כדמוכח לעיל דמאמר בתחלה פוסל אבל בגט שהוא במקום חליצה לא והא דקאמרי רבנן כמאמר בגדול ולא אמרו עשו ביאתו כמאמרו י\"ל דאית ליה מאמר וזוטר כדשני בגט לר\"מ ונראה דהלכה כרבנן וביאתו פוסלת תחלה וסוף ומאמרו דוקא תחלה ומהאי טעמא נמי לא אמרו חכמים ביאתו כמאמרו וחליצה וגט אין לו והא דאמר שמואל גט יש לו אליבא דר\"מ קאמר דלא תימא מדקאמר כגט בגדול אלמא קטן אין לו גט וכן הא דאמר יש לו מאמר אליבא דרבנן קאמר דלא תימא מדקאמר כמאמר בגדול אלמא קטן אין לו מאמר דאי אליבא דחד תנא קאמר שמואל כיון דאמר דיש לו גט כ\"ש מאמר עכ\"ל וגם הרמב\"ם בפ\"ה פסק כת\"ק דברייתא דפליג על ר\"מ וכתב ה\"ה שכן נראה מן ההלכות וגם בעל המאור כ' שכן הדברים מוכיחים דע\"כ לא קאמר בגמרא יש לו גט אלא לטעמיה דר\"מ דאמר יש לו חליצה אבל לרבנן דאמרי אין חליצת קטן כלום ה\"ה לגיטו ע\"כ ונתבארו דברי רבינו ור\"י כתב סברא אחרת בשם הרמ\"ה ואיכא למידק במ\"ש רבינו ואם אחר שבא עליה חזר אחיו הגדול ובא על צרתה או שנתן לה גט כו' למה לא כתב חזר אחיו הגדול ובא עליה או על צרתה ואפשר כיון דכתב שאם חזר אחיו הגדול ובא על צרתה פסלה על הקטן כ\"ש אם בא עליה בעצמה ומיהו אכתי איכא למידק למה השמיט שאם עשה בה אחיו הגדול מאמר פסלה על הקטן כדתנן בהדיא וגם הרמב\"ם ז\"ל בפ\"ה השמיט זה ויש לתמוה עליהם:","גדול שעשה מאמר ביבמה או נתן לה גט ולה צרה כשבא לחלוץ אחד מהם ולהתירן אין חליצת בעלת הגט או בעלת המאמר פוטרת הצרה אבל חליצת הצרה פוטרת לבעלת הגט לגמרי ולבעלת המאמר מחליצה וצריכה עוד גט למאמרה בר\"פ ד' אחין (יבמות דף כז.) אמר שמואל חלץ לבעלת הגט לא נפטרה צרה לצרה נפטרה בעלת הגט חלץ לבעלת המאמר לא נפטרה צרה לצרה נפטרה בעלת המאמר ופירש\"י לבעלת הגט. ב' יבמות מאח א' ונתן יבם גט לא' מהן שוב אין חליצתה הוגנת כ\"כ דקלישא זיקתה ואם חלץ לה לא נפטרה צרה: חלץ לבעלת מאמר. עשה מאמר באחד מנשי המת ואח\"כ חלץ לה לא נפטרה צרה שחליצה זו אינה פוטרת לגמרי שעדיין צריכה גט למאמרו כדתנן בפרק ר\"ג ואע\"ג דיהיב לה גט אחר דחליץ לה הוא דמהניא אבל צרתה צריכה חליצה אבל חלץ לצרה נפטרה בעלת המאמר מחליצה ואינה צריכה אלא גט למאמרו: ומ\"ש ואם עשה מאמר בזו ונתן גט לזו חולץ לאיזו שירצה ופוטר השנייה שם בעיא ואיפשיטא דכי הדדי נינהו ור\"י פירש דהיינו לומר ששתיהן צריכות חליצה אבל רש\"י פירש דהיינו לומר שחולץ לאי זו שירצה ותפטר צרתה. וכבר כתב רבינו כן בראש סימן זה ולפי שהרא\"ש הסכים לפירש\"י סתם רבינו הדברים כפירש\"י:","\u0003וכתב הרמב\"ם ז\"ל וכן אם נפלו לפניו איסור לאו או איסור עשה וצרתה כו'\u0004 בפ\"ז כתב כן גבי חלץ לאחיות ולא נפטרו צרות כו' וז\"ל יראה לי שכך הדין בשתי יבמות הבאות מבית אחד והאחת מהן אסורה על יבמה משום שנייה או מחייבי לאוין או מחייבי עשה שאם חלץ לאסורה לא הותרה צרתה חלץ לצרה הותרה האסורה: וכתב ה\"ה סברת רבינו בזה נראית נכונה שהרי חליצה פסולה הנזכרת בסמוך היא מפני שאין האחיות מתייבמות משום דהויא כל חדא אחות אשה בזיקה ואין זה אלא מדרבנן ואעפ\"כ אין חליצתה פוטרת צרתה וא\"כ מ\"ש שנייה או חייבי עשה וחייבי לאוין שכולן אינן עולות ליבום ולמה תפטור חליצתן צרותיהן אלא משמע דכולן שוות אבל בה\"ג ז\"ל כתב מי שהיה נשוי ב' נשים שנייה ליבם ואחרת כשהוא מייבם מייבם לאחרת כשהוא חולץ חולץ לשנייה ע\"כ וזה היפך מדברי רבינו ויש מן המפרשים סוברים כן ואומרים שלא אמרו חליצה פסולה אינה פוטרת אלא כגון שנאסרה עליו בזיקה כגון זו דאחיות או שעשה בה מאמר או נתן לה גט או חליצת מעוברת או האשה שהלך בעלה למ\"ה ושמע שמת ולא מת כמו שאכתוב בפ\"ט אבל בשנייה וכיוצא באלו שהן אסורות מתחלתה חליצה כשרה הוא ופוטרת צרתה אלו דבריהם ואין בחילוק זה טעם נכון אלא שסמכו על התוס' דקתני היתה הא' אסורה על א' מן האחין איסור ערוה וחלץ לה לא עשה כלום ולא פטר צרתה אלא או היא או צרתה מתייבמת לשאר אחין פי' אפי' מתייבמת היתה איסור מצוה ואיסור קדושה פי' שניות וחייבי לאוין חלץ לה או בא עליה נפטרה צרתה ע\"כ ואיפשר שדעת רבינו דהך ברייתא אתיא דלא כשמואל וכיון שלא הקשו ממנה בגמר' לשמואל לא סמכי' עלה דאם איתא ה\"ל לאתויי בגמרא וא\"ת שיש חילוק ביניהן ושמואל מודה בזו ה\"ל לפרושי והברייתא הנזכרת פרק כיצד איסור מצוה ואיסור קדושה בא עליה או שחלץ לה נפטרה צרתה י\"ל דצרתה שהיא [כיוצא בה] קאמר אלא שאין זה מספיק לתרץ דברי רבי' לפי דעתו שהוא סובר דחליצה פסולה אינה פוטרת כיוצא בה כמ\"ש בפ\"ה וברייתא זו צריכה תלמוד לפי דבריו ז\"ל עכ\"ל:","ג' אחיות יבמות שנפלו לפני ב' אחים יבמים נפלו כאחת שלא הספיקה ראשונה לחלוץ עד שכפלה שנייה ושלישית כו' בר\"פ ד' אחין (יבמות דף כו.) אמר רבה בר רב הונא אמר רב ג' אחיות יבמות שנפלו לפני ב' אחין יבמין זה חולץ לאחת וזה חולץ לאחת ואמצעית צריכה חליצה משניהם א\"ל רבא מדקאמרת אמצעית צריכה חליצה משניהם קסברת יש זיקה וה\"ל חליצה פסולה וחליצה פסולה צריכה לחזור על כל האחין אי הכי קמייתא נמי אי דנפול בבת אחת הכי נמי לא צריכא דנפול בזו אחר זו נפלה חדא חלץ לה ראובן נפלה אידך חלץ לה שמעון נפלה אידך חלץ לה האי מפקע זיקתו חלץ לה האי מפקע זיקתו והאמר רב אין זיקה לדברי האומר יש זיקה קאמר ושמואל אמר אחד חולץ לכולן מכדי שמעינן לשמואל דאמר חליצה מעליא בעינן דאמר שמואל חלץ לאחיות לא נפטרו צרות הכא דקיימא חליצה דשמעון כשרה חלץ לה ראובן חליצה פסולה מאי אחד חולץ לכולן נמי דקאמר אאמצעית והא כולן קאמר כיון דרובא גביה קרי ליה כולן ואב\"א כי קאמר שמואל חליצה מעליא בעינן ה\"מ למיפטר צרתה אבל מיפטר נפשה פטרה ופירש\"י מדקאמר צריכה חליצה קסבר יש זיקה וה\"ל חליצה פסולה וחליצה פסולה צריכה לחזור וכו' כלומר מדקאמרת צריכה חליצה משניהם קסברת אלימא מצות זיקת יבמין למרמי אתרוייהו והך חליצה ע\"כ חליצה פסולה היא כלומר גרועה שאם רצה לייבם אינו יכול דאחות חלוצתו היא הילכך לא מעלייתא היא וצריכה לחזר על כולן דלא מפקעא זיקה דתרוייהו בחליצה דחד משום דאלימא זיקה ורמי אתרוייהו: קמייתא. ב' ראשונות נמי ליבעו חליצה משניהם דחליצתו נמי לא מעלייתא היא דאי בעי ליבומי לא מצי הואיל ויש זיקה: בבת אחת. כלומר אם באו לחלוץ כאחת שלא הספיקה הראשונה לחלוץ עד שכפלה גם השנייה והשלישית ה\"נ דכולן צריכות לחזר אחר כל האחין הכא דנפלו זו אחר זו נפילתה של זו אחר חליצתה של זו נפלה לה חדא חלץ לה ראובן וחליצה כשרה היתה שאם רצה יכול לייבם נפלה אידך חלץ לה שמעון וגם זו כשרה שאם רצה מייבם ואין כאן אחות זקוקה שכבר חלצה אחותה קודם נפילה זו נפלה שלישית אי בעי ליבומי לא מצי דאחות חלוצת שניהם היא ובולא כלום נמי לא נפקא דאחות חלוצה אינה אלא מד\"ס הילכך חלץ האי חליצה כל דהו ולאו מעלייתא היא שאם חפץ לא ייבם ומיהו חליצתו וזיקתו שוות שתיהן לגרוע ופקעה זיקתו בחליצתו וחלץ האי מפקע זיקה: היכא דקיימא חליצה דשמעון חליצה כשרה. לחלוץ לשנייה שהוא לא חלץ לראשונה חלץ לה ראובן חליצה פסולה בתמיה ראובן שחלץ לראשונה והויא הך אחות חלוצתו ולא חליצה מעליא היא כדשמעון דזיקה גרידתא היא: אאמצעית. כלומר השלישית לאחר שחלץ שמעון לשנייה שהיא על שניהם אחות חלוצה ושניהם שוין בה וקסבר חליצה פסולה אין צריכה לחזור על כל האחין: כיון דרובא גביה. שהחולץ לשלישית חלץ לשתים: למפטר צרה. כדקאמרי' לא נפטרו צרות: אבל נפשה פטרה. בחליצה כל דהו הילכך א' חולץ לג' היכא דליכא צרות בהדייהו: וכתב נמוקי יוסף והכי הלכתא כשמואל ואע\"ג דבעלמא הלכתא כרב באיסורי שאני הכא דלרב אליבא דנפשיה כשרה דאיהו סבר אין זיקה ולא אמרה למילתיה אלא אליבא דשמואל דסבר יש זיקה וכיון דלשמואל שרי ניחא וכתב הרא\"ש רב אלפס לא הביא שינוייא קמא מאי אחד חולץ לכולן אאמצעית משום דחשיב לשינוייא בתרא עיקר ופטרה נפשה בחליצה גרועה ואינה צריכה לחלוץ משניהם ונראה דשינוייא קמא עיקר כי הוא אליבא דרב אשי כמו שהקשה ר\"י וכו' הילכך האי שינוייא עיקר ודוקא אמצעית חולצת מאחד אבל שתים הראשונות אי נפול בבת אחת זה חולץ לאחת וזה חולץ לאחת עכ\"ל ובתר הכי אהא דאמר שמואל חלץ לאחיות לא נפטרו צרות כו' וכתב הרי\"ף עלה פסקו רבוותא הלכתא כשמואל כתב הרא\"ש וז\"ל כתב הראב\"ד ז\"ל האי פיסקא כשמואל לא הוה צריכא אהא מילתא דהא ליכא פלוגתא עילויה אלא אפלוגתא דלעיל קאי דפליג בהדי רב בחליצה פסולה דא\"ר צריכה לחזר על כל האחין ופסקו כוותיה דשמואל מיהו ה\"מ גבי אמצעית אבל בתרתי קמייתא כיון דאיכא ב' יבמין זה חולץ לאחת וזה חולץ לאחת דכל מאי דאיפשר לאהדורי בתר חליצה כשרה מהדרינן ואפי' למפטר נפשה ואם עבר וחלץ נמי חד לכולהו מאי דעבד עבד ושריין לעלמא עכ\"ל הראב\"ד ז\"ל והרמב\"ן ז\"ל כתב דלדברי רב אלפס הלכה כרב דחליצה פסולה צריכה לחזר על כל האחין דהכי קיימא לן הלכתא כרב באיסורי והוצרכו לפסוק במימרא בתרייתא דשמואל במאי דאמר חלץ לצרות נפטרו אחיות דלא תימא כל חליצה פסולה צריכה לחזר ואלו שתיהן חלוצות פסולות נינהו קמ\"ל דכי אמרינן חליצה פסולה מחזרת ה\"מ כששתי החליצות שוות אז צריכות לחזר על כל האחין וכ\"ש על כל שאר הצרות אבל אם אחת מהן מעולה מחבירתה אע\"פ שהיא נמי פסולה כגון חליצות צרות במקום אחיות המעולה שבהם פוטרת והגרועה אינה פוטרת וזה דבר צריך ונכון הוא וכ\"פ הרמ\"ה ז\"ל דחליצה פסולה צריכה לחזר ויראה מתוך דברי התוס' דאין הלכה כרב כי הקשו אהא דאמר רבי יוחנן לקמן מתה שנייה מותר בראשונה כו' ותירצו משום דרב ס\"ל חליצה פסולה צריכה לחזר על כל האחין כו' ומה שלא דקדק התלמוד דלרבי יוחנן לישני הכי משום דמוכחא מילתא דסבר ר\"י אין צריכה לחזר והאי שינוייא דסמכא הוא כי א\"א לתרץ קושיא זו בע\"א וכיון דר\"י סבר כשמואל הלכתא כשמואל עכ\"ל: ואיכא למידק היאך כתב רבינו שהראב\"ד פסק כשמואל וכשינוייא בתרא ושלזה הסכים הרא\"ש שהרי נתבאר בדברי הרא\"ש שהוא סובר דשינוייא קמא עיקר ואיפשר לומר דלא כתב ולזה הסכים הרא\"ש אלא לענין דהלכה כשמואל ולאפוקי מהרמ\"ה והרמב\"ן ז\"ל שפסקו כרב אבל לענין לישנא קמא ולישנא בתרא לא אמר אבל מ\"מ קשה היאך כתב שהראב\"ד פסק כשינוייא בתרא דאפילו לפטור נפשה א\"א בחליצה כשרה לא תחלוץ גרועה דהא ללישנא קמא הוא דמשמע הכי וכמו שכתב בו רבינו דכל דמצי למחלץ חליצה כשרה לא תחלוץ חליצה גרועה דאילו ללישנא בתרא הרי כתב דלפטר נפשה פטרה בחליצה גרועה לכן נ\"ל שט\"ס יש כאן וצריך להגיה וכשינוייא קמא במקום שינוייא בתרא והשתא אתי שפיר ומ\"ש ולזה הסכים הרא\"ש על ומ\"ש וכשינוייא קמא:","ומ\"ש רבינו בשם הרמב\"ם ז\"ל בקצת ספרים יש חסרון הניכר וט\"ס הוא והילך לשון הרמב\"ם ז\"ל יבמות רבות הבאות מבית אחד כיון שנבעלה אחת מהן בעילה ראויה או שנחלצה חליצה מעולה הותרה הכל ונסתלקה זיקת היבם מעליהן ואם נבעלה אחת מהן בעילה פסולה או נתן לה מאמר פסול נאסרו כולן ליבם וצריכה זו שנבעלה או שנתן לה מאמר גט וצריכה אחת מהן חליצה להתירן לזרים שאין זיקת היבום מסתלקת בבעילה פחותה נחלצה אחת מהן חליצה פחותה הותרה להנשא לזר אותה שנחלצה אבל צרתה אסורה עד שתחלוץ גם היא או עד שיחלצו כל האחין לראשונה שנחלצה החליצה הפחותה שאין חליצה פחותה מסלקת זיקת יבום מבית זה עד שתחזור על כל האחין או עד שתחלוץ כל אחת מהן עכ\"ל: וכתב ה\"ה כיון שנבעלה א' מהן וכו' עיקר הנוסחא בדברי רבינו בכאן צריכה חליצה כל אחת מהן להתירן לזר שהוא סובר שחליצת אחת מהן אינה פוטרת צרתה וכמו שביאר בסמוך במ\"ש נחלצה אחת מהן חליצה פחותה כו' ודעתו בזה צל\"ע שהוא ז\"ל סבור שאם נתן האחד מאמר לאחת או נתן לה גט ואח\"כ בא עליה אחיו ואחד מהן חלץ לאחרת שלא נעשה בה מעשה שאין חליצתה של זו פוטרת זיקת היבום של שנייה וצריכה השנייה גט וחליצה והטעם לפי שזו חליצה פסולה ואינה פוטרת חבירתה ואע\"פ שיותר היא פסולה זו שנעשה בה מעשים אלו מ\"מ אין חליצתה של שנייה אע\"פ שמעולה פוטרתה ונמצא שהוא ז\"ל פוסק דלא כשמואל דאמר חלץ לבעלת הגט לא נפטרה צרתה לצרה נפטרה בעלת הגט חלץ לבעלת מאמר לא נפטרה צרתה לצרה נפטרה בעלת המאמר והוא ז\"ל סבור שאין חליצת אחת מהן פוטרת צרתה וסבור דלפטור עצמה פוטרת וכן הוא ז\"ל סבור שאם נחלצה האחת מהן מכל האחין נפטרה הצרה ואיני יודע מהיכן יצא לו זה ואיני יכול להלום הסוגיות לפי שיטתו וכבר נחלקו עליו הרמב\"ן והרשב\"א ז\"ל בדין זה ודעת הרשב\"א שכל שהן שוות כגון שיש לפניהם מאמר או גיטין שחליצת אחת מהן פוטרת צרתה ואם הא' בעלת גט או מאמר חליצת האחרות פוטרתה אבל חליצה של זו אינה פוטרת האחרות ואפילו חלצו לה כל האחין עכ\"ל:","ומ\"ש רבינו יראה שפוסק כשמואל אע\"פ שלכאורה נראה שפוסק כרב דאמר חליצה פסולה צריכה לחזור על כל האחין שהרי כתב שאין חליצה פסולה מסלקת היבום עד שתחזור על כל האחין לא משמע לרבינו הכי משום דא\"כ אמאי כתב שאם נחלצה אחת מהן חליצה פחותה הותרה לזר הא לרב לא הותרה אפילו היא עד שיחלצו לה כל האחין אלא ודאי כשמואל ס\"ל ומה שאמר שאין חליצה פסולה מסלקת היבום עד שתחזור על כל האחין היינו דוקא למפטר צרתה אבל למפטר נפשה אינה צריכה לחזור וכדשמואל ועל מה שאמר רבינו וכשינוייא קמא דלפטור נפשה פטורה בחליצה גרועה יש לתמוה דהאי לשינוייא בתרא הוא דאילו לשינוייא קמא כל היכא דמצי למיחלץ חליצה כשירה לא תחלוץ חליצה גרועה נ\"ל דט\"ס יש כאן וצריך להגיה וכשינוייא בתרא במקום וכשינוייא קמא. והה\"ר דוד הכהן ז\"ל בתשובה בית ל\"ג כתב ע\"ז ופלפל מאד והאריך ליישב גירסת הספרים דגבי הרמב\"ם כתב כשינויא קמא וגבי הראב\"ד כתב כשינויא בתרא כתב הריב\"ש בתשובת סימן קצ\"ט שנשאל על מי שמת בלא בנים והניח ב' אחים וב' נשים והקטן שבהם עשה מאמר באחת מהן והשנייה הוציאה גט ואומרת שנתגרשה בו אך ניכרים הדברים שלא נתגרשה בו אם צריך לחלוץ לשתיהן או אם מספיק בחליצת אחת מהם והאריך שם בתשובה עיין עליו כתוב בת\"ה סימן רכ\"ה על יבמה שחלצה ואח\"כ נמצא שהיתה קטנה דאפי' למ\"ד חליצה פסולה צריכה לחזר על כל האחין הכא אינה צריכה לחזר וכיון שחלצה לאחד מהיבמים משתגדיל הותרה:","כתב הרמב\"ם ב' יבמים שייבמו ב\" יבמות הבאות מבית אחד ולא נודע מי ייבם תחלה שניהם יוציאו בגט כו' עד סוף הסימן הכל בפ\"ה: \u0005ב\"ה על מ\"ש הרמב\"ם שאם רצה אחד מהם לחלוץ קודם שידע מה עשה אחיו אין מונעים אותו יש לתמוה מ\"ש מהאשה שהלך בעלה וצרתה למ\"ה ואמרו לה מת בעלך לא תחלוץ דחיישינן שמא צרתה מעוברת ותלד ונמצא אתה מצריכה כרוז לכהונה: \u0006 ובתשובת הגאונים כתב שצריך ג\"כ לחלוץ לאחת מהן ואע\"ג דאין לאחר בעילה כלום ה\"מ היכא דאיתא בתחלה דלא הוה קמה מאמר באחרת והכא אילו הוה ידעינן דחדא מינייהו איבעלה קמי כל [דלא] איתעביד מאמר באידך בודאי הות ביאה פוטרת צרתה השתא דאיכא למימר דילמא ההיא דאיבעלה קמי צרתה הוה איתעביד מאמר בצרתה קמי דתבעיל וה\"ל ביאה בתר מאמר ולא ידעינן הי מינייהו היא צריכה ב' גיטין וחליצה כדפרישית דעבדינן לחומרא ולא תסתבר לך דכיון דבא האח נמי על השנייה ליכא חליצה אלא איפשר דתרוייהו ביאות פסולות חדא ביאה אחר מאמר וחדא ביאה אחר ביאה וכי הא ביאה יש אחריה כלום עכ\"ל:"],["\u0003אע\"פ שמן התורה וכו'\u0004 משנה ר\"פ ר\"ג ומפרש בגמרא מ\"ט אמור רבנן גט ביבמה מהני משום דמהני בעלמא דאי אמרת לא מהני אמרי גט להוציאה וחליצה להוציאה ומדגט לא מהני חליצה נמי לא מהניא ואתי למיבעל אחר חליצה וא\"ת היאך יטעו דחליצה לא מהניא הא בהדיא הצריך הכתוב חליצה וי\"ל דיאמרו דחליצה צריך מלבד הגט שהוא בכל הנשים דמדגט לחודא לא מהני חליצה לחודא נמי לא מהני ולא קשה השתא יאמרו מדחליצה לחודא מהני גט לחודא נמי מהני בהא לא טעו דבהדיא הצריך הכתוב חליצה כ\"כ התוס' (דף נ') בד\"ה מדגט: ומ\"ש פסלה ואת כל צרותיה כ\"כ הר\"ר משה בר מיימוני בפ\"ה והוא דעשאוהו לגט כמו חליצה ואם חלץ לאחת קמה היא וצרותיה בלא יבנה על כל האחין:","\u0003ומ\"ש שכל גט הפוסל באשתו לכהונה וכו'\u0004 כך כתב הרב רבינו משה בר מיימוני פ\"ה והוא בעיא דאיפשיטא לשם דאם לא כן אתי למימר דגט מעליא נמי לא פסיל וכן פסק הרא\"ש לשם:","\u0003וכן המאמר שתיקנו חכמים וכו'\u0004 כלומר כבר כתבתי בסימן קס\"ו שתיקנו מאמר ביבמה לקנותה וצרתה אסורה עליו וגם היא אסורה על שאר אחין מיהו אינו קונה קנין גמור וכו'","ומ\"ש אלא צריכה גט למאמרה פי' שיפרש שהגט הוא למאמרה אבל בסתם אינו גט אלא לזיקתה וצריך לחזור וליתן גט למאמרה כמ\"ש בסמוך. ודע דה\"ה דאינו קונה קנין גמור שתפטר במיתתו אלא עדיין היא זקוקה לשאר אחין וחולצת ולא מתייבמת כיון שיש עליה זיקת ב' יבמין כמ\"ש בסוף סימן קע\"ד ולא היה צריך לפרש זה כאן דפשיטא היא דגט ומיתה שוין:","\u0003וכיון שאין מאמר קונה ק\"ג וכו'\u0004 פסק כחכמים במשנה לשם דיש גט אחר גט ויש מאמר אחר מאמר דלא כר\"ג וכן פסקו כל הפוסקים:","ומ\"ש בין בב' יבמות וב' יבמין כ\"כ הרב רבינו משה בר מיימוני בפ\"ה ואף ע\"פ דלא תנן הכי בהדיא מ\"מ משמע דלפי הטעם אין לחלק:","\u0003כיצד יבם וכו'\u0004 כאן מפרש דין גט אחר גט:","\u0003ומ\"ש וכשבאים להוציאה למ\"ד חליצה וכו'\u0004 עיין בסוף הסימן כתב מחלוקת הפוסקים בדין זה וחליצה פסולה פירושו חליצה גרוע שאם רצה לייבם אינו יכול וה\"נ כשנתן לה גט קם עליה בלא יבנה וכיון דחליצה לאו מעלייתא היא לא מפקעא זיקה דתרוייהו בחליצה דחד משום דקי\"ל יש זיקה כלומר אלימא זיקה ורמי אתרוייהו:","\u0003ומ\"ש וכתב הרמב\"ן והה\"נ וכו'\u0004 נראה שרבינו למד כך ממ\"ש הרא\"ש בפ' ד' אחין בשם הרמב\"ן דהלכה כרב דחליצה פסולה צריך לחזור וכו' וה\"מ כששני החליצות שוות צריכות לחזור על כל האחין וכ\"ש על כל הצרות וכו' אלמא דה\"ה בב' יבמות צריך חיזור על כל הצרות ואף כ\"ש הוא:","\u0003ומ\"ש ומדברי רש\"י יראה וכו'\u0004 לא ידעתי מאין למד כך ואפשר דלמד כך מדקאמר בפרק ר\"ג (יבמות דף נ\"א) מדסבר ר\"ג אין זיקה רבנן סברי יש זיקה לימא תיהוי תיובתא דרב דאמר חליצה פסולה צריכה לחזור על כל האחין ופירש\"י דפריך מסיפא דקתני וכן אתה אומר בב' יבמיי ויבמה אחת אלמא דסבירא ליה לרש\"י דמיבם אחד וב' יבמות לא קשיא דאף רב מודה דנפטרה אחת בחליצת חבירתה אכן בספרים שלנו איתא בגמרא בהדיא וקתני סיפא וכו' וכיון דגמרא קאמרה הכי בהדיא כתב רש\"י דפריך מסיפא ואין ראיה מכאן לסברת רש\"י בעצמו אלא דלפי שכך הוא גירסתו ודאי דכך הוא סברתו ואף לגירסא זו אין סתירה לדברי הרמב\"ן די\"ל דאה\"נ דקשיא מרישא ג\"כ אלא דניחא ליה לאקשויי מב' יבמין גופא דאיירי בה רב ואיכא למידק דבס\"פ ר\"ג (יבמות דף נג) משמע להדיא דרש\"י סובר דכ\"ש הוא בב' יבמות דקאמרי' התם אמאי דתנן גט לזו וגט לזו צריכות הימנו חליצה לימא מסייע ליה לרב דאמר חליצה פסולה צריכה לחזור וכו' ופירש\"י דצריכות משמע שתיהם צריכות חליצה וקתני סיפא וכן ב' יבמין וכו' אלמא דס\"ל לרש\"י דאי לאו מדקתני סיפא ליכא סייעתא דאיכא למימר דוקא ב' יבמות ולא בב' יבמין וכ\"פ התוס' (בדף נב) בד\"ה בן עזאי והיינו כדברי הרמב\"ן דאמר דכ\"ש הוא וצ\"ע מיהו הרב רבינו משה בר מיימוני תופס שיטה אחרת דלמיפטר נפשה בחליצה פסולה פטרה ואינה צריכה חיזור אבל למיפטר צרתה אפי' הן שוות כמו גט אחר גט דהכא אינה פוטרת אא\"כ חוזרת על כל האחין ואז נפטרת גם צרתה אפי' מעולה כמו שאבאר בס\"ד:","\u0003וכן יש מאמר אחר מאמר שאם עשה מאמר וכו'\u0004 אדלעיל קאי שאמר דגט אחר גט מהני בכולהו בין ביבם א' וב' יבמות וכו' וכן יש מאמר אחר מאמר בכולהו ומפרש בגמרא דטעמא משום דמאמר מהני בעלמא ואי ביבמה לא מהני מאמר יאמרו מאמר לקנות וביאה לקנות ומדמאמר לא מהני ביאה נמי לא מהני ואתי למיבעל אחר ביאה ופירושו הכא כמו גבי גט שיאמרו ביאה לחודא לא מהני כי היכי דמאמר לחודא לא מהני אלא צריך מאמר בהדי ביאה אבל לא יאמרו ביאה כלל לא מהני דהא כתיב בתורה יבמה יבא עליה וכמו שפי' התוספות גבי גט כך צריך לפרש הכא גבי מאמר ופי' רש\"י הא דבב' יבמות ויבם אחד ומאמר אחר מאמר צריכות ב' גיטין ולא אמרינן דליבומי להו ה\"ט דהיכי ליעבד דאי ליבומי לתרוייהו ה\"ל ב' בתים ואי לחדא הואיל וחבירתה בה אגידא ה\"ל ב' בתים בונה עכ\"ל כלומר כיון דעשה בה מאמר ה\"ל כאשתו וחבירתה אסורה עליו כדלעיל ומזה הטעם אף בב' יבמין אי אפשר ליבומי שום אחת מהן וק\"ל וכתבו התוס' בפ' ד' אחין (יבמות דף לב) בד\"ה נתן גט הקשה הריב\"ן יתן גט למאמרו ולא לזיקתו וליבמי אידך ותירץ דלכתחלה אין לעשות כן דגוזרים גט למאמרו אטו גט לזיקתו ודוקא בדיעבד קאמר דהותרה אפי' היא וכו':","ומ\"ש וחליצה לאחת מהן לפטור שתיהן סתם דבריו כדעת הרא\"ש דבכל חליצה פסולה אין צריך לחזור וכו':","וכן אם עשה מאמר בזו ואחר כך נתן גט או חלץ לה או לצרתה או שבא על צרתה וכו' כן צריך להיות אבל בא הוא עליה אין כאן גריעותא אלא כך הוא תקנת חכמים שיעשה מאמר ביבמה קודם שיבא עליה כדלעיל בסי' קס\"ו וכדתנן ר\"פ ר\"ג עשה מאמר ובעל הרי זו כמצותה ובמקצת ספרים כתוב כאן או שבא עליה או על צרתה והוא ט\"ס בהכרח ובכאן מפרש דין גט וחליצה שאחר מאמר ביבם א' ויבמה אחת ודין גט וחליצה וביאה ביבם א' וב' יבמות: ומ\"ש או שאחר המאמר שלו נתן לה אחיו וכו' חזר לפרש דין זה בב' יבמין ויבמה א' או ב' יבמין וב' יבמות:","\u0003עשה מאמר בזו ובעל הוא או אחיו צרתה צריכות ב' גיטין וחליצה לאחת מהן:\u0004 ","עשה מאמר בזו וחלץ הוא או אחיו לזו בעלת המאמר צריכה גט כך הוא הנוסחא האמיתית בספרי רבינו והוא משנה פ' ר\"ג וב\"י תמה על רבינו לפי נוסחא מוטעת שהיתה בספרו כמפורש בדבריו ואיתא בגמרא דאע\"ג דמדאורייתא קונה ביאה בזו אחר מאמר בזו צריכה חליצה לפי שהמאמר שנעשה בתחלה עושה לביאה שאחריה בצרתה ביאה פסולה והא דלא תסגי לבעלת ביאה בגט בלא חליצה ותיפטר אף חבירתה בביאתה מן החליצה ה\"ט דאי ביאה אחר הגט הוא גזירה משום ביאה אחר חליצה דאתי למימר מדקניא ביאה אחר הגט לגמרי אלמא מעליותא הוא ואתי למיבעל לכתחלה אחר חליצה ואי ביאה אחר מאמר הוא גזירה משום ביאה אחר ביאה פי' דאתי למימר מדקני ביאה של זו אחר מאמר של זו וסגי לה בגט לחוד אלמא מעליותא היא ואתי למיעבד ביאה אחר ביאה וקא פגע באיסור אשת אח: וכן אם נתן לה גט ואח\"כ בא עליה וכו' בכאן מפרש דין מאמר וביאה אחר הגט ביבם א' ויבמה אחת ודין מאמר וביאה וחליצ' אחר הגט ביבם אחד וב' יבמות אבל חליצה אחר הגט ביבם אחד ויבמה אחת אין אחר חליצה כלום דפקעה זיקה לגמרי ואי הדר עביד בה גט או מאמר לא מהני ואע\"פ דבחלץ לחבירתה נמי אין אחר חליצה כלום כמבואר במשנה ריש פרק ר\"ג היינו דוקא לענין זה דאי הדר עביד מאמר או חליצה או גט לשלישית לא מהני לאסור בקרובות השלישי' כדמפרש בגמרא מאי ליגזור נגזר חליצה אחר הגט משום חליצה אחר חליצה דלא ליתו למיחלץ שני יבמות זו אחר זו או שני יבמין ליבמה אחת זה אחר זה כל כי הני תחלוץ ותיזיל כלומר מאי איכפת לן כל ימיה תחלוץ מ\"מ מהני מה שחלץ לחבירתה ליאסר בקרובותיה אבל ביבם א' ויבמה אחת דמיתסר בקרובותיה מחמת הגט שנתן לה מקודם שחלץ א\"כ החליצה אינו מועיל כלום לשום דבר:","\u0003ומ\"ש או שאחר הגט שלו וכו'\u0004 חזר לפרש דין זה בב' יבמין ויבמה אחת ובב' יבמין וב' יבמות:","\u0003ומ\"ש או חלץ לה או לחבירתה וכו'\u0004 כלומר שזה מועיל לאסור בקרובותיה בלחוד וכדפי' וז\"ש מועיל מה שנעשה אחר הגט כלומר החליצה מועיל לענין זה ליאסר בקרובותיה אבל אינו מועיל לגט ומאמר וחליצה שנעשה לשלישית דאין אחר החליצה כלום אלא שיהא אסור בקרובות חבירתה שחלץ לה ומועיל ג\"כ להצריך גט למאמר שעשה אחיו אחר הגט מלבד איסור הקרובות ומה שאמר למאמר שנעשה אחריו דה\"ה לביאה שנעשה אחריו.","ומ\"ש וזה תקנתא נתן לה גט ואח\"כ בא עליה או עשה בה מאמר צריכה גט וחליצה נראה דצריך להגיה נתן לה גט ואח\"כ בא עליה הוא או אחיו או עשו בה מאמר וכו' דלמה לא יזכיר ביאת אחיו או מאמרו בדידה כמו בצרתה והא דצריכה חליצה אחר ביאה זהו מפני הגט שלפניו שעושה הביאה שאחריה ביאה פסולה וביאר פסולה גזרו בה רבנן כדפי':","\u0003הבעילה קונה קנין גמור וכן חליצה וכו'\u0004 פי' ביאה כשרה וחליצה כשרה שוין הן דאין אחריהם כלום כמו שמפרש והולך אבל בפסולין אף ע\"ג דמדאורייתא שוין הן מ\"מ רבנן חלקו ביניהן דביאה פסולה יש אחריה כלום אבל חליצה פסולה אין אחריה כלום כמו שנתבאר לעיל ויתבאר עוד בסמוך:","\u0003כיצד בא על יבמתו וכו'\u0004 בכאן מפרש דין חליצה אחר ביאה בכולהו בין ביבם א' וכו' אבל כשכתב וכן אם אחיו חזר ונתן לה גט וכו' לא כלל בתוכו גם דין יבם א' ויבמה א' דהא פשיטא דהיבם פוטר את יבמתו בגט לאחר שייבמה כדלעיל ריש סי' קס\"ח אך קשה למה לא כלל בכלל זה ג\"כ אם חזר הוא ונתן גט לצרתה דאינו כלום:","\u0003וכן אם חזר וכו'\u0004 הכא לא שייך לכלול אם הוא חזר ועשה בה מאמר או בעל דהא אשתו היא ופשיטא דאינו כלום דהא אסור בקרובותיה מביאה ראשונה:","אבל אם בא הוא או אחיו על צרתה או עשו בה מאמר צריכה גט פלוגתא דרב אחא ורבינא בבא על יבמתה וחזר הוא או אחיו על צרתה אם היא בכרת והלכה כדברי המיקל דאינו אלא בעשה דבית אחד הוא בונה ואינו בונה ב' בתים ולאו הבא מכלל עשה אינו אלא עשה וקי\"ל דקידושין תופסין בחייבי לאוין ועשה דלא כר\"ע ולפיכך אם בא עליה או קדשה סתם תופסין הקידושין מדאורייתא ואם עשה בה מאמר יבמין תופסין מדרבנן: וכן אם חלץ ליבמתו וחזר הוא או אחיו וחלצו וכו' כאן כתב דין חליצה ואחר חליצה בכולהו מלבד ליבם א' ויבמה א' דלא שייך דאי לאסור בקרובות כבר אסורין מחליצה הראשונה:","\u0003אבל אם אחר שחלץ ליבמתו בעל או קדש וכו'\u0004 פירוש משום דקידושין תופסין בחייבי לאוין ועשה כמ\"ש בסמוך בדין ביאה או מאמר שאחר ביאה וכאן מפרש דין ביאה או מאמר שאחר החליצה דפליגי בה ר' יוחנן וריש לקיש בפ\"ק אם החליצה היא בכרת ופסקו הרי\"ף והרא\"ש כר' יוחנן דאינה בכרת ואיכא לתמוה כיון דרבינו כותב כל החלוקות שנשנו במשנה אמאי לא כתב נמי דאין גט מועיל אחר חליצה שאם אחיו נתן לה גט או אחיו נתנו גט לצרתה אינו כלום ומותר בקרובותיה ומבואר הוא במשנה ריש פרק רבן גמליאל:","\u0003ומ\"ש בין שקדשה לשם אישות וכו'\u0004 פסק כחכמים בברייתא פרק ר\"ג דלא כרב ומפרש רבינו דבקדשה סתם הוי לשם אישות וה\"ל קידושי דאורייתא ולשם יבמות היינו במפרש הרי את מקודשת לי לזיקת יבמין ואף ע\"פ דלאחר שחלץ לה פקעה זיקה מ\"מ רבנן תקינו לה קידושין ה\"א באשיר\"י גם דברי הראב\"ד והרמב\"ן והרי\"ף לשם מבוארים:","\u0003עשה מאמר ביבמתו וכו'\u0004 פסק כלישנא בתרא דרבה פ' ד' אחין (יבמות דף לב) וכמ\"ש הרא\"ש לשם ובפרק ר\"ג ופירש\"י והרא\"ש דוקא שפירש למאמרו ולא לזיקתו אבל סתמא הוי לזיקתו וכ\"כ לקמן בסי' קע\"ד וכאן סתם דבריו:","\u0003ביאת בן תשע וכו'\u0004 משנה וברייתא וגמרא ס\"פ האשה רבה וע\"פ דברי הרא\"ש לשם ומביאו ב\"י אלא דהקשה ב\"י אמ\"ש רבינו ואם אחר שבא עליה חזר אחיו הגדול ובא על צרתה או שנתן לה גט או חלץ לה או לצרתה פסלה על הקטן אמאי לא כתב חזר אחיו הגדול ובא עליה או על צרתה ואפשר דממילא משמע דכיון דאפי' בא על צרתה פסלה על הקטן כ\"ש אם בא עליה בעצמה עכ\"ל ואע\"ג דבהדיא תנן כיצד בן ט' ויום א' שבא על יבמתו פסל ע\"י אחין באו עליה אחין עשו בה מאמר נתנו גט או חלצו פוסלין ע\"י וא\"כ לא ה\"ל להשמיטו כיון דתני ליה תנא בהדיא גם הרמב\"ם בפ\"ה לא השמיטו יש לתרץ דמ\"מ כיון דמסקינן חסורי מחסרא וכו' אם כן לא איירי תנא בביאת אחיו אחר ביאת בן ט' ותו דאף מקמי דידעינן חסורי מחסרא שפיר קתני מתני' ביאת אחיו אחר ביאת בן ט' כיון דלא תני בהדה ביאת אחיו על צרתה אבל רבינו דכתב כאן דין בא אח\"כ אחיו הגדול על צרתה דפסלה על הקטן תו לא צריך לכתוב בא אחיו הגדול עליה דשמעינן לה במכ\"ש כדפי' ב\"י מיהו אכתי קשה למה השמיט שאם עשה בה אחיו הגדול מאמר פסל' על הקטן כדתנן בהדיא וגם הרמב\"ם בפ\"ה השמיט זה ויש לתמוה עליהם עכ\"ל ב\"י:","\u0003גדול שעשה מאמר וכו'\u0004 פשוט ר\"פ ד' אחין. וכתב הרמב\"ם וכן אם נפלו לפניו איסור לאו וכו' בפ\"ז כתב כן וכתב ה\"ה דאיכא לתמוה דבפרק שני דיבמות (דף כ) איתא ברייתא איסור מצוה ואיסור קדושה בא עליה או חלץ לה נפטרה צרתה דאין לפרש דצרתה כיוצא בה קאמר דהא בפ\"ה מיבום כתב להדיא דחליצה פסולה אינה פוטרת אפילו לכיוצא בה ע\"כ ולפעד\"נ דל\"ק כלל דברייתא נפטרה צרתה דבר תורה קאמר דמדאורייתא ליבום נמי רמיא דלא תימא חייבי לאוין לחליצה רמיא ליבום לא רמיא דהא כתיב יבמתו כדקס\"ד התם מעיקרא קמ\"ל דלא אלא ביאה וחליצה שוין בה ויבמתו נפקא לן לאלמנה לכ\"ג מן הנישואין דאיכא עשה ול\"ת דלחליצה רמיא ולביאה לא רמיא אבל ח\"ל גרידא לביאה נמי רמיא ונפטרה צרתה זהו דבר תורה אבל ודאי דרבנן עבוד תקנתא דכל חליצה פסולה דלא חזיא ליבום צריכה לחזר על כל האחין או אינה פוטרת צרתה לדעת הרמב\"ם והלכך באיסור לאו ועשה ג\"כ דלא חזיא ליבום מטעם גזירה ביאה ראשונה אטו ביאה שנייה אינה פוטרת צרתה דהויא לה חליצה פחותה ופסולה כיון דלא חזיא ליבום אלא דברייתא לא מיירי בהכי מיהו אם עבר ובא עליה קנאה ונפטרה צרתה לגמרי ואף מדרבנן נפטרה דכיון דכבר ייבמה ומדאורייתא חזיא ליבום אע\"ג דעבר אדרבנן לכתחלה ס\"ס נפטרת ואינו דומה לביאה פסולה דגזרו בה וצריכה חליצה אחריה דהתם שייך גזירה ביאה אחר מאמר אטו ביאה אחר ביאה אבל הכא ביאה גרידא היא וליכא למיגזר זאת היא דעת הרמב\"ם ובריש סימן קע\"ד יתבאר עוד בס\"ד:","\u0003שלש אחיות וכו'\u0004 ר\"פ ד' אחין ומ\"ש אם נפלו כאחת וכולי פי' אם נפלו כאחת דאינן ראויין ליבום דכל אחת ה\"ל אחות זקוקתו דאלימא מצות זיקת יבמין על כל אחד מהאחין כאילו היא אשתו וכי מייבם אחותה כאילו נסיב אחות אשתו א\"כ ה\"ל חליצה פסולה כיון דאי בעי לייבם לא מצי לייבומי וחליצה גריעא צריכה לחזור על כל האחין דלא מפקעא זיקתה דשאר אחין לחליצה דחד משום דאלימא זיקה ורמי אכולהו אבל בנפלו זה אחר זה ראובן שחלץ תחלה חליצה כשרה היא שאם רצה יכול לייבם נפלה אידך חלץ לה שמעון וגם זו כשרה שאם רצה מייבם נפלה שלישית והיא אחות חלוצה של שניהם וכיון שאין אחד מהם יכול לייבמה ה\"ל חליצה פסולה וצריכה לחלוץ משניהם ושמואל סבר אין חליצה פסולה צריכה לחזור אלא אחד חולץ לכולן מיהו ללישנא קמא מודה שמואל בנפלה בזה אחר זה וחלץ ראובן חליצה כשרה לראשונה יחלוץ שמעון לשנייה שנפלה אחר כך חליצה כשרה ולא יחלוץ ראובן לשנייה חליצה פסולה וכשנפלה שלישית יחלוץ אחד מהם חליצה פסולה דהא לשניהם לא חזיא ליבום כיון דהיא אחות חלוצתו וא\"צ לחזור ולאידך שינוייא אחד חולץ לכולן אפי' בתחלה דלא מיבעיא היכא דכבר חלץ לכולן דפטרה נפשה בדיעבד אלא אפילו לכתחלה יכול ראובן לחלוץ לשלשתן אע\"פ שנפלו בזה אחר זה דלמיפטר נפשה פטרה לכתחלה אפי' בחליצה פסולה וז\"ל רש\"י אבל נפשה פטרה בחליצה כל דהו הלכך אחד חולץ לשלשה היכא דליכא צרות בהדייהו עכ\"ל ור\"ל אפי' בנפלו בזה אחר זה כדפי' אבל הרא\"ש כתב ללישנא קמא דדוקא אמצעית חולצת מאחד אבל ב' הראשונות אי נפול בבת אחת זה חולץ לאחת וזה חולץ לאחת עכ\"ל וכך מביאו ב\"י והוא תמוה ואין ספק דט\"ס הוא וצ\"ל אי לא נפול בבת אחת וכו':","\u0003והרמב\"ם כתב יבמות רבות וכו'\u0004 בפ\"ה כתב כן וה\"ה לשם הבין מדבריו דאם אחת מהיבמה נחלצה חליצה פסולה כגון שחלץ לבעלת המאמר או לבעלת הגט לא נפטרה צרתה וכן בחלץ לצרתה לא נפטרה בעלת הגט ובעלת המאמר ובנתן האחד מאמר לאחת או נתן לה גט ואחר כך בא עליה אחיו ואחד מהן חלץ לאחרת לא נפטרו עד שיחלצו לכולם ותמה עליו מן הסוגיא ע\"ש ומלבד תמיהתו איכא תימה דא\"כ הוא דוחה הך דשמואל דאמר חלץ לבעלת הגט לא נפטרה צרתה לצרה נפטרה בעלת הגט ובפ\"ז פסק בהדיא כשמואל דחלץ לצרות נפטרו אחיות ומ\"ש הא מהא אלא נראה עיקר דהרב פוסק כשמואל בכל דבריו ומ\"ש בפ\"ה דצריכה אחת חליצה להתירה לזרים היינו דוקא באותה שלא נעשה בה מעשה וכדשמואל דחלץ לצרה נפטרה בעלת הגט ומ\"ש נחלצה אחת מהן חליצה פחותה הותרה היא וכו' היינו נמי כשמואל דאמר חלץ לבעלת הגט לא נפטרה צרתה ומשמע אבל היא גופה נפטרה וכשינויא בתרא דלמיפטר נפשה פטרה ולפ\"ז בעל כרחך הא דאמר שמואל חליצה מעליא בעינן וממילא דמודה שמואל דחליצה פסולה צריכה לחזור על כל האחין וכדמשמע בסוגיא דלשינויא בתרא כי היכי דלמיפטר צרתה לא פטרה כיון שאין החליצה מעולה ובעינן לחלוץ לכל אחת ה\"ה דבעיא לחזור על כל האחין כיון שאין החליצה מעולה כל זה אינו אלא משום צרתה דלא נפטרה צרתה אלא א\"כ בחוזרת על כולם אבל היא נפשה נפטרת מיד ומ\"ש הרמב\"ם עוד אבל צרתה אסורה עד שתחלוץ גם היא היינו לומר דבחלץ מתחילה לבעלת הגט שוב לא נפטרה צרתה עד שתחלוץ גם היא אבל אם חלץ בתחלה לצרתה בודאי דנפטרת בעלת הגט לגמרי כדשמואל וכמו שפסק בפ\"ז וה\"ה הבין מדבריו אלה שר\"ל דלעולם אין חליצת א' מהן פוטרת צרתה מאחר שנעשה מעשה פיסול באחת מהן ומ\"ה הגיה בלשון הרמב\"ם צריכה חליצה כ\"א מהן להתירן וכו' ולא נהירא אלא כדפי' דדוקא בחלץ מתחלה לבעלת הגט הוא דלא נפטר צרתה עד שתחלוץ כל א' וא' וה\"ט דהחליצה פסולה אינה עוקרת הזיקה אלא במקצת ולא לגמרי הילכך כל א' וא' צריכה חליצה בפני עצמה משא\"כ בחלץ מתחלה לצרתה דעוקרת הזיקה לגמרי וזהו דעת רבי' שאמר ויראה מדבריו שפוסק כשמואל וכשינויא בתרא דלמיפטר נפשה פטרה בחליצה גרועה גם מ\"ש ה\"ה בפ\"ז דדעת הרמב\"ם דחליצה פסולה אינה פוטרת כיוצא בה עכ\"ל לכאורה איכא למימר דדוקא בחלץ לבעלת הגט הוא דס\"ל להרב דאינה פוטרת צרתה אבל כיוצא בה פוטרת אלא דמלשונו פ\"ה שכתב לפיכך גט אחר גט ביבמה וכו' וכן ב' יבמין שנתנו ב' גיטין ליבמה אחת זא\"ז ה\"ז כגרושה לשניהם ושניהם אסורים בקרובותיה וא' מהן חולץ וכו' מדכתב זר כאן ולא כתבו מקודם ביבם א' וב' יבמות וכן לאחריו בב' יבמין וב' יבמות יש ללמוד דדעתו דבב' יבמות צריכה חליצה לכל אחת דחליצה פסולה אינו פוטרת כיוצא בה אבל בב' יבמין ויבמה דחזרה על כל האחין אינו אלא משום צרתה לדעתו כדפי' וזו שאין לה צרה די בחליצת אחד מהן וכו' ודו\"ק:","\u0003ומ\"ש יראה מדבריו שפוסק כשמואל וכשינוייא קמא וכו'\u0004 והראב\"ד פסק גם כן כשמואל וכשינוייא בתרא וכו' הקשה ב\"י הלא מדברי שניהם משמע דאיפכא ס\"ל ולכן כתב דט\"ס הוא וצריך להגיה בדברי הרמב\"ם וכשינוייא בתרא ובדברי הראב\"ד וכשינוייא קמא גם מהרש\"ל הגיה כך ומ\"מ קשה היאך אמר דהראב\"ד פסק כשינוייא קמא דהלא דבריו אינן לא כקמא ולא כבתרא דלקמא אם יכול לחלוץ חליצה כשירה וחלץ חליצה פסולה אפי' דיעבד לא הויא חליצה ולבתרא אפי' לכתחלה חולץ חליצה פסולה למיפטר נפשה ואילו הראב\"ד מחלק בין לכתחלה לדיעבד אבל ה\"ר ירוחם כתב וז\"ל נראה מדברי הראב\"ד שמפרש דלאותם שפסקו כשמואל פסקו כתרי תירוצי דשמואל כתירוץ הראשון דצריך לעשות לכתחלה ובדיעבד אם עשה כתירוץ השני דאחד חולץ לכולן מותר עכ\"ל ואפשר דכך הוא דעת רבינו ולפי דהרמב\"ם פסק כשינוייא בתרא אלמא דליפטר נפשה פוטרת בחליצה פסולה לכתחילה כתב עליה דהראב\"ד חושש נמי לשינוייא קמא אליבא דשמואל דלכתחלה צריך לחלוץ חליצה כשירה אבל בדיעבד מאי דעבד עבד ולזה הסכים א\"א הרא\"ש והא דכתב הרא\"ש מתחלה דשינוייא קמא עיקר סובר רבינו דהיינו דוקא להחמיר לכתחלה אבל בדיעבד שריא דאי אפי' בדיעבד לא נפטרה ה\"ל להרא\"ש לפרש ודלא כהראב\"ד מדכתב בסתם דברי הראב\"ד ואחר כך הביא דברי הרמב\"ן והשיג עליו משמע שתופס שיטת הראב\"ד בכל דבריו ותו דבגמרא הכי משמע דקאמר היכא דקיימא חליצה דשמעון חליצה כשירה חליץ לה ראובן חליצה פסולה כלומר בתמיה אלמא דעיקר תימה למה נקל לכתחלה לחלוץ חליצה פסולה כיון דאפשר בכשרה אבל דיעבד ודאי כשירה והא דקאמר מכדי שמעינן ליה לשמואל דאמר חליצה מעליא בעינן דאמר שמואל חלץ לאחיות לא נפטרו צרות הכא דקיימא חליצה דשמעון חליצה כשירה וכו' משמע דבעי למימר דאפי' דיעבד לא נפטר כי היכי דבחלץ לאחיות לא נפטרה צרה י\"ל שאני התם דחליצת צרה כשירה טפי דלא אלימא זיקה לשווייה צרה כערוה וכדרב אשי אבל הכא חליצת כולן שוה לגריעותא אינו בדין לפוסלה בדיעבד ואפ\"ה פריך מינה דמדחזינן דשמואל קפיד אחליצה מעליא דבדאיכא כשירה טפי בצרות מבאחיות אפי' דיעבד לא נפטרה א\"כ הכא דחליצת כולן שוה לגריעותא אין לנו להקל לכתחלה ומשני אאמצעיתא התם הוא דחולצת לכתחלה מאחד אבל ב' הראשונות אי נפלו בבת אחת זה חולץ לאחת וזה חולץ לאחת לכתחלה אבל בדיעבד מאי דעבד עבד כיון דחליצת כולם שוה לגריעותא וכן פי' הרא\"ש להדיא דלשינוייא קמא צ\"ל דס\"ל כרב אשי וכדפי' וא\"כ שפיר כתב רבינו דהראב\"ד פסק כשמואל וכשינוייא קמא ולכתחלה אסור אבל בדיעבד שפיר דמי ושלזה הסכים הרא\"ש אבל לשינוייא בתרא צ\"ל דס\"ל כאידך שינוייא דהתחיל ולא התחיל ואין חילוק בין צרה לערוה דחליצת כולם שוה לגריעותא ואפ\"ה אף דיעבד לא נפטרה צרתה ושמואל דאמר חולץ אפי' לכתחלה היינו למיפטר נפשה וכן עיקר ודלא כהר\"ר ירוחם בהא מילתא ודו\"ק:","\u0003כתב הרמב\"ם ב' יבמין וכו'\u0004 בפ\"ה כתב כך וכל זה פשוט אלא שהב\"י הביא תשובת הגאונים שהחמירו שצריך גם כן לחלוץ לאחת מהן ע\"ש ובכסף משנה כתב וז\"ל רצה א' לחלוץ קודם שידע מה עשה אחיו אין מונעין אותו יש לתמוה על זה מ\"ש מהאשה שהלך בעלה וצרתה למ\"ה ואמר לה מת בעליך דחיישינן שמא תהא צרתה מעוברת ותלד ונמצא אתה מצריך כרוז לכהונה עכ\"ל ורבינו כתב דין זה לעיל סוף סימן קנ\"ו ולפע\"ד יש ליישב דלא דמי דהתם ליכא אלא חדא ספיקא שמא תהא צרתה מעוברת ותלד אבל הכא איכא תרתי ספיקי חדא שמא אחיו בצור לא שמע כלל שמת אחיו בירושלים ואם תמצא לומר שמע מיתתו שמא לא עשה מעשה ביבמתו כלום הילכך אין מונעין את זה מלחלוץ בעכו מחששא שמא אתה מצריכה כרוז בדוכתא דאיכא ס\"ס:"]],["\u0010c0\u0011\u0010y0\u0011קטנה יתומה שהשיאוה אחיה קידושיה דרבנן כדפירשתי לעיל וכן חרשת קידושיה דרבנן מ\"מ אין קידושי שתיהן שוות אלא קידושי הקטנה הם בספק אם קונין קנין גמור או אם אין קונין כלל וקידושי החרשת קונין במקצתה ומשיירים במקצתה \u0010c1\u0011לפיכך מי שהיה נשוי יתומה וחרשת ומת ונפלו לפני אחיו ליבום אין ביאת אחת מהן פוטרת צרתה \u0010c2\u0011וכיצד תקנתן דחרשת לאו בת חליצה היא ואם ייבם אותה ויחלוץ לקטנה לכשתגדיל תאסר עליו החרשת בחליצה דאידך שאין ביאת החרשת ביאה גמורה להפקיע כל הזיקה ונשאר עדיין זיקה בקטנה וחליצתה חליצה וקאמר רב חסדא כונס החרשת ומוציאה בגט וחולץ לקטנה לכשתגדיל וכ\"פ הראב\"ד ורב אלפס פסק כר\"א שמלמדים הקטנה שתמאן וייבם החרשת ולזה הסכים א\"א הרא\"ש ז\"ל ואם יראה אחר כן לגרש החרשת הרשות בידו \u0010c3\u0011\u0010y1\u0011היו שתיהן חרשות או קטנות ביאת אחת מהן פוטרת צרתה אחת גדולה ואחת קטנה ביאת גדולה או חליצתה פוטרת הקטנה ואין ביאת הקטנה פוטרת הגדולה אחת פקחת ואחת חרשת ביאת הפקחת או חליצתה פוטרת החרשת ואין ביאת החרשת פוטרת הפקחת \u0010y2\u0011ואם שתיהן קטנות ובא יבם על אחת מהן וחזר ובא הוא או אחיו על השנייה לא פסל הראשונה עליו אבל אסור לא לקיים השנייה אלא מלמדין אותה שתמאן ויקיים הראשונה וכן אם שתיהן חרשות אין ביאת השנייה פוסלת את הראשונה והשנייה אסורה לו ויוציאנה בגט \u0010c4\u0011\u0010y3\u0011אחת קטנה ואחת חרשת בא על הקטנה וחזר ובא הוא או אחיו על החרשת לרש\"י פסל הקטנה עליו וכן פירש הראב\"ד ולפי זה יוציא שתיהן בגט והקטנה תמתין עד שתגדיל ותחלוץ \u0010c5\u0011אבל לגירסת רב אלפס לא פסל הקטנה עליו וכן הוא גירסת א\"א הרא\"ש ז\"ל וכן כתב הרמב\"ם ויוציא החרשת בגט \u0010c6\u0011\u0010y4\u0011בא על החרשת וחזר ובא הוא או אחיו על הקטנה כתב הרמב\"ם דפסל החרשת עליו ומלמדין את הקטנה שתמאן ויוציא החרשת בגט והשיג עליו \u0010y5\u0011הראב\"ד דכיון ששתיהן יוצאות למה מלמדין אותה שתמאן ויראה מדבריו שסובר שחרשת תצא בגט והקטנה תשאר אצלו ול\"נ אלא מלמדין הקטנה שתמאן ותשאר החרשת אצלו \u0010c7\u0011\u0010y6\u0011וכן יראה מדברי א\"א הרא\"ש ז\"ל \u0010y7\u0011אחת פקחת ואחת חרשת בא על הפקחת וחזר ובא הוא או אחיו על החרשת לא פסל הפקחת \u0010y8\u0011והחרשת תצא בגט בא על החרשת וחזר ובא הוא או אחיו על הפקחת פסל החרשת והחרשת תצא בגט והפקחת בגט וחליצה \u0010y9\u0011אחת גדולה ואחת קטנה ובא על הגדולה וחזר ובא הוא או אחיו על הקטנה לא פסל הגדולה ומלמדין הקטנה שתמאן בא על הקטנה וחזר ובא הוא או אחיו על הגדולה מלמדין הקטנה שתמאן ותעקור קידושין הראשונים ויקיים הגדולה:",["קטנה יתומה שהשיאוה קידושיה דרבנן כדפירשתי לעיל בסי' מ\"ג וכן חרשת קידושיה דרבנן מ\"מ אין קידושי שתיהן שוות אלא קידושי הקטנה הם בספק אם הם קונים קנין גמור או אם אין קונין כלל וקידושי החרשת קונין במקצתה ומשיירין במקצתה לפיכך מי שהיה נשוי יתומה וחרשת ומת ונפלו לפני אחיו ליבום אין ביאת אחת מהן פוטרת צרתה וכיצד תקנתן כו' בפרק ב\"ש (יבמות דף קי:) תנן קטנה וחרשת אין ביאת אחת מהן פוטרת צרתה ובגמרא כיצד תקנתן א\"ר חסדא א\"ר כונס החרשת ומוציאה בגט וקטנה תמתין עד שתגדיל ותחלוץ אמר רב תסדא ש\"מ קסבר רב חרשת קנויה ומשויירת קטנה קנויה ואינה קנויה דאי ס\"ד חרשת קנויה ואינה קנויה קטנה קנויה ומשויירת חרשת אמאי כונס ומוציאה בגט תיתיב גביה ממ\"נ אי קנויה היא הא קנויה היא ואי לא קנויה היא אמאי נכרית בעלמא היא. וכ\"ת קטנה אמאי תמתין תיתיב גביה אי קנויה היא הא קנויה היא אי לאו קנויה היא נוכריתא בעלמא היא א\"כ חרשת במאי תיפוק ופירש\"י כיצד תקנתן. דקטנה וחרשת הואיל ואין הא' פוטרת צרתה וחרשת לאו בת חליצה היא דניפוק תרוייהו בחליצה ואי מייבם לה וחליץ לקטנה כשתגדיל מיפסיל קמייתא דקם ליה בלא יבנה דהא ביאה דחרשת לא דחיא זיקה דנימא אין אחריה כלום: כונס את החרשת ומוציאה בגט. דחליצת קטנה פסל לה: חרשת קנויה במקצת ומשויירת קטנה. ספק קנויה כולה ספק אינה קנויה דבשתיהן קנוייות ומשויירת ליכא למימר דממתני' שמעינן לה דא\"כ תפטר חדא בביאת חבירתה ושתיהן ספק נמי ליכא למימר מדקתני סיפא דמתני' בא היבם על הקטנה וחזר ובא על החרשת פסל את הקטנה בא יבם על החרשת וחזר ובא על הקטנה פסל את החרשת ואם שתיהן ספק קמייתא תיתיב גביה ממ\"נ דהא אחרונה לא פסלה לבא עליה דאם שתיהן קנויות אין האחרונה פוסלת הראשונה דאין אחר ביאה כלום ואם זו קנויה וזו אינה קנוייה אינן צרות זו לזו אלא חדא קנויה ומשויירת וחדא ספק ומדרב שמעינן דחרשת היא הקנויה והמשויירת וקטנה ספק מ\"ה תצא החרשת בגט דילמא קטנה קנויה היא לגמרי ועדיפא מחרשת ופסלה תליצה עליה: הא קנויה היא. ותו ליכא זיקא אבתרייתא: נכרית בעלמא היא. ולא פסלה לה חליצת קטנה וכי תימא אמאי תמתין ותחלוץ ישאנה מתחלה ותשב אצלו ממ\"נ: חרשת במאי תיפוק. הא לאו בת חליצה היא ורב תקנתא לתרוייהו קתני ואי קשיא מתני' דקתני בא על הקטנה וחזר ובא על החרשת פסל קטנה אמאי פסל הואיל ונסבה ברישא תיפוק חרשת בגט וקטנה תיתיב גביה ממ\"נ כדאמרן ואיכא תקנתא לתרוייהו תריץ משום גזירה דילמא אתי למיבעל חרשת ברישא תחלה וה\"נ מתרץ לה בברייתא לקמן עכ\"ל. ורב אלפס כתב על הא דא\"ר חסדא אמר רב ולר\"א מלמדין את הקטנה שתמאן בו ומייבם לחרשת וכן הלכה עכ\"ל. כלומר דר\"א אמר התם במתני' הכי וכתב הרא\"ש על פסק הרי\"ף כתב הראב\"ד ז\"ל זו אינה מחוורת דלא אר\"א מלמדין את הקטנה למאן אלא כדי לקיים בחבירתה מצות יבום דאורייתא אבל הכא יבום דחרשת דרבנן הא והא קיים לה בביאה ראשונה הלכך אין מלמדין אותה למאן מטעמא דאמרינן לעיל ובנוסחא דילן ל\"ג בדברי ר\"א בכולן מלמדין את הקטנה למאן ור\"א אבתרייתא לחוד קאי דאיכא גדולה וקטנה בהדדי וסוגיא דשמעתין (קיא:) נמי הכי משמע דקאמרת ואי אשמעינן בהא משום דגדולה רמיא קמיה מעיקרא וכו' ע\"כ והרמב\"ן ז\"ל כתב למה לא תמאן הא טעמיה דבר קפרא משום דילמא גדלה ומיחרטא בה וזו יוצאת עכ\"פ למה תתעגן עד שתגדיל ותחלוץ ותפסל מן הכהונה שופך מי בורו ואחרים צריכים לו ותאסר חרשת על בעלה שכנסה בהיתר וע\"כ לא הוצרכו לומר בגמרא ואי אשמעינן אלא בסיפא דמתני' דבא על הקטנה וחזר ובא על הגדולה דאיקיים מצות יבום והוא פוסלן על עצמו בפשיעה לפיכך היה ראוי שלא לחזור ולהתירו לו כלום וכן ברישא משום דגדולה לא רמיא קמיה דמעיקרא כאחות אשה דמיא ומוטב שתצא משתתייבם אבל הכא שאין תקנה אלא להוציא שתיהן למה לא ילמדוה למאן לתקנתה ולתקנת חבירתה וכ\"ש שנמצא בנוסחאות בכולן מלמדין את הקטנה והכי איתא בתוספתא ונראין דבריו עכ\"ל. וכ\"פ הרמב\"ם ז\"ל בפ\"ה מלמדין את הקטנה שתמאן וכונס את החרשת ואם רצה לגרשה כותב לה גט אחר שיבוא עליה ותותר לזה וכתב ה\"ה בהשגות א\"א זה המחבר גמר ועשה מדעת עצמו כי בגמרא אמרו תמתין עד שתגדיל ותחלוץ ולא התירו למאן ביבם ולא אפילו בעל אלא כדי לקיים מצות יבום של תורה ע\"כ סובר הרב ז\"ל שלא אר\"א שם בכולן מלמדין את הקטנה שתמאן בו אלא באחת גדולה ואחת קטנה שיבום הגדולה מן התורה ועל זה נפסקה ההלכה כמותו אבל כאן ששניהם מדבריהן לא אמרו בקטנה שתמאן ודעת רבינו כדעת ההלכות דרב דאמר כונס את החרשת לא אמרה אליבא דר\"א דלר\"א בכל גווני מלמדין את הקטנה והדבר צריך לי הכרע עכ\"ל ואני אומר שכבר כתבתי שהרמב\"ן ז\"ל הכריע כדברי הרי\"ף וכיון שהרי\"ף והרמב\"ם ז\"ל והרא\"ש והרמב\"ן ז\"ל הסכימו שמלמדין את הקטנה שתמאן וייבם לחרשת הכי נקטינן ואין לפקפק בדבר:","היו שתיהן חרשות או קטנות ביאת אחת מהן פוטרת צרתה אחת גדולה ואחת קטנה ביאת גדולה או חליצתה פוטרת הקטנה ואין ביאת הקטנה פוטרת את הגדולה אחת פקחת ואחת חרשת ביאת הפקחת או חליצתה פוטרת את החרשת ואין ביאת החרשת פוטרת הפקחת משנה בפ' ב\"ש (שם):","ואם שתיהן קטנות ובא יבם על אחת מהן וחזר ובא הוא או אחיו על השנייה לא פסל הראשונה עליו אבל אסור לו לקיים את השנייה אלא מלמדים אותה שתמאן ויקיים הראשונה וכן אם שתיהם חרשות אין ביאת השנייה פוסל את הראשונה והשנייה אסורה לו ויוציאנה בגט ג\"ז משנה שם (דף קיא) מי שהיה נשוי שתי יתומות קטנות ומת בא היבם על הראשונה וחזר ובא על השנייה או שבא אחיו על השנייה לא פסל את הראשונה וכן ב' חרשות ופירש\"י לא פסל את הראשונה. שהרי ביאתם שוה ואי ראשונה קנויה היא הרי היא אשתו ואחרונה ביאת זנות ואי לאו קנויה היא הרי שתיהן נכריות אצלו שלא היתה קנויה לאחיו: ומקיים את הראשונה. שלא נפסלה עליו אבל אחרונה לא דילמא קנויות הוי ומשבא על הראשונה קמה הך עליה באיסור שתי בתים:","אחת קטנה ואחת חרשת בא על הקטנה וחזר ובא הוא או אחיו על החרשת לרש\"י פסל הקטנה עליו וכן פי' הראב\"ד ולפי זה מוציא שתיהן בגט והקטנה תמתין עד שתגדיל ותחלוץ אבל לגירסת רב אלפס לא פסל הקטנה עליו וכן הוא גירסת א\"א הרא\"ש ז\"ל וכ\"כ הרמב\"ם ויוציא החרשת בגט שם במשנה קטנה וחרשת בא היבם על הקטנה וחזר ובא על החרשת או שבא אחיו על החרשת פסל את הקטנה ופירש\"י פסל את הקטנה. משום גזירה דילמא קדם ובעיל חרשת ברישא וכדאמרינן בגמרא ואע\"ג דממ\"נ היא שריא ליה הואיל וראשונה היא אי קנויה היא הא קנויה היא אי לא קנויה היא נכרית בעלמא היא עד כאן לשונו אבל הרא\"ש גורס במשנה לא פסל את הקטנה וכך הם דברי הרמב\"ם ז\"ל בפ\"ה וז\"ל קטנה וחרשת שבא היבם תחלה על הקטנה וחזר ובא הוא או אחיו על החרשת לא פסל את הקטנה והחרשת צריכה גט שביאת הקטנה מעולה מביאת החרשת שהקטנה ראויה היא לאחר זמן לפיכך יקיים הקטנה שנבעלה תחלה עכ\"ל. וכתב נ\"י שכן אמרו הגאונים וכן הרי\"ף ז\"ל בהלכותיו וגם ה\"ה כתב על דברי הרמב\"ם ז\"ל שם קטנה וחרשת בא היבם על הקטנה וחזר ובא על החרשת או שבא אחיו על החרשת לא פסל את הקטנה כך הוא הגירסא בספרים ובהלכות והן הן דברי רבינו אבל רש\"י ז\"ל גורס פסל את הקטנה והביאו לזה הברייתא שהזכירו שם בא היבם על הקטנה וחזר ובא על החרשת או שבא אחיו על החרשת נאסרו שתיהן עליו ואמרו שהטעם דלמא קדים ובעיל חרשת ברישא וזהו דעת הראב\"ד בהשגות שכתב א\"א טעות הוא זה שהרי נאסרו שתיהן עליו דילמא קדים ובעיל חרשת ברישא עד כאן ואיפשר שרבי' וההלכות סוברים דהך ברייתא פליגא אמתני' וה\"ל הלכה כסתם מתני' והרשב\"א ז\"ל הכריע כדברי רש\"י והרא\"ה ז\"ל עכ\"ל. ואני אומר דמאחר שהגאונים והרי\"ף והרמב\"ם והרא\"ש ז\"ל מסכימים דלא פסל את הקטנה הכי נקטינן הלכה למעשה:","בא על החרשת וחזר ובא הוא או אחיו על הקטנה כתב הרמב\"ם דפסל החרשת עליו ומלמדין את הקטנה שתמאן ויוציא החרשת בגט בפ\"ה ואין לשון רבינו מכוין דמשמע מיניה דהרמב\"ם הוא שחידש וכתב דפסל את החרשת והא ליתא דמשנה שלימה היא בסוף המשנה הנזכר ופירש\"י פסל את החרשת שמא קטנה קנויה כולה וקנין החרשת משויירת עכ\"ל. ומה שחידש הרמב\"ם אינו אלא שמלמדין את הקטנה שתמאן בו וכך ה\"ל לרבינו לסדר לשונו בא על החרשת וחזר ובא הוא או אחיו על הקטנה פסל את החרשת וכתב הרמב\"ם ומלמדין את הקטנה שתמאן ויוציא החרשת בגט.","ומ\"ש שהשיג עליו הראב\"ד ז\"ל בהשגות א\"א לא אמרו זהו אלא כדי שתתקיים מצות יבום שהוא מן התורה ולעולם יתרחק אדם מן המיאונים עוד דהא איכא מ\"ד ממאנת למאמרו ואינה ממאנת לזיקתו עכ\"ל וז\"ל ה\"ה כתב רבי' מלמדין את הקטנה שתמאן והוא כדברי ההלכה שכתבתי למעלה דלר\"א בכל גווני מלמדין שתמאן והר\"א חולק בזה בהשגה ולדבריו תמתין עד שתגדיל ותצא בגט וחליצה: ומ\"ש בכאן דהא איכא מ\"ד ממאנת למאמרו ואינה ממאנת לזיקתו אינה קושיא שכבר פסקו בהלכות כעולא דאמר ממאנת אף לזיקתו כמו שנתבאר פי\"א מהלכות גירושין עכ\"ל: ומ\"ש על דברי הראב\"ד ולדבריו תמתין עד שתגדיל ותצא בגט ובחליצה אפשר דהיינו לומר דקטנה תשאר אצלו וכמ\"ש רבי' שנראה מדבריו וקאמר שאם בא להוציאה משתגדיל צריכה גט וחליצה או אפשר שהוא מפרש דברי הראב\"ד שאינו רשאי לקיימה ושלא כדברי רבי':","ומ\"ש רבינו וכן יראה מדברי הרא\"ש ז\"ל איני יודע מהיכן למד כן מדברי הרא\"ש שהרי לא כתב אלא המשנה סתם ולא פירש בה דבר ולא עוד אלא דמשמע דהוא סובר כדברי הרמב\"ם שהרי כתב ה\"ה שטעמו של הרמב\"ם משום דס\"ל דלר\"א בכל גווני מלמדין שתמאן וכדברי הרי\"ף ז\"ל כבר נתבאר בסימן זה שגם דעת הרא\"ש כן וכתב נ\"י על המשנה הנזכר וז\"ל כתב הרשב\"א ז\"ל למ\"ד ממאנת אף לזיקתו בא היבם על החרשת וחזר ובא בין הוא בין אחיו על הקטנה מלמדין את הקטנה שתמאן בו ותשאר החרשת עמו שהרי עוקר הזיקה במיאוניה לגמרי וכמו שלא היתה צרתה כלל וקי\"ל ממאנת אף לזיקתו וקי\"ל כר\"א דאמר בכולן מלמדין את הקטנה שתמאן בו אבל הרמב\"ם ז\"ל כתב בא היבם על החרשת וחזר ובא על הקטנה מלמדין הקטנה למאן והחרשת יוצאה בגט וזה תימה שהרי עקרה זיקתה לגמרי אחר שמיאנה בביאה ובזיקה ועוד שהוא ז\"ל כתב גבי גדולה וקטנה בא על הקטנה וחזר ובא על הגדולה מלמדין את הקטנה שתמאן ויקיים את הגדולה שבעילה זו קונה קנין גמור ע\"כ ואם איתא דחרשת יוצאה בגט מפני שנפסלה תחלה בביאה דקטנה ואין יציאתה בקטנה התירה מ\"ש והלא אפילו הגדולה נפסלה בביאת הקטנה תחלה ואם מיאונה מתירה אף בחרשת כן וצ\"ע עכ\"ל הרשב\"א ז\"ל בשילהי ב\"ש:","אחת פקחת ואחת חרשת בא על הפקחת וחזר הוא או אחיו ובאו על החרשת לא פסלו את הפקחת משנה שם פקחת וחרשת בא היבם על הפקחת וחזר ובא על החרשת או שבא אחיו על החרשת לא פסל את הפקחת בא היבם על החרשת וחזר ובא על הפקחת או שבא אחיו על הפקחת פסל את החרשת והנך רואה שבבא שנייה חסרה בלשון רבינו ואין ספק שט\"ס הוא:","ומ\"ש והחרשת תצא בגט והפקחת בגט וחליצה הוא מקושר עם בבא שנייה דאילו בבא ראשונה פקחת אמאי צריכה חליצה הא כיון דנבעלה תחלה ביאה כשירה היא כבר נסתלק משם זיקת יבום וכי נבעלה אח\"כ החרשת מאי הוי וכך צריך לגרוס אחת פקחת ואחת חרשת בא על הפקחת וחזר ובא הוא או אחיו על החרשת לא פסל הפקחת והחרשת צריכה גט בא היבם על החרשת וחזר הוא או אחיו ובא על הפקחת פסל את החרשת והחרשת יוצאה בגט והפקחת בגט וחליצה וכך הם דברי הרמב\"ם ז\"ל בספ\"ה וכתב ה\"ה כתב רבינו שהחרשת צריכה גט והטעם שאע\"פ שביאת הפקחת פוטרתה מן הזיקה כמו שנזכר למעלה מ\"מ כבר נתבאר שיש ביאה אחר ביאה אפילו בשתי פקחות להצריכה גט והוא שבא עליה לשם אישות או לשם יבמות בא היבם על החרשת וחזר ובא הוא או אחיו על הפקחת כו' פירש רבינו שהחרשת יוצאה בגט ופשוט הוא שביאתה ביאה כשירה היתה ומספיק לה בגט וכן פירש שהפקחת צריכה גט וחליצה והטעם מפני שביאתה היתה ביאה פסולה עכ\"ל:","\u0003אחת גדולה ואחת קטנה כו'\u0004 וחזר ובא הוא או אחיו על הקטנה לא פסל את הגדולה וכולי ג\"ז שם במשנה גדולה וקטנה בא יבם על הגדולה וחזר ובא על הקטנה או שבא אחיו על הקטנה לא פסל את הגדולה בא יבם על הקטנה וחזר ובא על הגדולה או שבא אחיו על הגדולה פסל את הקטנה ר\"א אומר מלמדין את הקטנה שתמאן בו ופירש\"י מלמדין את הקטנה שתמאן בו. ותעקור נישואיה ויקיים את הגדולה עכ\"ל ואיפסק בגמרא הלכה כר\"א וטעמו של ר\"א מבואר דברישא כיון שבא על הגדולה תחלה קיים מצות יבום וכשחזר ובא על הקטנה קנאה כמו שנתבאר דיש ביאה אחר ביאה ואסור לקיים את השנייה ולפיכך מלמדין אותה שתמאן ובסיפא אע\"פ שבא על הקטנה תחלה כיון שלא קיים מצות יבום מן התורה כשבא אח\"כ על הגדולה קנאה קנין גמור מן התורה ונדחית הקטנה מפניה ואסור לקיימה ולפיכך מלמדין את הקטנה שתמאן:"],["\u0003קטנה יתומה וכו'\u0004 משנה וגמרא בפרק ב\"ש (יבמות דף ק\"י):","\u0003ומ\"ש לפיכך וכו'\u0004 פירוש ביאת קטנה אינה פוטרת לחרשת דשמא אינה קנויה כלל לאחיו ונכרית היא וביאת חרשת נמי אינה פוטרת לקטנה כיון דביאתה לא דחיא זיקה לגמרי דנשארה מקצת זיקה אצל הקטנה אם קנויה היא:","וכיצד תקנתן כצ\"ל כונס את החרשת ומוציאה בגט משמע דלאחר שכנס מיד חייב להוציאה בגט אבל אינו רשאי לדור עמה עד שתגדיל הקטנה ויחלוץ לה גזירה שמא יבא על החרשת לאחר שיחלוץ לקטנה ויעבור על לא יבנה כיון שלא בנה שוב לא יבנה. ורב אלפס פסק כר\"א וכו' פירוש דהוא ז\"ל גורס במשנה (דף קי\"א) ר\"א אומר בכולן מלמדין את הקטנה שתמאן וקאי נמי אקטנה וחרשת דתני ברישא ואיפסיקא בגמרא הלכה כר\"א אבל הראב\"ד גורם סתם ר\"א אומר מלמדין את הקטנה שתמאן בו ולא קאי אלא אגדולה וקטנה דתני בסיפא דמלמדין כדי לקיים בחבירתה יבום דאורייתא אבל בקטנה וחרשת דיבום דדבריהם הוא אין מלמדין דחוששין שמא לכשתגדיל מתחרטא בה ועיין בב\"י:","\u0003היו שתיהן חרשות או קטנות וכו'\u0004 משנה שם שתיהן קטנות ביאתה או חליצתה של אחת מהן פוטרת צרתה וכן שתי חרשות ורבינו הקדים בלשונו חרשות לקטנות משום דבמשנה לא אמר וכן ב' חרשות לענין חליצה דחרשת לאו בת חליצה היא כקטנה דבת חליצה היא לכשתגדיל אלא אביאת חרשת קאמר דפוטרת צרתה כמו בשתיהן קטנות וכדמוקי לה התם בגמרא וכיון שרבינו לא נקט כאן ב' חרשות אלא לענין ביאה לכך הקדים חרשות לקטנות כיון דבקטנות אף גבי חליצה פוטרת את צרתה ולא נקט במשנה ולא בפוסקים ב' גדולות משום דדבר פשוט הוא דבגדולות ביאת א' מהן או חליצת א' מהן פוטרת את חבירתה אבל בב' חרשות וב' קטנות סד\"א כיון דאין זיקת קטנה ודאי ואין זיקת חרשת בלא שיור א\"כ זיקה קלישא היא וצריכה חליצה מכל א' וא' קמ\"ל. ומ\"ש אלא מלמדין אותה שתמאן וכו' זה אינו מפורש לא בפירוש רש\"י ותוס' ולא באשיר\"י ואפשר לומר דכאן אין מלמדין אותה שתמאן שמא תתחרט אלא יוציאנה בגט כשיהא בה דעת לשמור גיטה אלא דנמשך אחר לשון הרמב\"ם שכ\"כ מלמדין וכו' ע\"ש פ\"ה:","\u0003אחת קטנה ואחת חרשת וכו'\u0004 לרש\"י פסל הקטנה עליו וכו' שם במשנה (דף קי\"א) כתב רש\"י פסל את הקטנה משום גזירה דלמא קדים ובעיל חרשת ברישא וכו' כלומר דאם בעל חרשת ברישא ה\"ל ביאה דקטנה ביאה פסולה דקם עליה באיסור ב' בתים ולא סגי לה בגט אלא צריכה חליצה ג\"כ וכדאיתא התם ואף ע\"ג דטפי מתוקן ללמד את הקטנה שתמאן אפ\"ה כאן שכתב לרש\"י והראב\"ד דס\"ל אין מלמדין ביבום דדבריהם צריך שיוציאו שתיהן בגט והקטנה תחלוץ כשתגדיל:","\u0003ומ\"ש אבל לגירסת רב אלפס וכו'\u0004 פי' דגרס במשנה קטנה וחרשת בא על הקטנה וכו' לא פסל הקטנה עליו דממה נפשך היא שריא הואיל וראשונה היא אי קנויה היא הא קנויה היא אי לאו קנויה היא נכרית בעלמא היא ורש\"י דגרס במשנה פסל את הקטנה אף ע\"ג דמדינא שריא ממ\"נ אפ\"ה אסורה משום גזירה דלמא קדים ובעיל חרשת ברישא וכו' כדפי':","\u0003בא על החרשת וכו'\u0004 והשיג עליו הראב\"ד דכיון ששתיהן יוצאות למה מלמדין אותה שתמאן פי' כיון דלא קי\"ל הלכה כר\"א דמלמדין אותה שתמאן אעפ\"י שאינו הגון ללמדה שמא כשתגדיל מתחרטה אלא מלמדין כדי לקיים יבום דאורייתא כגון גדולה וקטנה ובא על הגדולה וכו' דכתוב בסוף סימן זה דמלמדין שתמאן ויקיים הגדולה אבל הכא שכתב הרמב\"ם יוציא החרשת בגט א\"כ כשהקטנה תמאן אין כאן יבום כלל ודאי דקשה דלמה מלמדין אותה שתמאן שהוא דבר שאינו הגון והבין רבינו דרצונו לומר כיון דעכ\"פ יוציא החרשת בגט לא היה לנו לעשות דבר שאינו הגון בחנם ללמדה למאן אלא הקטנה תשאר אצלו ותימה גדולה היאך אפשר לדון את הראב\"ד בדברי טעות כזה הלא בהדיא אמרו לשם דדילמא קדים ובעיל חרשת ברישא וה\"ל ביאה דקטנה ביאה פסולה וקם עליה באיסורא דב' בתים כדפי' בסמוך אלמא דפשוט הוא דאם בא על החרשת ברישא ואחר כך בא על הקטנה דקטנה אסורה עליו ותו דהא לעיל בסמוך בבא על הקטנה תחלה ואח\"כ על החרשת כתב רבינו דלרש\"י והראב\"ד שתיהן יוציא בגט והקטנה תמתין עד שתגדיל ותחלוץ ואע\"ג דהקטנה שריא מדינא ממ\"נ אפ\"ה אסורה גזירה דלמא קדים ובעיל לחרשת ברישא דאז גם הקטנה אסורה עליו וצריך שיוציא שתיהן בגט והקטנה תמתין עד שתגדיל ותחלוץ כדפי' לשם וא\"כ היאך יפרש הראב\"ד כאן בהיפך בבא על החרשת תחילה ואחר כך על הקטנה דהחרשת תצא בגט והקטנה תשאר אצלו ואין ספק דמה\"ט כתב רבינו ולא נהירא וכו' אבל מ\"מ לא יצא רבינו נקי היאך עלה על דעתו להבין מדבריו טעות גדול כזה ולהשיג עליו מכחו ועוד הלא הדבר פשוט וברור דהראב\"ד ה\"ק דלמה מלמדין אותה שתמאן שהוא דבר שאינו הגון בחנם הא ודאי דאף להרמב\"ם דשתיהן יוצאות הלא גם הקטנה יוציאנה בגט כשיהא בה דעת לשמור גיטה וגם יחלוץ לה כשתגדיל:","\u0003ומ\"ש וכן יראה מדברי א\"א הרא\"ש ז\"ל כתב ב\"י איני יודע מהיכן למד כן וכו'\u0004 ואפשר מדכתב הרא\"ש המשנה בסתם רבי אלעזר אומר בכולן מלמדין הקטנה שתמאן בו משמעו דבקטנה וחרשת נמי קאמר שתמאן בו כדי שתשאר החרשת אצלו כי היכי דקאמרי' בגדולה וקטנה שתמאן כדי לקיים הגדולה הכי נמי בקטנה וחרשת ודלא כהרמב\"ם דשתיהן יוצאות:"]],["\u0010c0\u0011\u0010y0\u0011יש יבם ויבמה שאינן בני חליצה ויבום מפני שינוי שבגופם ומהן מפני איסור שעליהם ובאותם ששינוי בגופם מהם לא מייבמין ולא חולצין ומהן מייבמין ולא חולצין ומהן חולצין ולא מייבמין ובאותם שהאיסור עליהם מהם לא מייבמין ולא חולצין ומהם חולצין ולא מייבמין \u0010y1\u0011כיצד הסריס והאיילונית אינם בני חליצה ויבום לפיכך איילונית שחלצה לא נפסלה בכך לכהונה וכן הסריס שחלץ או שחלצו לאשתו אינו כלום היה לאיילונית צרה מותרת להתייבם ודוקא איילונית ודאית שיש בה סימני איילונית אבל ספק איילונית חולצת ולא מתייבמת \u0010c1\u0011\u0010y2\u0011ודוקא סריס חמה שלקה ממעי אמו אבל סריס אדם שהיה לו שעת הכושר חולצין לאשתו או מייבמין והוא חולץ ואינו מייבם מפני שפסול לבא בקהל ואם עבר ובא עליה קנאה ומוציאה בגט \u0010y3\u0011ואלו הן סימני איילונית כל שאין לה דדין או שתשמיש קשה לה או שקולה כקול האיש או שאין לה בשר גבוה ועגול כמין כף למעלה מאותו מקום ובאחת מאלו חשובה כאיילונית \u0010c2\u0011\u0010y4\u0011ואלו הן סימני סריס שערו לקוי ורך או שמחליק בשרו ורך כבשר האשה או כשמטיל מים בגומא אינו מעלה קצף או שאינן מחמיצין כששוהין לעמוד בכלי או שאינו עושה כיפה פירוש שאין קילוח השתן הולך למרחוק ועושה כיפה כשמטיל מים כלפי מעלה אלא יורדין מיד או שאין בשרו מעלה הבל כשיוצא ממרחץ בימות הגשמים או שקולו לקוי ואינו ניכר בין איש לאשה \u0010c3\u0011או שלא נתמלא זקנו אפילו הביא שתי שערות בערוה ואין לו שערות בזקנו כלל אפילו אין בו אלא אחד מאלו הסימנין חשוב סריס \u0010c4\u0011אבל אם יש לו ב' שערות בזקנו לא חשיב סריס עד שיהיו בו כל הסימנים אבל אם יש בו כל הסימנים חשיב סריס אע\"פ שיש לו ב' שערות בזקן אע\"פ שאם יש לו ב' שערות במקום אחד בכל הגוף מוציאין אותו מחזקת סריס היינו טעמא לפי שבמקום חזקן רגיל להיות שם שער לכך אינו יוצא על ידו מכלל סריס שאם יש לו כל סימני סריס נדון כסריס ואע\"פ שהביא שתי שערות בזקן חשוב אין לו זקן כיון שלא נתמלא זקנו \u0010c5\u0011\u0010y5\u0011בד\"א שע\"י הסימנין נידונים כסריס ואיילונית כשיהיו בהם הסימנים אחר שהם בני כ' שנה אבל קודם לכן אפילו יש בהם סימני סריס ואיילונית ולא הביאו שתי שערות אין נידונין כסריס ואיילונית אלא תולין הדבר במה שהם קטנים ודינן כקטנים בפחות מבן עשרים אבל מבן כ' ואילך אם יש בהן סימני סריס ואיילוני' נידונין כסריס ואיילוני' אפי הביאו אחר כן שערות \u0010c6\u0011ואם אין בהן סימנים וגם לא הביאו ב' שערות אין נידונים כסריס ואיילונית אלא חשובים כקטנים עד רוב שנותיהן ומרוב שנותיהן נידונין כסריס ואיילונית אפילו אין להם הסימנין \u0010c7\u0011והרמב\"ם כתב דמשהגיע לעשרים שנה פחות ל' יום ולא הביא ב' שערות ויש בו הסימנין חשוב כסריס וכתב עוד \u0010y6\u0011בד\"א כסריס חמה אבל מי שנחתכו או ניתקו גידיו או ביציו הוא הנקרא סריס אדם כשיהיה בן י\"ג שנה ויום אחד נקרא גדול שאינו מביא סימנים לעולם \u0010c8\u0011\u0010y7\u0011אנדרוגינוס כתב הרמב\"ם שדינו כסריס חמה שאינו בר חליצה ויבום וכן הוא לדעת רב אלפס \u0010y8\u0011אבל לדעת ר\"י דינו כזכר גמור לכל דבר וכן הוא מסקנת א\"א הרא\"ש ז\"ל \u0010c9\u0011\u0010y9\u0011וטומטום כתב הרמב\"ם חולץ ולא מייבם מפני שהוא ספק ואם נקרע ונמצא זכר רצה חולץ רצה מייבם וכתב א\"א הרא\"ש ז\"ל אפילו אם נמצא זכר שמא הוא סריס הלכך אם יש לו אחים אחרים וחלץ הוא פסל עליהן ואם אין לו אחים אלא הוא חולץ ולא מייבם \u0010y10\u0011אחים מן האם \u0010y11\u0011וגר ועבד משוחרר אפי' הם תאומים והורתן שלא בקדושה ולידתן בקדושה אינם לא חולצין ולא מייבמים \u0010c10\u0011\u0010y12\u0011פצוע דכא וכרות שפכה וסריס אדם והזקן לאו בני יבום נינהו אבל חולצין לפיכך מתו ולהם אחין מייבמים או חולצין לנשותיהן מתו אחיהם הם חולצין ולא מייבמים ואם בעלו קנו ופצוע דכא וכרות שפכה וסריס אדם יוציאו בגט \u0010c11\u0011\u0010y13\u0011חרשת קטנה ושוטה לאו בני חליצה הן אבל מתייבמות לפיכך אחת מאלו שנפלו לפני יבם אינו יכול לחלוץ \u0010y14\u0011אבל כונס ומוציא בגט אם ירצה \u0010c12\u0011וכן חש\"ו לאו בני חליצה הם אבל מייבמים \u0010y15\u0011והחרש אינו יכול להוציא לעולם שאין גירושיו גירושין בד\"א \u0010y16\u0011כשנפלה לו מאחיו פיקח אבל נפלה לו מאחיו חרש כשם שכנס אחיו ברמיזה כך יוציא ברמיזה \u0010y17\u0011והקטן יוציא בגט אם בא עליה לאחר שהגדיל \u0010y18\u0011ב' אחין א' פקח וא' חרש נשואין לשתי נשים נכריות פקחות מת חרש בעל פקחת אחיו הפקח רצה חולץ רצה מייבם מת פקח בעל פקחת אחיו החרש כונס ואינו יכול לחלוץ ואינו מוציאה לעולם שני אחין פקחין נשואין ב' נשים נכריות אחת פקחת ואחת חרשת מת פקח בעל חרשת אחיו פקח כונס ואינו יכול לחלוץ ואם ירצה יוציא בגט מת פקח בעל פקחת אחיו רצה חולץ רצה מייבם ב' אחין אחד פקח ואחד חרש נשואין לשתי נשים אחת פקחת ואחת חרשת פקח לפקחת וחרש לחרשת מת חרש בעל חרשת אחיו הפקח כונס ואם ירצה יוציא בגט מת פקח בעל פקחת אחיו החרש כונס ואינו מוציאה לעולם \u0010y19\u0011הסומא מייבם ואינו חולץ ואם חלץ חליצתו כשרה \u0010y20\u0011אשת הקטן והשוטה פטורין מן החליצה ומן היבום \u0010y21\u0011אבל אשת החרש והזקנה והעקרה הרי הן כשאר כל הנשים וחולצות ומתייבמות:",["יש יבם ויבמה שאינן בני חליצה ויבום מפני שינוי שבגופם ומהם מפני איסור שעליהם ובאותם ששינוי בגופם מהם לא מייבמין ולא חולצין ומהם מייבמין ולא חולצין ומהם חולצין ולא מייבמין ובאותם שהאיסור עליהם מהם מייבמין ולא חולצין ומהם חולצים ולא מייבמים כל זה מתבאר והולך בסימן זה ומה שלא כתב גבי מפני איסור שעליהן שיש שמייבמין ולא חולצין כמו שכתב גבי שינוי שבגופם הטעם מבואר דכיון שיש איסור עליהם א\"א להתייבם:","ומ\"ש כיצד הסריס והאיילונית אינם בני חליצה ויבום לפיכך איילונית שחלצה לא נפסלה בכך לכהונה וכן הסריס שחלץ או שחלצו לאשתו אינו כלום כלומר לא נפסלה בכך לכהונה וכל זה מבואר במשנה פרק הערל (יבמות דף עט.) וטעמא דסריס פירש\"י מדכתיב ולא ימחה שמו מישראל פרט לסריס ששמו מחוי ואיילונית אמרינן בגמרא בפ\"ק (יב.) דטעמא משום דכתיב והיה הבכור אשר תלד פרט לאיילונית שאינה יולדת. ומ\"ש היה לאיילונית צרה מותרת להתייבם בפ\"ק דיבמות (דף יב.) אמר רב אסי צרת איילונית אסורה ואסיקנא הלכתא צרת איילונית מותרת ואפילו הכיר בה ואפילו צרת בתו איילונית ופירש\"י ואע\"ג דהכיר בה. אחיו וקיימה והויא אשתו לא מיתסרא צרתה משום צרת הבת דכי אסר רחמנא צרת ערוה במקום מצוה הוא דאסרה והא כיון דאיילונית היא דבלאו ערוה נמי לא חזיא ליבום הויא צרתה צרת ערוה שלא במקום מצוה וכך מפרש בה\"ג עכ\"ל ודוקא איילונית ודאית שיש בה סימני איילונית אבל ספק איילונית חולצת ולא מתייבמת פשוט הוא:","ודוקא סריס חמה שלקה ממעי אמו אבל סריס אדם שהיה לו שעת הכושר חולצין לאשתו או מייבמין במשנה פרק הערל (דף מט:) איפליגו ר\"ע ור\"א במילתא ופסקו הפוסקים כר\"ע דאמר סריס אדם חולץ וחולצין לאשתו שהיתה לו שעת הכושר סריס חמה לא חולץ ולא חולצים לאשתו שלא היתה לו שעת הכושר ומשמע דאפי' סריס אדם מייבמין את אשתו אם ירצו ואיידי דנקט בדידיה חולץ דלא הוה מצי למיתני ביה מייבם משום דפסלו לבא בקהל נקט נמי בדידהו חולצין וכך הם דברי רבינו. ומ\"ש ואם עבר ובא עליה קנאה ומוציא' בגט שם בברייתא קתני דאם בעל קנה ואסור לקיימה מפני שהוא אסור לבא בקהל ודבר פשוט דכיון שהוא קונה אותה קנין גמור שהוא מוציאה בגט וא\"צ חליצה ואמרי' בגמרא פרק הערל שם ה\"ד סריס חמה כל שלא ראה מעולם שעה אחת בכשרות מנא ידעינן כלומר שהרי אין סימני סירוס ניכרים בקטנותו אמר אביי כל שמטיל מים ואינו עושה כיפה כלומר וסימן זה ניכר בקטנותו ואע\"ג דבהביא שתי שערות בזקן מודה רבי יוחנן דבעינן כולהו כיון שסימן זה ניכר מיד ושאר הסימנים ניכרים כל אחד בזמנו הראשון הוכיח על האחרים שממעי אמו היה לקוי אלא שלא היו האחרים ראויים להכיר סמוך ללידתו ומקשים בתר הכי וליחוש שמא הבריא כלומר והרי היתה לו שעת הכושר ומשני כיון שתחלתו וסופו לקוי לא חיישינן וכתב הריב\"ש בתשובה סימן תע\"ד נראה מסוגיא זו דלא דיינין ליה בודאי סריס ממעי אמו אלא א\"כ היה לו זה הסימן מתחלת לידתו אבל אם מתחלת לידתו לא היה בו סימן זה שלא נבדק בו איכא למיחש שמא אינו לקוי ממעי אמו ואע\"פ שנולדו בו אחר כך סימני סריס ומ\"מ ספק סריס הוא דכיון שנולדו בו סימני סריס אח\"כ הרי איפשר וקרוב שלקוי היה ממעי אמו וכי אמרינן מנא ידעינן היינו לשוויי' סריס ודאי אבל בלאו הכי הוי ספק וכ\"כ הרא\"ש וז\"ל הא דבעינן לעיל שיהא בו סימני סריס משנולד היינו ליחשב כודאי סריס אבל ספק סריס הוי אע\"פ שלא ניכרו בו סימנים בקטנות ולא נתבררו עד שהגדיל ע\"כ:","\u0003ואלו הן סימני איילונית כל שאין לה דדים וכו'\u0004 שם בפ' הערל (יבמות פב:) בברייתא אלו הן סימני איילונית כל שאין לה דדים ומתקשה בשעת תשמיש רשב\"ג אומר כל שאין לה שיפולי מעים כנשים רשב\"א אומר כל שקולה עבה ואינה ניכרת בין אשה לאיש ופירש\"י מתקשה בשעת תשמיש. תשמיש קשה לה: שיפולי מעים. כמין כף למעלה מאותו מקום כדאמר בפרק יוצא דופן עכ\"ל וכתב הרמב\"ם בפ\"ב מהלכות אישות בסימני איילונית ד' סימנים אלו וכתב ה\"ה פסק רבינו כדברי כולם וסובר שכל אחד מוסיף על דברי חבירו ומ\"ש ובאחת מאלו חשובה כאיילונית איפשר שלמד כן מדין סימני סריס שיתבאר בסמוך אבל הרמב\"ם בפ\"ב מהלכות אישות אע\"פ שבזכר כתב אם נראה בו אחד מסימני סריס הרי הוא סריס ואם לא נראה בו סימן מסימני סריס עדיין קטן הוא גבי איילונית כתב נראה בה סימני איילונית הרי היא איילונית ואם לא נראו בה סימני איילונית עדיין קטנה היא וכתב ה\"ה כתוב בקצת ספרי רבינו יש כל סימני איילונית ואף על פי שיש באיש חילוק סובר רבינו דבאיילונית בעינן כולהו עכ\"ל ול\"נ דאף לספרים דלא גרסינן כל נמי כיון דלא כתב באיילונית כדכתב בסריס משמע דבאיילונית כולהו סימנים בעינן:","ואלו הן סימני סריס כל שאין לו זקן ושערו לקוי ורך או שמחליק בשרו ורך כבשר האשה או כשמטיל מים בגומא אינו מעלה קצף או שאינן מחמיצין כששוהים לעמוד מעט בכלי או שאינו עושה כיפה פירוש שאין קילוח השתן הולך ועושה כיפה כשמטיל מים כלפי מעלה אלא יורדין מיד או שאין בשרו מעלה הבל כשיוצא בימות הגשמים מן המרחץ או שקולו לקוי ואינו ניכר בין איש לאשה שם בברייתא אלו הן סימני סריס חמה כל שאין לו זקן ושערו לקוי ובשרו מחליק רבן שמעון בן גמליאל אומר משום רבי יהודה בן יאיר כל שאין מימיו מעלין רתיחות ויש אומרים כל המטיל מים ואינו עושה כיפה וי\"א כל שאין שכבת זרעו דוחה וי\"א כל שאין מימי רגליו מחמיצין אחרים אומרים כל שרוחץ בימות הגשמים ואין בשרו מעלה הבל רשב\"א אומר כל שקולו לקוי ואינו ניכר בין אשה לאיש ופירש\"י לקוי. רך: מחליק. חלק כבשר האשה דרך בשר האיש להיות שעיר: רתיחות. אשקומא: כיפה. קילוח ארוך למרחוק: דוחה. שאינו קשור אלא צלול כמים: מחמיצין. מסריחין כששוהין בכלי: הבל. חמימות כעין עשן וכתב הרמב\"ם ז\"ל בפ\"ב מה' אישות כל סימנים אלו משמע דס\"ל דהני תנאי לא פליגי אלא כל אחד מוסיף על דברי חבירו כמו שפירש גבי סימני איילונית: ומ\"ש עוד רבינו או שלא נתמלא זקנו אפי' הביא ב' שערות בערוה ואין לו בזקנו כלל אפי' אין בו אלא א' מאלו הסימנים חשוב סריס אבל אם יש לו ב' שערות בזקנו לא חשיב סריס עד שיהיו בו כל הסימנים אבל אם יש בו כל הסימנים חשיב סריס אע\"פ שיש לו ב' שערות בזקן אע\"פ שאם יש לו ב' שערות בכל הגוף במקום א' מצילין אותו מחזקת סריס היינו טעמא לפי שבמקום הזקן רגיל להיות שם שער לכך אינו יוצא על ידם מכלל סריס שאם יש לו כל סימני סריס נדון כסריס ואע\"פ שהביא ב' שערות בזקן חשוב אין לו זקן כיון שלא נתמלא זקנו כך הוא הגירסא בספרי רבינו המדוייקים ובקצת ספרים יש בהם קצת חסרון ודברים אלו שם בפרק הערל שם איתמר סימני סריס רב הונא אמר עד שיהיו כולם רבי יוחנן אמר אפי' בא' מהם היכא דהביא ב' שערות בזקן כ\"ע ל\"פ דעד שיהיו כולן כי פליגי בשלא הביא אלא הא דא\"ל רבה בר אבוה לרבנן עיינו ביה ברב נחמן אי בשרו מעלה הבל איתיב ליה ברתאי כמאן כר\"ה לא רב נחמן סיכי דיקני הוו ליה וידוע דהלכה כר' יוחנן ופירש\"י איתיב ליה ברתאי. אלמא כיון דליתנהו כולהו סימני סריס דבצר ליה האי מחזקינן ליה כסריס: סיכי דיקנא. יתדות הזקן כלומר [בכמה] מקומות ה\"ל שער בזקנו וכתבו התוספות דהיכא דהביא ב' שערות בזקן כ\"ע ל\"פ עד שיהא בכולן וא\"ת והא אמרת לעיל בן כ' שנה ולא הביא ב' שערות וכו' הא הביא ב' שערות קודם כ' לא חשיב ודאי סריס אע\"פ שיש בו סימני סריס וא\"כ מאי קאמר עד שיהא בכולן אפי' כולן אין מועילין דהא הביא ב' שערות בזקן ואור\"י דשערות דזקן אין מועילין לדין הבאת ב' שערות אע\"ג דבכל שאר מקומות בגוף מועילין וא\"ת כיון דהביא ב' שערות בזקן מאי קאמר עד שיהא בכולן והלא אחד מן הסימנים הוא שאין לו זקן והרי יש לו זקן ואור\"י דאין חשוב בהבאת ב' שערות לבד יש לו זקן אא\"כ נתמלא זקנו עכ\"ל וכ\"כ הרא\"ש ז\"ל היכא דהביא ב' שערות [בזקן] כ\"ע ל\"פ דעד שיהיו כולן וב' שערות בזקן לא חשיבי שערות לגדלות לאפוקי מידי סריס אף על גב דבשאר מקומות בגוף מועילים לפי שמקומות הזקן רגיל להביא שערות לכך אינו חשוב גדול על ידם ואם הביא כל סימני סריס חשבינן ליה סריס ואף על פי שהביא ב' שערות בזקן חשיב אין לו זקן כיון שלא נתמלא זקנו עכ\"ל. והרמב\"ם ז\"ל כתב בפ\"ב מה\"א וז\"ל הגיע לזמן הזה ולא הביא ב' שערות למטה ולא הביא ב' שערות בזקן אם נראה בו א' מסימני סריס הרי הוא סריס ודינו כדין הגדול לכל דבר ואם לא נראה בו סימן מסימני סריס עדיין קטן הוא עד שיביא ב' שערות למטה במקום הראוי להן או עד שיהיה בן ל\"ה שנה ויום אחד וכתב ה\"ה חילוק זה שכתב רבינו שאם הביא ב' שערות בזקן בעי כל סימני סריס ואם לא הביא א\"צ אלא א' הוא כר\"י פרק הערל וא\"ת והלא שאין לו זקן הוא אחד מסימני סריס וא\"כ זה שהביא ב' שערות בזקן היאך אפשר שיהיו כל סימני סריס בו והלא חסר זה מהם [כבר] תירצו בתוס' דאין לו זקן [ר\"ל לא] נתמלא זקנו ומ\"מ הלשון שכתב רבינו ולא הביא ב' שערות בזקן אם נראה בו אחד מסימני סריס השיג עליו הרא\"ש ז\"ל ואמר דכיון דלא הביא ב' שערות בזקן הרי יש לו סימן אחד מסימני סריס וא\"צ יותר וי\"ל לדעת רבינו שאע\"פ שלא הביא ב' שערות בזקן אכתי בעי סימן אחר ולשון הגמרא מוכיח כן דקאמר דפלוגתייהו בלא הביא וקאמר ר\"י באחד מהם ואם לא היה צריך לסימן אחר הל\"ל הרי הוא כסריס ולדעת הרא\"ש ז\"ל לא משכחת לה ששאר סימני סריס יועילו כלל אלא הכל תלוי בהבאת ב' שערות בזקן כמו שיתבאר בסמוך בדעתו ז\"ל וזה תימה שא\"כ למה הוזכרו שאר סימנים עכ\"ל:","בד\"א שע\"י הסימנים נדונים כסריס ואיילונית כשיהיו בהם הסימנים אחר שהם בני כ' שנה אבל קודם לכן לא אפי' יש בהם סימני סריס ואיילונית ולא הביא ב' שערות אין נידונים כסריס ואיילונית אלא תולין הדבר במה שהם קטנים ודינן כקטן בפחות מבן כ' אבל מבן כ' ואילך אם יש בהם סימני סריס ואיילונית נידונין כסריס ואיילונית אפי' הביא אח\"כ שערות ואם אין בהם סימנין וגם לא הביאו ב' שערות אין נידונים כסריס ואיילונית אלא חשובים כקטנים עד רוב שנותיהם ומרוב שנותיהם נידונין כסריס ואיילונית אפי' אין להם סימנים כך הוא הגירסא הנכונה בספרי רבינו המדוייקים ובקצת ספרים יש חסרון הניכר ודינים אלו בס\"פ יוצא דופן (נדה דף מז.) דתנן התם בת עשרים שלא הביאה ב' שערות תביא ראיה שהיא בת עשרים והיא איילונית לא חולצת ולא מתייבמת בן עשרים שלא הביא ב' שערות יביאו ראיה שהוא בן כ' והוא סריס לא חולץ ולא מייבם אלו דברי בית הלל בית שמאי אומרים זה וזה בני י\"ח וידוע דהלכה כבית הלל. ובגמרא ורמינהו אחד לי בן ט' ויום אחד ואחד לי בן עשרים שלא הביא ב' שערות אמר רב שמואל בר יצחק אמר רב והוא שנולדו בו סימני סריס ואם לא נולדו בו סימני סריס עד כמה תני רבי חייא עד רוב שנותיו ופירש\"י ורמינהו אחד לי בן ט' שנים וכו'. שניהם דין אחד להם וביאתו כמאמר בגדול כדאמרי' לעיל אלמא קטן הוא ובעיא אמתוני: אמר רב שמואל. מתני' כגון שנולדו בו סימני סריס המפורשים בפ' הערל עכ\"ל. וז\"ל הריב\"ש בתשובה סי' תע\"ד ידוע שסימני סריס צריך שיהיו בו והוא בן כ' שנה אבל קודם לזמן הזה אין נקרא סריס אפי' יש בו כל סימני סריס ולא הביא שתי שערות כדאמר רבי אבהו בפ' הערל (יבמות פ.) סימני סריס וסימני איילונית אין עושין בהם מעשה עד שיהיו בן כ' ותנן נמי בפרק יוצא דופן בן עשרים שנה שלא הביא שתי שערות יביאו ראיה שהוא בן עשרים והוא סריס לא חולץ ולא מייבם ואיתמר עלה והוא שנולדו בו סימני סריס וכן אמרינן עלה נמי בפרק הבא על יבמתו ובפרק האשה רבה (יבמות דף צז) ואיכא למידק מינה הא פחות מבן עשרים שלא הביא שתי שערות אע\"פ שנולדו בו סימני סירוס לא דיינינן ליה כסריס אלא אמרינן עדיין קטן הוא וכן אם הוא בן עשרים ולא הביא שתי שערות לא דיינינן ליה כסריס אע\"פ שנולדו בו סימני סירוס אח\"כ אלא אמרינן דכיון שהגיע לעשרים ולא נולדו בו סימני סירוס לאו סריס הוא ומה שלא הביא שתי שערות עד עתה לפי שעדיין קטן הוא ומשעת הבאת סימנים ואילך הוא גדול ואם אח\"כ נולדו בו סימני סירוס חולי הוא ואין זה סריס חמה שהוא לקוי ממעי אמו ואם הוא בן עשרים ולא הביא שתי שערות ונולדו בו סימני סריס אע\"פ שהביא שתי שערות לאחר מכאן הרי הוא כסריס לכל דבריו כדאיתא בברייתא בפרק הערל דכיון שהוא בן כ' וקדמו סימני סירוס להבאת ב' שערות כסריס דיינינן ליה ואם הגיע לרוב שנותיו שהם ל\"ו שנים ולא הביא ב' שערות אע\"פ שלא נולדו בו סימני סירוס הוי סריס ואפי' הביא ב' שערות לאחר מכאן שכיון שנתאחרו כ\"כ ודאי סריס הוא כדאמרינן בפ' יוצא דופן וכי לא נולדו בו סימני סירוס עד כמה עד רוב שנותיו ובנדון זה אם ראובן הגיע לרוב שנותיו וידוע שלא הביא ב' שערות במקום הערוה שהוא מקום הבאת ב' שערות וכמ\"ש הרמב\"ם אף אם לא היו בו סימני סירוס כלל הרי הוא סריס ואין אשתו חולצת ולא מתייבמת אלא שא\"א לנו לידע זה בבירור ואפי' בבדיקה שאפי' אם נבדק ולא נמצאו בו ב' שערות קי\"ל בפרק יוצא דופן דחוששין שמא נשרו ובפ' בא סימן אמרינן גומות אע\"פ שאין שערות והביאוה הרי\"ף והרמב\"ם ומי יוכל לבדוק במקום הבאת שערות שלא יהא שם לא שער ולא גומא וע\"כ צריכה חליצה מספק שמא הביא ב' שערות ולאו סריס הוא ואינה מתייבמת דדלמא לא הביא ונמצא פוגע באשת את שלא במקום מצוה דכיון שנבדק לאחר רוב שנותיו ולא נמצאו לו שערות איתרע ליה רובא ואיכא למיחש לסריס וכ\"ש בזה שנמצאו בו קצת מסימני סריס אבל אם לא נבדקו כלל ולא ידענו אם הביא שתי שערות ולא הביא סימני סירוס בזה ודאי אשתו מתייבמת דכיון דע\"כ גדול הוא בין הביא ב' שערות בין לא הביא לא דיינינן ליה כסריס דרובא דאינשי לאו סריסים נינהו אלא אמרינן כיון שהגיע לרוב שנותיו ודאי הביא שתי שערות וכתב עוד ואם ראובן זה לא הביא ב' שערות והביא ב' שערות בזקן אלא שלא נתמלא זקנו אם אין בו כל סימני סריס אינו סריס אבל מ\"מ כיון שלא הביא ב' שערות ואינו סריס הרי הוא קטן עדיין ואשתו פטורה מן החליצה ומן היבום כדתניא בפ' חרש (קיב:) ואם לא נבדק בהבאת שתי שערות אם לא היו בו סימני סריס היתה אשתו חולצת ולא מתייבמת דאם הביא שתי שערות בהן מתייבמת שהרי גדול היה ואם לא הביא קטן היה ואינה אסורה עליו משום אשת אח ומספק צריכה חליצה שמא הביא ב' שערות דכיון שהגיע לכלל שנותיו חזקה הביא סימנים ולהצריכה חליצה לחומרא אזלינן בתר הך חזחה דהא אמרי' לה במיאון לחומרא לענין שלא תוכל למאן עכ\"ל ומ\"ש רבי' בשם הרמב\"ם דמשהגיע לכ' שנה פחות ל' יום ולא הביא ב' שערות ויש בו הסימנים חשיב כסריס ז\"ל בפ\"ב מה\"א היתה בת כ' פחות ל' יום ולא הביאה ב' שערות ונראו בה סימני איילונית הרי היא איילונית ואם לא נראו בה סימני איילונית עדיין היא קטנה עד שתביא ב' שערות או עד שתהיה בת ל\"ה שנה ויום אחד הגיעה לזמן הזה ולא הביאה שתי שערות הרי זו נקראת איילונית אע\"פ שלא נראה בה סימן מסימני איילונית ואצל הזכר כתב הביא ב' שערות למטה במקומות הידועים לשער והוא מבן י\"ג שנים ויום אחד ומעלה נקרא גדול והוא נקרא איש הגיע לזמן הזה ולא הביא ב' שערות אע\"פ שנראו בו סימני סריס הרי הוא קטן עד שיהיה בן עשרים שנה פחות ל' יום הגיע לזמן הזה ולא הביא שתי שערות למטה ולא ג\"כ בזקן אם נראה בו סימן אחד מסימני סריס הרי הוא סריס ודינו כדין הגדול לכל דבר ואם לא נראה בו סימן מסימני סריס עדיין קטן הוא עד שיביא ב' שערות למטה במקומות הראוי להן או עד שיהיה בן ל\"ה שנה ויום א' הגיע לזמן הזה ולא הביא הרי זה סריס אע\"פ שלא נראה בו אחד מסימני סריס הגיע לשנת עשרים פחות ל' יום ולא הביא ב' שערות למטה והביא ב' שערות בזקן אע\"פ שנולד לו אחד מסימני סריס אינו סריס אלא הרי הוא בקטנותו עד שנולדו בו כל סימני סריס או עד שיהיה בן ל\"ה שנה ויום אחד וכ' ה\"ה היתה בת כ' פחות ל' יום כו' כך נמצא בספרי רבי' ולפי זה הוא מפרש שמה שאמרו בסוף פ' יוצא דופן שבת עשרים שיצאו ממנה שלשים יום הרי היא כבת עשרים לכל דבריה ומסקנא דגמרא (עתידין) שיצאו שעתידין לצאת עדיין דכיון דאינה חסרה אלא שלשים יום הרי היא כאילו נשלמה וקורא שיצאו אבל כל שאר המפרשים ראיתי שפירשו שיצאו כבר דכיון דהיא בת י\"ט ושלשים יום משנת עשרים הרי הם חשובים שנה וכאלו נשלמה לה עשרים וכ\"כ בהשגות וכ\"נ עיקר הגיע לזמן זה כו' שם מבואר ומה שאמר בן עשרים שנה פחות שלשים יום הוא כפי דעתו הנזכר למעלה בדין הבת וכבר כתבתי שחלקו עליו עכ\"ל ורבינו כ' בסי' קנ\"ה על מ\"ש הרמב\"ם גבי איילונית היתה בת עשרים שנה פחות ל' יום שט\"ס הוא וכך יש לו להיות אם היתה בת י\"ט שנה ושלשים יום ויש לתמוה עליו למה כאן גבי סריס הביא דברי הרמב\"ם ולא כתב עליו שהוא ט\"ס ועוד יש לתמוה עליו למה כתב כאן שהם בני כ' שנה ולא כתב בני י\"ט ול' יום וצ\"ל שסמך על מה שכתב בסי' קנ\"ה:","וכתב עוד בד\"א בסריס חמה אבל מי שנחתכו או ניתקו גידיו או ביציו הוא הנקרא סריס אדם כשיהיה בן י\"ג שנה ויום אחד נקרא גדול שאינו מביא סימנים לעולם פשוט הוא. גרסי' בסוף פרק יוצא דופן (נדה מז:) כי אתו לקמיה דר' חייא אי כחוש אמר להו אבריוה אי בריא אמר להו אכחשוה דהני סימנים זימנין דאתו מחמת כחשותא זימנין דאתו מחמת בריאותא ופירש\"י כי אתו לקמיה דרבי חייא. בני כ' שנה שלא הביאו ולא ידעתי למה השמיטו הפוסקים דבר זה דהא ליכא מאן דפליג ביה :","אנדרוגינוס כתב הרמב\"ם שדינו כסריס חמה שאינו בר חליצה ויבום בפ\"ו מהלכות יבום ואלו שאין להן זיקה כלל סריס חמה ואנדרוגינוס מפני שאינן ראויין לילד ולא היה להם שעת הכושר והוא מבואר בברייתא שכתבו הרי\"ף והרא\"ש ז\"ל בספ\"ק דיבמות עריות שאמרו לא חולצות ולא מתייבמות מוסיף עליהם אשת סריס חמה ואשת אנדרוגינוס ומשמע דכי היכי דאשת אנדרוגינוס אינה זקוקה ליבום הכי נמי אנדרוגינוס שמת אחיו אין אשתו זקוקה לו גבי סריס חמה נמי אף על גב דלא קתני אלא אשת סריס חמה ה\"ה דסריס חמה שמת אחיו אין אשתו זקוקה לו:","ומ\"ש אבל לדעת ר\"י דינו כזכר גמור לכל דבר וכן הוא מסקנת אדוני אבי הרא\"ש ז\"ל בסוף פרק הערל (יבמות דף פא.) תנן רבי יוסי ור\"ש אומרים אנדרוגינוס כהן שנשא בת ישראל מאכילה בתרומה ובגמרא (דף פג:) אמר רב ליתא למתני' מקמי ברייתא דתניא רבי יוסי אומר אנדרוגינוס בריה בפני עצמו הוא ולא יכלו חכמים להכריע בו אם הוא זכר או נקבה אמרי בי רב משמיה דרב הלכה כרבי יוסי באנדרוגינוס כתב הרי\"ף וכן הלכה וכתב הרא\"ש מתוך דבריו משמע דהא דפסיק משמיה דרב הלכה כר' יוסי אר' יוסי דברייתא קאי כדאמר רב ליתא למתני' מקמי ברייתא ורש\"י פירש דארבי יוסי דמתני' קאי ואמרי בי רב היינו רב הונא כדאמר לקמן ופליג אהא דאמרן לעיל אליבא דרב ליתא למתני' מקמי ברייתא וכן פר\"י דאמרינן כי הוינן בי רב הונא כו' ש\"מ דפליגי אמוראי בהא מילתא אליבא דרב וכיון דפליגי אליביה דרב מסתבר דהלכה כדאמרי בי רב דשמואל סבר כוותיה דאמר ליתא לברייתא מקמי מתני' ולהאי פיסקא חייבים עליו סקילה מב' מקומות כרבי יוסי דמתניתין עכ\"ל ומשמע לפי דבריהם דהוי דינו כזכר גמור לכל דבר ומשמע לרבינו ז\"ל דמסקנת הרא\"ש כפי' רש\"י ור\"י מדהביא דבריהם לבסוף ויש לתמוה על זה דא\"כ היאך כתב בסוף בפ\"ק דיבמות סתם ברייתא דקתני אשת אנדרוגינוס לא חולצת ולא מתייבמת וצ\"ל דס\"ל לרבינו שאותה הברייתא אתיא דלא כהלכתא בענין אנדרוגינוס לדעת הרא\"ש ז\"ל ולא כתבה אלא משום דברים אחרים שנשנו בה דהלכתא נינהו וסמך על מ\"ש בפרק הערל וקשה לן דא\"כ לא הוה שתיק הרא\"ש מלכתוב על אותה הברייתא דקתני דאשת אנדרוגינוס לא חולצת ולא מתייבמת אתיא דלא כהלכתא כמו שאכתוב בסוף פ' הערל ומדלא כתב כן משמע דסבירא ליה דהאי ברייתא הלכתא היא ופי' רש\"י ור\"י שכתב בסוף פרק הערל לאו משום דסבירא ליה כוותייהו כתב כן אלא להודיענו דעתם ועוד יש לומר דאפילו אם תמצא לומר דסבירא ליה כפירוש רש\"י ור\"י שדינו כזכר להאכיל בתרומה ולחייב עליו סקילה מכל מקום לענין יבום וחליצה דינו כסריס חמה כדקתני בברייתא וטעמא משום דאינו ראוי להוליד וכמו שכתב הרמב\"ם ז\"ל ואיפשר דרש\"י ור\"י נמי הכי סבירא להו כתב רבינו ירוחם בשם הרמ\"ה אנדרוגינוס חולץ וחולצים לאשתו אבל אינה פסולה לכהונה דספק חלוצה לא גזרו בה רבנן ואם קדמו וכנסו אין מוציאין מידם:","וטומטום כתב הרמב\"ם חולץ ולא מייבם מפני שהוא ספק ואם נקרע ונמצא זכר רצה חולץ רצה מייבם בפרק ו' כתב הרב המגיד דין הטומטום פשוט הוא שהרי הוא בספק ואם נקרע ונמצא זכר הרי הוא זכר גמור הנזכר בפרק ב' מהלכות אישות ודלא כרבי יהודה דאמר בהערל טומטום שנקרע ונמצא זכר לא יחלוץ מפני שהוא כסריס עכ\"ל. ומ\"ש רבינו בשם הרא\"ש ז\"ל שם סוף פרק הערל אהא דתנן רבי יהודה אומר טומטום שנקרע ונמצא זכר לא יחלוץ מפני שהוא כסריס אמרי' בגמרא אמר רבי אמי מאי עביד רבי יהודה לטומטום דבירי דאותבוה אכורסיה ואיקרע ואוליד ז' בנין ורבי יהודה חזור על בניו מאין הם תניא ר\"י ברבי יהודה אומר טומטום לא יחלוץ שמא יקרע ונמצא נקבה ואפילו ימצא זכר שמא ימצא סריס חמה מאי בינייהו אמר רבא לפסול במקום אחין ולחלוץ שלא במקום אחין איכא בינייהו ופי' רש\"י מאי בינייהו. מאי איכא בין ר\"י ברבי יהודה לאבוה וכתב הרא\"ש א\"ר אמי מאי עביד רבי יהודה לטומטום דבירי כו' משמע דרבנן פליגי עליה וסברי דלאו סריס הוא וחולץ ומייבם ור\"י ברבי יהודה פליג אאבוה ועביד ליה ספק סריס ופסיל במקום אחין וחולץ שלא במקום אחין ואינו מייבם והכי עבדינן לחומרא עכ\"ל ויש לתמוה עליו כיון דמשמע ליה מדרבי אמי דרבנן פליגי עליה דרב יהודה אמאי לא פסק כוותייהו וכמו שפסק הרמב\"ם וכן נראה שהוא דעת הרי\"ף שהשמיט הא דאמר ר\"י טומטום שנקרע ונמצא זכר לא יחלוץ למימרא דלית הלכתא כוותיה ושמא י\"ל דטעמא דהרא\"ש משום דכיון דלא מפרש בהדיא לא במשנה ולא בברייתא ולא בגמרא דאיפליגו רבנן עליה דר' יהודה לא סמכינן אמשמעותא דמשמע לן להקל וכיון דר' יהודה ור\"י בריה פליגי ולא איפסיקא הלכתא כחד מינייהו נקטינן כמאן דמחמיר ואע\"ג דר\"י בר' יהודה מסתמא תלמידא דאבוה הוא וקי\"ל דאין הלכה כתלמיד במקום הרב כבר כתבו דלא אמרינן הכי אלא מאביי ורבא ואילך אבל קודם לכן איפשר דהלכה כתלמיד במקום הרב:","\u0003אחים מן האם וגר ועבד משוחרר כו'\u0004 לא חולצין ולא מייבמין אחים מן האם מבואר רפ\"ב דיבמו' (דף יז.) ואיכא מאן דיליף לה מדכתיב כי ישבו אחים יחדיו המיוחדים בנתלה פרט לאחים מן האם ואיכא מאן דיליף לה אחוה אחוה מבני יעקב:","ומ\"ש וגר ועבד משוחרר אפי' הם תאומים והורתם שלא בקדושה ולידתם בקדושה אינם לא חולצים ולא מייבמים ברייתא בר\"פ נושאין (דף צז:) ב' אחים תאומים גרים וכן משוחררים לא חולצין ולא מייבמין ואין חייבין משום אשת אח היתה הורתן שלא בקדושה ולידתן בקדושה לא חולצין ולא מייבמין אבל חייבים משום אשת אח:","פצוע דכא וכרות שפכה וסריס אדם והזקן לאו בני יבום נינהו אבל חולצין לפיכך מתו ולהם אחים מייבמים או חולצין לנשותיהם מתו אחיהם הם חולצים ולא מייבמים ואם בעלו קנו ופצוע דכא וכרות שפכה וסריס אדם יוציאו בגט ברייתא כתבוהו הרי\"ף והרא\"ש ז\"ל בספ\"ק דיבמות פצוע דכא וכרות שפכה וסריס אדם והזקן חולצים ולא מייבמים ואם בעלו קנו ואסור לקיימן משום שנאמר לא יבא פצוע דכא וכרות שפכה בקהל ה' וכתב נ\"י פצוע דכא כו' לא מייבמים דחייבי לאוין נינהו ומ\"מ כיון שהיתה להם שעת הכושר רמיא קמייהו לחליצה והאי זקן מיירי שתשש כחו וכשל הוא דומיא דסריס דלאו בר ביאה והקמת שם הוא ואם בעלו קנו ומגרשין בגט בלא חליצה עכ\"ל וכ\"כ הרמב\"ם ז\"ל בפ\"ו וז\"ל ואלו חולצים ולא מייבמים פצוע דכא וכרות שפכה וכיוצא בהן ממיני הסריס והזקן ביותר שתשש כחו וכשל ואם בעל סריס אדם קנה שהרי היתה לו שער הכושר ומוציא בגט מפני שהוא אסור לבא בקהל ובפ\"ב דיבמות (דף כ:) תניא פצוע דכה וכרות שפכה סריס אדם והזקן או חולצין או מייבמין כיצד מתו ולהם אחים ולהם נשים ועמדו אחים ועשו מאמר בנשותיהם ונתנו גט או שחלצו מה שעשו עשו ואם בעלו קנו מתו אחים ועמדו הם ועשו מאמר בנשותיהם ונתנו גט או שחלצו מה שעשו עשו ואם בעלו קנו ואסור לקיימן משום שנאמר לא יבא פצוע דכא כו' ופירש\"י סריס אדם שסירסו אדם ולא מחמת חולי נסתרס מאליו הוי בלאו דבלאו לא יבא פצוע דכא וכרות שפכה הוא ואסור לישא ישראלית דכתיב לא יבא פצוע דכא: או מייבמין. לאו לכתחלה קאמר אלא ייבומיה יבום: שאם בעלו קנו. כדקתני ואזיל והזקן שפסק מלידה והאי לאו מחייבי לאוין הוא אלא קמ\"ל אע\"ג דלאו בר אולודי הוא ביאתו ביאה לקנות יבמתו ויוציאנה ממנו בגט: ונתנו גט. כלומר או נתנו גט או חלצו וגט ביבמה מהני למפסל עליו ועל כל האחים דאי בעי ליבומי תו לא מצי דקם ליה בשוב לא יבנה: ואם בעלו קנו. ויוצאות בגט בלא חליצה: ואסור לקיימה. אסיפא קאי מתו אחין ובעלו הן את יבמתו ואפצוע דכא וכיוצא בו ולא אזקן ע\"כ וכתבו התוס' פצוע דכא וכרות שפכה וסריס אדם פי' שהם סרים אדם לאפוקי בידי שמים שלא היה להם שעת הכושר אם בעלו קנו ה\"ה דנמי לכתחלה שרי כדמוכח לקמן אלא איידי דנקט בסיפא לשון דיעבד נקט נמי ברישא לשון דיעבד עכ\"ל:","חרשת קטנה ושוטה לאו בני חליצה הן אבל מתייבמות לפיכך אחת מאלו שנפלו לפני יבם אינו יכול לחלוץ אבל כונס ומוציא בגט אם ירצה זה מבואר במשנה פרקי חרש בדין יבמה חרשת ודבר פשוט הוא דה\"ה לשוטה וקטנה לענין שמתייבמות ואינן חולצות שהרי קטנה נתבאר בפרק מצות חליצה שאינה חולצת ושוטה דינה כחרשת כמבואר בברייתא שכתבו הרי\"ף והרא\"ש ז\"ל בספ\"ק דיבמות:","ומ\"ש רבינו כונס ומוציא בגט אם ירצה דבריו סתומים דמשמע דקאי אשוטה וקטנה נמי והא ליתא שאין דברים אלו אמורים אלא לחרשת לא לשוטה וקטנה דהא שוטה אינה מתגרשת כמבואר בר\"פ חרש (קיב:) וקטנה נמי בעודה קטנה נמי לאו בת גירושי הוא כמבואר בפרק התקבל (גיטין סד:) ודברי הרמב\"ם ז\"ל בפ\"ו הם מכוונים שהרי כתב וזה לשונו אלו שמתייבמות ולא חולצות החרשת והשוטה והקטנה לפי שאין בהן דעת לקרות ולהבין ואם רצה הייבם לגרש החרשת בגט אחר שיבעול אותה ה\"ז מגרש עכ\"ל. וכן חש\"ו לאו בני חליצה נינהו אבל מייבמין בברייתא שכתבו הרי\"ף והרא\"ש ז\"ל בספ\"ק דיבמות החרש והשוטה מייבמין ולא חולצין ובמשנה פרק חרש מבואר דחרש מייבם ואינו חולץ ומשמע דה\"ה לשוטה כדאיתא בברייתא:","ומ\"ש והחרש אינו יכול להוציא לעולם שאין גירושיו גירושין מבואר במשנה פרק חרש גבי יבם חרש כונס ואינו מוציא לעולם ופירש\"י ואינו מוציא לעולם דלא אתי גט דידיה ומפקע זיקת יבומי אחיו הראשון:","ומ\"ש כשנפלה לו מאחיו פיקח אבל נפלה לו מאחיו חרש כשם שכנס אחיו ברמיזה כך יוציא הוא ברמיזה נראה שטעמו מדתנן בר\"פ חרש חרש שנשא פקחת ופיקח שנשא חרשת אם רצה יוציא ואם רצה יקיים כשם שהוא כונס ברמיזה כך מוציא ברמיזה ומשמע לרבינו דה\"ה ביבמה שנפלה לו מאחיו שנשאה כשהיה חרש כיון שנישואיה לא היה אלא ברמיזה וגם יבומיה לא היה אלא ברמיזה אם ירצה יוציא ברמיזה אבל הרמב\"ם כתב פ\"ו כלשון הזה ולכשייבם החרש אינו מוציא לעולם שבעילתו עושה אותה א\"א גמורה ואין גירושיו גירושין גמורים ולא חילק בין נפלה לו מאחיו פקח לנפלה לו מאחיו חרש ויש לתמוה עליו מההיא דתנן כשם שהוא כונס ברמיזה כך הוא מוציא ברמיזה והוא עצמו ז\"ל כתבה לפסק הלכה בפ\"ב מהל' גירושין וז\"ל אם נשא אשה כשהוא חרש ברמיזה שאין קידושיו קידושין גמורים מן התורה כשם שהוא כונס ברמיזה כך מוציא ברמיזה ובפ\"ד מה' אישות כתב חרש שנשא פקחת וכן חרשת שנישאת לפיקח אין קידושיהן גמורין מן התורה אלא מד\"ס ע\"כ והשתא כיון שחרש שנשא פקחת אם רצה מגרש ברמיזה כשם שכנסה כשנפלה לפני אחיו החרש וכנסה אמאי לא יגרשנה ברמיזה אם ירצה כמו שכנסה אחיו והוא ברמיזה וכן יש לתמוה על מ\"ש שבעילתו עושה אותה א\"א גמורה והרי הוא כתב גבי חרש שנשא פקחת שאין קידושי חרש מן התורה אלא מד\"ס ואין לומר דהא דאין קידושי חרש מן התורה ה\"מ במקדש אשה אבל בא על יבמתו אפי' נפלה לו מאחיו חרש ה\"ל קידושי תורה דכיון שקידושי הראשון אינם מן התורה לא נפלה לפני אחיו מן התורה ומן התורה ה\"ל כנושא אשה בעלמא שלא היתה אשת אחיו והיאך איפשר לומר שקידושי ב' יהיו קידושין גמורין מפני שהיתה מתחלה אשת אחיו לכן נ\"ל דלא איירי הרבמ\"ם ז\"ל אלא כשנפלה לו מאחיו פיקח אבל אם נפלה לו מאחיו חרש ודאי אם רצה יגרש ברמיזה כמו שכנסה אחיו והוא וכמו שכתב רבינו אחר שכתבתי כל זה מצאתי בפרק מי שאחזו (גיטין עא:) א\"ר כהנא אמר רב חרש שיכול לדבר מתוך הכתב כותבין ונותנין גט לאשתו מיתיבי חרש לא הלכו בו אחר רמיזותיו ואחר קפיצותיו ואחר כתב ידו אלא במטלטלין אבל לא לגיטין תנאי היא דתניא ארשב\"ג בד\"א בחרש מעיקרו אבל פקח ונתחרש הוא כותב והן חותמין וחרש מעיקרו לא כשם שכנסה ברמיזה כך מוציא ברמיזה אי באשתו הכי נמי הב\"ע ביבמתו יבמתו ממאי אילימא דנפלה מאחיו חרש כשם שכניסתה ברמיזה כך יציאתה ברמיזה אלא דנפלה ליה מאחיו פיקח ואי בעית אימא לעולם דנפלה ליה מאחיו חרש וגזרה אחיו חרש אטו אחיו פיקח אי הכי אשתו נמי יבמתו ביבמתו מיחלפא אשתו באשתו לא מיחלפא ומי גזרינן חרש אטו פיקח והתנן ב' אחים חרשים נשואים ב' אחיות פקחות כו' ואם היו נכריות יכנסו ואם רצו להוציא יוציאו אלא מחוורתא כדשנינן מעיקרא ופירש\"י יכנסו ואם רצו אחר כך להוציא יוציאו דאתי גט חרש ומפקע זיקת קידושי חרש אלמא היכא דנפלה ליה מאחיו חרש מפיק ולא גזרינן אטו אחיו פיקח ע\"כ וכיון דאסיקנא דמחוורתא כדשנינן מעיקרא דשאני לן בין נפלה ליה מאחיו חרש לנפלה לו מאחיו פיקח ע\"כ צ\"ל דהרמב\"ם נמי מפליג בינייהו וכמו שכתבתי בסמוך על מ\"ש שבעילתו עושה אותה א\"א גמורה דע\"כ בנפלה ליה מאחיו פיקח דוקא הוא וכמו שנתבאר:","ומ\"ש והקטן אם רצה יוציאה בגט אם בא עליה לאחר שהגדיל בפרח יוצא דופן(מה.) תנן בן ט' שנים ויום אחד שבא על יבמתו קנאה ואינו נותן גט עד שיגדיל ובגמרא ולכשיגדיל בגט סגי לה והא תניא עשו ביאת בן ט' כמאמר בגדול מה מאמר בגדול צריך גט למאמרו וחליצה לזיקתו אף ביאת בן ט' צריך גט לביאתו וחליצה לזיקתו אמר רב ה\"ק לכשיגדיל יבעול ויתן גט ופירש\"י לכשיגדיל ויבעול והך ביאה הוי קנין גמור ואם בא לגרשה אינה צריכה חליצה דכתיב ולקחה לו לאשה כיון שלקחה נעשית כאשתו לכל דבר:","\u0003שני אחין אחד פיקח ואחד חרש נשואים לב' נשים נכריות פקחות וכו'\u0004 ב' אחים פקחים נשואים ב' נשים נכריות אחת פקחת ואחת חרשת וכו' ב' אחין אחד פיקח ואחד חרש נשואים לב' נשים אחת פקחת ואחת חרשת וכו' עד כונס ואינו מוציא לעולם הכל משנה שם בפרק חרש והם דברים מבוארים בהקדמה מה שנתבאר בסימן זה בדין החרש והחרשת:","הסומא מייבם ואינו חולץ ואם חלץ חליצתו כשרה כבר נתבאר בסימן קס\"ט דמדתניא בפרק מ\"ח (קג.) חולצת מן הסומא חליצתה כשרה למד הרמב\"ם דלכתחלה לא יחלוץ ונתן טעם לדבר משום דכתיב וירקה בפניו ואין זה רואה הרוק ומשם יש ללמוד דשפיר מייבם ואפי' לכתחלה דהא ליכא טעמא למעוטי כלל:","אשת הקטן והשוטה פטורות מן החליצ' ומן היבום בסוף האשה רבה (יבמות צו:) תנן גבי ט' שנים ויום אחד נשא אשה ומת ה\"ז פטורה ופירש\"י נשא אשה שאינה יבמתו ולו אחין הרי זו פטורה ואף ע\"ג דביאתו ביאה קידושיו אינם קידושין ואין קנין כלום עד שיביא ב' שערות ובגמ' תנינא להא דת\"ר שוטה וקטן שנשאו ומתו נשותיהן פטורות מן החליצה ומן היבום וכתב הרמב\"ם ז\"ל בפ\"ז דטעמא משום דכתיב לא תהיה אשת המת פרט לאשת שוטה וקטן שאין להם אישות כלל:","ומ\"ש אבל אשת החרש והזקנה והעקרה הרי הן כשאר כל הנשים וחולצות ומתייבמות דין אשת החרש מבואר במשנה פרק חרש ודין זקנה ועקרה מבואר בברייתא שכתבו הרי\"ף והרא\"ש ז\"ל בספ\"ק דיבמות וכתב בנ\"י דטעמא משום דהא כמה עקרות וזקנות מצינו. שנפקדו וראויות להקים שם משא\"כ באיילונית והרמב\"ם ז\"ל כתב בפ\"ו דטעמא דזקנה ועקרה מפני שהיתה להם שעת הכושר:"],["\u0003יש יבם ויבמה וכו'\u0004 לשון זה כתב הרמב\"ם ריש פ\"ו דיבום וכך הוא בברייתא כתבוה הרי\"ף והרא\"ש ספ\"ק דיבמות ת\"ר יש חולצות וכו' ור\"פ יש מותרות לבעליהן ואסורות ליבמיהן וכו' וע\"ש בתוספות דכן דרך התנא וכו': היה לאיילונית צרה מותרת להתייבם מסקנא דגמרא פ\"ק (דף י\"ב) ואפי' הכיר בה הבעל ואפילו צרת בתו איילונית וע\"ש בפירש\"י הביאו ב\"י ובתוס' (דף ח') בד\"ה תרי איסורי ויתבאר בסי' קע\"ג: ומ\"ש ודוקא איילונית ודאית וכו' איכא למידק הא פשיטא היא דמאשר תלד לא אימעיט אלא איילונית ודאי שאינה יולדת ותו דבסריס נמי ה\"ל לפרש דוקא סריס ודאי כדילפינן מלא ימחה דאימעיט סריס ששמו מחוי ודאי אבל ספק סריס שלא ניכרו הסימנים יפה חולץ ולא מייבם ונראה דרבי' ה\"ק דוקא איילונית ודאי אפי' הכיר בה כיון דאינה בת חליצה ויבום צרתה מותרת אבל ספק אפי' לא הכיר בה חולצת ולא תימא אפי' בספק נמי פטורה לגמרי דלא דמי לשאר מומין דאפילו קידשה ע\"ת וכנסה סתם דאיכא מ\"ד דבעינן גט משום דאיכא דמחיל אבל באיילונית אין אדם מוחל והוי מקח טעות ולא בעיא גט וא\"כ ג\"כ פטורה לגמרי ואפי' חליצה אינה צריכה לכך אמר רבינו דליתא אלא דוקא איילונית ודאי וכו' וכמ\"ש הרא\"ש רפ\"ק דיבמות ע\"ש התוספות והוא מ\"ש רבינו למעלה בסימן מ\"ד דספק איילונית אפי' לא הכיר בה בעיא גט ולכן חולצת ולא נפטרת לגמרי והשתא לפ\"ז פשיטא היא דבספק סריס אין סברא כלל שלא יהא חולץ דהא ודאי דצריכה חליצה דשמא אינו סריס ואסורה לשוק בלא חליצה:","\u0003ודוקא סריס חמה וכו'\u0004 במשנה פרק הערל (יבמות דף ע\"ט) אפליגו ר\"א ור\"ע והעיד ריב\"ב על אחד שהיה סריס אדם וייבמו את אשתו לקיים דברי ר\"ע ועוד דר\"א שמותי הוא ועוד מחלוקת ואח\"כ סתם משנה באותו פרק הוא וכ\"כ הפוסקים ועוד בר\"פ יש מותרות קאמר תלמודא שייר פצוע דכא והיינו כר\"ע ומ\"ש אבל סריס אדם חולצים לאשתו או מייבמין אע\"ג דר\"ע לא אמר אלא חולץ וחולצין לאשתו מ\"מ מעדות של ר\"י בן בתירה שמעינן דה\"ה מייבמין אלא דר\"ע איידי דנקט חולץ אבל יבומי לא משום דאסור לבא בקהל נקט נמי חולצין וכ\"כ התוספות (דף עט) בד\"ה א\"ה יבומי וכן מבואר בר\"פ יש מותרות דקאמר שייר פצוע דכא וכו' ועיין במ\"ש התוספות לשם:","\u0003ואלו הן סימני סריס וכו'\u0004 שם בברייתא ואיתא תו התם וי\"א כל שזרעו דוחה ופירש\"י שאינו קשור אלא צלול כמים וכן נמצא בהלכות הרי\"ף וכ\"כ הרמב\"ם בפ\"ב מאישות וכ\"כ הסמ\"ג בה' מיאון אבל רבינו נמשך אחר פסקי הרא\"ש שלא כתבו וצ\"ע למה.","\u0003ומ\"ש או שלא נתמלא זקנו אפילו הביא ב' שערות בערוה ואין לו שערות בזקנו וכו'\u0004 ט\"ס הוא וכך צריך להגיה אפי' הביא ב' שערות בזקנו ואם אין לו שערות בזקנו וכו' ה\"א לשם איתמר סימני סריס רב הונא אמר עד שיהיו כולם רבי יוחנן אמר אפי' אחד מהם היכא דהביא ב' שערות בזקן כ\"ע ל\"פ דעד שיהיו כולן כי פליגי בשלא הביא וכתב הרי\"ף והרא\"ש וקי\"ל כר\"י ודעת רבי' דבאיילונית נמי לרבי יוחנן אפילו באחד מהן דמאי שנא וסריס דנקטיה לאו דוקא ותו דבסוגיא קרי לה לאיילונית נמי סריס דה\"א התם אכל חלב מבן י\"ב ויום אחד עד בן י\"ח ונולדו בו סימני סריס וכו' ואתינוקת קאי כדמוכח התם ותו משמע ודאי ה\"ה איילונית אלא דנקט סריס משום דתני לה ברישא בברייתא ומשמע דכי היכי דפליגי ברישא בסריס ה\"נ פליגי בסיפא באיילונית ומשמע לפי זה דכי היכי דגבי איילונית סגי בסימן אחד ה\"ה בסריס סגי בשלא הביא ב' שערות בזקן ולא בעינן עוד סימן אחר וז\"ש רבינו בתחלה שערות לקוי ורך וכו' או שלא נתמלא זקנו אפי' הביא ב' שערות ואחר שכתב הסימנים חזר ומבאר החילוק שביניהם ואמר דאם אין לו שערות בזקנו כלל אפי' אין בו אלא אחד מאלו הסימנים דהיינו שאין בו כלל מן הסימנים כ\"א סימן זה דזקן בלבד חשוב סריס אבל אם יש לו וכו' וכמו שצריך לפרש דברי ר' יוחנן כך הם פי' דברי רבי' שכתב כלשונו וכ\"כ התוספות סוף (דף פ') וז\"ל כי פליגי בשלא הביא והא דקאמר ר\"י אפי' בא' מהן לא שיצטרך סימן בהדי האי אלא בהאי לחודיה חשוב סריס ואין לתמוה על הלשון דבכה\"ג אמרינן בפא\"ט וכו' ובתשובת הריב\"ש סימן תע\"ד כתב כן בשם הרא\"ש ע\"ש ומסתמא כך הוא דעת רבי' כהרא\"ש אביו אלא שלא ביאר אבל ברמב\"ם ובסמ\"ג משמע להדיא שחולקין אכל זה וס\"ל דבאיילונית בעינן כל הסימנים ובסריס באין לו ב' שערות בזקן בעינן עוד סי' אחר בהדי האי וע\"ש:","\u0003ומ\"ש אבל אם יש לו ב' שערות וכו'\u0004 כ\"כ לשם התוספות והרא\"ש ומביאו ב\"י וכתבו עוד התוספות (בדף פ') בד\"ה עד שיהא אע\"ג דבעינן שיהא לקוי ממעי אמו ויש סימנים שאין יכולין להיודע משנולד מ\"מ כיון שניכר מיד שאין עושה כיפה ושאר סימנים נכרים כל אחד כשהוא בזמנו הוכיח הראשון על האחרים שממעי אמו הוא לקוי אלא שלא היו ראויין שיהיו נכרים סמוך ללידתן עכ\"ל וכך פי' ב\"י בהא דקאמר בגמ' מנא ידעינן ומתשובת הריב\"ש בסי' תע\"ד העתיק פי' זה ומדברי התוספות למדהו:","\u0003בד\"א שע\"י הסימנים נידונים כסריס וכו'\u0004 משנה וגמרא בפ' יוצא דופן וה\"א בפ' הערל מימרא דר' אבהו (דף פ') וכתב הריב\"ש דבן עשרים והביא אח\"כ ב' שערות אפי' נולדו בו סימני סריס לאחר שהביא ב' שערות לא דיינינן ליה כסריס אלא הוא גדול מהבאת ב' שערות ואילך ומה שנולדו בו אח\"כ סימני סירוס חולי הוא כו' עכ\"ל נראה מדבריו דבלא הביא ב' שערות אפי' לא נולדו בו סימני סירוס אלא לאחר כ' ה\"ה סריס חמה מיהו כיון דבעינן שיהא לקוי ממעי אמו צ\"ל שלא היה עושה כיפה מתחלת לידתו דהשתא אעפ\"י דסימנים אחרים לא היו נכרים אלא לאחר כ' אמרינן הוכיח הראשון וכו' כדפי' בסמוך בשם התוספות אבל אם הסימנים האחרים לא נולדו בו אלא לאחר כ' וקודם כ' בידוע היה שבשרו היה מעלה הבל ומי רגליו מחמיצין וכן בשאר סימנים השתא ודאי מה שנשתנה שאין מעלה הבל ושאין מי רגליו מחמיצין שינוי זה מחמת חולי הוא ודאי ואינו סריס חמה ואפי' לא הביא ב' שערות כלל:","\u0003ומ\"ש ואם אין בהם סימנים וכו'\u0004 עד רוב שנותיהן נראה דתוך הזמן מקמי שיגיע רוב שנותיהן אם נולדו בו סימני סריס אפי' הביא אח\"כ ב' שערות ה\"ה סריס חמה והוא שהיה ניכר סימן דכיפה מיד כדפי' אבל הביא תוך הזמן ב' שערות מתחלה ואח\"כ נולדו בו סימני סריס אין זה סריס חמה אלא ה\"ה גדול מהבאת שערות ואילך והני סימני סריס תלינן בחולי כמ\"ש הר\"י בר ששת:","\u0003והרמב\"ם כתב דמשהגיע לכ' שנה פחות ל' יום וכו'\u0004 בפ\"ב מהלכות אישות וטעמו דבס\"פ יוצא דופן קאמר עולא דשנת עשרים לא בעינן מע\"ל ות\"כ ר\"י בן כיפר אומר משום ר\"א שנת כ' שיצאו ממנה ל' ה\"ה כשנת כ' לכל דבריהם ופסקו הפוסקים דהלכה כעולא דת\"כ ר\"י בן כיפר וכו' ומפרש הרמב\"ם שיצאו ממנה ל' דקאמר כלומר שאתה מוציא ל' יום ממנה שלא תהא נחשבת משנה שעברה אלא לשנה הבאה אחריה ה\"ה כשנת עשרים לכל דבריהם וטעם דין זה נראה לפי דהשלשים דבסוף שנה נחשבים לתוספ' לשנה הבא אחריה כמו גבי ערלה ושביעית כדאמרינן בפ\"ק דר\"ה לדברי האומר שלשים צריך שלשים ושלשים וכו' ומייתי לה בפרק הערל והיינו דקאמר עולא דלא בעינן מע\"ל ממש כלום אלא בפחות מל' נחשב שנת עשרים כנ\"ל דעת הרמב\"ם בזה ורבי' לעיל בסימן קנ\"ה השיג עליו וכ\"כ ה\"ה שכל המפרשים חולקים על הרמב\"ם דבי\"ט שנה ול' יום משנת כ' חשוב שנת כ' ונראה דאעפ\"י דפשט הלשון שיצאו ממנו שלשים משמע כפירושם מ\"מ לפי הטעם יותר נכונים דברי הרב רבינו משה בר מיימוני דאלו לפירושם קשה מ\"ש ל' יום הלא אפי' יום אחד בשנה חשוב שנה אלא ודאי שנה שלימה בעינן אלא דל' יום דבסוף שנת עשרים לא חשבינן ליה לשנה שעברה אלא נחשב לתוס' לשנה הבאה ועל כן הלכה למעשה יש להחמיר כדבריו אף עפ\"י שהוא יחיד בדבר זה נ\"ל ועכשיו שאין אנו בקיאין בב' שערות דשמא נשרו או שמא איכא גומות לא דיינינן דינא דסריס ואיילונית אלא חולצין לעולם וכן פסק בהגהת ש\"ע:","אנדרוגינוס כתב הרמב\"ם שדינו כסריס חמה וכן הוא לדעת רב אלפס כלומ' אע\"פ שלא כתב הרי\"ף כך בפי' מ\"מ כיון דבס\"פ הערל משמע דסובר כרבי יוסי דבריה בפני עצמו הוא וכדכתב הרא\"ש לשם ממילא דדינו כסריס שאינו מוליד אבל מ\"ש רבינו דלר\"י והרא\"ש דינו כזכר גמור לכל דבר ואף לייבם או לחלוץ הוא תימה גדולה דאעפ\"י שהוא כזכר לכל דבר מ\"מ אינו מוליד כמו סריס חמה שלא ה\"ל שעת הכושר מעולם וכתיב להקים שם והאי לאו בר הקמת שם הוא כסריס ומשום הכי להרי\"ף והרמב\"ם דהוי ספק זכר כדלעיל בסי' מ\"ד ואשתו פטורה לגמרי ואפי' חליצה אינה צריכה מספק אלא ודאי דהוי ודאי סריס חמה שלא מצינו מעולם שהוליד ותו קשה דבפ\"ק דיבמות הביא הרא\"ש התוס' בסתם דאנדרוגינוס לא חולץ ולא מייבם וכך השיב עליו ב\"י ומהרש\"ל מיהו יש ליישב דרבינו תופס לשונו של ר\"י כמשמעו שכתב שדינו כזכר גמור לכל דבר דמשמע אף ליבום ולחליצה ואעפ\"י שמעולם לא הוליד אין דינו כסריס חמה אלא כעקר מחמת חולי שזה שיש לו ג\"כ נקבות כמו חולי הוא ומה שהקשה עוד בדברי רבינו דכאן כתב ע\"ש הרא\"ש דמסקנתו כר\"י וכ\"כ לעיל בסימן מ\"ד ולעיל בסימן כ\"ב כתב דספק הוא וכ\"כ בא\"ח סימן שט\"ו כבר נתבאר היטב בי\"ד הלכות מילה בסימן רס\"ה ע\"ם:","\u0003וטומטום כתב הרמב\"ם וכו'\u0004 בס\"פ הערל פליגי בה לרבנן בנקרע ונמצא זכר מוליד כעובדא דטומטום דבירי דאיקרע........... ואוליד ז' בנין וכך פסק הרמב\"ם ור' יהודה סובר סריס ודאי הוא ופטורה לגמרי ועובדא דבירי חזור על בניו מאין הם. ור\"י בר יהודה עביד ליה ספק סריס וחולץ ואינו מייבם שלא במקום אחין ופוסל במקום אחין וכך פסק הרא\"ש דעבדינן לחומרא ונראה דכך הוא העיקר משום דקאמר מילתא מציעתא וה\"ל כרבים בכל חדא וחדא דבמ\"ש דאינה פטורה לגמרי וצריכה חליצה רבנן נמי ס\"ל הכי ובמ\"ש דאינו מייבם ר\"י נמי ס\"ל הכי וכשיטה זו כתבתי פסק הלכה בא\"ח סימן ס\"ג דקורא שמע והוא מהלך צריך לעמוד עד על לבבך ושיטה זו כתב הר\"ן בפ' המדיר וע\"ש:","פצוע דכא וכרות שפכה וסריס אדם והזקן לאו בני יבום נינהו פי' זקן כיון דכחו תשש וכשל לאו בר יבום נינהו לכתחלה מדרבנן אבל אין בו איסור ואם בעל קנה ומותר לקיימה וכך מבואר בפירש\"י בפ\"ב דיבמות ומביאו ב\"י והכי משמע מלשון רבינו מיהו בזקנה מותר לייבמה אף לכתחלה ואין שם אפי' איסור דרבנן וכך הוא בתוספתא הביאה הרי\"ף והרא\"ש ספ\"ק דיבמות וכ\"כ רבינו בסוף סימן זה וכן פסק ראבי\"ה כמ\"ש המרדכי פ' החולץ והאריך בזה ע\"ש. והא דפצוע דכא אסור לייבם אינו אלא ביבמה ישראלי' אבל גיורת דמותרת לפצוע דכא שרי נמי ליבומה ה\"א פ' הערל ופשוט הוא:","\u0003חרשת קטנה וכו'\u0004 אבל כונס ומוציא בגט אם ירצה האי מוציא בגט רצונו לומר דאותה שמתגרשת כגון חרשת וכן קטנה כשיש בה דעת לשמור גיטה כדלעיל בסימן קמ\"א כאן נמי ביבמה מוציא בגט לאחר שיבעול אותה והיא מותרת לשוק משא\"כ שוטה דאינו מוציא בגט לאחר שיבעול אותה וצריך לקיימה:","\u0003ומ\"ש וכן חש\"ו וכו'\u0004 בד\"א כשנפלה לו מאחיו פיקח וכו' ה\"א בפ' מי שאחזו וכתב ב\"י דאף דברי הרמב\"ם הסתומים צריך לפרש כך ע\"ש כי האריך:"]],["\u0010c0\u0011\u0010y0\u0011היבמה שהיא אסורה ליבם והיא מחייבי כריתות או מיתות ב\"ד אינה זקוקה ליבם ומותרת לזר בלא חליצה כיצד הרי שאחיו מאביו היה נשוי בתו או בת בתו או חמותו או אחת מכל העריות ומת ונפלה הערוה לפניו פטורה מן החליצה ומן היבום וכשם שהיא פטורה כך צרתה פטורה שאם היה נשוי עוד אחרת אף על פי שאינה ערוה על היבם פטורה כמו הערוה וכן צרת צרתה כגון שמת ראובן ולו ב' נשים ואחת מהן היא ערוה על שמעון אחיו ולו עוד אח לוי שאין אחת מהן ערוה עליו והלך לוי ויבם אותה שהיא צרת ערוה לשמעון ולו אשה אחרת ומת ונפלו שתיהן לפני שמעון שתיהן פטורות מן החליצה והיבום האחת שהיא צרת ערוה לשמעון והשנייה משום צרתה וכן עד עולם שאם נישאת צרת הצרה לאח רביעי ומת \u0010c1\u0011\u0010y1\u0011אבל אחת מכל העריות שהיא נשואה לנכרי שאינו אחיו מאביו ומת מותר לישא צרתה \u0010c2\u0011\u0010y2\u0011היבמה שהיא ספק ערוה ליבם כגון שקדש אשה בספק קידושין ואחותה נשואה לאחיו מאביו ומת אחיו ונפלה אשתו לפניו שהיא ספק אחות ארוסתו הרי זו חולצת ולא מתייבמת ומוציא אשתו בגט מספק ושתיהן אסורות יבמתו שהיא ספק אחות ארוסתו וגרושתו שהיא ספק אחות חלוצתו \u0010c3\u0011\u0010y3\u0011היתה היבמה באיסור ערוה על הבעל כגון שעבר או טעה ונשא בתו או חמותו ומת ונפלה לפני אחיו אין זו אשתו שאין קידושין תופסין לו בה ולא שייך בה לא חליצה ולא יבום ואם היה לה צרה חולצת או מתייבמת וזו שהיתה לבעל באיסור ערוה היא ליבם כמו אשה נכרית ומותר בה \u0010c4\u0011\u0010y4\u0011ראיתי כדברי הרמב\"ם שאם היתה היבמה בספק ערוה לבעל שחולצת ולא מתייבמת ויראה שהוא טעות סופר דממה נפשך תתייבם שאם לא היתה עליו ערוה הרי היא זקוקה ליבם ואם היתה עליו ערוה לא תפסי לו בה קידושין והרי היא ליבם כאשה נכרית \u0010c5\u0011\u0010y5\u0011היה לאחיו בערוה ספק קידושין או ספק גירושין כגון שזרק לה קידושין או גיטא ספק קרוב לו ספק קרוב לה או שגירשה בגט שכתב בכתב ידו ואין עליו עדים או שיש עליו עדים ואין בו זמן או שיש בו זמן ואין בו אלא עד אחד והוא כתב ידו ולו אשה אחרת ומת הצרה חולצת ולא מתייבמת \u0010c6\u0011מתה הערוה בחיי אחיו או גירשה או שהיתה הערוה קטנה ומיאנה באחיו ומת מותרת צרתה להתייבם ואפילו כנס הצרה קודם שגירשה הערוה כיון שלא היתה צרת ערוה בשעה שנפלה ליבום \u0010y6\u0011אבל לא מיאנה בו בחייו ומיאנה בו אחרי מותו צרתה חולצת ולא מתייבמת \u0010y7\u0011ספק אם מתה הערוה בחייו אם לא כגון שאחיו היה נשוי בתו ונפל הבית על שניהם ואינו יודע איזה מהם מת תחלה ולו אשה אחרת חולצת ולא מתייבמת \u0010c7\u0011\u0010y8\u0011היתה הערוה איילונית צרתה מתייבמת ולא מיבעיא אם לא הכיר בה דהוי מקח טעות שנמצא שלא היתה אשתו מעולם ואינה צרת ערוה אלא אפילו הכיר בה מתייבמת הצרה דכיון דאיילונית לאו בת יבום היא הרי היא כמי שאינה ולא נפלה הזיקה אלא על הצרה לבד \u0010c8\u0011\u0010y9\u0011יבם הצרה שהיה סבור שהערוה איילונית ואח\"כ נמצא שאינה איילונית תצא מיבמה בלא גט והולד ממזר \u0010y10\u0011ניסת הצרה לזר שהיתה סבורה שאין הערוה איילונית ואח\"כ נמצאת איילונית תצא מהבעל ומהיבם וצריכה גט מהבעל וחליצה מהיבם להתירה לזר \u0010y11\u0011ואם נתקדשה לזר מותרת ליבם כדפרישית לעיל ביבמה שנתקדשה לזר. \u0010c9\u0011\u0010y12\u0011מי \u0010c10\u0011שזנתה אשתו תחתיו בעדים וברצון ומת בלא זרע ונפלה לפני אחיו דינה כדין הערוה והיא וצרתה פטורות מן החליצה ומן היבום \u0010y13\u0011בד\"א שזנתה בודאי אבל אם ספק זנתה אם לאו היא חולצת וצרתה חולצת או מתייבמת. \u0010c11\u0011אשת אחיו שלא היה בעולמו אינה בת יבום דכתיב כי ישבו אחים יחדו שהיו להם ישיבה אחת בעולם וכיון שאינה בת יבום הרי היא כאשת אחיו שלא במקום מצוה שהיא ערוה ופוטרת צרתה כיצד \u0010y14\u0011ראובן שמת ונפלה אשתו לפני שמעון אחיו ואח\"כ נולד לוי אחיו בין אם נולד קודם שייבם שמעון אשת ראובן שמת בין אם נולד לאחר שייבמה שמעון ומת אסורה על לוי לעולם וכשם שהיא אסורה כך צרתה אסורה כגון שהיה לשמעון אשה אחרת \u0010c12\u0011כתב הרמב\"ם עשה שמעון מאמר באשת ראובן ומת קודם שכנסה הרי לוי חולץ לצרתה ולא מייבם שהיא צרת \u0010y15\u0011אשת אחיו שלא היה בעולמו במאמר שקנה קצת \u0010y16\u0011וא\"א ז\"ל כתב דאפילו מת בלא מאמר צרתה חולצת ולא מתייבמת דקי\"ל יש זיקה \u0010c13\u0011\u0010y17\u0011קטנה שהיתה נשואה לאחיו מאמו או לאחי אמו ומת ונשאה אחיו מאביו ומת ונפלה לפניו ליבום ועודנה קטנה אינה יכולה למאן לעקור נישואין הראשונים כדי שתתייבם \u0010y18\u0011וצרתה חולצת ולא מתייבמת \u0010c14\u0011ונראה שאף היא חולצת אם תמאן \u0010c15\u0011\u0010y19\u0011היה אחיו נשוי קטנה שאינה ערוה עליו ומת ומיאנה הקטנה ביבם אסורה לו \u0010c16\u0011ומותרת לזר בלא חליצה \u0010y20\u0011ודוקא היא אבל צרתה מותרת לו \u0010y21\u0011ואפילו היא מותרת לשאר האחין שלא מיאנה בהן \u0010c17\u0011היה לאחיו באשתו ספק גירושין ומת ונפלה לפניו ליבום חולצת ולא מתייבמת דשמא הוו גירושין והרי היא גרושת אחיו שהיא בכרת אבל \u0010y22\u0011אם היו לאחיו בה ספק קידושין מתייבמת שאם היו בה קידושין הרי היא זקוקה לו ואם לא היו קידושין הרי היא נכרית \u0010y23\u0011המגרש אשתו גדולה או קטנה שהשיאה אחיה והחזירה ומת ונפלה לפני יבם מותרת לו אע\"פ שהיתה אסורה לו בחיי אחיו משום גרושת אחיו משום שהיתה אשת אחיו שמיתת אחיו מזקיקין אותה לייבום ובאותה שעה לא היה לה שום איסור אבל קטנה שהשיאה אביה ונתגרשה בקטנותה ע\"י אביה והחזירה ומת בעודה קטנה אסורה ליבם שגירושיה גירושין גמורים ואין חזרתה חזרה גמורה וחולצת \u0010y24\u0011וכן הדין במגרש הפקחת ונתחרשה והחזירה ומת והיא חרשת \u0010y25\u0011ולענין צרתה כתב הראב\"ד שהיא כמותה וחולצת ולא מתייבמת ורב אלפס כתב שהיא מתייבמת \u0010y26\u0011וכ\"כ הרמב\"ם ולזה הסכים א\"א הרא\"ש ז\"ל \u0010y27\u0011החזירה כשהיא קטנה או חרשת ונתגדלה או נתפקחת אצלו ואח\"כ מת מותרת להתייבם \u0010y28\u0011אחות גרושתו היא אסורה לו מן התורה כאחות אשתו לפיכך נפלה לפניו ליבום פטורה היא וצרתה מן החליצה ומן היבום:",["היבמה שהיא אסורה ליבם והיא מחייבי כריתו' או מיתות ב\"ד אינה זקוקה ליבם ומותרת לזר בלא חליצה כיצד הרי שאחיו מאביו היה נשוי בתו או בת בתו כו' וכשם שהיא פטורה כך צרתה פטורה וכו' וכן צרת צרתה כגון שמת ולו ב' נשים ואחת מהן היא ערוה על שמעון אחיו וכו' וכן עד עולם שאם נישאת צרת הצרה לאח רביעי ומת וכו' הכל מבואר במשנה בריש יבמות ומייתינן לה בגמרא (ג:) מקראי וסוף לשון רבינו ישבו קצת קיצור ומ\"מ המכוון מדבריו הוא מבואר:","אבל אחת מכל העריות שהיא נשואה לנכרי שאינו אחיו מאביו ומת מותר לישא צרתה גם זה מבואר שם במשנה שש עריות חמורות מאלו מפני שהן נשואות לאחרים צרותיהן מותרות אמו ואשת אביו כו':","\u0003היבמה שהיא ספק ערוה ליבם כגון שקדש אשה בספק קידושין ואחותה נשואה לאחיו ומת אחיו כו'\u0004 קצת דין זה מתבאר מהא דתניא בברייתא שכתבו הרי\"ף והרא\"ש ספ\"ק דיבמות הספיקות כגון שקדש אחד מב' אחיות ואינו יודע אי זה קדש חולץ ולא מייבם ותנן בפ\"ב מי שקדש אחד מב' אחיות ואינו יודע אי זו קדש מת ולו אח אחד חולץ לשתיהם וכן מתבאר בפ\"ד אחין וכולן שהיו להן קידושין או גירושין בספק חולצות ולא מתייבמות וז\"ל הרמב\"ם ז\"ל בפ\"ו יבמה שהיא ספק ערוה על היבם או ספק ערוה על בעלה ה\"ז חולצת ולא מתייבמת לפיכך מי שקדש אשה בספק קידושין ואח\"כ מת אחיו שהיה נושא אחותה ונפלה לו ליבום שהיא ספק אחות אשתו ה\"ז חולצת ולא מתייבמת ומוציא את אשתו בגט מספק ושתיהן אסורות עליו יבמתו מפני שהיא ספק ערוה וארוסתו מפני שהיא ספק קרובת חלוצתו שהיא בשנייה כמו שביארנו עכ\"ל וכתב ה\"ה זה פשוט שספק ערוה ליבם חולצת ולא מתייבמת: ומ\"ש שאשתו אסורה עליו ג\"כ פשוט כפי מה שנתבאר והכל מתבאר בפ\"ד אחין ונלמד כיוצא בזה ממשנת שומרת יבם שקדש אחיו את אחותה שבפרק החולץ (יבמות מא.) שאמרו בסוף המשנה יוציא את אשתו בגט ואת אשת אחיו בחליצה עכ\"ל:","היתה היבמה באיסור ערוה על הבעל כגון שעבר או טעה ונשא בתו או חמותו ומת ונפלה לפני אחיו אין זו אשתו שאין קידושין תופסין לו בה ולא שייך בה לא חליצה ולא יבום ואם היה לה צרה חולצת או מתייבמת וזו שהיתה לבעל באיסור ערוה היא ליבם כמו אשה נכריה ומותר בה בפ\"ק דיבמות (י.) תני לוי אמו פעמים פוטרת צרתה ופעמים שאין פוטרת צרתה כיצד היתה אמו נשואת אביו ונישאת לאחיו מאביו ומת זו היא אמו שאין פוטרת צרתה ופירש\"י היתה אמו נשואת אביו. ונישאת לאחיו מאביו ומת לא תפסי בה קידושין שהרי אשת אב בכרת ואין קידושין תופסין בחייבי כריתות דברי הכל הילכך כשמת רשע זה לא נפלה זו לפני בנה דלאו אשת אח היא ואין פוטרת צרתה:","ומ\"ש ראיתי בדברי הרמב\"ם שאם היתה היבמה בספק ערוה שחולצת ולא מתייבמת הוא הלשון שכתבתי בסמוך יבמה שהיא ספק ערוה על היבם או ערוה על בעלה הרי זה חולצת ולא מתייבמת ומ\"ש רבינו ויראה שהוא ט\"ס דממ\"נ תתייבם כו' מבואר דקאי למ\"ש או ספק ערוה על בעלה דכיון שהיא מותרת ליבם תתייבם ממה נפשך ואפשר לדחוק ולפרש דברי הרמב\"ם דה\"ק או שהיתה ג\"כ ספק ערוה על בעלה כמו שהיא ספק ערוה על יבמה שנמצא שהיא ספק ערוה לשניהם והכי מוכח מדמסיים בה לפיכך מי שקדש אשה בספק קידושין ואח\"כ מת אחיו שהיה נושא אחותה וכו' והיינו ספק ערוה על היבם ואילו ספק ערוה על הבעל שבקה אלא ודאי כדאמרן שכשכתב שהיא ספק ערוה על הבעל כשהיא גם כן ספק ערוה על היבם מיירי וכן מה שכתב גבי היתה היבמה ערוה על בעלה ואם היה לה צרה חולצת ולא מתייבמת כשהיתה ערוה גם על היבם היתה וכדמוכח בהדיא מדמסיים בה ואם היתה זו שהיא ערוה על הבעל מותרת ליבם ורצה היבם לישא אותה ולייבם צרתה הרשות בידו משמע דעד השתא כשהיתה ערוה גם על היבם מיירי: \u0005ב\"ה ומיהו בזו מצאתי מוגה ואם היה לה צרה חולצת או מתייבמת:\u0006","היה לאחיו בערוה ספק קידושין או ספק גירושין כגון שזרק לה קידושין או גיטא ספק קרוב לה ספק קרוב לו כו' משנה ס\"פ ד' אחין (יבמות ל:) וכולן שהיו להן קידושין או גירושין מספק הרי אלו צרות חולצות ולא מתייבמות כיצד ספק קידושין זרק לה קידושיה ספק קרוב לו ספק קרוב לה זהו ספק קידושין כיצד ספק גירושין כתב בכתב ידו ואין עליו עדים יש עליו עדים ואין בו זמן יש בו זמן ואין בו אלא עד אחד זהו ספק גירושין ופירש\"י וכולן ט\"ו עריות שהיה לאחיו המת ספק חידושין או ספק גירושין הויא צרתה ספק צרת ערוה דילמא איגרשא ערוה ולגבי קידושין דילמא לא מיקדשא הרי אלו הצרות חולצות ולא מיפטרן בלא כלום דלמא לאו צרת ערוה היא ולא מתייבמות דילמא צרת ערוה היא עכ\"ל ודבר פשוט הוא שמה שכתב היה לאחיו בערוה ספק קידושין או ספק גירושין היינו לומר שהיא מותרת לבעלה וערוה על היבם וכתב רבינו ירוחם בשם הרמ\"ה לא תימא דוקא בב' כיתי עדים ואחת אומרת קרוב לה ואחת אומרת קרוב לו דהוי ספק דאורייתא אלא אפילו בכת אחת דספק דרבנן היא בעיא חליצה מתה הערוה בחיי אחיו או גירשה או שהיתה הערוה קטנה ומיאנה באחיו ומת צרתה מותרת להתייבם ואפי' כנס הצרה קודם שגירש הערוה כיון שלא היתה צרת ערוה בשעה שנפלה ליבום משנה בריש יבמות ט\"ו נשים פוטרות צרותיהן וצרות צרותיהם ומן החליצה ומן היבום עד סוף העולם ואלו הן בתו ובת בתו כו' וכולן אם מתו או מיאנו או נתגרשו צרותיהן מותרות כו' כיצד פוטרות צרותיהן כו' כיצד אם מתו הן צרותיהן מותרות היתה בתו או אחת מכל העריות האלו נשואה לאחיו ולו אשה אחרת ומתה בתו או נתגרשה ואח\"כ מת הוא צרתה מותרת ובגמרא כיצד אם מתו הן כו' ואפי' כנס ולבסוף גירש ורמינהו ג' אחים שנים מהם נשואים לשתי אחיות ואחד נשוי נכרית גירש אחד מבעלי אחיות אשתו ומת נשוי נכרית וכנסה המגרש זהו שאמרו אם מתה או מיאנו או נתגרשו צרותיהן מותרות טעמא דגירש ואח\"כ כנס אבל כנס ואח\"כ גירש לא א\"ר ירמיה תברא מי ששנה זו לא שנה זו האי תנא סבר מיתה מפלת והאי תנא סבר נישואין הראשונים מפילים רבא אמר לעולם חד תנא הוא וזו ואצ\"ל זו קתני ופסקו הרי\"ף והרא\"ש ז\"ל כרבא וכן פסק הרמב\"ם בפ\"ו:","ומ\"ש אבל אם לא מיאנה בו בחייו ומיאנה בו לאחר מותו צרתה חולצת ולא מתייבמת שם במשנה וכל שיכולה למאן ולא מיאנה צרתה חולצת ולא מתייבמת פירש\"י וכל שיכולה למאן. שהיא קטנה הערוה ויכולה למאן ולא מיאנה ומת אחיו הואיל וקידושיה אינם אלא מדרבנן (ספק) וזיקת נפילתה ספק (מדרבנן) אינה פוטרת צרתה מן החליצה ולהתייבם אסורה כדמפרש טעמא בגמרא שנראית צרת ערוה עד כאן ובגמרא ותמאן השתא ותתייבם לימא מסייע ליה לרבי אושעיא דאמר ממאנת למאמרו ואינה ממאנת לזיקתו לא צרת ערוה שאני משום דמשעת נפילה נראית כצרת בתו ופירש\"י ותמאן. הערוה השתא ותאמר אי איפשי בקידושין שקדשני אמי ואחי לבעלי המת תעקור קידושין הראשונים: ותתייבם. צרתה: משעת נפילה. שנזקקה הבת ליבם למאן בו מחמת קידושי ראשון נראים נישואים גמורים למיהוי אשת המת וצרתה צרת הבת ואי שרית ליה אתי למשרי צרת הבת דעלמא:","ספק אם הערוה מתה בחייו אם לא כגון שאחיו היו נשוי בתו ונפל הבית על שניהם ואין ידוע איזה מהם מת תחילה ולו אשה אחרת חולצת ולא מתייבמת משנה בפרק אלמנה לכ\"ג (יבמות דף סז.) נפל הבית עליו ועל בת אחיו ואין ידוע איזהו מהם מת תחילה צרתה חולצת ולא מתייבמת ופירש\"י נפל הבית עליו ועל בת אחיו. שהיא אשתו ספק הוא מת תחילה ונפלו שתיהן לפני אחיו ופוטרת צרתה משום צרת הבת ספק בת אחיו מתה ראשונה ובשעת נפילה ליבום לא הוי צרתה צרת ערוה דתנן ופולן אם מתו או מיאנו צרותיהן מותרות צרתה חולצת ולא מתייבמת:","היתה הערוה איילונית צרתה מתייבמת ולא מיבעיא אם לא הכיר בה דהוי מקח טעות שנמצא שלא היתה אשתו מעולם ואינה צרת ערוה אלא אפילו הכיר בה מתייבמת הצרה דכיון דאיילונית לאו בת ייבום היא הרי היא כמי שאינה ולא נפלה הזיקה אלא על הצרה לבד בריש יבמות גבי ט\"ו נשים שפוטרות צרותיהן תנן וכולן אם מתו או מיאנו או שנתגרשו או שנמצאו איילונית צרותיהן מותרות ובגמרא אמר רבה צרת איילונית אפילו הכיר בה ואפילו צרת בתו איילונית ואלא הא דקתני שנמצאו תני שהיו ופירש\"י הלכתא צרת איילונית מותרת ואע\"ג דהכיר בה אחיו וקיימא והוי אשתו לא מיתסרא צרתה משום צרת הבת דכי אסר רחמנא צרת ערוה במקום מצוה הוא דאסרי והא כיון דאיילונית היא דבלאו ערוה נמי לא חזיא לייבום הויא צרתה צרת ערוה שלא במקום מצוה:","יבם הצרה שהיה סבור שהערוה איילונית ואח\"כ נמצאת שאינה איילונית תצא מיבמה בלא גט והולד ממזר כ\"כ הרמב\"ם ז\"ל בפ\"ו וכתב ה\"ה זה פשוט דכיון שהיא צרת ערוה הוי ליה אשת אח שלא במקום מצוה:","ניסת הצרה לזר שהיתה סבורה שאין הערוה איילונית ואחר כך נמצאת איילונית תצא מהבעל ומהיבם וצריכה גט מהבעל וחליצה מהיבם להתירה לזר משנה פרק הזורק (גיטין דף פ'.)","\u0003ומ\"ש ואם נתקדשה לזר מותרת ליבם כדפרישית לעיל ביבמה שנתקדשה לזר:\u0004 ","מי שזנתה אשתו תחתיו בעדים וברצון ומת בלא זרע ונפלה לפני אחיו דינה כדין הערוה והיא וצרתה פטורות מן החליצה ומן היבום בפ\"ק דיבמות (דף יא) א\"ר יהודה א\"ר צרת סוטה אסורה טומאה כתיב בה כעריות ופירש\"י צרת סוטה אסורה. היה נשוי ב' נשים וזינתה האחת תחתיו ויש עדים ומת בלא בנים היא וצרתה פטורות אף מן החליצה מאי טעמא טומאה כתיב בה ונסתרה והיא נטמאה: כעריות. דכתיב אל תטמאו בכל אלה:","ומ\"ש בד\"א שזינתה בודאי אבל ספק אם זינתה אם לאו היא חולצת וצרתה חולצת או מתייבמת שם מתיב רב אשי נכנסה עמו לסתר ושהתה כדי טומאה אסורה לביתה ואסורה לאכול בתרומה ואם מת חולצת ולא מתייבמת וכל דינים אלו מבוארים בדברי הרמב\"ם ז\"ל פ\"ו וכך הם דברי הרי\"ף ואע\"פ שהראב\"ד פסק דסוטה ודאית בעיא חליצה או היא או צרתה משום דאילו איתיה לבעל לא בעיא גיטא השתא נמי בעיא חליצה וצרתה כמוה כבר סתר הרא\"ש דבריו וכתב דדוקא גבי ספק הוא דאיתמר הכי בפ\"ק דסוטה (ה:) והראב\"ד לא עלה בלבו לחלק בין סוטה ודאי לסוטה ספק ולסברתו פליגי סוגיא דסוטה אסוגיא דשמעתק ופסק הלכה כסוגיא דסוטה לחומרא אבל לפי מה שחלקת בין סוטה ודאי ובין סוטה ספק אין אנו צריכים לכל זה ולא פליגי אהדדי עכ\"ל:","ראובן שהמירה אשתו ונישאת לעכו\"ם והלך ראובן ונשא אחרת ולא גירש את המומרת ומת בלא בנים אם פטורה רחל מהחליצה ומהיבום משום צרת סוטה עיין בת\"ה סימן רי\"ט ובמרדכי ריש יבמות :","אשת אחיו שלא היה בעולמו אינה בת יבום דכתיב כי ישבו אחים יחדיו שהיה להם ישיבה אחת בעולם וכיון שאינה בת יבום הרי היא כאשת אחיו שלא במקום מצוה ופוטרת צרתה כיצד ראובן שמת ונפלה אשתו לפני שמעון אחיו ואח\"כ נולד לוי אחיו וכו' משנה ביבמות רפ\"ק (ב:) ורפ\"ב (יז:) ומ\"ש בין אם נולד קודם שייבם וכו' בין אם נולד לאחר שייבמה שמעון וכו' משנה ר\"פ ב' ואע\"ג דפליג התם ר\"ש ידוע דהלכה כת\"ק: כתב הרמב\"ם עשה שמעון מאמר באשת ראובן ומת קודם שכנסה הרי לוי חולץ לצרתה ולא מייבם בפ\"ו והוא מבואר במשנה ר\"פ ב': כיצד אשת אחיו שלא היה בעולמו ב' אחין ומת אחד מהן נולד להם אח ואח\"כ ייבם הב' את אשת אחיו ומת הראשונה יוצאה משום אשת אחיו שלא היה בעולמו והשנייה משום צרתה עשה בה מאמר ומת שנייה חולצת ולא מתייבמת ופירש\"י עשה בה זה שמת מאמר ולא הספיק לכונסה עד שמת שנייה חולצת ולא מיפטרא משום צרת ערוה דלאו צרתה ממש היא ולא מתייבמת דמאמר קונה במקצת והויא צרת ערוה במקצת מדרבנן.","\u0003ומ\"ש בשם הרא\"ש דאפי' מת בלא מאמר צרתה חולצת ולא מתייבמת וכו'\u0004 שם א\"ר יהודה אמר שמואל שומרת יבם שמתה אסור באמה אלמא קסבר יש זיקה וכ' הרא\"ש וכן הלכתא ואע\"ג דרב פליג עליה ואמר שומרת יבם שמתה מותר באמה דאין זיקה וקי\"ל הלכתא כרב באיסורי בהא קי\"ל כשמואל דאמוראי בתראי שקלי וטרי לתרוצי אליבא דמאן דאמר יש זיקה דפריך בשמעתין ממתניתין עשה בה מאמר ומת שנייה חולצת ולא מתייבמת טעמא דעבד בה מאמר הא לא עבד בה מאמר שנייה יבומי נמי מייבמה ואי אמרת יש זיקה ה\"ל צרת אשת אחיו שלא היה בעולמו בזיקה אמר רבה ה\"ה אע\"ג דלא עבד בה מאמר מיחלץ חלצה יבומי לא מייבמה והא דקתני מאמר לאפוקי מדבית שמאי דאמרי מאמר קונה קנין גמור ע\"כ וה\"ה כתב בפ\"ו בבבת היתה היבמה אסורה על יבמה איסור לאו או איסור עשה כולי יש לדקדק למה לא ביאר רבינו שאפי' בלא מאמר צרתה חולצת ולא מתייבמת דמאמר דקתני מתניתין לאפוקי מדבית שמאי [מדר\"ש] היא וכדאיתא בגמרא ואנן קי\"ל יש זיקה ואפילו בלא מאמר ולא נזכר זה בהל' וגם רבינו לא כתב זה אבל הרשב\"א ז\"ל כ\"כ ומבואר הוא בגמרא עכ\"ל. ודברים אלו אינם ענין לבבא זו שנכתבו עליה בספרים שלנו אלא ודאי על מ\"ש הרמב\"ם בבית דין אשת אחיו שלא היה בעולמו עשה שמעון מאמר באשת ראובן ומת קודם שכנסה הרי לוי חולץ לצרתה ולא מייבם כתב ה\"ה דברים אלו ומה שהעיד ה\"ה שלא נזכר זה בהלכות אני אומר דאשתמיטתיה להרב המגיד דברי ההלכות בפרק ד' אחין אמתני' דג' אחים ב' מהם נשואים ב' אחיות ואחד נשוי נכרית וכו' עשה בה מאמר ומת נכרית חולצת ולא מתייבמת שכתב עליה וה\"ה אע\"ג דלא עשה בה מאמר ומת נכרית מיחלץ חלצה יבומי לא מייבמה דהויא אחות אשה בזיקה והא דקתני מאמר לאפוקי מדבית שמאי דאמרי מאמר קונה קנין גמור ואפילו חליצה נמי לא תיבעי קמ\"ל דצריכה חליצה עכ\"ל ומשם נלמוד לכחן לדעת הרי\"ף וכן נ\"ל שהרמב\"ם העתיק פה לישנא דמתני' דקתני עשה בה מאמר כו' ואין ה\"נ דבלא מאמר נמי חולצת משום דהוה ליה צרת ערוה בזיקה ולא חשש לבאר זה כאן לפי שסמך על מ\"ש גבי ג' אחים ב' מהם נשואים שתי אחיות ואחד מהם נשוי נכרית כו' ולא עוד אלא אפילו גירש אחד מבעלי אחיות את אשתו אחר שמת הנשוי נכרית ומת המגרש הרי נכרית חולצת ולא מתייבמת הואיל ונעשית צרת אחות אשתו בזיקה שעה אחת כו' שהרי ביאר שם דצרת ערוה בזיקה אסורה ומינה נשמע לכל אינך:","קטנה שהיתה נשואה לאחיו מאמו או לאחי אמו ומת ונשאה אחיו מאביו ומת ונפלה לפניו לייבום כו' בפרק ב\"ש (יבמות דף קח: ) הרי שהיתה אשת אחי אמו שהיא שנייה לו ונשאה אחיו מאביו ומת מהו שתמאן השתא ותעקרינהו לנישואין קמאי ותתייבם צרתה יש מיאון לאחר מיתה במקום מצוה או לא שכרו ב' בני אדם בת' זוז ובאו ושאלו את ר\"ע בבית האסורין ואסר את רבי יהודה בנציבין ואסר וכתב הרא\"ש פירוש אע\"ג דקי\"ל דיש מיאון לאחר מיתה הכא בשנייה לא דהא בתו לא ממאנת לאחר מיתה ותתייבם צרתה משום דרמי בר יחזקאל דאמר כיון דבשעת נפילה נראית כצרת ערוה אסורה ה\"נ אי שרית להאי שנייה למאן לאחר מיתה אתי למשרי צרת בתו עכ\"ל:","\u0003ומ\"ש וצרתה חולצת ולא מתייבמת שאפילו היא חולצת פשוט הוא:\u0004 ","\u0003היה אחיו נשוי קטנה שאינה ערוה עליו ומת ומיאנה הקטנה ביבם אסורה לו כו'\u0004 בר\"פ ב\"ש (יבמות דף קז:) א\"ר מיאנה בזה אסורה לזה מידי דהוה אבעלת גט בעלת גט כיון דאיתסרא לחד לא איתסרא לכולהו ושמואל אמר מיאנה בזה מותרת לזה ולא דמיא לבעלת הגט בעלת גט הוא דקעביד בה הכא איהי קעבדא ביה דאמרה לא רעינא בך ולא צבינא בך בך הוא דלא רעינא הא בחברך רעינא: ופירש\"י מיאנה בזה אסורה לזה. מיאנה יבמה באחד מן האחין יבמין אסורה לכולם ופסקו הרי\"ף והרא\"ש הלכה כשמואל משום דקאי רבי יוחנן כוותיה: ומ\"ש רבי' אסורה לו טעמא משום דמדמי לה לבעלת הגט לגבי ההוא דמיאנה ביה. ומ\"ש ומותרת לזר בלא חליצה היינו בדליכא אחין אחריני דאילו איכא אחריני אע\"ג דמיאנה בזיקתו של זה הרי לא מיאנה בזיקת דאחרים:","ומ\"ש ודוקא היא אבל צרתה מותרת לו זה פשוט דהא אפילו נתן גט לזו לא נאסר צרתה:","ומ\"ש ואפילו היא מותרת לשאר האחין שלא מיאנה בהן כבר נתבאר דפלוגתא דרב ושמואל הוא והילכתא כשמואל וז\"ל הרא\"ש והרי\"ף ז\"ל בפ\"ח אהא דכי אתא רבין א\"ר יוחנן אחת צרת ממאנת פי' ממאנת ביבם ואחת צרת איילונית ואחת צרת מחזיר גרושתו משנישאת כולן מותרות ודוקא צרותיהן אבל אינהו גופייהו בדליכא בהדייהו צרות כל חדא מינייהו אית לה דינא באנפי נפשי וכו' כמו שאכתוב בסי' קע\"ד:","\u0003היה לאחיו באשתו ספק גירושין ומת ונפלה לפניו ליבום חולצת ולא מתייבמת דשמא הוו גירושין וכו'\u0004 אבל אם היו לאחיו בה ספק קידושין מתייבמת כו'.","המגרש אשתו גדולה או קטנה שהשיאה אחיה והחזירה ומת ונפלה לפני יבם מותרת לו משנה בפרק ב\"ש (יבמות ד' קח:) המגרש את האשה והחזירה מותרת ליבם ר\"א אוסר המגרש את היתומה והחזירה מותרת ליבם ר\"א אוסר וידוע דהלכה כת\"ק. ומ\"ש אבל קטנה שהשיאה אביה ונתגרשה בקטנותה ע\"י אביה והחזירה ומת בעודה קטנה אסורה ליבם כו' שם משנה קטנה שהשיאה אביה ונתגרשה כיתומה בחיי האב והחזירה דברי הכל שאסורה ליבם ופירש\"י והחזירה בקטנותה אסורה ליבם אם מת בקטנותה ואפי' לרבנן דגירושיה גירושין גמורים ואין חזרתה חזרה גמורי דקידושי קטנה אינה כלום הואיל ופקע זכות אב והיא אין לה יד והו\"ל כגרושה ועומדת:","ומ\"ש וכן הדין במגרש הפקחת ונתחרשה והחזירה ומת והיא חרשת כן כתב הרמב\"ם ז\"ל בפ\"ז וכתב ה\"ה זה פשוט לפי מה שנתבאר שנישואי החרשת שוין לנישואי הקטנה וכולן מדבריהם ויש סמך לזה בירוש' פרק חרש פשוט הוא עכ\"ל:","\u0003ומ\"ש ולענין צרתה וכתב הראב\"ד שהיא כמותה כו'\u0004 שם (דף קט:) בעא מיניה רבא מרב נחמן צרתה מהו ומסקנא צרתה או חולצת או מתייבמת וכתב הרא\"ש תמוה לי למה כתב רב אלפס בעיא זו שהיא אליבא דר\"א דלא כהלכתא ויש הלכות רב אלפס שכתוב בהן וה\"ה לצרתה של יתומה בחיי האב לרבנן והשיב עליו הראב\"ד ז\"ל הא מילתא לא מיחוורא שפיר משום דלר\"א גופיה הא לא שרית לצרה אלא משום דהיא גופיה גזירה ואנן ניקום ונגזור גזירה לגזירה אבל יתומה בחיי האב בין לר' אליעזר בין לרבנן ערוה היא מן התורה הילכך צרתה נמי צרת ערוה הן ושתיהן חולצות ולא מתייבמות ולכאורה היה נראה כדבריו דהיינו דתנן בפ\"ק וכל שיכולה למאן ולא מיאנה צרתה חולצת ולא מתייבמת ה\"נ צרתה של ערוה קטנה היא ומיהו נוכל לקיים דברי רב אלפס ז\"ל דשאני ערוה זו שיש לה היתר לעצמה אם גדלה אצלו הילכך לר\"א דגזר אפילו בגדולה דעלמא אטו יתומה בחיי האב שמא יטעה אדם לומר דקידושי קטנה כלום כ\"ש דגזר בצרה דידיה אבל לרבנן דלא גזרו אפילו בדידה אם גדלה אצלו כ\"ש דבצרתה לא גזרו ומתייבמת וכ\"כ הרמב\"ן ז\"ל ופלוגתא היא בירושלמי עכ\"ל:","ומ\"ש רבינו בשם הרמב\"ם ז\"ל שמתייבמת בפ\"ז וכתב ה\"ה בהלכות הביאו בעיא דצרתה ומאי דאסיקו בה או חולצת או מתייבמת לומר דכי היכי דלרבי אליעזר בגדולה צרתה מתייבמת ה\"ה קטנה לרבנן וזהו דעת רבינו ויש חולקין בזה וכבר הכריע הרמב\"ן כדברי ההלכות וזהו דעת הרשב\"א ז\"ל עכ\"ל:","החזירה כשהיא קטנה או חרשת ונתגדלה או נתפקחה אצלו ואח\"כ מת מותרת להתייבם שם בברייתא בגמרא מודים חכמים לרבי אליעזר בקטנה שהשיאה אביה ונתגרשה הרי היא כיתומה בחיי האב והחזירה שאסורה לייבם מפני שגירושיה גירושין גמורים ואין חזרתה חזרה גמורה בד\"א שגירשה כשהיא קטנה והחזירה כשהיא קטנה אבל גירשה כשהיא קטנה והחזירה כשהיא גדולה א\"נ החזירה כשהיא קטנה וגדלה אצלו ומת או חולצת או מתייבמת ומה שהשוה דין החרשת לדין החטנה כ\"כ הרמב\"ם בפ\"ז וכבר נתבאר בסמוך:","אחות גרושתו היא אסורה לו מן התורה כאחות אשתו לפיכך נפלה לפניו לייבום פטורה היא וצרתה מן החליצה ומן הייבום משנה בפרק החולץ (יבמות מא.) המגרש את אשתו ונשא אחיו את אחותה ומת הרי זו פטורה ופירש\"י פטורה. אף מן החליצה משום אחות אשה הואיל ואשתו קיימת ואחות גרושה מד\"ת דכתיב עליה בחייה כל שבחייה:"],["\u0003היבמה שהיא אסורה ליבם וכו'\u0004 משנה ריש יבמות והתוס' והרא\"ש כתבו טעם למה נדה יבמה אינה פוטרת וע\"ש:","\u0003ומ\"ש אבל אחד מכל העריות שהיא נשואה לנכרי וכו'\u0004 משנה שם שש עריות חמורות מאלו וחומר שלהן הוא שאינן יכולים להנשא לאחיו מאביו אלא לאחרים ואם מתו בעליהן שהן נכרים אצל זה צרותיהן מותרות להנשא לו וסובר רבי' דלאו דוקא שש עריות דה\"ה נמי כל העריות וכדקאמר התם ומאי איריא דתנא פוטרות ליתני אוסרות ומשני כיון דבמקום מצוה הוא דאסורה צרה ושלא במקום מצוה שריא מ\"ה תנא פוטרות אלא נקט שש עריות לאשמעינן דכיון שהם חמורות שאינן יכולין להנשא לאחין מן האב הלכך אם עבר אחיו ונשא אחת מהם צרותיהן מותרות כמו אילו היו נשואות לנכרים דכיון דלא תפסי בה קידושין אין זו אשתו כמ\"ש בסמוך:","\u0003היבמה שהיא ספק ערוה וכו'\u0004 כך פסק הרמב\"ם בפ\"ו וצ\"ע מאין הוציא דספק אחות חלוצתו אסורה דאי מהברייתא שהביא הרי\"ף והרא\"ש בספ\"ק דיבמות הספיקות כגון שקידש אחת מב' אחיות ואינו ידוע איזה מהן קידש חולצין ולא מייבמין התם כל אחת שמא אינה יבמתו אלא אחות זקוקתו שהיא אחות אשתו והכי תנן בפ\"ב מי שקידש אחת מב' אחיות וכו' וכן בפ\"ד אחין וכולן שהיה להן קידושין וכו' דספק איסורא הוא וכן בפ' החולץ תנן שומרת יבם שקידש אחיו את אחותה מת יבם יוציא את אשתו בגט ואשת אחיו בחליצה התם אשתו היא אחות חלוצה ודאית אבל ספק א\"ח כיון דאיסורא דרבנן אימא לך דשריא ובפ' החולץ במרדכי כתב דשאל רבינו שלמה מדרוי\"ש לרבי' ברוך על ספק אחות חלוצה ודעתו היה להתיר והשיב ר\"ב דשאל את פי רבותיו ואמרו שאין רשאין להתיר לעשות מעשה משמע דמן ההלכה אין ראיה לאיסור ואפשר לומר דמדתנן בפ\"ב דיבמות קדמו וכנסו אין מוציאין מידם ותנא שילא ואפי' שניהם כהנים מ\"ט חלוצה דרבנן וספק חלוצה לא גזרו בהו רבנן משמע דוקא בקדמו וכנסו אבל לכתחלה אסור לכנוס דאל\"כ לאשמעינן רבותא דאפילו לכתחלה שריא ולמדנו מכאן דה\"ה לאחות חלוצה נמי אסור לכתחלה אפי' בספק ומיהו אם קדם וכנס אין מוציאין כנ\"ל:","\u0003היתה היבמה באיסור ערוה על הבעל וכו'\u0004 ומותר בה כך פסק הרמב\"ם בפ\"ו אלא שחילק דאם היתה היבמה באיסור ערוה על בעלה בלבד ומותרת ליבם צרתה מותרת להתייבם וזו שהיתה ערוה על בעלה היא ליבם כמו אשה נכרית ומותר בה אלא דבאחותו מאביו שהיא ערוה גם על היבם ס\"ל להרמב\"ם דצרתה חולצת ולא מתייבמת ונראה דטעמו דמפרש הך דשש עריות וכו' דלא כפירש\"י אלא ה\"פ ו' עריות חמורות מאלו שאינן יכולין לינשא לאחין שלא בעבירה ומפני שהן נשואות לאחרים צרותיהן מותרות אבל אם היו נשואות לאחין צרותיהן אסורות ואע\"ג דד\"ת צרותיהן שריין אפ\"ה אסור מדרבנן כיון דהוא צרת ערוה גזירה אטו צרת ערוה דעלמא גם הרי\"ף גורס במשנה ומפני בוי\"ו משמע להדיא כדפי' והא דקאמר התם תני לוי אמו פעמים פוטרת צרתה ופעמים אינה פוטרת כיצד היתה אמו נשואת אביו ונישאת לאחיו מאביו ומת זו היא שאינה פוטרת צרתה לאו למימרא דמותרת להתייבם אלא אין פוטרת קאמר ובעיא חליצה ואע\"פ דבפי' המשניות במשנה דשש עריות פי' להדיא דאפילו נשואות לאחין צרותיהן מותרות בחיבורו חזר בו:","\u0003ראיתי בדברי הרמב\"ם שאם היתה היבמה וכו'\u0004 ויראה שהוא ט\"ס וכו' ותימה דה\"ל לרבינו להקשות עליו מדברי עצמו דכיון דכתב דביבמה שהיתה ערוה על בעלה בלבד יכול לישא אותה ולייבם צרתה א\"כ למה יגרע ספק ערוה שלא לישא אותה בלחוד אבל לפעד\"נ שכל דברי הרמב\"ם חוזרין על בבא זו שכתב דיכול לישא את שניהם דהיינו לישא אותה ולייבם את צרתה דאין זה אלא ביבמה שהיא ערוה על בעלה בלבד ומותרת לייבם אבל אם לא היתה רק איסור עשה או לאו על בעלה ומותרת לייבם ה\"ז מותרת לייבם היא בלבד מותרת אבל צרתה אסורה דבית אחד הוא בונה וה\"ה אם מייבם צרתה אסורה היא חוץ ממחזיר גרושתו משנישאת ומת דאע\"פ שאינה אלא איסור לאו היא עצמה חולצת ולא מתייבמת ואז צרתה אסורה ואם רצה מייבם את צרתה והיא אסורה והכי אסיקנא בפ\"ק (ד' י\"ב) וע\"ז אמר וכן יבמה שהיא ספק ערוה על היבם דאז בין היא בין צרתה חולצת ולא מתייבמת דשמא פוגע בערוה או בצרתה דצרת ערוה גם כן ערוה עליו משום אשת אחיו שהרי אין לו עליה זיקה וכשהיא ספק ערוה על בעלה ה\"ז ג\"כ חולצת ולא מתייבמת בצד אחד כלומר דכשרוצה לישא אותה ממ\"נ אז אינו מייבם צרתה דשמא לא היתה היא ערוה על בעלה ונמצא עובר על בית אחד הוא בונה אבל צרתה צריכה חליצה דשמא היתה היא ערוה על בעלה וצרתה זקוקה אבל לא משכחת דלישא אותה ולייבם גם את צרתה אלא היכא דהיבמה היא ודאי ערוה על בעלה לבד ומותרת לייבם כללו של דבר דהא דכתב הרב דאם היבמה היתה ספק ערוה לבעלה דחולצת ולא מתייבמת אצרתה קאמר דחולצת עכ\"פ אע\"פ שכבר נשא היבם ספק ערוה דשמא היתה ערוה לבעלה ועדיין צרתה זקוקה כנ\"ל לפרש דברי הרמב\"ם ברווחא ודלא כמו שנדחק ב\"י:","\u0003היה לאחיו בערוה ספק קידושין וכו'\u0004 פי' יבמה שהיא מותרת לבעלה וערוה על היבם והיה לאחיו בה ספק קידושין והוא משנה פ' ד' אחין ודקדק רבינו ע\"פ מסקנת הגמרא דבגירושין נמי זרק לה גיטה ספק קרוב לו וכו' ספק גירושין הוא אבל אין עליו זמן אינו אלא ספק בגירושין אבל כשר הוא בקידושין וכתב הרא\"ש דה\"ה כתב בכתב ידו ואין עליו עדים דפסול דידיה משום זמן הוא כשר בקידושין ודלא כר\"י בתוספות דמספקא לוה ולפ\"ז הא דפסקינן בפרק בתרא דגיטין דיש זמן ואין בו אלא ע\"א כתב ידו וע\"א שנינו פשיטא דכשר הוא בקידושין דהא בכתב ידו אפי' ליכא עדים כלל כשר ולכן כתב רבינו או שגירשה בגט שכתב בכתב ידו וכו' וכתב ג\"כ אצל עד אחד והוא כתב ידו וכדלעיל סוף סימן ק\"ל דהני תלתא לא הוי ספיקא אלא בגירושין אבל בקידושין הוי ודאי קידושין:","\u0003מתה הערוה וכו'\u0004 עד ומיאנה בו אחרי מותו צרתה חולצת ולא מתייבמת פי' רש\"י שתאמרי אי אפשי בקידושין שקדשוני אמי ואחי לבעלי המת ותעקור קידושין הראשונים עכ\"ל משמע להדיא דאם מיאנה ביבם בלבד שאמרה אי אפשי ביבם אינו כלום עד שתאמר אי אפשי בקידושין הראשונים וכו' וז\"ש רבינו ומיאנה בו אחרי מותו פי' בו בבעלה ודו\"ק:","\u0003היתה הערוה איילונית צרתה מתייבמת וכו'\u0004 משנה ריש יבמות וכרבא (ד' י\"ב) דאפי' הכיר בה דלא כרב אסי וקשיא לי דהרא\"ש ריש יבמות כתב ע\"ש התוס' דבאיילונית כיון דלא בעיא גט אפי' מדרבנן הלכך צרתה מותרת שזה למאי דקי\"ל כרבא דאפי' הכיר בה צרתה מותרת דבהכיר בה ודאי בעיא גט וצ\"ל דלא כתב הרא\"ש כן בשם התוס' אלא לרב אסי דאין צרתה מותרת אלא בלא הכיר בה דהיינו טעמא דקידושי טעות נינהו ולא בעי' גט דלדידיה ליכא לפרש כמ\"ש רש\"י בשם בה\"ג (דף י\"ב) אליבא דרבא דכיון דאיילונית בלאו ערוה לא חזיא לייבומי הויא צרתה צרת ערוה שלא במקום מצוה דא\"כ אפילו הכיר בה נמי מתייבמת לפי טעם זה אלא לרב אסי הוא טעמא דבלא הכיר בה לא בעיא גט דלאו אשתו היא וכיון דלרב אסי לא בעיא גט ה\"ה לרבא דבהא לא פליגי אבל לגבי צרתה דמתייבמת קי\"ל כרבא דאפי' הכיר בה ובעיא גט נמי מתייבמת מטעם שפי' בה\"ג ודו\"ק ונראה דגם הרמב\"ם פוסק דאפי' הכיר בה אעפ\"י שאינו מפורש כך בדבריו דמדכתב בפ\"ו (הלכה כ\"א) טעמו של בה\"ג וכמ\"ש רבינו דאי הוה ס\"ל לחלק בין הכיר בה ללא הכיר בה הוי קידושי טעות ולא בעי' גט וק\"ל:","\u0003יבם הצרה וכו'\u0004 כ\"כ הרב רבינו משה בר מיימוני בפ\"ו. ניסת הצרה לזר כו' משנה בהזורק כל העריות שאמרו צרותיהם מותרות הלכו הצרות האלו ונישאו ונמצאו אלו איילונית תצא מזה ומזה וכל הדרכים האלו בה זו דר\"מ שאמר משום ר\"ע אבל חכ\"א אין ממזר מיבמה וכיון דקי\"ל כחכמים דאין ממזר מחייבי לאוין וקידושין תופסין בה לפיכך צריכה גט מהבעל וחליצה מהיבם להתירה לזר דחכמים נמי מודו דתצא מזה ומזה אלא דאין הולד ממזר ומדר\"מ לגבי יבמה לשוק דהוי ממזר מחייבי לאוין נשמע לחכמים בייבם הצרה כשנמצא אח\"כ שהערוה אינה איילונית דהו\"ל הצרה אשת אח שלא במקום מצוה דהולד ממזר וכל הדרכים האלו בה דבהא לא פליגי ומכאן למד הרמב\"ם ורבינו הדין הראשון שכתב כאן ייבם הצרה שהיה סבור וכו' ומשמע ג\"כ מלשון המשנה מדתני בה ונמצאו אלו איילונית שאפי' לא הכיר בה שהיא איילונית אלא עכשיו לא אמרינן מאי הו\"ל למיעבד משום דאיבעי ליה אמתוני וכדאיתא בפרק האשה רבה ודברי הכל הוא וז\"ל התוס' בפ\"ק (דף י\"ב) בד\"ה תני שהיו דלרבא אע\"פ דלא הכיר בה עד אחר מיתת הבעל דסד\"א דאסורה משום דבשעת נפילה נראית כצרת ערוה כדאמרי' בצרת ממאנת יש לחלק דהתם מיחסרא מיאון והכא לא מיחסרא מידי א\"כ ממאנת אין לה קול ובשעת מיאון נראה כצרת ערוה אבל איילונית יש לה קול וידוע שלא היתה צרת ערוה עכ\"ל ועיין לעיל סוף סי' י\"ז עוד מבואר במשנה דה\"ה בלא ערוה אלא בכונס את יבמתו והלכה צרתה ונישאת לאחר ונמצאת זו שנתייבמה איילונית ואין יבומה יבומין וצרתה לא נפטרה מזיקתה ונישאת לשוק בלא חליצה דתצא מזה ומזה ואין הולד ממזר:","\u0003מי שזינתה אשתו וכו'\u0004 כ\"כ הרמב\"ם בפ\"ו וכך הם דברי הרי\"ף והרא\"ש בפ' קמא דיבמות דסוטה ודאית הויא כערוה והיא וצרתה פטורה לגמרי אבל מתני' דריש סוטה דחולצת ולא מתייבמת מיירי בספק סוטה עצמה ומפרש התם רבא דק\"ו הוא אם נאסרה לבעלה שהיתה מותרת לו ליבם שהיתה אסורה לו לא כ\"ש וכתבו התוס' בפ\"ק דיבמות סוף (דף י\"א) דהאי ק\"ו לא אלים אלא לאוסרה לייבום דלפוטרה מן החליצה לא מהני אלים ק\"ו אפי' להיא גופה ומשמע דלצרתה לא אלים ק\"ו לא סרה ליבום מדקא מיבעיא במחזיר גרושתו משניסת אי אלים ק\"ו למדחי צרה לאוסרה לייבום או לא ואסיקנא דצרת מחזיר גרושה שריא ליבומי אלמא דלא אלים האי ק\"ו לגבי צרה אפי' לענין ייבום זאת היא דעת הרמב\"ם דמתיר צרת ספק סוטה להתייבם וכדכתב רבינו ודלא כהראב\"ד דאינו מחלק בין ספק לודאי דאידי ואידי חולצת ולא מתייבמת מיהו בת\"ה סימן רי\"ט כתב שכך הוא דעת מהר\"ם דצרת סוטה בעיא חליצה ע\"ש גם מהרש\"ל כתב דאפי' בודאי סוטה היא או צרתה חולצת דלא שייך לומר הכא חליצה פסולה וכמ\"ש התוס' (בדף י\"א) בד\"ה או היא עוד נלפע\"ד מדאמרינן ריש יבמות מניינא דרישא ודסיפא למעוטי דרב דאמר צרת סוטה אסורה ודרב אסי דאמר צרת איילונית אסורה וכיון דסתמא דתלמודא קאמר הכי וקי\"ל דלא כרב אסי ה\"נ קי\"ל דלא כרב ובמרדכי כתב ג\"כ מספקא לן אי הלכה כרב בצרת סוטה ולהלכה למעשה נקטינן כמאן דמחמיר:","ומ\"ש שזינתה תחתיו בעדים וברצון היינו משום דאם היה אונס כגון שהשיאוה ב\"ד ע\"פ ע\"א ואח\"כ בא בעלה ומת ואינה אלא סוטה דרבנן אף לרבנן דפליגי אדר\"ש בריש האשה רבה דחולצת ולא מתייבמת ל\"פ אלא אדידה אבל בצרתה מודו דמתייבמת וכדין ספק סוטה דאורייתא וכ\"פ רש\"י בסוגיא דצרת סוטה (דף י\"א) וז\"ל נ\"י צרת סוטה אסורה ברצון מיירי ובאשת ישראל אבל באשת כהן היכא דנאנסה צ\"ע אי אסרינן לה ואם מת חולצת עכ\"ל אבל בפרק הע\"י משמע דבין ללישנא קמא בין ללישנא בתרא אשת כהן שנאנסה בעלה לוקה עליו משום טומאה דכתיב בה אחרי אשר הוטמאה ע\"ש (בדף נ\"ב) וכן פסק רבינו לעיל בסי' ו' ואיכא למידק אמאי מיקל תלמודא בספק סוטה טפי משאר ספק דאורייתא וי\"ל דכיון דבסוטה ודאי כתב טומאה בלשון לאו כי היכי דכתיב בעריות אבל בספק סוטה כתיב טומאה דידה בלשון עשה אף ע\"ג דאסירא משום ספק טומאה גלי לן קרא דלא חשיב טומאה דידה למיהוי אפי' כספק ערוה וכ\"כ הרא\"ש בתחילת פרק קמא דיבמות והאריך ע\"ש:","\u0003אשת אחיו שלא היה בעולמו וכו'\u0004 בין אם נולד קודם שייבם שמעון וכו' משנה רפ\"ק ורפ\"ב פליגי בה ת\"ק ור\"ש והלכה כרבנן דאפי' ייבם ואח\"כ נולד דכי אשכחה בהיתירא אשכחה שלא נאסרה עליו שעה אחת שהרי לא נזקקה מכח הראשון שלא היה בעולמו כלום אלא נזקקה מכח השני שהיה עמו בעולמו ואפ\"ה אסורה לו וז\"ל רש\"י רפ\"ק כגון ראובן שמת בלא בנים ונולד לו אח לאחר מיתה ועמד שמעון וייבם אשתו וכו' עכ\"ל ונראה מדלא כתב רש\"י ואח\"כ עמד שמעון וייבם וכו' כלשון המשנה ר\"פ שני אלא כתב סתם ועמד שמעון וייבם אשתו אלמא דרצונו לומר בין שעמד וייבם לאחר שנולד בין שכבר עמד וייבם מקמי שנולד לוי בכל ענין אסורה לו וכדמסיק ר\"פ שני אבל בנ\"י רפ\"ק במ\"ש בשם המפרשים מבואר שהבינו מפירש\"י דפי' בנולד ואח\"כ ייבם והוקשה להם למה לא פי' על פי האמת דאפי' ייבם ואח\"כ נולד נמי אסורה לת\"ק ונדחקו ליישב זה אבל לפע\"ד האמת הוא כדפי' ואין כאן שום התחלה לקושיא:","\u0003כתב הרמב\"ם עשה שמעון מאמר וכו'\u0004 טעם מחלוקתם בסוגיא ר\"פ שני ומפורש בב\"י ע\"ש ועיין לעיל בסימן קע\"ה:","\u0003קטנה שהיתה נשואה לאחיו מאמו וכו'\u0004 בפ' ב\"ש סוף (יבמות דף ק\"ח) הרי שהיתה אשת אחי אמו שהיא שנייה לו ונשאה אחיו מאביו ומת מהו שתמאן השתא ותעקרינהו לנישואין קמאי ותתייבם יש מיאון לאחר מיתה במקום מצוה או לא ואסיקנא דאסור כך הוא גירסת רש\"י ופי' אבל באישות דערוה כגון אשת אחיו מאמו קטנה ומת ונשאה אחיו מאביו פשיטא לן דלא אתא מיאון דלאחר מיתה למשרי ערוה ליבומי עכ\"ל וכך הוא גירסת הרי\"ף והרא\"ש וכך כתב רבינו אינה יכולה למאן כדי שתתייבם אלמא דמפרש דבהיא גופה קמיבעיא לן אם יכולה למאן כדי שתתייבם ואסורה אבל התוס' גורסי' ותתייבם צרתה וגרסינן נמי יש מיאון אחר מיתה באחיו או לא ואסרוה וכתבו עוד דוקא באיסור שנייה קמיבעיא ליה אבל באיסור ערוה דאורייתא תנן כל שיכולה למאן ולא מיאנה צרתה חולצת ולא מתייבמת עכ\"ל ורבינו חשש לחומרא גם לגירסת התו' דאף בצרת שנייה אסורה לייבם כשתמאן השנייה וקצת קשה לאיזה צורך כתב רבינו דין זה בערוה גופה כשהית' נשואה לאחיו מאמו דפשיטא היא כמו שפירש\"י ותוס' דאי לאורויי דאפי' בערוה דאורייתא אין צרתה פטורה לגמרי אלא חולצת כבר כתב רבינו דין זה לעיל בסוף ס\"ה. ונראה ליישב דלפי דהרי\"ף והרא\"ש כתבו לשם וז\"ל ואע\"ג דקי\"ל דיש מיאון לאחר מיתה הכא בשנייה לא דהא בתו לא ממאנת לאחר מיתה ותתייבם צרתה משום דבשעת נפילה נראית כצרת ערוה ה\"נ אי שרית להאי שנייה למאן לאחר מיתה אתו למשרי צרת בתו עכ\"ל וזאת היתה דעת רבינו שכתבה בערוה כדי למיתב טעמא דהא דאסרוה בשנייה אינו אלא כי היכי דלא ליתו למשרי נמי בערוה ולכך גזרו אף בשנייה והכי משני תלמודא התם בריש (דף ק\"ט) האי מאי למימרא פשיטא אלא הא קמ\"ל טעמא דרבי אליעזר דגזר הנך משום האי ע\"ש:","ונראה שאף הוא חולצת אם תמאן משמע דבין בערוה ובין בשנייה קאמר אם תמאן לעקור נישואין הראשונים בלבד אבל לא תמאן בנישואי אחיו מאביו א\"כ זקוקה היא לו מדרבנן מכח נשואי אחיו מאביו וצריכה חליצה מדרבנן לעקור זיקתה והיינו באם אין לה צרה דאם יש לה צרה דזיקתה דאורייתא ולא נפטרה בחליצה זו שאינה אלא מדרבנן וכיון דצרה בעיא חליצה א\"כ נפטרה גם הקטנה בחליצת צרתה ולא צריך לחליצת הקטנה אבל צרתה לעולם חולצת ולא מתייבמת בין תמאן היא בין לא תמאן:","\u0003היה אחיו נשוי קטנה שאינה ערוה עליו וכו'\u0004 בפ\"ק דיבמות (דף י\"ב) אמר שמואל צרת ממאנת אסורה ליבם גזירה משום צרת בתו ממאנת ואסיקנא דשריא הצרה ליבם דלא כשמואל אבל ממאנת גופה אסורה ליבם משום דמיאון עקר לה לזיקה וקאי עליה באשת אח ואעפ\"י דמיאון עקר לנישואין קמאי והרי היא נכרית אצלו גזרינן הואיל ולא מיאנה בראשון ומכח נישואין שלו נפלה לפניו נראית כאשת אחיו ובריש פרק ב\"ש איתא רב אמר מיאנה בזה אסורה לזה ושמואל סבר מיאנה בזה מותרת לזה ורב אסי סבר מיאנה בזה מותרת אפילו לו ופסקו הרי\"ף והרא\"ש לשם דהלכתא כשמואל דקאי ר' יוחנן כוותיה דאמר מיאנה בזה מותרת לאחין דלאחין הוא דשריא הא לדידיה אסירא:","ומ\"ש ומותרת לזר בלא חליצה שם אמר עולא אף ממאנת לזיקתו ופי' הרי\"ף והרא\"ש ולא בעיא חליצה מ\"ט נישואין קמאי קא עקרה והלכתא כעולא ומשמע דאפי' איכא אחין ומיאנה בזה מותרת לזר כיון דעקרה לנישואין קמאי אבל מלשון הרי\"ף והרא\"ש פרק קמא דיבמות לא משמע הכי שכתבו ממאנת ביבם דלית לה צרה אף על גב דלגבי יבם דמיאנה בו לאו בת חליצה וייבום נינהו לגבי אחיו של יבם שריא וחולצת או מתייבמת דאמר שמואל מיאנה בזה מותרת בזה עכ\"ל. וזהו טעמו של ב\"י שכתב לפרש הא דמותרת לזר בלא חליצה היינו בדליכא אחי אחריני ותימה דמדשמואל לא שמעינן אלא היתירא לאחין אבל לא שמעינן מיניה איסורא לזר בלא חליצה וכך מבואר מדברי הרמב\"ם פ\"י דה\"ג שכתב דמיאנה ביבם אסורה לאביו אבל לשאר קרובים מותרת לפיכך אם מיאנה באחד מן היבמין מותרת לאחין עכ\"ל וכיון דבמה שמיאנה ליבם בלבד מהני לעקור נישואין הראשונים להתירה לשאר קרובים ה\"ה דמותרת לזר מה\"ט גופיה דאל\"כ בדאיכא אחין דצריכה חליצה אף לשאר קרובים אסורה דאין לפרש דלא שרינן לקרובים אלא בדליכא שאר אחין דא\"כ הו\"ל להרמב\"ם לפרש חילוק זה כ\"ש רבינו שדרכו לפרש לא הו\"ל לכתוב בסתם דמותרת בזר בלא חליצה אלא ודאי דשריא לזר בלא חליצה ולשון הרי\"ף והרא\"ש שכתבו דחולצת אינו לומר דצריך חליצה אלא לומר דחליצתה פסלה ואינה כחליצת סריס ואיילונית דאינה כלום דהכא כיון שמותרת לאחין אע\"ג דאסורה לאביו דאלמא דאיכא מצות ייבום א\"כ שייך כאן ג\"כ חליצה ופסלה אבל לזר שריא בלא חליצה כנ\"ל ליישב דברי הרי\"ף והרא\"ש עם דברי הרמב\"ם ורבינו ומיהו לענין מעשה עדיין צריכין אנו למודעי ולעיין בה:","\u0003היה לאחיו באשתו ספק גירושין וכו'\u0004 בפרק החולץ (יבמות דף מ\"א) הספיקות חולצות ולא מתייבמות מאי ספיקות אילימא ספק קידושין אמאי לא מתייבמת תתייבם ואין בכך כלום וכתבו התו' בספק גירושין ה\"מ לאוקמי דלא מתייבמת שמא היא גרושת אחיו ע\"כ:"]],["\u0010c0\u0011\u0010y0\u0011יבמה שהיא אסורה ליבם בלאו או בעשה או באיסור שניות דרבנן היא חולצת \u0010y1\u0011וצרתה או חולצת או מתייבמת \u0010c1\u0011\u0010y2\u0011ואין חליצתה \u0010y3\u0011פוטרת צרתה אבל חליצת צרתה פוטרת אותה כדפרישית לעיל ואם עבר ובא עליה קנאה ונפטרת צרתה ומוציאה בגט היתה אסורה לבעלה באיסור לאו או עשה או איסור דרבנן ומותרת ליבם הרי היא זקוקה לו דכיון שלא \u0010c2\u0011היתה אסורה לבעלה אלא בלאו תפסי בה קידושין וכיון שמותרת ליבם יכול לייבם אותה \u0010y4\u0011חוץ ממחזיר גרושתו משניסת שאם החזיר אחיו גרושתו משניסת ומת חולצת ולא מתייבמת \u0010c3\u0011\u0010y5\u0011אחות חלוצה אסורה מדרבנן לפיכך נפלה לפני יבם חולצת ולא מתייבמת וכן צרתה אסורה מדרבנן וחולצת ולא מתייבמת \u0010c4\u0011\u0010y6\u0011מי שיש עליה זיקת שני יבמין היא וצרתה חולצות ולא מתייבמות כיצד ג' אחין \u0010c5\u0011נשואין ג' נשים נכריות ומת אחד מהם ועשה אחד מהנשארין מאמר ביבמתו ומת קודם שכנסה \u0010c6\u0011בין שיש לה צרה או אין לה צרה היא או צרתה חולצת ולא מתייבמת \u0010y7\u0011נתן לה גט ופי' שהוא למאמרו הרי בטל המאמר שעשה ואין עליה אלא זיקת יבם אחד ומתייבמת אבל אם נתן הגט סתם אסורה \u0010y8\u0011קטן שבא על יבמתו ומת חולצת ולא מתייבמת שאין ביאתו קונה קנין גמור ויש עליה זיקת שני יבמין \u0010y9\u0011מי שחציה שפחה וחציה בת חורין שנתקדשה לראובן ונשתחררה וקדשה שמעון אחיו ומתו שניהם ונפלה לפני לוי אחיהם מתייבמת לו שאינה אשת שני מתים שאם קידושי ראובן קידושין אין קידושי שמעון כלום ואם קידושי שמעון קידושין אין קידושי ראובן כלום:",["\u0003יבמה שהיא אסורה ליבם בלאו או בעשה או באיסור שניות דרבנן היא חולצת כו'\u0004 משנה בפ\"ב דיבמות (דף כ.) כלל אמרו ביבמה כל שאיסורה איסור ערוה לא חולצת ולא מתייבמת איסור מצוה ואיסור קדושה חולצת ולא מתייבמת איסור מצוה שניות מדברי סופרים. איסור קדושה אלמנה לכ\"ג גרושה וחלוצה לכהן הדיוט ממזרת ונתינה לישראל בת ישראל לנתין ולממזר ופירש\"י שניות שניות לעריות שגזרו סופרים עליהם: אלמנה לכ\"ג. שמת אחיו ההדיוט ונפלה אלמנתו לפניו: גרושה וחלוצה לכהן הדיוט. שעבר אחיו המת ונשא חלוצה וגרושה וכשמת צריכה חליצה שהרי קידושין תופסין לו בה דקידושין תופסין בחייבי לאווין אבל יבומי לא שהרי אסורה לו לזה שהוא כהן ואפטורי בלא כלום לא דלא אלים לאו למיפטרה דילפינן מאחות אשה בפ\"ק עכ\"ל:","\u0003ומ\"ש רבינו וצרתה או חולצת או מתייבמת כ\"כ נ\"י אמתני' וז\"ל איסור מצוה ואיסור קדושה כו'\u0004 דוקא היא אבל צרתה מתייבמת שאין צרה פטורה אלא מערוה וכדנפקא לן בפ\"ק (ג:) מאחות אשה דכתיב בה לצרור וכן איתא בירושלמי להדיא עכ\"ל:","ומ\"ש ואין חליצתה פוטרת צרתה אבל חליצת צרתה פוטרת אותה כדפרישית לעיל בסימן ק\"ע כ\"כ בשם הרמב\"ם ז\"ל ושם נתבאר. ומ\"ש ואם עבר ובא עליה קנאה ונפטרה צרתה ומוציאה בגט בפ\"ב דיבמות (דף כ:) תניא פצוע דכא וכרות שפכה שמתו אחיהם ועמדו הם ובעלו קנו ואסור לקיימן משום שנאמר לא יבא פצוע דכא פירש\"י אם בעלו קנו ויוצאת בגט בלא חליצה.","ומ\"ש רבי' שנפטרה צרתה פשוט הוא דכיון שאם בעלו קנו ויוצאת בגט בלא חליצה א\"כ בביאה זו נעקרה זיקה לגמרי מבית זה ופשיטא דנפטרה צרתה וכך מפורש שם בברייתא איסור מצוה ואיסור קדושה בא עליה או חלץ לה נפטרה צרתה והא דקתני דאם חלץ לה שפוטרת צרתה ורבינו כתב בסמוך שאם חלץ לה לא נפטרה צרתה כבר נתבאר בדברי ה\"ה שכתבתי בסימן ק\"ע ז\"ל הרמב\"ם בפ\"ג היתה היבמה אסורה על יבמה איסור לאו או איסור עשה או שהיתה שנייה הרי זו חולצת ולא מתייבמת ומפני מה צריכה חליצה מפני שיש בה לקוחין הואיל וקידושין תופסין בהן הרי הן זקוקות לייבם ומן הדין היה שיתייבמו שהייבום מצות עשה וכל מקום שאתה מוצא עשה ולא תעשה יבא עשה וידחה את לא תעשה אבל חכמים גזרו שלא יתייבמו חייבי לאווין ולא שניות גזירה שמא יבא עליה פעם שנייה והרי ביאתה אסורה ואין שם מצוה שאין מ\"ע אלא ביאה ראשונה בלבד לפיכך אם עבר ובעל יבמתו האסורה לו משום לאו או משום עשה ואצ\"ל שנייה ה\"ז קנה קנין גמור ומוציאה בגט והיא וכל צרותיה מותרות לזר שהרי נפטרו עכ\"ל וטעם זה שכתב שהוא גזירה ביאה ראשונה אטו ביאה שנייה הוא מסקנא דרבא בפרק כיצד (שם) היתה אסורה לבעלה באיסור לאו או עשה או איסור דרבנן ומותרת לייבם הרי היא זקוקה לו דכיון שלא היתה אסורה לבעלה אלא בלאו תפסי בה קידושין וכיון שמותרת ליבם יכול לייבם אותה מבואר במשנה פרק יש מותרות (יבמות דף פד.):","ומ\"ש חוץ ממחזיר גרושתו משניסת שאם החזיר אחיו גרושתו משניסת ומת חולצת ולא מתייבמת בפ\"ק דיבמות (דף יא:) בעי ר\"י המחזיר גרושתו משניסת צרתה מהו ת\"ש המחזיר גרושתו משניסת היא וצרתה חולצת היא וצרתה ס\"ד אלא או היא או צרתה ולאו תירוצי קא מתרצת לה תריץ הכי הוא חולצת צרתה או חולצת או מתייבמת וכתבו הרי\"ף והרא\"ש ז\"ל ומסקנא כי האי תירוצא בתרא דאמרי' כי אתא רבין א\"ר יוחנן אחת צרת ממאנת פי' ממאנת ביבם ואחת צרת איילונית ואחת צרת מחזיר גרושתו משנישאת כולן מותרות ודוקא צרותיהן אבל אינהו גופייהו בדליכא בהדייהו צרות כל חדא מינייהו אית לה דינא באפי נפשה ממאנת ביבם אע\"ג דלגבי יבם דמיאנה בו לאו בת חליצה ויבום היא לגבי אחיו של יבם שריא וחולצת או מתייבמת דאמר שמואל מיאנה בזה מותרת בזה ואיילונית לא חולצת ולא מתייבמת ומחזיר גרושתו משנישאת ומת חולצת ולא מתייבמת וכתב ה\"ה בפ\"ו מפורש בפ\"ק ומסקנא שהיא חולצת ולא מתייבמת וצרתה או חולצת או מתייבמת פירוש והיא נפטרת בחליצתה או בביאתה וצרתה נפטרת בחליצתה של זו אבל לא בביאתה אם עבר ובא עליה כדין אלמנה מן הנישואין לכ\"ג וכ\"כ הרשב\"א ז\"ל דממעטי לה מההיא דרב גידל דלעיל וזהו שלא הזכיר רבינו איסור בצרתה עכ\"ל: ומ\"ש מההוא דרב גידל היינו דבפרק כיצד (כ.) אהא דתנא שאם היתה היבמה אלמנה לכ\"ג גרושה וחלוצה לכהן הדיוט חולצת ולא מתייבמת הקשו בגמרא קא פסיק ותנא ל\"ש אלמנה מן הנישואין ול\"ש מן האירוסין בשלמא מן הנישואין אין עשה דייבום דוחה את לא תעשה דאלמנה לא יקח ועשה דוהוא אשה בבתוליה בתולה ולא בעולה ולאו הבא מכלל עשה עשה אלא אלמנה מן האירוסין אמאי יבא עשה וידחה את לא תעשה ותירץ רב גידל בשם רב דאמר קרא ואם לא יחפוץ האיש לקחת יבמתו ועלתה יבמתו כו' שאין ת\"ל יבמתו מה ת\"ל יבמתו יש לך יבמה אחת שעולה לחליצה ואינה עולה ליבום ואי זו זו חייבי לאוין והקשו ע\"ז מן הברייתא דקתני גבי חייבי לאוין ואם בעלו קנו ואסור לקיימה ואי ס\"ד מדאורייתא חייבי לאוין לחליצה רמייה לייבום לא רמייה אמאי אם בעלו קנו ואסיקו דלאו מדאוריי' אלא מדרבנן אמרו שאינן עולות לייבום גזירה ביאה ראשונה אטו ביאה שנייה ולפיכך אם בעלו קנו וכתב ה\"ה שם כל זה על דברי הרמב\"ם ז\"ל וכתב עוד וז\"ל וכתב בה\"ג והא דרב גידל א\"ר מיקיימא באלמנה מן הנישואין דאע\"ג דמדאורייתא לאו בת ייבום היא רבייה רחמנא לחליצה עכ\"ל. ונרא' מדברי ה\"ה דמחזיר גרושתו עובר בעשה ול\"ת מדמדמי לה לאלמנה לכ\"ג מן הנישואין ומייתי לה מדרב גידל ואיני יודע מנין לו שאיני מוצא בה אלא לאו בלבד ועוד יש לתמוה עליו שכתב וצרתה של זו נפטרת בחליצה של זו אבל לא בביאתה שהרי כתב הרמב\"ם ז\"ל בפ\"ז יראה לי שכך הדין בב' יבמות הבאות מבית אחד והאחת מהן אסורה על יבמה משום שנייה או מחייבי לאוין או מחייבי עשה שאם חלץ לאסורה לא הותרה צרתה וצ\"ע:","אחות חלוצה אסורה מדרבנן לפיכך נפלה לפני יבם חולצת ולא מתייבמת וכן צרתה אסורה מדרבנן וחולצת ולא מתייבמת כך כתוב בספרי רבינו המדוייקים ובקצת ספרים חסר כל בבא זו והוא ט\"ס שהרי דין זה הוא מבואר בפרק החולץ (יבמות דף מא.) דתנן התם החולץ ליבמתו ונשא אחיו את אחותה ומת חולצת ולא מתייבמת ובגמרא (שם) אמר ר\"ל כאן שנה רבי אחות חלוצה מד\"ס ומשמע נמי התם במתני' דאסור אדם בצרת קרובת חלוצתו דגם צרת חלוצה אסורה מד\"ס:","מי שיש עליה זיקת ב' יבמין היא וצרתה חולצות ולא מתייבמות כיצד ג' אחים נשואים לג' נשים נכריות ומת אחד מהם ועשה אחד מהנשארים מאמר ביבמתו ומת קודם שכנסה כו' משנה פ' ד' אחין (יבמות דף לא:) ג' אחים נשואים ג' נשים נכריות ומת אחד מהם ועשה בה השני מאמר ומת הרי אלו חולצות ולא מתייבמות שנאמר ומת אחד מהם יבמה יבא עליה שעליה זיקת יבם אחד ולא שעליה זיקת ב' יבמים ובגמרא (שם) ואי זיקת ב' יבמים דאורייתא חליצה נמי לא תיבעי אלא מדרבנן וגזירה שמא יאמרו ב' יבמות הבאות מבית אחד מתייבמות ולייבם לחדא ונחלוץ לחדא גזירה שמא יאמרו בית אחד מקצתו בנוי ומקצתו חלוץ ויאמרו אי דמייבם והדר חליץ ה\"נ אלא גזירה דילמא חליץ והדר מייבם וקם ליה באשר לא יבנה ורחמנא אמר כיון שלא בנה שוב לא יבנה ופירש\"י מקצתו חלוץ. ואתו למימר בשתי יבמות הבאות מבית אחד חדא מתייבמת ואחרת חלצה. וכתבו הרי\"ף והרא\"ש ז\"ל הא דאמרינן בזיקת ב' יבמין מיחלץ חלצה יבומי לא מייבמה לא תימא ה\"מ היכא דאיכא צרה דאיכא למיגזר משום צרה אלא אפילו היכא דליכא אלא חדא יבמה ואיכא עלה זיקת שני יבמין מיחלץ חלצה יבומי לא מייבמה כדתנן בפרק האשה רבה (יבמות צו:) בן ט' שנים ויום אחד שבא על יבמתו ומת חולצת ולא מתייבמת ואמר רבא עלה הא דאמרי רבנן זיקת שני יבמין מיחלץ חלצה יבומי לא מייבמה לא תימא ה\"מ היכא דאיכא צרה דאיכא למיגזר משום צרה דהא הכא דליכא צרה מיחלץ חלצה יבומי לא מייבמה:","\u0003נתן לה גט ופירש שהוא למאמרו הרי ביטל המאמר שעשה כו'\u0004 שם (ד' לב.) אמר רבא נתן גט למאמרו הותרה צרתה אבל היא אסורה משום דמיחלפא בבעלת הגט איכא דאמרי אמר רבא נתן גט למאמרו הותרה אפילו היא מאי טעמא מאי דעביד בה שקליה ופסק הרמב\"ם ז\"ל בפ\"ו כלישנא בתרא וכ\"פ הרא\"ש ז\"ל ופירש\"י הותרה אפילו היא. לשלישי כשימות שני: מאי דעבד שקליה. והוה ליה כמי שלא עשה בה מאמר ואתיא ומתייבמת לשלישי מחמת זיקת אחיו הראשון ודוקא שפירט למאמרו ולא לזיקתו קאמר אבל סתמא קאי בלא יבנה אכולהו אחים והכי מוכחא מילתא דרבא בפרק ר\"ג (יבמות נב:) דלמאמרו ולא לזיקתו קאמר וכ\"כ הרא\"ש ז\"ל והכי דייק לישנא דהרמב\"ם ז\"ל:","קטן שבא על יבמתו ומת חולצת ולא מתייבמת שאין ביאתו קונה קנין גמור ויש עליה זיקת ב' יבמים משנה וגמרא בס\"פ האשה רבה (יבמות דף צו:) וכתבתיו בסמוך:","מי שחציה שפחה וחציה בת חורין שנתקדשה לראובן ונשתחררה וקדשה שמעון אחיו ומתו שניהם ונפלה לפני לוי אחיהם מתייבמת לו שאינה אשת ב' מתים וכו' מימרא דרב חסדא בפ' השולח (גיטין מג.):"],["\u0003יבמה וכו'\u0004 וצרתה או חולצת או מתייבמת ירושלמי הביאו הרי\"ף והרא\"ש פ\"ב דיבמות תחלתו תני בר קפרא וכו' עד צרת שנייה או חולצת או מתייבמת ומשמע דה\"ה בחייבי לאווין ועשה שהרי במתניתין השוו מדותיהם כלל אמרו ביבמה כו' וכ\"כ בנ\"י פ\"ק דיבמות:","\u0003ומ\"ש ואין חליצתה וכו'\u0004 כדפי' לעיל ע\"ל בסימן ק\"ע סי\"ג כתבתי דמדרבנן הוא דמחמרינן דחליצתה אינה פוטרת אבל ד\"ת כי היכי דאם בא עליה קנאה ונפטרה צרתה ה\"ה חלץ לה כדתניא להדיא פ\"ב (דף כ) ע\"ש:","\u0003היתה אסורה לבעלה וכו'\u0004 חוץ ממחזיר גרושתו וכו' בפ\"ק (ריש ד' י\"ב) אסיקנא תריץ הכי מחזיר גרושתו משניסת היא חולצת צרתה או חולצת או מתייבמת וכך פסקו הרי\"ף והרא\"ש לשם ואע\"ג דליכא בה שום איסור לאו ועשה על היבם אפילו הכי מתייבמת מק\"ו במותר לה נאסרה באסור לה לא כ\"ש ומ\"מ לא אלים האי ק\"ו למיפטרה מחליצה היא גופה אבל צרתה אף לייבום דאין זו צרת ערוה דטומאה דכתיב בה מוקים לה בסוטה ודאי ואיתעקר ממחזיר גרושתו כאילו לא כתב בה טומאה וכדמוכח בסוגיא ועיין במ\"ש לעיל סי' קע\"ב ס\"ח: כתב הרמב\"ם בפ\"ו יבמה שהיא אלמנה מן הנישואין ובא עליה כ\"ג לא נפטר צרתה שאין עשה דוחה ל\"ת ועשה והואיל דלא קנה מן התורה קנין גמור לא הותרה צרתה לזר עד שתחלץ עכ\"ל וטעמו דפסק כרב גידל בפ\"ב (דף כ) דדריש יבמתו יתירא דחייבי לאווין עולה לחליצה ואינו עולה לייבום ואע\"ג דדחינן דח\"ל מדאורייתא שריא אף לייבום היינו ח\"ל גרידא אבל אלמנה מן הנישואין לכ\"ג דאיכא ל\"ת ועשה אינה עולה לייבום ד\"ת ואפ\"ה עולה לחליצה ולפ\"ז אם עבר כ\"ג ובעל לא נפטרה צרתה וכ\"כ ה\"ה לשם בשם בה\"ג ולמד ה\"ה מכאן דבמחזיר גרושתו משניסת נמי אם עבר ובא עליה היבם לא נפטרה הצרה הואיל ולא קנאה מן התורה מק\"ו דלעיל אבל הב\"י כאן וכן בכ\"מ השיג על ה\"ה וז\"ל ונראה מדברי ה\"ה דמחזיר גרושתו משניסת עובר בעשה ול\"ת מדמדמי ליה לאלמנה לכ\"ג מן הנישואין ואיני יודע מניין לו שאינו מוצא בה אלא לאו בלבד עכ\"ל ושרי ליה מאריה דהא באלמנה לכ\"ג איסור לאו ועשה על היבם היא ובמחזיר גרושתו משניסת אין שם לאו ולא שום איסור עשה על היבם אלא מק\"ו הוא נלמד וכאילו כתב קרא בפי' דאינו עולה לייבום והלכך אין צרתה נפטרת בביאתה ולא דמי לח\"ל דקי\"ל דעשה דוחה ל\"ת ולפ\"ז ספק סוטה נמי דמק\"ו הוא נלמד אין צרתה נפטרת בביאתה. עוד כתב ה\"ה דצרת מחזיר גרושתו משניסת נפטרת בחליצה והחשה עליו ב\"י לשם ממ\"ש הרמב\"ם פ\"ז דב' יבמות מבית א' והאחד מהן שנייה על היבם או ח\"ל או חייבי עשה שאם חלץ לאסורה לא הותרה צרתה וצ\"ע עכ\"ל וגם זה אינו קשה כלל דהא מעיקרא קס\"ד דאו היא או צרתה חולצת וכל אחת נפטרה בחליצת חבירתה דלאו חליצה פסולה היא השתא ודאי דגם למאי דמסיק היא חולצת צרתה או חולצת או מתייבמת מ\"מ הא דצרתה נפטרה בחליצתה לא אידחיא לה וכ\"כ התו' לשם ובר\"פ ד' אחין בד\"ה וחליצה פסולה דמחזיר גרושתו משניסת אף ע\"ג דאסורה להתייבם כיון שהזיקה שלימה פוטרת ואינו דומה לשאר חליצה פסולה ואף להרמב\"ם דבח\"ל ועשה ושניות הויא נמי חליצה פסולה אף על פי דהזיקה שלימה מ\"מ לא דמי למחזיר גרושתו משניסת דדוקא ח\"ל ועשה ושנייה כיון דד\"ת עולה לייבום אלא דרבנן עבוד תקנתא דלא ליבומי גזירה ביאה ראשונה אטו שנייה ומ\"ה הו\"ל חליצה פחותה ופסולה הדור עבוד רבנן תקנתא דלחזור על כל האחין אף על פי שהזיקה שלימה אבל מחזיר גרושתו משניסת דד\"ת אינה עולה לייבום מח\"ו ולחליצה עולה ד\"ת מקרא דיבמתו ופטרה צרתה כיון שהזיקה שלימה אם כן חליצה מעולה ד\"ת היא אף על פי שאינה עולה לייבום אין להם לרבנן למיעבד תקנתא בכדי דלחזור על כל האחים ולהוסיף על התורה וכן בספק סוטה דמדאורייתא אינו עולה לייבום נפטרה צרתה בחליצתה אבל סוטה דרבנן דמדאורייתא עולה לייבום אלא דרבנן גזרו שלא תתייבם הו\"ל חליצה פסולה כמ\"ש התוס' בשם הירושלמי ר\"פ ד' אחין בדבור הנזכר וה\"ה הביא הירושלמי פ\"ח מה' יבום ע\"ש ומ\"מ קשה מאין למד ה\"ה מדברי הרמב\"ם דבמחזיר גרושתו משניסת נפטרה צרתה בחליצתה שזה לא נשמע מדברי הרב ואפשר דס\"ל להחמיר דלא נפטרה צרתה כיון דבעיא זו לא נפשטא בגמרא וצ\"ל דס\"ל לה\"ה כיון דהרי\"ף פסק להקל מסתמא הוא גם דעת הרמב\"ם ודו\"ק:","\u0003אחות חלוצה אסורה מדרבנן וכו'\u0004 משנה וגמרא פרק החולץ ריש (יבמות דף מ\"א) ולעיל סי' קע\"ג כתב רבינו דאף ספק אחות חלוצה אסורה לכתחילה ע\"ש:","\u0003מי שיש עליה זיקת שני יבמין היא.\u0004 וצרתה חולצות ולא מתייבמות כיצד וכו' משנה וגמרא פ' ד' אחין ריש (יבמות דף ל\"ב) והכי פי' מדאורייתא מאמר לא קני והו\"ל ב' יבמות מב' בתים ותרווייהו מצי ליבומי ורבנן הוא דגזרו שלא יאמרו כיון דעשה בה מאמר גם זו אשתו היא וא\"כ מייבם ב' יבמות הבאות מבית אחד וצריך לחלוץ לשתיהן כיון דמשתי בתים הם באים: ומ\"ש בספרי רבינו בסמוך היא או צרתה חולצת וכו' ט\"ס הוא וצ\"ל היא וצרתה חולצות כמ\"ש בתחילה וקאמר בגמרא דאפי' חליץ לאחת מהן אסור גזירה וכו' והרי\"ף והרא\"ש כתבו עוד דאפי' לית לה צרה דליכא גזירה אפ\"ה לא פלוג רבנן בתקנתם וא\"ת מאי איריא דעשה בה מאמר אפי' כנסה ליבמה ומת נמי נימא דאיכא עליה זיקת ב' יבמין וי\"ל דבכנסה פקעה זיקה דקמא וכי מיית לא הוי עלה אלא זיקת שני וכן אי לא עבד בה מאמר לא הוי עלה אלא זיקת ראשון אבל אי עבד בה מאמר ומת הוי עלה זיקת ב' יבמין:","\u0003ומ\"ש נשואין ג' נשים נכריות כתבו התוס' ה\"מ למינקט ואחד מופנה:\u0004 ","ומ\"ש בין יש לה צרה כלומר בין יש לה צרה כגון ג' אחים נשואין ג' נשים נכריות שכתב בסמוך בין אין לה צרה כגון שלשה אחים אחד נשוי אשה ושנים פנויים אי נמי כגון קטן שבא על יבמתו דבסמוך:"]],["\u0010c0\u0011\u0010y0\u0011יבמה שאינה ראויה להתייבם בשעת נפילה משום איסור ערוה אסורה עולמית אפילו אם יפקע האיסור כגון ב' אחין שנשואין ב' אחיות ומת אחד מהם ונפלה אשתו לפני השני שנשוי אחותה אפילו אם תמות אשתו אח\"כ שפקע איסור אחות אשה אפ\"ה אסורה \u0010y1\u0011ואפילו נפלה לפניו פעם אחרת אחרי מות אשתו כגון שהיה להם אח שלישי שלא היתה ערוה עליו וכנסה ומתה אשתו של זה שהיה נשוי אחותה ומת השלישי שכנסה וחזרה לפניו אסורה \u0010c1\u0011ל\"ש מתה אשתו קודם שכנס השלישי \u0010y2\u0011ל\"ש מתה \u0010c2\u0011אחר שכנס \u0010y3\u0011אע\"פ שלא היתה אסורה עליו בנפילה אחרונה \u0010c3\u0011אפ\"ה אסורה לו היא וצרתה כגון שהיתה אשה אחרת לאח הג' כיון שהיתה \u0010y4\u0011אסורה לו בשעת נפילה ראשונה \u0010c4\u0011\u0010y5\u0011אבל אם מותרת לו בשעת נפילה אפילו אם תיאסר אח\"כ אם פקע האיסור חוזרת להיתרה כיצד ג' אחין ב' מהם נשואין ב' אחיות ומת אחד מהם ונזקקה אשתו לשלישי שאינו נשוי אחותה ולא הספיק לכונסה עד שמת האח הב' שהיה נשוי האחרת והרי שתיהן אסורו' עליו מתה האחרונה חזרה הראשונה להיתרה כיון שהיתה מותרת בשעת נפילה אע\"פ שנאסרה בנתיים \u0010c5\u0011אבל אם מתה הראשונה לא הותרה האחרונה כיון שהיתה אסורה בשעת נפילה \u0010c6\u0011\u0010y6\u0011וכן אם היו שם עוד אחים \u0010c7\u0011וקדם אחד מהם וחלץ לאחרונה \u0010y7\u0011או שהיתה הראשונה אסורה לא' מן האחים וייבם את האחרונה שהרי היא מותרת לו הותרה הראשונה לשאר אחין שהרי האחרונה שאסרה אותה עליהם נחלצה או נתייבמה למותר לה אבל אם האחרונה אסורה לאחד מהם משום ערוה הרי הוא מותר לייבם הראשונה \u0010c8\u0011ושאר האחין אסורים בשתיהן וחולצות ולא מתייבמות \u0010c9\u0011\u0010y8\u0011ד' אחים ב' מהם נשואים לב' אחיות ומתו הנשואין את האחיות \u0010y9\u0011בבת אחת או בזה אחד זה \u0010c10\u0011קודם שהספיקו לייבם לראשונה שתיהן חולצות ולא מתייבמות שא\"א לשום אחת מהן להתייבם משום איסור אחות זקוקה \u0010c11\u0011\u0010y10\u0011קדמו וכנסו אין מוציאין אותן מידם היתה אחת מהן אסורה לאחד מהיבמין משום איסור ערוה כגון שהיא בתו או אחת משאר כל העריות מותר בשנייה שהרי אין הערוה זקוקה לו ונמצא שאין לו זקוקה אלא א' והב' אסור בשתיהן \u0010y11\u0011היתה אחת מהן אסורה לזה משום ערוה והשנייה אסורה לב' משום ערוה האסורה לזה מותרת לזה והאסורה לזה מותרת לזה שכל א' אין זקוקה לו אלא א' אבל אם אין אסורות עליהם אלא באיסור לאו או עשה לא נדחית הזיקה מהם כיון שמן התורה הן בני חליצה ויבום וחולצות ולא מתייבמות \u0010y12\u0011נ' אחין ב' מהם נשואין ב' אחיות ומת אחד מבעלי האחיות ועשה הג' מאמר ביבמתו ואח\"כ מת בעל אחות השנייה ונפלה גם האחות הב' לפני האח השלישי אינה נדחית מפני הראשונה שהיא אחותה כיון שלא עשה בה אלא מאמר שאינו קונה קנין גמור וגם אין יכול לכנוס הראשונה שהאחרונה אוסרתו ושתיהן אסורות עליו ויוציא בעלת המאמר בגט ובחליצה והאחרונה בחליצה \u0010c12\u0011\u0010y13\u0011וכתב הרמב\"ם מת זה שעשה מאמר והיה לו אשה אחרת ונפלו שתיהן לפני בעל האחות השנייה בעלת המאמר פטורה מן החליצה ומן היבום שהיא אחות אשתו והאשה האחרת חולצת ולא מתייבמת שאין המאמר קונה קנין גמור שיפטור צרתה \u0010y14\u0011וא\"א הרא\"ש ז\"ל כתב אפילו לא עשה הג' מאמר באחת מן האחיות אלא אחר שמת אחד מנשוי האחיות מת הג' ונפלה אשתו לפני בעל נשוי האחות האחרת אשתו חולצת ולא מתייבמת כיון שהיא צרת אחות אשתו בזיקה. \u0010c13\u0011\u0010y15\u0011ג' אחים ב' מהם נשואים ב' אחיות ואחד נשוי נכרית וגירש אחד מבעלי אחיות \u0010y16\u0011ומת אחיו נשוי נכרית וכנסה המגרש ומת מותרת לאח הנשאר שלא היתה מעולם צרת ערוה שהרי גירש אחיו הערוה קודם שנזקקה לו הנכרית אבל אם מת נשוי נכרית קודם שגירש אחד מבעלי אחיות את אשתו אפילו אם לא כנס הנכרית ומת שנמצא שהיתה צרת ערוה בזיקה אסורה לאח הנשאר אפילו גירש הערוה קודם שמת \u0010y17\u0011וכל שכן אם לא גירש הערוה ומת \u0010c14\u0011\u0010y18\u0011אבל אם כנס בעל האחות את הנכרית וגירש הערוה \u0010y19\u0011ומת ל\"ש גירש קודם שכנס הערוה ל\"ש אח\"כ מותרת הנכרית לאח הנשאר \u0010y20\u0011ב' אחים פקחים נשואים ב' אחיות קטנות או חרשות ומת אחד מהן תצא משום אחות אשה שהרי נשואי שתיהן שוות אחד נשוי פקחת ואחד נשוי חרשת מת בעל החרשת תצא משום אחות אשה מת בעל הפקחת בעל חרשת מוציא את אשתו בגט לפי שקידושי הפקחת לפיקח שהן דאורייתא אוסרת את אשתו עליו משום אחות זקוקה שאין כח בקידושי אשתו לדחות הפקחת משום אחות אשה לפיכך מוציא את אשתו בגט ואת אשת אחיו כחליצה \u0010c15\u0011\u0010y21\u0011היתה אחת גדולה ואחת קטנה מת בעל הקטנה תצא משום אחות אשה מת בעל הגדולה היא אוסרת הקטנה עליו כדפי' גבי פקחת וחרשת ומלמדין הקטנה שתמאן בבעלה וייבם הגדולה \u0010y22\u0011ב' אחין א' פיקח וא' חרש נשואין לב' אחיות פקחות או אחת פקחת ואחת חרשת והפקחת נשואה לפיקח מת חרש בעל חרשת או חרש בעל פקחת תצא משום אחות אשה מת פיקח בעל פקחת החרש בעל החרשת או בעל הפקחת מוציא את אשתו בגט שאחותה הפקחת אוסרתה עליו ואשת אחיו אסורה לעולם שאינו יכול לחלוץ לה כיון שחרש הוא ב' אחין חרשים נשואין לב' אחיות פקחות או חרשות או אחת פקחת ואחת חרשת וכן ב' אחיות חרשות נשואין לב' אחין פקחין או חרשין או אחד פיקח ואחד חרש ומת אחד מהם תצא משום אחות אשה דכיון דב' האחין חרשין או ב' אחיות חרשות קידושיהן שוות וכמו שהן הקדושין כך היא הזיקה ויוצאת משום אחות אשה ואם היו נכריות יכניסו ואם ירצו להוציא בגט יוציאו דכמו שכנס אחיו ברמיזה כך יוציא גם הוא ברמיזה \u0010y23\u0011ב' אחין אחד פיקח ואחד חרש והחרש נשוי ב' נשים פקחות ואחת מהן ערוה על הפיקח ומת החרש שתיהן פטורות מן החליצה ומן היבום שאם נישואי הערוה נישואין הרי השנייה צרתה ופטורה ואם אין נישואי הערוה נישואין גם אין נישואי הצרה נישואין ואינה זקוקה לו היו שניהם פקחין ואחד מהם נשוי ב' נשים אחת פקחת ואחת חרשת והחרשת היא ערוה על אחיו השני הפקחת חולצת ולא מתייבמת שאין נישואי החרשת שהיא ערוה נישואין גמורים שתחשב זאת צרת ערוה:",["יבמה שאינה ראויה להתייבם בשעת נפילה משום איסור ערוה אסורה עולמית אפילו אם יפקע האיסור כגון ב' אחים שנשואים ב' אחיות ומת אחד מהם ונפלה אשתו לפני השני שנשוי אחותה אפי' אם תמות אשתו אח\"כ שפקע איסור אחות אשה אפ\"ה אסורה משנה פ' ד' אחין (יבמות לב:):","ומ\"ש ואפי' נפלה לפניו פעם אחרת אחרי מות אשתו כגון שהיה להם אח שלישי שלא היתה ערוה עליו כו' ג\"ז משנה שם (ל.) ג' אחים ב' מהם נשואים ב' אחיות ואחד נשוי נכרית מת אחד מבעלי אחיות וכנס נשוי נכרית את אשתו ומתה אשתו של שני ואח\"כ מת נשוי נכרית ה\"ז אסורה עליו עולמית הואיל ונאסרה עליו שעה אחת:","ומ\"ש ל\"ש מתה אשתו קודם שכנס השלישי ל\"ש מתה אחר שכנס אע\"פ שלא היתה אסורה עליו בנפילה אחרונה אפ\"ה אסורה לו (שם) אמר רב יהודה א\"ר כל יבמה שאין אני קורא בה בשעת נפילה יבמה יבא עליה הרי היא כאשת אח שיש לו בנים ואסורה מאי קמ\"ל תנינא ה\"ז אסורה עליו עולמית הואיל ונאסרה עליו שעה אחת מהו דתימא ה\"מ היכא דלא איחזיא לה בנפילה ראשונה אבל היכא דאיחזיא לה בנפילה ראשונה אימא תשתרי קמ\"ל ופירש\"י שעה אחת. בנפילה ראשונה כשנפלה מאחיו הראשון: הרי היא כאשת אח כו'. ואע\"ג דהדר איחזיא: בנפילה ראשונה. כל זמן נפילה ראשונה היתה אשתו קיימת שהיא אחותה: אבל היכא דאיתחזי בנפילה ראשונה. כגון שמתה אשתו אחר מיתת אחיו ולא כנסה נשוי נכרית עכ\"ל:","\u0003ומ\"ש רבינו אע\"פ שלא היתה אסורה עליו בנפילה אחרונה כו'\u0004 כלומר שלא היתה אסורה עליו בשעת נפילה אחרונה שמתה אשתו קודם שכנס נשוי נכרית את היבמה אפילו הכי אסורה לו כיון שהיתה אסורה לו בשעת נפילה ראשונה:","ומ\"ש אסורה לו היא וצרתה כגון שהיה אשה אחרת לאח הג' כ\"כ הרמב\"ם ז\"ל בפ\"ז ודבר פשוט הוא דכיון דהיא אסורה משום אשת אח הו\"ל צרתה צרת ערוה וכתב ה\"ה הדבר פשוט דל\"ש בנכרית אם היה נשוי אותה האח השני בשעה שכנס יבמתו ל\"ש נשאה אח\"כ דכל יבמה שאין אני קורא בה בשעת נפילה יבמה יבא עליה הרי היא כאשת אח שיש לו בני' ואסורה כדאיתא התם וצרתה הו\"ל צרת ערוה עכ\"ל:","ומ\"ש אבל אם מותרת לו בשעת נפילה אפילו אם תיאסר אח\"כ אם פקע האיסור חוזרת להיתירה כיצד ג' אחים ב' מהם נשואים ב' אחיות ומת אחד מהם כו' בר\"פ ד' אחין (יבמות כז:) אמר ר\"ה אמר רב ב' אחיות יבמות שנפלו לפני יבם א' חלץ לראשונה הותרה לשנייה הותרה מתה הראשונה מותר בשנייה ואצ\"ל מתה שנייה שמותר בראשונה משום דהויא יבמה שהותרה ונאסרה וחזרה והותרה תחזור להיתירה הראשון ר' יוחנן אמר מתה שנייה מותר בראשונה אבל מתה הראשונה אסור בשנייה מ\"ט שכל יבמה שאין אני קורא בה בשעת נפילה יבמה יבא עליה ה\"ז כאשת אח שיש לה בנים ואסורה ורב ה\"מ היכא דקאי באפה איסור אחות אשה דאורייתא אבל הכא זיקה דרבנן היא ופירש\"י ור' יוחנן אמר מתה שנייה מותר בראשונה. הואיל ובשעת נפילה היתה ראויה לו וידוע דרב ור' יוחנן הלכה כר\"י ודע שיש בקצת ספרי רבינו חסרון הניכר והגירסא הנכונה בספרים המדוייקים כך הוא מתה האחרונה חזרה הראשונה להיתירה הראשון כיון שהיתה מותרת בשעת נפילה אף על פי שנאסרה בנתיים אבל אם מתה הראשונה לא הותרה האחרונה כיון שהיתה אסורה עליו בשעת נפילה:","וכן אם היו שם עוד אחין וקדם א' מהם וחלץ לאחרונה שם איתיביה ר' יוסי בר חנינא לר' יוחנן ד' אחין ב' מהם נשואים ב' אחיות ומתו הנשואין את האחיות הרי אלו חולצות ולא מתייבמות ואמאי ליקום חד מינייהו ולחלוץ לשנייה ותיהוי הראשונה לגבי אידך כיבמה שהותרה ונאסרה וחזרה והותרה תחזור להיתרה הראשון א\"ל אחיות איני יודע מי שנאן ופירש\"י כלומר זו אינה משנה ודקדק רבינו לכתוב וקדם אחד מהם וחלץ לאחרונה דמשמע דלכתחילה לא אמרי' להו לחלוץ השנייה ולייבם הראשונה דגזרי' דילמא אתי למעבד איפכא באלו הצרות עצמן וכ\"כ שם התוספות אהא דפריך על מאן דאמר אחיות איני יודע מי שנאן ולימא ליה גזירה דילמא קדים וחליץ לראשונה ברישא וגם הרמב\"ם ז\"ל בפ\"ז כ\"כ אם קדם אחד מן האחין וחלץ לאחרונה הותרה הראשונה לשאר אחין דמשמע דדוקא בדיעבד וחלץ קאמר דהותרה ראשונה אבל לכתחילה לא מורינן להו לחלוץ לאחרונה כדי שתותר הראשונה:","ומ\"ש או שהיתה הראשונה אסורה לאחד מן האחין וייבם האחרונה שהרי היא מותרת לו הותרה הראשונה לשאר אחין שהרי האחרונה שאסרה אותה עליהם נחלצה או נתייבמה למותר לה אבל אם האחרונה אסורה לאחד מהם משום ערוה הרי הוא מותר לייבם הראשונה ושאר האחין אסורים בשתיהן וחולצות ולא מתייבמות שם (דף כח.) תנן היה א' מהן אסורה על האחד איסור ערוה אסור בה ומותר באחותה והשני אסור בשתיהן ס\"ד דנפלה חמותה ברישא וכו' ותיהוי חמותה לגבי אידך כיבמה שהותרה ונאסרה וחזרה והותרה תחזור להיתירה הראשון אמר רב פפא כגון דנפלה הך דאין חמותה ברישא ומתוך דברים הללו יתבאר לך שמ\"ש או שהיתה הראשונה אסורה לא' מן האחין היינו לומר שהיא אסורה לו משום ערוה וכך הם דברי הרמב\"ם ז\"ל בפ\"ז ואהא דכתב רבינו ושאר האחים אסורין בשתיהן וחולצות ולא מתייבמות סיים הרמב\"ם ז\"ל ואם קדמו וכנסו כל אחד אחת מן האחיות מוציאין אותן מהם. כתב עוד הרמב\"ם ז\"ל בפ\"ז ב' מן האחים נשואין לב' אחיות ומתו שניהם ולא נודע איזה מהם מת ראשון הואיל ואי איפשר לייבם שתיהן והרי זיקה נפלה על שתיהן שתיהן חולצות ולא מתייבמות ואפי' היתה אחת מהן אסורה על היבם משום שנייה או מחייבי עשה או מחייבי לאוין הרי אלו חולצות ולא מתייבמות אבל אם היתה אחת מהם ערוה עליו כגון שהיתה אם אשתו או בתה הרי אחותה מותרת לו רצה חולץ רצה מייבם שהרי לא נפלה זיקתו על שתיהן שאין זיקה על הערוה וכ\"כ מדאמרינן בגמרא אהא דאמר רבי יוחנן אחיות איני יודע מי שנאן ולימא ליה דלא ידעינן הי נפיל ברישא אי הכי היינו דקתני קדמו וכנסו יוציאו בשלמא ראשון אמרי' ליה מאן שרי לך אלא שני יאמר חבראי שנייה ייבם אלא ראשונה מייבם היינו דקא\"ל אחיות איני יודע מי שנאן משמע בהדיא דכל היכא דלא ידעינן הי נפיל ברישא חולצות ולא מתייבמות:","\u0003ד' אחין ב' מהם נשואים ב' אחיות ומתו הנשואים את האחיות הרי אלו חולצות ולא מתייבמות:\u0004 ","ומ\"ש דבת אחת או בזה אחר זה קודם שהספיקו לייבם לראשונה פשוט הוא שכל שלא הספיקו לייבם לראשונה עד שנפלה שניה כנפלו שתיהן בבת אחת דמי:","ומ\"ש קדמו וכנסו אין מוציאין אותם מידם שם במשנה הנזכר ואם קדמו וכנסו ר\"א אומר ב\"ש אומרים יקיימו וב\"ה אומרים יוציאו וכתב הרמב\"ם ז\"ל בפירוש המשנה העיקר אצלנו ב\"ש במקום ב\"ה אינו משנה ר\"ל כל זמן שתמצא ב\"ש מקילין וב\"ה מחמירין וזה היפך המפורסם מסברתם לפיכך תדע שהמשנה מוטעת ושדבר המיוחד לב\"ש הוא אמנם הוא חוץ מן המקומות המנויים שהם מקולי ב\"ש ומחומרי ב\"ה ולפיכך פסק הלכה בכאן יקיימו עכ\"ל וקשה לן על דבריו דהא כיון דב\"ש מקילין וב\"ה מחמירין ר\"א הוא דקאמר לה ואילו סתם מתני' קתני לה סתמא אם קדמו וכנסו יוציאו הכי איבעי לן למפסק הלכה. ואפשר שזה היה דעת הרמב\"ם ז\"ל בחיבורו שכתב אם קדמו וכנסו כל אחד אחת מן האחיות מוציאין אותן מהם. ורבינו איפשר טעמו מדתניא בגמרא ר\"א אומר ב\"ש אומרים יקיימו ובה\"א יוציאו ר\"ש אומר יקיימו אבא שאול אומר קל היה להם לב\"ה בדבר זה שב\"ש אומרים יוציאו ובה\"א יקיימו ר\"ש כמאן אי כב\"ש היינו ר\"א אי כב\"ה היינו אבא שאול ה\"ק לא נחלקו ב\"ש וב\"ה בדבר זה והשתא כיון דאבא שאול סבר דלב\"ה יקיימו ור\"ש סבר דלדברי הכל יקיימו הכי נקטינן.","היתה א' מהן אסורה לאחד מהיבמים משום איסור ערוה כגון שהיתה בתו או אחת מהעריות מותר בשנייה שהרי אין הערוה זקוקה לו ונמצא שאין זקוקה לו אלא אחת והשני אסור בשתיהן היתה אחת מהן אסורה לזה משום ערוה והשנייה אסורה לשני משום ערוה האסורה לזה מותרת לזה שכל אחד אין זקוקה לו אלא אחת אבל אם אין אסורה עליהם אלא באיסור לאו או עשה לא נדחית הזיקה מהם כיון שמן התורה הם בני חליצה וייבום וחולצות ולא מתייבמות הכל שם במשנה:","\u0003ג' אחים ב' מהם נשואים ב' אחיות ומת אחד מבעלי האחיות ועשה השלישי מאמר ביבמתו כו'\u0004 משנה שם ג' אחים ב' מהם נשואים ב' אחיות ואחד מופנה מת אחד מבעלי האחיות ועשה בה מופנה מאמר ואח\"כ מת אחיו השני בש\"א אשתו עמו והלה תצא משום אחות אשה ובה\"א מוציא את אשתו בגט וחליצה ואשת אחיו בחליצה:","וכתב הרמב\"ם ז\"ל מת זה שעשה מאמר והיה לו אשה אחרת ונפלו שתיהן לפני בעל האחות השנייה בעלת המאמר פטורה וכו' בפ\"ז והוא מבואר במשנה פרק ד' אחין (יבמות ל:) ג' אחין ב' מהם נשואין ב' אחיות ואחד נשוי נכרית מת נשוי נכרית וכנס אחד מבעלי אחיות את אשתו ומת הראשונה יוצאת משום אחות אשה והשנייה משום צרתה עשה בה מאמר ומת נכרית חולצת ולא מתייבמת:","\u0003ומ\"ש רבינו בשם הרא\"ש אפי' לא עשה השלישי מאמר בא' מן האחיות כו'\u0004 חולצת ולא מתייבמת כיון שהיא צרת אחות אשה בזיקה על המשנה הנזכרת אהא דקתני עשה בה מאמר ומת נכרית חולצת ולא מתייבמת כ' וה\"ה אע\"ג דלא עבד בה מאמר ומת נכרית מחלץ חלצה יבומי לא מייבמה דהו\"ל צרת אחות אשה בזיקה והאי דקתני מאמר לאפוקי מב\"ש דאמרו מאמר קונה קנין גמור ואפילו חליצה נמי לא תיבעי קמ\"ל דצרתה חולצת עכ\"ל וכ\"כ הרי\"ף ז\"ל והם דברי הגמרא בפרק הנזכר על מתניתין דג' אחים ב' מהם נשואין ב' אחיות ואחד נשוי נכרית גירש אחד מבעלי אחיות את אשתו כו' ובסימן קע\"ג גבי אשת אחיו שלא היה בעולמו כתבתי בזה לדעת הרמב\"ם ז\"ל:","\u0003ג' אחים ב' מהם נשואין ב אחיות ואחד נשוי נכרית כו'\u0004 שם (ל.) ב' מהם נשואין ב' אחיות ואחד נשוי נכרית גירש אחד מבעלי האחיות את אשתו ומת נשוי נכרית וכנסה המגרש ומת זו היא שאמרו וכולן שמתו או נתגרשו צרותיהן מותרות ופירש\"י כנסה המגרש ומת. מותרת זו להתייבם שהרי עד שלא כנסה גירש את הראשונה שהיא ערוה ולא היתה צרתה מעולם וזהו שאמרו בפרק ראשון נתגרשו העריות צרותיהן מותרות.","ומ\"ש אבל אם מת נשוי נכרית קודם שגירש אחד מבעלי האחיות את אשתו אפילו אם לא כנס הנכרית ומת שנמצא שהיתה צרת ערוה בזיקה אסורה לאח הנשאר אפי' גרשה הערוה קודם שמת שם בגמרא אמתני' טעמא דגירש ואח\"כ מת אבל מת ואח\"כ גירש אסורה אמר רבי אשי זאת אומרת יש זיקה אפי' בתרי אחי","\u0003ומ\"ש וכ\"ש אם לא גירש הערוה ומת פשוט הוא:\u0004 ","ומ\"ש אבל אם כנס בעל האחות את הנכרית וגירש הערוה ומת ל\"ש גירש קודם שכנס הערוה (הנכרית) ל\"ש אח\"כ מותרת הנכרית לאח הנשאר שם אהא דאמר רב אשי זאת אומרת יש זיקה אפילו בתרי אחי כתב הרא\"ש וקודם שגירשה היתה זקוקה לב' אחים נשואין ב' אחיות והו\"ל צרת אחות אשה בזיקה הילכך אסורה עליו עולמית וא\"ת היאך כנסה המגרש הא הויא לכל אחד ואחד צרת אחות אשה בזיקה וי\"ל דלא שייך למיקרי צרת ערוה אלא כשהיא והערוה נופלים בבת אחת כשמת המגרש היתה היא צרת אשתו ונפלו שתיהם בבת אחת לפני האח הג' אבל כשהוא חי לא:","ומ\"ש בה\"ג אם מת ולא גירש אסורה לתרוייהו לא שתאסר להם בחייהם אלא לכל אחד כשימות אחיו תהיה אסורה לו דהויא צרת אחות אשה בזיקה וכ\"כ הרי\"ף ז\"ל דלא אסורה נכרית אלא אחר שמת המגרש עכ\"ל ובפ\"ק אהא דתנן כיצד אם מתו הן צרותיהן מותרות היתה בתה או אחת מכל העריות האלו נשואה לאחיו ולו אשה אחרת ומתה בתו או שנתגרשה ואח\"כ מת אחיו צרתה מותרת אמרינן בגמרא אליבא דרבה דל\"ש גירש ולבסוף כנס ל\"ש כנס ולבסוף גירש צרת מותרת וכן פסקו הפוסקים ז\"ל:","שני אחים פקחין נשואין ב' אחיות קטנות או חרשות ומת אחד מהם תצא משום אחות אשה שהרי נשואי שתיהן שוות: אחת פקחת ואחת חרשת מת בעל החרשת תצא משום אחות אשה מת בעל הפקחת בעל חרשת מוציא את אשתו בגט לפי שקידושי הפקחת לפיקח שהן דאורייתא אוסרת את אשתו עליו משום אחות זקוקה שאין כח בקידושי אשתו לדחות הפקחת משום אחות אשה לפיכך מוציא את אשתו בגט ואת אשת אחיו בחליצה כך היא הגירסא הנכונה בספרי רבינו המדוייקים ויש קצת ספרים שיש בהם חסרון הניכר והבבא הראשונה היא משנה בפרק ב\"ש (יבמות דף קט.) והבבא השנייה היא משנה בפרק חרש (דף קיב:):","ומ\"ש היתה אחת גדולה ואחת קטנה מת בעל הקטנה תצא משום אחות אשה מת בעל הגדולה היא אוסרת הקטנה עליו כדפרישית גבי פיקח וחרשת. ומלמדים את הקטנה שתמאן בבעלה וייבם הגדולה משנה בפרק ב\"ש (יבמות דף קט.) ב' אחים נשואין ב' אחיות גדולה וקטנה מת בעלה של קטנה תצא משום אחות אשה מת בעלה של גדולה ר\"א אומר מלמדין את הקטנה שתמאן בו ר\"ג אומר אם מיאנה מיאנה ואם לאו תמתין עד שתגדיל ותצא הלה משום אחות אשה ר' יהושע אומר אי לו על אשתו ואי לו על אשת אחיו מוציא את אשתו בגט ואשת אחיו בחליצה ומסיק בגמ' הלכה כר\"א ופירש\"י תצא משום אחות אשה. ופטורה מחליצה ומיבום: מת בעלה של גדולה. ונפלה לפני בעל הקטנה זיקתה של גדולה שהיא מן התורה אוסרת הקטנה עליה דנישואיה מדרבנן ולא אלימי לאפקועי זיקה דאורייתא והו\"ל אחות זקוקתו: ר' אליעזר אומר מלמדין את הקטנה שתמאן בו. ותעקור נישואיה ויהא מייבם את הגדולה וכתב ר\"י בשם הרמ\"ה ואם לא מיאנה הקטנה והגדילה ל\"ש בא עליה לאחר שהגדילה ל\"ש לא בא עליה מוציא את אשתו בגט ואת אשת אחיו בחליצה דקי\"ל יש זיקה:","\u0003שני אחים אחד פיקח ואחד חרש נשואין לב' אחיות פקחות או אחת פקחת ואחת חרשת כו'\u0004 עד דכמו שכנס אחיו ברמיזה כך יוציא גם הוא ברמיזה הכל מבואר במשנה (פרק חרש קי\"ב):","שני אחים אחד פיקח ואחד חרש והחרש נשוי ב' נשים פקחות ואחת מהן ערוה על הפיקח כו' עד סוף הסימן ירושלמי בפרק חרש וכתבו הרמב\"ם ז\"ל בס' פ\"ז ואיתא תו בירושלמי בתו חרשת נשואה לאחיו חרש צרתה פטורה מן החליצה ומן היבום וכתב ה\"ה שהשמיטו הרמב\"ם ז\"ל לפי שהוא מתבאר במ\"ש:"],["\u0003יבמה שאינה ראוייה להתייבם וכו'\u0004 משנה פ' ד' אחין (יבמות דף ל\"ב) ואפילו נפלה לפניו פעם אחרת וכו' משנה שם (דף ל') ופרכינן בגמ' למה לן למיתני הך דב' אחים דכיון דאפילו בג' אחים דבנפילה קמייתא לא אידחיא לה לגמרי דהא קא נשוי נכרית שזקוקה לייבום וקורא אני בה בשעת נפילה יבמה יבא עליה אפילו הכי חשבינן לה לגבי בעל אחותה כאשת אח שיש לה בנים לאתסורי עליה אפי' לאחר מיתת אחותה גבי ב' אחים דקא מידחיא מהאי ביתא לגמרי בשעת נפילה דאין כאן זיקת יבום עליה מיבעיא ומשני תנא הך דשני אחין תנא ברישא והך דג' אחין חזיא להיתירא ושיירה והדר חזיא לאיסורא ואיידי דחביבא ליה אקדמה ומשנה לא זזה ממקומה וכיון דהך דג' אחין רבותא היא כתב רבינו תחלה הך דב' אחין ואח\"כ כתב הך דג' אחין בדרך לא זו אף זו. וז\"ש ואפי' נפלה לפניו פעם אחרת וכו' אבל הרמב\"ם בפ\"ז כתב כסדר המשנה בתחלה כתב דג' אחין ואח\"כ וכן ב' אחין וכו' ולשון וכן אינו מדוקדק דבכל דוכתא משמעו לשון לא זו אף זו:","\u0003ומ\"ש ל\"ש מתה אשתו וכו'\u0004 (שם בדף ל') מימרא דרב ואשמועינן רבותא דלא מיבעיא היכא דמתה אחר שכנס השלישי דלא הוית חזיא ליה כל זמן נפילה הראשונה כיון דאשתו היתה קיימת שהיא אחותה אלא אפי' מתה ואח\"כ כנס השלישי דאיכא למימר דאיחזיא ליה בסוף נפילה הראשונה כשמתה אשתו מקמי דכנסה השלישי ואפ\"ה אסורה עליו אף לאחר שנפלה לפניו פעם אחרת ה\"א בגמרא ופירש\"י ורבינו דכתב אע\"פ שלא היתה אסורה עליו בנפילה אחרונה הוא תמוה דכתב היפך הגמרא והב\"י בפירושו הוסיף תימה על תימה שכתב כלומ' שלא היתה אסורה עליו בשעת נפילה אחרונה שמתה אשתו קודם שכנס נשוי נכרית את היבמה וכו' עכ\"ל דהלא אע\"פ שמתה אשתו לאחר שכנס נשוי נכרית אח היבמה אם מתה מקמי שמת נשוי נכרית נמי לא היתה אסורה עליו בנפילה אחרונה כיון שכבר מתה אשתו שהיא אחותה כשנפלה באחרונה ולבי אומר לי דט\"ס הוא וצ\"ל בנפילה ראשונה ורצונו לומר בסוף נפילה ראשונה הוית חזיא ליה ואפ\"ה אסורה כיון שהיתה אסורה לו בשעת נפילה הראשונה וזהו ששינה הלשון דבתחילה כתב בנפילה הראשונה כלומר בסוף נפילה וכאן כתב בשעת נפילה הראשונה כלומר מיד בתחילת נפילתה וכדאיתא בגמרא ואם לאו ט\"ס הוא יש ליישב ולומר דמה שכתב רבינו תחילה לא שנא מתה אשתו קודם שכנס השלישי וכו' פירושו כדקאמר בגמרא ופירש\"י דהרבותא הוא אע\"פ שמתה אשתו קודם שכנס השלישי:","\u0003ומ\"ש אחר כך אף על פי וכו'\u0004 הוא רבותא אחרת וקאי אהיכא שמתה אחר שכנס השלישי והכי קאמר לא מיבעיא במתה לאחר מיתת השלישי דהיתה אסורה עליו מיד בשעת נפילה אחרונה דפשיטא דאסורה דלא עדיפא נפילה אחרונה מנפילה הראשונה אלא אעפ\"י שמתה אשתו ואח\"כ מת השלישי דלא היתה אסורה עליו בשעת נפילה אחרונה אפ\"ה אסורה:","\u0003ומ\"ש אפ\"ה אסורה לו היא וצרתה וכו'\u0004 כ\"כ התוס' (דף ל') בד\"ה ונאסרה וז\"ל ה\"מ למינקט ואחד מופנה אלא נקט הכי משום דנכרית נמי מיתסרא לפי שהיתה צרת אחות אשה שעה אחת עכ\"ל ונראה דלאו דוקא קאמרי דבעינן שתהא צרת א\"א שעה אחת דהא מדרב שמעינן דאפי' מתה ואח\"כ כנס השלישי נמי אסורה היא וצרתה ואעפ\"י שלא היתה צרת א\"א אפי' שעה אחת אלא נאסרה כיון דהו\"ל צרת ערוה בשעת נפילה אחרונה וכ\"כ ה\"ה בפ\"ז אלא דהתו' בפי' למתני' דמדברת במתה אחר שכנס השלישי כתבו ג\"כ בהך לישנא דהיתה צרת אחות אשה שעה אחת אבל למסקנא דרב בכל ענין אסורה היא וצרתה ופטור אף מלחלוץ והכי משמע מדברי רבינו. מיהו נראה פשוט דכל זה דוקא במת אחד מן האחין הנשוי א' מן האחיות תחילה אבל במתה אחת מן האחיות ואח\"כ מת בעלה של שנייה שריא להתייבם מיד אף לאח שהיה נשוי אחותה כיון דבשעת נפילה לא היתה ערוה עליו וקי\"ל דמיתה מפלת ועוד פי' התוס' לשם דאפי' למ\"ד נשואין מפילין ומתה אחת מן האחיות תחלה ואח\"כ מת בעלה של שנייה וכנס נשוי נכרית את אשתו ומת שמותרת לראשון ואפי' מיד היתה מותרת לו דלא אמרינן בכה\"ג נישואין מפילין ע\"ש:","\u0003ומ\"ש אבל אם מותרת לו בשעת נפילה וכו'\u0004 שם (דף כ\"ז) הכל מודים בזה:","\u0003ומ\"ש אבל אם מתה הראשונה וכו'\u0004 שם פליגי בה רב ור\"י והלכה כר\"י לגבי רב דאחרונה לא הותרה להתייבם מיהו חליצה בעיא:","\u0003וכן אם היו שם עוד אחין וכו'\u0004 שם בסוגיא אליבא דר' יוחנן ומביאו ב\"י:","ומ\"ש וקדם וחלץ דמשמע אבל לכתחילה לא כך מבואר לשם בפירש\"י גזירה דילמא אתי למיעבד איפכא באלו הצרות עצמן וכ\"כ התוס' בשם ר\"י ושחזר ממה שפי' תחילה לאסור אפי' בדיעבד:","\u0003ומ\"ש ושאר האחין אסורין בשתיהן וכו'\u0004 פי ואפילו אם קדמו וכנסו נמי מוציאין מידם כמ\"ש בסמוך:","\u0003ארבעה אחין וכו'\u0004 משנה ר\"פ ד' אחין:","\u0003ומ\"ש קודם שהספיקו וכו'\u0004 פי' דאילו הספיקו לייבם לראשונה כבר פקעה זיקה ואף השנייה מתייבמת:","ומ\"ש קדמו וכנסו אין מוציאין אותה מידם ואיכא לתמוה כיון דהרי\"ף והרא\"ש הביאו סתם מתני' דאם קדמו וכנסו יוציאו ר\"א אומר ב\"ש אומרים יקיימו ובה\"א יוציאו ומשמע דר\"א אתא לאפוקי מאבא שאול דברייתא דב\"ה מיקל דיקיימו וקאמר ר\"א דליתא וכמו שפי' התוס' ומ\"ה לא הביאו הרי\"ף והרא\"ש הברייתא דאבא שאול וכ\"כ הרמב\"ם בפ\"ז ותו דבפ' שני דיבמות כתב הרא\"ש דדוקא בספק אחות זקוקתו דאיכא למימר בכל חד דידיה קא מתרמיא ליה התם הוא דאם קדמו וכנסו אין מוציאין אבל ודאי אחות זקוקתו כי הכא אפי' כנס מוציאין מידו וכן כתב רבינו בשמו בסימן קע\"ו וא\"כ קשה היאך פסק כאן בהיפך דאפי' ודאי אחות זקוקתו אין מוציאין וכאבא שאול ונראה דט\"ס הוא וצ\"ל קדמו וכנסו מוציאין אותם מידם מיהו אפשר ליישב ולומר דרבינו סובר דכשמתו בבת אחת אפשר לצמצם וכר\"י הגלילי אלא דלא ידעינן הי נפול ברישא ולפיכך אם קדמו וכנסו ולא ידעינן נמי הי כנס ברישא כל חד מצי אמר חבראי שנייה ייבם אנא ראשונה מייבם וליכא אלא ספק אם פגע באחות זקוקתו ולכן אין מוציאין מידם ודכוותא בזה אחר זה ולא הספיקו וכו' היינו דשוב לא נודע מי מת ראשון וקדמו וכנסו ולא ידעי הי כנס ברישא אין מוציאין מידם משום דכל חד מצי אמר וכו' כמו במתו בבת אחת כדפי' אבל במתו בזה אחר זה ונודע מי מת ראשון אע\"פ דלא ידעינן הי כנס ברישא הא ודאי דאין מוציאין מיד אותו שכנס הראשונה מצי אמר חבראי כנס ברישא שנייה ואנא ראשונה מייבם בתר הכי אבל אותו שכנס השנייה לא מצי נמי אמר חבראי כנס הראשונה ברישא ופקע לה איסור אחות זקוקה דסוף סוף שנייה אסורה ליה כיון שלא הותרה מתחילה אלא דקשה דאע\"פ דהדין דין אמת מ\"מ הוה ליה לרבינו לפרש דבריו גם קשה לפ\"ז למה השמיט דין המשנה דכשאין שם ספק וקדמו וכנסו דמוציאין מידם וכמו שפסקו הרי\"ף והרא\"ש והרמב\"ם אלא כדפי' עיקר דט\"ס הוא וצ\"ל קדמו וכנסו מוציאין אותם מידם ומה שקשה מהא דתנן שומרת יבם שקדש אחיו את אחותה דקי\"ל דאסור לו לכונסה ואם קדם וכנס מותר לקיימה כדלעיל ס\"ס קנ\"ט פירשו התוס' בפ\"ב (דף י\"ח) בד\"ה א\"ל המתן דהתם אחות יבמה אתיא לכלל היתר לאחר שיעשה אחיו מעשה לא החמירו להוציא אבל הכא גבי ד' אחין דהאחיות לא באות לעולם לכלל היתר שכל אחת אחות זקוקתו החמירו עכ\"ל ואכתי קשה על מ\"ש ה\"ה בפ\"ז ואף בשאין ידוע איזה מהן מת ראשון אם קדמו וכנסו יוציאו עכ\"ל דהא ודאי ליתא כדאמרינן בגמרא בשלמא ראשון אמרינן ליה מאן שרא לך אלא שני אמר חבראי שנייה יבם אלא ראשונה מייבם וצ\"ע:","\u0003וכתב הרמב\"ם מת זה וכו'\u0004 בפ\"ז כ\"כ והוא מבואר במשנה שם (דף ל') ומ\"ש בשם הרא\"ש כ\"כ גם הרי\"ף לשם ולעיל בסי' קע\"ג סוף ס\"ט כתב ב\"י שגם הרמב\"ם תופס שיטתם:","\u0003ג' אחים וכו'\u0004 משנה שם (דף ל') ג' אחים ב' מהם נשואין ב' אחיות ואחד נשוי נכרית גירש א' מבעלי אחיות את אשתו ומת הנשוי נכרית וכנסה המגרש ומת זו היא ששנינו וכולן אם מתו או נתגרשו צרותיהן מותרות ובגמרא טעמא דגירש ואח\"כ מת אבל מת ואח\"כ גירש אסורה א\"ר אשי זאת אומרת יש זיקה ואפי' בתרי אחי ופירש\"י ואח\"כ גירש ונשאה לזו הואיל וקודם שגירש נעשית צרתה בזיקה אסורה על אחיו כשימות המגרש משום צרת אחות אשה בשלמא אי לא כנסה היתה מותרת לזה מחמת זיקת אחיו הראשון אבל משכנסה ועכשיו זקוקה לזה מכח בעל הערוה אסורה ואע\"ג דלא היתה צרתה אלא בזיקה עכ\"ל ובתר הכי גרסינן ולרבא הניחא אי ס\"ל כרב אשי זו היא למעוטי מת בלא גירש ופירש\"י ולרבא דאמר מיתה מפלת וכנס ואח\"כ גירש שריא הניחא אי סבר כרב אשי דיש זיקה זו היא למעוטי מת בלא גירש ולא דייק למתני' כרב אשי דאמר הא מת ואח\"כ גירש אסורה דהא רבא מיתה מפלת ס\"ל וכיון דגירש שריא אלא הכי דייק טעמא דגירש דבשעת מיתה לאו צרות הוו זו היא דנכרית מותרת אבל מת שני זה אחר ראשון ולא גירש את אשתו ואפי' לא כנס את הנכרית אסורה דהואי צרת אחות אשה בזיקה ואפי' בשעת מיתה דכיון דיש זיקה הוי כאילו באה אף מכח השני וא\"ת הואיל וזיקה חשובה להיות עליה כח השני הויא אשת ב' מתים דבלאו איסור דאחיות נמי אסורה לא היא דזיקת ב' יבמין דאסורה ליתא מדאורייתא ולא גזור רבנן אלא היכא דעביד בה מאמר גזירה שמא יאמרו ב' יבמות הבאות מבית אחד מתייבמות עכ\"ל ואסיקנא דרבא כרב אשי ס\"ל והרי\"ף והרא\"ש פסקו פ\"ק דיבמות כרבא דאמר מיתה מפלת ול\"ש כנס ולבסוף גירש הערוה ל\"ש גירש הערוה ולבסוף כנס צרתה מותרת ובפ\"ב דיבמות פסקו כשמואל דיש זיקה וכך פסקו שאר פוסקים וא\"כ לפי פי' רש\"י כל שגירש הערוה מותרת הנכרית אפי' מת נשוי הנכרית קודם שגירש הערוה אינה אסורה הנכרית אלא בדלא גירש הערוה ואע\"פ דלא כנס לנכרית ומת אסורה הנכרית לאח הנשאר אבל רבינו פסק דאם מת נשוי נכרית ואח\"כ גירש ומת אסורה ונראה דנמשך אחר מ\"ש הרי\"ף והרא\"ש בפ' ד' אחין שכתבו להך דרב אשי דאמר טעמא דגירש ואח\"כ מת אבל מת ואח\"כ גירש אסורה א\"ר אשי זאת אומרת יש זיקה ובע\"כ צ\"ל דפסקו כרבא דאמר מיתה מפלת דגם רב אשי ס\"ל דמיתה מפלת דלא כפירש\"י דאי הוו מפרשים כפירש\"י היו דבריהם סותרין זא\"ז אלא צ\"ל דמפרשים דלרבא נמי דוקא בדכנס הנכרית התם הוא דמיתה מפלת ושריא הנכרית אם גירש הערוה אע\"פ דכנס ואח\"כ גירש אבל אם לא כנסה התם הוא דקאמר רב אשי דאם מת ואח\"כ גירש אסורה דכיון דהיתה צרת ערוה בזיקה גזרינן טפי גירש אטולא גירש משום זיקה דעלמא שמא יבא לייבם אותה ואפי' לא גירש כיון שאין איסור זה ידוע לכל וכ\"פ הרמב\"ם פ\"ז והוא מ\"ש הרי\"ף בטעמא קמא ולפ\"ז אף לרבא זו היא למעוטי מת ואח\"כ גירש כרב אשי והיינו דוקא בלא כנס ומטעם גזירה ולא פליגי וגרסינן בגמרא הניחא אי סבר כרב אשי דיש זיקה זו היא למעוטי מת ואח\"כ גירש וכך הם דברי רבינו ומ\"ש במקצת ספרי רבינו אפי' אם לא כנס וכו' צריך להעביר הקולמוס על תיבת אפי' דדוקא בלא כנס משום דגזרינן גירש אטו לא גירש והיינו כרב אשי כדפי' וז\"ש וכ\"ש אם לא גירש הערוה ומת:","\u0003ומ\"ש אבל אם כנס כו'\u0004 היינו כרבא דאמר מיתה מפלת. מיהו קשה שכל זה דלא כמ\"ש הרא\"ש וז\"ל טעמא דגירשה ואח\"כ מת וכנסה המגרש ומת הוא דשריא אבל מת ואח\"כ גירשה וכנסה המגרש ומת אסורה אמר רב אשי זאת אומרת וכו' דכתב כפי' רש\"י דבכנסה קאמר רב אשי דאסורה וגם קשה בדברי הרא\"ש שסותר מ\"ש בפ\"ק כרבא דל\"ש כנס ולבסוף גירש ל\"ש גירש ולבסוף כנס צרתה מותרת ונראה ליישב דהרא\"ש סובר מדכתב הרי\"ף במסקנתו לחלק בין צרת ערוה דעלמא דאם גירש הערוה דצרתה מותרת ולא גזרינן גירש אטו לא גירש והכא גזרינן דהיינו טעמא דהתם גבי ערוה כיון דגירשה מקמי דנפלה לה קמי יבם מהני בה גירושין דכי נפלה צרה קמי יבם בהיתירא נפלה קמיה אבל הכא גבי נכרית כיון דבשעת נפילה באיסור זיקה נפלה קמיה לא מהני בה גירושין ולא מידי והאי טעמא טפי עדיף ומסתבר מההוא קמא ע\"כ השתא ודאי לא קשיא דאע\"פ דהכא גבי נכרית בכנסה המגרש אסורה אפ\"ה הלכה כרבא בצרת ערוה דעלמא דשריא צרתה אע\"פ דכנסה ואח\"כ גירש הערוה משום דכי נפלה בהיתירא נפלה וס\"ל להרא\"ש דבמת ואח\"כ גירש ולא כנסה כלל ומת אף הרי\"ף מודה דהנכרית מותרת דלא חשבינן לה צרת ערוה כיון דלא כנסה כלל וכמו שפירש\"י לרב אשי וסובר נמי דלרבא ג\"כ זו היא למעוטי מת ואח\"כ גירש וכנסה ומת דאסורה כרב אשי ואע\"פ דסובר בצרת ערוה דעלמא מיתה מפלת הכא שאני מאחר דבשעת נפילה באיסור זיקה נפלה ודלא כפי' רש\"י בזה גם ה\"ה כתב ע\"ש הרשב\"א דאף לדעת הרי\"ף אם לא כנס הנכרית נכרית מותרת ושיטה זו ברורה וסברא נכונה היא ולא ידעתי אמאי לא הביא רבינו דעת הרא\"ש בזה ולפע\"ד שהוא העיקר גם ה\"ר ירוחם לא הביאו כי אם דעת הרא\"ש ע\"ש:","\u0003היתה אחת גדולה ואחת קטנה וכו'\u0004 משנה בפרק ב\"ש פליגי בה תנאי והלכה כר\"א דמלמדין את הקטנה שתמאן בו וכתב הר\"ר ירוחם בשם הרמ\"ה אם לא מיאנה הקטנה והגדילה ל\"ש בא עליה לאחר שהגדילה ול\"ש לא בא עליה לאחר שהגדילה מוציא את אשתו בגט ואת אשת אחיו בחליצה דקי\"ל יש זיקה וליכא דמפקע לה לזיקה ע\"כ ומביאו ב\"י ונראה דכתב כך ע\"פ פירש\"י פ\"ב (דף י\"ח) ובפרק ב\"ש (יבמות דף ק\"ט) דטעמא דר\"ג דאמר אם מיאנה מיאנה ואם לאו תמתין עד שתגדיל ותצא הלזו משום אחות אשה משום דס\"ל אין זיקה אבל ר' יהושע דאמר אוי לו על אשתו וכו' ולא יתבה תותיה משום אחות זקוקתו ס\"ל יש זיקה וא\"כ אנן דקי\"ל יש זיקה אם לא מיאנה עבדינן כרבי יהושע ומוציא אשתו בגט ואשת אחיו בחליצה וקשיא לי דבפרק ד' אחין (יבמות דף כ\"ט) אמתני' דג' אחין ב' נשואין ב' אחיות ואחד מופנה וכו' זו היא שאמרו אוי לו על אשתו ואוי לו על אשת אחיו קאמר בגמ' זו היא למעוטי הך דרבי יהושע דלא עבדינן כוותיה אלא אי כר\"ג אי כר\"א וי\"ל דהרמ\"ה מפרש דה\"ק אי כר\"ג למ\"ד אין זיקה ואי כר\"א למ\"ד יש זיקה ור\"ל דלכתחילה עבדינן כר\"א אבל בדיעבד אם לא מיאנה בע\"כ צריכין למיעבד כרבי יהושע דקי\"ל יש זיקה מיהו נלפע\"ד דמ\"ש הרמ\"ה אינו אמת אלא תלמודא כפשוטו קאמר דעבדינן כר\"א או כר\"י דלכתחילה עבדינן כר\"א דמלמדין אותה שתמאן ואם לא מיאנה כר\"א עבדינן כר\"ג דתמתין עד שתגדיל ואע\"ג דקי\"ל יש זיקה אפ\"ה הקילו בקידושי קטנה טפי מבעלת מאמר כדכתבו התוס' לשם בד\"ה אי כר\"ג משום דכנוס היא אצלו מזמן גדול והא דקאמר בפ\"ב (דף י\"ח) ואי אין זיקה תיבטל דהא ר\"ג אמר אין זיקה ומותר לבטל מצות יבמין דתנן ר\"ג אומר אם מיאנה וכו' אין פירושו דמהאי מתני' שמעינן לר\"ג דאין זיקה מדשרי קטנה עליה כדפי' רש\"י דהא ליתא אלא אפילו למ\"ד יש זיקה שריא קטנה כדפי' אלא ממאי דקאמר ר\"ג בפרק ר\"ג (יבמות דף נ\"א) שמעינן דס\"ל אין זיקה וכ\"כ רש\"י בפ\"ב ותוס' דבפרק הערל (סוף יבמות דף ע\"ט) קמותיב אביי לרבה וליתי איסור פצוע דכא וידחה עשה דייבום מי לא תנן ר\"ג אומר אם מיאנה מיאנה וכו' מדקא מותיב מיניה לרבה ורבא בפ\"ב לשם (דף י\"ח) יש זיקה ס\"ל אלמא דאף למ\"ד יש זיקה עבדינן כר\"ג בקטנה והכי מוכח בתוס' פרק ב\"ש ריש (יבמות דף ק\"י) בד\"ה קסבר שמואל שכתבו וז\"ל וברפ\"ב משמע דשמואל אית ליה מילתא דר\"ג דפריך ממילתיה ואי אין זיקה תיבטל דהא אר\"ג וכו' והשתא אי איתא דהתוספות ס\"ל כפירש\"י דטעמיה דר\"ג משום דאין זיקה א\"כ אי אפשר לומר דשמואל ס\"ל כר\"ג דהא ברפ\"ב איתא להדיא דשמואל יש זיקה ס\"ל אלא בע\"כ דעת התוס' דהך דר\"ג הילכתא היא אף למ\"ד יש זיקה משום דכנוסה היא אצלו מזמן גדול כמ\"ש התוס' בפרק ד' אחין והא דפסק שמואל הלכה כר\"א דמלמדין את הקטנה שתמאן היינו לכתחילה אבל דיעבד אם לא מיאנה עבדינן כר\"ג דתמתין עד שתגדיל והכי נקטינן ודלא כהרמ\"ה:"]],["\u0010c0\u0011\u0010y0\u0011מי שקידש אחת מב' אחיות ואינו יודע איזו קידש אפילו לא הוכרו מעולם שלא ניתנו לביאה הוו קידושין וצריך גט לכל אחת ואחת מת ולו אח חולץ לשתיהן שאינו יכול לייבם לא' ולחלוץ לשנייה שמא ישא אחות זקוקתו ולא לחלוץ לאחת ולייבם לשנייה שמא ישא אחות חלוצתו היה לו ב' אחין אחד חולץ ואחד מייבם לשנייה שאם היא זקוקתו הרי טוב ואם אינה זקוקתו היא לו כאשה נכרית ואחות זקוקה אינה שהרי כבר חלץ אחיו לאחותה קדמו ב' אחין וכנסו את שתיהן אין מוציאין אותן מידן שכל אחד ואחד יאמר הזקוקה נזדמנה לי ואפילו לא נזדמנה לי הזקוקה פקע האיסור כשייבם אחיו \u0010c1\u0011וכתב א\"א הרא\"ש ז\"ל דוקא היכא שכל אחד ואחד אומר כנסתי הזקוקה אבל מי שעבר וייבם אחות זקוקתו בודאי יוציא כיון שבא עליה באיסור בודאי צריך להוציא ואפ\"ה דוקא שקדמו וכנסו קודם שנמלכו בבית דין אבל אם נמלכו בב\"ד ואמרו להם שיחלוץ האחד וייבם הב' והלכו שניהם ויבמו יוציאו כיון שעברו על דברי ב\"ד \u0010c2\u0011\u0010y1\u0011ב' שקידשו ב' אחיות זה אינו יודע איזו קידש וזה אינו יודע איזו קידש ומתו ולזה אח ולזה אח כל אחד חולץ לשתיהם ואין שום אחד מהם יכול לייבם כדפי' לעיל \u0010c3\u0011לזה אחד ולזה ב' היחיד חולץ לשתיהן והשנים אחד חולץ לאחת תחילה ואח\"כ מייבם הב' לשנייה אבל לא ייבם קודם שיחלוץ היחיד אפי' אחר חליצת אחיו שמא יפגע ביבמה לשוק קדמו השנים וכנסו אחר שחלץ היחיד אין מוציאין מידם \u0010c4\u0011אפי' שניהם כהנים שכל אחת אינה אלא ספק חלוצה שחליצת אחת מהם אינה כלום וספק חלוצה לא גזרו בה רבנן \u0010c5\u0011היו לזה ב' אחין ולזה ב' אחין אחיו של זה חולץ לא' ואחיו של זה חולץ לאחרת ואח\"כ בא האח הב' של זה ומייבם חלוצתו של זה והאח הב' של זה מייבם חלוצתו של זה ואם קדמו שני האחים של האחד וחלצו לשתיהן לא ייבמו הב' האחין האחרים של הב' לשתיהן אלא אחד חולץ וא' מייבם לשנייה קדמו הב' האחרונים וכנסו אחר שחלצו ב' הראשונים אין מוציאין מידם \u0010c6\u0011\u0010y2\u0011מי שהלך בעלה למ\"ה ושמעו שמת וניסת ואח\"כ בא בעלה ומתו שניהם ולזה אח ולזה אח אחיו של זה ושל זה חולצין ולא מייבמין. \u0010y3\u0011האשה שהיו לה בנים ולכלתה בנים וילדה היא וכלתה ב' זכרים במחבא ונתערבו הבנים וגדלו התערובות ונשאו נשים ומתו בני הכלה חולצין לשתיהם תהלה ולא מייבמין שכל אחת משתיהן ספק אם היא אשת אחיו שהיא מותרת לו או אם היא אשת אחי אביו שהיא ערוה לו ובני הזקנה אחר חליצת בני הכלה חולצין או מייבמין שאם היא אשת אחיו הרי היא יבמה ואם היא אשת בן הכלה הרי היא אשת בן אחיו ומותרת לו שכבר נחלצו מתו הבנים הודאין של הזקנה והכלה והספקות קיימין הספקות לנשי בני הזקנות חולצין ולא מייבמין שהיא ספק אשת אחי אביו ולנשי בני הכלה אחד מהספקות חולץ לה תחלה והשני מייבם ממה נפשך אם זה שחלץ בן הכלה הוא הרי חלץ לאשת אחיו וא\"כ הספק השני הוא בן הזקנה ומותר לו לישא אשת בן אחיו אחר שנחלצה מיבמה ואם זה שחלץ תחלה הוא בן הזקנה הרי חלץ לאשת בן אחיו ולא עשה ולא כלום א\"כ הספק השני הוא בן הכלה והרי הוא מייבם את אשת אחיו \u0010y4\u0011מי שלא שהתה אחר בעלה ג' חדשים וניסת וילדה ואין ידוע אם הוא בן ט' לראשון או בן שבעה לאחרון והיו לה בנים מן הראשון ומן השני וגדל הספק ונשא אשה ומת בנים מן הראשון ומן השני חולצין ולא מייבמים שלכל אחד מהם הוא בספק שמא אחיו הוא מן האם ולא מן האב וכן הספק לנשותיהן חילץ ולא מייבם היו לראשון ולשני לכל אחד בן אחד מאשה אחרת ומתו זה הספק חולץ או מייבם לנשותיהם שאם הוא אחיו מאביו הרי הוא יבמתו ואם אינו אחיו נכרית היא לו ומותר בה כיון שאין לה יבם אחר שתהא זקוקה לו מת הספק אחד מב' הבנים הודאי חולץ לה תהלה והשני מייבם ממה נפשך אם הוא אחיו הרי היא יבמתו ואם אינו אחיו נכרית היא לו וכבר נחלצה מחאה הא' שהוא יבמה \u0010c7\u0011\u0010y5\u0011ה' נשים שהיה לכל אחת בן ידוע ונתערבו חמשתן וילדו כאחת במחבואה וגדלו התערובות ונשאו נשים ומתו ונפלו נשותיהן לפני ה' הבנים הודאין שאין אחד מהם יודע איזו היא אשת אחיו זו היא תקנתם ארבעה מהודאין יחלצו לאחת והה' ישאנה אחר שנחלצה ד' חליצות שאם היא אשת אחיו הרי היא יבמה ואם אינה אשת אחיו נכרית היא לו וכבר נחלצה מיבמה שאחד מאלו הד' שחלצו לה היה יבמה וכן השנייה חולצין לה ד' והה' ישאנה נמצא שחמשתן נושאין ה' נשים אחר שנחלצה כל אחת ואחת ד' חליצות וה\"ה נמי שאחד יכול לישא כולן אחר שיחלצו לה הד' אלא שזה יותר טוב שמא יזדמן לכל אחד לייבם את יבמתו ואם מת אחד מהבנים הודאין ד' הספקות יחלצו לה והה' ייבם היו קצת הודאין כהנים וקצתם אינם כהנים הכהנים חולצים ולא מייבמים שמא יפגעו בחלוצה ושאינם כהנים מייבמים היו קצת הודאין שיש להם באלו הספקות אחים שהם אחים מן האם שלא מן האב וגם יש לו בהן אחים מן האב חולצים ולא מייבמין כגון יעקב נשא לאה והיה לה בן מבועז ואשה אחרת שיש לו לבועז ילדה עם לאה אשת יעקב ועם שלש אחרות במחבואה נמצא שבן בועז מלאה יש לו בתערובות אח מאם שלא מן האב שהוא בן לאה מיעקב ובן בועז מאשתו האחרת הוא אחיו מן האב לפיכך אינו יכול לייבם לשום אחת שמא היא אשת אחיו מאמו מקצתם כהנים ומקצתם שיש להם אחים מן האם אלו ואלו חולצים ולא מייבמים:",["\u0003מי שקידש אחת מב' אחיות ואינו יודע איזו קידש כו'\u0004 משנה בפ\"ב דיבמות (כג:) מי שקידש אחת מב' אחיות ואינו יודע איזו קידש נותן גט לזו וגט לזו מת ולו אח אחד חולץ לשתיהן היו לו ב' אחד חולץ ואחד מייבם קדמו וכנסו אין מוציאין מידם ובגמרא שם ש\"מ קידושין שאינם מסורין לביאה הוו קידושין הב\"ע כשהוכרו ולבסוף נתערבו וכתבו הרי\"ף והרא\"ש ז\"ל האי קושיא והאי פירוקא אליבא דרבא הוא דסבר קידושין שאינם מסורה לביאה לא הוו קידושין ולית הילכתא כוותיה דקי\"ל כאביי ביע\"ל קג\"ם והא חדא מינייהו הילכך בין הוכרו ולבסוף נתערבו בין לא הוכרו כלל נותן גט לזו וגט לזו כפשטא דמתניתין עכ\"ל ומ\"ש רבי' בשם הרא\"ש דוקא בשכל אחד וא' אומר כנסתי הזקוקה כו' שם אהא דתנן קדמו וכנסו אין מוציאין מידם מתיב בגמרא ומ\"ש מהא דתנן ד' אחים ב' מהם נשואים ב' אחיות ומתו הנשואים את האחיות הרי אלו חולצות ולא מתייבמות התם משום זיקה הכא כל חד וחד אימור דידיה קא מתרמיא ליה וכתב הרא\"ש מזה יכול לדקדק דוקא משום דאימור דידיה קא מתרמי ליה אבל המייבם אחות זקוקתו יוציא ונ\"ל שיש עוד לדקדק דוקא קדמו וכנסו שלא נמלכו בב\"ד אבל אם נמלכו בב\"ד ואמר להם שיחלוץ הא' וייבם הא' והלכו שניהם וייבמו מוציאין מידן ואף ע\"ג דאימר כל חד וחד דידיה מתרמי ליה כיון שעברו על דברי ב\"ד מוציאין וכך משמע מתוך פירש\"י ז\"ל עכ\"ל:","שנים שקידשו ב' אחיות זה אינו יודע איזו קידש וזה אינו יודע איזו קידש ומתו ולזה אח ולזה אח וכו' עד וקדמו השנים האחרונים וכנסו אחר שחלצו שנים הראשונים אין מוציאין מידם משנה וגמ' שם:","מי שהלך למ\"ה ושמעו שמת וניסת ואח\"כ בא בעלה ומתו שניהם ולזה אח ולזה אח אחיו של זה ואחיו של זה חולצין ולא מייבמין משנה פרק האשה רבה (דף פו) ובגמרא (דף צא:) אחיו של ראשון חולץ מדאורייתא ולא מייבם מדרבנן אחיו של שני חולץ מדרבנן ולא מייבם לא מדאורייתא ולא מדרבנן ופירש\"י ולא מייבם מדרבנן. רבנן קנסוה: אחיו של שני חולץ. דמדאורייתא לא קא רמיא עליה ורבנן הוא דאצרכוה חליצה משום גזירה שמא יאמרו גירש זה ונשא זה כדאמרינן לגבי גט:","האשה שהיו לה בנים ולכלתה בנים וילדה היא וכלתה שני זכרים במחבא ונתערבו הבנים וגדלו התערובות ונשאו נשים ומתו וכו' עד א\"כ הספק השני הוא בן הכלה והרי הוא מייבם את אשת אחיו משנה שם בפרק נושאין (דף צט):","מי שלא שהתה אחר בעלה ג' חדשים וניסת וילדה ואין ידוע אם הוא בן ט' לראשון או בן ז' לאחרון והיו לה בנים מן הראשון ומן השני וכו' עד וכבר נחלצה מן האח האחר שהוא יבמה ג\"ז משנה שם (דף ק.):","\u0003חמש נשים שהיה לכל אחת בן ידוע ונתערבו חמשתן וילדו כאחת במחבואה וכו'\u0004 עד סוף הסימן גם זה משנה שם:"],["\u0003מי שקידש אחת מב' אחיות וכו'\u0004 משנה פ\"ב (דף כ\"ג) ומ\"ש מת ולו אח וכו' כן פירש\"י לשם ומשמע דבייבומי ברישא ליכא משום אחות חלוצתו ולהכי קאמר דאיסוריה משום אחות זקוקתו וקשה דא\"כ אמאי לא תני ברישא באח אחד אם קדם וכנס לאחת וחלץ לשנייה דאין מוציאין כי היכי דתני בסיפא בשנים דהא ברישא נמי אם קדם וכנס לאחת וחלץ לשנייה ליכא משום אחות חלוצתו אלא דאיכא ספק אחות זקוקתו ואזלינן לקולא ואמרינן דפקע זיקה למפרע כשחלץ לשנייה וי\"ל דבאח אחד כיון שע\"י עצמו שחלץ לשנייה פקע זיקה למפרע לא הקילו אבל בנ\"י מפורש דדוקא בחלץ תחילה הוא דמוציאין כיון דאיכא ספיקא דהיא באיסור תחתיו דהיינו איסור אחות חלוצתו אבל בכנס תחלה ואח\"כ חלץ דפקע זיקה למפרע אין מוציאין מידו והכי מסתבר טפי ולא קשה א\"כ אמאי לא תני ברישא באח אחד קדם וכנס אין מוציאין מידו דיש לתרץ דלא פסיקא ליה כיון דבקדם וחלץ ואח\"כ כנס אסירא ליה להכי שבקא ותני להך בבא בסיפא קדמו וכנסו דממילא שמעינן דברישא נמי היכא דליכא איסורא אלא משום ספק אחות זקוקתו אין מוציאין כיון דפקע זיקה למפרע ולא משמע הכי מדברי שאר פוסקים שסתמו וכתבו כלשון המשנה וכמ\"ש רבינו:","\u0003ומ\"ש וכתב א\"א הרא\"ש דוקא וכו'\u0004 ע\"ל בס\"ס י\"ח ובמ\"ש לשם ועיין עוד בס\"ס קמ\"א ובסי' קע\"ה:","\u0003שנים שקידשו ב' אחיות וכו'\u0004 משנה שם ופירש\"י דכל חד וחד מינייהו אסור לייבומי דדלמא באחות זקוקתו פגע עכ\"ל כלומר אפי' היכא דליכא למיחש ליבמה לשוק כגון דחד חליץ לשתיהן מעיקרא ואחות חלוצתו נמי לא הויא כיון דייבם לחדא ברישא ולכי חליץ בתר הכי לשנייה פקע זיקה למפרע ואפ\"ה אסור לייבומי לכתחלה דדלמא קעביד איסורא מעיקרא דפגע באחות זקוקתו ומשמע דבקדם וכנס לא מפקינן מיניה כיון דליכא אלא ספק אחות זקוקתו והא דלא תני לה הכא קדם וכנס משום דלא פסיקא שהרי בחלץ תחלה איכא איסורא כדלעיל:","\u0003לזה אחד ולזה שנים וכו'\u0004 משנה שם:","\u0003ומ\"ש ואפי' שניהם כהנים שם תני שילא ואפי' שניהם כהנים וכו'\u0004 ואף ע\"ג דבגמרא איתא להא ברייתא אפיסקא דסיפא דהיו לזה ב' ולזה ב' כתבה רבינו בהיו לזה א' ולזה ב' דבמציעתא משום דלפי הטעם אין חילוק ותלמודא דקבעה לה אסיפא היינו משום דס\"ל דממשנה יתירה דסיפא דייק שילא הכי אבל במציעתא איכא למימר איידי דתני אחד חולץ ואחד מייבם תני נמי אם קדמו וכנסו אין מוציאין מידם אבל בסיפא דהך בבא דקדמו ב' וחלצו לא ייבמו השנים אלא א' חולץ ואחד מייבם לא איצטריכא ליה כלל דהיינו מציעתא בע\"כ דלא תני לה אלא משום הך דקדמו וכנסו וכו' לאשמעי' דאפי' שניהם כהנים אין מוציאין וממילא שמעינן דאף במציעתא נמי הכי דינא אלא דמסיפא מוכח הכי:","\u0003היו לזה ב' אחין וכו'\u0004 משנה שם ובסמוך כתב דאפילו שניהם כהנים וה\"ה הכא:","\u0003מי שהלך בעלה למ\"ה וכו'\u0004 משנה ר\"פ האשה רבה ובגמרא אחיו של ראשון חולץ מדאורייתא ולא מייבם מדרבנן דרבנן קנסוה דה\"ל למידק אחיו של שני חולץ מדרבנן לא מייבם לא מדאורייתא ולא מדרבנן ופסק הרי\"ף והרא\"ש לשם דבין נישאת ע\"פ ע\"א ובין נישאת ע\"פ ב' עדים בכל ענין קנסוה ולא אמרינן כניסה ע\"פ ב' עדים מאי ה\"ל למיעבד ולפיכך כתב רבינו בסתם ושמעו שמת וכו' לומר דבכל ענין הוה דינא הכי ודלא כרב פסק לעיל בסימן י\"ז:","\u0003חמש נשים וכו'\u0004 עד סוף הסימן בפ' נושאין ויש להקשות אמאי תנן חמש נשים וכדפריך בריש ד' אחין א\"ה תלתא נמי ויראה לי דלרבותא תני חמש נשים להיכא שיש למקצתן בהן אחין מן האם שלא מן האב דל\"מ ד' דהתם ודאי כיון דחדא כי מתייבמה עדיין נשארו ג' ואיסורא ברובא איתא וכי מתייבמה תו חבירתה ונשארו שתים נעשית גיף האיסור והלכך אפי' מתייבמת תו שלישית נשארה הרביעית באיסורא קמא אבל בחמש נשים סד\"א דכי מתייבמת שלישית איסורא ברובא איתא והמיעוט הנשארים מותרים לייבם אחר שחלצו לה הד' קמ\"ל דלא ובהא מתיישב מאי דהדר תני בברייתא מקצתם כהנים ומקצתן אחין מן האם אלו ואלו חולצין ולא מייבמין דלכאורה בבא שאינה צריכה היא דהא תני לה רישא מקצתן כהנים וכו' אבל למאי דפי' אתי שפיר דאתא לאשמועינן דלא תימא דדוקא במקצתן אחין מן האב בלבד התם הוא דאמרינן דאחין מן האם חולצין ולא אמרי' כיון דאיכא ה' נשים דבג' שנפרשו לשם הוא האיסור דאיסורא ברובא איתיה שהרי אין שם אלא פרישה בעלמא אבל במקצתן כהנים ומקצתן אחין מן האם דאיכא למימר כיון דכהנים חולצין ולא מייבמין ושריא לעלמא ה\"ל כאילו נאבדה מן העולם ואיסורא ברובא איתיה והשנים הנשארים מותרין להתייבם לאחר שחלצו לה הד' ולא חיישינן דילמא נסיב אשת אחיו מן האם קמ\"ל דלא ודוק. ועיין בי\"ד סימן ק\"י:"]],["\u0003הלכות אונס ומפתה \u0004\n\u0010c0\u0011\u0010y0\u0011המפתה או מאנס בתולת ישראל קונסין אותו נ' סלעים כסף \u0010y1\u0011בין אם היתה בת גדול שבישראל או בת קטן שבישראל \u0010y2\u0011ואיזהו מפתה ואיזהו מאנס מפתה לרצונה מאנס שלא לרצונה \u0010c1\u0011\u0010y3\u0011וכתב הרמב\"ם כל הנבעלה בשדה היא בחזקת אנוסה ודנין בו דין אונס עד שיעידו עדים שלרצונה נבעלה וכל הנבעלת בעיר היא בחזקת מפותה מפני שלא צעקה עד שיעידו שהיתה אנוסה כגון ששלף חרבו ואמר לה אם תצעק אני אהרוג אותך \u0010c2\u0011\u0010y4\u0011וכתב הראב\"ד חזקה זו איני יודע מה תועלת יש בה אם יש עדים יבאו ויעידו ואם אין עדים אין שם קנס ואם לענין שלשה דברים אם יש טענה ביניהם כלל גדול בדין המע\"ה והעיר והשדה שווים הם \u0010y5\u0011דין נ' סלעים הם הם קנס על המעשה הרע שעשה אבל מלבד זה צריך ליתן לה במפותה בושת ופגם אבל לא צער שאין למפותה צער ובאנוסה שיש לה צער צער ובושת ופגם \u0010y6\u0011ואלו אינן שוין בכל אדם אלא הכל לפי מה שהוא \u0010c3\u0011בושת הכל לפי המבייש והמתבייש שאינו דומה המבייש נערה חשובה ממשפחה מיוחסת למבייש בזויה וענייה ואינו דומה המתבייש מאדם חשוב למתבייש מאדם בזוי ונקלה לפ\"ז רואין ב\"ד מעלתו למעלתה ושמין כמה היה נותן אביה ומשפחתה ולא יארע להם דבר זה מאדם זה וכמוהו יתן לו. \u0010c4\u0011פגם רואין כמה שוה פחות ממה שהיתה שוה תחלה ושמין אותה כשפחה הנמכרת בשוק לפי יפיה ולפי משפחתה כיצד מי שיש לו עבד שחשוב בעיניו וחביב עליו עד שירצה להשיאו אשה יפה ומיוחסת כזאת כמה יוסיף ליתן לה כשהיא בתולה מבעולה. \u0010c5\u0011\u0010y7\u0011צער רואין לפי קטנו וקטנותה ולפי בריאותה כמה נצטערה וכן יתן מותר על חמשים של קנס \u0010y8\u0011וקונסין המאנס שצריך לישא אותה \u0010y9\u0011אפילו היא חגרת או סומא \u0010y10\u0011ואינו רשאי להוציאה לעולם \u0010y11\u0011אלא לרצונה לפיכך א\"צ לכתוב לה כתובה \u0010y12\u0011ואם עבר והוציא כופין אותו להחזירה דה\"ל לאו הניתק לעשה דכתיב ולו תהיה לאשה אע\"ג דכתיב קודם לא יוכל לשלחה כל ימיו הכי פירושו לא יוכל לשלחה שילוחים שתהיה בה כל ימיו אלא יחזירנה לפיכך אם עבר וגירש כופין אותו להחזירה ואינו לוקה \u0010c6\u0011\u0010y13\u0011מתה גרושתו קודם שיחזירנה או שנתקדשה לאחר או שהוא כהן שאסור בגרושה הרי זה לוקה שהרי עבר על לא תעשה ואין יכול לקיים עשה שבה \u0010c7\u0011\u0010y14\u0011ומיהו אם היא אסורה לו אפילו אינה \u0010y15\u0011אלא חייבי לאוין ועשה או אפילו שנייה דרבנן א\"צ לישא אותה וכן אם נשאה ומצא בה ערות דבר יכול לגרשה \u0010c8\u0011\u0010y16\u0011ואם היא או אביה אינם חפצים שישא אותה יכולין לעכב אבל הוא אינו יכול לעכב בד\"א במאנס \u0010y17\u0011אבל במפתה בין הוא או היא או אביה יכולין לעכב הנישואין \u0010y18\u0011ואם כנס המפתה אינו נותן נ' כסף אלא נותן לאביה בשת ופגם וכותב לה כתובה כמו לשאר הבתולות אבל מאנס אף על פי שכונסה צריך ליתן מיד הקנס ובושת צער ופגם \u0010y19\u0011ומיהו אם מת או מוציאה לרצונה א\"צ ליתן לה כתובה שכסף קנסה יוציא בכתובתה \u0010c9\u0011\u0010y20\u0011כתב הרמב\"ם אין האונס והמפתה חייב בקנס עד שיבא עליה כדרכה \u0010y21\u0011ובעדים \u0010y22\u0011וא\"צ התראה \u0010y23\u0011באו עליה שנים אחד כדרכה ואחד שלא כדרכה \u0010y24\u0011אם הראשון בא עליה שלא כדרכה חייב בבושת ופגם \u0010y25\u0011ולא בקנס \u0010y26\u0011ואם הוא האחרון אינו חייב אלא בבושת שכבר נפגמה \u0010y27\u0011וזה שבא עליה כדרכה בין הראשון או אחרון חייב בקנס ובשאר הדברים \u0010y28\u0011אבל אין בושת ופגם של בת שלא נבעלה כלל כבושת ופגם של זו שנבעלה שלא כדרכה ע\"כ. \u0010y29\u0011וא\"א הרא\"ש ז\"ל כתב שחייב בקנס אפי' שלא כדרכה ואם באו עליה הרבה זה אחר זה שלא כדרכה כולם חייבים בקנס \u0010y30\u0011וכן כתב הראב\"ד \u0010c10\u0011\u0010y31\u0011מאימתי יש לה קנס משתהיה בת ג' שנים ויום אחד עד שתבגר \u0010y32\u0011בין אם יש לה אב או אין לה אב אבל קודם ג' שנים ולאחר שתבגר אין לה ור\"ח פסק שאין קנס לקטנה אלא משנעשית נערה עד שתבגר וא\"א הרא\"ש ז\"ל הסכים לסברא ראשונה \u0010y33\u0011גיורת ושבויה ושפחה שנתגיירו ונפדו ונשתחררו בת ג' שנים או פחות יש להן קנס ואם נתגיירו או נפדו או נשתחררו מבת ג' שנים ולמעלה אין להן קנס \u0010c11\u0011\u0010y34\u0011נתארסה ונתגרשה מן האירוסין יש להם קנס \u0010y35\u0011נתגרשה מן הנישואין אע\"פ שהיא בתולה כגון שנכנסה לחופה ולא נבעלה אין לה קנס \u0010y36\u0011מי שיצא עליה שם רע כגון שבאו שנים והעידו עליה שתבעתם לזנות אין לה קנס אבל בשביל קול בעלמא על ש\"ר שיצא עליה אינה מפסדת הקנס \u0010c12\u0011\u0010y37\u0011הבא על אסורה לו באיסור לאו כגון ממזרת נתינה וכותית או באיסור כרת כגון אחותו ואחות אביו ואחות אמו ואשת אחיו ואשת אחי אביו ונדה אם התרו בו לוקה ואינו משלם שאין אדם לוקה ומשלם ואם לא התרו בו משלם כיון שאינו חייב מלקות \u0010y38\u0011ואם בא על חייבי עשה או שנייה משלם לעולם כיון שאין בהן מלקות \u0010c13\u0011\u0010y39\u0011ואם בא על חייבי מיתות ב\"ד כגון בתו ובת בתו ובת בנו בת אשתו בת בנה בת בתה אע\"פ שלא התרו בו פטור מן הקנס \u0010c14\u0011\u0010y40\u0011כתב הרמב\"ם הממאנת והבוגרת והאיילונית החרשת ושוטה אין להם קנס ולא נהירא שהרי הוא פסק כרבנן שקטנה יש לה קנס והאיילונית דינה כקטנה עד שתהיה בת כ' שנה ומשם ואילך דינה כבוגרת שמקטנותה יוצאת לבגר \u0010y41\u0011וכן בחרשת ושוטה השיג עליו הראב\"ד וכתב יש לה קנס \u0010y42\u0011וכ\"כ הרמ\"ה ואפילו למוכת עץ \u0010y43\u0011ומדברי ר\"י יראה שאין קנס לחרשת ושוטה ולא למוכת עץ \u0010y44\u0011כתב הרמב\"ם כל בת שיש לה קנס יש לה בושת ופגם ואם היתה אנוסה יש לה צער וכל בת שאין לה קנס אין לה בושת ולא פגם אם נתפתתה וכן אם נאנסה חוץ מבוגרת וממאנת וחרשת ושוטה כיצד האונס את הבוגרת ואת הממאנת אף על פי שאין להן קנס יש להן בושת ופגם וצער והאונס השוטה והחרשת משלם את הצער בלבד אבל המפתה את כולן פטור מכולם עד כאן ואיני מבין דבריו דמה תלוי צער ובושת ופגם בקנס דאף על פי שאין להן קנס למה לא יהא להן שאר הדברים. \u0010y45\u0011בא עליה ומתה קודם שהעמידו האב בדין פטור \u0010y46\u0011כתב הרמב\"ם ג' דברים של מפתה וארבע של אונס הם של אב \u0010y47\u0011נתארסה אחר שנתפתית אין האירוסין מוציאין מרשות האב והן שלו ואם אין לה אב הרי הן של עצמה \u0010y48\u0011והראב\"ד כתכ דצער לעצמה דכי היכי דאמרי' בשאר חבלות צערא דגופה לא אקני ליה רחמנא לאב ה\"ה נמי הכא אפילו אם יש לה אב \u0010y49\u0011ואם לא הספיק האב להעמידו בדין עד שבגרה או ניסת או \u0010y50\u0011מת הכל לעצמה אבל אם העמידו בדין ואחר כך בגרה או ניסת כבר זכה בו משעת העמדה בדין והוא שלו ואם מת מורישו לבניו \u0010c15\u0011\u0010y51\u0011נערה שנתארסה ונתגרשה קנסה לעצמה לפיכך המאנס אותה חייב והמפתה פטור שמהלה לו \u0010c16\u0011\u0010y52\u0011וכתב הרמב\"ם שהקנס לבד הוא לעצמה אבל צער ובושת ופגם הוא לאביה וא\"א הרא\"ש ז\"ל כתב שהכל לעצמה \u0010c17\u0011\u0010y53\u0011אין אדם משלם קנס ע\"פ עצמו אלא ע\"פ עדים לפיכך האומר אנסתי או פתיתי בתו של פלוני אינו משלם קנס אבל משלם צער ובושת ופגם \u0010c18\u0011\u0010y54\u0011כתב הרמב\"ם אם הבת תבעתו ואומרת אנסת או פתית אותי והוא אומר לא היו דברים מעולם הרי זה נשבע שבועת היסת שאילו הודה היה משלם בושת ופגם וצער ע\"פ עצמו אמרה לו אנסת אותי והוא אומר לא כי אלא פתיתי הרי זה נשבע שבועת התורה על דמי הצער ומשלם בושת ופגם שהרי הודה במקצת הטענה \u0010c19\u0011והראב\"ד כתב שהצער לעצמה דצער דגופה אקני ליה רחמנא הלכך אינו מודה במקצת דהנך ג' דברים דאביה נינהו ומה שהודה לאביה הודה ומה שכפר לה כפר ועוד אם טען אביה טענת שמא הוא. \u0010y55\u0011אונס ומפתה \u0010y56\u0011דנין אותו בג' לפיכך דנין אותו בכל זמן ואפי' שלא בזמן הבית אבל צריך מומחין \u0010y57\u0011לפיכך אין דנין אותו בבבל \u0010y58\u0011ולא עבדינן בהו שליחותייהו \u0010y59\u0011אבל מתקנת הגאונים מנדין אותו עד שיפייס לחבריה וכ\"כ הרי\"ף מנהג שתי ישיבות אע\"פ שאין גובין בבבל מנדין אותו עד דמפייס לחבריה וכד יהיב שיעור מאי דהזי למיתב שרינן ליה לאלתר בין איפייס כין לא איפייס: \u0010y60\u0011וכן נשאל מרב צמח גאון אלו נערות שיש להן קנס מהו לגבותו כדי שלא יהא חוטא נשכר ושלא יהו ישראל פרוצים בנזקין והשיב כבר אמרו חכמים אין גובין קנס בבבל אבל כדי שלא יהא חוטא נשכר ושלא יהו ישראל פרוצים בנזקין נהגו חכמים האחרונים לנדותו עד שיפייסו בממון או עד שירבה עליו רעים ויפייסו בדברים \u0010y61\u0011כתב א\"א ז\"ל הנטען על הפנויה יש דעות חלוקות י\"א שלא לכנוס משום לזות שפתים וי\"א שמצוה לכנוס כדאשכחן באונס ומפתה ולו תהיה לאשה ואני אומר נהי דחייבתו תורה לכונסה אחר שפגמה ה\"מ בודאי אבל בקול דעלמא אין להחזיק הקול לפגום שניהם \u0010y62\u0011כתב הרמב\"ם אני אומר זה שאמרה תורה אל תחלל את בתך להזנותה שלא יאמר אדם הואיל ולא חייבה תורה אונס ומפתה אלא שיתן ממון לאב הריני שוכר בתי הבתולה לזה לבא עליה בממון בכ\"מ שארצה או אניח לזה לבא עליה בחנם שיש לאדם למחול וליתן ממונו לכל מי שירצה לכך נאמר אל תחלל את בתך להזנותה שזה שחייבה תורה לאונס ומפתה ממון ולא מלקות כשאירע הדבר במקרה שלא מדעת אביה שדבר זה אינו מצוי אבל אם הפקיר את בתו הבתולה לכל מי שיבא עליה גורם שתתמלא הארץ זימה שנמצא אב נושא בתו ואח נושא אחותו שאם תתעבר ותלד לא יודע כן מי הוא והמכין בתו לכך הרי היא קדשה ולוקה הבועל והנבעלת משום לא תהיה קדשה ואין קונסין אותו שלא קנסה תורה אלא לאונס ומפתה על זו שהכינה עצמה לכך בין מדעתה בין מדעת אביה הרי זו קדשה ואיסור קדשה אחד הוא בין בתולה בין בעולה ולפיכך אמרו חכמים שהיוצא עליה שם רע בילדותה אין לה קנס כמו שביארנו שהרי זו בחזקה שהפקירה עצמה לדבר זה לרצונה \u0010c20\u0011\u0010y63\u0011המוציא שם רע על בתולת ישראל ונמצא הדבר שקר לוקה ומשלם ק' סלעים כסף לאביה \u0010y64\u0011ואם היא יתומה הרי הוא של עצמה \u0010y65\u0011והמוציא שם רע על הקטנה ועל הבוגרת פטור מהקנס \u0010y66\u0011וכיצד הוא הוצאת שם רע בא לבית דין ואומר בעלתי כדרכה ולא מצאתי לה בתולים ומביא עדים שזינתה \u0010c21\u0011אם זינתה קודם אירוסין פטורה ואין לה כתובה ואם לאחר אירוסין זינתה סוקלין אותה \u0010y67\u0011הוזמו עדים לוקה ומשלם ק' כסף אבל אם לא הביא העדים אלא שהעידו מעצמן והוזמו הן נהרגין והוא פטור \u0010y68\u0011וכן אם הוציא עליה שם רע שזינתה שלא כדרכה והוזמו פטור לא בעל ואפילו אם בעל אלא שלא בעל כדרכה והוציא עליה שם רע אפילו שנבעלה כדרכה והוזמו עדיו אינו חייב אלא מכות מרדות מדרבנן \u0010y69\u0011ועוד יש בו דינין הרבה ואין רצוני להאריך בהן לפי שאינו נוהג עתה שאין דנין אותו אלא בב\"ד של כ\"ג:",["\u0003המפתה או מאנס בתולת ישראל קונסין אותו נ' סלעים כסף מפורש בכתוב:\u0004 ","ומ\"ש בין אם היא בת גדול שבישראל או בת קטן שבישראל משנה בפרק יש בערכין (ערכין דף יד:):","\u0003ואיזהו מפתה ואיזהו מאנס מפתה לרצונה מאנס שלא לרצונה פשוט הוא:\u0004 ","\u0003כתב הרמב\"ם כל הנבעלת בשדה היא בחזקת אנוסה כו'\u0004 וכל הנבעלת בעיר היא בחזקת מפותה וכולי בתחילת הלכות נערה בתולה:","\u0003ומ\"ש בשם הראב\"ד חזקה זו איני יודע מה תועלת יש בה וכו'\u0004 שם בהשגות וכבר תירץ בעל מגדל עוז דהב\"ע שיש עדים שראו נבעלת ממקום רחוק אבל לא ידעו ולא ראו אם ברצון אם באונס היא אומרת אנוסה הייתי ויש לי צער והוא אומר מפותה היית ואין ליך צער סמכינן אחזקה בשדה אנוסה וכפשטיה דקרא צעקה ואין מושיע לה ובעיר מפותה ומעניינא דקרא על דבר אשר לא צעקה בעיר אם כדבריה כן הוא ע\"כ:","דין נ' סלעים הם קנס על המעשה הרע שעשה אבל מלבד זה צריך ליתן לה במפותה בושת ופגם אבל לא צער שאין למפותה צער ובאנוסה שיש לה צער ובושת ופגם נותן לה צער ובושת ופגם כך הוא הגירסא הנכונה לאפוקי ממקצת ספרים שיש בהם חסרון הניכר ודברים אלו הם מבוארים במשנה פ' אלו נערות (כתובות דף לט):","ומ\"ש ואלו אינן שוין בכל אדם אלא הכל לפי מה שהוא בושת הכל לפי המבייש והמתבייש כו' שם במשנה (דף מ.) איזהו בושת הכל לפי המבייש והמתבייש פגם רואין אותה כאילו היא שפחה נמכרת בשוק כמה היתה יפה וכמה היא יפה ובגמרא (שם) פגם רואין אותה כאילו היא שפחה כו' היכי שיימינן לה ואסיקנא אומדים כמה אדם רוצה ליתן בין שפחה בתולה לשפחה בעולה להשיאה לעבדו שיש לו קורת רוח ממנו וכתבו התוספות תימה דמה שומא היא זו וכי אשה חשובה ממשפחה גדולה אינה נפסדת בפגמה אלא שוה שפחה הניסת לעבד וי\"ל דכל אשה שמין לפי מה שהיא בענין זה כמה רוצה ליתן בין בתולה לבעולה להשיא לעבדו אשה כזאת הנפגמת והא דנקט שפחה אורחא דמילתא נקט דאין דרך להשיא לעבדו אשה בת מלכים עכ\"ל:","ומ\"ש צער רואין לפי קטנו וקטנותה ולפי בריאותה כמה נצטערה וכן יתן על נ' של קנס פשוט הוא וז\"ל הרמב\"ם ז\"ל בפ\"ב צער לפי קטנותה ובנין גופה ולפי שניו וגופו אומדין כמה האב רוצה ליתן ולא תצטער זו מזה ויתן עכ\"ל:","וקונסין המאנס שצריך לישא אותה מפורש בתורה (דברים כ״ב:י״ט) ולו תהיה לאשה לא יוכל לשלחה כל ימיו:","ומ\"ש אפי' היא חגרת או סומא משנה בפ' אלו נערות (כתובות דף לט:):","\u0003ומ\"ש ואינו רשאי להוציאה לעולם מפורש בתורה ולא יוכל לשלחה כל ימיו:\u0004 ","ומ\"ש אלא לרצונה דמשמע דלרצונה מיהא מפיק לה וכן מ\"ש לפיכך א\"צ לכתוב לה כתובה בפרק אלו נערות (שם) תניא אע\"פ שאמרו אונס כשיוציא הוא אין לה עליו כלום. כשיוציא מי מצי מפיק לה אימא כשתוציא היא אין לה עליו כלום מת יצא כסף קנסה בכתובתה ר' יוסי ב\"ר יהודה אומר יש לה כתובה מנה במאי קמיפלגי רבנן סברי טעמא מאי תקינו רבנן כתובה כדי שלא תהא קלה בעיניו להוציאה והא לא מצי מפיק לה ור\"י ב\"ר יהודה סבר הוא נמי מצי מצער לה עד דאמרה היא לא בעינא לך וידוע דהלכה כת\"ק:","ואם עבר והוציאה כיפין אותו להחזירה דהוה ליה לאו הניתק לעשה דכתיב ולו תהיה לאשה אע\"ג דכתיב קודם לא יוכל לשלחה כל ימיו הכי פירושו לא יוכל לשלחה שילוחין שתהיה בה כל ימיו אלא יחזירנה לפיכך אם עבר וגירש כופין אותה להחזירה ואינו לוקה בסוף חולין (דף קמא.) ובפ' בתרא דמכות (דף יז.) תנן זה הכלל כל מצות לא תעשה שיש בה קום עשה אין לוקין עליה ובפ' בתרא דמכות (דף יד:) אמר רבה בר בר חנה אמר רבי יוחנן כל לא תעשה שקדמו עשה לוקין עליו ואקשינן עליה מדתניא אונס שגירש אם ישראל הוא מחזיר ואינו לוקה אם כהן הוא לוקה ואינו מחזיר אם ישראל הוא מחזיר ואינו לוקה אמאי ל\"ת שקדמו עשה הוא ואסיקנא אלא אמר רבא כל ימיו בעמוד והחזיר קאי וכן כי אתא רבין אמר ר' יוחנן כל ימיו בעמוד והחזיר קאי ופירש\"י אם ישראל הוא. שיכול לקיים העשה ויחזירנה מחזיר ואינו לוקה: ואם כהן הוא. שאסור בגרושה לוקה ואינו מחזיר: אלא אמר רבא. הא דתניא באונס מחזיר ואינו לוקה טעמא משום דע\"כ לאו שניתק לעשה הוא דאמר קרא כל ימיו לא ה\"ל למכתב אלא לא יוכל לשלחה מאי כל ימיו ה\"ק לא תהא בשילוחיה כל ימיו אלא יחזירנה ע\"כ עמוד והחזיר קאמר והכי קאמר ולו תהיה לאשה אם שלחה שלא יהיו שילוחיה לכל ימיו הרי העשה אחר העברת הלאו:","ומ\"ש רבינו מתה גרושתו קודם שיחזירנה או שנתקדשה לאחר או שהוא כהן שאסור בגרושה ה\"ז לוקה כבר נתבאר דבפרק בתרא דמכות שם תניא אם כהן הוא לוקה ואינו מחזיר ואיתא נמי בפ\"ק דתמורה (דף ה) והא דמתה גרושתו או שנתקדשה לאתר מדברי רש\"י משמע דאינו לוקה דבפ\"ב דמכות אהא דא\"ר יוחנן כל ל\"ת שקדמו עשה לוקין עליו ואמרינן הניחא למ\"ד בטלו ולא בטלו אלא למ\"ד קיימו ולא קיימו מאי איכא למימר מידי הוא טעמא אלא לרבי יוחנן הא א\"ל ר\"י לתנא תני בטלו חייב לא בטלו פטור דתני תנא קמיה דר\"י כל מל\"ת שיש בה קום עשה קיים עשה שבה פטור בטל עשה שבה חייב א\"ל מאי קאמרת קיים פטור לא קיים חייב ביטל חייב לא ביטל פטור תני בטלו ולא בטלו ור\"ל אמר קיימו ולא קיימו ופירש\"י הניחא למאן. דתני לקמן בלאו הניתק לעשה ביטל את העשה חייב על הלאו לא ביטל את העשה פטור שהלאו תלוי בביטול העשה ואינו נגמר עד שיבטל העשה בידים ביטול עולם שלא יוכל להתקיים עוד איכא למימר כל ימיו יש לו תקנה בחזרה שאין מבטל את העשה אא\"כ מדירה שלא תיהנה ממנו נדר שאין לו הפרה כדלקמן: אלא למאן דתני. קיים את העשה פטור לא קיימו חייב שהעשה תיקונו של לאו הוא ואין הלאו תלוי בביטול העשה שמשעה שעבר הלאו נגמר אבל העשה ניתן לעקור המלקות ולכשיבא לב\"ד או יקיים העשה ויפטר או ילקה ליכא למימר בעמוד והחזיר קאי כדקאמרת שאם לא יחזירנה מיד כשיבא לבית דין ילקוהו דהא ליכא למימר קיים לאחר זמן דאל\"כ לא קיים ה\"ד לעולם הוא יכול לומר אני מקיים: מידי הוא טעמא אלא לר\"י. מי הוצרך לדרוש כל ימיו בעמוד והחזיר ר\"י שאמר לא תעשה שקדמו עשה לוקים עליו וקשיא ליה אונס שגירש דקתני אינו לוקה והוצרך לעשותו לאו שניתק לעשה: הא א\"ל ר\"י לתנא. לקמן תני בטלו חייב לא בטלו פטור אבל ר\"ל דתני קיימו ולא קיימו לא דריש ליה לעמוד והחזר אלא לפני הגירושין לומר כל ימיו תהיה לו לאשה ולא ישלחנה ולדידיה לאו שקדמו עשה ולאו שניתק לעשה שוין ואין לוקין עליהם אלא יקיים העשה מיד כשהזהירו ב\"ד להחזיר: א\"ל מאי קאמרת אי בקיים תתני פטור בלא קיים תתני חייב ואע\"פ שלא ביטל ואי בביטל תתני חיובא ע\"כ תתני פטורא בלא ביטל אף ע\"פ שלא קיים ה\"ג תני בטלו ולא בטלו בטל עשה שבה חייב לא בטל עשה שבה פטור קיימו ולא קיימו קיימו פטור לא קיימו כשאומרים לו קיים מלקין אותו ור\"י מוקים לה למתניתין בלאו הניתק לעשה דאילו בלאו שקדמו עשה ס\"ל דלוקין ולר\"ל בין ניתק בין קדמו עשה שוין עכ\"ל והשתא כיון דר\"י דהלכתא כוותיה סבר בטלו חייב לא בטלו פטור דהיינו לומר שהלאו תלוי בביטול העשה ואינו נגמר עד שיבטל העשה בידים ביטול עולם שלא יוכל להתקיים עוד ומתה גרושתו או נתקדשה לאחר כיון שהוא לא ביטל העשה בידים אינו לוקה אבל הרמב\"ם ז\"ל פסק בפ\"א מהלכות נערה בתולה דמתה גרושתו או נתקדשה לאחר לוקה וטעמו משום שהוא גורס כגירסת רי\"ף דגריס תני תנא קמיה דר\"י כל מל\"ת שיש בה קום עשה קיים עשה שבה פטור בטל עשה שבה חייב א\"ל ר\"י מאי קאמרת קיים פטור לא קיים חייב בטל חייב לא בטל פטור תני קיימו ולא קיימו כלומר אף על פי שלא בטלו לעשה כיון שלא קיימו לוקה אלא תעשה ופי' נ\"י כלומר תפוס רישא דוקא דאם לא קיימו חייב דמיד כשהתרו בו ב\"ד לתקן הלאו ולא תיקן שוב אין לו תקנה לתקן אותו ולוקה ואע\"פ שכתב הרא\"ש על דברי הרי\"ף רש\"י גורס תני בטלו ולא בטלו וכל הסוגיא מתפרשת ומתיישבת לפי גירסתו והוא עיקר עכ\"ל משום דלא נפקא לן בזמן הזה דאין לנו דיינים להלקות העתיק דברי הרמב\"ם ז\"ל לבד ולא חשש לכתוב דעת הרא\"ה ז\"ל:","\u0003ומיהו אם היא אסורה לו אפי' אינה אלא חייבי לאוין ועשה וכו'\u0004 וכן אם נשאה ומצא בה ערות דבר יכול לגרשה משנה בפרק אלו נערות (כתובות דף לט.) נמצא בה דבר זמה או שאינה ראויה לבא בקהל אינו רשאי לקיימה שנאמר ולו תהיה לאשה אשה שהיא ראויה לו:","ומ\"ש דחייבי עשה או אפי' שנייה דרבנן א\"צ לישא אותה כ\"כ הרמב\"ם ז\"ל בפ\"א וחייבי עשה איכא למימר דבכלל אינה ראויה לבא בקהל הם ותניא בפרק א\"נ (כט:) ולו תהיה לאשה שמעון התימני אומר אשה שיש בה הויה רש\"א אשה הראויה לקיימה מאי בינייהו ממזרת ונתינה איכא בינייהו ומסקינן דאפי' חייבי עשה אין ראוי לקיימן אבל שנייה קשה כיון דמדאורייתא שריא אשה שהיא ראויה לו היא ואפשר דכיון דמדכתיב ושמרתם את משמרתי מצאו חכמים מקום לאסור שניות שפיר איכא למימר דשנייה אימעיטא מולו תהיה לאשה ובלא\"ה כיון דכל מילי דרבנן אסמכינהו אלאו דלא תסור שפיר איכא למימר דשנייה אימעיטא מולו תהיה לאשה:","ואם היא או אביה אינם חפצים שישא אותה יכולין לעכב אבל הוא אינו יכול לעכב בד\"א באונס אבל במפתה בין הוא או היא או אביה יכולין לעכב הנישואין מבואר בפרק אלו נערות (כתובות לט:) בברייתא ובגמרא:","\u0003ומ\"ש שהמפתה יכול לעכב (שם.) במשנה:\u0004 ","ואם כנס המפתה אינו נותן נ' כסף אלא נותן לאביה בושת ופגם וכותב לה כתובה כמו לשאר הבתולות אבל לאונס אע\"פ שכונסה צריך ליתן מיד הקנס ובושת וצער ופגם משנה וברייתא שם:","ומ\"ש אם מת או מוציאה לרצונה א\"צ ליתן לה כתובה שכסף קנסה יוציא בכתובתה שם פלוגתא דתנאי בברייתא והלכה כת\"ק דאמר הכי וכבר נתבאר לעיל בסי' זה:","\u0003כתב הרמב\"ם ז\"ל אין האונס והמפתה חייב בקנסה עד שיבא עליה כדרכה כו'\u0004 בפ\"א וכתבו הגהות דהכי איתא בפ' א\"נ (מ:) דאמרינן אלו באו עליה שנים א' כדרכה וא' שלא כדרכה יאמרו בעל שלימה נותן נ' בעל פגומה נותן נ' וה\"פ בעל שלימה דעלמא נותן נ' בעל פגומה כגון זה שבא עליה כדרכה והיא כבר נבעלת שלא כדרכה וכן משמע מתוך פירש\"י ומיהו אח\"כ כתבו ע\"כ מחייב קנס אביאה שלא כדרכה כדאמר בהדיא פ\"ק דקידושין (ט:) באו עליה י' ב\"א שלא כדרכה ועדיין היא בתולה וכו' וקאמר דמודה ר' לענין קנס שכולם חייבין וכן מוכיח בפרק הבע\"י (כט.):","\u0003ומ\"ש דצריך עדים פשוט הוא דאין לחייבו קנס אלא על פי עדים:\u0004 ","\u0003ומ\"ש שא\"צ התראה פשוט הוא דלא צריך התראה אלא למיתה או למלקות:\u0004 ","\u0003ומ\"ש באו עליה שנים אחד כדרכה ואחד שלא כדרכה וכו'\u0004 בפ\"ב:","\u0003ומ\"ש את שבא עליה שלא כדרכה חייב בבושת ופגם ולא בקנס פשוט הוא שחייב בבושת ופגם:\u0004 ","\u0003ומ\"ש שאינו חייב בקנס כבר נתבאר טעמו:\u0004 ","\u0003ומ\"ש ואם הוא האחרון אינו חייב אלא בבושת שכבר נפגמה פשוט הוא:\u0004 ","\u0003ומ\"ש וזה שבא עליה כדרכה בין הוא ראשון או אחרון חייב בקנס ובשאר דברים ג\"ז פשוט:\u0004 ","ומ\"ש אבל אין בושת ופגם של בת שלא נבעלה כלל כבושת ופגם של זו שנבעלה שלא כדרכה ג\"ז פשוט הוא:","\u0003ומ\"ש בשם הרא\"ש שחייב בקנס אפי' שלא כדרכה כ\"כ בפ' א\"נ מההיא דפ\"ק דקידושין ודפרק הבע\"י:\u0004 ","\u0003ומ\"ש בשם הראב\"ד ז\"ל בהשגות בפ\"ה מהלכות נערה בתולה:\u0004 ","מאימתי יש לבת קנס משתהיה בת ג' שנים ויום אחד עד שתבגר בפרק א\"נ (כט.) תניא קטנה מבת יום אחד ועד שתביא ב' שערות יש לה מכר ואין לה קנס משתביא ב' שערות עד שתבגר יש לה קנס ואין לה מכר דר\"מ וחכ\"א קטנה מבת ג' שנים ויום אחד יש לה קנס ואע\"פ שר\"ח והראב\"ד פסקו כר\"מ הרי\"ף והרמב\"ם והרא\"ש ז\"ל פסקו כחכמים ובריש פרק נערה אמרינן בהדיא דבוגרת בושת ופגם וצער אית לה קנס לית לה. וז\"ל הרמב\"ם בפ\"א מאימתי יהיה לבת קנס מאחר ג' שנים גמורות עד שתבגר נבעלה בתוך ג' שנים אין ביאתה ביאה בא עליה משבגרה אין לה קנס שנא' נערה בתולה לא הבוגרת עכ\"ל:","ומ\"ש בין אם יש לה אב או אין לה אב כך כתב הרמב\"ם ז\"ל בפ\"א והיא ברייתא בפרק הנזכר (מד:) אם מאן ימאן אביה לרבות יתומה לקנס דברי ר\"י הגלילי ואע\"ג דדחי לה בגמרא האי דרשא לדעת ר\"י הגלילי דחייה בעלמא הוא:","גיורת ושבוייה ושפחה שנתגיירו ונפדו ונשתחררו בת ג' שנים או פחות יש להן קנס ואם נפדו או נתגיירו או נשתחררו מבת ג' שנים ומעלה אין להן קנס משנה בפרק א\"נ (דף כט. ל:):","נתארסה ונתגרשה מן האירוסין יש לה קנס שם (לח.) במשנה פלוגתא דתנאי ופסקו הפוסקים כר\"ע דאמר הכי:","נתגרשה מן הנישואין אע\"פ שהיא בתולה כגון שנכנסה לחופה ולא נבעלה אין לה קנס נלמד ממה שנתבאר דכיון דנכנסה לחופה אע\"פ שלא נבעלה דינה כבעולה:","מי שיצא עליה ש\"ר כגון שבאו ב' והעידו עליה שתבעתם לזנות אין לה קנס אבל בשביל קול בעלמא על ש\"ר שיצא עליה אינה מפסדת קנס ברייתא וגמ' פ' א\"נ (דף לה:):","הבא על אסורה לו באיסור לאו כגון ממזרת נתינה כותית או באיסור כרת כגון אחותו ואחות אביו ואחות אמו כולי אם התרו בו לוקה ואינו משלם שאין אדם לוקה ומשלם ואם לא התרו בו משלם כיון שאינו חייב מלקות בר\"פ א\"נ (דף כט.) תנן דהבא על חייבי לאוין וחייבי כריתות משלם קנס ובגמרא (דף לא:) רמי עלה מדתנן אלו הן הלוקין הבא על אחותו כו' וקי\"ל דאין אדם לוקה ומשלם ושני רבי יוחנן כאן שהתרו בו כאן שלא התרו בו דקסבר ר\"י כל היכא דאיכא ממון ומלקות ואתרו ביה מילקא לקי ממונא לא משלם:","ואם בא על חייבי עשה או שנייה משלם לעולם כיון שאין בהם מלקות כ\"כ הרמב\"ם ז\"ל בפ\"א ופשוט הוא:","\u0003אם בא על חייבי מיתות ב\"ד כגון בתו ובת בתו כו'\u0004 אע\"פ שלא התרו בו פטור מן הקנס שם במשנה (דף לו:) אלו נערות שאין להם קנס הבא על בתו ועל בת בתו כו' ובההוא פירקא (לה.) אסיקנא כי אתא רבין אמר חייבי מיתות שוגגין כ\"ע ל\"פ דפטירי ופירש\"י שוגגין שלא התרו בהן וז\"ל הרמב\"ם בפ\"א היתה מחייבי מיתות ב\"ד כגון בתו ואשת בנו וכיוצא בהן בין התרו בו בין לא התרו בו פטור מן הקנס שנאמר ולא יהיה אסון ענוש יענש הא אם היה שם אסון אין כאן עונש ואע\"פ שהריגת האשה בשגגה שהרי לא נתכוונו לה שהרי כתיב כי ינצו אנשים יחדיו ונגפו אשה הרה הא למדת שלא חלק הכתוב באסון בין שוגג למזיד לפוטרו מתשלומין והרי הוא אומר מכה נפש בהמה ישלמנה ומכה אדם יומת מה מכה בהמה לא חלק הכתוב בין שוגג למזיד לחייבו בתשלומין אף מכה אדם לא חלק הכתוב בין שוגג למזיד לפוטרו מן התשלומין וכן הדין לכל עבירה שיש בה מיתת ב\"ד שאין בה תשלומין עכ\"ל. ודרשא דלא יהיה אסון שם במשנה ודרשא דמכה נפש בהמה וכו' הוא דתני דבי רבי חייא \u0005ב\"ה צריך להעביר הקולמוס על רבי חייא ולכתוב במקומו חזקיה\u0006: בפרק הנזכר:","וכתב הרמב\"ם הממאנת ואיילונית והחרשת והשוטה והבוגרת אין להן קנס בפ\"א והוא מדתניא בפרק אלו נערות (כתובות לה:) הממאנת והאיילונית אין להן לא קנס ולא פתוי ופירש\"י הממאנת בבעלה כגון יתומה שהשיאה אמה או אחיה ומיאנה בבעלה אין לה קנס שאינה בחזקת בתולה הואיל וניסת: איילונית. אין לה קנס לפי שאין קנס אלא לנערה וזו שלא תביא ב' שערות לעולם כל כ' שנה היא בחזקת קטנה ומשם ואילך היא בוגרת ואמרינן תו בגמרא (לו.) איילונית אין לה קנס ולא פתוי ורמינהו החרשת והשוטה והאיילונית יש להן קנס ויש להן טענת בתולים והא מאי רומיא הא ר\"מ והא רבנן ודקארי לה מאי קארי לה משום דאיכא למירמה אחריתי עליה החרשת והשוטה והבוגרת ומוכת עץ אין להן טענת בתולים א\"ר ששת ל\"ק הא ר\"ג הא ר' יהושע ופירש\"י הא ר\"ג. בפ\"ק היא אומרת משארסתני נאנסתי נאמנת הכא נמי אין להן טענת בתולים להפסידה כתובתה דאמרינן אי הות פקחת לטעון הוה טענה משארסתני ומהימנא: הא ר' יהושע. דאמר לא מפיה אנו חיין הכא יש לה טענת בתולים דא\"נ הות טענה קמן לא מהימנינן לה עכ\"ל וכיון דברייתא וחרשת ושוטה אין לה טענת בתולים אתיא כר\"ג דקי\"ל כוותיה ממילא משמע דאין להן קנס דאין קנס אלא לבתולה ומ\"ש רבינו ול\"נ שהרי הוא פסק כרבנן שהקטנה יש לה קנס והאיילונית דינה כקטנה עד שתהיה בת כ' שנה ומשם ואילך דינה כבוגרת שמקטנות יוצאה לבוגרת הראב\"ד והגהות מיימון השיגו עליו כן ואיפשר לדחות ולומר דסבר הרמב\"ם ז\"ל דכיון דגבי קנס נערה כתיב אף ע\"ג דלחכמים קטנה בכלל כיון דכתיב נערה חסר ה\"א מפקינן לה כדאיתא בגמרא איכא למימר דהיינו דוקא קטנה דאתיא לידי נערות אבל איילונית דלא אתיא לידי נערות לא והיינו פשטא דברייתא דהממאנת והאיילונית אין להן קנס ואע\"ג דתלמודא שני לה בגווני אחריני היינו למאי דס\"ד דמקשה דאיילונית לחכמים יש לה קנס אבל לפום קושטא לחכמים נמי לית לה קנס ומהרר\"י קולון בשורש קל\"ח כתב שי\"ל שהרמב\"ם ז\"ל מפרש הא דקאמר פרק אלו נערות (שם) האי תנא סבר לה כר\"מ בחדא ופליג עליה בחדא היינו לומר דסבר לה כר\"מ באיילונית ופליג עליה בחדא בקטנה שיש לה קנס:","\u0003וכן בחרשת ושוטה השיב עליו הראב\"ד וכתב יש לה קנס ז\"ל הראב\"ד השוטה והחרשת כו'\u0004 א\"א אף זו טעות דלהדיא לרבנן יש לה קנס ופתוי עכ\"ל טעמו מדאמרינן בגמרא שכתבתי בסמוך איילונית אין לה לא קנס ולא פתוי ורמינהו החרשת והשוטה והאיילונית יש להן קנס ויש להן טענת בתולים והאי מאי רומיא הא ר\"מ והא רבנן כלומר דברייתא דאיילונית אין לה קנס כר\"מ וברייתא דאיילונית יש לה קנס כרבנן וכיון דבההיא ברייתא דאתיא כרבנן קתני דחרשת ושוטה יש להן קנס הכי נקטינן זה נראה שהוא טעמו של הראב\"ד וכבר כתבתי בסמוך טעמו של הרמב\"ם ז\"ל דבגמרא בסמוך מוקי ההיא ברייתא כרבי יהושע אבל לר\"ג דקי\"ל כוותיה חרשת ושוטה אין להן טענת בתולים וממילא שמעי' דלית להו קנס:","וכן כתב הרמ\"ה ואפילו במוכת עץ איפשר שטעמו משום דכיון דברייתא דאוקימנא כרבנן קתני החרשת והשוטה והאיילונית יש להן קנס ויש להן טענת בתולים משמע דלא תלי קנס בבתולים דאל\"כ הוה ליה למיתני יש להן טענת בתולים ברישא ונהי דבדרוסת איש אין לה קנס במוכת עץ מיהא יש לה קנס:","\u0003ומדברי ר\"י יראה שאין קנס לחרשת ושוטה ולא למוכת עץ:\u0004 ","כתב הרמב\"ם כל בת שיש לה קנס יש לה בשת ופגם ואם היתה אנוסה יש לה צער וכל בת שאין לה קנס אין לה בשת ופגם אם נתפתתה וכו' בפ\"ב ומ\"ש רבינו ואיני מבין דבריו דמה תלוי צער ובשת ופגם בקנס דאע\"פ שאין להם קנס למה לא יהא להן שאר דברים גם בעיני יפלא וצ\"ע ולענין בוגרת מפותה דאין לה בושת ופגם טעמא משום דמחלה וכ\"כ מהרי\"ק בשורש קס\"ח: \u0005ב\"ה וכן מפורש בגמרא נערה שנתפתתה (מב.) וכ\"כ הרא\"ש והרי\"ף:\u0006","בא עליה ומתה קודם שהעמידו האב בדין פטור בפרק אלו נערות (כתובות דף כט.) אמר אביי בא עליה ומתה פטור שנאמר ונתן לאבי הנערה ולא לאבי המתה ואע\"ג דאמרינן התם מילתא דפשיטא לאביי מיבעיא ליה לרבא כתב הרא\"ש דכיון דלאביי פשיטא ליה אזלינן בתר פשיטותיה:","כתב הרמב\"ם ז\"ל ג' דברים של מפתה וארבע של אונס הם של אב בפרק ב' ונתן טעם שכל שבח נעוריה לאביה ואם אין לה אב הרי הן של עצמה והוא משנה בפ' נערה שנתפתתה בושתה ופגמה וקנסה לאביה והצער בתפוסה:","\u0003ומ\"ש נתארסה אחר שנתפתית אין האירוסין מוציאין מרשות האב והן שלו ג\"ז בפ\"ב:\u0004 ","\u0003ומ\"ש בשם הראב\"ד דצער לעצמה וכו':\u0004 \u0005ב\"ה יש לתמוה עליו דהא תנן נערה שנתפתתה בושתה ופגמה וקנסה לאביה והצער בתפוסה ומשמע דצער נמי לאביה דקתני ברישא הוא וכן פירש\"י:\u0006","ואם לא הספיק האב להעמידו בדין עד שבגרה או ניסת או מת הכל לעצמה אבל אם העמידו בדין ואח\"כ בגרה או ניסת כבר זכה בו משעת העמדה בדין והוא שלו ומורישו לבניו אם מת משנה בפרק נערה שנתפתתה (כתובות דף מא:) עמדה בדין עד שלא מת האב הרי הן של אב מת האב הרי הן של אחין לא הספיקה לעמוד בדין עד שמת האב הרי הן של עצמה עמדה בדין עד שלא בגרה הרי הן של אב מת האב הרי הן של אחין לא הספיקה לעמוד בדין עד שבגרה הרי הן של עצמה ופירש\"י ולא הספיק לעמוד בדין וכו'. כיון דלא עמד בדין לאו ממון הוא להורישו ואמרינן לקמן אין אדם מוריש לבניו זכות שזכתה לו תורה בבתו ויליף לה מקרא:","מת האב משעמדה בדין בנערותה בין בגרה קודם מיתה בין לא בגרה הרי הן של אחים דכיון שעמד בדין זכה בהן האב ע\"כ וניסת ידוע שדינה כדין בגרה שכך יוצאת מרשות האב בזה כמו בזה:","נערה שנתארסה ונתגרשה קנסה לעצמה לפיכך המאנס אותה חייב והמפתה אותה פטור משנה בפרק אלו נערות (כתובות דף לח.) נערה שנתארסה ונתגרשה רבי יוסי הגלילי אומר אין לה קנס ר\"ע אומר יש לה קנס וקנסה לעצמה וכבר נתבאר בסימן זה שפסקו הפוסקים כר\"ע ותנן תו התם (דף מ.) יתומה שנתארסה ונתגרשה ר\"א אומר האונס חייב והמפתה פטור ובגמרא שם אמר רבה בר בר חנה א\"ר יוחנן ר\"א בשיטת ר\"ע רבו אמרה דאמר יש לה קנס וקנסה לעצמה ממאי מדקתני יתומה פשיטא אלא למאן אלא הא קמ\"ל דנערה שנתארסה ונתגרשה כיתומה מה יתומה לעצמה אף נערה שנתארסה ונתגרשה לעצמה א\"ר זירא אמר רב הלכה כר\"א ופירש\"י בשיטת ר\"ע רבו אמרה. דאמר במתני' נערה שנתארסה ונתגרשה קנסה לעצמה והך נתארסה ונתגרשה דר\"א כשאביה קיים וקרי לה יתומה משום דפקע זכות אב מינה לגבי קנסה ממאי דכר\"ע ס\"ל מדקתני אונס חייב ומפתה פטור אלמא יש לה קנס ולעצמה הילכך מפתה פטור דמדעתה עבד ואונס חייב ואפילו אביה קיים דאי יתומה כדקתני פשיטא דמפתה פטור אלא הא קמ\"ל וכו':","\u0003וכתב הרמב\"ם ז\"ל שהקנס לבד היא לעצמה וכו'\u0004 בפ\"ב וכתב הרא\"ש בפרק אלו נערות איפשר דטעמיה מהא דאמרינן לקמן על בושת ופגם ואימא לדידה ומסיק דבושת ופגם לאביה משום דאי בעי מסר לה למנוול ומוכה שחין והאי טעמא שייך נמי כשנתארסה ונתגרשה וקרא דלא אורסה לא קאי אלא אקנסא דכתיב בקרא אבל בשת ופגם יליף מדכתיב ונתן האיש השוכב וכו' הנאת שכיבה חמשים מכלל דאיכא בשת ופגם כמו בשאר חבלות אבל בהאי קרא לא כתיבי ומיהו נראה דגם בשתה ופגמה לעצמה מדקאמר ר\"א ביתומה שנתארסה ונתגרשה המפתה פטור ואם איתא דבשתה ופגמה לאביה לא ה\"ל למיתני דמפתה פטור בסתם כיון דחייב בבשת ופגם והיינו טעמו משום דלענין גביית האב יש לבשת ופגם דין קנס משום דאיתקש לקנס דכתיב ונתן לאבי הנערה נ' כסף ולו תהיה לאשה תחת אשר ענה ודרשינן מהאי קרא מכלל דאיכא בשת ופגם ולענין גביית האב אתקיש דבמקום שהקנס לאב גם הוא לאב ומהאי טעמא תנן לקמן בפרק נערה לא הספיקה לעמוד בדין עד שמת האב הרי הן של עצמה ואבשת ופגם נמי קאי מדקתני הרי הן אלמא בשת ופגם אע\"ג דממונא הן אין מורישין לבניו משום דאיתקש לקנס לענין גביית האב הילכך נתארסה ונתגרשה כיון שנתמעט האב מלא אורסה מדין קנס נתמעט נמי מדין בושת ופגם והכל לעצמה עכ\"ל:","אין אדם משלם קנס על פי עצמו אלא על פי עדים לפיכך האומר אנסתי או פתיתי בתו של פלוני אינו משלם קנס אבל משלם צער ובשת ופגם משנה ס\"פ א\"נ (ד' מא.). דין אשה שתחלתה באונס וסופה ברצון בביאה אחת או בשתי ביאות עיין במהרי\"ק שורש קנ\"ט ושם כתב דין אשה טוענת שאיש בא עליה בעת עילופה והבטיח אותה שישאנה והוא כופר:","כתב הרמב\"ם אם הבת תובעתו ואומרת אנסת או פתית אותי והוא אומר להד\"מ הרי זה נשבע שבועת היסת וכו' אמרה לו אנסת אותי והוא אומר לא כי אלא פתיתך הרי זה נשבע שבועת התורה על דמי הצער וכו' בפ\"ב והראב\"ד כתב שהצער לעצמה וכו' הילכך אינו מודה במקצת דהנך ג' דברים דאביה נינהו ומה שהודה לאביה הודה ומה שכפר לה כפר אין זו השגה על הרמב\"ם ז\"ל דלטעמיה אזיל שכבר נתבאר בסימן זה שהוא סובר שהצער ג\"כ לאביה: \u0005ב\"ה וכך היא פשטא דמתניתין ומ\"ש ועוד אם טען אביה טענת שמא הוא י\"ל דאפי' לפי מה שהוא ז\"ל סובר שהצער לעצמה לא קשיא דכיון דהני ג' דברים דידה אלא דרחמנא זכינהו לאב שפיר מיקרי איהו בעלת דבר:\u0006 ועוד אם טען אביה טענת שמא הוא:","אונס ומפתה דנין אותו בג' לפיכך דנין אותו בכל זמן אפילו שלא בזמן הבית אבל צריך מומחין לפיכך אין דנין אותו בבבל אין לשון זה מקושר יפה ונראה בעיני שט\"ס יש כאן:","ומ\"ש שדנין אותו בג' משנה בריש סנהדרין (ב.): ומ\"ש דנין אותו בכל זמן ואפילו שלא בזמן הבית פשוט הוא: ומ\"ש אבל צריך מומחין שם בגמרא:","ומ\"ש לפיכך אין דנין אותו בבבל נראה דהיינו לומר דייני בבל כיון שאינם סמוכים אין דנין אותו אבל דייני סמוכים אף בח\"ל דנין דיני קנסות וכן משמע בהדיא בפ\"ק דסנהדרין (יד.) דגרסינן התם אמר ריב\"ל אין סמיכה בחוץ לארץ מאי אין סמיכה אילימא דלא דיינין דיני קנסות בח\"ל והא תנן סנהדרין נוהגות בין בארץ בין בח\"ל אלא דלא סמכי בח\"ל:","ומ\"ש ולא עבדינן בהו שליחותייהו בר\"פ החובל (בבא קמא דף פד:) אסיקנא דלא עבדי' שליחותייהו אלא בממונ' ובמלתא דשכיחא ואית בהו חסרון כיס כמו הודאות והלואות אבל מילתא דלית בה חסרון כיס אע\"ג דשכיח א\"נ לא שכיח אף על גב דאית בה חסרון כיס לא עבדינן שליחותייהו ומהכא משמע בהדיא דבין בקנס ובין בבשת ופגם לא עבדינן שליחותייהו והכי אמרינן בגמרא בהדיא:","ומ\"ש אבל מתקנת הגאונים מנדין אותו עד שיפייס חבירו וכ\"כ הרי\"ף מנהג ב' ישיבות אע\"פ שאין גובין קנס בבבל מנדין אותו עד שיפייס את חבירו וכד יהיב שיעור מאי דחזי למיתב שרינן ליה כו' כך הוא הנוסחא הנכונה בדברי רבינו ודברי הרי\"ף הם בפ' החובל וכך הם דברי הרמב\"ם זכרונו לברכה בפ' ה' מהלכות סנהדרין:","ומ\"ש וכן נשאל מרב צמח גאון אלו נערות שיש להם קנס מהו להגבותו כדי שלא יהא חוטא נשכר וכו' הרא\"ש הביאו בר\"פ החובל ועוד כתב שם הרא\"ש דעת רב שרירא גאון בזה וכתבו רבינו בטור ח\"מ סימן א' כתב הריב\"ש בתשובה סי' מ\"א אם תובעה ממנו הפנויה שכשבא עליה נדר לה איזה דבר באתננה חייב שבועת היסת על תביעה זו:","\u0003כתב א\"א ז\"ל הנטען על הפנויה יש דעות חלוקות י\"א שלא לכנוס כו'\u0004 עד אין להחזיק הקול לפגום שניהם בפ\"ב דיבמות כתב כן וכתב מהר\"י קולון בשורש קנ\"ט גם מתוך לשון המרדכי משמע קצת היותו נוטה שלא לכדברי ר\"י ומ\"מ בנדון זה יש להכריע כדברי האומר לכנוס כו' עד מ\"מ פשיטא דאין לכופו אפי' לפי' דברי רבי' יצחק כדפי' לעיל ועיין עוד במהרי\"ק סימן קכ\"ט וסימן קל\"ה:","כתב הרמב\"ם ז\"ל אני אומר זה שאמרה תורה אל תחלל את בתך להזנותה שלא יאמר אדם הואיל ולא חייבה תורה אונס ומפתה אלא שיתן ממון לאב הריני שוכר בתי הבתולה כו' עד שהרי זו בחזקה שהפקירה עצמה לדבר זה לרצונה הכל בפ\"ב מהלכות נערה בתולה:","המוציא ש\"ר על בתולת ישראל ונמצא הדבר שקר לוקה ומשלם ק' סלעים כסף לאביה בפרק נערה שנתפתתה (כתובות דף מו.) ת\"ר וענשו אותו זה ממון ויסרו זה מלקות:","ומ\"ש ואם היא יתומה הרי היא של עצמה שם (דף מד:) א\"ר יוסי בר חנינא המוציא ש\"ר על היתומה פטור שנאמר ונתן לאבי הנערה פרט לזו שאין לה אב רבא אמר חייב מדתני אמי בתולת ישראל ולא בתולת גרים אא\"ב בכה\"ג בישראל מיחייב איצטריך קרא למעוטי גרים אלא אי אמרת בישראל פטור השתא בישראל פטור בגרים מיבעיא ומשמע דהלכה כרבא וכ\"פ הרמב\"ם ז\"ל בפרק ג' מהלכות נערה בתולה:","והמוציא שם רע על הקטנה ועל הבוגרת פטור מהקנס שם אמר ר\"ל המוציא ש\"ר על הקטנה פטור שנאמר ונתן לאבי הנערה נערה מלא דיבר הכתוב ופירש\"י נערה מלא דיבר הכתוב בכ\"מ דיבר הכתוב נער וכאן כתב נערה מלא להוציא את הקטנה ע\"כ: ומ\"ש רבינו דעל הבוגרת נמי פטור כ\"כ הרמב\"ם ז\"ל בפ\"ג מהלכות נערה בתולה ונראה מדבריו דמשמע ליה מדכתיב נערה למעט את הבוגרת ובפרק נערה שנתפתתה (כתובות דף מה:) תניא נערה בתולה המאורסה שזינתה ומשבגרה הוציא עליה ש\"ר הוא אינו לוקה ואינו נותן ק' סלעים ופירש\"י הוציא עליה ש\"ר שכנסה משבגרה ולא מצא לה בתולים ובא לב\"ד הוא אינו לוקה אם כיחש ואינו נותן ק' סלעים דכי כתיב ויסרו אותו מלקות וענשו אותו ממון בנערה כתיב וזה עקימת שפתיו גורמין לו ליעשה ועקימת שפתיו בבוגרת הואי:","כיצד הוא הוצאת ש\"ר בא לב\"ד ואומר בעלתי כדרכה ולא מצאתי לה בתולים ומביא עדים שזינתה אם זינתה קודם אירוסין פטורה ואין לה כתובה ואם לאחר אירוסין זינתה סוקלין אותה בפרק נערה שנתפתתה (כתובות מו.) כיצד הוצאת ש\"ר בא לב\"ד ואמר פלוני לא מצאתי לבתך בתולים אם יש עדים שזינתה תחתיו בסקילה זינתה מעיקרא כתובתה מנה ויש לתמוה על רבינו שכתב אין לה כתובה ואפשר דאין לה כתובה מאתים קאמר:","הוזמו עדיו לוקה ומשלם ק' כסף כבר נתבאר ומ\"ש אבל אם לא הביא עדים אלא שהעידו מעצמן והוזמו הן נהרגין והוא פטור כ\"כ הרמב\"ם בפ\"ג מהלכות נערה בתולה ופשוט הוא:","וכן אם הוציא עליה ש\"ר שזינתה שלא כדרכה והוזמו פטור לא בעל ואפילו אם בעל אלא שלא בעל כדרכה והוציא עליה ש\"ר אפי' שנבעלה כדרכה והוזמו עדיו אינו חייב אלא מכת מרדות מדרבנן בפרק נערה שנתפתתה (שם) איפליגו תנאי אי בעינן שיוציא ש\"ר אחר שבעל או אפילו קודם שבעל נמי ובמסקנא אמרינן שלח רב כהנא משמיה דרבי יוחנן אינו חייב עד שיבעול כדרכה ויוציא ש\"ר כדרכה:","\u0003ועוד יש בו דינים וכו'\u0004 שאין דנים אותו אלא בב\"ד של כ\"ג במשנה ריש סנהדרין:"],["\u0003המפתה או מאנס וכו'\u0004 עד מפתה לרצונה ומאנס שלא לרצונה כ\"כ הרמב\"ם רפ\"א מה' נערה בתולה ונראה דבאו להורות דמפתה דכתב קרא לאו דוקא דשידלה בדבריו אלא כל שהיה לרצונה מפותה קרי לה אף ע\"פ שלא פיתה אותה אלא תבעה והיא נתרצית מיהו ודאי צריך שאירע הדבר מקרה שלא מדעת אביה ולא הכינה עצמה לכך דאם הכינה עצמה לכך ה\"ז קדשה ואין לה קנס כמ\"ש הרמב\"ם גופיה ומביאו רבינו בסוף סימן זה וכן מאנס אפילו פיתה אותה ושידלה בדבריו כיון שלא לרצונה נבעלה מאנס קרי לה:","\u0003ומ\"ש וכתב הרמב\"ם כל הנבעלת וכו':\u0004 ","\u0003וכתב הראב\"ד חזקה זו איני יודע וכו'\u0004 תירץ במ\"ע שהעדים ראו מרתוק ששכב עמה ולא ידעו אם באונס אם ברצון היה בעיר חזקה שהיא מפותה אם לא צעקה ולא העידו ששלף חרבו וכו' ואם הוא בשדה חזקה שהיא אנוסה וכ\"כ ב\"י והיינו לומר דבעיר לא מיבעיא כשעמדו מרחוק ושמעו שצעקה דפשיטא שהיא בחזקת אנוסה אלא אפילו היו ברחוק קצת שהיו יכולין לשמוע אם היתה צועקת ולא שמעו צעקתה אפי' הכי אם ראו ששלף חרבו נמי מחזקינן לה באנוסה ואין פירושו ששמעו העדים שא\"ל אם תצעקי אהרוג אותך אלא שהיא טוענת שא\"ל כך ונאמנת כיון שראו העדים ששלף חרבו ומ\"ש הראב\"ד לגבי קנס אם אין עדים אין שם קנס ולגבי ג' דברים כתב המע\"ה היינו משום דגבי קנס אפי' היה מודה דאנסה אם אין עדים מודה בקנס פטור אבל לגבי ג' דברים דממון הוא אם היה מודה חייב בהן ואם אינו מודה המע\"ה:","\u0003ומ\"ש בושת הכל לפי המבייש וכו'\u0004 עד וכמוהו יתן לו כ\"כ גם הרמב\"ם לשם אבל רש\"י לא פי' כן ועיין במ\"ש בח\"מ סי' ת\"כ סי\"ז:","\u0003ומ\"ש פגם וכו'\u0004 כשפחה וכו' כיצד מי שיש לו עבד וכו' בגמ' (דף מ) נקט בסתם בין שפחה בתולה לשפחה בעולה להשיאו לעבדו וכו' אלא שהתוס' פירשו דשמין לפי יפיה ומשפחתה להשיאה לעבדו ואיכא להקשות אמאי נקט שפחה ועבד הלא אף להשיאה לעצמו הוא נותן יותר בעד בתולה מבבעולה וי\"ל דנקט חומרא למאנס דבעד בתולה יפה ומיוחסת כדי להשיאה לעבדו צריך ליתן הרבה יותר מאילו היתה בעולה משא\"כ בבא להשיאה לעצמו:","\u0003צער רואין וכו'\u0004 אבל הרמב\"ם בפ\"ב כתב וז\"ל אומדין כמה האב רוצה ליתן ולא תצטער זו מזה ויתן דקדק שאין פי' כמה אדם רוצה ליקח להצטער בכך ותימה דבח\"מ לשם הביא רבינו דברי הרמב\"ם שכתב גבי חובל כמה אדם רוצה ליקח להצטער ושהרא\"ש חולק דאין אדם רוצה ליקח שום ממון כדי לקבל צער וכו' ע\"ש וכאן כתב בסתם ואפשר לטעות דמשמעו כמה אדם רוצה ליקח וי\"ל דכאן קיצר ונסמך על מ\"ש בח\"מ:","\u0003מתה גרושתו וכו'\u0004 ה\"ז לוקה כ\"כ הרמב\"ם פ\"א לפי גירסת הרי\"ף בפ' אלו הן הלוקין דמיד שהתרו בו ב\"ד לתקן הלאו להחזירה ולא תיקן שוב אין לו תקנה ולוקה ואף על גב דלגירסת רש\"י והרא\"ש אינו לוקה אם לא קיים העשה אא\"כ בטל העשה בידים כגון שלח תשלח האם וביטל העשה ששיבר כנפיה שלא תוכל לפרוח וח\"כ הכא שמת גרושתו שלא בטלו בידים אינו לוקה רבינו ראה דהעיקר כגירסת הרי\"ף והרמב\"ם ועיין במ\"ש ב\"י:","\u0003ומ\"ש ומיהו אם היא אסורה לו וכו'\u0004 וכן אם נשואה וכו' פי' דבאסורה לו א\"צ לישא אותה כדתנן נמצא בה דבר ערוה או שאינה ראויה לבא בישראל אינו רשאי לקיימה שנאמר ולו תהיה לאשה אשה הראויה לו וכיון שא\"צ לישא אותה א\"כ בין שהיא אסורה לו מדאורייתא ובין שאינה אסורה לו אלא מדרבנן אסור לישא אותה אבל כשנמצא בה דבר זמה וערוה צריך הוא לכנסה דכיון שהיא עכשיו פנויה אינה אסורה לו ושמא תסור מדעתה אלא דאם נמצא בה דבר זמה וערוה לאחר שכנסה ה\"ז יגרשנה וכך מפורש בדברי הרמב\"ם וס\"ל דמה ששנינו אינו רשאי לקיימה דמשמע דלכתחלה צריך לכנסה לא קאי אלא אנמצא בה דבר ערוה אבל אשה שאינה ראויה לו אפי' לכתחילה לא יכנסנה כיון שאסורה לו. ולשון וכן שכתבו הרמב\"ם ורבינו ה\"פ ל\"מ באסורה לו דכיון דא\"צ לישא אותה פשיטא דאסורה לו לישאנה אלא אפי' נמצא בה דבר זמה דצריך לכונסה לכתחלה אפ\"ה אם חזרה לסורה ונמצא בה דבר זמה לאחר שכנסה צריך לגרשה אלא דקשה בלשון רבינו שכתב יכול לגרשה דמשמע דרשאי לקיימה ותנן להדיא אינו רשאי לקיימה וכ\"כ הרמב\"ם ה\"ז יגרשנה ונראה דרבינו סובר דאף על גב דתנן אינו רשאי לקיימה היינו לומר דמצוה לגרשה אבל אין כופין אותו לגרשה אם אינו רוצה לקיים את המצוה ולכן אמר יכול לגרשה אבל אין כופין וע\"ל בסי' קט\"ו כתב רבינו בעוברת על דת אין כופין אותו להוציאה אלא דמצוה עליו שיוציאנה ובריש סי' קי\"ט נמי כתב דאם נמצא בה ערות דבר או פריצות מצוה לגרשה וכו' משמע מצוה הוא אבל אין כופין וזאת היתה דעתו במ\"ש כאן יכול לגרשה:","\u0003ואם היא כו'\u0004 אבל במפתה בין הוא וכו' פ' אלו נערות סוף (כתובות דף ל\"ט) פריך מכדי מגמרו גמרי מהדדי אונס ממפתה להא מילתא שיהיה מפתה נושאה על כרחו נמי ליגמרו מהדדי אמר קרא מהר ימהרנה לו לאשה לו מדעתו וכתבו התוס' וא\"ת ולו תהיה לאשה נדרוש נמי לו מדעתו והא דכתיב לא יוכל לשלחה היינו היכא דכבר נשאה וי\"ל דאין סברא שיהיה מדעתו כיון שאם נשאה לא יוכל לשלחה עכ\"ל:","\u0003כתב הרמב\"ם אין המאנס והמפתה חייב בחנם עד שיבא עליה כדרכה בפ\"א באו עליה שנים וכו'\u0004 בפרק ב' וטעמו דבפ' אלו נערות (כתובות דף מ) מקשינן ואימא נ' סלעים אמר רחמנא מכל מילי א\"ר זירא אילו באו עליה שנים א' כדרכה וא' שלא כדרכה יאמרו בעל שלימה חמשים בעל פגומה חמשים ופירש\"י מהכא מסתברא שאין בושת בכלל חמשים דא\"כ אין הפרש בין בעל שלימה לבעל פגומה שנבעלה שלא כדרכה והיכן הוא הפרש שביניהם ש\"מ גבי בשת שזו שנפגמה כבר אין בושת רב כשלימה עכ\"ל פי' לפירושו דא\"כ אין הפרש בין בעל שלימה דעלמא דנותן נ' לבעל פגומה כגון זה שבא עליה כדרכה והיא כבר נבעלה שלא כדרכה עכ\"ל דאלמא דזה שנבעלה לו שלא כדרכה אינו חייב קנס אלא זה שבעלה אח\"כ כדרכה הוא דחייב קנס ותלמודא ה\"ל למנקט ברישא שלא כדרכה אלא דרך התלמוד כן כמ\"ש לשם התוס' אלא שחולקים אפירש\"י ומפרשים דבבתולה אחת קאמר אילו באו עליה שנים א' שלא כדרכה וא' כדרכה דכל א' מהם חייב קנס וכדעת הרא\"ש והראב\"ד:","מאימתי יש לבת קנס משתהיה בת ג' שנים ויום א' נראה דלאו דוקא יום א' אלא כל שהיא מבת ג' שנים ומעלה אפילו לא נכנסה בשנה רביעית אלא שעה אחת אלא לפי שאין דרך למנות לבן ולבת שעות אלא ימים נקט תלמודא בן י\"ג ויום אחד בת י\"ב ויום א' בת ג' ויום א' ובכולהו לאו דוקא יום א':","ומ\"ש נתארסה ונתגרשה מן האירוסין יש לה קנס פי' דוקא נתגרשה דבעודה ארוסה דחייב סקילה פטור מתשלומין דקים ליה בדרבה מיניה וכן פירש\"י במשנה (ד' לח):","\u0003הבא על אסורה לו וכו'\u0004 ר\"פ אלו נערות:","\u0003ומ\"ש ואם בא על חייבי מיתות ב\"ד וכו'\u0004 שם בברייתא ילפינן לה מקרא דולא יהיה אסון ומביאו הרמב\"ם פ\"א:","\u0003כתב הרמב\"ם הממאנת וכו'\u0004 עיין בב\"י מבואר טעם מחלוקת זה:","\u0003נערה שנתארסה ונתגרשה וכו'\u0004 שם במשנה (דף לח) פליגי בה ר\"י הגלילי ור\"ע והלכה כר\"ע ולעיל כתב רבינו בסתם נתארסה ונתגרשה מן האירוסין יש לה קנס משום דקודם לכן כתב מחלוקת הפוסקים בקטנה לכך כתב בסתם נתארסה ונתגרשה דלר\"ח דוקא נערה ולשאר פוסקי' אפי' קטנה יש לה קנס כשנתגרשה מן האירוסין אבל נתגרשה מן הנישואין אפילו היתה נערה אין לה קנס דכל שנכנסה לחופה אע\"פ שלא נבעלה דינה כבעולה אבל כאן כתב נערה דאף ע\"פ דלמ\"ד קטנה יש לה קנס אם נתארסה ונתגרשה נמי קנסה לעצמה נקט נערה משום דתני המאנס חייב והמפתה פטור שמחלה לו ובנערה דוקא מהניא מחילה אבל קטנה שאין לה דעת אין מחילתה מחילה:","\u0003וכתב הרמב\"ם שהקנס לבד הוא לעצמה וכו'\u0004 עיין בב\"י טעם מחלוקתם בזה:","\u0003אין אדם משלם קנס ע\"פ עצמו וכו'\u0004 משנה ס\"פ אלו נערות ובגמרא לא מיבעיא אנסתי דלא פגים לה דמהימנינן ליה למישקל מיניה בושת ופגם על פיו אלא אפי' פתיתי דלעז גדול הוא לה ולאביה ולכל המשפחה שנתפתתה וזינתה וסד\"א דלא להימניה למישקל מיניה בושת ופגם להחזיק את הלעז ואע\"פ דניחא לה ולאביה לשאת את הלעז ולהשתכר ממון לא ניחא ליה לאחד מבני משפחה במ\"ה קמ\"ל דמשלם ע\"פ עצמו:","\u0003כתב הרמב\"ם אם הבת תובעתו וכו'\u0004 פי' כיון שאילו הודה היה משלם א\"כ כשכופר חייב לישבע דכל טענה שאפי' אם הודה לא היה חייב לשלם אם כופר א\"צ לישבע כמ\"ש רבינו בח\"מ סימן פ\"ז סל\"ט:","ומ\"ש הראב\"ד ועוד אם טען אביה טענת שמא הוא פי' ועוד את\"ל דהצער גם הוא לאביה אפ\"ה אין כאן שבועה על דמי הצער כיון דאביה אינו טוען ברי אלא ע\"פ הבת ואין שם עדים אך קשה מהא דכתב רבינו בח\"מ סוף סימן ע\"ה ס\"ל ע\"ש הראב\"ד דבטען אבא א\"ל שאתה חייב לו מנה דהוי טענה ודאי ונשבע עליה ור\"נ דבטוען בשם אביו חשוב טפי טענת ודאי הואיל והיתה הנתינה מכח בן דעת משא\"כ הבת ועיין בח\"מ ריש סימן צ\"ו:","\u0003המוציא שם רע וכו'\u0004 כל הסוגיא בפרק נערה שנתפתתה:","ומ\"ש אם זינתה קודם אירוסין פטורה ואין לה כתובה הקשה ב\"י דבפרק נערה (כתובות דף מו) תניא כתובה מנה ותקפה עליו משנתו דלעיל בסימן ס\"ז כתב ב\"י בעצמו דאין לה כלל כתובה משום דקי\"ל כרבא דמקח טעות הוא וכדכתב הרי\"ף והרא\"ש בפ\"ק דכתובות וכ\"כ עוד בפרק נערה ולית הלכתא כהך ברייתא דתני בה כתובתה מנה:"]],["\u0003הלכות סוטה \u0004\n\u0010c0\u0011\u0010y0\u0011המקנא לאשתו ונסתרה ואינו יודע אם נטמאה בזמן שבית המקדש קיים מביאה אל הכהן ומשקה אותה מי המרים ונבדקת על ידן אם נמצאת טהורה מותרת אבל אסורה לעולם עד שתבדק כי רק ההיתר תלוי בהשקאת המים בזמן הבית אבל באיסור אחר הסתירה אינו תלוי בזמן הבית שאפילו א\"א להשקותה כמו בזמן הזה או שאינה ראויה להשקותה שיש דברים רבים שמונעים השתייה ויש נשים רבות שאינן ראויות להשקות כולן אסורות ובכאן אין רצוני להאריך לא בדברים המונעים לה השתייה ולא בנשים שאינן ראויות לשתות כיון שכולן אסורות \u0010y1\u0011ובלבד שיהא הסתירה והקינוי כראוי כיצד הקינוי אומר לה בפני ב' אל תסתרי עם איש פלוני אפילו הוא אביה או אחיה או עכו\"ם או שחוף פי' שאינו מתקשה ואינו מוליד והוא שיהיה גדול אבל אם אמר לה אל תסתרי עם פלוני והוא קטן או עם בהמה לא הוי קינוי \u0010y2\u0011ומקנא לה בין אם היא ארוסה או נשואה או זקוקה ליבם \u0010c1\u0011\u0010y3\u0011כתב הרמב\"ם קטנה שהשיאה אביה אם זינתה לרצונה אסורה לבעלה לפיכך מקנאין לה ולא להשקותה אלא להפסידה כתובתה \u0010c2\u0011אבל קטנה בת מיאון אין מקנאין לה לפי שאין לה רצון לאוסרה על בעלה ואפילו אם הוא כהן אינה נאסרת עליו \u0010c3\u0011\u0010y4\u0011והראב\"ד השיג עליו וכתב והלא אמרינן פיתוי קטנה אונס הוא ועוד התראה לקטנה אינה התראה שאין לה דעת אלא אם זנתה אסורה ודאי לבעלה כהן ולא מצאתי הפרש בין קטנה לקטנה לענין פתוי לומר בת מיאון אין לה רצון ויתן הצער כמו אנוסה אלא כולן שוין להתפתות כקלות הדעת ע\"כ \u0010y5\u0011וכיצד היא הסתירה שנסתרה בפני עדים עם פלוני שקינא לה עליו ושהתה \u0010y6\u0011כדי טומאה שהוא שיעור כדי לצלות ביצה ולגומעה \u0010c4\u0011\u0010y7\u0011קינא לה מב' שאמר לה אל תסתרי עם פלוני ופלוני ונסתרה עם שניהם כאחד ושהתה כדי טומאה אפי' הם ב' אחים או אביה או אחיה אסורה עד שתשתה \u0010y8\u0011אמר לה בפני ב' אל תדברי עם פלוני אין זה קינוי ואפילו נסתרה עמו ושהתה עמו כדי טומאה מותרת או אמר לה אל תסתרי עם פלוני ודברה עמו בפני עדים מותרת שאין זו סתירה \u0010c5\u0011וכן אם נסתרה בפני עדים ושהתה כדי טומאה ולא קינא לה בפני עדים מותרת שאין אוסרין על הייחוד אפילו נסתרה יחד על דעת ערוה אא\"כ קינא לה תחלה בפני ב' \u0010y9\u0011ומ\"מ לא תתייחד אשה עם אנשים כדפרישית לעיל באיסור ייחוד. \u0010c6\u0011\u0010y10\u0011כתב בסה\"מ לא יאמר אדם לאשתו בזמן הזה אל תסתרי עם פלוני דשמא הלכה כר\"י דאמר קינא לה בינה לבין עצמו שלא בפני עדים הוי קינוי ועכשיו אין מי סוטה ותיאסר עליו לעולם \u0010c7\u0011\u0010y11\u0011בא ע\"א והעיד לו שנסתרה עם אותו שקינא לה עליו ושהתה כדי טומאה אם הוא נאמן בעיניו ודעתו סומכת עליו יוציאה ויתן כתובה ואם לאו מותרת לו ואם הוא בעצמו ראה שנסתרה עמו ושהתה כדי טומאה הרי זו אסורה עליו ויוציא ויתן כתובה שאינו יכול להשקותה ע\"פ עצמו \u0010y12\u0011לא קינא לה ובא עד אחד ואמר לו זנתה והוא שותק אם הוא נאמן בעיניו ודעתו סומכת עליו כשנים יוציאה ויתן כתובה ואם לאו מותרת לו \u0010y13\u0011כתב א\"א הרא\"ש ז\"ל בתשובה על אחד שהוציא קול על אשתו שזנתה ואמר שנתברר לו הדבר ואח\"כ אמר אינו אמת אלא שמחמת הכעס שהכעיסתו הוציא עליה קול זה אם נתן אמתלא לדבריו מותרת לו ואם לאו אסורה לו עד כאן \u0010c8\u0011\u0010y14\u0011שמע העם מרננים אחר הקינוי והסתירה עד שהנשים נושאת ונותנות בה שזנתה מהאיש שקינא לה עליו אסורה ויוציאנה ויתן כתובה \u0010y15\u0011בעל שמחל על קינויו קודם סתירה קינויו מחול וכאילו לא קינא אבל לאחר סתירה אין קינויו מחול גירשה ה\"ז כאילו מחל לה ואם החזירה צריך לקנאות לה פעם אחרת ואלו שב\"ד מקנאין להם מי שנתחרש בעלה או נשתטה או היה במדינה אחרת או שהיה חבוש בבית האסורין ולא להשקותה אלא להפסידה כתובתה \u0010y16\u0011כיצד שמעו ב\"ד שהעם מרננין אחריה קוראין לה ואומרים לה אל תסתרי עם פלוני באו עדים אח\"כ שנסתרה עמו ושהתה כדי טומאה אוסרין אותה על בעלה לעולם וקורעין לה כתובתה וכשיבא בעלה או יבריא או יצא מבית האסורין יתן לה גט ואינו יכול להשקותה שהרי לא קינא \u0010c9\u0011\u0010y17\u0011בא עד אחד והעיד שנטמאה \u0010y18\u0011מאותו שקינא לה אינה שותה ותצא בלא כתובה \u0010y19\u0011אפילו עד הטומאה הוא עד אחד מעדי הסתירה ואפילו עבד או שפחה או אשה או קרוב כשר לעדות זה \u0010y20\u0011ואפילו נשים ששונאות זו את זו מעידות זו לזו לומר שנטמאה ונאמנת עליה לאוסרה על בעלה ושלא להשקותה אבל לא להפסיד כתובתה אבל נוטלת כתובתה ויוצאה \u0010c10\u0011\u0010y21\u0011בא עד אחד ואמר שנטמאה ואחר כך בא עד אחד ואמר לא נטמאה אין שומעין לאחרון שעד אחד בטומאת סוטה כשנים ואין דברי האחרון דוחין דברי הראשון שהוא כשנים באו שנים כאחד זה אומר נטמאת וזה אומר לא נטמאת או שבא אחד ואמר נטמאת ואח\"כ באו ב' ואמרו לא נטמאת הרי זו שותה פי' בשעה שאתה אומר נטמאת ידענו שלא נטמאת לפיכך שותה שנתבטלו דברי האחד ואוקמה אחזקת ספק בא עד אחד כשר ונשים רבות כאחד העד הכשר אומר נטמאת והנשים אומרות לא נטמאת הרי זו שותה שעד אחד כשר ורבים פסולים כמחצה על מחצה דמי \u0010y22\u0011היו כולם פסולים הולכין אחר רוב דעות \u0010y23\u0011כתב הרמב\"ם כיצד ב' אומרות נטמאת ושלש אומרות לא נטמאת הרי זו שותה ג' אומרות לא נטמאת וד' אומרות נטמאת אינה שותה היו מחצה על מחצה הרי זו שותה ע\"כ \u0010y24\u0011כל שאינה שותה מפני עדי טומאה אסורה לעולם ותצא בלא כתובה \u0010y25\u0011כתב בה\"ג שאין מוציאין על ידי עדי טומאה עד שיראה כמכחול בשפופרת ור\"ח כתב שאין צריך רק שיראו אותם דבוקים זה בזה ונוהגין כדרך מנאפין וכ\"פ רב אלפס ביבמות פרק כיצד וכן הוא מסקנת א\"א הרא\"ש ז\"ל \u0010y26\u0011אשה שקינא לה בעלה ונסתרה ומת אינה נוטלת כתובתה \u0010y27\u0011כל שאסורה לבעל משום קינוי אסורה לבועל לפיכך האידנא שאסורה לעולם אחר קינוי וסתירה אסורה ג\"כ לבועל ואם ניסת תצא ואם אין עדי טומאה אלא עדי כיעור פירשתי למעלה בסי' י\"א \u0010y28\u0011כתב ר\"ת ישראלית שהמירה ונישאת לעכו\"ם ושוב חזרה בתשובה ונתגייר העכו\"ם עמה וגירשה בעלה שמותרת לגר שנתגייר עמה וכ\"כ א\"א הרא\"ש ז\"ל ואע\"פ שבודאי אסור לבעל מותרת לעכו\"ם \u0010y29\u0011כתב הרמב\"ם מצות חכמים היא על בני ישראל לקנאות לנשותיהן שנא' וקינא את אשתו \u0010y30\u0011וכל המקנא לאשתו נכנסה בו רוח טהרה ולא יקנא לה מתוך שחוק ולא מתוך שיחה ולא מתוך קלות ראש ולא מתוך מריבה ולא להטיל עליה אימה ואם עבר וקינא לה מתוך אחד מאלו הדברים הרי היא קנוי ואין ראויה לקפוץ ולקנאה בפני עדים תחלה אלא בינו ובינה בנחת ובדרך טהרה ואזהרה כדי להדריכה בדרך ישרה ולהסירה ממכשול וכל שאינו מקפיד על אשתו ובניו ומזהירן ופוקד דרכיהן תמיד עד שידע שהם שלימים מכל חטא נקרא חוטא שנאמר ופקדת נוך ולא תחטא:\nנשלם ספר אבן העזר. בעזרת האל העוזר",["המקנא לאשתו ונסתרה ואינו יודע אם נטמאה בזמן שב\"ה קיים משקה אותה מי המרים ונבדקת על ידן אם נמצאת טהורה מותרת אבל אסורה לעולם עד שתבדק וכו' דברים פשוטים הם:","ומ\"ש ובלבד שיהא הסתירה והקינוי כראוי כיצד הקינוי אומר לה בפני ב' אל תסתרי עם איש פלוני אפי' הוא אביה או אחיה או עכו\"ם או שחוף פי' שאינו מתקשה ואינו מוליד והוא שיהיה גדול אבל אם אמר לה אל תסתרי עם פלוני והוא קטן או עם בהמה לא הוי קינוי בפרק ארוסה (סוטה כד.) תנן ע\"י כל העריות מקנאין. חוץ מן הקטן וממי שאינו איש ופירש\"י ע\"י כל העריות מקנאין אם קינא לה מאביה או מאחיה ומאחד מכל העריות שבתורה ונסתרה הוי קינויו קינוי ונאסרה עליו ושותה ובגמ' (דף כו:) חוץ מן הקטן איש אמר רחמנא ולא קטן ושאינו איש למעוטי מאי אילימא למעוטי שחוף והאמר שמואל שחוף מקנאין על ידו ואלא למעוטי עכו\"ם והאמר רב המנונא עכו\"ם מקנאין על ידו אמר רב פפא למעוטי בהמה שאין זנות בבהמה:","ומקנא לה בין אם היא ארוסה או נשואה או זקוקה ליבם ר\"פ ארוסה (סוטה דף כג:) ושומרת יבם לא שותה ולא נוטלת כתובה שנאמר אשר תשטה אשה תחת אישה פרט לארוסה ושומרת יבם ובגמרא (דף כד:) מישתא הוא דלא שתיא הא קינוי מקני לה מה\"מ דבר אל בני ישראל ואמרת לרבות ארוסה ושומרת יבם לקינוי פירש\"י ארוסה שקינא לה ארוס ושומרת יבם שקינא לה יבם:","כתב הרמב\"ם קטנה שהשיאה אביה אם זינתה לרצונה אסורה לבעלה לפיכך מקנאין לה ולא להשקותה אלא להפסידה כתובתה אבל קטנה בת מיאון אין מקנאין לה וכו' בפ\"ב מה' סוטה:","\u0003והראב\"ד השיג עליו וכתב והלא אמרי' פתוי קטנה אונס הוא ועוד התראה לקטנה אינו התראה וכו'\u0004 כבר כתב ה\"ה בזה פ\"ג מה' א\"ב ומהרי\"ק בשורש קס\"ח:","וכיצד היא הסתירה שנסתרה בפני עדים ושהתה כדי טומאה שהוא שיעור כדי לצלות ביצה ולגמעה במשנה בריש סוטה (דף ב) כיצד הוא מקנא לה אמר לה בפני שנים אל תדברי עם איש פלוני וכו' נכנסה עמו לבית הסתר ושהתה עמו כדי טומאה אסורה לביתה ותנן תו התם (דף לא.) בפרק מי שקנא לאשתו ונסתרה אפי' שמע מן העוף הפורח באויר יוציא יתן כתובה דברי ר\"א ר' יהושע אומר עד שישאו ויתנו בה מוזרות בלבנה. ופירש רש\"י מי שקינא לה ונסתרה אם מאחר שקינא לה נסתרה אפי' שמע מהעוף הפורח שנסתרה יוציא ויתן כתובה ר\"א לטעמיה דאמר בפ\"ק סתירה לא בעיא עדות ואפי' עבד ואפי' שפחה נאמנים דהיינו נמי כעוף הפורח דאיתקש לטומאה דכולהו מהימני הלכך נאסרה עליו ואם אינו רוצה להשקותה יוציא ויתן כתובה רבי יהושע אומר עד שישאו ויתנו בה מוזרות בלבנה כלומר משום סתירה שאין בה ב' עדים אינה נאסרת עליו רבי יהושע לטעמיה דאמר משקה ע\"פ שנים מיהו כשישאו ויתנו בה מוזרות בלבנה בפריצות מכוער הדבר ותצא דהא אפי' מיא תו לא בדקי לה תניא בפ\"ק (ו:) וטהורה היא ולא שישאו ויתנו בה מוזרות בלבנה וידוע דהלכה כר' יהושע דלא סגי ליה בשמע מן העוף הפורח ולפיכך כתב רבינו שנסתרה בעדים הא דישאו ויתנו בה מוזרות בלבנה כתבו רבינו לקמן שמע העם מרננים אחר הסתירה והקינוי עד שהנשים נותנות ונושאות בה וכו' וכך פסק הרמב\"ם ז\"ל בפ\"ב וז\"ל אם שמע העם מרננים אחריה אחר הקינוי וסתירה עד ששמע מהנשים הטוות לאור הלבנה נושאות ונותנות בה שזינתה עם האיש שקינא לה עליו ה\"ז אסורה לקיימה ויוציא ויתן כתובה:","ומ\"ש שכדי טומאה הוא שיעור כדי לצלות ביצה ולגמעה בריש סוטה (דף ד.) איפליגו תנאי בשיעור טומאה ומסיק תלמודא דר\"ע אמר כדי לצלות ביצה וכל חד מהנך תנאי דאיפליגו עליה הוי יחידי לגביה וידוע דהלכה כר\"ע מחבירו וכ\"פ הרמב\"ם בפ\"א:","קינא לה משנים שאמר לה אל תסתרי עם פלוני ופלוני ונסתרה עם שניהם כאחד ושהתה כדי טומאה אפי' הם שני אחים או אביה ואחיה אסורה עד שתשתה כן כתב הרמב\"ם ז\"ל בפ\"א: \u0005ב\"ה והוא ירושלמי בריש סוטה ופסק כמ\"ד הכי וצריך להעביר הקולמוס על מדתנן בפ\"ק דכריתות עד ושותה שנית:\u0006 והוא מדתנן בפ\"ק דכריתות (דף ט) המקנא לאשתו ע\"י אנשים הרבה ובגמרא מנ\"ל דכתיב זאת תורת הקנאות תורה אחת לקנויין הרבה ובפ\"ב דסוטה (דף יח:) ת\"ר זאת תורת הקנאות מלמד שהאשה שותה ושונה וכו' עד ב' אנשים וב' בועלים ופירש\"י וכו' והקשו בתוס' וא\"ת הא דרשינן ליה בפ\"ב דכריתות שאדם מביא קרבן א' אפילו קינא לאשתו ע\"י אנשים הרבה וכו' עד ושותה שנית:","אמר לה בפני שנים אל תדברי עם פלוני אין זה קינוי ואפי' נסתרה עמו ושהתה עמו כדי טומאה מותרת או אמר לה אל תסתרי עם פלוני ודברה עמו בפני עדים מותרת שאין זו סתירה בריש סוטה (דף ב.) תנן כיצד מקנא לה אמר לה בפני ב' אל תדברי עם איש פלוני ודברה עמו עדיין הוא מותרת לביתה ומסיק בגמרא דה\"ק אל תדברי ודברה אל תדברי ונסתרה ולא כלום אל תסתרי ודברה עמו עדיין מותרת לביתה. וכן אם נסתרה בפני עדים ושהתה כדי טומאה ולא קינא לה בפני עדים מותרת שאין אוסרים על הייחוד אפי' נסתרו יחד על דעת ערוה אלא א\"כ קינא לה תחלה בפני ב' הכי משמע בריש סוטה ובפרק ארוסה (סוטה כה.) דאין סתירה אוסרת אא\"כ קודם קינוי וז\"ל הרא\"ש בפ\"ב דיבמות נראה דבסתירה לחודה בלא קינוי אע\"ג דאדעתא דניאוף אסתתרת כי הנהו עובדי דשילהי נדרים (צא:) שריא לבעלה אפילו כי ליכא טעמא כי התם למשרי דהא קי\"ל אין אוסרין על הייחוד וסתירה נמי לא אשכחן בה דאיתסרא בה בלא קינוי אפי' בעדים והא דאיצטריך למימר התם טעמא דאיתתא שריא אי איתא דעבד אסורא אירכוסי הוה מירכס ואם איתא דעבד איסורא ניחא ליה דליכול ולימות משום דהתם מיירי באומרת טמאה אני כי מתני' דהתם דעלה קאי או בשותקת ומודה ומ\"ה איצטריך למימר טעמא דאיתתא שריא אבל לאומרת טהורה אני שריא אפי' בלא הני טעמי דהתם:","\u0003ומ\"ש ומ\"מ לא תתייחד אשה עם אנשים כדפרישית לעיל בסי' כ\"ב:\u0004 ","כתב בספר המצות לא יאמר אדם לאשתו בזמן הזה אל תסתרי עם פלוני דשמא הלכה כר\"י דאמר קינא לה בינה לבין עצמו שלא בפני עדים הוי קינוי וכו' הא דר\"י בר יהודה בריש סוטה (דף ב:) וקאמר התם בגמרא א\"ר חנינא מסורא לא לימא איניש לאינשי ביתיה בזמן הזה אל תסתרי בהדי פלוני דדילמא קי\"ל כר\"י בר יהודה דאמר קינוי ע\"פ עצמו ומסתתרת וליכא האידנא מי סוטה למיבדקה וקא אסר לה עילויה איסור עולם ופירש\"י לא לימא איניש. אפי' בינו לבינה: וז\"ל הרשב\"א בתשובה סי' תקנ\"ז קרוב אני בעיני לומר דמי שאמר לאשתו לא תסתרי עם איש פלוני בלא עדים ונסתרה בפניו בלא עדים אף ע\"פ שמדין תורה אינה מתגרשת מ\"מ מצוה לגרשה :","בא עד אחד והעיד לו שנסתרה עם אותו שקינא לה עליו ושהתה כדי טומאה אם הוא נאמן בעיניו ודעתו סומכת עליו יוציא ויתן כתובה ואם לאו מותרת לו כן כתב הרמב\"ם בפ\"א וז\"ל בא עד אחד והעיד לו שנסתרה עמו אחר קינוי ושהתה עמו כדי טומאה אם הוא נאמן לו ודעתו סומכת עליו יוציא ויתן כתובה ואם לאו הרי אשתו מותרת לו וטעמו מדגרסינן בקידושין פרק האומר (דף סו) ההוא סמיא דהוה מסדר מתנייתא קמיה דמר שמואל שדר שמואל שליחא אבתריה א\"ל שליח אשתו זינתה אתא לקמיה דמר שמואל א\"ל אי מהימן לך זיל אפקה ואי לא לא תפיק ופריש רבא דה\"ק אי מהימן כבי תרי זיל אפקה ואי לא לא תפקה ומשמע דאשתו זינתה לאו דוקא דה\"ה לאומר לו אשתו נסתרה עם פלוני אחר שקינא לה עמו שהרי אילו היו שני עדים בסתירה זו היתה אסורה לבעלה כאילו ראה שזינתה ממש ואם הוא בעצמו ראה שנסתרה עמו ושהתה כדי טומאה ה\"ז אסורה עליו ויוציא ויתן כתובה שאינו יכול להשקותה ע\"פ עצמו כ\"כ הרמב\"ם ז\"ל בפ\"א ופשוט הוא:","לא קינא לה ובא עד א' וא\"ל זינתה והוא שותק אם הוא נאמן בעיניו ודעתו סומכת עליו כשנים יוציא ויתן כתובה ואם לאו מותרת לו היינו עובדא דההוא סמיא שכתבתי בסמוך ועיין במה שכתבתי בסימן קט\"ו:","\u0003כתב א\"א הרא\"ש ז\"ל בתשובה על אחד שהוציא קול על אשתו שזינתה וכו'\u0004 בכלל ל\"ב סי' י\"ב והביא ראיה לדבר מדאמר בפ\"ב דכתובות (כב.) אם נתנה אמתלא לדבריה נאמנת הרשב\"א בתשו' סי' אלף ורל\"ז כתב דינים דשייכי לסי' זה. ועיין בדברי רבינו בסימן י\"א:","שמע העם מרננים אחר הקינוי והסתירה עד שהנשים נושאות ונותנות בה שזינתה מהאיש שקינא לה עליו אסורה לו ויוציאנה ויתן כתובה כבר נתבאר בסימן זה:","\u0003בעל שמחל על קינויו קודם סתירה קינויו מחול וכו'\u0004 מסקנא דגמרא פרק ארוסה (סוטה כה.) ומ\"ש גירשה ה\"ז כאילו מחל לה ואם החזירה צריך לקנאות לה פעם אחרת כ\"כ הרמב\"ם ז\"ל בפ\"א והוא ירושל' כתבוהו התוספות פ' היה מביא (סוטה יח:) ואלו שב\"ד מקנאין להן מי שנתחרש בעלה או נשתטה או היה במדינה אחרת או שהיה חבוש בבית האסורים ולא להשקותה אלא להפסידה כתובתה משנה בפ' ארוסה:","\u0003ומ\"ש כיצד שמעו שהעם מרננים אחריה קוראין לה וכו'\u0004 הם דברי הרמב\"ם ז\"ל בפ\"א מהל' סוטה ומבואר שהם פירוש למשנה הנזכר:","בא ע\"א והעיד שנטמאה מאותו שקינא לה אינה שותה ותצא בלא כתובה משנה בפ' מי שקינא לה (דף לא.) אמר עד אחד אני ראיתיה שנטמאת לא היתה שותה ולא עוד אלא אפי' עבד אפי' שפחה הרי אלו נאמנים אף לפוסלה מכתובתה ופירש\"י לא היתה שותה. דעד א' נאמן להפסיד שרגלים לדבר ומקראי ילפינן לה לקמן במתני' עכ\"ל:","ומ\"ש רבינו מאותו שקינא לה כ\"כ הרמב\"ם בפ\"א וכ\"נ מדברי רש\"י שם וטעמא דמסתבר הוא דלא היה לנו להאמין עד אחד להפסידה כתובתה אם לא שיהיה רגלים לדבר היינו שקינא לה תחלה עם האיש שמעיד עד זה שזינתה עמו ועוד דמקרא דמייתי לה במתני' משמע דבמעיד עד זה שנטמאה מאותו שקינא לה הוא:","ומ\"ש אפי' עד הטומאה הוא עד א' מעידי הסתירה כ\"כ הרמב\"ם בפ\"ח ומייתי לה מדכתיב ועד אין בה והרי עד ומ\"ש ואפילו עבד או אשה או שפחה או קרוב כשר לעדות זו משנה כתבתי בסמוך אמר עד אחד אני ראיתיה שנטמאת לא היתה שותה ולא עוד אלא אפילו עבד אפילו שפחה הרי אלו נאמנים אף לפוסלה מכתובתה:","ומ\"ש ואפי' נשים ששונאות זו את זו מעידות זו לזו לומר שנטמאת ונאמנות עליה לאוסרה על בעלה וכו' שם במשנה חמותה ובת חמותה וצרתה ויבמתה ובת בעלה הרי אלו נאמנות לא לפוסלה מכתובתה אמרו אלא שלא תשתה ופירש\"י הרי אלו נאמנות לה לעדות זו שהתורה האמינה כל עדות שיש בה ומיהו לא לפוסלה מכתובתה הואיל ושונאות אותה אלא שלא תשתה:","בא עד אחד ואמר שנטמאת ואח\"כ בא עד אחד ואמר שלא נטמאת אין שומעין לאחרון שעד אחד בטומאת סוטה כשנים ואין דברי האחרון דוחין דברי הראשון שהוא כשנים באו שנים כאחד זה אומר נטמאת וזה אומר לא נטמאת או שבא אחד ואמר נטמאת ואח\"כ באו שנים ואמרו לא נטמאת הרי זו שותה כך הם דברי הרמב\"ם ז\"ל בפ\"ח והוא מדתנן בפרק מי שקינא (שם:) עד אומר נטמאת ועד אומר לא נטמאת אשה אומרת נטמאת ואשה אומרת לא נטמאת היתה שותה עד אחד אומר נטמאת וב' אומרים לא נטמאת היתה שותה ב' אומרים נטמאת ואחד אומר לא נטמאת לא היתה שותה ופירש\"י עד אומר נטמאת ועד אומר לא נטמאת. אוקי חד בהדי חד והרי היא בספיקא ושותה: וב' אומרים לא נטמאת. כלומר לא נטמאת בפניך שכשבאת ומצאת שנסתרו יחד גם אנו היינו עמך ובפנינו לא נטמאת הרי נסתלק העד הזה ובטלו דבריו מפני השנים והרי היא בספיקא אם נטמאה קודם שבא אלו ומצאום והיתה שותה: ובגמרא (שם) עד אומר נטמאת טעמא דקא מכחיש ליה הא לא קא מכחיש ליה עד אחד מהימן מה\"מ דתנו רבנן ועד אין בה וכו' כיון דמדאורייתא עד אחד מהימן אידך היכי מצי מכחיש ליה והאמר עולא כ\"מ שהאמינה תורה עד אחד הרי כאן שנים ואין דבריו של אחד במקום שנים אלא אמר עולא לא היתה שותה וכן א\"ר יצחק לא היתה שותה ורבי חייא אומר שותה לר' חייא קשיא לעולא ל\"ק כאן בבת אחת כאן בזה אחר זה תנן עד אומר נטמאת וב' אומרים לא נטמאת היתה שותה הא חד וחד לא הוה שותה תיובתא דר\"ח אמר לך ר\"ח ולטעמיך אימא סיפא ב' אומרים נטמאת וא' אומר לא נטמאת לא היתה שותה הא חד וחד היתה שותה אלא כולה בפסולי עדות ור' נחמיה היא דתניא ר' נחמיה אומר כ\"מ שהאמינה תורה עד אחד הלך אחר רוב דעות ועשו ב' נשים באשה א' כב' אנשים באיש אחד ואיכא דאמרי כל היכא דאתא ע\"א כשר מעיקרא אפילו מאה נשים כע\"א דמיין הב\"ע כיון דאתאי אשה מעיקרא ותרצה לדרבי נחמיה הכי רבי נחמיה אומר כ\"מ שהאמינה תורה ע\"א הלך אחר רוב דעות ועשו ב' נשים באשה אחת כב' אנשים באיש א' אבל ב' נשים באיש א' כי פלגא ופלגא דמו. ופירש\"י הרי כאן ב'. הרי הוא כב': קשיא דעולא. דכיון שהאמינה תורה הרי העמידתו במקום ב': כאן בבת אחת. מתני' כשהעידו שניהם בתוך כדי דיבור דבטלו דבריו מיד דלא נתקיימו עדותן בב\"ד והיכא האמינתו תורה כשנים כגון אם העיד עדותו ויצא דתו לא מצי חד לאכחושיה: כ\"מ שהאמינה תורה. הוציאתו לעדות זה מכלל כל עדיות שבתורה לפיכך פסולים וכשרים שוים בה והלך אחר רוב דעות המעידין בדבר: ואיכא דאמרי כל היכא דאתא עד כשר מעיקרא. ואמר נטמאת ונתקבלה עדותו ואח\"כ באו ק' נשים כע\"א דמיין וה\"ל קמא שנים ואין דבריו של א' במקום ב' ואינה שותה: והב\"ע. דקתני עד א' אומר נטמאת וב' אומר לא נטמאת היתה שותה ואוקימנא בפסולי עדות ובין בבת א' בין בזה אחר זה וכר' נחמיה וע\"כ דבזה אחר זה איצטריך עיקר לאשמועינן דאי בב\"א מאי הלך אחר רוב דעות איכא בחד וחד נמי היתה שותה אלא בהכי עסקינן דההוא דאתא מעיקרא ואמר נטמאת אשה הוי הלכך אפי' בזה אחר זה אתו תרתי ומבטיל להם: ותרצה לר' נחמיה הכי וכו'. דהא דאמרן לעיל ועשו ב' נשים באשה אחת וכו' לאו סיפיה דמילתיה דר' נחמיה הוא אלא פי' דמילתיה הוא דאנן מפרשינן לה הכי: כי פלגא ופלגא. כלומר כי חד וחד ואי בב\"א אתי אוקי תרי לבהדי חד ואוקמיה אספיקא ואי בזה אחר זה וההוא דהאמינה תורה קדים ואתא ברישא ה\"ל כב' והנך כחד ואין דבריהם במקומו והיכא דשתים אומרות נטמאת ועד אומר לא נטמאת היתה שותה דכי חד וחד נינהו ומתני' דקתני לא היתה שותה כגון דההוא חד הוה פסול עכ\"ל ומשמע דהלכה כרבי חייא דמוקי למתני' כדקתני היתה שותה ולא כעולא דמשבש לה ומתני לא היתה שותה ולפיכך כתבו הרמב\"ם ורבינו בא עד אחד ואמר שנטמאת ובא עד אחד ואמר לא נטמאת אין שומעין לאחרון כו' באו שנים כא' זה אומר נטמאת וזה אומר לא נטמאת וכו' ה\"ז שותה דהיינו מה שחלק ר' חייא בין בבת א' לזה אחר זה ומ\"ש או שבא אחד ואמר נטמאת ואח\"כ באו ב' ואמרו לא נטמאת ה\"ז שותה פשוט הוא דאע\"ג דכ\"מ שהאמינה תורה עד א' הרי כאן ב' מ\"מ כי אתו תרי ומכחשי ליה ה\"ל כתרי ותרי והדרא לספיקה והיתה שותה: ומ\"ש בא עד א' ונשים רבות כאחד העד הכשר אומר נטמאת והנשים אומרות לא נטמאת ה\"ז שותה וכו' היינו כלישנא בתרא דאמרי כל היכא דאתא עד אחד כשר מעיקרא אפילו מאה נשים כעד אחד דמיין והכא במאי עסקינן וכו' אבל שני נשים באיש אחד כי פלגא ופלגא דמי:","ומ\"ש היו כולם פסולים הולכים אחר רוב דעות היינו דרבי נחמיה דאמר כל מקום שהאמינה תורה עד אחד הלך אחר רוב דעות ועשו ב' נשים באשה אחת כשני אנשים באיש אחד:","ומ\"ש רבי' בשם הרמב\"ם כיצד שתים אומרות נטמאת וג' אומרות לא נטמאת וכולי דברים פשוטים הם ויש לתמוה למה הוצרך לתלות בשם הרמב\"ם ואפשר לומר דמשום דהוה אפשר למטעי בדר' נחמיה ולומר דלא קאמר אלא שעשו שני אנשים באשה אחת כשני אנשים באיש אחד אבל ג' נשים בשתי נשים כי פלגא ופלגא דמי לכך הוצרך לכתוב בשם הרמב\"ם דליתא מצאתי כתוב בקצת ספרי רבינו אצל מ\"ש לפיכך שותה שנתבטלו דברי האחד הגיהו וכתבו חמש נשים ששונאות זו את זו מעידות זו את זו ונ\"ל דהגה\"ה בטעות היא שהרי דין חמש נשים הללו כבר נתבאר למעלה ולמה לו לחזור ולשנותן ועוד שאין כאן מקומן ואין להם קשר עם מה שלמעלה ולא עם מה שלמטה דוק ותשכח:","כל שאינה שותה מפני עדי טומאה אסורה לעולם ותצא בלא כתובה כן כתב הרמב\"ם בפ\"א ודבר פשוט הוא:","\u0003כתב בה\"ג שאין מוציאין ע\"י עדי טומאה עד שיראו כמכחול בשפופרת ור\"ח כתב שא\"צ וכו'\u0004 ז\"ל הרא\"ש בפ\"ב דיבמות כתב בה\"ג דאין מוציאין מהבעל עד שיראו העדים כמכחול בשפופרת והא ליתא דהא לענין חיוב מיתה סגי אם ראוהו העדים כדרך המנאפים כדאיתא בפ' הפועלים (בבא מציעא דף צא) ובספ\"ק דמכות (דף ז.) במנאפים עד שיראו כדרך המנאפים ובכלאים עד שיכניס כמכחול בשפופרת וכיון דבדיני נפשות כתיב והצילו העדה סגי בהכי כ\"ש לאוסרה על בעלה וכ\"פ ר\"ח מראיה זו עכ\"ל וכ\"פ הרי\"ף ז\"ל ג\"כ על איזה דברים מוציאים אשה מבעלה נתבאר בסימן י\"א ואימתי כופין אותו להוציא ואימתי אין כופין עיין בר\"י נכ\"ג ח\"ב:","אשה שקינא לה בעלה ונסתרה ומת אינה נוטלת כתובה משנה בפ' הארוסה (דף כד.) מתו בעליהן עד שלא שתו ב\"ש אומר נוטלות כתובה ולא שותות וב\"ה אומרי' שותות או לא נוטלות כתובה ופירש\"י מתו בעליהן. של כל סוטות הנסתרות וראויות לשתות ולא הספיקה לשתות וכו' דבעינן והביא האיש את אשתו וגו' ובגמרא במאי קמיפלגי ב\"ש סברי שטר העומד לגבות כגבוי דמי וב\"ה סברי לאו כגבוי דמי ופירש\"י לאו כגבוי דמי. וה\"ל היא תובעת מספק דדילמא זנאי הלכך אינהו ודאי ואיהי ספק ואין ספק מוציא מידי ודאי ועליה להביא ראיה שלא זינתה:","כל שאסורה לבעל משום קינוי אסורה לבועל לפיכך האידנא שאסורה לעולם אחר קינוי וסתירה אסורה ג\"כ לבועל ואם ניסת תצא משנה בפרק כשם שהמים וכו' כשם שאסורה לבעל כך אסורה לבועל ומ\"ש ואם ניסת תצא כן משמע בפ\"ב דיבמות. וכתב הרמב\"ם ז\"ל בפ\"ב מה' סוטה אם עבר ונשאה מוציאין אותה מתחתיו בגט אפי' היו לה כמה בנים ממנו וכן משמע קצת בפרק הנזכר ואם אין עדי טומאה אלא עדי כיעור פירשתי למעלה בסי' י\"א ושם כתבתי גם אני וביארתי כל הצורך:","\u0003כתב ר\"ת ישראלית שהמירה ונישאת לעכו\"ם ושוב חזרה בתשובה וכו'\u0004 שמותרת לגר שנתגייר עמה כ\"כ התוס' בריש כתובות (ג:) אהא דמקשה התם ולדרוש להו דאונס שרי וא\"ת והא אמרינן בפ' בן סורר ומורה על כל עבירות שבתורה יעבור ואל יהרג חוץ מעכו\"ם ג\"ע וש\"ד ותירץ ר\"ת דאין חייבין מיתה על בעילת עכו\"ם דרחמנא אפקריה לזרעיה דכתיב וזרמת סוסים זרמתם ומייתי ראיה דפריך בפרק בן סורר ומורה והא אסתר פרהסיא הואי ולא פריך והא אסתר ג\"ע הואי משמע דמשום עריות לא הוה מחוייבת ומתוך כך התיר ר\"ת לבת ישראל שהמירה ובא עליה עכו\"ם לקיימה לאותו עכו\"ם כשנתגייר דלא שייך למימר אחד לבועל בביאת עכו\"ם דהויא כביאת בהמה ואין נראה לריב\"ם דהא ע\"י ביאת עכו\"ם באסרה לבעלה כדאמרינן הכא דאיכא פרוצות ובפרק האשה שנתארמלה דברצון אסורה לבעלה אלמא לגבי בעלה ביאת עכו\"ם לא חשיבא כביאת בהמה וה\"ה לבועל והאריכו בדבר והרא\"ש כתב ע\"ז בפסקיו ונ\"ל לקיים פסק ר\"ת ולא מטעמיה אלא משום הא דאמרן ונטמאה ונטמאה אחד לבעל ואחד לבועל היינו היכא שלא היתה אסורה לבועל אלא ע\"י ביאה זו אבל בביאת עכו\"ם דבלאו הכי היתה אסורה לו לא קרינן ביה ונטמאה אחד לבועל ונהי דנאסרה לבעל מ\"מ לא ניתוסף בה איסור לבועל בביאתו כיון דבלאו הכי היתה אסורה לו וכן מוכח בסוטה פ' ארוסה (סוטה כו:) גבי מקנאין ע\"י עכו\"ם עכ\"ל ובא\"ח כתוב דאין לסמוך על ר\"ת שכל חכמי דורו נחלקו עליו :","\u0003כתב הרמב\"ם מצות חכמים על בני ישראל לקנאות לנשותיהם כו'\u0004 עד סוף הסימן הכל בסוף הל' סוטה:","ומ\"ש כל המקנא את אשתו נכנסה בו רוח טהרה מסקנא דגמרא בריש סוטה (דף ג'.) אין אדם מקנא לאשתו אא\"כ נכנסה בו רוח טהרה: כתב הריב\"ש בתשובה סימן ע\"ט על א\"א שטענה על איש אחד שהוא רודף אחריה והוא מכחישה שאין לאמינה כדי לייסרו ולהענישו אבל כדי להפרישו מאיסור יגזרו עליו נידוי לבל ידבר עמה מטוב עד רע וכן שלא ידורו בשכונה א' ואם הוא מוחזק בעיניהם לחשוד על העריות ראוי לגעור בו בנזיפה ולאיים עליו שאם לא יתנהג כשורה יבדילוהו מביניהם לרעה וידחוהו בב' ידים כמו שארז\"ל (קידושין פא) מלקין על לא טובה השמועה וכמו שכתב הרמב\"ם בפ' כ\"ד מהלכות סנהדרין יש לב\"ד בכ\"מ ובכל זמן להלקות אדם ששמועתו רעה וכולי וכיוצא בזה כתב מהרי\"ק בשורש קכ\"ט לענין הטוענת על איש שבא עליה בשעת עילופה והבטיח אותה שישאנה וכתב בשורש קפ\"ט אפי' היכא שעד אחד מעיד ובעל דבר מכחישו כתבתי כל זה בסימן צ\"ב. גרסינן בפרק הערל (יבמות ע:) עבד רבה תוספאה עובדא באשה שהלך בעלה למדינת הים ואישתהי עד י\"ב ירחי שתא ואכשרה וכתב מהרי\"ק בשורש ק\"ג שכן דעת הפוסקים שהולד כשר והאשה מותרת לבעלה והרא\"ש כתב בפרק עשרה יוחסין בשם ה\"ג דאפי' שהה טובא נמי כשר דאמרינן שמא בא בעלה בצינעא ושימש וההיא דפ' הערל דמשמע דבשהה יותר מי\"ב חדש הוי ממזר מיירי שהבעל והאשה מודים שלא בא וכתב רבינו סברות אלו בסימן ד': מצאתי כתוב ראובן בא לעירו בתחלת חדש כסליו אחר שעמד חוץ לביתו קרוב לשנה ונתעברה אשתו ובסוף אדר הפילה נפל כבן ז' באיבריו ובכה מעט וחיה קרוב לי\"ב שעות והיה קול בעיר שא\"א שבפחות מה' חדשים שלימים ישמיע קולו וחששו שמא היתה הרה לזנונים ובדקוהו אם יש לה שפע חלב ולא נמצא לה והשיב ה\"ר דוראן מה שהסכמתם שאין לחוש לה כיון שהבעל מחזיקה בכשרות יפה הסכמתם שאפי' בא\"ל עד אחד שזינתה אמרינן אי לא מהימן לך לא תפקה וכ\"ש בזו שלא נשמע עליה כלום אלא שחשש גדלות הנפל גרם לקול ולהראותכם כי אין כל חדש אכתוב לכם ענין יותר קשה מזה והתירוה לבעלה אם אינו חושש לה לזנות שראובן שהה חוץ מעירו זמן וחזר בו' בתמוז ואמר כי שמעון הוציא עליה קול שזינתה קודם בוא הבעל ובחדשי כסליו ישלמו לה ט' חדשים ותלד וילדה בטבת י' ימים אחר שקבע שמעון וקודם לידתה כ' ימים ראה הבעל בה סימנים שהיה רואה לשהיתה מגעת לחדש הט' ודרך האשה ללדת לסוף הט' ולפעמים שוהה עד הי' ועכשיו ילדה לו' חדשים לביאת הבעל ואפ\"ה השיב הרשב\"א שאם חושש הבעל לדברי שמעון אסורה וכדאמרי' בההוא סמיא אי מהימן לך כבי תרי ע\"כ. ואיני רואה ק\"ו בנדון זה אלא שאם הדבר ברור שנפל בן ה' חדשים אינו בוכה ה\"ז כאילו הפילה בעודו חוץ לביתו והרמב\"ם כתב בפט\"ו מהא\"ב שהולד ממזר אם הוא בן קיימא ואם הוא ממזר היה נראה שתאסר לבעלה ואינו נאמן להכשירה עליו והרי היא כאילו זינתה בעדים וכ\"נ ממאי דאמרינן בפרק עשרה יוחסין (קידושין עג:) גבי אסופי משום דליכא אלא מיעוט שהלכו בעליהן למדינת הים וכו' ולפי זה אם הדבר ברי שאין נפל של חמש חדשים נגמר באיבריו ובהשמעת קול אין מועיל חזקה דכשרות לבעלה שלא לאסרה עליו זהו לפי דעת הרמב\"ם שכתבתי אבל בה\"ג כתב בסוף הלכות גירושין אשה שהלך בעלה למדינת הים וילדה דלא חיישינן לממזרות דילמא אתא בעל בצינעא ושימש כי עובדא דאבוה דשמואל וזה נראה כסותר דעתו של הרמב\"ם אלא שאיפשר לומר שהגאון לא אמר כן אלא כשאין הבעל בפנינו אבל אם הבעל לפנינו הולד ממזר כדעת הרמב\"ם לפי זה חזרה הדין כנדון זה אם איפשר לנפל בן חמשה חדשים להשמיע קול ושיהיה נגמר באיבריו כבן ז' וזהו מה שאני אומר בזה ידוע שהיולדת לז' יולדת למקוטעין ויולדת לט' אינה יולדת (אלא) למקוטעין כדאיתא בהמפלת א\"כ הרי חדש חמישי לבן ז' כחדש שמיני לבן ט' ואין ספק שנפל בן ח' בוכה ויונק עד קרוב לל' יום דכל שלא שהה ל' יום הרי הוא נפל כדאיתא בנדה (מד:) ובפרק רבי אליעזר דמילה (קצה:) ור\"פ הערל (יבמות פ:) וכיון שבן ה' ליולדת לז' הוא כבן ח' ליולדת לט' א\"כ כשם שבן ח' יכול להתקיים ולבכות הכי נמי בן ה' יכול להתקיים ולבכות דאמרינן בן ז' היה ונגמר מהרה ואף ע\"פ שלענין שיהיה נגמר באיבריו ידוע שהנולדים לז' הם הדבר חלושי היצירה אבל כבר אמרתם בזה טעם נכון לפי שאביו ואמו רמי הקומה וא\"כ נכון הדבר להחזיקה בכשרה ומותרת לבעלה עכ\"ל:"],["\u0003המקנא לאשתו וכו'\u0004 אפי' הוא אביה או אחיה ואף על גב דלעיל בסימן כ\"ב כתב דמותר האב להתייחד עם בתו וכן הבן עם אמו דאהנו אנשי כנסת הגדולה דסמיוה לעיני דיצה\"ר דלא מיגרי בקרובות היינו מן הסתם אבל המקנא לאשתו דאל תסתרי עם איש פלוני דאין ספק דלפי שראה איזה פריצות עם אותו האיש לכך מקנא לה ממנו א\"כ אפי' הוא אביה או אחיה נמי הוי קינוי דאיתרע הכא חזקתייהו ומ\"ש או עכו\"ם נראה דאתא לאורויי דאע\"פ דבזינתה עם עכו\"ם אינה אסורה לו לאחר שנתגיירה כדלעיל סעיף ח' בשם ר\"ת אפ\"ה לבעלה אסורה אף בזינתה עם העכו\"ם ומ\"ש או שחוף נראה דלרבותא נקט שחוף דאעפ\"י שאינו מתקשה ואצ\"ל סריס שמתקשה אלא דאינו מוליד וכן נראה ממ\"ש התוספות בסוטה (דף כו):","\u0003כתב הרמב\"ם קטנה שהשיאה אביה וכו'\u0004 עד אלא להפסידה כתובתה לאו דוקא כתובה דהוא הדין לאוסרה בעיא קינוי והתראה ואיפשר דרבותא נקט דאפילו כתובתה הפסידה ומכ\"ש דאסורה על בעלה כיון דקינא לה והתרה בה ועברה ונסתרה:","\u0003ומ\"ש אבל קטנה בת מיאון כו'\u0004 פי' כיון שאין קידושין תופסין בה מדאורייתא אלא מדרבנן ויכולה למאן ולצאת מבעלה בלא גט השתא ודאי אפי' זינתה תחת בעלה לרצונה אינה נאסרת על בעלה דכיון דאינה אשת איש מן התורה ה\"ל כפנוי הבא על הפנויה שלא לשם אישות דלא עשאה זונה ושריא אפי' לכהן כדלעיל בסימן ששי ומה שצריך לומר שאין לה רצון היינו שאם היה לה דעת ורצונה רצון אעפ\"י דקידושיה מדרבנן היתה נאסרת על בעלה מדרבנן אבל השתא שאין לה רצון וחשובה כפנויה מה\"ת שריא אפי' לכהן אפי' מדרבנן ודו\"ק:","\u0003והראב\"ד השיג וכו'\u0004 פי' וכיון דאונס הוא אפי' השיאה אביה וזינתה לרצונה אינה נאסרת לבעלה ישראל ועוד אפילו את\"ל דאינו אנוס אין כאן קינוי כיון שאין בה דעת לקבל הקינוי וההתראה ולפיכך אם זינתה אעפ\"י שהשיאה אביה לא נאסרה אלא לבעלה כהן כדין אשת כהן שנאנסה אלא מיהו לא חשיב פתוי קטנה אונס אלא לענין זה שאינה נאסרת על בעלה ישראל אפילו השיאה אביה אבל אם לא השיאה אביה והיא בת מיאון לא חשיב אונס ולומר כיון שאין לה רצון א\"כ יתן הצער כמו לאנוסה אלא כולן שוות לענין זה דכיון דנתפתתה אין לה צער ועי' במ\"ש ה\"ה פ\"ג מה' א\"ב ובכ\"מ פ\"ב דסוטה:","\u0003קינא לה משנים וכו'\u0004 בגמרא פ\"ק שני דכריתות (דף ט) יליף לה מזאת תורת הקנאות תורה אחת לקינויין הרבה דחמשה מביאין קרבן אחד על עבירות הרבה וחד מינייהו המקנא לאשתו ע\"י אנשים הרבה וכ\"כ התוס' ספ\"ק דסוטה בדיבור האחרון:","\u0003ומ\"ש וכן אם נסתרה בפני עדים ושהתה כדי טומאה ולא קינא לה בפני עדים מותרת וכו'\u0004 כ\"כ הרא\"ש בפרק שני דיבמות והיינו דוקא באומרת טהורה אני אבל בשותקת היינו מודה ואסורה וכ\"ש באומרת טמאה אני ומביאו ב\"י:","\u0003כתב בספר המצות לא יאמר אדם לאשתו בזמן הזה וכו'\u0004 ברפ\"ק דסוטה א\"ר חנינא מסורא לא לימא איניש לאיתתיה בזמן הזה לא תסתרי בהדי פלוני דילמא קי\"ל כר' יוסי ב\"ר יהודה וכו' פי' דבזמן הבית דאיכא מי סוטה לא היתה אסורה עליו דלר\"י ב\"ר יהודה נמי כיון דקינוי ע\"פ עצמו הוא היתה שותה ג\"כ ע\"פ אותו קינוי ומותרת לבעלה לאחר השקאה ואע\"ג דלרבנן נמי דאינו קינוי אא\"כ ע\"פ עדים אם קינא לה בזמן הזה בעדים נמי אסורה עליו לעולם לא היה מזהיר שלא יקנא לה בזמן הזה בעדים דבהא ודאי אם יקנא לה בעלה ותעבור על הקינוי בדין היא אסורה עליו לעולם וכופין אותו להוציא ע\"פ עדים שיעידו שקינא לה ועברה אבל בקינוי על פי עצמו ותעבור על קינויו אפי' הבעל מודה בדבר ולא יגרשנה אין בידינו לכופו להוציא כיון דלרבנן אין קינויו קינוי ושמא הלכה כר\"י בר\"י דאסורה עליו לעולם ותהיה עמו באיסור כל ימיו ומכ\"ש אם יתחרט על הקינוי ויכחיש ויאמר שלא קינא לה כלל ויש להקשות כיון דתלמוד ערוך הוא דהכי אמר רחמנא אמאי כתבו רבינו בשם סה\"מ וי\"ל דבתלמודא איכא לפרש דר\"ח מסורא הוה מספקא ליה הילכתא כמאן שהרי אמר שמא הלכה כר\"י ב\"ר יהודה ולכך הזהיר על זה אבל למאי דקי\"ל כרבנן ולא מספקא לן השתא לית דחש להא דר\"ח מסורא אבל מספר המצות שפסק כך למדנו דמפרש דר\"ח מסורא נמי פוסק דבדיעבד הלכה כרבנן דאין קינוי אלא בפני שנים ואין כופין להוציא אלא דצריך לחוש לכתחלה לדר\"י ב\"ר יהודה דלא לימא לאתתיה וכו' דכל א' יחוש לעצמו לכתחלה שמא תהא אשתו עמו באיסור כל ימיו אליבא דר\"י בר יהודה ודו\"ק:","\u0003בא ע\"א והעיד לו שנסתרה וכו'\u0004 גם בכאן מיירי באמרה טהורה אני ואפ\"ה אם הוא נאמן בעיניו וכו' אסורה ואפי' לא היה שותק הבעל מתחלה דכיון דקינא לה רגלים לדבר שזינתה ובסמוך דכתב רבינו לא קינא לה וכו' דליכא רגלים לדבר כתב רבינו והוא שותק ואסורה עליו משום לזות שפתים מדרבנן ולכן אינה אסורה אלא בהוא שותק דאיכא לזות שפתים מדשתק הבעל ולא הכחישו אבל בקינא לה דאסורה מדאורייתא כיון דאיכא רגלים לדבר אפי' הכחישו הבעל אסורה עליו מדאורייתא ומ\"ש בספרי רבינו והיא שותקת ט\"ס הוא וצ\"ל והוא שותק ודלא כב\"י לעיל בסי' קט\"ו ולשם הארכתי בס\"ד ע\"ש ס\"ו:","\u0003שמע העם מרננים וכו'\u0004 משנה ר\"פ מי שקינא לאשתו פליגי בה רבי אליעזר ורבי יהושע והלכה כר\"י עד שישאו ויתנו בה מוזרות בלבנה וה\"פ אם קינא לה בעדים ונסתרה ועל הסתירה אין עדים אלא דהעם מרננים וכו' דהיינו דאין כאן אלא קול מפני שהנשים נושאות ונותנות בה שזינתה מהאיש שקינא לה אסורה לו וכו':","\u0003בא עד אחד והעיד שנטמאת וכו'\u0004 עד אפי' עד הטומאה הוא אחד מעדי הסתירה כ\"כ גם הרמב\"ם בפ\"א והקשה בכ\"מ דהיכי תיסק אדעתין שיגרע מפני שהוא אחד מעדי סתירה עכ\"ל ולפעד\"נ דסד\"א דכיון דראה הסתירה קאמר בדדמי דודאי נטמאה אע\"ג דלא חזי אלא פריצות דבכה\"ג חששו חכמים בעדים שראו לראובן שנטבע במים ואח\"כ העלו אחד מן המים שהוא מת דאין נאמנין לומר שהוא ראובן דחיישינן דקאמרי בדדמי מאחר שראו הטביעה כדלעיל בסי' י\"ז וה\"נ הכא סד\"א דאינו נאמן מה\"ט וקאמר דאפ\"ה נאמן שנטמאה ולא חיישינן דקאמר בדדמי:","\u0003בא עד אחד ואמר שנטמאה וכו'\u0004 עד אחר רוב דעות משנה וגמרא פרק מי שקינא והכל מפורש בב\"י אלא דהקשה הא דכתב בשם הרמב\"ם ב' אומרות נטמאת וכו' דתלמוד ערוך הוא דהולכים אחר רוב דיעות בין לחומרא שתשתה בין לקולא שלא תשתה ולמה מביא אותו בשם הרמב\"ם וי\"ל דתלמודא לא קא מיירי אלא באחד ושנים דהולכים אחר השנים בין לקולא בין לחומרא דאף ע\"פ דכולן פסולין אין דברים של אחד במקום שנים כלום ומדברי הרמב\"ם למדנו דגם בשנים וג' דאף ע\"ג דבעלמא אמרינן דתרי כק' אפ\"ה אמרו רבנן דכאן אזלינן בתר רוב דיעות ובג' אומרות לא נטמאת מחמרינן עליה שתשתה ולא חיישינן להני תרתי דאמרי נטמאת ובג' וארבעה אזלינן נמי בתר רוב דיעות ומקילינן עלה דלא תשתה כהני ארבעה דאמרי נטמאת ולא חיישינן להני ג' דאמרי לא נטמאת ושינה הרב דנקט הכא ג' וד' לאורויי דכי היכי דאין חילוק בין אחד ושנים לבין שנים ושלשה הכי נמי אין חילוק בין שנים וג' לג' וד' לעולם הולכין בתר רוב דיעות והדר אשמעינן במחצה על מחצה כיון דליכא רוב דיעות אזלינן לחומרא דתשתה:"]]]};
